import SwiftUI
@testable import Noum

struct NoumTests {

    /// Ensure that dynamic filler word variants like "errr" and "uhhhh" are
    /// detected by ``SpeechRecognizerViewModel``.
    @Test func dynamicVariantsAreCounted() async throws {
        let count1 = FillerWordDetector.count(in: "errr well uhhhh")
        #expect(count1 == 2)
    }

    /// Verify that a mix of base filler words and dynamic variants are all
    /// counted in the transcript.
    @Test func mixedFillerWordsCount() async throws {
        let count2 = FillerWordDetector.count(in: "like so you know errr uhhhh")
        #expect(count2 == 5)
    }

    /// Ensure newer filler words such as "hmm" and "erm" are detected.
    @Test func additionalFillerWords() async throws {
        let count3 = FillerWordDetector.count(in: "hmm erm mm")
        #expect(count3 == 3)
    }

}

@Suite("NotificationCopy Evening Nudge")
struct NotificationCopyEveningNudgeTests {
    @Test func eveningNudgeAvoidsPressureFramingAcrossStreakBands() {
        let lines = [0, 1, 3, 7, 14, 30].flatMap { streak in
            [
                NotificationCopy.streakWarning(streakDays: streak, freezesAvailable: 0),
                NotificationCopy.streakWarning(streakDays: streak, freezesAvailable: 1)
            ]
        }
        let bannedFragments = [
            "at risk",
            "break",
            "lose",
            "lost",
            "deadline",
            "buzzer",
            "only a rep",
            "hurry",
            "last chance"
        ]

        for line in lines {
            let combined = "\(line.title) \(line.body)".lowercased()
            for fragment in bannedFragments {
                #expect(!combined.contains(fragment))
            }
        }
    }
}

final class VideoRecordingLifecycleTests: XCTestCase {
    func testStartingNewRecordingClearsPreviousResultAndError() {
        let firstURL = URL(fileURLWithPath: "/tmp/first.mov")
        var lifecycle = VideoRecordingLifecycle()

        lifecycle.startRecording()
        lifecycle.complete(url: firstURL)
        lifecycle.fail("Old failure")
        lifecycle.startRecording()

        XCTAssertEqual(lifecycle.state, .recording)
        XCTAssertNil(lifecycle.recordingURL)
        XCTAssertNil(lifecycle.savedRecordingURL)
        XCTAssertNil(lifecycle.errorMessage)
    }

    func testFinalizingSuccessPublishesAvailableURL() {
        let url = URL(fileURLWithPath: "/tmp/final.mov")
        var lifecycle = VideoRecordingLifecycle()

        lifecycle.startRecording()
        lifecycle.beginFinalizing()
        lifecycle.complete(url: url)

        XCTAssertEqual(lifecycle.state, .available(url))
        XCTAssertEqual(lifecycle.recordingURL, url)
        XCTAssertNil(lifecycle.errorMessage)
    }

    func testFailedFinalizationClearsURLAndStoresError() {
        let url = URL(fileURLWithPath: "/tmp/final.mov")
        var lifecycle = VideoRecordingLifecycle()

        lifecycle.startRecording()
        lifecycle.complete(url: url)
        lifecycle.fail("Recording failed")

        XCTAssertEqual(lifecycle.state, .failed("Recording failed"))
        XCTAssertNil(lifecycle.recordingURL)
        XCTAssertEqual(lifecycle.errorMessage, "Recording failed")
    }

    func testCleanupResetsAllPublicLifecycleState() {
        let url = URL(fileURLWithPath: "/tmp/final.mov")
        var lifecycle = VideoRecordingLifecycle()

        lifecycle.startRecording()
        lifecycle.complete(url: url)
        lifecycle.markSaved(url: url)
        lifecycle.cleanup()

        XCTAssertEqual(lifecycle.state, .idle)
        XCTAssertNil(lifecycle.recordingURL)
        XCTAssertNil(lifecycle.savedRecordingURL)
        XCTAssertNil(lifecycle.errorMessage)
    }
}

// MARK: - Firebase bootstrap

@Suite("FirebaseBootstrap")
struct FirebaseBootstrapTests {
    @Test func optionalServicesStartOnlyWhenConfigExistsAndCoreConfigured() {
        #expect(!FirebaseBootstrap.shouldStartOptionalServices(configurationPresent: false, configured: false))
        #expect(!FirebaseBootstrap.shouldStartOptionalServices(configurationPresent: false, configured: true))
        #expect(!FirebaseBootstrap.shouldStartOptionalServices(configurationPresent: true, configured: false))
        #expect(FirebaseBootstrap.shouldStartOptionalServices(configurationPresent: true, configured: true))
    }

    @Test func reviewExperimentReceivesRemoteConfigActivationCompletionSignal() {
        let center = NotificationCenter()
        let expectation = XCTNSNotificationExpectation(
            name: FirebaseBootstrap.reviewRemoteConfigActivationDidComplete,
            object: nil,
            notificationCenter: center
        )

        FirebaseBootstrap.signalReviewRemoteConfigActivationCompleted(using: center)

        #expect(XCTWaiter.wait(for: [expectation], timeout: 0.1) == .completed)
    }

    @Test func appConfiguresFirebaseBeforeDelegateAndStateOwnersInitialize() throws {
        let repositoryRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let appSource = try String(
            contentsOf: repositoryRoot.appendingPathComponent("Noum/NoumApp.swift"),
            encoding: .utf8
        )

        let bootstrap = try #require(appSource.range(
            of: "private let firebaseReady: Void = FirebaseBootstrap.configure()"
        ))
        let delegateAdaptor = try #require(appSource.range(
            of: "@UIApplicationDelegateAdaptor(NoumAppDelegate.self)"
        ))
        let firstStateOwner = try #require(appSource.range(
            of: "@StateObject private var authManager = AuthManager.shared"
        ))

        #expect(bootstrap.lowerBound < delegateAdaptor.lowerBound)
        #expect(bootstrap.lowerBound < firstStateOwner.lowerBound)
    }

    @Test func firebaseDelegateProxyOptOutIsTrackedInBothAppBuildConfigurations() throws {
        let repositoryRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let project = try String(
            contentsOf: repositoryRoot.appendingPathComponent("Noum.xcodeproj/project.pbxproj"),
            encoding: .utf8
        )

        #expect(
            project.components(separatedBy: "INFOPLIST_KEY_FirebaseAppDelegateProxyEnabled = NO;").count - 1 == 2
        )
    }

    @Test func simulatorRunnerForwardsAppCheckTokenUsingSDKEnvironmentKey() throws {
        let repositoryRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let runner = try String(
            contentsOf: repositoryRoot.appendingPathComponent("scripts/run-noum-with-ai.sh"),
            encoding: .utf8
        )

        #expect(runner.contains("SIMCTL_CHILD_AppCheckDebugToken=${FIREBASE_APPCHECK_DEBUG_TOKEN}"))
        #expect(!runner.contains("SIMCTL_CHILD_FIREBASE_APPCHECK_DEBUG_TOKEN="))
    }

    @Test func authManagerIsTheOnlyAnonymousAuthenticationSourceOwner() throws {
        let repositoryRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let sourceDirectory = repositoryRoot.appendingPathComponent("Noum", isDirectory: true)
        let swiftSources = try FileManager.default
            .subpathsOfDirectory(atPath: sourceDirectory.path)
            .filter { $0.hasSuffix(".swift") }

        var owners: [String] = []
        for relativePath in swiftSources {
            let sourceURL = sourceDirectory.appendingPathComponent(relativePath)
            let source = try String(contentsOf: sourceURL, encoding: .utf8)
            if source.contains(".signInAnonymously") {
                owners.append(relativePath)
            }
        }
        #expect(owners.sorted() == ["AuthManager.swift"])

        let bootstrapSource = try String(
            contentsOf: sourceDirectory.appendingPathComponent("FirebaseBootstrap.swift"),
            encoding: .utf8
        )
        #expect(!bootstrapSource.contains("import FirebaseAuth"))
        #expect(bootstrapSource.contains("private static let runtimeServicesReady"))
        #expect(bootstrapSource.contains("FirebaseApp.configure()"))
        #expect(bootstrapSource.contains("AppCheck.setAppCheckProviderFactory"))
        #expect(bootstrapSource.contains("RemoteConfig.remoteConfig()"))
    }
}

// MARK: - Filler Detection Confidence Tests

struct FillerDetectionTests {

    @Test func cleanTranscriptHasNoHighConfidenceFillers() {
        let transcript = "I think the most important quality in a leader is the ability to listen. When you listen, you understand what your team needs, and you can make better decisions."
        let detections = FillerWordDetector.detections(in: transcript, prompt: "What is the most important quality in a leader?")
        let highConf = detections.filter { $0.confidence >= FillerDetection.suddenDeathThreshold }
        // Clean transcript should have zero high-confidence fillers
        #expect(highConf.count == 0, "Clean transcript should not trigger sudden death. Got: \(highConf.map { "'\($0.word)' c=\($0.confidence)" })")
    }

    @Test func fillerHeavyTranscriptDetectsManyFillers() {
        let transcript = "So um I think like the most important thing is uh you know when you're like trying to um lead a team you have to uh like be uh you know present and like um available."
        let detections = FillerWordDetector.detections(in: transcript, prompt: "What makes a good team leader?")
        let highConf = detections.filter { $0.confidence >= FillerDetection.suddenDeathThreshold }
        // Should detect many high-confidence fillers (um, uh, you know)
        #expect(highConf.count >= 6, "Filler-heavy transcript should have 6+ high-confidence fillers, got \(highConf.count)")
        // "um" and "uh" should be 0.95 confidence
        let pureDisf = detections.filter { ["um", "uh"].contains($0.word) }
        for d in pureDisf {
            #expect(d.confidence == 0.95, "Pure disfluency '\(d.word)' should be 0.95, got \(d.confidence)")
        }
    }

    @Test func promptEchoLikeGetsLowConfidence() {
        let transcript = "I like to think about what qualities I look for. Someone like a mentor who can guide the team."
        let detections = FillerWordDetector.detections(in: transcript, prompt: "What do you like about great leaders?")
        // "like" appears in the prompt, so occurrences should get prompt echo treatment
        let likeDetections = detections.filter { $0.word == "like" }
        let highConfLike = likeDetections.filter { $0.confidence >= FillerDetection.suddenDeathThreshold }
        #expect(highConfLike.count == 0, "Prompt-echo 'like' should NOT trigger sudden death. Got high-conf: \(highConfLike.map { "c=\($0.confidence) ctx=\($0.context)" })")
    }

    @Test func validLikeUsageNotFlagged() {
        let transcript = "It looks like the project is on track. I would like to discuss the timeline. The results feel like a strong indicator of progress."
        let detections = FillerWordDetector.detections(in: transcript, prompt: "How is the project going?")
        // "looks like", "would like", "feel like" — all valid, should return nil or very low
        let highConf = detections.filter { $0.confidence >= FillerDetection.suddenDeathThreshold }
        #expect(highConf.count == 0, "Valid 'like' usage should not be flagged. Got: \(highConf.map { "'\($0.word)' c=\($0.confidence)" })")
    }

    @Test func likeAfterPronounIsFiller() {
        let transcript = "So I was like thinking about it and she like went to the store and I like couldn't believe it."
        let detections = FillerWordDetector.detections(in: transcript, prompt: "Tell me about your weekend.")
        let likeFills = detections.filter { $0.word == "like" && $0.confidence >= 0.8 }
        // "I was like", "she like", "I like" — filler preceders
        #expect(likeFills.count >= 2, "Filler 'like' after pronouns should be detected. Got \(likeFills.count): \(likeFills.map { "c=\($0.confidence)" })")
    }

    @Test func youKnowDiscourseMarkerVsQuestion() {
        let transcript = "You know what I mean? But you know it's hard to explain. Do you know the feeling when you know everything clicks?"
        let detections = FillerWordDetector.detections(in: transcript, prompt: "Describe a breakthrough moment.")
        let youKnow = detections.filter { $0.word == "you know" }
        // "you know what" → NOT filler, "you know" standalone → filler, "do you know" → NOT filler
        // "you know everything" could go either way but "you know" before "everything" → probably filler
        let highConf = youKnow.filter { $0.confidence >= 0.8 }
        #expect(highConf.count >= 1 && highConf.count <= 3, "Should detect 1-3 discourse-marker 'you know'. Got \(highConf.count)")
    }

    @Test func soAsFillerVsAdverb() {
        let transcript = "So the thing is, it was so good that I couldn't stop. So then I realized it's not so bad after all."
        let detections = FillerWordDetector.detections(in: transcript, prompt: "What happened?")
        let soDetections = detections.filter { $0.word == "so" }
        // "So the thing" at start → filler (0.7)
        // "so good" → NOT filler (adverb)
        // "So then" → depends on position
        // "not so bad" → NOT filler
        let highConf = soDetections.filter { $0.confidence >= 0.7 }
        #expect(highConf.count >= 1, "Sentence-start 'so' should be detected as filler")
        // Verify "so good" and "not so bad" are NOT detected
        #expect(soDetections.count <= 3, "Should not over-detect 'so'. Got \(soDetections.count)")
    }

    @Test func pureDisfluenciesAlwaysHighConfidence() {
        let transcript = "The uh thing about erm leadership is that um you need to be uhh decisive and ah not hesitate."
        let detections = FillerWordDetector.detections(in: transcript, prompt: "What makes a good leader?")
        let pureDisf = detections.filter { ["uh", "erm", "um", "uhh", "ah"].contains($0.word) }
        #expect(pureDisf.count >= 4, "Should detect at least 4 pure disfluencies, got \(pureDisf.count)")
        for d in pureDisf {
            #expect(d.confidence == 0.95, "Pure disfluency '\(d.word)' should have 0.95 confidence, got \(d.confidence)")
        }
    }

    @Test func suddenDeathFairnessPromptEcho() {
        // Key test: should NOT end a sudden death run on prompt-echo words
        let transcript = "Like I mentioned earlier, what I like about this approach is that it like brings people together."
        let prompt = "What do you like about collaborative approaches?"
        let highCount = FillerWordDetector.highConfidenceCount(in: transcript, prompt: prompt)
        // "like" appears in prompt → most uses should be echo or valid
        // "it like brings" → ambiguous, may or may not flag
        #expect(highCount <= 1, "Sudden death should be lenient with prompt-echo 'like'. High-conf count: \(highCount)")
    }

    @Test func fillerAnalysisSeparatesRawAndAdjustedCounts() {
        let prompt = "What do you like about teams?"
        let transcript = "I like how teams work. It feels like a real support system. Um, the best teams are clear."
        let analysis = FillerWordDetector.analysis(in: transcript, prompt: prompt)
        #expect(analysis.rawCount >= analysis.adjustedCount)
        #expect(analysis.adjustedCount == 1, "Only the explicit disfluency should count. Got \(analysis.adjustedCount)")
    }
}

struct FillerAlertGateTests {
    @Test func alertOnlyPlaysForEnabledHighConfidenceIncrementAfterCooldown() {
        var gate = FillerAlertGate()
        gate.cooldown = 1.0
        let detection = FillerDetection(word: "um", range: NSRange(location: 0, length: 2), confidence: 0.95, context: .midPhrase)
        let start = Date()

        let first = gate.evaluate(previousAdjustedCount: 0, adjustedCount: 1, detections: [detection], isEnabled: true, now: start)
        #expect(first.shouldPlay)

        let cooled = gate.evaluate(previousAdjustedCount: 1, adjustedCount: 2, detections: [detection, detection], isEnabled: true, now: start.addingTimeInterval(0.2))
        #expect(!cooled.shouldPlay)

        let disabled = gate.evaluate(previousAdjustedCount: 2, adjustedCount: 3, detections: [detection, detection, detection], isEnabled: false, now: start.addingTimeInterval(2.0))
        #expect(!disabled.shouldPlay)
    }
}

struct DrillXPEngineTests {
    @Test func drillXPVariesWithOutcomeQuality() {
        let variation = DrillCatalog.allVariations.first { $0.id == "pace.beatTheBrake" }!
        let drill = DrillRecommendationV2(variation: variation, reason: "test", trendContext: nil, alternateFormat: nil)
        let strong = MiniDrillOutcome(
            drill: drill,
            drillType: .beatTheBrake,
            transcript: String(repeating: "clear ", count: 70),
            fillerCount: 0,
            duration: 45,
            wordCount: 70,
            succeeded: true,
            beatTheBrakeMetrics: BeatTheBrakeMetrics(
                averageWPM: 126,
                timeInZone: 38,
                totalDuration: 45,
                zonePercentage: 0.84,
                peakWPM: 137,
                lowestWPM: 112,
                adjustedFillers: 0,
                rushedBursts: 0
            )
        )
        let weak = MiniDrillOutcome(
            drill: drill,
            drillType: .beatTheBrake,
            transcript: "um rushed answer",
            fillerCount: 1,
            duration: 8,
            wordCount: 3,
            succeeded: false,
            beatTheBrakeMetrics: BeatTheBrakeMetrics(
                averageWPM: 180,
                timeInZone: 1,
                totalDuration: 8,
                zonePercentage: 0.12,
                peakWPM: 210,
                lowestWPM: 160,
                adjustedFillers: 1,
                rushedBursts: 4
            )
        )

        #expect(DrillXPEngine.breakdown(outcome: strong).total > DrillXPEngine.breakdown(outcome: weak).total)
        #expect(DrillCompletionCopy.title(for: strong) == "Cleaner Rhythm")
        #expect(DrillCompletionCopy.title(for: weak) == "Rushed Finish")
    }
}

// MARK: - Framework Drill Check Tests
//
// Per-detector boundary tests for the deterministic named-framework drills.
// Every fixture is hand-traced against the REAL
// `PracticeEvaluator.relevanceContentWords` stop set + the named
// `FrameworkDrillChecks` constants so a threshold change breaks a test rather
// than silently shifting a verdict. These cover the DETERMINISTIC seams only —
// never live model output (there is none here; the detectors are pure).

struct FrameworkDrillCheckTests {

    // Helper: build a framework-drill outcome the way `MiniDrillView` does,
    // routing the verdict through the same `FrameworkDrillVerdict.evaluate`
    // factory the recording flow uses.
    private func makeFrameworkOutcome(
        variationId: String,
        transcript: String,
        duration: TimeInterval,
        succeeded: Bool
    ) -> MiniDrillOutcome {
        let variation = DrillCatalog.allVariations.first { $0.id == variationId }!
        let drill = DrillRecommendationV2(variation: variation, reason: "test", trendContext: nil, alternateFormat: nil)
        let framework = MiniDrillType.framework(for: variationId)
        let verdict = FrameworkDrillVerdict.evaluate(framework, transcript: transcript, duration: duration)
        let wordCount = transcript.split { !$0.isLetter && !$0.isNumber }.count
        return MiniDrillOutcome(
            drill: drill,
            drillType: MiniDrillType.from(variationId: variationId),
            transcript: transcript,
            fillerCount: 0,
            duration: duration,
            wordCount: wordCount,
            succeeded: succeeded,
            framework: framework,
            frameworkVerdict: verdict
        )
    }

    // MARK: STAR turn-check

    @Test func starSetupShiftTakeawayDetectsTurn() {
        // 9 content words + the "but then" shift marker.
        let t = "I was leading a struggling project with no budget but then everything shifted completely after the deadline."
        #expect(FrameworkDrillChecks.starTurn(transcript: t) == .turnDetected)
    }

    @Test func starFlatDescriptionHasNoTurn() {
        // Plenty of content words, no shift marker -> flat, not punitive nil.
        let t = "I manage a marketing department handling several campaigns across multiple regions every quarter consistently."
        #expect(FrameworkDrillChecks.starTurn(transcript: t) == .flat)
    }

    @Test func starBelowFloorIsTentativeNotNegative() {
        // 2 content words (small, team) — below the 6-content-word floor.
        let t = "I led a small team."
        #expect(FrameworkDrillChecks.starTurn(transcript: t) == nil)
    }

    @Test func starBelowFloorNeverAssertsTurnEither() {
        // A shift marker but too thin -> still nil (no confident verdict at all
        // on thin data, positive OR negative).
        let t = "but then I quit."
        #expect(FrameworkDrillChecks.starTurn(transcript: t) == nil)
    }

    @Test func starUntilMarkerDetectsTurn() {
        let t = "Everything was going smoothly across the whole quarter until production completely collapsed overnight."
        #expect(FrameworkDrillChecks.starTurn(transcript: t) == .turnDetected)
    }

    // MARK: Claim / counter

    @Test func claimWithAcknowledgedCounterAndBridgeSatisfiesFramework() {
        let t = "Remote work boosts productivity dramatically. Some would say collaboration suffers, but the data shows teams actually deliver faster."
        #expect(FrameworkDrillChecks.claimCounter(transcript: t) == .counterAcknowledged)
    }

    @Test func oneSidedAssertionMissesCounter() {
        let t = "Remote work clearly boosts productivity, improves morale, and reduces commuting costs significantly."
        #expect(FrameworkDrillChecks.claimCounter(transcript: t) == .oneSided)
    }

    @Test func bareBridgeWithoutPriorConcessionIsOneSided() {
        // "but" is present but there is no acknowledgement marker before it, so
        // the acknowledge-THEN-bridge ordering is not satisfied. This is the
        // honesty-critical case: a bare continuation is not a counter move.
        let t = "I think remote work is great but I also enjoy office banter sometimes honestly."
        #expect(FrameworkDrillChecks.claimCounter(transcript: t) == .oneSided)
    }

    @Test func acknowledgementAfterBridgeDoesNotSatisfyOrdering() {
        // Concession appears AFTER the only bridge -> ordering fails -> oneSided.
        // "however" (bridge) precedes "although" (acknowledgement); there is no
        // bridge after the acknowledgement.
        let t = "Productivity rises however teams ship faster although remote collaboration occasionally stalls."
        #expect(FrameworkDrillChecks.claimCounter(transcript: t) == .oneSided)
    }

    @Test func claimCounterBelowFloorIsTentative() {
        let t = "Remote work rules."
        #expect(FrameworkDrillChecks.claimCounter(transcript: t) == nil)
    }

    // MARK: Claim / Evidence / Warrant

    @Test func cewFullChainCompletes() {
        let t = "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day."
        #expect(FrameworkDrillChecks.claimEvidenceWarrant(transcript: t) == .complete)
    }

    @Test func cewEvidenceOnlyNeedsWarrant() {
        let t = "We should raise the price because demand keeps climbing well past our current supply levels."
        #expect(FrameworkDrillChecks.claimEvidenceWarrant(transcript: t) == .missingWarrant)
    }

    @Test func cewImplicationOnlyNeedsEvidence() {
        let t = "We should raise the price, which means stronger margins and room to invest properly next year."
        #expect(FrameworkDrillChecks.claimEvidenceWarrant(transcript: t) == .missingEvidence)
    }

    @Test func cewAssertionOnlyIsConstructiveMiss() {
        let t = "Remote work clearly boosts output and keeps the whole team genuinely happier every single day."
        #expect(FrameworkDrillChecks.claimEvidenceWarrant(transcript: t) == .assertionOnly)
    }

    @Test func cewBelowFloorIsTentative() {
        #expect(FrameworkDrillChecks.claimEvidenceWarrant(transcript: "Yes, we should.") == nil)
    }

    // MARK: Monroe's Sequence

    @Test func monroeOrderedSequenceCompletes() {
        let t = "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high. Start by approving the pilot this week."
        #expect(FrameworkDrillChecks.monroeSequence(transcript: t) == .complete)
    }

    @Test func monroeMissingNeedIsFirstMiss() {
        let t = "Imagine the hiring team moving faster. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high. Start by approving the pilot this week."
        #expect(FrameworkDrillChecks.monroeSequence(transcript: t) == .missingNeed)
    }

    @Test func monroeMissingSolutionAfterNeed() {
        let t = "Imagine the hiring team losing top candidates. The problem is our interview loop takes three weeks. Picture candidates getting clear answers while interest is high. Start by approving the pilot this week."
        #expect(FrameworkDrillChecks.monroeSequence(transcript: t) == .missingSolution)
    }

    @Test func monroeMissingVisualizationAfterSolution() {
        let t = "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Start by approving the pilot this week."
        #expect(FrameworkDrillChecks.monroeSequence(transcript: t) == .missingVisualization)
    }

    @Test func monroeMissingActionAfterVisualization() {
        let t = "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high."
        #expect(FrameworkDrillChecks.monroeSequence(transcript: t) == .missingAction)
    }

    @Test func monroeOutOfOrderSolutionDoesNotSatisfySequence() {
        let t = "My proposal is a two day decision sprint. The problem is our interview loop takes three weeks. Picture candidates getting clear answers while interest is high. Start by approving the pilot this week."
        #expect(FrameworkDrillChecks.monroeSequence(transcript: t) == .missingSolution)
    }

    @Test func monroeBelowFloorIsTentative() {
        let t = "Problem is. Solution is. Imagine. Start."
        #expect(FrameworkDrillChecks.monroeSequence(transcript: t) == nil)
    }

    // MARK: Elevator pitch

    @Test func elevatorNamedHookInBoxLands() {
        let t = "Hi, I'm Jordan, and I build communication training software that helps people speak with confidence under pressure."
        #expect(FrameworkDrillChecks.elevatorPitch(transcript: t, duration: 18) == .landed)
    }

    @Test func elevatorOverTimeMissesBox() {
        let t = "Hi, I'm Jordan, and I build communication training software that helps people speak with confidence under pressure."
        #expect(FrameworkDrillChecks.elevatorPitch(transcript: t, duration: 42) == .overTime)
    }

    @Test func elevatorMissingNameFlagged() {
        let t = "This software helps people speak with confidence and clarity under real pressure every day."
        #expect(FrameworkDrillChecks.elevatorPitch(transcript: t, duration: 15) == .missingName)
    }

    @Test func elevatorNamedButHooklessFlagged() {
        // Named, in box, but 0 content words -> missing hook (not landed).
        let t = "Hi, I'm Sam."
        #expect(FrameworkDrillChecks.elevatorPitch(transcript: t, duration: 10) == .missingHook)
    }

    @Test func elevatorBelowFloorIsTentative() {
        // Both too short (<8s) AND too thin (<6 content words) -> no assertion.
        let t = "Hi there."
        #expect(FrameworkDrillChecks.elevatorPitch(transcript: t, duration: 4) == nil)
    }

    @Test func elevatorContentRichButShortStillGraded() {
        // <8s but content-rich (>=6 content words) clears the floor (OR, not
        // AND) and is graded honestly — here named + hook + in box -> landed.
        let t = "I'm Dana, founder of a climate analytics startup helping cities cut emissions fast."
        #expect(FrameworkDrillChecks.elevatorPitch(transcript: t, duration: 6) == .landed)
    }

    @Test func elevatorWordCountCeilingTreatsRambleAsOverTime() {
        // Named + in the time box by SECONDS, but word count blows the ceiling
        // (a fast talker who rambled) -> not a concise pitch -> overTime.
        let body = String(repeating: "and then I also want to mention ", count: 15) // ~105 words
        let t = "I'm Alex. " + body
        #expect(FrameworkDrillChecks.elevatorPitch(transcript: t, duration: 25) == .overTime)
    }

    // MARK: Reframe / bridge (curveball)

    @Test func reframeAcknowledgeThenBridgeToPrioritySatisfies() {
        // "that's fair" (ack) BEFORE "the real question is" (priority bridge).
        // 9 content words: fair, real, question, whether, customers, actually,
        // trust, product, enough.
        let t = "That's fair, but the real question is whether our customers actually trust the product enough."
        #expect(FrameworkDrillChecks.bridgeReframe(transcript: t) == .reframed)
    }

    @Test func reframeDirectAnswerWithoutBridgeIsFacedDirectly() {
        // No fair-acknowledgement marker at all -> answered head-on, which is
        // valid; the reframe move simply isn't present. Constructive, not nil.
        let t = "Our revenue grew thirty percent this quarter and the team shipped every major feature."
        #expect(FrameworkDrillChecks.bridgeReframe(transcript: t) == .facedDirectly)
    }

    @Test func reframeBridgeBeforeAcknowledgementFailsOrdering() {
        // Honesty-critical ordering case (mirrors claim/counter): the priority
        // bridge ("the real question") appears BEFORE the acknowledgement
        // ("that's fair"), and there is no bridge AFTER the ack -> facedDirectly,
        // never a confident "reframed". Exactly 6 content words (at the floor):
        // real, question, cost, fair, point, honestly.
        let t = "The real question is cost, that's fair to point out honestly."
        #expect(FrameworkDrillChecks.bridgeReframe(transcript: t) == .facedDirectly)
    }

    @Test func reframeAlternateMarkersStillSatisfy() {
        // Different ack ("i hear that") + different priority bridge ("what
        // matters more"). 8 content words: hear, concern, completely, matters,
        // keeping, existing, customers, happy.
        let t = "I hear that concern completely, but what matters more is keeping our existing customers happy."
        #expect(FrameworkDrillChecks.bridgeReframe(transcript: t) == .reframed)
    }

    @Test func reframeBelowFloorIsTentative() {
        // "that's" tokenizes to "that"(stop)+"s"(<4); only "fair" is a content
        // word -> 1 < 6 -> nil (no confident verdict on thin data, even with an
        // ack marker present).
        let t = "That's fair, but no."
        #expect(FrameworkDrillChecks.bridgeReframe(transcript: t) == nil)
    }

    // MARK: AREA (Answer · Reason · Example · Answer)

    @Test func areaAllFourBeatsComplete() {
        // Reason ("the reason is"), example ("for example", "last week"), and a
        // closing loop ("so that's why") all present above the floor.
        let t = "Remote work wins. The reason is teams ship faster. For example, last week we shipped in two days. So that's why remote wins."
        #expect(FrameworkDrillChecks.areaAnswer(transcript: t) == .complete)
    }

    @Test func areaMissingReasonFlagged() {
        // Example present ("for example") but NO reason marker -> missingReason
        // (checked first). 9 content words incl. the duplicate "charge".
        let t = "Our pricing is too high. For example, competitors charge half what we charge for similar features."
        #expect(FrameworkDrillChecks.areaAnswer(transcript: t) == .missingReason)
    }

    @Test func areaMissingExampleFlagged() {
        // Reason ("because") present, NO example marker -> missingExample. Note
        // "because" is a CONTENT-WORD stop word (it does not inflate the floor)
        // yet still matches as a reason discourse marker — the design seam.
        // Content words: discipline, beats, talent, consistent, effort,
        // compounds, time = 7 >= 6.
        let t = "Discipline beats talent because consistent effort compounds over time and habits outlast motivation eventually."
        #expect(FrameworkDrillChecks.areaAnswer(transcript: t) == .missingExample)
    }

    @Test func areaBuriedLeadFlagged() {
        // Above the floor (6 content words: answer, discipline, consistent,
        // practice, compounds, daily) but the FIRST sentence ("Um, so, well,
        // like, just") carries zero content words ("well"/"like"/"just" are stop
        // words, the rest < 4 chars) -> the answer is buried -> missingLead,
        // checked before reason/example/closing. The "..." splits the lead from
        // the body on the shared first-sentence rule.
        let t = "Um, so, well, like, just... the answer is discipline because consistent practice compounds daily."
        #expect(FrameworkDrillChecks.areaAnswer(transcript: t) == .missingLead)
    }

    @Test func areaNoClosingLoopFlagged() {
        // Reason ("because") + example ("for instance" / "last month") present,
        // but no closing-loop marker (deliberately avoids "that's why" / "which
        // is why" / "so the answer", which double as closings) -> noClosingLoop.
        let t = "Hiring slowly is smart because a bad hire is costly. For instance, last month one wrong hire stalled the whole roadmap."
        #expect(FrameworkDrillChecks.areaAnswer(transcript: t) == .noClosingLoop)
    }

    @Test func areaBelowFloorIsTentative() {
        // The floor gate runs BEFORE any beat detection: only "reasons" is a
        // content word ("because" is a stop word; "yes" < 4) -> 1 < 6 -> nil,
        // even though a reason marker is present.
        let t = "Yes, because reasons."
        #expect(FrameworkDrillChecks.areaAnswer(transcript: t) == nil)
    }

    // MARK: Verdict wrapper + factory

    @Test func evaluateReturnsNilForNonFrameworkDrill() {
        #expect(FrameworkDrillVerdict.evaluate(nil, transcript: "anything at all here", duration: 20) == nil)
    }

    @Test func evaluateRoutesEachFrameworkToItsDetector() {
        let star = FrameworkDrillVerdict.evaluate(
            .starTurn,
            transcript: "I was running a calm project until everything suddenly fell apart completely overnight.",
            duration: 30
        )
        #expect(star == .star(.turnDetected))

        let claim = FrameworkDrillVerdict.evaluate(
            .claimCounter,
            transcript: "Remote work boosts output. Some would say it hurts culture, but the numbers prove otherwise here.",
            duration: 30
        )
        #expect(claim == .claimCounter(.counterAcknowledged))

        let cew = FrameworkDrillVerdict.evaluate(
            .claimEvidenceWarrant,
            transcript: "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day.",
            duration: 30
        )
        #expect(cew == .claimEvidenceWarrant(.complete))

        let monroe = FrameworkDrillVerdict.evaluate(
            .monroeSequence,
            transcript: "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high. Start by approving the pilot this week.",
            duration: 45
        )
        #expect(monroe == .monroeSequence(.complete))

        let pitch = FrameworkDrillVerdict.evaluate(
            .elevatorPitch,
            transcript: "Hi, I'm Jordan and I build communication training tools for nervous speakers under pressure.",
            duration: 16
        )
        #expect(pitch == .elevatorPitch(.landed))

        let reframe = FrameworkDrillVerdict.evaluate(
            .bridgeReframe,
            transcript: "That's fair, but the real question is whether our customers actually trust the product enough.",
            duration: 30
        )
        #expect(reframe == .bridgeReframe(.reframed))

        let area = FrameworkDrillVerdict.evaluate(
            .areaAnswer,
            transcript: "Remote work wins. The reason is teams ship faster. For example, last week we shipped in two days. So that's why remote wins.",
            duration: 30
        )
        #expect(area == .areaAnswer(.complete))
    }
}

