// MARK: - Framework Drill Score-Safety + Copy Tests

struct FrameworkDrillCopyAndScoreTests {

    private func outcome(
        variationId: String,
        transcript: String,
        duration: TimeInterval,
        wordCount: Int,
        succeeded: Bool
    ) -> MiniDrillOutcome {
        let variation = DrillCatalog.allVariations.first { $0.id == variationId }!
        let drill = DrillRecommendationV2(variation: variation, reason: "test", trendContext: nil, alternateFormat: nil)
        let framework = MiniDrillType.framework(for: variationId)
        let verdict = FrameworkDrillVerdict.evaluate(framework, transcript: transcript, duration: duration)
        return MiniDrillOutcome(
            drill: drill,
            drillType: MiniDrillType.from(variationId: variationId),
            transcript: transcript,
            fillerCount: 0,
            duration: duration,
            wordCount: wordCount,
            succeeded: succeeded,
            framework: framework,
            frameworkVerdict: verdict
        )
    }

    @Test func structuralVerdictDoesNotMoveXP() {
        // Two STAR outcomes IDENTICAL in every numeric input (succeeded, words,
        // duration, fillers) but one has a turn and one is flat. XP MUST match:
        // the verdict is coaching copy only, never a score input.
        let withTurn = outcome(
            variationId: "story.starTurn",
            transcript: "I was leading a struggling project with no budget but then everything shifted completely after deadline.",
            duration: 40,
            wordCount: 60,
            succeeded: true
        )
        let flat = outcome(
            variationId: "story.starTurn",
            transcript: "I manage a marketing department handling several campaigns across multiple regions every quarter consistently always.",
            duration: 40,
            wordCount: 60,
            succeeded: true
        )
        #expect(withTurn.frameworkVerdict == .star(.turnDetected))
        #expect(flat.frameworkVerdict == .star(.flat))
        #expect(DrillXPEngine.calculate(outcome: withTurn) == DrillXPEngine.calculate(outcome: flat))
    }

    @Test func feedbackCopyMatchesVerdictBand() {
        let landed = outcome(
            variationId: "concise.elevatorPitch",
            transcript: "Hi, I'm Jordan and I build communication training software for nervous speakers under real pressure.",
            duration: 17,
            wordCount: 16,
            succeeded: true
        )
        let missName = outcome(
            variationId: "concise.elevatorPitch",
            transcript: "This software helps people speak with confidence and clarity under real pressure every single day.",
            duration: 15,
            wordCount: 15,
            succeeded: true
        )
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: landed).contains("pitch") || DrillCompletionCopy.frameworkFeedback(outcome: landed).contains("hook"))
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: missName).contains("introduce yourself"))
        // Titles are verdict-keyed.
        #expect(DrillCompletionCopy.title(for: landed) == "Pitch Landed")
        #expect(DrillCompletionCopy.title(for: missName) == "Who Are You?")
    }

    @Test func belowFloorFeedbackFallsBackToSkillLine() {
        // A too-thin framework rep (no verdict) must NOT emit a structural
        // claim — it falls back to the neutral skill-area feedback line.
        let thin = outcome(
            variationId: "story.starTurn",
            transcript: "I led a team.",
            duration: 6,
            wordCount: 4,
            succeeded: false
        )
        #expect(thin.frameworkVerdict == nil)
        let expectedFallback = DrillCompletionCopy.feedbackLine(
            skillArea: .answerDevelopment,
            succeeded: false,
            fillerCount: 0,
            wordCount: 4,
            duration: 6,
            wpm: 4.0 / 6.0 * 60
        )
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: thin) == expectedFallback)
        // And the title falls back to the neutral skill title, not a structural label.
        #expect(DrillCompletionCopy.title(for: thin) == "Go Deeper")
    }

    // MARK: Reframe / AREA copy + score-safety

    @Test func cewAndMonroeCopyMatchesVerdictBand() {
        let fullCEW = outcome(
            variationId: "structure.claimEvidenceWarrant",
            transcript: "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        let missingWarrant = outcome(
            variationId: "structure.claimEvidenceWarrant",
            transcript: "We should raise the price because demand keeps climbing well past our current supply levels.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        let fullMonroe = outcome(
            variationId: "structure.monroeSequence",
            transcript: "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high. Start by approving the pilot this week.",
            duration: 45,
            wordCount: 60,
            succeeded: true
        )
        let missingAction = outcome(
            variationId: "structure.monroeSequence",
            transcript: "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high.",
            duration: 45,
            wordCount: 60,
            succeeded: true
        )

        #expect(fullCEW.frameworkVerdict == .claimEvidenceWarrant(.complete))
        #expect(missingWarrant.frameworkVerdict == .claimEvidenceWarrant(.missingWarrant))
        #expect(fullMonroe.frameworkVerdict == .monroeSequence(.complete))
        #expect(missingAction.frameworkVerdict == .monroeSequence(.missingAction))
        #expect(DrillCompletionCopy.title(for: fullCEW) == "Full CEW")
        #expect(DrillCompletionCopy.title(for: missingWarrant) == "Add Warrant")
        #expect(DrillCompletionCopy.title(for: fullMonroe) == "Sequence Landed")
        #expect(DrillCompletionCopy.title(for: missingAction) == "Ask for Action")
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: fullCEW).contains("Claim, evidence, warrant"))
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: missingWarrant).contains("warrant"))
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: fullMonroe).contains("Need, solution, picture, action"))
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: missingAction).contains("concrete action"))
    }

    @Test func reframeCopyMatchesVerdictBand() {
        let reframed = outcome(
            variationId: "structure.bridgeReframe",
            transcript: "That's fair, but the real question is whether our customers actually trust the product enough.",
            duration: 22,
            wordCount: 15,
            succeeded: true
        )
        let faced = outcome(
            variationId: "structure.bridgeReframe",
            transcript: "Our revenue grew thirty percent this quarter and the team shipped every major feature on time.",
            duration: 22,
            wordCount: 15,
            succeeded: true
        )
        #expect(reframed.frameworkVerdict == .bridgeReframe(.reframed))
        #expect(faced.frameworkVerdict == .bridgeReframe(.facedDirectly))
        #expect(DrillCompletionCopy.title(for: reframed) == "Reframed It")
        #expect(DrillCompletionCopy.title(for: faced) == "Faced It Head-On")
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: reframed).contains("reframe"))
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: faced).contains("reframe"))
    }

    @Test func areaCopyMatchesVerdictBand() {
        let complete = outcome(
            variationId: "depth.areaAnswer",
            transcript: "Remote work wins. The reason is teams ship faster. For example, last week we shipped in two days. So that's why remote wins.",
            duration: 40,
            wordCount: 50,
            succeeded: true
        )
        let missingExample = outcome(
            variationId: "depth.areaAnswer",
            transcript: "Discipline beats talent because consistent effort compounds over time and habits outlast motivation eventually here.",
            duration: 40,
            wordCount: 50,
            succeeded: true
        )
        #expect(complete.frameworkVerdict == .areaAnswer(.complete))
        #expect(missingExample.frameworkVerdict == .areaAnswer(.missingExample))
        #expect(DrillCompletionCopy.title(for: complete) == "Full AREA")
        #expect(DrillCompletionCopy.title(for: missingExample) == "Need an Example")
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: complete).contains("AREA"))
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: missingExample).contains("example"))
    }

    @Test func newFrameworkVerdictsDoNotMoveXP() {
        // Identical numeric inputs, divergent structural verdicts -> identical XP
        // for BOTH new drills. The verdict is coaching copy only, never a score.
        let reframed = outcome(
            variationId: "structure.bridgeReframe",
            transcript: "That's fair, but the real question is whether our customers actually trust the product enough.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        let faced = outcome(
            variationId: "structure.bridgeReframe",
            transcript: "Our revenue grew thirty percent this quarter and the team shipped every major feature on time.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        #expect(reframed.frameworkVerdict == .bridgeReframe(.reframed))
        #expect(faced.frameworkVerdict == .bridgeReframe(.facedDirectly))
        #expect(DrillXPEngine.calculate(outcome: reframed) == DrillXPEngine.calculate(outcome: faced))

        let areaComplete = outcome(
            variationId: "depth.areaAnswer",
            transcript: "Remote work wins. The reason is teams ship faster. For example, last week we shipped in two days. So that's why remote wins.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        let areaMissing = outcome(
            variationId: "depth.areaAnswer",
            transcript: "Discipline beats talent because consistent effort compounds over time and habits outlast motivation eventually here.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        #expect(areaComplete.frameworkVerdict == .areaAnswer(.complete))
        #expect(areaMissing.frameworkVerdict == .areaAnswer(.missingExample))
        #expect(DrillXPEngine.calculate(outcome: areaComplete) == DrillXPEngine.calculate(outcome: areaMissing))

        let cewComplete = outcome(
            variationId: "structure.claimEvidenceWarrant",
            transcript: "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        let cewMiss = outcome(
            variationId: "structure.claimEvidenceWarrant",
            transcript: "Remote work clearly boosts output and keeps the whole team genuinely happier every single day.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        #expect(cewComplete.frameworkVerdict == .claimEvidenceWarrant(.complete))
        #expect(cewMiss.frameworkVerdict == .claimEvidenceWarrant(.assertionOnly))
        #expect(DrillXPEngine.calculate(outcome: cewComplete) == DrillXPEngine.calculate(outcome: cewMiss))

        let monroeComplete = outcome(
            variationId: "structure.monroeSequence",
            transcript: "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high. Start by approving the pilot this week.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        let monroeMiss = outcome(
            variationId: "structure.monroeSequence",
            transcript: "Imagine the hiring team losing top candidates today. The problem is our interview loop takes three weeks. My proposal is a two day decision sprint. Picture candidates getting clear answers while interest is high.",
            duration: 30,
            wordCount: 45,
            succeeded: true
        )
        #expect(monroeComplete.frameworkVerdict == .monroeSequence(.complete))
        #expect(monroeMiss.frameworkVerdict == .monroeSequence(.missingAction))
        #expect(DrillXPEngine.calculate(outcome: monroeComplete) == DrillXPEngine.calculate(outcome: monroeMiss))
    }

    @Test func areaBelowFloorFeedbackFallsBackToSkillLine() {
        // A too-thin AREA rep (no verdict) must NOT emit a structural claim — it
        // falls back BYTE-IDENTICAL to the neutral answer-development line.
        let thin = outcome(
            variationId: "depth.areaAnswer",
            transcript: "Yes, because reasons.",
            duration: 6,
            wordCount: 3,
            succeeded: false
        )
        #expect(thin.frameworkVerdict == nil)
        let expectedFallback = DrillCompletionCopy.feedbackLine(
            skillArea: .answerDevelopment,
            succeeded: false,
            fillerCount: 0,
            wordCount: 3,
            duration: 6,
            wpm: 3.0 / 6.0 * 60
        )
        #expect(DrillCompletionCopy.frameworkFeedback(outcome: thin) == expectedFallback)
        #expect(DrillCompletionCopy.title(for: thin) == "Go Deeper")
    }
}

// MARK: - NextAction Engine Tests

struct NextActionEngineTests {

    private func makeBaseline(
        sessionCount: Int = 15,
        fillerRate: Double = 2.0,
        pace: Double = 135,
        score: Double = 7.0,
        strengths: [String] = ["Pace control"],
        blockers: [String] = []
    ) -> CommunicationBaseline {
        let confidence = BaselineConfidence.from(sessionCount: sessionCount)
        return CommunicationBaseline(
            lastUpdated: Date(),
            sessionCount: sessionCount,
            qualifyingSessionCount: sessionCount,
            fillerRate: BaselineStat(value: fillerRate, sampleCount: sessionCount, confidence: confidence, trend: .stable, percentile25: fillerRate * 0.7, percentile75: fillerRate * 1.3),
            pace: BaselineStat(value: pace, sampleCount: sessionCount, confidence: confidence, trend: .stable, percentile25: pace - 10, percentile75: pace + 10),
            paceVariance: .empty,
            durationTendency: BaselineStat(value: 45, sampleCount: sessionCount, confidence: confidence, trend: .stable, percentile25: 35, percentile75: 55),
            pauseRate: .empty,
            pauseFilledRatio: .empty,
            openingStrength: .empty,
            closingStrength: .empty,
            structureQuality: .empty,
            answerDepth: .empty,
            clarity: .empty,
            vocabularyRange: .empty,
            hedgingRate: .empty,
            averageScore: BaselineStat(value: score, sampleCount: sessionCount, confidence: confidence, trend: .stable, percentile25: score - 1, percentile75: score + 1),
            clutchWordFrequencies: [:],
            topStrengths: strengths,
            persistentBlockers: blockers
        )
    }

    private func makePressure(resilience: Double? = nil) -> PressureProfile {
        if let resilience {
            // Build a profile where resilience is approximately the target.
            // The resilience formula averages delta across filler, pace, and score,
            // so we need all three dimensions populated to get the right result.
            let targetDelta = 1.0 - resilience  // e.g. resilience 0.4 → delta 0.6
            let fillerDelta = targetDelta * 2.0  // fillerDelta/max(casual,1) = targetDelta
            let casualFiller = BaselineStat(value: 2.0, sampleCount: 10, confidence: .established, trend: .stable, percentile25: 1.5, percentile75: 2.5)
            let highFiller = BaselineStat(value: 2.0 + fillerDelta, sampleCount: 5, confidence: .moderate, trend: .stable, percentile25: 2.0, percentile75: 3.0 + fillerDelta)
            // Pace: casual 130, high = 130 * (1 + targetDelta)
            let casualPace = BaselineStat(value: 130, sampleCount: 10, confidence: .established, trend: .stable, percentile25: 120, percentile75: 140)
            let highPace = BaselineStat(value: 130 * (1 + targetDelta), sampleCount: 5, confidence: .moderate, trend: .stable, percentile25: 140, percentile75: 180)
            // Score: casual 7.0, high = 7.0 * (1 - targetDelta)
            let casualScore = BaselineStat(value: 7.0, sampleCount: 10, confidence: .established, trend: .stable, percentile25: 6.0, percentile75: 8.0)
            let highScore = BaselineStat(value: max(1, 7.0 * (1 - targetDelta)), sampleCount: 5, confidence: .moderate, trend: .stable, percentile25: 2.0, percentile75: 5.0)
            return PressureProfile(
                casualFillerRate: casualFiller, highFillerRate: highFiller,
                casualPace: casualPace, highPace: highPace,
                casualScore: casualScore, highScore: highScore
            )
        }
        return .empty
    }

