        // the common "added the file but Xcode didn't sync" failure mode.
        let url = Bundle.main.url(forResource: "Localizable", withExtension: "xcstrings")
        // The catalog gets compiled to .strings tables at build time —
        // the .xcstrings source file isn't always present in the runtime
        // bundle. Fall back to confirming the localisation table works
        // for a single key by Bundle.localizedString returning non-empty.
        if url == nil {
            #expect(!Bundle.main.localizedString(forKey: "Account", value: nil, table: nil).isEmpty)
        } else {
            #expect(url != nil)
        }
    }
}

// MARK: - Skill Level-Up detection
//
// Asks the question: when a session bumps a SkillTrend up a band, do we
// queue a celebration event? And do we silently ignore drops, never
// firing a "punish" moment? The detection logic itself is pure — these
// tests don't touch UserDefaults; they exercise the static `detect`
// helper directly.

struct SkillLevelUpDetectionTests {

    private func trend(_ area: SkillArea, _ level: SkillLevel) -> SkillTrend {
        SkillTrend(
            skillArea: area,
            direction: .stable,
            confidence: .medium,
            windowSize: 5,
            currentLevel: level
        )
    }

    @Test func upwardCrossingFiresEvent() {
        let previous: [SkillArea: SkillLevel] = [.fillerReduction: .developing]
        let current = [trend(.fillerReduction, .solid)]
        let events = SkillLevelUpEvent.detect(previous: previous, current: current)
        #expect(events.count == 1)
        #expect(events.first?.previousLevel == .developing)
        #expect(events.first?.newLevel == .solid)
    }

    @Test func downwardCrossingDoesNotFire() {
        // Per the brand anti-goal "never punish-shame a miss in copy",
        // drops are stored silently. No event fires.
        let previous: [SkillArea: SkillLevel] = [.paceControl: .solid]
        let current = [trend(.paceControl, .developing)]
        let events = SkillLevelUpEvent.detect(previous: previous, current: current)
        #expect(events.isEmpty)
    }

    @Test func sameLevelDoesNotFire() {
        let previous: [SkillArea: SkillLevel] = [.structure: .solid]
        let current = [trend(.structure, .solid)]
        #expect(SkillLevelUpEvent.detect(previous: previous, current: current).isEmpty)
    }

    @Test func firstObservationDoesNotFire() {
        // No previous reading for this skill — first time it's been ranked.
        // We don't celebrate the first sighting; we wait for an actual
        // upward transition before firing the moment.
        let previous: [SkillArea: SkillLevel] = [:]
        let current = [trend(.openingStrength, .solid)]
        #expect(SkillLevelUpEvent.detect(previous: previous, current: current).isEmpty)
    }

    @Test func multipleSkillsCanCrossInOneSession() {
        // Rare but real — a strong session can move multiple skills.
        let previous: [SkillArea: SkillLevel] = [
            .fillerReduction: .developing,
            .paceControl:     .developing,
            .structure:       .weak
        ]
        let current = [
            trend(.fillerReduction, .solid),     // up
            trend(.paceControl,     .developing), // unchanged
            trend(.structure,       .developing)  // up
        ]
        let events = SkillLevelUpEvent.detect(previous: previous, current: current)
        #expect(events.count == 2)
        let areas = Set(events.map { $0.skillArea })
        #expect(areas == [.fillerReduction, .structure])
    }

    @Test func headlineCopyMatchesSkill() {
        let event = SkillLevelUpEvent(
            skillArea: .fillerReduction,
            previousLevel: .developing,
            newLevel: .solid,
            date: Date()
        )
        #expect(event.headline == "Filler Words leveled up")
        #expect(event.subline == "Developing → Solid")
    }
}

// MARK: - AI Rewrite voice-preservation (real-device feedback fix)
//
// User-stated requirement at M14: "don't want them to learn how to speak
// like chatgpt/AI right, THIS IS VERY IMPORTANT". These tests pin the
// deterministic pieces of the rewrite service — VoiceSignals + the
// content filter — so the voice-preservation contract can't regress
// silently. The actual model call is integration-only; we don't test it
// here.

struct VoiceSignalsTests {

    @Test func detectsContractions() {
        let s = VoiceSignals.compute(transcript: "I'm not sure about it. I don't know yet, but it's something I'm working on.")
        #expect(s.usesContractions == true)
    }

    @Test func absenceOfContractionsReadsAsFormal() {
        let s = VoiceSignals.compute(transcript: "I am not sure about it. I do not know yet, but it is something I am working on.")
        #expect(s.usesContractions == false)
    }

    @Test func detectsHedging() {
        let s = VoiceSignals.compute(transcript: "It's kind of like a thing where I sort of feel that way, you know?")
        #expect(s.usesHedging == true)
    }

    @Test func averageSentenceLengthIsRoughlyCorrect() {
        // Three sentences of ~6 words each.
        let s = VoiceSignals.compute(transcript: "I think this matters a lot. We should look at it. The team can probably help.")
        #expect(s.avgSentenceLength >= 5 && s.avgSentenceLength <= 8)
    }

    @Test func firstPersonHeavyDetected() {
        let s = VoiceSignals.compute(transcript: "I think I'm pretty good at this. I've been doing it for a while. I just need to keep going. I really like it.")
        #expect(s.firstPersonHeavy == true)
    }

    @Test func distinctiveWordsExcludeStopwords() {
        let s = VoiceSignals.compute(transcript: "Strategic thinking really matters because everything around it depends on people understanding the framework before they actually start.")
        // "really", "actually", "everything", "around", "people", "before"
        // are stopwords and should be excluded.
        #expect(!s.distinctiveWords.contains("really"))
        #expect(!s.distinctiveWords.contains("actually"))
        #expect(!s.distinctiveWords.contains("everything"))
        // "framework" and "strategic" should make it through.
        #expect(s.distinctiveWords.contains("strategic") || s.distinctiveWords.contains("framework"))
    }

    @Test func emptyTranscriptReturnsEmptySignals() {
        let s = VoiceSignals.compute(transcript: "")
        #expect(s.avgSentenceLength == 0)
        #expect(s.distinctiveWords.isEmpty)
    }
}

struct RewriteContentFilterTests {

    private let casualSignals = VoiceSignals(
        avgSentenceLength: 8,
        usesContractions: true,
        usesHedging: true,
        firstPersonHeavy: true,
        distinctiveWords: ["meeting", "project", "manager"]
    )

    @Test func rejectsCorporateJargonUserDidNotSay() {
        // User never said "leverage" — model output containing it must be
        // rejected. This is the AI-tell guard the user explicitly asked for.
        let raw = "We can leverage the meeting to align on the project."
        #expect(RewriteContentFilter.accept(raw, signals: casualSignals) == nil)
    }

    @Test func rejectsValueAddPhrasing() {
        let raw = "It's really a value-add for the project — strategic thinking matters."
        #expect(RewriteContentFilter.accept(raw, signals: casualSignals) == nil)
    }

    @Test func rejectsMissingContractionsWhenUserUsesThem() {
        // User uses contractions; rewrite without any contraction reads
        // formal vs. their voice — reject.
        let raw = "I will share the update with the team in the meeting."
        #expect(RewriteContentFilter.accept(raw, signals: casualSignals) == nil)
    }

    @Test func acceptsCleanCasualRewrite() {
        let raw = "I'll share the update with the team in the meeting."
        let cleaned = RewriteContentFilter.accept(raw, signals: casualSignals)
        #expect(cleaned == "I'll share the update with the team in the meeting.")
    }

    @Test func rejectsTooShort() {
        let raw = "I will."
        #expect(RewriteContentFilter.accept(raw, signals: casualSignals) == nil)
    }

    @Test func rejectsTooLong() {
        let raw = String(repeating: "x", count: 250) + "."
        #expect(RewriteContentFilter.accept(raw, signals: casualSignals) == nil)
    }

    @Test func stripsEnclosingDoubleQuotes() {
        let raw = "\"I'll keep this concise — here's the answer in one line for the team.\""
        let cleaned = RewriteContentFilter.accept(raw, signals: casualSignals)
        #expect(cleaned == "I'll keep this concise — here's the answer in one line for the team.")
    }

    @Test func acceptsAITellWordIfUserActuallyUsedIt() {
        // If the user actually said "strategic" themselves, the rewrite
        // is allowed to keep it. The filter is "no NEW jargon", not
        // "no jargon at all."
        let signals = VoiceSignals(
            avgSentenceLength: 8,
            usesContractions: false,
            usesHedging: false,
            firstPersonHeavy: false,
            distinctiveWords: ["strategic", "meeting", "project"]
        )
        let raw = "The meeting is strategic for our project this quarter."
        let cleaned = RewriteContentFilter.accept(raw, signals: signals)
        #expect(cleaned != nil)
    }
}

// MARK: - Score recalibration (real-device feedback fix)
//
// Real-device QA surfaced that an obviously-poor rep (80 WPM, 2 fillers,
// 30s on Medium) was scoring 8/10 — too generous. The fix tightened the
// pace bands and score formula. These tests pin the new behaviour so we
// don't regress to the old bands.

struct ScoreCalibrationTests {

    /// 80 WPM is genuinely halting speech, not "controlled and calm".
    /// Old behaviour returned 0.72 (encouraging) — caller's score got
    /// lifted by ~1.4 points across that band. New behaviour: ≤ 0.5.
    @Test func paceScore80WPMIsHonestlyPoor() {
        let score = PracticeEvaluator.paceScoreForTesting(wpm: 80, wordCount: 40)
        #expect(score <= 0.5, "80 WPM should not get >0.5 pace credit; got \(score)")
    }

    @Test func paceScoreInTargetRangeReturnsFullCredit() {
        // 145 WPM is mid-target.
        let score = PracticeEvaluator.paceScoreForTesting(wpm: 145, wordCount: 40)
        #expect(score == 1.0)
    }

    @Test func paceScoreOver200WPMIsRushed() {
        let score = PracticeEvaluator.paceScoreForTesting(wpm: 220, wordCount: 60)
        #expect(score <= 0.3, "220 WPM is sprinting; pace credit must be low")
    }

    /// Halting label, not "Measured" — copy must match the new band.
    @Test func paceSnapshotAt80WPMUsesHonestLabel() {
        let snap = PracticeEvaluator.paceSnapshotForTesting(wpm: 80, wordCount: 40)
        #expect(snap.label == "Hesitant" || snap.label == "Halting",
                "label was \(snap.label); old 'Measured' was the bug")
    }

    /// The original real-device read: 80 WPM, 2 fillers, 30s on Medium
    /// difficulty. Score should NOT be 8 anymore.
    @Test func realWorldPoorRepDoesNotScoreEight() {
        // Build a transcript with ~40 words to hit 80 WPM in 30s.
        let words = Array(repeating: "word", count: 40).joined(separator: " ")
        let evaluation = PracticeEvaluator.evaluateTimedPractice(
            transcript: words,
            fillerCount: 2,
            duration: 30,
            difficulty: .medium,
            recentSessions: [],
            profile: nil,
            transcriptConfidence: nil
        )
        #expect(evaluation.score <= 6,
                "80 WPM + 2 fillers + 30s Medium scored \(evaluation.score); old bug returned 8")
    }

    @Test func abortedRepHeadlineIsHonestNotGoodWarmup() {
        // A 0-word / 0s rep must name itself, not read "Good warmup".
        let aborted = PracticeEvaluator.evaluateTimedPractice(
            transcript: "", fillerCount: 0, duration: 0,
            difficulty: .medium, recentSessions: [], profile: nil
        )
        #expect(aborted.headline == "Too short to score")
        #expect(aborted.score == 1)

        // A real rep keeps its normal headline.
        let real = PracticeEvaluator.evaluateTimedPractice(
            transcript: Array(repeating: "word", count: 60).joined(separator: " "),
            fillerCount: 1, duration: 40,
            difficulty: .medium, recentSessions: [], profile: nil
        )
        #expect(real.headline != "Too short to score")
    }

    /// Filler penalty must accelerate past 4 fillers — old cap of 3.0
    /// meant 10 fillers looked the same as 4. New cap is 5.5 with
    /// non-linear ramp.
    @Test func highFillerCountCostsMoreThanLowCount() {
        let lowFillerWords = Array(repeating: "word", count: 60).joined(separator: " ")
        let lowEval = PracticeEvaluator.evaluateTimedPractice(
            transcript: lowFillerWords,
            fillerCount: 2,
            duration: 30,
            difficulty: .medium,
            recentSessions: [],
            profile: nil
        )
        let highEval = PracticeEvaluator.evaluateTimedPractice(
            transcript: lowFillerWords,
            fillerCount: 10,
            duration: 30,
            difficulty: .medium,
            recentSessions: [],
            profile: nil
        )
        #expect(lowEval.score > highEval.score,
                "10 fillers (\(highEval.score)) should score lower than 2 (\(lowEval.score))")
    }

    // MARK: - Typography Dynamic Type contract
    //
    // Every Typography role builds through `figtree(_:weight:relativeTo:)`
    // or `manrope(_:weight:relativeTo:)`, both of which now *require* a
    // `Font.TextStyle` argument. If a future refactor drops `relativeTo:`
    // the call site fails to compile. These tests sanity-check that the
    // canonical roles still resolve to a non-nil Font (i.e. Family.display
    // / Family.text names haven't drifted to something the system can't
    // find — Font.custom always returns a Font but the smoke test catches
    // any future accidental nil-able variant).

    @Test func typographyRolesResolveToFonts() {
        // Touch every role so a renamed family or removed enum case fails
        // the test rather than silently rendering the system fallback.
        _ = Typography.display
        _ = Typography.hero
        _ = Typography.screenTitle
        _ = Typography.sectionHero
        _ = Typography.bigStat
        _ = Typography.statHero
        _ = Typography.cardTitle
        _ = Typography.headline
        _ = Typography.cardLabel
        _ = Typography.subheadline
        _ = Typography.body
        _ = Typography.caption
        _ = Typography.captionSmall
        _ = Typography.micro
        _ = Typography.nav
        #expect(Typography.Family.display == "Figtree")
        #expect(Typography.Family.text == "Manrope")
    }

    @Test func typographyNumericHelperReturnsMonospacedDigit() {
        // The numeric helper must monospace digits so stat counters don't
        // wobble when the leading digit changes width.
        _ = Typography.figtreeNumeric(size: 28)
        _ = Typography.figtreeNumeric(size: 18, weight: .heavy, relativeTo: .headline)
        // Compile-time check is the contract — runtime smoke is enough.
    }

    // MARK: - Prompt-grounded relevance (replaces the wordCount/65 proxy)
    //
    // The Relevance *rating* on the 7-dimension card now reads the prompt,
    // not just length. These pin the conservative contract: a clear miss
    // only softens to "Mostly relevant" (.ok), never a confident off-topic
    // (.couldImprove) from overlap alone; nil/thin prompt or thin transcript
    // defaults HIGH (no down-rate on weak evidence); the named overlap
    // boundary is locked; and the numeric score never moves.

    private func relevanceCategory(in categories: [FeedbackCategory]) -> FeedbackRating? {
        categories.first(where: { $0.dimension == "Relevance" })?.rating
    }

    @Test func promptRelevanceOffTopicLongAnswerLowOverlapRatesDownNotConfidentMiss() {
        // 60 words about an unrelated topic, no shared content words with the
        // shipping question.
        let transcript = Array(repeating: "garden flowers bloom slowly through spring sunshine warmth", count: 7)
            .joined(separator: " ")
        let read = PracticeEvaluator.promptRelevance(
            prompt: "Should we ship the feature this week?",
            transcript: transcript
        )
        #expect(read.evidenceFloorMet)
        #expect(read.overlap < PracticeEvaluator.relevanceWeakOverlap)
        #expect(read.progress == 0.45)
        // Rating softens to .ok, never .couldImprove from overlap alone.
        let categories = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 56, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: 1.0,
            paceProgress: 1.0, transcript: transcript, relevanceProgress: read.progress
        )
        #expect(relevanceCategory(in: categories) == .ok)
    }

    @Test func promptRelevanceOnTopicAnswerHighOverlapRatesUp() {
        let transcript = "We should ship the feature this week because the rollout data and customer feedback both point the same direction."
        let read = PracticeEvaluator.promptRelevance(
            prompt: "Should we ship the feature this week?",
            transcript: transcript
        )
        #expect(read.overlap >= PracticeEvaluator.relevanceStrongOverlap)
        #expect(read.progress == 1.0)
        let categories = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 20, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: 1.0,
            paceProgress: 1.0, transcript: transcript, relevanceProgress: read.progress
        )
        #expect(relevanceCategory(in: categories) == .good)
    }

    @Test func promptRelevanceNilPromptDefaultsHighNoDownRate() {
        let transcript = Array(repeating: "word", count: 60).joined(separator: " ")
        let read = PracticeEvaluator.promptRelevance(prompt: nil, transcript: transcript)
        #expect(read.evidenceFloorMet == false)
        #expect(read.progress == PracticeEvaluator.relevanceAbsentDefault)
        // Rating identical to the contentProgress path for the same length:
        // 60 words -> contentProgress 60/65 ≈ 0.92 -> .good; the high default
        // (0.70) also yields .good, so the nil-prompt path matches today.
        let withDefault = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 60, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: min(60.0 / 65.0, 1.0),
            paceProgress: 1.0, transcript: transcript, relevanceProgress: read.progress
        )
        let legacy = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 60, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: min(60.0 / 65.0, 1.0),
            paceProgress: 1.0, transcript: transcript, relevanceProgress: nil
        )
        #expect(relevanceCategory(in: withDefault) == relevanceCategory(in: legacy))
    }

    @Test func promptRelevanceThinTranscriptBelowFloorStaysTentative() {
        let read = PracticeEvaluator.promptRelevance(
            prompt: "Should we ship the feature this week?",
            transcript: "Yes we should ship it" // 5 words < minTranscriptWordsForRelevance
        )
        #expect(read.evidenceFloorMet == false)
        #expect(read.progress == PracticeEvaluator.relevanceAbsentDefault)
        #expect(read.progress >= 0.4) // never a confident off-topic
    }

    @Test func promptRelevanceThinPromptUnderThreeContentWordsBelowFloor() {
        // "Why?" has zero content words after the >=4-char + stop filter.
        let read = PracticeEvaluator.promptRelevance(
            prompt: "Why?",
            transcript: Array(repeating: "answer", count: 40).joined(separator: " ")
        )
        #expect(read.promptContentWords < PracticeEvaluator.minPromptContentWordsForRelevance)
        #expect(read.evidenceFloorMet == false)
        #expect(read.progress == PracticeEvaluator.relevanceAbsentDefault)
    }

    @Test func promptRelevanceBoundaryOverlapAtStrongThresholdIsGood() {
        // Prompt with exactly 10 distinct content words. A transcript echoing
        // exactly 3 of them = overlap 0.30 == relevanceStrongOverlap -> .good.
        // 12 transcript words clears the transcript floor.
        // 10 distinct content words (all >=4 chars, none a stop word).
        let prompt = "Whales travel oceans yearly tracking plankton blooms northern southern currents"
        let echoingThree = "Whales travel oceans every season and also rest quietly near shore daily"
        let read = PracticeEvaluator.promptRelevance(prompt: prompt, transcript: echoingThree)
        #expect(read.promptContentWords == 10)
        #expect(read.overlap == PracticeEvaluator.relevanceStrongOverlap)
        #expect(read.progress == 1.0)

        // One fewer echoed word -> overlap 0.20 < 0.30 -> not full credit, but above the ramp floor.
        let echoingTwo = "Whales travel deeply every season and also rest quietly near shore daily"
        let readTwo = PracticeEvaluator.promptRelevance(prompt: prompt, transcript: echoingTwo)
        #expect(readTwo.overlap < PracticeEvaluator.relevanceStrongOverlap)
        #expect(readTwo.progress < 1.0)
        #expect(readTwo.progress >= 0.45)
    }

    @Test func evaluateTimedPracticeQuestionDefaultedExistingCallSitesUnchanged() {
        // Back-compat for the 3 existing ScoreCalibration call sites + 3 prod
        // sites that pass no `question`: the defaulted nil must NOT change the
        // score (formula reads contentProgress, untouched), and the omitted
        // arg must behave identically to an explicit nil. 60 words sits where
        // the high nil-prompt default (0.70) and the contentProgress proxy
        // (60/65 ≈ 0.92) BOTH read .good, so the rating matches today too.
        let words = Array(repeating: "word", count: 60).joined(separator: " ")
        let baseline = PracticeEvaluator.evaluateTimedPractice(
            transcript: words, fillerCount: 2, duration: 30,
            difficulty: .medium, recentSessions: [], profile: nil
        )
        let withDefault = PracticeEvaluator.evaluateTimedPractice(
            transcript: words, fillerCount: 2, duration: 30,
            difficulty: .medium, recentSessions: [], profile: nil,
            transcriptConfidence: nil, question: nil
        )
        #expect(baseline.score == withDefault.score)
        #expect(relevanceCategory(in: baseline.categories) == relevanceCategory(in: withDefault.categories))
        // And that rating is .good — matching the pre-change contentProgress
        // read for a 60-word answer (no upward drift at this length).
        #expect(relevanceCategory(in: withDefault.categories) == .good)
    }

    @Test func evaluateTimedPracticeOffTopicDoesNotMoveScoreOnlyRating() {
        // Same transcript/duration/fillers, two questions: on-topic vs
        // off-topic. The numeric score must be IDENTICAL (score formula reads
        // contentProgress, untouched); only the Relevance rating may differ.
        let transcript = "We should ship the feature this week because the rollout data and customer feedback both point the same direction and the team is ready."
        let onTopic = PracticeEvaluator.evaluateTimedPractice(
            transcript: transcript, fillerCount: 1, duration: 40,
            difficulty: .medium, recentSessions: [], profile: nil,
            transcriptConfidence: nil, question: "Should we ship the feature this week?"
        )
        let offTopic = PracticeEvaluator.evaluateTimedPractice(
            transcript: transcript, fillerCount: 1, duration: 40,
            difficulty: .medium, recentSessions: [], profile: nil,
            transcriptConfidence: nil, question: "What did you have for breakfast on holiday abroad?"
        )
        #expect(onTopic.score == offTopic.score, "Relevance must be rating-only; score moved")
        #expect(relevanceCategory(in: onTopic.categories) == .good)
        #expect(relevanceCategory(in: offTopic.categories) == .ok)
    }

    @Test func buildFeedbackCategoriesRelevanceProgressOverridesContentProgress() {
        // contentProgress=1.0 (would be .good) but relevanceProgress=0.45 -> .ok.
        let overridden = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 60, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: 1.0,
            paceProgress: 1.0, transcript: "filler body text", relevanceProgress: 0.45
        )
        #expect(relevanceCategory(in: overridden) == .ok)
        // relevanceProgress=nil -> falls back to contentProgress (.good).
        let fallback = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 60, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: 1.0,
            paceProgress: 1.0, transcript: "filler body text", relevanceProgress: nil
        )
        #expect(relevanceCategory(in: fallback) == .good)
    }

    @Test func relevanceCopyStringsUnchangedNoOverclaim() {
        // The three Relevance note strings must be byte-identical post-change
        // — we changed the gating signal, not the copy. .good / .ok /
        // .couldImprove each map to its established string.
        let good = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 60, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: 1.0,
            paceProgress: 1.0, transcript: "body", relevanceProgress: 1.0
        )
        let ok = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 60, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: 1.0,
            paceProgress: 1.0, transcript: "body", relevanceProgress: 0.45
        )
        let low = PracticeEvaluator.buildFeedbackCategoriesForTesting(
            wordCount: 60, duration: 40, fillerCount: 0,
            wordsPerMinute: 140, durationProgress: 1.0, contentProgress: 1.0,
            paceProgress: 1.0, transcript: "body", relevanceProgress: 0.2
        )
        let goodNote = good.first(where: { $0.dimension == "Relevance" })?.note
        let okNote = ok.first(where: { $0.dimension == "Relevance" })?.note
        let lowNote = low.first(where: { $0.dimension == "Relevance" })?.note
        #expect(goodNote == "Stayed on topic")
        #expect(okNote == "Mostly relevant")
        #expect(lowNote == "Connect more directly to the prompt")
    }
}

// MARK: - Prompt-grounded relevance follow-on (chat coach + Timed three-part note)
//
// Initiative #8 gave the deterministic Relevance rating + the two AI surfaces a
// shared `PromptRelevanceRead`. This suite pins the follow-on that threads the
// SAME read into the two surfaces #8 deferred: the live chat coach
// (`CoachContextBuilder`) and the `FeedbackEngine` Timed three-part note
// (`VerdictEngine`). Contracts mirror #8 — the verdict softens, never asserts a
// confident off-topic; weak/absent evidence yields no verdict (no down-talk);
// and the rest of the coach-note structure (momentum / next-step) never moves.
// Fixtures reuse the #8 ScoreCalibrationTests pairs so the overlap bands stay
// locked against the real tokenizer + stop set rather than re-derived here.

struct PromptRelevanceFollowOnTests {

    private let shipQuestion = "Should we ship the feature this week?"

    /// Genuine BURIED LEDE (initiative #10): the point (ship/feature/week) is
    /// present across the rep (whole overlap 3/3 = 1.0) but absent from the lead
    /// (first sentence "Honestly there were a lot of competing priorities…"
    /// echoes none of it -> first-sentence overlap 0/3 = 0.0 < weak). The only
    /// configuration that earns the positional `.buried` verdict.
    private var buriedRead: PracticeEvaluator.PromptRelevanceRead {
        let transcript = "Honestly there were a lot of competing priorities pulling at the team. We weighed the tradeoffs at length. In the end I do think we should ship the feature this week."
        return PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
    }
    /// 56 off-topic words, zero shared content words -> whole overlap 0. Used
    /// to be classified `.buried` (the pre-#10 magnitude-only mapping); under
    /// the positional mapping a point that is nowhere in the rep is NOT a buried
    /// lede — it is `.partial` ("did not clearly lead"), never the confident
    /// "arrived late" claim. The rating still softens to .ok (progress 0.45).
    private var offTopicRead: PracticeEvaluator.PromptRelevanceRead {
        let transcript = Array(repeating: "garden flowers bloom slowly through spring sunshine warmth", count: 7)
            .joined(separator: " ")
        return PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
    }
    /// On-topic answer that LEADS with the point — echoes every prompt content
    /// word, and the first sentence carries them (lead overlap 3/3) -> `.answered`.
    private var answeredRead: PracticeEvaluator.PromptRelevanceRead {
        let transcript = "We should ship the feature this week because the rollout data and customer feedback both point the same direction."
        return PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
    }
    /// 10-content-word prompt, transcript echoes exactly 2 across the whole rep
    /// and in the (single-sentence) lead -> whole 0.20, lead 0.20. Neither
    /// leads (lead < strong) nor buried (whole < strong) -> `.partial`.
    private var partialRead: PracticeEvaluator.PromptRelevanceRead {
        let prompt = "Whales travel oceans yearly tracking plankton blooms northern southern currents"
        let transcript = "Whales travel deeply every season and also rest quietly near shore daily"
        return PracticeEvaluator.promptRelevance(prompt: prompt, transcript: transcript)
    }
    /// Same prompt, single-sentence transcript echoes exactly 3 -> lead overlap
    /// == strong 0.30 -> `.answered` (the point led, inclusive boundary).
    private var boundaryAnsweredRead: PracticeEvaluator.PromptRelevanceRead {
        let prompt = "Whales travel oceans yearly tracking plankton blooms northern southern currents"
        let transcript = "Whales travel oceans every season and also rest quietly near shore daily"
        return PracticeEvaluator.promptRelevance(prompt: prompt, transcript: transcript)
    }

    // MARK: - Shared verdict mapping (the one point all four surfaces read)

    @Test func verdictAnsweredWhenPointLeads() {
        // The point led — first-sentence overlap cleared the strong bar.
        #expect(answeredRead.firstSentenceOverlap >= PracticeEvaluator.relevanceStrongOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: answeredRead) == .answered)
    }

    @Test func verdictBuriedWhenPointPresentButNotInLead() {
        // Genuine buried lede: present across the rep, absent from the lead.
        #expect(buriedRead.overlap >= PracticeEvaluator.relevanceStrongOverlap)
        #expect(buriedRead.firstSentenceOverlap < PracticeEvaluator.relevanceWeakOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: buriedRead) == .buried)
    }

    @Test func verdictOffTopicLowWholeOverlapIsPartialNotBuried() {
        // Honesty fix (initiative #10): a point that is NOWHERE in the rep is
        // not a "buried lede" — overlap alone never earns the positional
        // "arrived late" claim. Pre-#10 this fixture mapped to `.buried`.
        #expect(offTopicRead.overlap < PracticeEvaluator.relevanceWeakOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: offTopicRead) == .partial)
    }

    @Test func verdictPartialBetweenThresholds() {
        #expect(PracticeEvaluator.promptAnswerVerdict(for: partialRead) == .partial)
    }

    @Test func verdictAnsweredAtStrongLeadBoundaryInclusive() {
        // first-sentence overlap == relevanceStrongOverlap is .answered
        // (inclusive), matching the rating's `>= relevanceStrongOverlap` branch.
        #expect(boundaryAnsweredRead.firstSentenceOverlap == PracticeEvaluator.relevanceStrongOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: boundaryAnsweredRead) == .answered)
    }

    @Test func verdictPartialWhenPresentButLeadBetweenWeakAndStrong() {
        // Asymmetry lock: a high-whole-overlap rep whose LEAD overlap sits
        // between weak and strong is NOT buried (lead is not < weak) — `.buried`
        // requires the lead to genuinely miss the point, not merely under-lead.
        let prompt = "Should we adopt a four day work week policy"
        let transcript = "The policy is worth a look. Then after weighing the tradeoffs I would adopt the four day work week across the board."
        let read = PracticeEvaluator.promptRelevance(prompt: prompt, transcript: transcript)
        #expect(read.overlap >= PracticeEvaluator.relevanceStrongOverlap)
        #expect(read.firstSentenceOverlap >= PracticeEvaluator.relevanceWeakOverlap)
        #expect(read.firstSentenceOverlap < PracticeEvaluator.relevanceStrongOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: read) == .partial)
    }

    @Test func verdictAnsweredWhenLeadCarriesPointEvenWithFewExactWords() {
        // The slice's front-vs-buried boundary, positive side: a rep that LEADS
        // with the answer using few exact question words but still clears the
        // strong lead bar is `.answered`, never `.buried`.
        let transcript = "Ship it now. The rollout numbers are strong and customers are clearly waiting, so holding back only costs us momentum we will not recover."
        let read = PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
        #expect(read.firstSentenceOverlap >= PracticeEvaluator.relevanceStrongOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: read) == .answered)
    }

    @Test func verdictPartialWhenLedSubstanceButLowWholeOverlap() {
        // The slice's boundary, the "leads with the answer but reuses few exact
        // question words" case where the WHOLE overlap is also low: NOT buried
        // (whole < strong) and not answered (lead < strong) -> `.partial`. This
        // proves `.buried` needs BOTH high whole overlap AND a missing lead.
        let transcript = "Yes, release it right away. The numbers are strong, the team is ready, and customers have been asking for this capability for months now."
        let read = PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
        #expect(read.overlap < PracticeEvaluator.relevanceStrongOverlap)
        #expect(read.firstSentenceOverlap < PracticeEvaluator.relevanceStrongOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: read) != .buried)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: read) == .partial)
    }

    @Test func verdictNilBelowEvidenceFloor() {
        // nil prompt, thin transcript, and a sub-3-content-word prompt all
        // return no verdict -> no surface down-talks weak/absent evidence.
        let nilPrompt = PracticeEvaluator.promptRelevance(
            prompt: nil,
            transcript: Array(repeating: "word", count: 40).joined(separator: " ")
        )
        let thinTranscript = PracticeEvaluator.promptRelevance(
            prompt: shipQuestion,
            transcript: "Yes we should ship it"
        )
        let thinPrompt = PracticeEvaluator.promptRelevance(
            prompt: "Why?",
            transcript: Array(repeating: "answer", count: 40).joined(separator: " ")
        )
        #expect(PracticeEvaluator.promptAnswerVerdict(for: nilPrompt) == nil)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: thinTranscript) == nil)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: thinPrompt) == nil)
    }

    // MARK: - FeedbackEngine Timed three-part note (Layer 2b)

    private func note(relevance: PracticeEvaluator.PromptRelevanceRead?) -> CoachNote {
        VerdictEngine.generate(
            fillerCount: 3, duration: 45, wordCount: 100, wpm: 130, score: 6,
            categoryRatings: [:], trends: [], primaryFocus: .fillerReduction,
            drillHistory: [], promptRelevance: relevance
        )
    }

    private let buriedNoteFragment = "anchored to the question"

    @Test func buriedRelevanceAddsLeverageNote() {
        // Fires only on the genuine positional buried lede.
        #expect(note(relevance: buriedRead).leverage.contains(buriedNoteFragment))
    }

    @Test func answeredRelevanceAddsNoLeverageNote() {
        #expect(!note(relevance: answeredRead).leverage.contains(buriedNoteFragment))
    }

    @Test func partialRelevanceAddsNoLeverageNote() {
        // Only a buried lede (.buried) fires the note — partial stays quiet so
        // the leverage line never piles onto a borderline read.
        #expect(!note(relevance: partialRead).leverage.contains(buriedNoteFragment))
    }

    @Test func offTopicRelevanceAddsNoLeverageNote() {
        // A low-whole-overlap off-topic rep is `.partial` now, not `.buried`,
        // so it must NOT fire the buried-lede note (no "arrived late" implied
        // about an answer whose point is nowhere in the rep).
        #expect(PracticeEvaluator.promptAnswerVerdict(for: offTopicRead) == .partial)
        #expect(!note(relevance: offTopicRead).leverage.contains(buriedNoteFragment))
    }

    @Test func belowFloorRelevanceAddsNoLeverageNote() {
        let belowFloor = PracticeEvaluator.promptRelevance(
            prompt: shipQuestion,
            transcript: "Yes we should ship it"
        )
        #expect(!note(relevance: belowFloor).leverage.contains(buriedNoteFragment))
    }

    @Test func nilRelevanceLeavesNoteByteIdenticalBackCompat() {
        // Existing callers pass no read -> leverage identical to an explicit
        // nil, and never carries the relevance note.
        let omitted = VerdictEngine.generate(
            fillerCount: 3, duration: 45, wordCount: 100, wpm: 130, score: 6,
            categoryRatings: [:], trends: [], primaryFocus: .fillerReduction,
            drillHistory: []
        )
        let explicitNil = note(relevance: nil)
        #expect(omitted.leverage == explicitNil.leverage)
        #expect(omitted.momentum == explicitNil.momentum)
        #expect(omitted.nextStep == explicitNil.nextStep)
        #expect(!omitted.leverage.contains(buriedNoteFragment))
    }

    @Test func relevanceNoteTouchesOnlyLeverage() {
        // The substance read must not bleed into momentum or next-step — it is
        // a leverage-line concern only (mirrors buildIMContextNote).
        let withBuried = note(relevance: buriedRead)
        let withoutRead = note(relevance: nil)
        #expect(withBuried.momentum == withoutRead.momentum)
        #expect(withBuried.nextStep == withoutRead.nextStep)
        #expect(withBuried.leverage != withoutRead.leverage)
    }

    @Test func buriedNoteCopyRestrainedNoOverclaim() {
        let leverage = note(relevance: buriedRead).leverage.lowercased()
        #expect(!leverage.contains("off-topic"))
        #expect(!leverage.contains("off topic"))
        #expect(!leverage.contains("!"))
        #expect(!leverage.contains("definitely"))
        #expect(!leverage.contains("clearly"))
    }

    // MARK: - CoachContextBuilder rep-context section

    private func session(mode: PracticeMode, prompt: String?, transcript: String) -> PracticeSession {
        PracticeSession(
            transcript: transcript,
            fillerWordCount: 2,
            duration: 40,
            date: Date(),
            mode: mode,
            score: 6,
            prompt: prompt
        )
    }

    private func context(for session: PracticeSession) -> String {
        CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [session],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
    }

    @Test func contextSurfacesBuriedRelevanceForTimedRep() {
        // Genuine buried lede -> the chat-context section names the positional
        // "arrived late" read and keeps the association disclaimer.
        let transcript = "Honestly there were a lot of competing priorities pulling at the team. We weighed the tradeoffs at length. In the end I do think we should ship the feature this week."
        let ctx = context(for: session(mode: .timed, prompt: shipQuestion, transcript: transcript))
        #expect(ctx.contains("PROMPT RELEVANCE"))
        #expect(ctx.contains("the point arrived late"))
        #expect(ctx.contains("missing from the lead"))
        #expect(ctx.contains("never proof the answer was off-topic"))
    }

    @Test func contextSurfacesPositionalOverlapNumbersForTimedRep() {
        // The data line now reports BOTH the lead overlap and the whole-rep
        // overlap so the coach can cite the gap that defines a buried lede.
        let transcript = "Honestly there were a lot of competing priorities pulling at the team. We weighed the tradeoffs at length. In the end I do think we should ship the feature this week."
        let ctx = context(for: session(mode: .timed, prompt: shipQuestion, transcript: transcript))
        #expect(ctx.contains("The first sentence echoed 0%"))
        #expect(ctx.contains("the whole answer echoed 100%"))
    }

    @Test func contextSurfacesAnsweredRelevanceForTimedRep() {
        let transcript = "We should ship the feature this week because the rollout data and customer feedback both point the same direction."
        let ctx = context(for: session(mode: .timed, prompt: shipQuestion, transcript: transcript))
        #expect(ctx.contains("PROMPT RELEVANCE"))
        #expect(ctx.contains("the point led"))
    }

    @Test func contextOmitsRelevanceBelowEvidenceFloor() {
        // Thin transcript -> read below floor -> no verdict -> no section.
        let ctx = context(for: session(mode: .timed, prompt: shipQuestion, transcript: "Yes we should ship it"))
        #expect(!ctx.contains("PROMPT RELEVANCE"))
    }

    @Test func contextOmitsRelevanceForNonTimedRep() {
        // Same buried pair, but a non-Timed most-recent rep -> the section is
        // gated off (IM relevance is carried by the TONE-DRILL sections).
        let transcript = "Honestly there were a lot of competing priorities pulling at the team. We weighed the tradeoffs at length. In the end I do think we should ship the feature this week."
        let ctx = context(for: session(mode: .suddenDeath, prompt: shipQuestion, transcript: transcript))
        #expect(!ctx.contains("PROMPT RELEVANCE"))
    }

    @Test func promptRelevanceLinesNilBelowFloor() {
        let belowFloor = PracticeEvaluator.promptRelevance(
            prompt: "Why?",
            transcript: Array(repeating: "answer", count: 40).joined(separator: " ")
        )
        #expect(CoachContextBuilder.promptRelevanceLines(for: belowFloor, prompt: "Why?") == nil)
    }

    @Test func promptRelevanceLinesBuriedCarriesAssociationDisclaimer() {
        let lines = CoachContextBuilder.promptRelevanceLines(for: buriedRead, prompt: shipQuestion)
        let joined = (lines ?? []).joined(separator: "\n")
        #expect(lines != nil)
        #expect(joined.contains("never proof the answer was off-topic"))
        #expect(joined.contains("lexical overlap"))
    }

    @Test func oneReadDrivesBothSurfaces() {
        // The decisive coherence contract: the SAME positional read produces a
        // .buried verdict, fires the Timed note, AND yields the buried
        // chat-context guidance — one read, every surface agrees.
        #expect(PracticeEvaluator.promptAnswerVerdict(for: buriedRead) == .buried)
        #expect(note(relevance: buriedRead).leverage.contains(buriedNoteFragment))
        let lines = CoachContextBuilder.promptRelevanceLines(for: buriedRead, prompt: shipQuestion) ?? []
        #expect(lines.joined(separator: "\n").contains("the point arrived late"))
    }
}

// MARK: - Argument-logic + concision-of-meaning reads (slice C2)
//
// Two deterministic PracticeEvaluator read+verdict pairs modelled on the
// promptRelevance/promptAnswerVerdict contract: a read struct, a verdict enum,
// and a nil-below-floor mapping fn. Every fixture is hand-traced against the
// REAL `relevanceContentWords` stop set + `wordCount` tokenizer + the named
// marker bands, so a threshold change breaks a test rather than silently
// shifting a verdict. These cover the DETERMINISTIC seams only (the reads are
// pure — no model output). The two new verdicts are pinned DISTINCT from the
// existing positional `promptAnswerVerdict` (topic relevance) and from
// `StyleSignalSnapshot` length/diversity on the same fixtures.

struct ArgumentLogicTests {

    // MARK: claim -> evidence -> implication

    @Test func fullChainWhenClaimEvidenceAndImplicationPresent() {
        // "the reason is" -> evidence; "which means" -> implication; lead
        // sentence "Remote work boosts output" carries content -> claim.
        // 10 content words clears the >=6 floor.
        let read = PracticeEvaluator.argumentStructure(
            transcript: "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day."
        )
        #expect(read.evidenceFloorMet)
        #expect(read.hasClaim)
        #expect(read.hasEvidence)
        #expect(read.hasImplication)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == .fullChain)
    }

    @Test func assertionOnlyWhenClaimButNoEvidenceOrImplication() {
        // A clear, on-its-own-terms claim with NO justification and NO
        // consequence marker. 11 content words clears the floor.
        let read = PracticeEvaluator.argumentStructure(
            transcript: "Remote work clearly boosts output and keeps the whole team genuinely happier every single day."
        )
        #expect(read.evidenceFloorMet)
        #expect(read.hasClaim)
        #expect(!read.hasEvidence)
        #expect(!read.hasImplication)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == .assertionOnly)
    }

    @Test func claimWithSupportWhenEvidenceOnly() {
        // "because" -> evidence; no implication marker -> claimWithSupport, and
        // read.hasEvidence is the branch flag. ("because" is a stop word for the
        // content-word COUNT but still matches as a discourse marker; 9 other
        // content words clear the floor.)
        let read = PracticeEvaluator.argumentStructure(
            transcript: "We should raise the price because demand keeps climbing well past our current supply levels."
        )
        #expect(read.evidenceFloorMet)
        #expect(read.hasClaim)
        #expect(read.hasEvidence)
        #expect(!read.hasImplication)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == .claimWithSupport)
    }

    @Test func claimWithSupportWhenImplicationOnly() {
        // "which means" -> implication; no evidence marker -> claimWithSupport.
        let read = PracticeEvaluator.argumentStructure(
            transcript: "We should raise the price, which means stronger margins and room to invest properly next year."
        )
        #expect(read.evidenceFloorMet)
        #expect(read.hasClaim)
        #expect(!read.hasEvidence)
        #expect(read.hasImplication)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == .claimWithSupport)
    }

    @Test func nilBelowContentWordFloor() {
        // "Yes, we should." -> yes(<4), we(<4), should(stop) -> 0 content words
        // < 6 -> floor not met -> no verdict (never a confident "no argument").
        let read = PracticeEvaluator.argumentStructure(transcript: "Yes, we should.")
        #expect(!read.evidenceFloorMet)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == nil)
    }

    @Test func floorBoundaryExactlySixContentWordsAsserts() {
        // Exactly 6 content words (alpha tokens, each >=4 chars, none a stop
        // word, none a marker) -> floor met (>=), assertionOnly (no markers).
        // "winter" "spring" "summer" "autumn" "season" "weather" = 6.
        let read = PracticeEvaluator.argumentStructure(
            transcript: "winter spring summer autumn season weather"
        )
        #expect(read.evidenceFloorMet)
        #expect(read.hasClaim)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == .assertionOnly)
        // One fewer content word -> below the floor -> nil.
        let belowFloor = PracticeEvaluator.argumentStructure(
            transcript: "winter spring summer autumn season"
        )
        #expect(!belowFloor.evidenceFloorMet)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: belowFloor) == nil)
    }

    @Test func markersAreWordBoundaryAwareNoFalsePositive() {
        // "single" must NOT match the "since" marker; "contributes" must NOT
        // match a bridge-style "but". Above the floor, no real marker -> the
        // verdict stays assertionOnly (no spurious evidence/implication).
        let read = PracticeEvaluator.argumentStructure(
            transcript: "This single contributes genuinely toward the broader quarterly company performance results overall."
        )
        #expect(read.evidenceFloorMet)
        #expect(!read.hasEvidence)
        #expect(!read.hasImplication)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == .assertionOnly)
    }

    // MARK: distinctness from prompt-relevance (topic) verdict

    private let shipQuestion = "Should we ship the feature this week?"

    @Test func topicallyRelevantButLogicallyUnstructuredDiverges() {
        // On-topic (echoes ship/feature/week in the lead -> .answered) yet a
        // flat assertion with no reason / implication -> .assertionOnly. The two
        // verdicts read DIFFERENT things on the same rep.
        let transcript = "We should ship the feature this week without any further delay or hesitation at all really."
        let relevance = PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
        let argument = PracticeEvaluator.argumentStructure(transcript: transcript)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: relevance) == .answered)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: argument) == .assertionOnly)
    }

    @Test func logicallyStructuredButTopicallyOffDiverges() {
        // A full claim->evidence->implication argument about an UNRELATED topic:
        // argument .fullChain, relevance .partial (point nowhere in the rep).
        let transcript = "Gardening reduces stress because plants demand patience, which means calmer evenings after a long workday."
        let relevance = PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
        let argument = PracticeEvaluator.argumentStructure(transcript: transcript)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: argument) == .fullChain)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: relevance) == .partial)
    }

    // MARK: CoachContextBuilder consumer (cross-surface single source)

    private func session(prompt: String?, transcript: String, mode: PracticeMode = .timed) -> PracticeSession {
        PracticeSession(
            transcript: transcript,
            fillerWordCount: 2,
            duration: 40,
            date: Date(),
            mode: mode,
            score: 6,
            prompt: prompt
        )
    }

    private func context(for session: PracticeSession) -> String {
        CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [session],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
    }

    @Test func contextSurfacesArgumentLogicForTimedRep() {
        let transcript = "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day."
        let ctx = context(for: session(prompt: shipQuestion, transcript: transcript))
        #expect(ctx.contains("ARGUMENT LOGIC"))
        #expect(ctx.contains("claim + reason + implication all present"))
        #expect(ctx.contains("never proof the reasoning is sound"))
    }

    @Test func contextOmitsArgumentLogicBelowFloor() {
        // Thin transcript -> argument read below floor -> no section.
        let ctx = context(for: session(prompt: shipQuestion, transcript: "Yes we should ship it"))
        #expect(!ctx.contains("ARGUMENT LOGIC"))
    }

    @Test func contextOmitsArgumentLogicForNonTimedRep() {
        let transcript = "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day."
        let ctx = context(for: session(prompt: shipQuestion, transcript: transcript, mode: .suddenDeath))
        #expect(!ctx.contains("ARGUMENT LOGIC"))
    }

    @Test func argumentLogicLinesNilBelowFloor() {
        #expect(CoachContextBuilder.argumentLogicLines(transcript: "Yes we should ship it") == nil)
    }

    @Test func argumentLogicLinesAssertionOnlyCarriesAssociationDisclaimer() {
        let lines = CoachContextBuilder.argumentLogicLines(
            transcript: "Remote work clearly boosts output and keeps the whole team genuinely happier every single day."
        )
        let joined = (lines ?? []).joined(separator: "\n")
        #expect(lines != nil)
        #expect(joined.contains("asserted, not argued"))
        #expect(joined.contains("never proof the answer was wrong"))
    }

    @Test func oneArgumentReadDrivesInsightAndContext() {
        // Coherence: the SAME read yields the .fullChain verdict, the Timed
        // insight line, and the chat-context line — one read, surfaces agree.
        let transcript = "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day."
        let read = PracticeEvaluator.argumentStructure(transcript: transcript)
        #expect(PracticeEvaluator.argumentLogicVerdict(for: read) == .fullChain)
        let insights = PracticeEvaluator.timedModeInsightsForTesting(
            fillerCount: 1, duration: 30, wordCount: 16, wordsPerMinute: 130,
            recentSessions: [], transcript: transcript, prompt: shipQuestion
        )
        #expect(insights.contains { $0.contains("the shape of a complete argument") })
        let ctx = context(for: session(prompt: shipQuestion, transcript: transcript))
        #expect(ctx.contains("ARGUMENT LOGIC"))
    }
}

struct ConcisionOfMeaningTests {

    private let shipQuestion = "Should we ship the feature this week?"

    // MARK: content-word density bands

    @Test func denseWhenHighFractionAndNoPromptToJudgeArrival() {
        // 13 tokens, 11 content words -> fraction 0.846 >= 0.50. nil prompt ->
        // arrival unknown -> .dense (front-loaded by default when un-judgeable).
        let transcript = "The decision saves three million dollars annually because automation removes manual review entirely."
        let read = PracticeEvaluator.meaningDensity(
            transcript: transcript,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: transcript)
        )
        #expect(read.evidenceFloorMet)
        #expect(read.totalWords == 13)
        #expect(read.answerArrivedEarly == nil)
        #expect(abs(read.contentWordFraction - 11.0 / 13.0) < 0.0001)
        #expect(read.contentWordFraction >= PracticeEvaluator.meaningDensityHighFraction)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: read) == .dense)
    }

    @Test func paddedWhenLowContentWordFraction() {
        // 19 tokens, 6 content words -> fraction 0.316 < 0.35 -> .padded.
        let transcript = "Well you know I think that maybe we could possibly try to do something about it at some point."
        let read = PracticeEvaluator.meaningDensity(
            transcript: transcript,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: transcript)
        )
        #expect(read.evidenceFloorMet)
        #expect(read.totalWords == 19)
        #expect(abs(read.contentWordFraction - 6.0 / 19.0) < 0.0001)
        #expect(read.contentWordFraction < PracticeEvaluator.meaningDensityLowFraction)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: read) == .padded)
    }

    @Test func measuredWhenMidFraction() {
        // 17 tokens; content words = think, team, probably, need, time, plan,
        // right = 7 (We/that/the/will/a/bit/more/to/get are <4 chars or stop
        // words) -> fraction 7/17 = 0.4118, in [0.35, 0.50) -> .measured
        // (nil prompt -> arrival unknown, so not the late path).
        let transcript = "We think that the team will probably need a bit more time to get the plan right."
        let read = PracticeEvaluator.meaningDensity(
            transcript: transcript,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: transcript)
        )
        #expect(read.evidenceFloorMet)
        #expect(read.totalWords == 17)
        #expect(abs(read.contentWordFraction - 7.0 / 17.0) < 0.0001)
        #expect(read.contentWordFraction >= PracticeEvaluator.meaningDensityLowFraction)
        #expect(read.contentWordFraction < PracticeEvaluator.meaningDensityHighFraction)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: read) == .measured)
    }

    @Test func denseButLateArrivalDowngradesToMeasured() {
        // High fraction (11/16 = 0.6875 >= 0.50) BUT the point arrives late: the
        // lead echoes none of ship/feature/week (lead overlap 0 < weak) while
        // the whole rep echoes all 3. So answerArrivedEarly == false ->
        // .measured (dense-but-late), NOT .dense. This is the one branch where a
        // real prompt changes the verdict vs the nil-prompt path.
        let transcript = "Countless competing priorities dominated every strategic discussion lately. We should ship the feature this week regardless."
        let relevance = PracticeEvaluator.promptRelevance(prompt: shipQuestion, transcript: transcript)
        let read = PracticeEvaluator.meaningDensity(transcript: transcript, relevance: relevance)
        #expect(read.evidenceFloorMet)
        #expect(read.contentWordFraction >= PracticeEvaluator.meaningDensityHighFraction)
        #expect(read.answerArrivedEarly == false)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: read) == .measured)
    }

    @Test func nilBelowTokenFloor() {
        // 6 tokens < minWordsForMeaningDensity (12) -> floor not met -> no
        // verdict (never a confident "padded" on a fragment).
        let transcript = "The plan works well overall here."
        let read = PracticeEvaluator.meaningDensity(
            transcript: transcript,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: transcript)
        )
        #expect(!read.evidenceFloorMet)
        #expect(read.totalWords == 6)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: read) == nil)
    }

    @Test func floorBoundaryExactlyTwelveTokensAsserts() {
        // Exactly 12 tokens -> floor met (>=). Twelve content words -> fraction
        // 1.0 -> .dense (nil prompt). Eleven tokens -> below floor -> nil.
        let twelve = "winter spring summer autumn season weather climate forecast pattern region coastal inland"
        let readTwelve = PracticeEvaluator.meaningDensity(
            transcript: twelve,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: twelve)
        )
        #expect(readTwelve.totalWords == 12)
        #expect(readTwelve.evidenceFloorMet)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: readTwelve) == .dense)

        let eleven = "winter spring summer autumn season weather climate forecast pattern region coastal"
        let readEleven = PracticeEvaluator.meaningDensity(
            transcript: eleven,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: eleven)
        )
        #expect(readEleven.totalWords == 11)
        #expect(!readEleven.evidenceFloorMet)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: readEleven) == nil)
    }

    // MARK: distinctness from raw word count + lexical diversity

    @Test func distinctFromRawWordCountAndUniqueRatio() {
        // Two reps, identical raw length (19 tokens) and similar token diversity,
        // but very different MEANING density -> different verdicts. Proves the
        // metric is not a length or word-count proxy.
        let padded = "Well you know I think that maybe we could possibly try to do something about it at some point."
        let dense = "Quarterly revenue climbed sharply because disciplined spending freed real capital, which then funded three strategic brand new product launches."
        let paddedRead = PracticeEvaluator.meaningDensity(
            transcript: padded,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: padded)
        )
        let denseRead = PracticeEvaluator.meaningDensity(
            transcript: dense,
            relevance: PracticeEvaluator.promptRelevance(prompt: nil, transcript: dense)
        )
        // Same raw length, opposite density verdicts.
        #expect(paddedRead.totalWords == denseRead.totalWords)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: paddedRead) == .padded)
        #expect(PracticeEvaluator.concisionOfMeaningVerdict(for: denseRead) == .dense)
    }

    // MARK: timedModeInsights consumer surfacing

    @Test func insightSurfacesPaddedLineAboveFloorViaTimedInsights() {
        let padded = "Well you know I think that maybe we could possibly try to do something about it at some point."
        let insights = PracticeEvaluator.timedModeInsightsForTesting(
            fillerCount: 1, duration: 30, wordCount: 19, wordsPerMinute: 130,
            recentSessions: [], transcript: padded, prompt: nil
        )
        #expect(insights.contains { $0.contains("carried little of the meaning") })
    }

    @Test func insightOmitsConcisionLineBelowFloor() {
        // 6-token transcript -> density read below floor -> NO concision line in
        // the uncapped insight list (byte-identical to today on a fragment).
        let thin = "The plan works well overall here."
        let insights = PracticeEvaluator.timedModeInsightsForTesting(
            fillerCount: 1, duration: 30, wordCount: 6, wordsPerMinute: 130,
            recentSessions: [], transcript: thin, prompt: nil
        )
        // No concision-of-meaning line in any band: "carried" covers the
        // dense + padded copy, "substance" covers the measured copy.
        #expect(!insights.contains { $0.contains("carried") })
        #expect(!insights.contains { $0.contains("substance") })
    }

    @Test func denseButLateInsightCoachesLeadingWithIt() {
        // The dense-but-late .measured branch emits the "lead with it" copy.
        let transcript = "Countless competing priorities dominated every strategic discussion lately. We should ship the feature this week regardless."
        let insights = PracticeEvaluator.timedModeInsightsForTesting(
            fillerCount: 1, duration: 30, wordCount: 16, wordsPerMinute: 130,
            recentSessions: [], transcript: transcript, prompt: shipQuestion
        )
        #expect(insights.contains { $0.contains("the point took a while to arrive") })
    }
}

// MARK: - Timed insight consumer surfacing (slice C2, full pipeline)
//
// Proves the argument-logic line reaches the REAL `evaluateTimedPractice`
// insights (capped at 3). With empty history the insight order is
// [first-rep, pace, argument], so the fullChain line lands in the cap; below
// the floor it is absent. The uncapped `timedModeInsightsForTesting` suites
// above pin both lines independently of the cap.

struct TimedInsightArgumentConsumerTests {

    @Test func fullPipelineSurfacesArgumentLineWithinPrefixCap() {
        // Fixture A: 16 raw words, .fullChain. duration 20 / wordCount 16 means
        // neither thin gate (wordCount<8 || duration<8) fires, so the order is
        // [first-rep, pace, argument] and the argument line survives prefix(3).
        let eval = PracticeEvaluator.evaluateTimedPractice(
            transcript: "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day.",
            fillerCount: 1,
            duration: 20,
            difficulty: .medium,
            recentSessions: [],
            profile: nil,
            transcriptConfidence: nil,
            question: "What is the case for remote work?"
        )
        #expect(eval.insights.count <= 3)
        #expect(eval.insights.contains { $0.contains("the shape of a complete argument") })
    }

    @Test func fullPipelineScoreUnchangedByNewInsightLines() {
        // The new insight lines are copy only — the numeric score must be
        // identical to a run whose transcript yields no argument/density line
        // (same length, same fillers, same duration). Score reads contentProgress
        // + pace + duration, never the insight builder.
        let withArgument = PracticeEvaluator.evaluateTimedPractice(
            transcript: "Remote work boosts output. The reason is fewer interruptions, which means deeper focus across the day.",
            fillerCount: 1, duration: 20, difficulty: .medium,
            recentSessions: [], profile: nil
        )
        // Same raw word count (16), no markers, no claim-bearing structure.
        let withoutArgument = PracticeEvaluator.evaluateTimedPractice(
            transcript: "word word word word word word word word word word word word word word word word",
            fillerCount: 1, duration: 20, difficulty: .medium,
            recentSessions: [], profile: nil
        )
        #expect(withArgument.score == withoutArgument.score)
    }
}

// MARK: - Goal Progress Tests (M14)
//
// Locks the contract for the profile's goal-progress ring:
//   • Snapshot-window distance computes from raw signal aggregates for all
//     four goals — `.calmerDelivery` reads the per-snapshot
//     `pauseFilledRatio` field and skips zero-pause reps so the loop is
//     closed across every voice without faking a "perfectly calm" read.
//   • measuredDistanceFromGoal returns nil on insufficient baseline data so
//     the UI can render "Early signal" rather than a fake 50%.
//   • Trend compute classifies closer / steady / slipped honestly and
//     returns nil when either window has fewer than 3 qualifying snapshots.

struct GoalProgressTests {

    private func snapshot(
        daysAgo: Int,
        fillerCount: Int,
        duration: TimeInterval,
        score: Int,
        pauseFilledRatio: Double? = nil
    ) -> SkillSnapshot {
        let date = Calendar.current.date(byAdding: .day, value: -daysAgo, to: Date()) ?? Date()
        return SkillSnapshot(
            sessionId: UUID(),
            date: date,
            fillerCount: fillerCount,
            duration: duration,
            wordCount: 120,
            wpm: 130,
            score: score,
            categoryRatings: [:],
            drillCompleted: nil,
            pauseRate: nil,
            pitchMonotone: nil,
            pauseFilledRatio: pauseFilledRatio
        )
    }

    // MARK: distanceFromGoal(in:)

    @Test func snapshotDistanceFillerHitsTargetAtCleanRate() {
        // 6 reps × 60s × 1 filler each = 1.0 filler/min → distance 0.125
        // (well inside "On track" band — proximity ≥ 87%).
        let snaps = (0..<6).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 60, score: 7) }
        guard let d = CommunicationBaseline.distanceFromGoal(.reduceFillers, in: snaps) else {
            #expect(Bool(false), "Expected a measured distance for filler-clean reps.")
            return
        }
        #expect(d < 0.20, "Clean filler reps should sit inside On-track band. Got: \(d)")
    }

    @Test func snapshotDistanceFillerSaturatesAtNoisyRate() {
        // 6 reps × 30s × 8 fillers each = 16/min → clamps to 1.0.
        let snaps = (0..<6).map { snapshot(daysAgo: $0, fillerCount: 8, duration: 30, score: 4) }
        guard let d = CommunicationBaseline.distanceFromGoal(.reduceFillers, in: snaps) else {
            #expect(Bool(false), "Expected a measured distance for filler-heavy reps.")
            return
        }
        #expect(d == 1.0, "16 fillers/min must saturate at 1.0. Got: \(d)")
    }

    @Test func snapshotDistanceConciseTracksDurationMean() {
        // 5 reps averaging 40s → distance = (40-20)/100 = 0.20.
        let snaps = (0..<5).map { snapshot(daysAgo: $0, fillerCount: 0, duration: 40, score: 7) }
        guard let d = CommunicationBaseline.distanceFromGoal(.moreConcise, in: snaps) else {
            #expect(Bool(false), "Expected a measured distance for concise reps.")
            return
        }
        #expect(abs(d - 0.20) < 0.01, "40s mean should map to distance 0.20. Got: \(d)")
    }

    @Test func snapshotDistanceThinkFasterTracksScoreMean() {
        // 5 reps × score 8 → distance = max(0, 1 - 8/7.5) = 0.0.
        let snaps = (0..<5).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 45, score: 8) }
        guard let d = CommunicationBaseline.distanceFromGoal(.thinkFaster, in: snaps) else {
            #expect(Bool(false), "Expected a measured distance for high-score reps.")
            return
        }
        #expect(d == 0.0, "Score-8 mean should pin distance at 0.0. Got: \(d)")
    }

    @Test func snapshotDistanceCalmerDeliveryHiddenWithoutPauseHistory() {
        // Reps without any captured pauses don't contribute a calmness
        // reading — the helper returns nil so the trend chip stays hidden
        // rather than treat zero-pause sessions as "perfectly calm".
        let snaps = (0..<6).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 45, score: 7) }
        let d = CommunicationBaseline.distanceFromGoal(.calmerDelivery, in: snaps)
        #expect(d == nil, "calmerDelivery is unmeasurable without pause history. Got: \(String(describing: d))")
    }

    @Test func snapshotDistanceCalmerDeliveryTracksFilledPauseMean() {
        // 5 reps with mean filledRatio = 0.4 → distance = 0.4 / 0.8 = 0.50.
        let snaps = (0..<5).map { i in
            snapshot(daysAgo: i, fillerCount: 1, duration: 45, score: 7, pauseFilledRatio: 0.4)
        }
        guard let d = CommunicationBaseline.distanceFromGoal(.calmerDelivery, in: snaps) else {
            #expect(Bool(false), "Expected a measured distance once filled-ratio history exists.")
            return
        }
        #expect(abs(d - 0.50) < 0.01, "0.4 filled-ratio mean should map to distance 0.50. Got: \(d)")
    }

    @Test func snapshotDistanceCalmerDeliverySaturatesAtFullyFilled() {
        // Every pause filled with disfluency → mean 1.0 → distance clamps to 1.0.
        let snaps = (0..<4).map { i in
            snapshot(daysAgo: i, fillerCount: 4, duration: 30, score: 4, pauseFilledRatio: 1.0)
        }
        guard let d = CommunicationBaseline.distanceFromGoal(.calmerDelivery, in: snaps) else {
            #expect(Bool(false), "Expected a measured distance for fully-filled pauses.")
            return
        }
        #expect(d == 1.0, "1.0 filled mean must saturate at distance 1.0. Got: \(d)")
    }

    @Test func snapshotDistanceCalmerDeliverySkipsZeroPauseReps() {
        // Mixed history: 2 reps with pauses (good calmness) + 3 zero-pause
        // reps. Only the 2 reps with pause history qualify — that's below
        // the 3-sample minimum, so the helper honestly returns nil.
        var snaps: [SkillSnapshot] = []
        snaps.append(snapshot(daysAgo: 0, fillerCount: 1, duration: 45, score: 7, pauseFilledRatio: 0.1))
        snaps.append(snapshot(daysAgo: 1, fillerCount: 1, duration: 45, score: 7, pauseFilledRatio: 0.15))
        snaps.append(contentsOf: (2..<5).map { i in
            snapshot(daysAgo: i, fillerCount: 1, duration: 45, score: 7, pauseFilledRatio: nil)
        })
        let d = CommunicationBaseline.distanceFromGoal(.calmerDelivery, in: snaps)
        #expect(d == nil, "Need ≥3 reps with non-nil filled ratio to read calmness. Got: \(String(describing: d))")
    }

    @Test func snapshotDistanceBelowMinimumSamplesReturnsNil() {
        // Two snapshots is below the minimum-3 floor.
        let snaps = (0..<2).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 60, score: 7) }
        #expect(CommunicationBaseline.distanceFromGoal(.reduceFillers, in: snaps) == nil)
    }

    // MARK: measuredDistanceFromGoal

    @Test func measuredDistanceHidesWhenConfidenceInsufficient() {
        // .empty baseline → every dimension is .insufficient → measured
        // returns nil for every goal so the ring renders "Early signal"
        // rather than a fake 50% reading.
        let baseline = CommunicationBaseline.empty
        #expect(baseline.measuredDistanceFromGoal(.reduceFillers) == nil)
        #expect(baseline.measuredDistanceFromGoal(.moreConcise) == nil)
        #expect(baseline.measuredDistanceFromGoal(.thinkFaster) == nil)
        #expect(baseline.measuredDistanceFromGoal(.calmerDelivery) == nil)
    }

    @Test func measuredDistanceSurfacesWhenConfidenceClearsThreshold() {
        let baseline = CommunicationBaseline(
            lastUpdated: Date(), sessionCount: 12, qualifyingSessionCount: 12,
            fillerRate: BaselineStat(value: 2.0, sampleCount: 12, confidence: .established, trend: .stable, percentile25: 1.5, percentile75: 2.5),
            pace: .empty, paceVariance: .empty, durationTendency: .empty,
            pauseRate: .empty, pauseFilledRatio: .empty,
            openingStrength: .empty, closingStrength: .empty,
            structureQuality: .empty, answerDepth: .empty, clarity: .empty,
            vocabularyRange: .empty, hedgingRate: .empty,
            averageScore: .empty, clutchWordFrequencies: [:],
            topStrengths: [], persistentBlockers: []
        )
        guard let d = baseline.measuredDistanceFromGoal(.reduceFillers) else {
            #expect(Bool(false), "Expected a measured distance when fillerRate confidence is established.")
            return
        }
        #expect(abs(d - 0.25) < 0.01, "2.0 fillers/min should map to distance 0.25. Got: \(d)")
    }

    // MARK: GoalProgressTrend.compute

    @Test func trendDetectsImprovementWeekOverWeek() {
        // Recent 5 reps: 1 filler/60s → 1/min. Prior 5 reps: 4 fillers/60s →
        // 4/min. Distance drops from 0.5 to 0.125 — clearly "closer".
        let recent = (0..<5).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 60, score: 7) }
        let prior = (5..<10).map { snapshot(daysAgo: $0, fillerCount: 4, duration: 60, score: 5) }
        guard let trend = GoalProgressTrend.compute(goal: .reduceFillers, snapshots: recent + prior) else {
            #expect(Bool(false), "Expected a trend with 5+5 qualifying snapshots.")
            return
        }
        #expect(trend.direction == .closer, "Filler drop should classify as closer. Got: \(trend.direction)")
        #expect(trend.delta < -GoalProgressTrend.steadyThreshold, "Closer trend must have a meaningfully negative delta. Got: \(trend.delta)")
    }

    @Test func trendDetectsSlippageWeekOverWeek() {
        // Recent reps drift longer (concise distance goes up).
        let recent = (0..<5).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 90, score: 7) }
        let prior = (5..<10).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 40, score: 7) }
        guard let trend = GoalProgressTrend.compute(goal: .moreConcise, snapshots: recent + prior) else {
            #expect(Bool(false), "Expected a trend for the slip case.")
            return
        }
        #expect(trend.direction == .slipped, "Longer mean duration must classify as slipped. Got: \(trend.direction)")
    }

    @Test func trendClassifiesSteadyInsideNoiseBand() {
        // Recent and prior windows hold the same filler rate — the chip
        // should not celebrate movement that isn't there.
        let all = (0..<10).map { snapshot(daysAgo: $0, fillerCount: 2, duration: 60, score: 7) }
        guard let trend = GoalProgressTrend.compute(goal: .reduceFillers, snapshots: all) else {
            #expect(Bool(false), "Expected a steady trend on identical windows.")
            return
        }
        #expect(trend.direction == .steady, "Identical windows must classify as steady. Got: \(trend.direction)")
        #expect(abs(trend.delta) < GoalProgressTrend.steadyThreshold)
    }

    @Test func trendReturnsNilWhenPriorWindowIsThin() {
        // 5 recent snapshots but only 2 prior — below the 3-sample floor for
        // the prior window. The chip stays hidden rather than celebrate a
        // delta against a noisy baseline.
        let recent = (0..<5).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 60, score: 7) }
        let prior = (5..<7).map { snapshot(daysAgo: $0, fillerCount: 4, duration: 60, score: 5) }
        let trend = GoalProgressTrend.compute(goal: .reduceFillers, snapshots: recent + prior)
        #expect(trend == nil, "Trend must require ≥3 snapshots in each window. Got: \(String(describing: trend))")
    }

    @Test func trendReturnsNilForCalmerDeliveryWithoutPauseHistory() {
        // Without filled-ratio readings on the snapshots, the trend chip
        // stays hidden so the UI never claims a calmness delta it can't
        // actually compute — restraint over coverage.
        let snaps = (0..<10).map { snapshot(daysAgo: $0, fillerCount: 1, duration: 45, score: 7) }
        let trend = GoalProgressTrend.compute(goal: .calmerDelivery, snapshots: snaps)
        #expect(trend == nil)
    }

    @Test func trendDetectsCalmerDeliveryImprovement() {
        // Recent 5 reps: filled-ratio 0.15 (calm). Prior 5 reps: 0.6 (noisy).
        // Distance drops from 0.75 → 0.1875 → clearly "closer".
        let recent = (0..<5).map { i in
            snapshot(daysAgo: i, fillerCount: 1, duration: 45, score: 7, pauseFilledRatio: 0.15)
        }
        let prior = (5..<10).map { i in
            snapshot(daysAgo: i, fillerCount: 3, duration: 45, score: 5, pauseFilledRatio: 0.6)
        }
        guard let trend = GoalProgressTrend.compute(goal: .calmerDelivery, snapshots: recent + prior) else {
            #expect(Bool(false), "Expected a calmness trend once snapshots carry filled-ratio history.")
            return
        }
        #expect(trend.direction == .closer, "Filled-ratio drop should classify as closer. Got: \(trend.direction)")
        #expect(trend.delta < -GoalProgressTrend.steadyThreshold, "Closer trend must have a meaningfully negative delta. Got: \(trend.delta)")
    }

    @Test func trendChipCopyIsRestraintFriendly() {
        // Quick smoke on the user-facing strings — guards against an
        // accidental "let's" / emoji / exclamation creep that would violate
        // the brand voice rules in the design system.
        let closer = GoalProgressTrend(direction: .closer, delta: -0.1, windowSize: 5)
        let steady = GoalProgressTrend(direction: .steady, delta: 0.0, windowSize: 5)
        let slipped = GoalProgressTrend(direction: .slipped, delta: 0.1, windowSize: 5)
        for chip in [closer, steady, slipped] {
            #expect(!chip.label.isEmpty)
            #expect(!chip.label.contains("!"))
            #expect(!chip.label.lowercased().contains("let's"))
        }
    }
}

// MARK: - Baseline Coach Map

struct BaselineCoachMapTests {

    private func stat(
        _ value: Double,
        samples: Int = 8,
        confidence: BaselineConfidence = .moderate
    ) -> BaselineStat {
        BaselineStat(
            value: value,
            sampleCount: samples,
            confidence: confidence,
            trend: .stable,
            percentile25: value * 0.8,
            percentile75: value * 1.2
        )
    }

    private func baseline(
        sessionCount: Int = 8,
        fillerRate: Double = 2.0,
        confidence: BaselineConfidence = .moderate
    ) -> CommunicationBaseline {
        CommunicationBaseline(
            lastUpdated: Date(),
            sessionCount: sessionCount,
            qualifyingSessionCount: sessionCount,
            fillerRate: stat(fillerRate, samples: sessionCount, confidence: confidence),
            pace: stat(130, samples: sessionCount, confidence: confidence),
            paceVariance: .empty,
            durationTendency: stat(48, samples: sessionCount, confidence: confidence),
            pauseRate: stat(2.0, samples: sessionCount, confidence: confidence),
            pauseFilledRatio: stat(0.25, samples: sessionCount, confidence: confidence),
            openingStrength: .empty,
            closingStrength: .empty,
            structureQuality: stat(2.4, samples: sessionCount, confidence: confidence),
            answerDepth: .empty,
            clarity: stat(2.5, samples: sessionCount, confidence: confidence),
            vocabularyRange: .empty,
            hedgingRate: stat(0.5, samples: sessionCount, confidence: confidence),
            pitchVariation: stat(0.22, samples: sessionCount, confidence: confidence),
            averageScore: stat(7.0, samples: sessionCount, confidence: confidence),
            clutchWordFrequencies: [:],
            topStrengths: [],
            persistentBlockers: []
        )
    }

    private func profile(
        why: String = "Investor Q&A is coming up.",
        vision: String = "Sound calm when the question gets hard."
    ) -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .composed,
            speakingStyleGoal: .executive,
            styleReference: "",
            coachingBrief: "Cut the ums before my point.",
            motivationWhyNow: why,
            successVision: vision,
            chosenStyleGoal: .executive
        )
    }

    @Test func baselineMapShowsFormationProgressWithoutClaimingStability() {
        let map = BaselineCoachMap.make(baseline: baseline(sessionCount: 5, confidence: .moderate), profile: nil)

        #expect(map.statusTitle == "Baseline forming")
        #expect(map.coachHeadline == "Your baseline is taking shape")
        #expect(abs(map.formationProgress - 0.5) < 0.001)
        #expect(map.repsUntilEstablished == 5)
        #expect(map.dimensions.count == BaselineCoachDimension.allCases.count)
        #expect(map.measuredDimensionCount >= 5)
    }

    @Test func baselineMapNamesWeakestMeasuredReadAsCoachPriority() {
        let map = BaselineCoachMap.make(
            baseline: baseline(sessionCount: 12, fillerRate: 6.0, confidence: .established),
            profile: nil
        )

        #expect(map.coachHeadline == "Your baseline is usable")
        #expect(map.weakestMeasuredDimension?.dimension == .fillerControl)
        #expect(map.coachPriorityLine == "Filler control is the clearest gap to work next.")
    }

    @Test func baselineMapPriorityFallsBackToNextEvidenceGap() {
        let map = BaselineCoachMap.make(baseline: .empty, profile: nil)

        #expect(map.measuredDimensionCount == 0)
        #expect(map.nextEvidenceDimension?.dimension == .fillerControl)
        #expect(map.coachPriorityLine == "Filler control still needs more signal.")
        #expect(map.readoutFocusDimension?.dimension == .fillerControl)
        #expect(map.readoutStrengthDimension == nil)
    }

    @Test func baselineDimensionStateLabelsStaySoftAndEvidenceBounded() {
        let emptyMap = BaselineCoachMap.make(baseline: .empty, profile: nil)
        #expect(emptyMap.dimensions.first?.coachStateLabel == "Needs signal")

        let measuredMap = BaselineCoachMap.make(baseline: baseline(fillerRate: 0.5, confidence: .established), profile: nil)
        let fillerRead = measuredMap.dimensions.first { $0.dimension == .fillerControl }
        #expect(fillerRead?.coachStateLabel == "Strong")

        let focusMap = BaselineCoachMap.make(baseline: baseline(fillerRate: 7.0, confidence: .established), profile: nil)
        let focusRead = focusMap.dimensions.first { $0.dimension == .fillerControl }
        #expect(focusRead?.coachStateLabel == "Focus")
    }

    @Test func baselineReadoutPrioritizesWorstGapThenStrongestSignal() {
        let map = BaselineCoachMap.make(
            baseline: baseline(sessionCount: 12, fillerRate: 6.0, confidence: .established),
            profile: nil
        )

        #expect(map.readoutFocusDimension?.dimension == .fillerControl)
        #expect(map.readoutStrengthDimension?.dimension == .paceControl)
        #expect(!map.supportingReadoutDimensions.contains { $0.dimension == .fillerControl })
        #expect(!map.supportingReadoutDimensions.contains { $0.dimension == .paceControl })
        #expect(map.supportingReadoutDimensions.count == BaselineCoachDimension.allCases.count - 2)
    }

    @Test func baselineReadoutOmitsDuplicateStrengthWhenOnlyOneMeasuredDimensionExists() {
        var partial = CommunicationBaseline.empty
        partial.sessionCount = 3
        partial.qualifyingSessionCount = 3
        partial.fillerRate = stat(2.0, samples: 3, confidence: .tentative)

        let map = BaselineCoachMap.make(baseline: partial, profile: nil)

        #expect(map.readoutFocusDimension?.dimension == .fillerControl)
        #expect(map.readoutStrengthDimension == nil)
        #expect(map.supportingReadoutDimensions.count == BaselineCoachDimension.allCases.count - 1)
    }

    @Test func baselineMapGoalGapUsesMeasuredDistanceOnly() {
        let empty = BaselineCoachMap.make(baseline: .empty, profile: profile())
        #expect(empty.goalGap == nil)

        let measured = BaselineCoachMap.make(baseline: baseline(fillerRate: 2.0, confidence: .established), profile: profile())
        guard let gap = measured.goalGap else {
            #expect(Bool(false), "Expected a goal gap when filler rate is measured.")
            return
        }
        #expect(gap.goal == .reduceFillers)
        #expect(abs(gap.proximity - 0.75) < 0.001)
        #expect(gap.currentLabel.contains("2.0 fillers/min"))
        #expect(gap.targetLabel.contains("1.0/min"))
    }

    @Test func baselineMapPreservesSignupMotivation() {
        let map = BaselineCoachMap.make(baseline: baseline(), profile: profile())

        #expect(map.motivationAnchor?.contains("Investor Q&A is coming up.") == true)
        #expect(map.motivationAnchor?.contains("Sound calm when the question gets hard.") == true)
    }

    @Test func signupMemoryContextKeepsExactUserWordsAndRestraintInstruction() {
        let lines = CoachContextBuilder.signupMemoryContextLines(for: profile())
        let joined = lines.joined(separator: "\n")

        #expect(joined.contains("Cut the ums before my point."))
        #expect(joined.contains("Investor Q&A is coming up."))
        #expect(joined.contains("Sound calm when the question gets hard."))
        #expect(joined.contains("do not bring it up every turn"))
        #expect(joined.contains("do not invent an emotion"))
    }

    @Test func userContextContainsDedicatedSignupMemorySection() {
        let ctx = CoachContextBuilder.userContext(
            profile: profile(),
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )

        #expect(ctx.contains("SIGNUP MEMORY"))
        #expect(ctx.contains("Felt stakes / why it mattered then: Investor Q&A is coming up."))
        #expect(ctx.contains("do not invent an emotion"))
    }
}

// MARK: - Voice Alignment (M14: fifth surface in the goal-aware loop)
//
// Tests for the home-recommendation alignment chip. The chip extends the
// pre-rep banner → mid-rep HUD → post-rep Coach Note → profile ring chain
// onto the home `suggestionLink`. The contract:
//
//   • `PracticeMode.primarySkillAreas` is the canonical mode→skill map.
//     Every mode owns 2–3 skills it most directly trains.
//   • `SpeakingStyleGoal.aligns(with mode:)` is true iff the voice's aligned
//     skills overlap with the mode's primary skills.
//   • Each of the 4 modes has ≥1 aligned voice; each of the 6 voices has ≥1
//     aligned mode. Otherwise the chip would orphan a surface.
//   • Some voice→mode pairs do NOT align by design — voices that need space
//     (warm, storytelling) don't align with sudden-death pressure; voices
//     that need composure (executive) don't align with the looser ah-counter.
//
// The chip's copy ("Toward your <voice> voice") reuses `shortVoiceLabel`, so
// the brand-voice smoke covers it via `GoalProgressTests.trendChipCopyIsRestraintFriendly`-
// style guards on the same source string.

struct VoiceAlignmentTests {

    private let allModes: [PracticeMode] = [.timed, .suddenDeath, .ahCounter, .imConversation]

    // MARK: PracticeMode.primarySkillAreas

    @Test func timedTrainsStructureAndAnswerDevelopment() {
        let skills = PracticeMode.timed.primarySkillAreas
        #expect(skills.contains(.structure))
        #expect(skills.contains(.answerDevelopment))
        #expect(skills.contains(.openingStrength))
    }

    @Test func suddenDeathTrainsConfidenceAndFillerControl() {
        let skills = PracticeMode.suddenDeath.primarySkillAreas
        #expect(skills.contains(.confidence))
        #expect(skills.contains(.fillerReduction))
    }

    @Test func ahCounterTrainsFillerAndPaceAndPauseSkills() {
        let skills = PracticeMode.ahCounter.primarySkillAreas
        #expect(skills.contains(.fillerReduction))
        #expect(skills.contains(.paceControl))
        #expect(skills.contains(.pauseUsage))
    }

    @Test func imConversationTrainsEmphasisAndDepth() {
        let skills = PracticeMode.imConversation.primarySkillAreas
        #expect(skills.contains(.vocalEmphasis))
        #expect(skills.contains(.answerDevelopment))
    }

    @Test func primarySkillAreasStayNarrow() {
        // Intentional restraint — broader maps dilute the signal that the
        // home chip reads from. 2–3 skills per mode is the design contract.
        for mode in allModes {
            let count = mode.primarySkillAreas.count
            #expect(count >= 2 && count <= 3, "\(mode) maps to \(count) skills — expected 2–3.")
        }
    }

    // MARK: SpeakingStyleGoal.aligns(with:)

    @Test func conciseVoiceAlignsWithTimedAndAhCounter() {
        // Concise → structure + fillerReduction + conciseSpeaking. Both timed
        // (structure) and ahCounter (fillerReduction) overlap.
        #expect(SpeakingStyleGoal.concise.aligns(with: .timed))
        #expect(SpeakingStyleGoal.concise.aligns(with: .ahCounter))
    }

    @Test func warmVoiceDoesNotAlignWithSuddenDeath() {
        // Warm voice needs space and rhythm — pressure mode cuts both. The
        // chip must stay silent rather than claim a sudden-death rep moves
        // a speaker toward warmth.
        #expect(!SpeakingStyleGoal.warm.aligns(with: .suddenDeath))
    }

    @Test func warmVoiceAlignsWithImConversation() {
        // Warm voice ↔ IM. Live two-way exchange is exactly where vocal
        // emphasis + answer depth land warmly.
        #expect(SpeakingStyleGoal.warm.aligns(with: .imConversation))
    }

    @Test func executiveVoiceDoesNotAlignWithAhCounter() {
        // Executive presence is composed and tight. Ah-counter's loose,
        // free-form delivery isn't a direct lever — the chip stays out of
        // the way on this combination.
        #expect(!SpeakingStyleGoal.executive.aligns(with: .ahCounter))
    }

    @Test func authoritativeAlignsWithSuddenDeath() {
        // Authoritative voice trains confidence — sudden death's primary
        // lesson is composure under pressure.
        #expect(SpeakingStyleGoal.authoritative.aligns(with: .suddenDeath))
    }

    @Test func storytellingDoesNotAlignWithSuddenDeath() {
        // Storytelling needs pauseUsage and vocalEmphasis — both impossible
        // in a mode that ends on the first filler. Silent on this pair.
        #expect(!SpeakingStyleGoal.storytelling.aligns(with: .suddenDeath))
    }

    @Test func persuasiveAlignsWithTimedNotAhCounter() {
        // Persuasive structure (rule-of-three, antithesis) needs the
        // architecture timed mode trains. Ah-counter is too loose to land
        // a persuasive close.
        #expect(SpeakingStyleGoal.persuasive.aligns(with: .timed))
        #expect(!SpeakingStyleGoal.persuasive.aligns(with: .ahCounter))
    }

    // MARK: Coverage invariants

    @Test func everyModeHasAtLeastOneAlignedVoice() {
        // Sanity check — no orphan modes. If a mode mapped to skills no
        // voice cared about, the chip would never fire on that mode and
        // we'd silently lose half the alignment surface.
        for mode in allModes {
            let aligned = SpeakingStyleGoal.allCases.filter { $0.aligns(with: mode) }
            #expect(!aligned.isEmpty, "\(mode) has no aligned voice — orphan mode.")
        }
    }

    @Test func everyVoiceAlignsWithAtLeastOneMode() {
        // The chip should be reachable for every voice goal — otherwise
        // a user who picked, say, .storytelling would never see the
        // alignment chip and the loop would feel incomplete for them.
        for voice in SpeakingStyleGoal.allCases {
            let aligned = allModes.filter { voice.aligns(with: $0) }
            #expect(!aligned.isEmpty, "\(voice) has no aligned mode — chip would never fire.")
        }
    }

    @Test func everyVoiceHasAtLeastOneNonAlignedMode() {
        // Restraint contract: the chip must stay silent some of the time
        // for every voice. If a voice aligned with all 4 modes, the chip
        // would lose its meaning — it'd always be on and stop reading as
        // personalization.
        for voice in SpeakingStyleGoal.allCases {
            let silent = allModes.filter { !voice.aligns(with: $0) }
            #expect(!silent.isEmpty, "\(voice) aligns with every mode — chip would never go silent.")
        }
    }

    // MARK: Copy restraint

    @Test func chipCopyFollowsBrandVoice() {
        // The chip phrase is "Toward your <voice>". Guards against an
        // accidental "let's" / emoji / exclamation creep that would
        // violate the design-system voice rules.
        for voice in SpeakingStyleGoal.allCases {
            let copy = "Toward your \(voice.shortVoiceLabel)"
            #expect(!copy.isEmpty)
            #expect(!copy.contains("!"))
            #expect(!copy.lowercased().contains("let's"))
            #expect(!copy.lowercased().contains("great job"))
        }
    }
}

// MARK: - LookingAheadCard voice alignment (M14: sixth surface in the goal-aware loop)
//
// The post-session "Looking ahead" card mirrors the home recommendation
// tile by surfacing the same `VoiceAlignmentChip` when the user has a
// voice goal AND the recommended next-session mode aligns with it.
//
// Tests below lock the Hint's gating predicate independently of the
// SwiftUI body. The chip's own visual gating (`shouldShow`) is already
// covered by `VoiceAlignmentTests`; these tests pin the contract that
// `LookingAheadCard.Hint` exposes the same gate to its caller — so the
// post-rep surface stays honest in the same three silent paths the home
// surface respects (no profile, no voice goal, off-mode alignment).
//
// Adding the chip to the post-rep card is the closing move on a chain of
// six goal-aware surfaces. The home, banner, HUD, Coach Note momentum,
// profile ring, and Looking Ahead card now all read from the single
// `SpeakingStyleGoal` source of truth.

struct LookingAheadCardVoiceAlignmentTests {

    private func hint(mode: PracticeMode, styleGoal: SpeakingStyleGoal?) -> LookingAheadCard.Hint {
        LookingAheadCard.Hint(
            mode: mode,
            whyMode: "Test mode benefit.",
            whyNow: "Test why now.",
            styleGoal: styleGoal
        )
    }

    @Test func alignedVoiceAndModeShowsChip() {
        // .concise aligns with .timed (concise → structure ∩ timed.primary).
        // The Looking Ahead chip should fire here, same as the home chip.
        let h = hint(mode: .timed, styleGoal: .concise)
        #expect(h.shouldShowVoiceAlignment, "Concise → timed should surface the chip on the post-rep card.")
    }

    @Test func warmVoiceWithImConversationShowsChip() {
        // The warm-voice user is most likely to end up here: finish a Timed
        // rep, see "try IM Conversation next" — the chip should ground that
        // suggestion in the user's chosen voice.
        let h = hint(mode: .imConversation, styleGoal: .warm)
        #expect(h.shouldShowVoiceAlignment)
    }

    @Test func unalignedVoiceAndModeHidesChip() {
        // Warm voice + sudden death is an honest silent case — pressure
        // mode cuts the rhythm warm voice needs. The post-rep card must
        // mirror the home card's restraint here.
        let h = hint(mode: .suddenDeath, styleGoal: .warm)
        #expect(!h.shouldShowVoiceAlignment, "Warm → sudden death must stay silent on the post-rep card too.")
    }

    @Test func nilStyleGoalHidesChip() {
        // Pre-onboarding users (and users who skipped the voice step) pass
        // nil. No personalization should be invented on either surface.
        let h = hint(mode: .timed, styleGoal: nil)
        #expect(!h.shouldShowVoiceAlignment)
    }

    @Test func everyVoiceHasAtLeastOneShowingAndOneSilentPair() {
        // Restraint contract — the chip must fire some of the time and stay
        // silent some of the time for every voice. Same coverage invariant
        // as the home chip; lifted here so a future refactor that breaks
        // this on the post-rep surface fails the test suite independently.
        let allModes: [PracticeMode] = [.timed, .suddenDeath, .ahCounter, .imConversation]
        for voice in SpeakingStyleGoal.allCases {
            let firing = allModes.filter { hint(mode: $0, styleGoal: voice).shouldShowVoiceAlignment }
            let silent = allModes.filter { !hint(mode: $0, styleGoal: voice).shouldShowVoiceAlignment }
            #expect(!firing.isEmpty, "\(voice) never fires the post-rep chip — surface would orphan.")
            #expect(!silent.isEmpty, "\(voice) fires the post-rep chip on every mode — would lose meaning.")
        }
    }

    @Test func hintDefaultsToNilStyleGoalForCallSiteBackCompat() {
        // The legacy initializer (mode/whyMode/whyNow only) must keep
        // working — `styleGoal:` is optional with a nil default. Locks the
        // back-compat contract so older call sites still compile and stay
        // silent on the chip.
        let h = LookingAheadCard.Hint(
            mode: .timed,
            whyMode: "Legacy why mode.",
            whyNow: "Legacy why now."
        )
        #expect(h.styleGoal == nil)
        #expect(!h.shouldShowVoiceAlignment)
    }
}

// MARK: - Goal-aware drill selection (closes the M14 loop)

/// Locks the contract that the user's `SpeakingStyleGoal` biases drill *selection*
/// itself — not just post-session copy. The bias is a small (+10) tiebreaker
/// inside `TrendAnalyzer.primaryFocus`, so urgent off-goal trends still win.
/// This is the seventh and final surface of the goal-aware loop: every other
/// surface (banner, HUD, momentum line, profile ring, home chip, looking-ahead
/// chip) already reads from the goal; this test set verifies the *picker
/// itself* does too.
struct GoalAwareDrillSelectionTests {

    private func warmTrend(level: SkillLevel, direction: TrendDirection = .stable) -> SkillTrend {
        SkillTrend(skillArea: .paceControl,            // warm-aligned
                   direction: direction, confidence: .medium,
                   windowSize: 5, currentLevel: level)
    }

    private func offGoalTrend(_ area: SkillArea,
                              level: SkillLevel,
                              direction: TrendDirection = .stable,
                              confidence: TrendConfidence = .medium) -> SkillTrend {
        SkillTrend(skillArea: area, direction: direction, confidence: confidence,
                   windowSize: 5, currentLevel: level)
    }

    @Test func goalBiasBreaksTieAtDevelopingTier() {
        // Two developing trends, same priority (50). With a warm voice goal,
        // the .paceControl trend (warm-aligned) should beat the .structure
        // trend (off-goal for warm).
        let trends = [
            warmTrend(level: .developing),
            offGoalTrend(.structure, level: .developing),
        ]
        let pick = TrendAnalyzer.primaryFocus(
            trends: trends,
            currentSessionSnapshot: nil,
            recentDrills: [],
            styleGoal: .warm
        )
        #expect(pick == .paceControl,
                "Goal-aligned developing skill should beat off-goal developing skill")
    }

    @Test func goalBiasDoesNotOverrideDecliningHighConfidence() {
        // Declining-high-confidence on off-goal skill (priority 100) should
        // still beat developing on goal-aligned (priority 60 with bonus).
        // Urgency wins over goal alignment.
        let trends = [
            warmTrend(level: .developing),
            offGoalTrend(.fillerReduction, level: .solid,
                         direction: .declining, confidence: .high),
        ]
        let pick = TrendAnalyzer.primaryFocus(
            trends: trends,
            currentSessionSnapshot: nil,
            recentDrills: [],
            styleGoal: .warm
        )
        #expect(pick == .fillerReduction,
                "Declining-high-confidence on off-goal must still beat goal-aligned developing")
    }

    @Test func goalBiasDoesNotOverrideWeakStable() {
        // Weak-stable on off-goal (priority 90) should still beat developing
        // on goal-aligned (priority 60 with bonus). Persistent off-goal
        // problems remain the highest-leverage move.
        let trends = [
            warmTrend(level: .developing),
            offGoalTrend(.structure, level: .weak, direction: .stable),
        ]
        let pick = TrendAnalyzer.primaryFocus(
            trends: trends,
            currentSessionSnapshot: nil,
            recentDrills: [],
            styleGoal: .warm
        )
        #expect(pick == .structure,
                "Weak-stable off-goal must still beat goal-aligned developing")
    }

    @Test func goalBiasDoesNotOverrideNewIssue() {
        // New-issue on off-goal (priority 80) should still beat developing on
        // goal-aligned (priority 60 with bonus). Just-appeared issues get
        // caught early regardless of voice.
        let trends = [
            warmTrend(level: .developing),
            offGoalTrend(.openingStrength, level: .developing, direction: .newIssue),
        ]
        let pick = TrendAnalyzer.primaryFocus(
            trends: trends,
            currentSessionSnapshot: nil,
            recentDrills: [],
            styleGoal: .warm
        )
        #expect(pick == .openingStrength,
                "New-issue off-goal must still beat goal-aligned developing")
    }

    @Test func goalBiasTipsAdjacentTierNearTie() {
        // Solid goal-aligned (priority 20+10=30) should NOT beat developing
        // off-goal (priority 50). Confirms the +10 bonus stays a tiebreaker
        // — it can't promote a solid skill over a developing one. Picker
        // remains weakness-first.
        let trends = [
            warmTrend(level: .solid),
            offGoalTrend(.structure, level: .developing),
        ]
        let pick = TrendAnalyzer.primaryFocus(
            trends: trends,
            currentSessionSnapshot: nil,
            recentDrills: [],
            styleGoal: .warm
        )
        #expect(pick == .structure,
                "Goal bias must not promote a solid aligned skill over a developing off-goal skill")
    }

    @Test func goalBiasIsSilentWhenNoGoalSet() {
        // No styleGoal → behavior is exactly the pre-M14 contract: developing
        // trends tie at 50 and `max` picks the first one found (here, .structure).
        // Locks the no-regression promise.
        let trends = [
            warmTrend(level: .developing),
            offGoalTrend(.structure, level: .developing),
        ]
        let pickWithGoal = TrendAnalyzer.primaryFocus(
            trends: trends, currentSessionSnapshot: nil,
            recentDrills: [], styleGoal: .warm
        )
        let pickWithout = TrendAnalyzer.primaryFocus(
            trends: trends, currentSessionSnapshot: nil,
            recentDrills: [], styleGoal: nil
        )
        #expect(pickWithGoal == .paceControl)
        // Without the goal, the picker is allowed to land on either
        // developing trend — the contract is "no goal-aware promotion",
        // not "stable ordering". We assert it's _one of_ the candidates.
        #expect(pickWithout == .structure || pickWithout == .paceControl)
    }

    @Test func goalDrivesDayOneFallbackWhenNoTrendsOrSignal() {
        // No trends, no session snapshot at all — the function previously
        // returned the generic `.structure`. With a stated voice goal it now
        // returns that voice's canonical most-direct lever. Locks the
        // "day-one user with a stated voice still gets a goal-grounded
        // first drill" contract.
        let cases: [(SpeakingStyleGoal, SkillArea)] = [
            (.authoritative, .confidence),
            (.warm,          .paceControl),
            (.concise,       .conciseSpeaking),
            (.persuasive,    .structure),
            (.executive,     .confidence),
            (.storytelling,  .answerDevelopment),
        ]
        for (voice, expected) in cases {
            let pick = TrendAnalyzer.primaryFocus(
                trends: [], currentSessionSnapshot: nil,
                recentDrills: [], styleGoal: voice
            )
            #expect(pick == expected,
                    "\(voice) should map to \(expected) for day-one users")
        }
    }

    @Test func noGoalFallbackStaysStructureForBackCompat() {
        // No styleGoal AND no trends AND no snapshot → unchanged from the
        // pre-bias contract: `.structure`. Locks the back-compat path so
        // older call sites that never pass `styleGoal` keep behaving exactly
        // as before.
        let pick = TrendAnalyzer.primaryFocus(
            trends: [], currentSessionSnapshot: nil,
            recentDrills: [], styleGoal: nil
        )
        #expect(pick == .structure)
    }

    @Test func decliningWithoutHighConfidenceCanBeBeatenByAlignedWeakStable() {
        // Declining-medium-confidence falls into the "default" 40 bucket
        // (the priority tree only fires the 100 score for high-confidence
        // declines). A weak-stable goal-aligned trend (90+10=100) should
        // beat it. Confirms the picker's tier hierarchy is intact and goal
        // alignment only stacks _within_ a tier or across small gaps.
        let trends = [
            warmTrend(level: .weak, direction: .stable),
            offGoalTrend(.structure, level: .solid,
                         direction: .declining, confidence: .medium),
        ]
        let pick = TrendAnalyzer.primaryFocus(
            trends: trends, currentSessionSnapshot: nil,
            recentDrills: [], styleGoal: .warm
        )
        #expect(pick == .paceControl)
    }

    @Test func primaryAlignedSkillAreaIsDeterministic() {
        // `alignedSkillAreas` is a `Set` and can't carry order; the picker
        // relies on `primaryAlignedSkillArea` for a deterministic
        // day-one default. Lock the mapping so a refactor that drops it
        // (or shuffles the switch order) fails this test rather than
        // quietly randomising day-one drills.
        #expect(SpeakingStyleGoal.authoritative.primaryAlignedSkillArea == .confidence)
        #expect(SpeakingStyleGoal.warm.primaryAlignedSkillArea          == .paceControl)
        #expect(SpeakingStyleGoal.concise.primaryAlignedSkillArea       == .conciseSpeaking)
        #expect(SpeakingStyleGoal.persuasive.primaryAlignedSkillArea    == .structure)
        #expect(SpeakingStyleGoal.executive.primaryAlignedSkillArea     == .confidence)
        #expect(SpeakingStyleGoal.storytelling.primaryAlignedSkillArea  == .answerDevelopment)

        // Every voice's primary lever must also be in its `alignedSkillAreas`
        // — keeps the deterministic accessor consistent with the set-based one.
        for voice in SpeakingStyleGoal.allCases {
            #expect(voice.alignedSkillAreas.contains(voice.primaryAlignedSkillArea),
                    "\(voice).primaryAlignedSkillArea must be in alignedSkillAreas")
        }
    }
}

// MARK: - Peak glow (Home post-session demotion)
//
// `RatingStore.pendingPeakGlow` is the gate that decides whether the
// Personal Best purple hero shows on Home as a post-rep glow. The
// invariants below come straight from the brand rules:
//   - Only fire on UPWARD movement (never punish-shame regression).
//   - Only fire when the new peak strictly exceeds the last value
//     the Home glow has already consumed.
//   - `markPeakGlowConsumed()` must clear the flag exactly once.
@MainActor
struct PeakGlowGatingTests {

    @Test func markPeakGlowConsumedClearsFlag() {
        // The simplest invariant: `markPeakGlowConsumed()` flips the
        // flag to false regardless of prior state. The upward-fire
        // case relies on per-account UserDefaults cursor state that's
        // shared across the test process; covering it here would
        // require keychain + UserDefaults isolation. The no-fire cases
        // below (flat + downward) cover the "must not punish-shame"
        // brand rule directly; combined with `markPeakGlowConsumed`
        // clearing the flag, the upward path is exercised in QA / the
        // detailed screenshot tour rather than as a unit test.
        let store = RatingStore.shared
        store.markPeakGlowConsumed()
        #expect(!store.pendingPeakGlow,
                "markPeakGlowConsumed must clear pendingPeakGlow.")
    }

    @Test func flatPeakSilenceGlow() {
        #expect(!RatingStore.shouldRaisePeakGlow(
            hasRatedEvidence: true,
            weekPeakRating: 700,
            lastShownPeak: 700
        ),
                "Flat peak (no movement) must not raise glow.")
    }

    @Test func downwardPeakSilenceGlow() {
        // Brand rule from `never_punish_shame.md`: drops are silent.
        // Even if `weekPeakRating` somehow decreased (week boundary
        // reset, etc.), the glow must not fire.
        #expect(!RatingStore.shouldRaisePeakGlow(
            hasRatedEvidence: true,
            weekPeakRating: 650,
            lastShownPeak: 700
        ),
                "Downward peak must never raise glow — no punish-shame on regression.")
    }

    @Test func initialRatingSilencesPeakGlow() {
        #expect(!RatingStore.shouldRaisePeakGlow(
            hasRatedEvidence: false,
            weekPeakRating: 400,
            lastShownPeak: 0
        ),
                "The default 400 starting line must not trigger a personal-best glow.")
    }

    @Test func homePeakGlowCopyAvoidsOverclaimAndAmbiguousDeltaAtAllTimeMark() {
        let presentation = HomePeakGlowPresentation.make(
            weekPeak: 740,
            current: 740,
            allTime: 740
        )
        let combined = ([presentation.headline, presentation.body] + presentation.stats.flatMap { [$0.value, $0.label] })
            .joined(separator: " ")

        #expect(presentation.headline == "You moved your rating mark.")
        #expect(presentation.stats == [.init(value: "740", label: "This week's peak")])
        #expect(!combined.localizedCaseInsensitiveContains("highest rating"))
        #expect(!combined.localizedCaseInsensitiveContains("new high"))
        #expect(!combined.localizedCaseInsensitiveContains("+0"))
        #expect(!combined.localizedCaseInsensitiveContains("vs all-time"))
        #expect(!combined.localizedCaseInsensitiveContains("to all-time"))
    }

    @Test func homePeakGlowCopyUsesSinglePlainAllTimeGapWhenBelowAllTime() {
        let presentation = HomePeakGlowPresentation.make(
            weekPeak: 728,
            current: 728,
            allTime: 740
        )

        #expect(presentation.headline == "You raised this week's rating mark.")
        #expect(presentation.body == "728 is this week's best. All-time is 740.")
        #expect(presentation.stats == [
            .init(value: "728", label: "This week's peak"),
            .init(value: "12", label: "off all-time")
        ])
    }
}

struct BelievableProgressZeroDataTests {

    @Test func initialRatingHasNoRatedEvidence() {
        #expect(!SpeakingRating.initial.hasRatedEvidence)
        #expect(!PeakRatingWallCard.shouldRender(for: .initial))
    }

    @Test func ratedSessionCreatesRatedEvidence() {
        let rated = RatingEngine.processRatedSession(
            rating: .initial,
            sessionScore: 8,
            sessionId: UUID(),
            pressureLevel: .elevated
        )

        #expect(rated.hasRatedEvidence)
        #expect(PeakRatingWallCard.shouldRender(for: rated))
    }

    @Test func leagueCopyDoesNotAssignTierBeforeRatedEvidence() {
        let title = LeaguePlacementPresentation.title(tier: .silver, rating: .initial)
        let subtitle = LeaguePlacementPresentation.subtitle(tier: .silver, rating: .initial)
        let fullSubtitle = LeaguePlacementPresentation.fullScreenSubtitle(tier: .silver, rating: .initial)

        #expect(title == "Peer comparison pending")
        #expect(subtitle.contains("One rated rep"))
        #expect(fullSubtitle.contains("Complete one rated rep"))
        #expect(!title.contains("Silver"))
        #expect(!subtitle.contains("Gold"))
        #expect(LeaguePlacementPresentation.ratingValue(for: .initial) == "—")
    }

    @Test func leagueBucketStaysEmptyBeforeRatedEvidence() {
        let key = LeagueManager.bucketKey(
            for: .silver,
            rating: .initial,
            on: Date(timeIntervalSince1970: 1_780_000_000)
        )

        #expect(key.isEmpty)
    }

    @Test func leagueCopyUsesTierAfterRatedEvidence() {
        let rated = RatingEngine.processRatedSession(
            rating: .initial,
            sessionScore: 8,
            sessionId: UUID(),
            pressureLevel: .elevated
        )

        let tier = LeagueTier.tier(for: rated.overall)
        let title = LeaguePlacementPresentation.title(tier: tier, rating: rated)
        let subtitle = LeaguePlacementPresentation.subtitle(tier: tier, rating: rated)

        #expect(title.contains(tier.title))
        #expect(subtitle.contains("rating"))
        #expect(LeaguePlacementPresentation.ratingValue(for: rated) == "\(rated.overall)")
        #expect(!LeagueManager.bucketKey(
            for: tier,
            rating: rated,
            on: Date(timeIntervalSince1970: 1_780_000_000)
        ).isEmpty)
    }

    @Test func friendLeaderboardSelfRowDoesNotInventDefaultRating() {
        #expect(FriendLeaderboardSelfRowPresentation.ratingValue(for: .initial) == nil)
    }

    @Test func friendLeaderboardSelfRowUsesRatingAfterRatedEvidence() {
        let rated = RatingEngine.processRatedSession(
            rating: .initial,
            sessionScore: 8,
            sessionId: UUID(),
            pressureLevel: .elevated
        )

        #expect(FriendLeaderboardSelfRowPresentation.ratingValue(for: rated) == rated.overall)
    }

    @Test func leagueWeeklyActivityShowsRepsBeforeDailyClaims() {
        #expect(LeagueActivityPresentation.weeklyActivityValue(sessionCount: 2, dailyChallengeClaims: 3) == "2 reps")
        #expect(LeagueActivityPresentation.weeklyActivityValue(sessionCount: 1, dailyChallengeClaims: 0) == "1 rep")
    }

    @Test func leagueWeeklyActivityCanShowDailyPresenceWithoutReps() {
        #expect(LeagueActivityPresentation.weeklyActivityValue(sessionCount: 0, dailyChallengeClaims: 1) == "1 daily")
        #expect(LeagueActivityPresentation.weeklyActivityValue(sessionCount: 0, dailyChallengeClaims: 2) == "2 dailies")
        #expect(LeagueActivityPresentation.weeklyActivityValue(sessionCount: 0, dailyChallengeClaims: 0) == "—")
    }

    @Test func leagueWeeklySessionCountUsesCurrentISOWeek() {
        var calendar = Calendar(identifier: .iso8601)
        calendar.firstWeekday = 2
        let now = Date(timeIntervalSince1970: 1_782_950_400) // 2026-06-28 00:00:00 UTC
        let currentWeek = calendar.date(byAdding: .day, value: -1, to: now)!
        let previousWeek = calendar.date(byAdding: .day, value: -7, to: now)!
        let sessions = [
            makePracticeSession(date: currentWeek),
            makePracticeSession(date: previousWeek)
        ]

        #expect(LeagueActivityPresentation.weeklySessionCount(from: sessions, now: now, calendar: calendar) == 1)
    }
}

struct ProfileCollapseContractTests {

    private func makeProfile(
        effectiveVoice: SpeakingStyleGoal = .warm,
        chosenVoice: SpeakingStyleGoal? = nil
    ) -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: effectiveVoice,
            styleReference: "",
            coachingBrief: "Brief.",
            motivationWhyNow: "",
            successVision: "",
            chosenStyleGoal: chosenVoice
        )
    }

