        #expect(display == "Stop after the recommendation.")
        #expect(!display.lowercased().contains("coach read"))
        #expect(!display.lowercased().contains("move:"))
    }

    @Test func liveLandingTextDropsScreenshotScaffoldAndCollapsesLines() {
