    @Test func spokenTextDropsSameLineScaffoldLabels() {
        let spoken = CoachReplyTextSanitizer.spokenText(
            from: "Read: your close is rushed. Move: stop after the recommendation. Why: it tests control."
        )

        #expect(spoken == "Your close is rushed. Stop after the recommendation. It tests control.")
        #expect(!spoken.lowercased().contains("read:"))
        #expect(!spoken.lowercased().contains("move:"))
        #expect(!spoken.lowercased().contains("why:"))
    }

    @Test func spokenTextDropsTargetAndNextRepLabelsBeforeTTS() {
        let raw = """
        **Fair.** I’ll keep it direct.
        - **Target:** answer first, proof second.
        - **Next rep:** 30-second update, so the recommendation lands before the explanation: recommendation, one proof point, stop.
        """
        let spoken = CoachReplyTextSanitizer.spokenText(from: raw)

        #expect(spoken == "Fair. I’ll keep it direct. Answer first, proof second. 30-second update, so the recommendation lands before the explanation: recommendation, one proof point, stop.")
        #expect(!spoken.lowercased().contains("target:"))
        #expect(!spoken.lowercased().contains("next rep:"))
        #expect(!spoken.contains("**"))
    }

    @Test func spokenTextDropsEmojiAndDecorativeSymbolsBeforeTTS() {
        let raw = "Read: fair push 🎯. Move: one clean close, then stop ✅"
        let display = CoachReplyTextSanitizer.displayText(from: raw)
        let spoken = CoachReplyTextSanitizer.spokenText(from: raw)

        #expect(display.contains("🎯"))
        #expect(display.contains("✅"))
        #expect(spoken == "Fair push. One clean close, then stop")
        #expect(!spoken.contains("🎯"))
        #expect(!spoken.contains("✅"))
        #expect(!spoken.lowercased().contains("move:"))
    }

    @Test func reportVoiceStripKeepsCoachingMoveAfterFillerBridge() {
        let cleaned = CoachReplyTextSanitizer.strippingReportVoiceResidue(
            from: "Fair push: the symbols broke trust. Your last rep had 4 fillers, so for the next rep, state the recommendation first, give one proof, then stop."
        )
        let lower = cleaned.lowercased()

        #expect(!lower.contains("4 fillers"))
        #expect(!lower.contains("had for"))
        #expect(cleaned.contains("For the next rep, state the recommendation first"))
    }

    @Test func reportVoiceStripPreservesGrammarForFillerComparisons() {
        let cleaned = CoachReplyTextSanitizer.strippingReportVoiceResidue(
            from: "For a persuasive pitch, that softens the one line the whole thing turns on, more than your 7 fillers do."
        )
        let lower = cleaned.lowercased()

        #expect(!lower.contains("7 fillers"))
        #expect(!lower.contains("your do"))
        #expect(cleaned.contains("more than the filler words do"))
    }

    @Test func finalizedCoachReplyStripsCompactMetricClusterFromNonMetricTurn() {
        let cleaned = AICoachChatService.finalizedCoachReply(
            from: "The opening is the next lever. The signal I can use is Pressure Drill, 1/10, 0 fillers, 0s. Try this next: end the next rep on the exact ask.",
            latestUserTurn: "Give me one direct move for my next update.",
            turnDepth: .quickMove
        )
        let lower = cleaned.lowercased()

        #expect(!lower.contains("1/10"))
        #expect(!lower.contains("0 fillers"))
        #expect(!lower.contains("0s"))
        #expect(!cleaned.contains("The signal I can use is Pressure Drill."))
        #expect(cleaned.contains("Try this next"))
    }

    @Test func finalizedCoachReplyStripsModeOnlyEvidenceSentence() {
        let cleaned = AICoachChatService.finalizedCoachReply(
            from: "Pacing is the next lever: add one deliberate beat before the reason, then judge the same answer. The signal I can use is Timed. Try this next: use one silent beat after the verdict.",
            latestUserTurn: "Is it the pause or the close?",
            turnDepth: .quickMove
        )

        #expect(!cleaned.contains("The signal I can use is Timed."))
        #expect(!cleaned.contains(".."))
        #expect(cleaned.contains("Pacing is the next lever"))
        #expect(cleaned.contains("Try this next"))
    }

    @Test func finalizedCoachReplyKeepsRequestedMetrics() {
        let reply = "The signal I can use is Pressure Drill, 1/10, 0 fillers, 0s."
        let cleaned = AICoachChatService.finalizedCoachReply(
            from: reply,
            latestUserTurn: "What were the exact metrics?",
            turnDepth: .quickMove
        )

        #expect(cleaned == reply)
    }
}

