        #expect(!AskNoumStore.hasCompletedPracticeEvidence(sessionCount: -1))
        #expect(!AskNoumStore.hasCompletedPracticeEvidence(sessionCount: 0))
        #expect(AskNoumStore.hasCompletedPracticeEvidence(sessionCount: 1))
