struct RecommendationBiasContextBuilderTests {

    @Test func sharedContextKeepsHomeCoachAndPickerRecommendationsInLockstep() {
        let profile = sampleProfile()
        let sessions = [
            session(mode: .timed, fillers: 2, duration: 60, score: 7, transcript: "Here is the point and the next step for the team."),
            session(mode: .ahCounter, fillers: 5, duration: 45, score: 5, transcript: "Um I think maybe the update is basically still moving."),
            session(mode: .timed, fillers: 1, duration: 70, score: 8, transcript: "The decision is clear and the reason is simple.")
        ]

        let home = RecommendationBiasContextBuilder.context(
            profile: profile,
            sessions: sessions,
            sessionStreak: 2,
            daysSinceLastSession: 0,
            coachMemory: nil,
            imAvailable: false,
            summaryStyle: .detailed
        )
        let picker = RecommendationBiasContextBuilder.context(
            profile: profile,
            sessions: sessions,
            sessionStreak: 2,
            daysSinceLastSession: 0,
            coachMemory: nil,
            imAvailable: false,
            summaryStyle: .compact
        )

        #expect(home.blueprint.recommendedMode == picker.blueprint.recommendedMode)
        #expect(home.blueprint.focus == picker.blueprint.focus)
        #expect(home.blueprint.target == picker.blueprint.target)
        #expect(home.blueprint.suggestedTimedDifficulty == picker.blueprint.suggestedTimedDifficulty)
        #expect(home.input.recentSessionSummary.contains("Session 1"))
        #expect(picker.input.recentSessionSummary.contains(PracticeMode.timed.displayLabel))
    }

    @Test func aiPromptBiasesCanReuseTheDeterministicBlueprint() {
        let profile = sampleProfile()
        let sessions = [
            session(mode: .timed, fillers: 0, duration: 65, score: 8, transcript: "The priority is clear and the outcome is measurable.")
        ]
        let context = RecommendationBiasContextBuilder.context(
            profile: profile,
            sessions: sessions,
            sessionStreak: 1,
            daysSinceLastSession: 0,
            coachMemory: nil,
            imAvailable: false
        )

        let aiInput = RecommendationBiasContextBuilder.input(
            profile: profile,
            sessions: sessions,
            plan: context.plan,
            sessionStreak: 1,
            daysSinceLastSession: 0,
            preferredModeBias: context.blueprint.recommendedMode.rawValue,
            preferredToneBias: context.blueprint.recommendedTone?.rawValue ?? "",
            preferredScenarioBias: context.blueprint.recommendedScenario?.rawValue ?? "",
            modeBenefitBias: context.blueprint.modeBenefit
        )

        #expect(aiInput.preferredModeBias == context.blueprint.recommendedMode.rawValue)
        #expect(aiInput.modeBenefitBias == context.blueprint.modeBenefit)
        #expect(aiInput.strongestMode == context.plan?.strongestMode)
    }

    @Test func emptyOrThinLedgerKeepsGoalBiasedMode() {
        let profile = sampleProfile()
        let input = RecommendationBiasContextBuilder.input(
            profile: profile,
            sessions: [],
            plan: nil,
            sessionStreak: 0,
            daysSinceLastSession: 0
        )

        let empty = RecommendationBiasEngine.blueprint(
            profile: profile,
            input: input,
            plan: nil,
            recommendationOutcomes: []
        )
        #expect(empty.recommendedMode == .timed)
        #expect(empty.source == .goalBias)

        let thin = RecommendationBiasEngine.blueprint(
            profile: profile,
            input: input,
            plan: nil,
            recommendationOutcomes: unfavorableLedger(mode: .timed, count: 3)
        )
        #expect(thin.recommendedMode == .timed)
        #expect(thin.source == .goalBias)
        #expect(!thin.whyNow.contains("trended down alongside"))
    }

    @Test func confidentReplaceBiasesGoalModeToNextCandidate() {
        let profile = sampleProfile()
        let input = RecommendationBiasContextBuilder.input(
            profile: profile,
            sessions: [],
            plan: nil,
            sessionStreak: 0,
            daysSinceLastSession: 0
        )

        let adapted = RecommendationBiasEngine.blueprint(
            profile: profile,
            input: input,
            plan: nil,
            recommendationOutcomes: unfavorableLedger(mode: .timed, count: 6)
        )

        #expect(RecommendationAdaptationAnalyzer.confidentlyReplaces(
            mode: .timed,
            in: unfavorableLedger(mode: .timed, count: 6)
        ))
        #expect(adapted.recommendedMode == .imConversation)
        #expect(adapted.source == .adaptationBias)
        #expect(adapted.recommendedScenario == .workUpdate)
        #expect(adapted.recommendedTone == .professional)
        #expect(adapted.whyNow.contains("trended down alongside"))
        #expect(adapted.whyNow.contains(PracticeMode.timed.displayLabel))
        #expect(adapted.whyNow.contains(PracticeMode.imConversation.displayLabel))
    }

    @Test func contextBuilderThreadsRecommendationOutcomesIntoBlueprint() {
        let adapted = RecommendationBiasContextBuilder.context(
            profile: sampleProfile(),
            sessions: [],
            sessionStreak: 0,
            daysSinceLastSession: 0,
            coachMemory: nil,
            imAvailable: false,
            recommendationOutcomes: unfavorableLedger(mode: .timed, count: 6),
            summaryStyle: .compact
        )

        #expect(adapted.blueprint.recommendedMode == .imConversation)
        #expect(adapted.blueprint.whyNow.contains("trended down alongside"))
    }

    private func sampleProfile() -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .moreConcise,
            confidenceLevel: .inconsistent,
            biggestChallenge: .rambling,
            desiredOutcome: .concise,
            speakingStyleGoal: .executive,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: "",
            chosenStyleGoal: .executive
        )
    }

    private func session(
        mode: PracticeMode,
        fillers: Int,
        duration: TimeInterval,
        score: Int?,
        transcript: String
    ) -> PracticeSession {
        var session = PracticeSession(
            transcript: transcript,
            fillerWordCount: fillers,
            duration: duration,
            date: Date()
        )
        session.mode = mode
        session.score = score
        return session
    }

    private func unfavorableLedger(mode: PracticeMode, count: Int) -> [RecommendationOutcome] {
        (0..<count).map { i in
            RecommendationOutcome(
                id: UUID(),
                fingerprint: "\(mode.rawValue)|structured-delivery",
                title: "\(mode.displayLabel) Practice",
                focus: "Structured delivery",
                target: "One complete rep",
                mode: mode,
                sessionID: UUID(),
                followed: true,
                completedAt: Date(timeIntervalSince1970: 1_000 + Double(i)),
                scoreDelta: -0.9,
                hasComparableScore: true,
                fillerDelta: 0,
                durationDelta: 0,
                comparisonSessionCount: 3
            )
        }
    }
}

