// MARK: - M19 Derived Confidence

@Suite("DerivedConfidenceTests")
struct DerivedConfidenceTests {

    private func makeBaselineWith(averageScore: Double) -> CommunicationBaseline {
        var b = CommunicationBaseline.empty
        b.averageScore = BaselineStat(
            value: averageScore,
            sampleCount: 12,
            confidence: .tentative,
            trend: .stable,
            percentile25: averageScore - 1,
            percentile75: averageScore + 1
        )
        return b
    }

    @Test func highAverageScoreYieldsConfident() {
        let b = makeBaselineWith(averageScore: 8.0)
        let label = CoachContextBuilder.derivedConfidenceLabel(baseline: b, sessions: [])
        #expect(label == "confident")
    }

    @Test func lowAverageScoreYieldsRebuilding() {
        let b = makeBaselineWith(averageScore: 4.5)
        let label = CoachContextBuilder.derivedConfidenceLabel(baseline: b, sessions: [])
        #expect(label == "rebuilding")
    }

    @Test func midRangeYieldsDeveloping() {
        let b = makeBaselineWith(averageScore: 6.5)
        let label = CoachContextBuilder.derivedConfidenceLabel(baseline: b, sessions: [])
        #expect(label == "developing")
    }

    @Test func fallsBackToSessionScoresWhenBaselineInsufficient() {
        let b = CommunicationBaseline.empty  // averageScore confidence = .insufficient
        let sessions: [PracticeSession] = (0..<10).map { _ in
            PracticeSession(
                transcript: "test",
                fillerWordCount: 2,
                duration: 60,
                date: Date(),
                score: 9
            )
        }
        let label = CoachContextBuilder.derivedConfidenceLabel(baseline: b, sessions: sessions)
        #expect(label == "confident")
    }

    @Test func rebuildingFromSessionScoresWhenLow() {
        let b = CommunicationBaseline.empty
        let sessions: [PracticeSession] = (0..<5).map { _ in
            PracticeSession(
                transcript: "test",
                fillerWordCount: 5,
                duration: 60,
                date: Date(),
                score: 4
            )
        }
        let label = CoachContextBuilder.derivedConfidenceLabel(baseline: b, sessions: sessions)
        #expect(label == "rebuilding")
    }
}

// MARK: - M19 Primary Focus Memory

@Suite("PrimaryFocusMemoryTests")
struct PrimaryFocusMemoryTests {

    private let testAccountID = "test-focus-memory-\(UUID().uuidString)"

    @Test func persistAndRetrieve() {
        PrimaryFocusMemory.save(.fillerReduction, for: testAccountID)
        let retrieved = PrimaryFocusMemory.lastFocus(for: testAccountID)
        #expect(retrieved == .fillerReduction)
    }

    @Test func detectShiftReturnNilOnFirstRun() {
        let freshID = "fresh-\(UUID().uuidString)"
        let shift = PrimaryFocusMemory.detectShift(current: .paceControl, accountID: freshID)
        #expect(shift == nil)
    }

    @Test func detectShiftReturnEventWhenChanged() {
        let id = "shift-test-\(UUID().uuidString)"
        PrimaryFocusMemory.save(.fillerReduction, for: id)
        let shift = PrimaryFocusMemory.detectShift(current: .paceControl, accountID: id)
        #expect(shift != nil)
        #expect(shift?.from == .fillerReduction)
        #expect(shift?.to == .paceControl)
    }

    @Test func detectShiftReturnNilWhenUnchanged() {
        let id = "noshift-\(UUID().uuidString)"
        PrimaryFocusMemory.save(.paceControl, for: id)
        let shift = PrimaryFocusMemory.detectShift(current: .paceControl, accountID: id)
        #expect(shift == nil)
    }

    @Test func detectShiftPersistsNewValueAfterDetection() {
        let id = "persist-after-\(UUID().uuidString)"
        PrimaryFocusMemory.save(.fillerReduction, for: id)
        _ = PrimaryFocusMemory.detectShift(current: .paceControl, accountID: id)
        let stored = PrimaryFocusMemory.lastFocus(for: id)
        #expect(stored == .paceControl)
    }
}

@Suite("RecommendationResponseAnalyzerTests")
struct RecommendationResponseAnalyzerTests {

    @Test func ignoresRecommendationsTheUserDidNotFollow() {
        let summaries = RecommendationResponseAnalyzer.summarize(outcomes: [
            outcome(mode: .timed, followed: false, scoreDelta: -2, hasComparableScore: true, fillerDelta: 3)
        ])

        #expect(summaries.isEmpty)
        #expect(RecommendationResponseAnalyzer.promptLines(from: []).isEmpty)
    }

    @Test func oneFollowedRepIsTentativeAndUnmeasuredScoreIsNotQuoted() {
        let lines = RecommendationResponseAnalyzer.promptLines(from: [
            outcome(mode: .timed, focus: "clearer close", scoreDelta: 0, hasComparableScore: false, fillerDelta: -2)
        ])

        #expect(lines.count == 1)
        #expect(lines[0].contains("Timed Practice for clearer close"))
        #expect(!lines[0].contains("score"))
        #expect(lines[0].contains("filler rate -2.0/min"))
        #expect(lines[0].contains("one observation only; treat it as tentative"))
    }

    @Test func repeatedMeasuredImprovementShowsPromise() {
        let summaries = RecommendationResponseAnalyzer.summarize(outcomes: [
            outcome(mode: .ahCounter, scoreDelta: 1, hasComparableScore: true, fillerDelta: -2),
            outcome(mode: .ahCounter, scoreDelta: 0.5, hasComparableScore: true, fillerDelta: -1)
        ])

        #expect(summaries.first?.assessment == .promising)
        #expect(summaries.first?.averageScoreDelta == nil)
        #expect(summaries.first?.averageFillerRateDelta == -1.5)
    }

    @Test func repeatedRegressionAsksCoachToAdapt() {
        let lines = RecommendationResponseAnalyzer.promptLines(from: [
            outcome(mode: .suddenDeath, scoreDelta: -1, hasComparableScore: true, fillerDelta: 2),
            outcome(mode: .suddenDeath, scoreDelta: -2, hasComparableScore: true, fillerDelta: 1)
        ])

        #expect(lines[0].contains("score -1.5"))
        #expect(lines[0].contains("filler rate +1.5/min"))
        #expect(lines[0].contains("adapt before repeating it"))
    }

    @Test func legacyOutcomeMetricsFailClosedWithoutComparisonProvenance() {
        let legacy = RecommendationOutcome(
            id: UUID(), fingerprint: "legacy", title: "Old prescription",
            focus: "clearer close", target: nil, mode: .timed,
            sessionID: UUID(), followed: true, completedAt: Date(),
            scoreDelta: 3, hasComparableScore: true, fillerDelta: -4,
            durationDelta: 20, wordsPerMinute: 150, paceDelta: -30,
            goal: .concise, targetDimensionID: "clean_close",
            goalFollowUpResult: .earlyImprovement
        )

        let summary = RecommendationResponseAnalyzer.summarize(outcomes: [legacy]).first
        #expect(summary?.measuredCount == 0)
        #expect(summary?.averageScoreDelta == nil)
        #expect(summary?.averageFillerRateDelta == nil)
        #expect(summary?.assessment == .forming)
        let lines = RecommendationResponseAnalyzer.promptLines(from: [legacy])
        #expect(lines.count == 1)
        #expect(lines[0].contains("no comparable metric yet"))
        #expect(!lines[0].contains("Goal follow-up"))
    }

    @Test func newOptionalEvidenceFieldsDecodeOlderOutcomeRecords() throws {
        struct LegacyOutcome: Codable {
            let id: UUID
            let fingerprint: String
            let title: String
            let mode: PracticeMode
            let sessionID: UUID
            let followed: Bool
            let completedAt: Date
            let scoreDelta: Double
            let fillerDelta: Double
            let durationDelta: Double
        }
        let legacy = LegacyOutcome(
            id: UUID(),
            fingerprint: "legacy",
            title: "Legacy recommendation",
            mode: .timed,
            sessionID: UUID(),
            followed: true,
            completedAt: Date(timeIntervalSince1970: 1_000),
            scoreDelta: 2,
            fillerDelta: -1,
            durationDelta: 2
        )
        let decoded = try JSONDecoder().decode(
            RecommendationOutcome.self,
            from: JSONEncoder().encode(legacy)
        )

        #expect(decoded.focus == nil)
        #expect(decoded.target == nil)
        #expect(decoded.hasComparableScore == nil)
        #expect(decoded.fillerRateDelta == nil)
        #expect(decoded.comparisonSessionCount == nil)
    }

    private func outcome(
        mode: PracticeMode,
        focus: String? = nil,
        followed: Bool = true,
        scoreDelta: Double,
        hasComparableScore: Bool,
        fillerDelta: Double
    ) -> RecommendationOutcome {
        RecommendationOutcome(
            id: UUID(),
            fingerprint: "\(mode.rawValue)-test",
            title: "Test prescription",
            focus: focus,
            target: nil,
            mode: mode,
            sessionID: UUID(),
            followed: followed,
            completedAt: Date(),
            scoreDelta: scoreDelta,
            hasComparableScore: hasComparableScore,
            fillerDelta: fillerDelta,
            durationDelta: 0,
            fillerRateDelta: fillerDelta,
            comparisonSessionCount: 3
        )
    }
}

@Suite("RecommendationAdaptationAnalyzerTests")
struct RecommendationAdaptationAnalyzerTests {

    // MARK: Cold start + thin evidence

    @Test func coldStart_noFollowedReps_returnsNilAndNoRationale() {
        #expect(RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: []) == nil)
        // Followed:false reps for the key are not cold-start material either.
        let unfollowed = (0..<5).map { adOutcome(mode: .timed, focus: "close", followed: false, at: 100 + Double($0), score: -2) }
        #expect(RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: unfollowed) == nil)
        #expect(RecommendationAdaptationAnalyzer.adaptationRationale(mode: .timed, focus: "close", in: unfollowed) == nil)
    }

    @Test func belowMovementFloor_reinforceTentative_noRationale_excludesNoSignalReps() {
        // 2 moving (comparable score) + 3 followed reps with no movement at all.
        var outcomes = [
            adOutcome(mode: .timed, focus: "close", at: 200, score: -0.7, hasScore: true),
            adOutcome(mode: .timed, focus: "close", at: 199, score: -0.8, hasScore: true),
        ]
        outcomes += (0..<3).map { adOutcome(mode: .timed, focus: "close", at: 100 + Double($0), score: 0, hasScore: false, filler: 0) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.action == .reinforce)
        #expect(verdict?.confidence == .tentative)
        #expect(verdict?.movementReps == 2)        // 3 no-signal reps excluded
        #expect(verdict?.followedReps == 5)
        #expect(RecommendationAdaptationAnalyzer.adaptationRationale(mode: .timed, focus: "close", in: outcomes) == nil)
    }

    // MARK: Vary / replace floors

    @Test func exactlyThreeUnfavorable_varyTentative_notReplace_notFailed() {
        let outcomes = (0..<3).map { adOutcome(mode: .suddenDeath, focus: "open", at: 100 + Double($0), score: -0.7, hasScore: true) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, focus: "open", in: outcomes)
        #expect(verdict?.action == .vary)
        #expect(verdict?.confidence == .tentative)
        #expect(verdict?.movementReps == 3)
        #expect(verdict?.improvedRate == 0.0)
        let line = RecommendationAdaptationAnalyzer.adaptationRationale(mode: .suddenDeath, focus: "open", in: outcomes)
        #expect(line?.contains("varying the approach") == true)
        #expect(line?.contains("not abandoning it yet") == true)
        #expect(line?.contains("failed") == false)
        #expect(line?.contains("swap") == false)
    }

    @Test func replaceFloorHoldsAtFive_neverReplace() {
        let outcomes = (0..<5).map { adOutcome(mode: .suddenDeath, focus: "open", at: 100 + Double($0), score: -0.9, hasScore: true) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, focus: "open", in: outcomes)
        #expect(verdict?.action == .vary)        // 5 < 6 confident-replace floor
        #expect(verdict?.action != .replace)
    }

    @Test func sixSustainedUnfavorable_confidentReplace_trendedDown_noCausalClaim() {
        let outcomes = (0..<6).map { adOutcome(mode: .suddenDeath, focus: "open", at: 100 + Double($0), score: -0.9, hasScore: true) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, focus: "open", in: outcomes)
        #expect(verdict?.action == .replace)
        #expect(verdict?.confidence == .confident)
        #expect(verdict?.movementReps == 6)
        #expect((verdict?.unfavorableRate ?? 0) >= 0.6)
        let line = RecommendationAdaptationAnalyzer.adaptationRationale(mode: .suddenDeath, focus: "open", in: outcomes)
        #expect(line?.contains("trended down") == true)
        #expect(line?.contains("swap it for a different angle") == true)
        for banned in ["failed", "caused", "because", "proves", "guarantee"] {
            #expect(line?.contains(banned) == false)
        }
    }

    // MARK: Autocorrelation + recency hardening

    @Test func autocorrelatedMeanReversion_neverConfidentReplace() {
        // oldest -> newest: unfav, unfav, unfav, neutral, fav, fav (one early bad run that
        // mean-reverts). All 6 carry a comparable score, so movementReps == 6 reaches the
        // confident-replace FLOOR — yet the positive recent window must still block replace.
        let scores = [-0.9, -0.9, -0.9, 0.0, 0.9, 0.9]
        let outcomes = scores.enumerated().map { i, s in
            adOutcome(mode: .timed, focus: "close", at: 100 + Double(i), score: s, hasScore: true, filler: 0)
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.movementReps == 6)      // at the replace floor…
        #expect(verdict?.action != .replace)     // …but the late window is positive -> not replace
    }

    @Test func slippingTrend_overridesHighRate_doesNotReinforce() {
        // oldest -> newest: fav, fav, fav, unfav, unfav, unfav. improvedRate 0.5 but recent window clearly negative.
        let scores = [0.9, 0.9, 0.9, -0.9, -0.9, -0.9]
        let outcomes = scores.enumerated().map { i, s in
            adOutcome(mode: .timed, focus: "close", at: 100 + Double(i), score: s, hasScore: true)
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.action != .reinforce)   // a clearly-negative recent window beats a high lifetime rate
        #expect(verdict?.improvedRate == 0.5)
    }

    @Test func recoveringTrend_aboveWindowFloor_reinforces() {
        // oldest -> newest: unfav, unfav, unfav, fav, fav, fav.
        let scores = [-0.9, -0.9, -0.9, 0.9, 0.9, 0.9]
        let outcomes = scores.enumerated().map { i, s in
            adOutcome(mode: .timed, focus: "close", at: 100 + Double(i), score: s, hasScore: true)
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.action == .reinforce)
        #expect(verdict?.trend == .recovering)
    }

    @Test func recoveringTail_belowWindowFloor_doesNotRescue() {
        // 3 moving reps arranged unfav -> neutral -> favorable (a 1-rep tail cannot rescue: floor is 4).
        let outcomes = [
            adOutcome(mode: .timed, focus: "close", at: 100, score: -0.9, hasScore: true),
            adOutcome(mode: .timed, focus: "close", at: 101, score: 0.0, hasScore: true),
            adOutcome(mode: .timed, focus: "close", at: 102, score: 0.9, hasScore: true),
        ]
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.action == .vary)        // not reinforce — 1-rep window can't rescue
    }

    // MARK: Filler polarity + jitter

    @Test func fillerOnlySignal_polarityInverts_favorableReinforces() {
        // Negative filler delta = improvement; no comparable score.
        let outcomes = (0..<4).map { adOutcome(mode: .ahCounter, focus: "lean", at: 100 + Double($0), score: 0, hasScore: false, filler: -1.2) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .ahCounter, focus: "lean", in: outcomes)
        #expect(verdict?.action == .reinforce)
        #expect(verdict?.movementReps == 4)
        #expect(verdict?.improvedRate == 1.0)
    }

    @Test func fillerJitterBelowFloor_isNotMovement() {
        let outcomes = (0..<6).map { adOutcome(mode: .timed, focus: "close", at: 100 + Double($0), score: 0, hasScore: false, filler: 0.1) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.movementReps == 0)      // 0.1 < 0.375 movement floor
        #expect(verdict?.action == .reinforce)   // falls to thin-evidence reinforce, never near replace
        #expect(verdict?.action != .replace)
    }

    @Test func nilComparableScore_isNeverWeighted_fillerStillCounts() {
        // 4 reps: huge positive scoreDelta but hasComparableScore == nil -> score ignored, no filler movement -> excluded.
        var outcomes = (0..<4).map { adOutcome(mode: .timed, focus: "close", at: 100 + Double($0), score: 2.0, hasScoreOptional: nil, filler: 0) }
        // 3 reps with a real filler improvement, still nil score.
        outcomes += (0..<3).map { adOutcome(mode: .timed, focus: "close", at: 200 + Double($0), score: 2.0, hasScoreOptional: nil, filler: -1.0) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.movementReps == 3)      // only the filler-moving reps count; +2.0 score on nil-flag reps ignored
    }

    @Test func legacyMetricsWithoutComparisonSchemaCannotDriveAdaptation() {
        let legacy = (0..<6).map { index in
            RecommendationOutcome(
                id: UUID(), fingerprint: "legacy", title: "Old prescription",
                focus: "close", target: nil, mode: .timed,
                sessionID: UUID(), followed: true,
                completedAt: Date(timeIntervalSince1970: Double(index)),
                scoreDelta: -3, hasComparableScore: true, fillerDelta: 5,
                durationDelta: -30, wordsPerMinute: 210, paceDelta: 40
            )
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(
            mode: .timed,
            focus: "close",
            in: legacy
        )
        #expect(verdict == nil)
    }

    @Test func fillerPrescriptionIsJudgedOnFillerRateNotCompositeScore() {
        let outcomes = (0..<6).map { index in
            adOutcome(
                mode: .ahCounter,
                focus: "filler control",
                at: 100 + Double(index),
                score: 2,
                hasScoreOptional: true,
                filler: 1.2
            )
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(
            mode: .ahCounter,
            focus: "filler control",
            in: outcomes
        )
        #expect(verdict?.action == .replace)
        #expect(verdict?.unfavorableRate == 1)
    }

    // MARK: Keying

    @Test func verdictScopedPerModeFocusGroup_notGlobal() {
        // The sustained-unfavorable group under test (suddenDeath|close) is given the
        // NEWEST timestamps so the staleness escape-hatch doesn't decay its replace —
        // this test isolates per-key scoping + whitespace normalisation, not staleness.
        var outcomes = (0..<6).map { adOutcome(mode: .suddenDeath, focus: "close", at: 500 + Double($0), score: -0.9, hasScore: true) }
        outcomes += (0..<6).map { adOutcome(mode: .suddenDeath, focus: "opener", at: 300 + Double($0), score: 0.9, hasScore: true) }
        outcomes += (0..<6).map { adOutcome(mode: .timed, focus: "close", at: 100 + Double($0), score: 0.9, hasScore: true) }
        // Whitespace variant must normalise into the "close" group (and stay newest).
        outcomes.append(adOutcome(mode: .suddenDeath, focus: "  close  ", at: 510, score: -0.9, hasScore: true))
        #expect(RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, focus: "close", in: outcomes)?.action == .replace)
        #expect(RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, focus: "opener", in: outcomes)?.action == .reinforce)
        #expect(RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)?.action == .reinforce)
    }

    @Test func modeOnlyOverload_aggregatesFocuses_forSelectionBias() {
        // Same mode, two focuses, all unfavorable -> aggregate reaches the replace floor.
        var outcomes = (0..<3).map { adOutcome(mode: .suddenDeath, focus: "close", at: 100 + Double($0), score: -0.9, hasScore: true) }
        outcomes += (0..<3).map { adOutcome(mode: .suddenDeath, focus: "opener", at: 200 + Double($0), score: -0.9, hasScore: true) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, in: outcomes)
        #expect(verdict?.action == .replace)
        #expect(verdict?.movementReps == 6)
        #expect(verdict?.normalizedFocus == nil)
    }

    @Test func modeOnlyOverload_mixedFocuses_doesNotReplace() {
        var outcomes = (0..<3).map { adOutcome(mode: .suddenDeath, focus: "close", at: 100 + Double($0), score: -0.9, hasScore: true) }
        outcomes += (0..<3).map { adOutcome(mode: .suddenDeath, focus: "opener", at: 200 + Double($0), score: 0.9, hasScore: true) }
        #expect(RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, in: outcomes)?.action != .replace)
    }

    // MARK: Window + ordering + latch

    @Test func windowCap_stalEvidenceBeyond12_excluded() {
        // 9 oldest unfavorable, 6 newest favorable. Only the most-recent 12 count.
        var outcomes = (0..<9).map { adOutcome(mode: .timed, focus: "close", at: 100 + Double($0), score: -0.9, hasScore: true) }
        outcomes += (0..<6).map { adOutcome(mode: .timed, focus: "close", at: 500 + Double($0), score: 0.9, hasScore: true) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: outcomes)
        #expect(verdict?.action == .reinforce)   // recent 12 are mostly favorable; stale history can't force replace
        #expect(verdict?.action != .replace)
    }

    @Test func orderIndependence_givenDistinctTimestamps() {
        let base = [-0.9, -0.9, -0.9, 0.9, 0.9, 0.9].enumerated().map { i, s in
            adOutcome(mode: .timed, focus: "close", at: 100 + Double(i), score: s, hasScore: true)
        }
        let forward = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: base)
        let reversed = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: base.reversed())
        let shuffled = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "close", in: [base[3], base[0], base[5], base[1], base[4], base[2]])
        #expect(forward == reversed)
        #expect(forward == shuffled)
    }

    @Test func latchDecays_whenModeUnrevisited() {
        // 6 sustained-unfavorable reps for the key (old), then 8 newer followed reps for OTHER keys.
        var outcomes = (0..<6).map { adOutcome(mode: .suddenDeath, focus: "open", at: 100 + Double($0), score: -0.9, hasScore: true) }
        outcomes += (0..<8).map { adOutcome(mode: .timed, focus: "other", at: 500 + Double($0), score: 0.2, hasScore: true) }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .suddenDeath, focus: "open", in: outcomes)
        #expect(verdict?.action == .vary)        // decayed from confident replace; the mode earns a fresh trial
        #expect(verdict?.action != .replace)
    }

    // MARK: The single most important copy-safety lock

    @Test func associationLanguage_noCausalClaim_everyEmittingBranch() {
        let reinforce = (0..<3).map { adOutcome(mode: .timed, focus: "close", at: 100 + Double($0), score: 0.9, hasScore: true) }
        let vary = (0..<3).map { adOutcome(mode: .suddenDeath, focus: "open", at: 100 + Double($0), score: -0.9, hasScore: true) }
        let replace = (0..<6).map { adOutcome(mode: .timed, focus: "lean", at: 100 + Double($0), score: -0.9, hasScore: true) }
        let lines = [
            RecommendationAdaptationAnalyzer.adaptationRationale(mode: .timed, focus: "close", in: reinforce),
            RecommendationAdaptationAnalyzer.adaptationRationale(mode: .suddenDeath, focus: "open", in: vary),
            RecommendationAdaptationAnalyzer.adaptationRationale(mode: .timed, focus: "lean", in: replace),
        ]
        for line in lines {
            #expect(line != nil)
            #expect(line?.contains("measurable rep") == true)        // honest count label, never bare "followed reps"
            #expect(line?.contains("followed rep") == false)
            for banned in ["failed", "caused", "because", "proves", "guarantee"] {
                #expect(line?.contains(banned) == false)
            }
        }
        // reinforce + vary speak of moving "alongside your metric"; replace says "trended down".
        #expect(lines[0]?.contains("alongside your metric") == true)
        #expect(lines[1]?.contains("alongside your metric") == true)
        #expect(lines[2]?.contains("trended down") == true)
    }

    // MARK: Factory

    private func adOutcome(
        mode: PracticeMode,
        focus: String?,
        followed: Bool = true,
        at completedAt: TimeInterval,
        score: Double,
        hasScore: Bool = true,
        filler: Double = 0
    ) -> RecommendationOutcome {
        adOutcome(mode: mode, focus: focus, followed: followed, at: completedAt, score: score, hasScoreOptional: hasScore, filler: filler)
    }

    private func adOutcome(
        mode: PracticeMode,
        focus: String?,
        followed: Bool = true,
        at completedAt: TimeInterval,
        score: Double,
        hasScoreOptional: Bool?,
        filler: Double = 0,
        wordsPerMinute: Double? = nil,
        paceDelta: Double? = nil
    ) -> RecommendationOutcome {
        RecommendationOutcome(
            id: UUID(),
            fingerprint: "\(mode.rawValue)|\(focus ?? "")",
            title: "Test prescription",
            focus: focus,
            target: nil,
            mode: mode,
            sessionID: UUID(),
            followed: followed,
            completedAt: Date(timeIntervalSince1970: completedAt),
            scoreDelta: score,
            hasComparableScore: hasScoreOptional,
            fillerDelta: filler,
            durationDelta: 0,
            fillerRateDelta: filler,
            comparisonSessionCount: 3,
            wordsPerMinute: wordsPerMinute,
            paceDelta: paceDelta
        )
    }

    // MARK: Focus-matched pace read (judge the intervention on the metric it prescribed)

    @Test func paceFocusedPrescriptionIsJudgedOnPaceNotTheCompositeScore() {
        // Score/filler read says NO movement (no comparable score, flat
        // fillers) — under the old read these reps were invisible. The pace
        // evidence shows the fast talker closing on the band each rep
        // (distance 30 -> 15, 20 -> 8, 15 -> 3), all >= the 10wpm swing.
        let outcomes = [
            adOutcome(mode: .timed, focus: "controlled pacing under pressure", at: 100, score: 0, hasScoreOptional: false, wordsPerMinute: 190, paceDelta: -15),
            adOutcome(mode: .timed, focus: "controlled pacing under pressure", at: 101, score: 0, hasScoreOptional: false, wordsPerMinute: 183, paceDelta: -12),
            adOutcome(mode: .timed, focus: "controlled pacing under pressure", at: 102, score: 0, hasScoreOptional: false, wordsPerMinute: 178, paceDelta: -12),
        ]
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "controlled pacing under pressure", in: outcomes)
        #expect(verdict?.action == .reinforce)
        #expect(verdict?.movementReps == 3, "pace movement must count toward the floor")
        #expect(verdict?.improvedRate == 1.0)
        #expect(RecommendationAdaptationAnalyzer.adaptationRationale(mode: .timed, focus: "controlled pacing under pressure", in: outcomes) != nil)
    }

    @Test func paceReadIsPolarityCorrectForASlowTalkerLifting() {
        // Slow talker rising toward the band: prior 83 -> 95 wpm shrinks the
        // band distance 22 -> 10 (+12 improvement) — favorable, not "faster
        // is worse".
        let outcomes = (0..<3).map { i in
            adOutcome(mode: .timed, focus: "lift your speaking speed", at: 100 + Double(i), score: 0, hasScoreOptional: false, wordsPerMinute: 95, paceDelta: 12)
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "lift your speaking speed", in: outcomes)
        #expect(verdict?.action == .reinforce)
        #expect(verdict?.improvedRate == 1.0)
    }

    @Test func paceDriftingAwayFromBandSustainedIsConfidentReplace() {
        // Six reps drifting AWAY from the band (prior 188 -> 200: distance
        // 13 -> 25, −12 each) — the same confident-replace bar as any other
        // sustained unfavorable ledger.
        let outcomes = (0..<6).map { i in
            adOutcome(mode: .timed, focus: "controlled pacing", at: 100 + Double(i), score: 0, hasScoreOptional: false, wordsPerMinute: 200, paceDelta: 12)
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "controlled pacing", in: outcomes)
        #expect(verdict?.action == .replace)
        #expect(verdict?.confidence == .confident)
        #expect((verdict?.unfavorableRate ?? 0) >= 0.6)
    }

    @Test func paceFocusedOutcomesWithoutPaceFieldsStayUnmeasured() {
        // A pace prescription is judged only on pace. Comparable score data
        // must not become substitute evidence for the intervention's target.
        let outcomes = (0..<3).map { i in
            adOutcome(mode: .timed, focus: "controlled pacing", at: 100 + Double(i), score: -0.7, hasScoreOptional: true)
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "controlled pacing", in: outcomes)
        #expect(verdict == nil)
        #expect(RecommendationAdaptationAnalyzer.adaptationRationale(
            mode: .timed, focus: "controlled pacing", in: outcomes
        ) == nil)
        let prompt = RecommendationResponseAnalyzer.promptLines(from: outcomes).joined(separator: "\n")
        #expect(prompt.contains("no comparable metric yet"))
        #expect(!prompt.contains("score -"))
        #expect(!prompt.contains("filler rate"))
    }

    @Test func nonPaceFocusIgnoresPaceEvidence() {
        // A close-focused prescription with incidental pace improvement must
        // still be judged on the score read (unfavorable -> vary), never on
        // pace it didn't prescribe.
        let outcomes = (0..<3).map { i in
            adOutcome(mode: .timed, focus: "a decisive close", at: 100 + Double(i), score: -0.7, hasScoreOptional: true, wordsPerMinute: 178, paceDelta: -12)
        }
        let verdict = RecommendationAdaptationAnalyzer.adaptationVerdict(mode: .timed, focus: "a decisive close", in: outcomes)
        #expect(verdict?.action == .vary)
    }
}

