        )

        #expect(memory?.adaptationLog?.count == 1)
        let entry = memory?.adaptationLog?.last
        #expect(entry?.fromLever == .paceControl)
        #expect(entry?.toLever == .answerDevelopment)
        // Carries BOTH the focus shift AND the user-reported reason.
        #expect(entry?.reason.contains("Shifted focus from Pace to Depth") == true)
        #expect(entry?.reason.contains("user reported the prior hypothesis did not match") == true)
        // Evidence basis is the user-tapped rejection, not the engine
        // inference — the documented reason is the user's report.
        #expect(entry?.evidenceBasis.contains("user-tapped rejection") == true)
        #expect(memory?.hypothesisAcknowledgement == nil)
    }

    @Test func buildDoesNotLogAdaptationForConfirmedOrUncertainAck() {
        // Only the `.rejected` branch documents a course change — a
        // confirmed/uncertain ack on a now-rewritten hypothesis is
        // dropped (the snapshot guard catches it) but does NOT pollute
        // the adaptation log. The course-change record must only carry
        // genuine pushback.
        for confidence in [CoachHypothesisConfidence.confirmed, .uncertain] {
            let prior = CoachMemory(
                updatedAt: Date(timeIntervalSince1970: 900),
                evidenceCount: 2,
                evidenceConfidence: .tentative,
                currentLever: .paceControl,
                goalFit: .aligned,
                strengths: [],
                blockers: [],
                workingHypothesis: "Pace may be the highest-leverage focus because stable at developing; verify over more reps.",
                hypothesisAcknowledgement: CoachHypothesisAcknowledgement(
                    confidence: confidence,
                    hypothesisSnapshot: "Pace may be the highest-leverage focus because stable at developing; verify over more reps.",
                    acknowledgedAt: Date(timeIntervalSince1970: 950)
                )
            )
            let trend = SkillTrend(
                skillArea: .paceControl,
                direction: .stable,
                confidence: .high,
                windowSize: 10,
                currentLevel: .developing
            )

            let memory = CoachMemoryEngine.build(
                profile: profile(voice: .warm),
                baseline: .empty,
                sessions: Array(repeating: session(), count: 10),
                trends: [trend],
                forwardPlan: nil,
                previous: prior,
                lastSessionID: nil,
                now: Date(timeIntervalSince1970: 1_000)
            )

            #expect(memory?.adaptationLog == nil,
                    "\(confidence) ack on a rewritten hypothesis must NOT append a course change")
            #expect(memory?.hypothesisAcknowledgement == nil,
                    "\(confidence) ack on a rewritten hypothesis is still dropped by the snapshot guard")
        }
    }

    @Test func buildDoesNotDoubleLogRejectedAckWhenHypothesisHolds() {
        // The ack still applies to the freshly-built hypothesis (same
        // snapshot text). The engine must NOT append a course-change
        // entry — the rejection is still active and the user will be
        // re-prompted on the chip row. Double-logging would balloon
        // the case file every rebuild.
        //
        // Fixture sized to 3 sessions / windowSize 3 so the build's
        // `evidenceCount` lands at 3 → `BaselineConfidence.tentative` →
        // the workingHypothesis(...) helper emits the "may be ...
        // verify" clause that the snapshot below mirrors.
        let hypothesisText = "Pace may be the highest-leverage focus because stable at developing; verify over more reps."
        let prior = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 900),
            evidenceCount: 2,
            evidenceConfidence: .tentative,
            currentLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: hypothesisText,
            hypothesisAcknowledgement: CoachHypothesisAcknowledgement(
                confidence: .rejected,
                hypothesisSnapshot: hypothesisText,
                acknowledgedAt: Date(timeIntervalSince1970: 950)
            )
        )
        let trend = SkillTrend(
            skillArea: .paceControl,
            direction: .stable,
            confidence: .high,
            windowSize: 3,
            currentLevel: .developing
        )

        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .warm),
            baseline: .empty,
            sessions: Array(repeating: session(), count: 3),
            trends: [trend],
            forwardPlan: nil,
            previous: prior,
            lastSessionID: nil,
            now: Date(timeIntervalSince1970: 1_000)
        )

        #expect(memory?.workingHypothesis == hypothesisText,
                "fixture should produce the same hypothesis text so the snapshot guard holds")
        #expect(memory?.adaptationLog == nil,
                "no rebuild-triggered log when the rejected ack still applies")
        #expect(memory?.hypothesisAcknowledgement?.confidence == .rejected,
                "the ack persists because the user has not yet re-evaluated")
    }

    @Test func buildTrimsLongRejectedSnapshotInEvidenceBasis() {
        // Snapshot longer than the 140-char readable cap must be
        // truncated with an ellipsis so the adaptation log entry stays
        // a single readable clause in the coach-context block. The
        // bounded case file is for the coach to skim, not for archival.
        let longSnapshot = String(repeating: "Filler reduction may be the highest-leverage focus because the rolling rate trend is stable at developing across the most-recent reps; verify over more reps. ", count: 3)
        let prior = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 900),
            evidenceCount: 2,
            evidenceConfidence: .tentative,
            currentLever: .fillerReduction,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: "stale hypothesis text that does not match the snapshot below",
            hypothesisAcknowledgement: CoachHypothesisAcknowledgement(
                confidence: .rejected,
                hypothesisSnapshot: longSnapshot,
                acknowledgedAt: Date(timeIntervalSince1970: 950)
            )
        )
        let trend = SkillTrend(
            skillArea: .fillerReduction,
            direction: .stable,
            confidence: .high,
            windowSize: 8,
            currentLevel: .developing
        )

        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .warm),
            baseline: .empty,
            sessions: Array(repeating: session(), count: 8),
            trends: [trend],
            forwardPlan: nil,
            previous: prior,
            lastSessionID: nil,
            now: Date(timeIntervalSince1970: 1_000)
        )

        let entry = memory?.adaptationLog?.last
        #expect(entry != nil)
        #expect(entry?.evidenceBasis.contains("…") == true,
                "long snapshots must be truncated with an ellipsis")
        // Quoted clause itself should be ≤ ~150 chars (140 cap + ellipsis
        // + quotes); the full evidence basis is slightly longer because
        // of the lead "user-tapped rejection of: " prefix.
        #expect((entry?.evidenceBasis.count ?? 0) < 200,
                "trimmed evidence basis stays short and readable")
    }

    // MARK: - Round-28: `CoachCourseChange` predicates for the
    // post-rep `RevisedReadCard` eligibility contract. Pure-function
    // tests; no engine round-trip required.

    @Test func courseChangeDocumentsUserPushbackOnRejectionAck() {
        // The `(nil, ack?)` switch arm in `CoachMemoryEngine.build(...)`
        // — a user-pushback rejection that rewrote the hypothesis text
        // inside the same lever — must mark `documentsUserPushback`.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
        #expect(change.documentsUserPushback == true)
    }

    @Test func courseChangeDocumentsUserPushbackOnCombinedShiftAndRejection() {
        // The `(prior?, ack?)` switch arm — both lever shifted AND the
        // user rejected the prior hypothesis — also marks pushback so
        // the post-rep card surfaces on a same-rebuild combined branch.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .answerDevelopment,
            reason: "Shifted focus from Pace to Depth after the user reported the prior hypothesis did not match what they saw.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
        #expect(change.documentsUserPushback == true)
    }

    @Test func courseChangeDoesNotDocumentUserPushbackOnEngineOnlyShift() {
        // The `(prior?, nil)` switch arm — engine inference only, no
        // user ack — must NOT mark pushback. The post-rep card stays
        // hidden on these; the Profile-tab `CaseReviewCard` keeps the
        // long-term history.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .answerDevelopment,
            reason: "Shifted focus from Pace to Depth.",
            evidenceBasis: "updated read across recent reps"
        )
        #expect(change.documentsUserPushback == false)
    }

    @Test func courseChangeIsFreshWhenStampedAtMemoryUpdate() {
        // Both `changedAt` and `CoachMemory.updatedAt` are written from
        // the same `now` in `CoachMemoryEngine.build(...)`, so equality
        // must read as fresh.
        let now = Date(timeIntervalSince1970: 1_000)
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: now,
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: ""
        )
        #expect(change.isFresh(comparedTo: now) == true)
    }

    @Test func courseChangeIsNotFreshAcrossMultipleSessions() {
        // The carried-forward entry on a later rebuild (memory.updatedAt
        // moved on, but the bounded history still holds the older
        // change) must read as stale so the post-rep card does not
        // re-show on every subsequent rep.
        let changedAt = Date(timeIntervalSince1970: 1_000)
        let laterMemoryUpdate = Date(timeIntervalSince1970: 2_000)
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: changedAt,
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: ""
        )
        #expect(change.isFresh(comparedTo: laterMemoryUpdate) == false)
    }

    @Test func freshlyBuiltMemoryMarksRejectedAckEntryAsFreshAndPushback() {
        // End-to-end pin: a single `CoachMemoryEngine.build(...)` pass
        // that folds a `.rejected` ack into a course-change entry must
        // produce an entry whose `documentsUserPushback` is true AND
        // whose `changedAt` is fresh against the returned memory's
        // `updatedAt`. Round-trips the contract the `RevisedReadCard`
        // gate reads on the post-rep summary.
        let prior = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 900),
            evidenceCount: 2,
            evidenceConfidence: .tentative,
            currentLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: "Pace may be the highest-leverage focus because stable at developing; verify over more reps.",
            hypothesisAcknowledgement: CoachHypothesisAcknowledgement(
                confidence: .rejected,
                hypothesisSnapshot: "Pace may be the highest-leverage focus because stable at developing; verify over more reps.",
                acknowledgedAt: Date(timeIntervalSince1970: 950)
            )
        )
        let trend = SkillTrend(
            skillArea: .paceControl,
            direction: .stable,
            confidence: .high,
            windowSize: 10,
            currentLevel: .developing
        )
        let now = Date(timeIntervalSince1970: 1_000)
        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .warm),
            baseline: .empty,
            sessions: Array(repeating: session(), count: 10),
            trends: [trend],
            forwardPlan: nil,
            previous: prior,
            lastSessionID: nil,
            now: now
        )
        let entry = memory?.adaptationLog?.last
        #expect(entry?.documentsUserPushback == true)
        #expect(entry?.isFresh(comparedTo: memory?.updatedAt ?? .distantPast) == true)
        #expect(memory?.updatedAt == now)
    }

    // MARK: - Round-33: second-cycle pushback detection in
    // `CoachMemoryEngine.build(...)`. The engine writes the
    // `secondCyclePushbackMarker` parenthetical into the new
    // `CoachCourseChange.reason` when the previous adaptation log's last
    // entry was itself a user pushback rebuild — so the bounded record
    // carries the cycle lineage and the chat-coach context block can
    // surface the repeated-adapt signal AFTER the round-30 chip-row ack
    // ages out of memory (which is when round 32 goes dark).

    @Test func courseChangeDocumentsSecondCyclePushbackWhenMarkerEmbedded() {
        // Pure-function predicate: a reason that contains BOTH the
        // first-cycle pushback marker AND the second-cycle parenthetical
        // returns true on both predicates. The two layer cleanly; round 33
        // never strips the first-cycle marker.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw (after a prior pushback rebuild); revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
        #expect(change.documentsUserPushback == true)
        #expect(change.documentsSecondCyclePushback == true)
    }

    @Test func courseChangeDoesNotDocumentSecondCycleWithoutMarker() {
        // The first-cycle reason (no parenthetical) must report
        // `documentsSecondCyclePushback == false`. The chat-coach context
        // and the post-rep card both gate on this predicate to decide
        // between first-cycle and second-cycle copy.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
        #expect(change.documentsUserPushback == true)
        #expect(change.documentsSecondCyclePushback == false)
    }

    @Test func courseChangeDoesNotDocumentSecondCycleForEngineOnlyShift() {
        // Engine-only lever shifts must not be mis-classified as second-
        // cycle pushback, even if a prior entry was a pushback rebuild.
        // The second-cycle signal is specifically about repeated USER
        // pushback, never repeated engine inference.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .answerDevelopment,
            reason: "Shifted focus from Pace to Depth.",
            evidenceBasis: "updated read across recent reps"
        )
        #expect(change.documentsUserPushback == false)
        #expect(change.documentsSecondCyclePushback == false)
    }

    @Test func buildEmbedsSecondCycleMarkerOnAckOnlyArmWhenPriorEntryWasPushback() {
        // Engine-side contract: the (nil, ack?) arm — same lever, rewritten
        // hypothesis text — must embed the second-cycle parenthetical when
        // the previous bounded log already documents a user pushback.
        let firstCycle = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 800),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
        let prior = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 900),
            evidenceCount: 2,
            evidenceConfidence: .tentative,
            currentLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: "Pace may be the highest-leverage focus because stable at developing; verify over more reps.",
            hypothesisAcknowledgement: CoachHypothesisAcknowledgement(
                confidence: .rejected,
                hypothesisSnapshot: "Pace may be the highest-leverage focus because stable at developing; verify over more reps.",
                acknowledgedAt: Date(timeIntervalSince1970: 950)
            ),
            adaptationLog: [firstCycle]
        )
        let trend = SkillTrend(
            skillArea: .paceControl,
            direction: .stable,
            confidence: .high,
            windowSize: 10,
            currentLevel: .developing
        )

        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .warm),
            baseline: .empty,
            sessions: Array(repeating: session(), count: 10),
            trends: [trend],
            forwardPlan: nil,
            previous: prior,
            lastSessionID: nil,
            now: Date(timeIntervalSince1970: 1_000)
        )

        // Bounded log carries BOTH cycles, ordered oldest-first.
        #expect(memory?.adaptationLog?.count == 2)
        let latest = memory?.adaptationLog?.last
        #expect(latest?.documentsUserPushback == true)
        #expect(latest?.documentsSecondCyclePushback == true)
        #expect(latest?.reason.contains("after a prior pushback rebuild") == true)
        // First-cycle marker preserved verbatim so existing predicates
        // (and the round-31 / round-32 gates) keep firing on the second
        // entry just as they would on the first.
        #expect(latest?.reason.contains("User reported the prior hypothesis did not match what they saw") == true)
    }

    @Test func buildEmbedsSecondCycleMarkerOnCombinedShiftArmWhenPriorEntryWasPushback() {
        // The (prior?, ack?) arm — lever shifted AND user rejected the
        // prior hypothesis — must also pick up the second-cycle tag when
        // the previous log entry already documents pushback.
        let firstCycle = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 800),
            fromLever: .fillerReduction,
