        )

        let latest = memory?.adaptationLog?.last
        #expect(latest?.documentsUserPushback == true)
        #expect(latest?.documentsSecondCyclePushback == false,
                "engine-only prior entry is not a 'pushback' — today's pushback is the first cycle, not the second")
    }

    @Test func buildDoesNotTagSecondCycleOnEngineOnlyShiftEvenAfterPriorPushback() {
        // The other half of the orthogonality test: an engine-only lever
        // shift today, even when the previous bounded log already
        // documents a user pushback, MUST stay untagged. The tag is
        // ack-driven only.
        let firstCycle = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 800),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
        let prior = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 900),
            evidenceCount: 8,
            evidenceConfidence: .moderate,
            currentLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: "Pace appears to be the highest-leverage focus because stable at developing; keep checking against future reps.",
            hypothesisAcknowledgement: nil,
            adaptationLog: [firstCycle]
        )
        // Lever shift today, no ack to drop.
        let trend = SkillTrend(
            skillArea: .answerDevelopment,
            direction: .newIssue,
            confidence: .high,
            windowSize: 8,
            currentLevel: .weak
        )

        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .warm),
            baseline: .empty,
            sessions: [session()],
            trends: [trend],
            forwardPlan: nil,
            previous: prior,
            lastSessionID: nil,
            now: Date(timeIntervalSince1970: 1_000)
        )

        let latest = memory?.adaptationLog?.last
        #expect(latest?.documentsUserPushback == false,
                "engine-only shift today; no user pushback recorded")
        #expect(latest?.documentsSecondCyclePushback == false,
                "engine-only shifts never get the second-cycle tag, regardless of prior log")
    }

    private func ahCounterSession(
        id: UUID = UUID(),
        fillers: Int,
        duration: TimeInterval = 60,
        at time: TimeInterval
    ) -> PracticeSession {
        PracticeSession(
            id: id,
            transcript: "rep",
            fillerWordCount: fillers,
            duration: duration,
            date: Date(timeIntervalSince1970: time),
            mode: .ahCounter,
            score: 6
        )
    }

    private func profile(voice: SpeakingStyleGoal) -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: voice,
            styleReference: "",
            coachingBrief: "I want to brief senior stakeholders clearly.",
            motivationWhyNow: "",
            successVision: "",
            paraphrasedGoal: "Brief senior stakeholders clearly.",
            chosenStyleGoal: voice
        )
    }

    private func session(id: UUID = UUID(), intentLabel: String? = nil) -> PracticeSession {
        PracticeSession(
            id: id,
            transcript: "The update needs to be clear and calm.",
            fillerWordCount: 2,
            duration: 60,
            date: Date(timeIntervalSince1970: 1_000),
            mode: .timed,
            score: 6,
            intentLabel: intentLabel
        )
    }

    private func reflection(
        _ feeling: ReflectionFeeling,
        at time: TimeInterval,
        note: String? = nil
    ) -> SessionReflection {
        SessionReflection(
            sessionID: UUID(),
            feeling: feeling,
            note: note,
            recordedAt: Date(timeIntervalSince1970: time)
        )
    }

    private func interventionOutcome(
        mode: PracticeMode,
        sessionID: UUID = UUID(),
        followed: Bool = true,
        completedAt: TimeInterval,
        scoreDelta: Double,
        fillerDelta: Double,
        focus: String = "a decisive close",
        hasComparableScore: Bool? = true,
        fillerRateDelta: Double? = nil,
        comparisonSessionCount: Int? = 3,
        wordsPerMinute: Double? = nil,
        paceDelta: Double? = nil
    ) -> RecommendationOutcome {
        RecommendationOutcome(
            id: UUID(),
            fingerprint: "\(mode.rawValue)-case",
            title: "Test prescription",
            focus: focus,
            target: "One clean final sentence",
            mode: mode,
            sessionID: sessionID,
            followed: followed,
            completedAt: Date(timeIntervalSince1970: completedAt),
            scoreDelta: scoreDelta,
            hasComparableScore: hasComparableScore,
            fillerDelta: fillerDelta,
            durationDelta: 0,
            fillerRateDelta: fillerRateDelta ?? fillerDelta,
            comparisonSessionCount: comparisonSessionCount,
            wordsPerMinute: wordsPerMinute,
            paceDelta: paceDelta
        )
    }

    // MARK: - B1 #5 — Grounded success-bar criterion copy
    //
    // The success measure recovers the same-demand baseline persisted on an
    // accepted outcome. Absolute status is then judged only from exact joined
    // outcome/session IDs; arbitrary same-mode history is not followed proof.

    @Test func buildGroundsFillerCriterionInPriorAverageAboveFloor() {
        // fillers newest→oldest: 1, 1, 7, 6, 6.
        // window = 2 → priorValues = [7, 6, 6] (count 3, at the floor),
        // priorAverage = 19/3 ≈ 6.333 → "6.3"; threshold = (6.333-1).rounded() = 5.
        let ahSessions = [
            ahCounterSession(fillers: 1, at: 1_000),
            ahCounterSession(fillers: 1, at: 900),
            ahCounterSession(fillers: 7, at: 800),
            ahCounterSession(fillers: 6, at: 700),
            ahCounterSession(fillers: 6, at: 600),
        ]

        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .concise),
            baseline: .empty,
            sessions: ahSessions,
            trends: [],
            forwardPlan: nil,
            previous: nil,
            lastSessionID: nil,
            recommendationOutcomes: [
                interventionOutcome(
                    mode: .ahCounter,
                    sessionID: ahSessions[0].id,
                    followed: true,
                    completedAt: 1_000,
                    scoreDelta: 0,
                    fillerDelta: -1,
                    fillerRateDelta: -1
                )
            ],
            now: Date(timeIntervalSince1970: 1_000)
        )

        let criterion = memory?.activeIntervention?.successCriterion
        #expect(criterion?.metric == .fillersPerMinute)
        #expect(criterion?.threshold == 1.3)
        #expect(criterion?.baselineSnapshot?.sampleDepth == 3)
        #expect(criterion?.baselineSnapshot?.priorAverage == 2)
        #expect(criterion?.summary == "your last 3 comparable reps averaged 2 fillers/min — hold at 1.3 or fewer/min across 2 reps")
    }

    @Test func buildGroundsScoreCriterionInPriorAverageAboveFloor() {
        // Score metric (non-filler focus). scores newest→oldest: 8, 8, 5, 5, 5.
        // priorValues = [5, 5, 5] (count 3), priorAverage = 5.0 → "5";
        // threshold = min(10, (5+1).rounded()) = 6.
        let timedSessions: [PracticeSession] = [
            PracticeSession(transcript: "rep", fillerWordCount: 0, duration: 60, date: Date(timeIntervalSince1970: 1_000), mode: .timed, score: 8),
            PracticeSession(transcript: "rep", fillerWordCount: 0, duration: 60, date: Date(timeIntervalSince1970: 900), mode: .timed, score: 8),
            PracticeSession(transcript: "rep", fillerWordCount: 0, duration: 60, date: Date(timeIntervalSince1970: 800), mode: .timed, score: 5),
            PracticeSession(transcript: "rep", fillerWordCount: 0, duration: 60, date: Date(timeIntervalSince1970: 700), mode: .timed, score: 5),
            PracticeSession(transcript: "rep", fillerWordCount: 0, duration: 60, date: Date(timeIntervalSince1970: 600), mode: .timed, score: 5),
        ]

        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .concise),
            baseline: .empty,
            sessions: timedSessions,
            trends: [],
            forwardPlan: nil,
            previous: nil,
            lastSessionID: nil,
            recommendationOutcomes: [
                interventionOutcome(
                    mode: .timed,
                    sessionID: timedSessions[0].id,
                    followed: true,
                    completedAt: 1_000,
                    scoreDelta: 3,
                    fillerDelta: 0
                ),
                interventionOutcome(
                    mode: .timed,
                    sessionID: timedSessions[1].id,
                    followed: true,
                    completedAt: 900,
                    scoreDelta: 3,
                    fillerDelta: 0
                )
            ],
            now: Date(timeIntervalSince1970: 1_000)
        )

        let criterion = memory?.activeIntervention?.successCriterion
        #expect(criterion?.metric == .sessionScore)
        #expect(criterion?.threshold == 6)
        #expect(criterion?.baselineSnapshot?.sampleDepth == 3)
        #expect(criterion?.baselineSnapshot?.priorAverage == 5)
        #expect(criterion?.summary == "your last 3 reps averaged 5 — hold a 6 or higher across 2 reps")
        #expect(memory?.activeIntervention?.criterionStatus == .met)
    }

    /// A pacing session with a controlled word count: duration 60s means
    /// wpm == word count exactly.
    private func pacedSession(words: Int, at time: TimeInterval, duration: Double = 60) -> PracticeSession {
        PracticeSession(
            transcript: Array(repeating: "word", count: words).joined(separator: " "),
            fillerWordCount: 0,
            duration: duration,
            date: Date(timeIntervalSince1970: time),
            mode: .timed,
            score: 7
        )
    }

    @Test func paceFocusedPrescriptionIsHeldToWordsPerMinuteForAFastTalker() {
        // Focus-matched criterion: a pacing prescription for a demonstrably
        // fast talker (priors 190/195/185 wpm, avg 190 > 175 band edge) is
        // judged on wpm — bar = get inside the band (175 or slower) — not on
        // the composite session score.
        let sessions = [
            pacedSession(words: 150, at: 1_000),
            pacedSession(words: 150, at: 900),
            pacedSession(words: 190, at: 800),
            pacedSession(words: 195, at: 700),
            pacedSession(words: 185, at: 600),
        ]
        let memory = CoachMemoryEngine.build(
            profile: profile(voice: .concise),
            baseline: .empty,
            sessions: sessions,
            trends: [],
            forwardPlan: nil,
            previous: nil,
            lastSessionID: nil,
            recommendationOutcomes: [
                interventionOutcome(
                    mode: .timed,
                    sessionID: sessions[0].id,
                    followed: true,
                    completedAt: 1_000,
                    scoreDelta: 1,
                    fillerDelta: 0,
                    focus: "controlled pacing under pressure",
                    wordsPerMinute: 150,
                    paceDelta: -40
                ),
                interventionOutcome(
                    mode: .timed,
                    sessionID: sessions[1].id,
                    followed: true,
                    completedAt: 900,
                    scoreDelta: 1,
                    fillerDelta: 0,
                    focus: "controlled pacing under pressure",
                    wordsPerMinute: 150,
                    paceDelta: -40
                )
            ],
            now: Date(timeIntervalSince1970: 1_000)
        )
        let criterion = memory?.activeIntervention?.successCriterion
        #expect(criterion?.metric == .wordsPerMinute)
        #expect(criterion?.comparator == .atMost)
        #expect(criterion?.threshold == 175)
        #expect(criterion?.baselineSnapshot?.sampleDepth == 3)
        #expect(criterion?.baselineSnapshot?.priorAverage == 190)
        #expect(criterion?.summary == "your last 3 reps averaged 190 words/min — bring it to 175 or slower across 2 reps")
        #expect(memory?.activeIntervention?.criterionStatus == .met)
    }

    @Test func paceFocusInsideHealthyBandFallsBackToGenericScoreCriterion() {
        // Priors average ~150 wpm — inside 105...175. Holding an in-band
        // speaker to a pace bar would be theatre, so the criterion must be
        // BYTE-IDENTICAL to the generic score criterion a non-pace focus gets.
        let sessions = [
            pacedSession(words: 150, at: 1_000),
            pacedSession(words: 150, at: 900),
            pacedSession(words: 148, at: 800),
            pacedSession(words: 152, at: 700),
            pacedSession(words: 150, at: 600),
        ]
        func build(focus: String) -> CoachSuccessCriterion? {
            CoachMemoryEngine.build(
                profile: profile(voice: .concise),
                baseline: .empty,
                sessions: sessions,
                trends: [],
                forwardPlan: nil,
                previous: nil,
                lastSessionID: nil,
                recommendationOutcomes: [
                    interventionOutcome(
                        mode: .timed,
                        sessionID: sessions[0].id,
                        followed: true,
                        completedAt: 1_000,
                        scoreDelta: 1,
                        fillerDelta: 0,
                        focus: focus,
                        wordsPerMinute: 150,
                        paceDelta: 0
                    )
                ],
                now: Date(timeIntervalSince1970: 1_000)
            )?.activeIntervention?.successCriterion
        }
        let paceFocused = build(focus: "controlled pacing under pressure")
        let genericFocus = build(focus: "a decisive close")
        #expect(paceFocused?.metric == .sessionScore)
        #expect(paceFocused == genericFocus, "in-band pace focus must fall back byte-identically to the generic criterion")
    }

