    // MARK: Decode-safety — old blob without the new keys

    @Test func decodesOldCoachMemoryBlobWithoutConcordanceKeys() throws {
        // A CoachMemory persisted before slice-4 carries neither
        // `statedChallengeConcordance` nor `statedChallengeArea`. It must
        // decode cleanly with the defaulted (.unknown / nil) values — no
        // throw, no migration.
        let legacy = """
        {
          "updatedAt": 1000,
          "evidenceCount": 8,
          "evidenceConfidence": 2,
          "currentLever": "fillerReduction",
          "goalFit": "aligned",
          "strengths": [],
          "blockers": []
        }
        """.data(using: .utf8)!
        let decoded = try JSONDecoder().decode(CoachMemory.self, from: legacy)
        #expect(decoded.statedChallengeConcordance == .unknown)
        #expect(decoded.statedChallengeArea == nil)
        #expect(decoded.currentLever == .fillerReduction)
    }

    @Test func concordanceFieldSurvivesEncodeDecodeRoundTrip() throws {
        let memory = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_000),
            evidenceCount: 12,
            evidenceConfidence: .established,
            voice: .concise,
            currentLever: .fillerReduction,
            goalFit: .offGoal,
            statedChallengeConcordance: .divergent,
            statedChallengeArea: .confidence,
            strengths: [],
            blockers: []
        )
        let data = try JSONEncoder().encode(memory)
        let decoded = try JSONDecoder().decode(CoachMemory.self, from: data)
        #expect(decoded.statedChallengeConcordance == .divergent)
        #expect(decoded.statedChallengeArea == .confidence)
    }
}

@Suite("CoachSuccessCriterionTests")
struct CoachSuccessCriterionTests {
    private func criterion(_ comparator: CoachCaseComparator, threshold: Double, window: Int = 2) -> CoachSuccessCriterion {
        CoachSuccessCriterion(
            metric: comparator == .atMost ? .fillersPerRep : .sessionScore,
            comparator: comparator,
            threshold: threshold,
            evaluationWindow: window,
            summary: "test"
        )
    }

    @Test func pendingUntilWindowFilled() {
        let c = criterion(.atMost, threshold: 3)
        #expect(c.status(forFollowedValues: []) == .pending)
        #expect(c.status(forFollowedValues: [1]) == .pending)
    }

    @Test func atMostMetWhenWindowAverageWithinThreshold() {
        let c = criterion(.atMost, threshold: 3)
        #expect(c.status(forFollowedValues: [2, 3, 9]) == .met)
        #expect(c.status(forFollowedValues: [4, 4]) == .notYetMet)
    }

    @Test func atLeastMetWhenWindowAverageMeetsThreshold() {
        let c = criterion(.atLeast, threshold: 7)
        #expect(c.status(forFollowedValues: [8, 7]) == .met)
        #expect(c.status(forFollowedValues: [6, 6, 10]) == .notYetMet)
    }

    @Test func zeroWindowStaysPending() {
        let c = criterion(.atMost, threshold: 3, window: 0)
        #expect(c.status(forFollowedValues: [1, 1]) == .pending)
    }

    @Test func legacyCriterionWithoutBaselineSnapshotDecodesWithNilSnapshot() throws {
        let legacy = """
        {
          "metric": "fillersPerRep",
          "comparator": "atMost",
          "threshold": 3,
          "evaluationWindow": 2,
          "summary": "3 or fewer fillers per rep across 2 reps"
        }
        """.data(using: .utf8)!

        let decoded = try JSONDecoder().decode(CoachSuccessCriterion.self, from: legacy)

        #expect(decoded.metric == .fillersPerRep)
        #expect(decoded.comparator == .atMost)
        #expect(decoded.threshold == 3)
        #expect(decoded.evaluationWindow == 2)
        #expect(decoded.summary == "3 or fewer fillers per rep across 2 reps")
        #expect(decoded.baselineSnapshot == nil)
    }
}

