            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: voice,
            styleReference: "",
            coachingBrief: "I want to sound sharper.",
            motivationWhyNow: "",
            successVision: ""
        )
