        #expect(reflection.coachClause.contains("nerves affected their delivery"))
        #expect(reflection.coachClause.contains("\""))
    }

    @Test func historyCapIsThirty() {
        #expect(SessionReflectionStore.historyCap == 30)
    }

    @Test func accountKeysDontCollide() {
        #expect("sessionReflection.history.account-abc" != "sessionReflection.history.account-xyz")
    }
}

// MARK: - M21 — SessionIntentMatcher → summary bullet alignment

struct SessionIntentMatcherTests {

    @Test func fillerIntentMatchesFillerAndClarityBullets() {
        #expect(SessionIntentMatcher.aligns(bulletID: "filler", with: .reduceFillers))
        #expect(SessionIntentMatcher.aligns(bulletID: "category-Clarity", with: .reduceFillers))
        #expect(!SessionIntentMatcher.aligns(bulletID: "pace-fast", with: .reduceFillers))
        #expect(!SessionIntentMatcher.aligns(bulletID: "leverage", with: .reduceFillers))
    }

    @Test func conciseIntentMatchesStructureAndDepthBullets() {
        #expect(SessionIntentMatcher.aligns(bulletID: "category-Structure", with: .moreConcise))
        #expect(SessionIntentMatcher.aligns(bulletID: "category-Depth", with: .moreConcise))
        #expect(SessionIntentMatcher.aligns(bulletID: "category-Clarity", with: .moreConcise))
        #expect(!SessionIntentMatcher.aligns(bulletID: "filler", with: .moreConcise))
    }

    @Test func thinkFasterIntentMatchesOpeningAndPaceFast() {
        #expect(SessionIntentMatcher.aligns(bulletID: "category-Opening", with: .thinkFaster))
        #expect(SessionIntentMatcher.aligns(bulletID: "pace-fast", with: .thinkFaster))
        #expect(!SessionIntentMatcher.aligns(bulletID: "filler", with: .thinkFaster))
    }

    @Test func calmerDeliveryMatchesPaceBullets() {
        #expect(SessionIntentMatcher.aligns(bulletID: "pace-fast", with: .calmerDelivery))
        #expect(SessionIntentMatcher.aligns(bulletID: "pace-slow", with: .calmerDelivery))
        #expect(SessionIntentMatcher.aligns(bulletID: "category-Pace", with: .calmerDelivery))
        #expect(!SessionIntentMatcher.aligns(bulletID: "filler", with: .calmerDelivery))
    }

    @Test func momentumAndLeverageNeverMatchAnyIntent() {
        // The momentum/leverage bullets are the coach's verdict line,
        // not a per-skill verdict — they shouldn't carry the "you
        // aimed for this" chip even when the intent ostensibly
        // overlaps. Keeps the chip's signal high.
        for priority in CoachingPriority.allCases {
            #expect(!SessionIntentMatcher.aligns(bulletID: "momentum", with: priority))
            #expect(!SessionIntentMatcher.aligns(bulletID: "leverage", with: priority))
            #expect(!SessionIntentMatcher.aligns(bulletID: "ai-strength", with: priority))
            #expect(!SessionIntentMatcher.aligns(bulletID: "ai-improvement", with: priority))
        }
    }
}

// MARK: - M21 — CoachContextBuilder INTENT row in RECENT

struct CoachContextBuilderIntentTests {

    private func makeProfile() -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .moreConcise,
            confidenceLevel: .inconsistent,
            biggestChallenge: .rambling,
            desiredOutcome: .concise,
            speakingStyleGoal: .warm,
            styleReference: "",
            coachingBrief: "Brief.",
            motivationWhyNow: "",
            successVision: ""
        )
    }

    private func makeBaseline() -> CommunicationBaseline {
        // .empty has every BaselineStat marked .insufficient — the
        // RECENT block does not depend on baseline confidence, so this
        // keeps the test surface tight.
        CommunicationBaseline.empty
    }

    @Test func intentTailAppearsWhenSessionCarriesLabel() {
        let session = PracticeSession(
            transcript: "Sample transcript.",
            fillerWordCount: 2,
            duration: 25,
            date: Date(),
            mode: .timed,
            intentFocus: .moreConcise,
            intentLabel: "Tighten structure"
        )
        let context = CoachContextBuilder.userContext(
            profile: makeProfile(),
            baseline: makeBaseline(),
            rating: SpeakingRating.initial,
            sessions: [session],
            currentStreak: 1,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(context.contains("Intent: Tighten structure"))
    }

    @Test func intentTailOmittedWhenSessionLacksIntent() {
        let session = PracticeSession(
            transcript: "Sample transcript.",
            fillerWordCount: 2,
            duration: 25,
            date: Date(),
            mode: .timed
        )
        let context = CoachContextBuilder.userContext(
            profile: makeProfile(),
            baseline: makeBaseline(),
            rating: SpeakingRating.initial,
            sessions: [session],
            currentStreak: 1,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!context.contains("Intent:"))
    }

    @Test func intentTailIgnoresWhitespaceOnlyLabels() {
        // A defensive contract: if a future code path somehow writes
        // an all-whitespace label, the RECENT row should silently omit
        // the tail rather than render "Intent:   ".
        let session = PracticeSession(
            transcript: "Sample transcript.",
            fillerWordCount: 2,
            duration: 25,
            date: Date(),
            mode: .timed,
            intentFocus: .moreConcise,
            intentLabel: "   "
        )
        let context = CoachContextBuilder.userContext(
            profile: makeProfile(),
            baseline: makeBaseline(),
            rating: SpeakingRating.initial,
            sessions: [session],
            currentStreak: 1,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!context.contains("Intent:"))
    }
}

struct CoachContextBuilderWeeklyCheckInOpportunityTests {

    @Test func dueWeeklyCheckInAddsOrganicChatCue() {
        let context = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            weeklyCheckInDue: true
        )

        #expect(context.contains("CHECK-IN OPPORTUNITY"))
        #expect(context.contains("Do not interrupt practice"))
        #expect(context.contains("at most one concise human-coach question"))
        #expect(context.contains("Suggested question"))
        #expect(context.contains("What felt hardest in a real conversation this week?"))
        #expect(!context.contains("what felt hardest this week, what they avoided saying"))
    }

    @Test func quietWeeklyCadenceOmitsCheckInCue() {
        let context = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            weeklyCheckInDue: false
        )

        #expect(!context.contains("CHECK-IN OPPORTUNITY"))
    }

    @Test func weeklyCheckInQuestionPrioritizesMissedDrillForAdaptation() {
        let checkIn = CoachCheckIn(
            hardest: "Holding the room",
            outsideApp: "Leadership update",
            drillVerdict: .missed,
            confidenceShift: .lessSteady,
            avoidedSaying: "I softened the direct ask"
        )

        let question = CoachContextBuilder.weeklyCheckInQuestionHint(for: checkIn)

        #expect(question == "What did the current drill miss that you actually needed this week?")
    }

    @Test func weeklyCheckInQuestionPrioritizesStalledDrillBeforeAvoidance() {
        let checkIn = CoachCheckIn(
            drillVerdict: .stalled,
            confidenceShift: .lessSteady,
            avoidedSaying: "I avoided naming the risk clearly"
        )

        let question = CoachContextBuilder.weeklyCheckInQuestionHint(for: checkIn)

        #expect(question.contains("Where did the current drill stall"))
        #expect(!question.contains("avoided"))
    }

    @Test func weeklyCheckInQuestionUsesAvoidanceWhenDrillDidNotStall() {
        let checkIn = CoachCheckIn(
            drillVerdict: .helped,
            confidenceShift: .lessSteady,
            avoidedSaying: "I avoided naming the risk clearly"
        )

        let question = CoachContextBuilder.weeklyCheckInQuestionHint(for: checkIn)

        #expect(question.contains("avoided saying"))
        #expect(question.contains("cleanly"))
    }

    @Test func weeklyCheckInQuestionUsesConfidenceWhenAvoidanceAbsent() {
        let lessSteady = CoachCheckIn(confidenceShift: .lessSteady)
        let moreSteady = CoachCheckIn(confidenceShift: .moreSteady)

        #expect(CoachContextBuilder.weeklyCheckInQuestionHint(for: lessSteady).contains("confidence dip"))
        #expect(CoachContextBuilder.weeklyCheckInQuestionHint(for: moreSteady).contains("more steady"))
    }

    @Test func dueContextCarriesSelectedQuestionFromLatestCheckIn() {
        let checkIn = CoachCheckIn(
            drillVerdict: .helped,
            avoidedSaying: "I avoided naming the risk clearly"
        )

        let context = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            recentCheckIns: [checkIn],
            weeklyCheckInDue: true
        )

        #expect(context.contains("Suggested question"))
        #expect(context.contains("Is the thing you avoided saying still worth saying"))
        #expect(context.contains("Do not diagnose a trait"))
    }

    @Test func recentCheckInCarriesConfidenceAndAvoidanceIntoContext() {
        let checkIn = CoachCheckIn(
            hardest: "Holding the room",
            outsideApp: "Leadership update",
            drillVerdict: .helped,
            confidenceShift: .moreSteady,
            avoidedSaying: "I avoided naming the risk clearly"
        )

        let context = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            recentCheckIns: [checkIn]
        )

        #expect(context.contains("WEEKLY CHECK-IN"))
        #expect(context.contains("Confidence this week"))
        #expect(context.contains("more steady"))
        #expect(context.contains("What they avoided saying"))
        #expect(context.contains("I avoided naming the risk clearly"))
        #expect(context.contains("user-reported"))
    }
}

// MARK: - M21 — PracticeSession Codable forward compatibility

struct PracticeSessionIntentDecodingTests {

    @Test func oldPersistedSessionDecodesIntentAsNil() throws {
        // Simulate a session persisted before M21 — no intentFocus /
        // intentLabel keys. The optional fields must decode to nil
        // instead of throwing or defaulting to a bogus value.
        let json = """
        {
            "id": "11111111-1111-1111-1111-111111111111",
            "transcript": "Old rep.",
            "fillerWordCount": 1,
            "duration": 12.0,
            "date": 730000000.0,
            "mode": "timed"
        }
        """
        let data = json.data(using: .utf8)!
        let session = try JSONDecoder().decode(PracticeSession.self, from: data)
        #expect(session.intentFocus == nil)
        #expect(session.intentLabel == nil)
    }

    @Test func newSessionWithIntentRoundTrips() throws {
        let original = PracticeSession(
            transcript: "New rep.",
            fillerWordCount: 0,
            duration: 18,
            date: Date(),
            mode: .suddenDeath,
            intentFocus: .reduceFillers,
            intentLabel: "Cut fillers"
        )
        let data = try JSONEncoder().encode(original)
        let decoded = try JSONDecoder().decode(PracticeSession.self, from: data)
        #expect(decoded.intentFocus == .reduceFillers)
        #expect(decoded.intentLabel == "Cut fillers")
    }
}

struct FeedbackRatingDecodingTests {

    @Test func decodesCanonicalAndProviderStyleRatings() throws {
        let cases: [(String, FeedbackRating)] = [
            ("Good", .good),
            ("good", .good),
            ("OK", .ok),
            ("ok", .ok),
            ("okay", .ok),
            ("Could improve", .couldImprove),
            ("couldImprove", .couldImprove),
            ("could_improve", .couldImprove)
        ]

        for (raw, expected) in cases {
            let data = "\"\(raw)\"".data(using: .utf8)!
            let decoded = try JSONDecoder().decode(FeedbackRating.self, from: data)
            #expect(decoded == expected, "\(raw) should decode as \(expected)")
        }
    }

    @Test func encodesCanonicalDisplayRating() throws {
        let data = try JSONEncoder().encode(FeedbackRating.couldImprove)
        let encoded = String(data: data, encoding: .utf8)

        #expect(encoded == "\"Could improve\"")
    }
}

struct VideoAnalysisContractTests {

    @Test func providerEligibilityRequiresVisionCapableProvider() {
        #expect(VideoAnalysisContract.providerSupportsVision(.openAI))
        #expect(VideoAnalysisContract.providerSupportsVision(.gemini))
        #expect(!VideoAnalysisContract.providerSupportsVision(.deepSeek))
        #expect(!VideoAnalysisContract.providerSupportsVision(.none))
    }

    @Test func localeEligibilityFollowsPracticeLocaleAISupport() {
        #expect(VideoAnalysisContract.localeSupportsAI(.enUS))
        #expect(!VideoAnalysisContract.localeSupportsAI(.esES))
        #expect(!VideoAnalysisContract.localeSupportsAI(.frFR))
    }

    @Test func normalizedResultTrimsAndBoundsNotes() {
        let longOverall = Array(repeating: "steady", count: 50).joined(separator: " ")
        let normalized = VideoAnalysisContract.normalized(result(
            postureNote: "  Shoulders stay open and stable on camera.  ",
            overallNote: longOverall
        ))

        #expect(normalized?.postureNote == "Shoulders stay open and stable on camera.")
        #expect(normalized?.overallNote.split(whereSeparator: \.isWhitespace).count == 42)
    }

    @Test func genericTextOnlyVideoReadIsRejected() {
        let normalized = VideoAnalysisContract.normalized(result(
            postureNote: "This is a generic video analysis based on common areas speakers should focus on."
        ))

        #expect(normalized == nil)
    }

    @Test func emptyVisualNoteIsRejected() {
        let normalized = VideoAnalysisContract.normalized(result(eyeContactNote: " "))

        #expect(normalized == nil)
    }

    @Test func aiSelfDisclosureIsRejected() {
        let normalized = VideoAnalysisContract.normalized(result(
            overallNote: "As an AI, I cannot see the frames, but posture is usually worth improving."
        ))

        #expect(normalized == nil)
    }

    @Test func visualDeliveryReadUsesNormalizedOptInVideoRead() throws {
        let sessionID = UUID()
        let read = try #require(VisualDeliveryRead.make(
            from: result(
                eyeContactNote: "Eye line returns to the lens often enough.",
                overallNote: "Your visual delivery looks composed. Keep the eye line steadier on the next rep."
            ),
            sessionID: sessionID,
            recordedAt: Date(timeIntervalSince1970: 2_000)
        ))

        #expect(read.sessionID == sessionID)
        #expect(read.recordedAt == Date(timeIntervalSince1970: 2_000))
        #expect(read.eyeContact == .ok)
        #expect(read.primaryImprovement?.contains("Eye contact") == true)
        #expect(read.coachContextLine.contains("User-initiated video read"))
        #expect(read.coachContextLine.contains("opt-in visual evidence from one recording"))
        #expect(read.coachContextLine.contains("not a trait or diagnosis"))
    }

    @Test func visualDeliveryReadRejectsInvalidProviderRead() {
        let read = VisualDeliveryRead.make(
            from: result(
                overallNote: "As an AI, I cannot see the frames, but posture is usually worth improving."
            ),
            sessionID: UUID(),
            recordedAt: Date(timeIntervalSince1970: 2_000)
        )

        #expect(read == nil)
    }

    private func result(
        postureNote: String = "Shoulders stay open and stable on camera.",
        eyeContactNote: String = "Eye line returns to the lens often enough.",
        facialExpressionNote: String = "Expression reads engaged and calm.",
        gestureNote: String = "Gestures look contained and deliberate.",
        energyNote: String = "Upper-body energy stays present without rushing.",
        presenceNote: String = "Presence reads steady and composed.",
        overallNote: String = "Your visual delivery looks composed. Keep the eye line steadier on the next rep."
    ) -> VideoAnalysisResult {
        VideoAnalysisResult(
            posture: .good,
            postureNote: postureNote,
            eyeContact: .ok,
            eyeContactNote: eyeContactNote,
            facialExpression: .good,
            facialExpressionNote: facialExpressionNote,
            gestureUse: .ok,
            gestureNote: gestureNote,
            energyConfidence: .good,
            energyNote: energyNote,
            presenceDelivery: .good,
            presenceNote: presenceNote,
            overallNote: overallNote
        )
    }
}

// MARK: - M20 Paywall Feature Accuracy Tests

@Suite("PaywallFeatureAccuracy")
@MainActor
struct PaywallFeatureAccuracyTests {

    // Verify that features listed as Pro-gated in PremiumManager are actually
    // gated (not accidentally open to free users after a logic change).
    @Test func proGatedFeaturesRequirePremium() {
        let manager = PremiumManager.shared
        // Snapshot without premium entitlement
        let wasPremium = manager.isPremium
        if wasPremium { manager.revokePremium() }
        defer { wasPremium ? manager.upgradeToPremium() : manager.revokePremium() }

        #expect(!manager.canUseCoachMode, "Coach mode must require Pro")
        #expect(!manager.canUseLiveTranscript, "Live transcript must require Pro")
        #expect(!manager.canRecordVideo, "Video recording must require Pro")
        #expect(!manager.canUseFillerTracking, "Filler tracking must require Pro")
        #expect(!manager.canViewTrends, "Trend analytics must require Pro")
        #expect(!manager.canUseAsyncChallenges, "Unlimited async challenges must require Pro")
        #expect(!manager.canUseVideoAnalysis, "AI video analysis must require Pro")
    }

    // Verify that free-tier features listed on the paywall are genuinely open.
    @Test func freeFeaturesTrulyFreeForAll() {
        let manager = PremiumManager.shared
        let wasPremium = manager.isPremium
        if wasPremium { manager.revokePremium() }
        defer { wasPremium ? manager.upgradeToPremium() : manager.revokePremium() }

        #expect(manager.canUseClassicMode, "Classic mode must be free")
        #expect(manager.canViewBasicScore, "Basic scoring must be free")
        #expect(manager.canUseDailyChallenges, "Daily challenges must be free")
        #expect(manager.canUseThinkingTime, "Thinking time must be free")
    }

    // Filler tracking is listed as a PRO feature on the paywall.
    // It must NOT appear in canUseDailyChallenges-style open gates.
    @Test func fillerTrackingIsNotFree() {
        let manager = PremiumManager.shared
        let wasPremium = manager.isPremium
        if wasPremium { manager.revokePremium() }
        defer { wasPremium ? manager.upgradeToPremium() : manager.revokePremium() }

        #expect(!manager.canUseFillerTracking,
                "Filler tracking is gated Pro — it must not be free, matching the paywall listing")
    }

    // Video analysis credits are bounded at 5/month for Pro users.
    @Test func videoAnalysisLimitIsEnforced() {
        #expect(PremiumManager.monthlyVideoAnalysisLimit == 5,
                "Paywall advertises 5 video analyses/month — limit constant must match")
    }

    // Free users get 1 async challenge slot; Pro users are unlimited.
    @Test func asyncChallengeLimitEnforced() {
        let manager = PremiumManager.shared
        let wasPremium = manager.isPremium
        if wasPremium { manager.revokePremium() }
        defer { wasPremium ? manager.upgradeToPremium() : manager.revokePremium() }

        #expect(manager.asyncChallengeLimit == 1, "Free tier gets 1 async challenge slot")
        manager.upgradeToPremium()
        #expect(manager.asyncChallengeLimit == .max, "Pro tier gets unlimited async challenge slots")
    }
}

@Suite("PremiumReleaseContracts")
@MainActor
struct PremiumReleaseContractTests {
    @Test func emptyVerifiedEntitlementsResolveToFree() {
        // There is intentionally no persisted `true` input. Once StoreKit's
