@Suite("SpeakOffFriendEligibilityTests")
struct SpeakOffFriendEligibilityTests {
    @Test func manualFriendsAreNotEligibleForScoredSpeakOffs() {
        let manual = NoumFriend(
            id: UUID(),
            displayName: "Manual Friend",
            addedAt: Date(),
            addedVia: .manual
        )
        let linked = NoumFriend(
            id: UUID(),
            displayName: "Linked Friend",
            addedAt: Date(),
            addedVia: .invite,
            accountID: "linked-account"
        )

        let eligible = SpeakOffFriendEligibility.linkedFriends(from: [manual, linked])

        #expect(eligible.map(\.displayName) == ["Linked Friend"])
    }

    @Test func blankAccountIDsAreTreatedAsUnlinked() {
        let blank = NoumFriend(
            id: UUID(),
            displayName: "Blank",
            addedAt: Date(),
            addedVia: .invite,
            accountID: "   "
        )

        #expect(SpeakOffFriendEligibility.isLinked(blank) == false)
    }
}

// MARK: - Test helpers

extension CommunicationBaseline {
    func withBlockers(_ blockers: [String]) -> CommunicationBaseline {
        var copy = self
        copy.persistentBlockers = blockers
        return copy
    }
}

// MARK: - M20 Ask Noum chip filter tests

@Suite("AskNoumChipFilterTests")
struct AskNoumChipFilterTests {

    @Test func parseAndFilterStripsMarkersAndPassesCleanChips() {
        let raw = "- What's my target pace?\n* How do I lock it?\n1. Any drift to watch?"
        let result = CoachContextBuilder.parseAndFilterChips(raw, count: 3)
        #expect(result?.count == 3)
        #expect(result?.allSatisfy { !$0.hasPrefix("-") && !$0.hasPrefix("*") } == true)
    }

    @Test func parseAndFilterRejectsExclamationMark() {
        let raw = "Nice work!\nWhat's the move?\nHow long?"
        let result = CoachContextBuilder.parseAndFilterChips(raw, count: 3)
        // "Nice work!" fails the filter — fewer than 3 survive → nil
        #expect(result == nil)
    }

    @Test func parseAndFilterRejectsLeadingLets() {
        let raw = "Let's try this drill\nWhat's the move?\nHow long?"
        let result = CoachContextBuilder.parseAndFilterChips(raw, count: 3)
        #expect(result == nil)
    }

    @Test func parseAndFilterReturnsNilWhenFewerThanCountSurvive() {
        let raw = "OK\nHow long?"  // "OK" is too short (2 chars < 4) + only 2 chips
        let result = CoachContextBuilder.parseAndFilterChips(raw, count: 3)
        #expect(result == nil)
    }

    @Test func starterPromptsWithBigMomentLeadsWithEventChip() {
        let moment = BigMoment(
            title: "Board presentation",
            date: Calendar.current.date(byAdding: .day, value: 5, to: Date()),
            category: .presentation
        )
        let emptyBaseline = CommunicationBaseline.empty
        let chips = CoachContextBuilder.starterPrompts(
            bigMoment: moment,
            baseline: emptyBaseline,
            voice: .authoritative
        )
        #expect(chips.count <= 3)
        #expect(chips.first?.contains("presentation") == true || chips.first?.contains("open") == true)
    }

    @Test func starterPromptsWithoutSignalsFallsBackToVoiceCatalog() {
        let emptyBaseline = CommunicationBaseline.empty
        let chips = CoachContextBuilder.starterPrompts(
            bigMoment: nil,
            baseline: emptyBaseline,
            voice: .concise
        )
        let catalog = CoachContextBuilder.starterPrompts(for: .concise)
        #expect(chips.count <= 3)
        // All returned chips should appear in the catalog when no signals exist
        #expect(chips.allSatisfy { catalog.contains($0) })
    }

    @Test func starterPromptsBlockerSignalInjectsWeaknessChip() {
        let baseline = CommunicationBaseline.empty.withBlockers(["pace"])
        let chips = CoachContextBuilder.starterPrompts(
            bigMoment: nil,
            baseline: baseline,
            voice: .warm
        )
        #expect(chips.count <= 3)
        let hasBlockerChip = chips.contains { $0.lowercased().contains("pace") }
        #expect(hasBlockerChip)
    }

    @Test func starterPromptsCanLeadWithWeeklyCheckInWhenDue() {
        let chips = CoachContextBuilder.starterPrompts(
            bigMoment: nil,
            baseline: .empty,
            voice: .warm,
            weeklyCheckInDue: true
        )

        #expect(chips.first == "Check in on this week.")
        #expect(chips.count <= 3)
    }

    @Test func starterPromptsCanReconnectToSignupMotivation() {
        let profile = CoachingProfile(
            speakingContext: .work,
            primaryGoal: .moreConcise,
            confidenceLevel: .inconsistent,
            biggestChallenge: .rambling,
            desiredOutcome: .concise,
            speakingStyleGoal: .warm,
            styleReference: "",
            coachingBrief: "Help me speak clearly.",
            motivationWhyNow: "I have started leading more senior meetings.",
            successVision: "I can be concise without sounding cold."
        )
        let chips = CoachContextBuilder.starterPrompts(
            bigMoment: nil,
            baseline: .empty,
            voice: .warm,
            profile: profile
        )

        #expect(chips.contains("Reconnect me to why I started."))
        #expect(chips.count <= 3)
    }

    @Test func starterPromptsCapAt3() {
        let moment = BigMoment(
            title: "Interview",
            date: Calendar.current.date(byAdding: .day, value: 3, to: Date()),
            category: .interview
        )
        let baseline = CommunicationBaseline.empty.withBlockers(["fillers"])
        let chips = CoachContextBuilder.starterPrompts(
            bigMoment: moment,
            baseline: baseline,
            voice: .persuasive
        )
        #expect(chips.count == 3)
    }

    @Test func starterPromptsChipsAllUnder60Chars() {
        let moment = BigMoment(
            title: "My annual performance review with the entire executive committee",
            date: Calendar.current.date(byAdding: .day, value: 10, to: Date()),
            category: .review
        )
        let baseline = CommunicationBaseline.empty.withBlockers(["hedging rate"])
        let chips = CoachContextBuilder.starterPrompts(
            bigMoment: moment,
            baseline: baseline,
            voice: .executive
        )
        #expect(chips.allSatisfy { $0.count <= 60 })
    }
}

// MARK: - S3 — Recent-session digest + AI-starter fallback contract
//
// Covers the two NEW deterministic seams added for session-aware chips +
// dynamic empty-state starters. `parseAndFilterChips` itself is already
// exercised in `AskNoumChipFilterTests` / `CoachContextBuilderChipParserTests`
// — here we cover (1) `recentSessionDigestForChips` (the privacy-bounded
// summary that feeds both the follow-up chips and the AI starters) and
// (2) the contract that the AI-starter path reuses `parseAndFilterChips` as
// its grounding gate, so a short/ungrounded batch yields nil and the caller
// falls back to the deterministic catalog.

@Suite("AskNoumStarterDigestTests")
struct AskNoumStarterDigestTests {

    // Local factory — mirrors the positional-init + var-assignment shape the
    // rest of the suite uses for PracticeSession.
    private func session(
        score: Int? = nil,
        theme: PromptTheme? = nil,
        intentLabel: String? = nil,
        headline: String? = nil,
        transcript: String = "raw transcript words the user actually said out loud",
        date: Date = Date()
    ) -> PracticeSession {
        var s = PracticeSession(
            transcript: transcript,
            fillerWordCount: 0,
            duration: 30,
            date: date
        )
        s.score = score
        s.theme = theme
        s.intentLabel = intentLabel
        s.headline = headline
        return s
    }

    // MARK: - recentSessionDigestForChips

    @Test func digestIsNilOnEmptySessions() {
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: [],
            baseline: .empty
        )
        #expect(digest == nil)
    }

    @Test func digestIsNilWhenSessionsCarryNoSignal() {
        // A rep with no score, no theme, no intent, no headline produces no
        // row — and an all-bare history produces no digest at all.
        let bare = session(score: nil, theme: nil, intentLabel: nil, headline: nil)
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: [bare],
            baseline: .empty
        )
        #expect(digest == nil)
    }

    @Test func digestIncludesScoreAndIntentLabels() throws {
        let s = session(
            score: 7,
            theme: .workCareer,
            intentLabel: "Cut fillers",
            headline: "Strong open, lost the thread mid-answer"
        )
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: [s],
            baseline: .empty
        )
        let unwrapped = try #require(digest)
        #expect(unwrapped.contains("score 7/10"))
        #expect(unwrapped.contains("aimed for Cut fillers"))
        #expect(unwrapped.contains("Work & Career"))      // theme rawValue
        #expect(unwrapped.contains("Strong open"))         // headline survives
        #expect(unwrapped.contains("LAST SESSIONS"))       // labelled block
    }

    @Test func digestIsBoundedToLimit() throws {
        // Five scored reps, limit 2 → exactly two "- " rows.
        let sessions = (1...5).map { i in
            session(score: i + 3, theme: .leadership, date: Date().addingTimeInterval(Double(i)))
        }
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: sessions,
            baseline: .empty,
            limit: 2
        )
        let unwrapped = try #require(digest)
        let rowCount = unwrapped
            .split(separator: "\n")
            .filter { $0.hasPrefix("- ") }
            .count
        #expect(rowCount == 2)
    }

    @Test func digestTakesMostRecentByDate() throws {
        // Unsorted input — the digest must pick the newest two by date,
        // not by array order. Newest two scores are 9 and 8.
        let old = session(score: 4, date: Date().addingTimeInterval(-300))
        let newest = session(score: 9, date: Date().addingTimeInterval(0))
        let middle = session(score: 8, date: Date().addingTimeInterval(-100))
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: [old, newest, middle],
            baseline: .empty,
            limit: 2
        )
        let unwrapped = try #require(digest)
        #expect(unwrapped.contains("score 9/10"))
        #expect(unwrapped.contains("score 8/10"))
        #expect(!unwrapped.contains("score 4/10"))
    }

    @Test func digestNeverPastesRawTranscript() throws {
        // PRIVACY invariant — the raw spoken words must never appear in the
        // digest. Only score / theme / intent / coach-authored headline.
        let secret = "MY_SECRET_RAW_TRANSCRIPT_PHRASE"
        let s = session(
            score: 6,
            theme: .general,
            intentLabel: "Tighten structure",
            headline: "Clear and direct",
            transcript: "Here is \(secret) that I said in the rep."
        )
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: [s],
            baseline: .empty
        )
        let unwrapped = try #require(digest)
        #expect(!unwrapped.contains(secret))
    }

    @Test func digestContainsNoExclamationOrEmoji() throws {
        // Brand-voice safety — even though the digest is model-input (not
        // user-visible), keep it clean so a model can't echo an exclamation
        // straight into a chip. Headlines with a trailing "!" are stripped.
        let s = session(
            score: 8,
            theme: .funRandom,
            intentLabel: "Slow down",
            headline: "Nailed the landing!"
        )
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: [s],
            baseline: .empty
        )
        let unwrapped = try #require(digest)
        #expect(!unwrapped.contains("!"))
        for scalar in unwrapped.unicodeScalars {
            #expect(!(scalar.properties.isEmoji && scalar.value > 0x238C))
        }
    }

    @Test func digestSkipsAllThemeButKeepsRealThemes() throws {
        // `.all` is a UI filter sentinel, not a real session theme — it must
        // not leak into the digest. A real theme must.
        let allTheme = session(score: 5, theme: .all)
        let realTheme = session(score: 6, theme: .interviewPrep, date: Date().addingTimeInterval(10))
        let digest = CoachContextBuilder.recentSessionDigestForChips(
            sessions: [allTheme, realTheme],
            baseline: .empty
        )
        let unwrapped = try #require(digest)
        #expect(!unwrapped.contains("All Themes"))
        #expect(unwrapped.contains("Interview Prep"))
    }

    @Test func digestRejectsNonPositiveLimit() {
        let s = session(score: 7)
        #expect(CoachContextBuilder.recentSessionDigestForChips(
            sessions: [s], baseline: .empty, limit: 0) == nil)
    }

    // MARK: - AI-starter fallback contract (reuses parseAndFilterChips)
    //
    // The AI-starter path (`generateAIStarterPrompts`) cannot be exercised
    // without a provider, but its grounding gate IS `parseAndFilterChips`
    // — identical to the follow-up chip path. These assert the contract the
    // caller relies on: a full clean batch parses; a short/dirty batch
    // returns nil, at which point Ask Noum shows no suggested ask rather than
    // surfacing the deterministic `starterPrompts(...)` catalog.

    @Test func aiStarterCleanBatchParsesToExactCount() {
        let raw = """
        How should I open my board pitch?
        What cut my last rep short?
        Plan my next 7 days.
        """
        let chips = CoachContextBuilder.parseAndFilterChips(raw, count: 3)
        #expect(chips?.count == 3)
    }

    @Test func aiStarterShortBatchReturnsNilSoCallerShowsNoSuggestedAsk() {
        // Only two survive (the exclamation line is dropped) → nil → the
        // empty-state suggestion row stays hidden.
        let raw = "Open my pitch?\nGreat work today!\nNext 7 days?"
        let chips = CoachContextBuilder.parseAndFilterChips(raw, count: 3)
        #expect(chips == nil)
    }
}

// MARK: - M24 Track 1 — CoachPersona catalogue contract

struct CoachPersonaTests {

    @Test func personaForNilReturnsDefault() {
        let p = CoachPersona.persona(for: nil)
        #expect(p.voice == nil)
        #expect(p.registerName == "Default")
    }

    @Test func everyVoiceReturnsDistinctRegisterName() {
        var seen: Set<String> = ["Default"]
        for voice in SpeakingStyleGoal.allCases {
            let p = CoachPersona.persona(for: voice)
            #expect(!seen.contains(p.registerName), "Duplicate registerName for \(voice)")
            seen.insert(p.registerName)
        }
    }

    @Test func everyVoiceHasNonEmptyOpeningsAndClosings() {
        for voice in SpeakingStyleGoal.allCases {
            let p = CoachPersona.persona(for: voice)
            #expect(!p.openings.isEmpty, "\(voice) openings empty")
            #expect(!p.closings.isEmpty, "\(voice) closings empty")
            #expect(!p.reflectionLead.isEmpty, "\(voice) reflectionLead empty")
        }
    }

    @Test func brandVoiceContractAcrossAllPersonas() {
        // Brand voice rule: no exclamations anywhere in the catalogue.
        // The `.default` persona is exercised by voice = nil.
        let personas = SpeakingStyleGoal.allCases.map { CoachPersona.persona(for: $0) } + [CoachPersona.default]
        for p in personas {
            for line in p.openings + p.closings + [p.reflectionLead, p.signatureTone, p.registerName] {
                #expect(!line.contains("!"), "Exclamation in \(p.registerName): \(line)")
            }
        }
    }

    @Test func openingAndClosingSeededPicksAreStable() {
        // Same seed → same line. Critical so a session's coach note
        // doesn't shuffle text on every render.
        let p = CoachPersona.persona(for: .concise)
        let seed = 42
        #expect(p.opening(seed: seed) == p.opening(seed: seed))
        #expect(p.closing(seed: seed) == p.closing(seed: seed))
    }

    @Test func openingAndClosingNeverCrashWithExtremeSeeds() {
        // Negative seed (Int.min) was a previous crash class on
        // `abs(Int.min)`. Cover the boundary explicitly.
        let p = CoachPersona.persona(for: .warm)
        // Don't use Int.min directly (abs(Int.min) overflows). Use a
        // realistic large negative + positive seed instead, which is
        // what hashValue actually produces.
        let opening = p.opening(seed: -987654321)
        let closing = p.closing(seed: 987654321)
        #expect(!opening.isEmpty)
        #expect(!closing.isEmpty)
    }
}

// MARK: - M24 Track 1 — PostRepCoachNoteService deterministic path

struct PostRepCoachNoteServiceDeterministicTests {

    private func makeInput(
        score: Int? = 7,
        fillerCount: Int = 3,
        duration: TimeInterval = 60,
        wordCount: Int = 120,
        voice: SpeakingStyleGoal? = nil,
        baselineFillerRate: Double? = nil,
        baselinePaceWPM: Double? = nil,
        transcript: String = "",
        prompt: String = ""
    ) -> PostRepCoachNoteInput {
        PostRepCoachNoteInput(
            sessionID: UUID(),
            mode: .timed,
            score: score,
            fillerCount: fillerCount,
            duration: duration,
            wordCount: wordCount,
            voice: voice,
            intentLabel: nil,
            baselineFillerRate: baselineFillerRate,
            baselinePaceWPM: baselinePaceWPM,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            transcript: transcript,
            prompt: prompt
        )
    }

    @Test func deterministicNoteIsHonestAboutBeingRuleBased() {
        let note = PostRepCoachNoteService.deterministicNote(input: makeInput())
        #expect(note.isAIBacked == false)
    }

    @Test func noteCarriesGenerationVoice() {
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(voice: .authoritative)
        )
        #expect(note.voice == .authoritative)
    }

    @Test func noteCarriesSessionID() {
        let session = UUID()
        let input = PostRepCoachNoteInput(
            sessionID: session,
            mode: .timed, score: 7, fillerCount: 1,
            duration: 60, wordCount: 100, voice: nil,
            intentLabel: nil, baselineFillerRate: nil, baselinePaceWPM: nil,
            bigMoment: nil, bigMomentDaysUntil: nil
        )
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        #expect(note.sessionID == session)
    }

    @Test func zeroFillersAlwaysCelebratedAsCleanRun() {
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(score: 6, fillerCount: 0, duration: 60, wordCount: 100)
        )
        // The clean-run branch should fire ahead of score-band/pace
        // — "clean" or "zero" should appear somewhere in the text.
        let lower = note.noteText.lowercased()
        #expect(lower.contains("zero") || lower.contains("clean") || lower.contains("no filler") || lower.contains("not a single"))
    }

    @Test func strongScoreCitesScoreNumber() {
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(score: 9, fillerCount: 5, duration: 60, wordCount: 120, baselineFillerRate: 6.0)
        )
        // Score 9 should land somewhere in the note — either explicitly
        // ("scored 9", "an 9", "9 of 10", "9.") or via the filler-win
        // branch since baseline=6, sessionRate=5, ratio<0.83×base — that
        // doesn't trigger win; score takes over.
        #expect(note.noteText.contains("9") || note.noteText.lowercased().contains("repeat"))
    }

    @Test func weakScoreNeverPunishShames() {
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(score: 3, fillerCount: 4, duration: 30, wordCount: 60)
        )
        let lower = note.noteText.lowercased()
        // Brand voice contract — never use 'failure', 'bad', 'poor', etc.
        #expect(!lower.contains("failure"))
        #expect(!lower.contains("bad rep"))
        #expect(!lower.contains("poor"))
        #expect(!lower.contains("terrible"))
    }

    @Test func rushedPaceAcknowledgedWithNumber() {
        // 240 words in 60s = 240 WPM (well over 170 threshold).
        // No score so the pace branch fires.
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(score: nil, fillerCount: 1, duration: 60, wordCount: 240)
        )
        #expect(note.noteText.contains("WPM") || note.noteText.contains("pace") || note.noteText.lowercased().contains("rush"))
    }

    @Test func slowPaceAcknowledgedWithNumber() {
        // 60 words in 60s = 60 WPM (under 95).
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(score: nil, fillerCount: 1, duration: 60, wordCount: 60)
        )
        #expect(note.noteText.contains("WPM") || note.noteText.contains("pace") || note.noteText.lowercased().contains("lift") || note.noteText.lowercased().contains("slow"))
    }

    @Test func shortRepStaysHonestWithoutShaming() {
        // 10s rep. No score. Pace branch doesn't fire (duration < 15s).
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(score: nil, fillerCount: 0, duration: 10, wordCount: 15)
        )
        // 0 fillers + 15 words doesn't trigger the clean-run win (≥20
        // word floor), so the short-rep branch is what we should see.
        let lower = note.noteText.lowercased()
        #expect(lower.contains("short") || lower.contains("brief") || lower.contains("quick") || lower.contains("scene"))
    }

    @Test func noteHasNoExclamationMarks() {
        // Brand-voice contract across many input shapes — sweep voices
        // and score bands to lock the no-exclamation rule.
        let voices: [SpeakingStyleGoal?] = SpeakingStyleGoal.allCases.map { Optional($0) } + [nil]
        for voice in voices {
            for score in [3, 5, 7, 9] {
                for fillers in [0, 3, 8] {
                    let note = PostRepCoachNoteService.deterministicNote(
                        input: makeInput(score: score, fillerCount: fillers, voice: voice)
                    )
                    #expect(!note.noteText.contains("!"), "Voice \(String(describing: voice)) score \(score) fillers \(fillers) has !")
                }
            }
        }
    }

    @Test func noteRespectsLengthCap() {
        // Stress test — every voice + score combo stays ≤ 200 chars.
        let voices: [SpeakingStyleGoal?] = SpeakingStyleGoal.allCases.map { Optional($0) } + [nil]
        for voice in voices {
            for score in [3, 5, 7, 9] {
                let note = PostRepCoachNoteService.deterministicNote(
                    input: makeInput(score: score, voice: voice)
                )
                #expect(note.noteText.count <= 200, "Voice \(String(describing: voice)) score \(score) → \(note.noteText.count) chars")
            }
        }
    }

    @Test func fillerLossBranchFiresWhenSessionRateExceedsBaseline() {
        // Baseline = 2 fillers/min. Session = 10 fillers in 60s = 10/min.
        // Ratio 5× → loss branch fires (≥1.5×, fillers ≥ 3).
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(
                score: 6,
                fillerCount: 10,
                duration: 60,
                wordCount: 120,
                voice: .concise,
                baselineFillerRate: 2.0
            )
        )
        #expect(note.noteText.contains("10"))
        // Concise voice loss branch says "Slow the open"
        #expect(note.noteText.lowercased().contains("slow") || note.noteText.lowercased().contains("open"))
    }

    @Test func fillerWinBranchFiresWhenSessionRateUnderHalfBaseline() {
        // Baseline = 4 fillers/min. Session = 1 filler in 60s = 1/min.
        // Ratio 0.25 → win branch fires (≤0.5× AND filler count ≤ 2).
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(
                score: 7,
                fillerCount: 1,
                duration: 60,
                wordCount: 100,
                voice: .authoritative,
                baselineFillerRate: 4.0
            )
        )
        // Authoritative win text: "well below your usual rate"
        #expect(note.noteText.contains("1"))
        let lower = note.noteText.lowercased()
        #expect(lower.contains("below") || lower.contains("usual") || lower.contains("clean"))
    }

    @Test func brandVoiceContractValidatorRejectsExclamations() {
        #expect(!PostRepCoachNoteService.passesBrandVoiceContract("Great job! That was fast."))
    }

    @Test func brandVoiceContractValidatorRejectsChirpyFiller() {
        #expect(!PostRepCoachNoteService.passesBrandVoiceContract("Awesome. Let's keep going."))
        #expect(!PostRepCoachNoteService.passesBrandVoiceContract("Let's run another rep. That was solid."))
    }

    @Test func brandVoiceContractValidatorAcceptsCleanText() {
        let candidate = "Steady delivery. The fundamentals held."
        #expect(PostRepCoachNoteService.passesBrandVoiceContract(candidate))
    }

    @Test func brandVoiceContractValidatorRejectsOverlongText() {
        let longText = String(repeating: "Steady delivery line. ", count: 30)
        #expect(!PostRepCoachNoteService.passesBrandVoiceContract(longText))
    }

    @Test func collapseWhitespaceMergesRunsAndTrims() {
        let collapsed = PostRepCoachNoteService.collapseWhitespace(in: "  Hello    world.  \n  Coach.   ")
        #expect(collapsed == "Hello world. Coach.")
    }

    @Test func ensureNoExclamationsReplacesWithPeriod() {
        let safe = PostRepCoachNoteService.ensureNoExclamations(in: "Nice rep! Hold the line!")
        #expect(safe == "Nice rep. Hold the line.")
    }

    // MARK: - Prompt-grounded read: defaulted prompt field + presence gate

    /// The new `prompt` field defaults to "" so the 30+ existing fixtures
    /// (which never pass it) still compile, and the deterministic path is
    /// byte-identical (the deterministic note never reads `prompt`).
    @Test func postRepInputPromptFieldDefaultsEmptyFixturesCompile() {
        let input = PostRepCoachNoteInput(
            sessionID: UUID(),
            mode: .timed, score: 7, fillerCount: 1,
            duration: 60, wordCount: 100, voice: nil,
            intentLabel: nil, baselineFillerRate: nil, baselinePaceWPM: nil,
            bigMoment: nil, bigMomentDaysUntil: nil
        )
        #expect(input.prompt == "")
        // Empty transcript -> presence gate passes (nothing to quote).
        #expect(PostRepCoachNoteService.engagesTranscript("Any note about the rep.", input: input))
        // Deterministic note unaffected by the absent prompt.
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        #expect(note.isAIBacked == false)
    }

    @Test func engagesTranscriptSharedContentWordPasses() {
        let input = makeInput(transcript: "I think we should ship the revenue dashboard this week.")
        #expect(PostRepCoachNoteService.engagesTranscript("You opened with the revenue point cleanly.", input: input))
    }

    @Test func engagesTranscriptVerbatimSubstringPasses() {
        // The transcript's content words are all short function words that the
        // >=4-char content-word filter drops, so path 1 (shared content word)
        // can't fire — but the note contains a >=12-char verbatim slice
        // ("can do it now"), so path 2 must. Isolates the substring branch.
        let input = makeInput(transcript: "We can do it now and we will.")
        let note = "You said you can do it now, so commit to that."
        #expect(PostRepCoachNoteService.engagesTranscript(note, input: input))
    }

    @Test func engagesTranscriptStatRestateOnlyFailsFallsBack() {
        let input = makeInput(transcript: "We launched the new onboarding flow to all customers today.")
        // Pure stat-restate: zero shared content words, no verbatim slice.
        #expect(!PostRepCoachNoteService.engagesTranscript("Scored 7. The fundamentals held.", input: input))
    }

    @Test func engagesTranscriptEmptyTranscriptPasses() {
        let input = makeInput(transcript: "")
        // Nothing to quote — the gate must not block IM/silent reps.
        #expect(PostRepCoachNoteService.engagesTranscript("Any abstract coaching note.", input: input))
    }

    // MARK: - Prompt-grounded read: userPrompt question injection

    @Test func postRepUserPromptInjectsQuestionWhenPresent() {
        let input = makeInput(
            transcript: "We should ship because the data is clear.",
            prompt: "Should we ship the feature this week?"
        )
        let user = PostRepCoachNoteService.userPrompt(from: input)
        #expect(user.contains("THE QUESTION ASKED: Should we ship the feature this week?"))
        // The question line lands before the transcript block.
        if let qRange = user.range(of: "THE QUESTION ASKED:"),
           let tRange = user.range(of: "THIS REP — TRANSCRIPT") {
            #expect(qRange.lowerBound < tRange.lowerBound)
        } else {
            Issue.record("Expected both the question line and the transcript block in the prompt")
        }
    }

    @Test func postRepUserPromptOmitsQuestionWhenEmpty() {
        let input = makeInput(
            transcript: "We should ship because the data is clear.",
            prompt: ""
        )
        let user = PostRepCoachNoteService.userPrompt(from: input)
        // Match the injected line specifically (colon+space) — the transcript-block
        // header also contains the bare phrase "THE QUESTION ASKED" without a colon.
        #expect(!user.contains("THE QUESTION ASKED: "))
        // No stray blank-only artefact from an omitted question.
        #expect(!user.contains("\n\n\n"))
    }
}

// MARK: - Initiative #9 — Coach Read parity (AICoachService deepening)
//
// Tests the deterministic-observable seams of the deepened "Coach Read"
// (AICoachService.generateDeeperFeedback): the deterministic fallback that runs
// offline / non-English / on every gated failure, the transcript-grounding
// gate, the brand-voice contract, the schema-decode stability, the defaulted-
// init back-compat, the question-aware user prompt, and the pure call-site
// helpers (recent-summaries + baseline extraction). It does NOT test live
// model output (no LLM on the build host) — only the substrate that determines
// whether the read is grounded, honest, well-formed, and never worse offline.

struct CoachReadParityTests {

    private func makeInput(
        transcript: String = "Here is the core of what I want to say today.",
        mode: PracticeMode = .timed,
        score: Int? = 7,
        fillerCount: Int = 2,
        duration: TimeInterval = 60,
        wordsPerMinute: Int = 130,
        speakingIdentity: String = "Composed speaker",
        prompt: String = "",
        voice: SpeakingStyleGoal? = nil,
        recentSessionSummaries: [String] = [],
        baselineFillerRate: Double? = nil,
        baselinePaceWPM: Double? = nil,
        standingHypothesis: String? = nil,
        standingObservableTarget: String? = nil,
        standingSuccessMeasure: String? = nil,
        standingReviewDueAt: Date? = nil
    ) -> AICoachSessionInput {
        AICoachSessionInput(
            transcript: transcript,
            mode: mode,
            score: score,
            fillerCount: fillerCount,
            duration: duration,
            wordsPerMinute: wordsPerMinute,
            speakingIdentity: speakingIdentity,
            prompt: prompt,
            voice: voice,
            recentSessionSummaries: recentSessionSummaries,
            baselineFillerRate: baselineFillerRate,
            baselinePaceWPM: baselinePaceWPM,
            standingHypothesis: standingHypothesis,
            standingObservableTarget: standingObservableTarget,
            standingSuccessMeasure: standingSuccessMeasure,
            standingReviewDueAt: standingReviewDueAt
        )
    }

    // 1. deterministicFeedback is always well-formed across the input space.
    @Test func deterministicFeedbackIsAlwaysWellFormed() {
        let voices: [SpeakingStyleGoal?] = SpeakingStyleGoal.allCases.map { Optional($0) } + [nil]
        for voice in voices {
            for score in [nil, 3, 5, 7, 9] {
                for fillers in [0, 3, 8] {
                    let fb = AICoachService.deterministicFeedback(
                        input: makeInput(score: score, fillerCount: fillers, voice: voice)
                    )
                    #expect(fb.strengths.count == 2,
                            "voice \(String(describing: voice)) score \(String(describing: score)) fillers \(fillers): strengths=\(fb.strengths.count)")
                    #expect(fb.strengths.allSatisfy { !$0.trimmingCharacters(in: .whitespaces).isEmpty })
                    #expect(!fb.keyImprovement.trimmingCharacters(in: .whitespaces).isEmpty)
                    #expect(!fb.suggestedDrill.trimmingCharacters(in: .whitespaces).isEmpty)
                }
            }
        }
    }

    // 2. deterministicFeedback honors the brand-voice contract across the sweep.
    @Test func deterministicFeedbackHonorsBrandVoiceContract() {
        let voices: [SpeakingStyleGoal?] = SpeakingStyleGoal.allCases.map { Optional($0) } + [nil]
        for voice in voices {
            for score in [nil, 3, 5, 7, 9] {
                for fillers in [0, 3, 8] {
                    let fb = AICoachService.deterministicFeedback(
                        input: makeInput(score: score, fillerCount: fillers, voice: voice)
                    )
                    #expect(AICoachService.passesBrandVoiceContract(fb),
                            "voice \(String(describing: voice)) score \(String(describing: score)) fillers \(fillers) violates brand voice")
                    // Explicit no-exclamation / no-chirp sweep over every field.
                    for field in fb.strengths + [fb.keyImprovement, fb.suggestedDrill, fb.revisedOpening] {
                        let lower = field.lowercased()
                        #expect(!field.contains("!"))
                        #expect(!lower.contains("awesome"))
                        #expect(!lower.contains("great job"))
                        #expect(!lower.contains("let's"))
                        #expect(!lower.contains("lets "))
                    }
                }
            }
        }
    }

    // 3. .answered (point led) -> "engaged the question directly" keyImprovement.
    @Test func deterministicVerdictAnsweredLeadsToAnsweredKeyImprovement() {
        // Prompt content words (>=4, non-stop): adopt, four, work, week, policy.
        let prompt = "Should we adopt a four day work week policy"
        // Single-sentence answer that LEADS with adopt + policy + work + week
        // (lead overlap 4/5 = 0.80 >= strong), and >= 12 words.
        let transcript = "We should adopt the policy because the data shows work output stays strong across the week."
        let read = PracticeEvaluator.promptRelevance(prompt: prompt, transcript: transcript)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: read) == .answered)

        let fb = AICoachService.deterministicFeedback(
            input: makeInput(transcript: transcript, prompt: prompt)
        )
        let lower = fb.keyImprovement.lowercased()
        #expect(lower.contains("engaged the question directly"))
        #expect(lower.contains("led with the point"))
        #expect(!lower.contains("arrived late"))
    }

    // 4. .buried (point present but late) -> lead-with-the-point keyImprovement.
    @Test func deterministicVerdictBuriedLeadsToLeadWithPointKeyImprovement() {
        let prompt = "Should we adopt a four day work week policy"
        // Genuine buried lede: the lead echoes none of the question's key terms
        // ("There are a lot of competing pressures…" -> lead overlap 0/5), but
        // the point IS present in the final clause (whole overlap 5/5). This is
        // the only configuration that earns the positional "arrived late" copy
        // — and now it is TRUE, not asserted. Pre-#10 this branch fired for any
        // low-overlap rep, including off-topic ones where the point never
        // arrived at all (the honesty mismatch this slice closes).
        let transcript = "There are a lot of competing pressures on the calendar right now and people are stretched. After thinking it through carefully I would adopt the four day work week policy."
        let read = PracticeEvaluator.promptRelevance(prompt: prompt, transcript: transcript)
        #expect(read.overlap >= PracticeEvaluator.relevanceStrongOverlap)
        #expect(read.firstSentenceOverlap < PracticeEvaluator.relevanceWeakOverlap)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: read) == .buried)

        let fb = AICoachService.deterministicFeedback(
            input: makeInput(transcript: transcript, prompt: prompt)
        )
        let lower = fb.keyImprovement.lowercased()
        #expect(lower.contains("lead with your point"))
        #expect(lower.contains("arrived late"))
    }

    // 4b. Off-topic low-overlap rep -> `.partial`, and the deterministic copy
    // must NOT claim "arrived late" (the point never arrived). The honesty fix.
    @Test func deterministicOffTopicLowOverlapDoesNotClaimArrivedLate() {
        let prompt = "Should we adopt a four day work week policy"
        // Different topic — zero content-word overlap, but >= 12 words.
        let transcript = "Yesterday morning the garden looked lovely after the rain and the birds were singing softly outside."
        let read = PracticeEvaluator.promptRelevance(prompt: prompt, transcript: transcript)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: read) == .partial)

        let fb = AICoachService.deterministicFeedback(
            input: makeInput(transcript: transcript, prompt: prompt)
        )
        let lower = fb.keyImprovement.lowercased()
        #expect(!lower.contains("arrived late"))
        // Still coaches leading with the point — the constructive move applies.
        #expect(lower.contains("first sentence"))
    }

    // 5. No substance claim below the evidence floor (no fake certainty).
    @Test func deterministicNoSubstanceClaimBelowEvidenceFloor() {
        // (a) Empty prompt -> verdict nil regardless of transcript length.
        let longTranscript = "We should adopt the policy because the data shows work output stays strong across the week."
        let readNoPrompt = PracticeEvaluator.promptRelevance(prompt: nil, transcript: longTranscript)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: readNoPrompt) == nil)
        let fbNoPrompt = AICoachService.deterministicFeedback(
            input: makeInput(transcript: longTranscript, prompt: "")
        )
        let lowerA = fbNoPrompt.keyImprovement.lowercased()
        #expect(!lowerA.contains("engaged the question"))
        #expect(!lowerA.contains("arrived late"))
        #expect(!lowerA.contains("lead with your point"))

        // (b) Thin transcript (< 12 words) -> verdict nil even with a prompt.
        let thin = "Yes I think so."
        let prompt = "Should we adopt a four day work week policy"
        let readThin = PracticeEvaluator.promptRelevance(prompt: prompt, transcript: thin)
        #expect(PracticeEvaluator.promptAnswerVerdict(for: readThin) == nil)
        let fbThin = AICoachService.deterministicFeedback(
            input: makeInput(transcript: thin, wordsPerMinute: 180, prompt: prompt)
        )
        let lowerB = fbThin.keyImprovement.lowercased()
        #expect(!lowerB.contains("engaged the question"))
        #expect(!lowerB.contains("arrived late"))
    }

    // 6. Quotes the opener when present; never fabricates one when absent.
    @Test func deterministicQuotesOpenerWhenPresent() {
        let transcript = "Productivity research is genuinely complicated to summarise."
        let fb = AICoachService.deterministicFeedback(
            input: makeInput(transcript: transcript, voice: .executive)
        )
        // strengths[0] or revisedOpening should carry a verbatim slice of the
        // opener — "productivity" is a long content word from the first line.
        let joined = (fb.strengths.first ?? "") + " " + fb.revisedOpening
        #expect(joined.lowercased().contains("productivity"))

        // Too-short transcript -> no fabricated quote, empty revisedOpening.
        let shortFb = AICoachService.deterministicFeedback(
            input: makeInput(transcript: "Yes.", score: nil, fillerCount: 0)
        )
        #expect(shortFb.revisedOpening.isEmpty)
    }

    // 7. engagesTranscript rejects a stat-restate that ignores the words.
    @Test func engagesTranscriptRejectsStatRestate() {
        let transcript = "Our quarterly revenue pipeline needs a tighter forecast model."
        let fb = AICoachFeedback(
            strengths: ["Clean delivery."],
            keyImprovement: "Work on structure and confidence.",
            suggestedDrill: "Practice pausing.",
            revisedOpening: "Open with the main idea."
        )
        #expect(AICoachService.engagesTranscript(fb, transcript: transcript) == false)
    }

    // 8. engagesTranscript accepts a shared content word, a verbatim slice, and
    //    an empty transcript.
    @Test func engagesTranscriptAcceptsSharedContentWord() {
        let transcript = "Our quarterly revenue pipeline needs a tighter forecast model."
        // Shared content word "pipeline" in keyImprovement.
        let sharedWord = AICoachFeedback(
            strengths: ["Clean delivery."],
            keyImprovement: "Your point about the pipeline was the strongest moment.",
            suggestedDrill: "Practice pausing.",
            revisedOpening: ""
        )
        #expect(AICoachService.engagesTranscript(sharedWord, transcript: transcript) == true)

        // A revisedOpening that quotes a verbatim phrase of the transcript
        // passes (here via both the shared content word and the >= 12-char
        // slice "quarterly re…" — either path returns true).
        let verbatim = AICoachFeedback(
            strengths: ["Clean delivery."],
            keyImprovement: "Lead sooner.",
            suggestedDrill: "Practice pausing.",
            revisedOpening: "Open on the quarterly revenue, then the model."
        )
        #expect(AICoachService.engagesTranscript(verbatim, transcript: transcript) == true)

        // Empty transcript -> never blocks.
        #expect(AICoachService.engagesTranscript(sharedWord, transcript: "") == true)
        #expect(AICoachService.engagesTranscript(sharedWord, transcript: "   ") == true)
    }

    // 9. passesBrandVoiceContract rejects exclamation + chirp; accepts clean.
    @Test func passesBrandVoiceContractRejectsExclamationAndChirp() {
        let clean = AICoachFeedback(
            strengths: ["You opened with conviction.", "Pace stayed steady."],
            keyImprovement: "Tighten the close so the last line lands.",
            suggestedDrill: "Pause between your two strongest points.",
            revisedOpening: "Lead with the conclusion, then support it."
        )
        #expect(AICoachService.passesBrandVoiceContract(clean) == true)

        let exclamation = AICoachFeedback(
            strengths: ["Great rep!", "Pace stayed steady."],
            keyImprovement: "Tighten the close.",
            suggestedDrill: "Pause more.",
            revisedOpening: ""
        )
        #expect(AICoachService.passesBrandVoiceContract(exclamation) == false)

        let chirp = AICoachFeedback(
            strengths: ["You opened well.", "Pace steady."],
            keyImprovement: "Awesome work — keep it up.",
            suggestedDrill: "Pause more.",
            revisedOpening: ""
        )
        #expect(AICoachService.passesBrandVoiceContract(chirp) == false)

        let lets = AICoachFeedback(
            strengths: ["You opened well.", "Pace steady."],
            keyImprovement: "Tighten the close.",
            suggestedDrill: "Let's practice pausing.",
            revisedOpening: ""
        )
        #expect(AICoachService.passesBrandVoiceContract(lets) == false)

        let greatJob = AICoachFeedback(
            strengths: ["Great job on the open.", "Pace steady."],
            keyImprovement: "Tighten the close.",
            suggestedDrill: "Pause more.",
            revisedOpening: ""
        )
        #expect(AICoachService.passesBrandVoiceContract(greatJob) == false)
    }

    // 10. The wire schema the render path depends on decodes unchanged.
    @Test func aiCoachFeedbackSchemaDecodesUnchanged() throws {
        let json = #"{"strengths":["a","b"],"keyImprovement":"x","suggestedDrill":"y","revisedOpening":"z"}"#
        let data = json.data(using: .utf8)!
        let fb = try JSONDecoder().decode(AICoachFeedback.self, from: data)
        #expect(fb.strengths == ["a", "b"])
        #expect(fb.keyImprovement == "x")
        #expect(fb.suggestedDrill == "y")
        #expect(fb.revisedOpening == "z")
    }

    // 11. The old 7-arg positional construction still compiles and defaults
    //     the new fields. (Compile-guard for the defaulted init.)
    @Test func inputDefaultsKeepLegacyConstructionCompiling() {
        let input = AICoachSessionInput(
            transcript: "Hello there friends",
            mode: .timed,
            score: 5,
            fillerCount: 1,
            duration: 30,
            wordsPerMinute: 120,
            speakingIdentity: "Speaker"
        )
        #expect(input.prompt == "")
        #expect(input.voice == nil)
        #expect(input.recentSessionSummaries.isEmpty)
        #expect(input.baselineFillerRate == nil)
        #expect(input.baselinePaceWPM == nil)
        // SUBSTANCE-4 standing-case fields also default to nil.
        #expect(input.standingHypothesis == nil)
        #expect(input.standingObservableTarget == nil)
        #expect(input.standingSuccessMeasure == nil)
        #expect(input.standingReviewDueAt == nil)
    }

    // 12. The user prompt omits the question / continuity / baseline lines when
    //     those inputs are absent (no placeholder injected).
    @Test func userPromptOmitsQuestionAndContinuityWhenAbsent() {
        let input = makeInput(prompt: "", recentSessionSummaries: [],
                              baselineFillerRate: nil, baselinePaceWPM: nil)
        let user = AICoachService.userPrompt(
            input: input, profile: nil, plan: nil, baselineContext: ""
        )
        // No injected QUESTION ASKED line (colon-qualified — the transcript-block
        // header also contains the bare phrase without the prompt value).
        #expect(!user.contains("THE QUESTION ASKED: "))
        #expect(!user.contains("RECENT REPS"))
        #expect(!user.contains("Baseline filler rate:"))
        #expect(!user.contains("Baseline pace:"))
        // No STANDING CASE block when all four standing fields are nil.
        #expect(!user.contains("STANDING CASE"))
        #expect(!user.contains("Working hypothesis:"))
        #expect(!user.contains("Observable target:"))
        #expect(!user.contains("Success measure:"))
        #expect(!user.contains("Review cadence:"))
        // No stray blank-block artefact.
        #expect(!user.contains("\n\n\n"))
    }

    // 13. The user prompt surfaces the question + register + grounding
    //     instruction when present.
    @Test func userPromptSurfacesQuestionAndRegisterWhenPresent() {
        let input = makeInput(
            transcript: "Productivity is complicated.",
            prompt: "Should we adopt a four day work week",
            voice: .executive,
            recentSessionSummaries: ["Timed | score 6/10 | 3 fillers"]
        )
        let user = AICoachService.userPrompt(
            input: input, profile: nil, plan: nil, baselineContext: ""
        )
        #expect(user.contains("THE QUESTION ASKED: Should we adopt a four day work week"))
        // The executive register clause is surfaced.
        #expect(user.contains(AIInsightsService.registerClause(for: .executive)))
        // The transcript block carries the answered / where-the-point-landed
        // grounding instruction.
        #expect(user.contains("answered THE QUESTION ASKED and where the main point landed"))
        // Continuity block present.
        #expect(user.contains("RECENT REPS (continuity, never invent):"))
        #expect(user.contains("- Timed | score 6/10 | 3 fillers"))
        // Mode uses the display label, not the rawValue.
        #expect(user.contains("Mode: Timed"))
    }

    // 13b. (SUBSTANCE-4) The user prompt surfaces the STANDING CASE block with
    //      the standing hypothesis / observable target / success measure /
    //      review cadence when those durable-context fields are present.
    @Test func userPromptSurfacesStandingCaseWhenPresent() {
        let input = makeInput(
            transcript: "Productivity is complicated.",
            standingHypothesis: "Leads strong but buries the ask under hedging.",
            standingObservableTarget: "State the ask in the first sentence.",
            standingSuccessMeasure: "Ask lands in sentence one for 3 reps.",
            standingReviewDueAt: Calendar.current.date(byAdding: .day, value: 2, to: Date())
        )
        let user = AICoachService.userPrompt(
            input: input, profile: nil, plan: nil, baselineContext: ""
        )
        #expect(user.contains("STANDING CASE (the user's current goal/target — reason over this, not just this rep):"))
        #expect(user.contains("Working hypothesis: Leads strong but buries the ask under hedging."))
        #expect(user.contains("Observable target: State the ask in the first sentence."))
        #expect(user.contains("Success measure: Ask lands in sentence one for 3 reps."))
        #expect(user.contains("Review cadence: revisit by"))
        // No stray blank-block artefact.
        #expect(!user.contains("\n\n\n"))
    }

    // 13c. (SUBSTANCE-4) Each STANDING CASE component is independently omitted
    //      when its source field is nil — a hypothesis with no active
    //      intervention surfaces only the hypothesis line, not target/measure.
    @Test func userPromptStandingCaseOmitsMissingComponents() {
        let input = makeInput(
            standingHypothesis: "Tends to over-qualify before the point.",
            standingObservableTarget: nil,
            standingSuccessMeasure: nil
        )
        let user = AICoachService.userPrompt(
            input: input, profile: nil, plan: nil, baselineContext: ""
        )
        #expect(user.contains("STANDING CASE (the user's current goal/target — reason over this, not just this rep):"))
        #expect(user.contains("Working hypothesis: Tends to over-qualify before the point."))
        #expect(!user.contains("Observable target:"))
        #expect(!user.contains("Success measure:"))
        #expect(!user.contains("Review cadence:"))
    }

    // 13d. (SUBSTANCE-4) Byte-identical omission: the user prompt with all
    //      standing fields nil is exactly the prompt that never had them — the
    //      STANDING CASE block adds nothing when empty.
    @Test func userPromptStandingCaseOmittedByteIdenticalWhenAllNil() {
        let withNilStanding = makeInput(
            transcript: "A grounded line about the topic.",
            prompt: "Should we adopt the policy",
            voice: .executive,
            standingHypothesis: nil,
            standingObservableTarget: nil,
            standingSuccessMeasure: nil,
            standingReviewDueAt: nil
        )
        let baseline = makeInput(
            transcript: "A grounded line about the topic.",
            prompt: "Should we adopt the policy",
            voice: .executive
        )
        let a = AICoachService.userPrompt(
            input: withNilStanding, profile: nil, plan: nil, baselineContext: ""
        )
        let b = AICoachService.userPrompt(
            input: baseline, profile: nil, plan: nil, baselineContext: ""
        )
        #expect(a == b)
    }

    // 13e. (SUBSTANCE-4) The AI coach read uses the same short relative
    //      review-cadence language as the case-file context builder.
    @Test func standingReviewCadenceUsesSharedRelativeCaseFileLanguage() {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(secondsFromGMT: 0)!
        let now = calendar.date(from: DateComponents(
            year: 2026, month: 6, day: 8, hour: 12
        ))!

        #expect(CoachContextBuilder.caseReviewLabel(for: now, now: now, calendar: calendar) == "today")
        #expect(CoachContextBuilder.caseReviewLabel(
            for: calendar.date(byAdding: .day, value: 1, to: now)!,
            now: now,
            calendar: calendar
        ) == "tomorrow")
        #expect(CoachContextBuilder.caseReviewLabel(
            for: calendar.date(byAdding: .day, value: 3, to: now)!,
            now: now,
            calendar: calendar
        ) == "in 3 days")
        #expect(CoachContextBuilder.caseReviewLabel(
            for: calendar.date(byAdding: .day, value: -1, to: now)!,
            now: now,
            calendar: calendar
        ) == "now (review overdue)")
    }

    // 13f. (SUBSTANCE-4) The systemPrompt carries the standing-target rubric
    //      line that keeps the standing case as a hypothesis to test, never an
    //      assertion the target was hit this rep without transcript support.
    @Test func systemPromptCarriesStandingCaseRubricLine() {
        let prompt = AICoachService.systemPrompt(persona: CoachPersona.persona(for: .executive))
        #expect(prompt.contains("STANDING CASE. If a STANDING CASE is given"))
        #expect(prompt.contains("standing target/measure/review cadence"))
        #expect(prompt.contains("never assert the"))
        // The standing case is framed as a hypothesis to test, never causation.
        #expect(prompt.contains("treat it as the hypothesis you are testing"))
    }

    // 14. recentSessionSummaries excludes the current rep and is bounded to 3.
    @Test func summaryViewRecentSummariesExcludeCurrentRep() {
        let currentID = UUID()
        let now = Date()
        let current = PracticeSession(
            id: currentID, transcript: "current", fillerWordCount: 9,
            duration: 60, date: now, mode: .timed, score: 9
        )
        let prior1 = PracticeSession(
            id: UUID(), transcript: "p1", fillerWordCount: 1,
            duration: 60, date: now, mode: .timed, score: 8
        )
        let prior2 = PracticeSession(
            id: UUID(), transcript: "p2", fillerWordCount: 2,
            duration: 60, date: now, mode: .suddenDeath, score: 7
        )
        let prior3 = PracticeSession(
            id: UUID(), transcript: "p3", fillerWordCount: 3,
            duration: 60, date: now, mode: .timed, score: nil
        )
        let prior4 = PracticeSession(
            id: UUID(), transcript: "p4", fillerWordCount: 4,
            duration: 60, date: now, mode: .timed, score: 5
        )
        let summaries = AICoachService.recentSessionSummaries(
            sessions: [current, prior1, prior2, prior3, prior4],
            currentRepID: currentID
        )
        // Bounded to 3, current rep dropped (no "9 fillers" self-reference).
        #expect(summaries.count == 3)
        #expect(!summaries.contains { $0.contains("9 filler") })
        // Shape: "Mode | score X/10 | N fillers", singular for 1.
        #expect(summaries[0] == "Timed Practice | score 8/10 | 1 filler")
        #expect(summaries[1] == "Pressure Drill | score 7/10 | 2 fillers")
        #expect(summaries[2] == "Timed Practice | score n/a | 3 fillers")
    }

    // 15. Baseline extraction returns nil on insufficient confidence, value
    //     otherwise (mirrors PracticeSupport.swift:7182-7185 — the gate the
    //     call site applies so the prompt never shows a fake baseline number).
    @Test func baselineExtractionReturnsNilOnInsufficientConfidence() {
        func extract(_ stat: BaselineStat) -> Double? {
            stat.confidence == .insufficient ? nil : stat.value
        }
        let insufficient = BaselineStat(
            value: 4.2, sampleCount: 1, confidence: .insufficient,
            trend: .stable, percentile25: 0, percentile75: 0
        )
        let moderate = BaselineStat(
            value: 4.2, sampleCount: 6, confidence: .moderate,
            trend: .stable, percentile25: 0, percentile75: 0
        )
        #expect(extract(insufficient) == nil)
        #expect(extract(moderate) == 4.2)
    }
}

// MARK: - M24 Track 1 — PostRepCoachNoteStore persistence

@MainActor
struct PostRepCoachNoteStoreTests {

    private func freshStore() -> PostRepCoachNoteStore {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        return PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "tester" })
    }

    @Test func recordAndFetchRoundTrip() {
        let store = freshStore()
        let sessionID = UUID()
        let note = PostRepCoachNote(
            sessionID: sessionID,
            voice: .warm,
            noteText: "Steady rep — the foundation is doing its work.",
            isAIBacked: false
        )
        store.record(note)
        let fetched = store.note(for: sessionID)
        #expect(fetched?.noteText == note.noteText)
        #expect(fetched?.voice == .warm)
    }

    @Test func recordDedupesOnSessionID() {
        // Re-recording the same session (deterministic → AI upgrade)
        // should replace the previous entry, not stack.
        let store = freshStore()
        let sessionID = UUID()
        let deterministic = PostRepCoachNote(
            sessionID: sessionID, voice: .concise,
            noteText: "Steady. Hold the line.", isAIBacked: false
        )
        let aiUpgrade = PostRepCoachNote(
            sessionID: sessionID, voice: .concise,
            noteText: "Tight rep. The pace held under pressure.", isAIBacked: true
        )
        store.record(deterministic)
        store.record(aiUpgrade)
        #expect(store.notes.count == 1)
        #expect(store.note(for: sessionID)?.isAIBacked == true)
    }

    @Test func capacityEvictsOldestByGeneratedAt() {
        let store = freshStore()
        let cap = PostRepCoachNoteStore.capacity
        // Create cap+1 notes with ascending generatedAt timestamps.
        for offset in 0..<(cap + 1) {
            let note = PostRepCoachNote(
                sessionID: UUID(),
                voice: nil,
                noteText: "Steady rep \(offset). The fundamentals held.",
                isAIBacked: false,
                generatedAt: Date(timeIntervalSince1970: TimeInterval(offset))
            )
            store.record(note)
        }
        #expect(store.notes.count == cap)
        // Oldest (offset=0) should be evicted; newest (offset=cap) retained.
        let oldestText = "Steady rep 0. The fundamentals held."
        let newestText = "Steady rep \(cap). The fundamentals held."
        #expect(!store.notes.contains { $0.noteText == oldestText })
        #expect(store.notes.contains { $0.noteText == newestText })
    }

    @Test func latestNoteReturnsHighestGeneratedAt() {
        let store = freshStore()
        let older = PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Older note. Fundamentals held.",
            isAIBacked: false,
            generatedAt: Date(timeIntervalSince1970: 100)
        )
        let newer = PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Newer note. The line moved.",
            isAIBacked: false,
            generatedAt: Date(timeIntervalSince1970: 200)
        )
        store.record(older)
        store.record(newer)
        #expect(store.latestNote()?.noteText == "Newer note. The line moved.")
    }

    @Test func activeReadsRequireExactChosenVoiceCompatibility() {
        let store = freshStore()
        let conciseID = UUID()
        let genericID = UUID()
        store.record(PostRepCoachNote(
            sessionID: conciseID,
            voice: .concise,
            noteText: "Tighten the concise line.",
            isAIBacked: false,
            generatedAt: Date(timeIntervalSince1970: 200)
        ))
        store.record(PostRepCoachNote(
            sessionID: genericID,
            voice: nil,
            noteText: "Keep the next rep measured.",
            isAIBacked: false,
            generatedAt: Date(timeIntervalSince1970: 100)
        ))

        #expect(store.note(for: conciseID, chosenStyleGoal: nil) == nil)
        #expect(store.note(for: conciseID, chosenStyleGoal: .concise)?.sessionID == conciseID)
        #expect(store.latestNote(chosenStyleGoal: nil)?.sessionID == genericID)
        #expect(store.latestNote(chosenStyleGoal: .warm) == nil)
    }

    @Test func clearAllEmptiesStore() {
        let store = freshStore()
        store.record(PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Steady delivery. The fundamentals held.",
            isAIBacked: false
        ))
        #expect(store.notes.count == 1)
        store.clearAll()
        #expect(store.notes.isEmpty)
    }

    @Test func deleteAllDataWipesByAccountID() {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let store = PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "alpha" })
        store.record(PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Steady delivery. The fundamentals held.",
            isAIBacked: false
        ))
        #expect(store.notes.count == 1)
        store.deleteAllData(for: "alpha")
        #expect(store.notes.isEmpty)
    }

    @Test func perAccountKeyIsolation() {
        // Two stores against the SAME UserDefaults suite but different
        // account IDs must not see each other's notes.
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let alpha = PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "alpha" })
        let beta  = PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "beta" })
        alpha.record(PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Alpha rep. Steady delivery.",
            isAIBacked: false
        ))
        #expect(alpha.notes.count == 1)
        #expect(beta.notes.isEmpty)
    }

    @Test func reloadForCurrentAccountReadsPersistedNotes() {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let writer = PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "shared" })
        let sessionID = UUID()
        writer.record(PostRepCoachNote(
            sessionID: sessionID, voice: .concise,
            noteText: "Steady. Hold the line.",
            isAIBacked: false
        ))
        // Build a fresh store against the same suite + account — should
        // load the persisted note from disk.
        let reader = PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "shared" })
        #expect(reader.note(for: sessionID)?.noteText == "Steady. Hold the line.")
    }

    @Test func endSessionClearsInMemoryWithoutErasingDisk() {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let store = PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "tester" })
        store.record(PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Steady delivery. The fundamentals held.",
            isAIBacked: false
        ))
        store.endSession()
        #expect(store.notes.isEmpty)
        // Disk still has the note — a fresh store re-loads it.
        let reloaded = PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "tester" })
        #expect(reloaded.notes.count == 1)
    }
}

// MARK: - M24 Track 1 — CoachContext LAST REP NOTE section

struct CoachContextLastRepNoteTests {

    private func minimalContext(latestRepNote: PostRepCoachNote?) -> String {
        CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            recentProofs: [],
            bigMoment: nil,
            forwardPlan: nil,
            latestRepNote: latestRepNote
        )
    }

    @Test func lastRepNoteSectionOmittedWhenNil() {
        let context = minimalContext(latestRepNote: nil)
        #expect(!context.contains("LAST REP NOTE"))
    }

    @Test func lastRepNoteSectionPresentWhenSet() {
        let note = PostRepCoachNote(
            sessionID: UUID(),
            voice: nil,
            noteText: "Steady rep. The foundation held.",
            isAIBacked: false
        )
        let context = minimalContext(latestRepNote: note)
        #expect(context.contains("LAST REP NOTE"))
        #expect(context.contains("Steady rep. The foundation held."))
    }

    @Test func staleVoiceRepNoteIsWithheldFromCoachContext() {
        let note = PostRepCoachNote(
            sessionID: UUID(),
            voice: .concise,
            noteText: "Keep building the concise voice.",
            isAIBacked: false
        )
        let context = minimalContext(latestRepNote: note)
        #expect(!context.contains("LAST REP NOTE"))
        #expect(!context.localizedCaseInsensitiveContains("concise voice"))
    }

    @Test func lastRepNoteSurfacesProvenance() {
        // AI-backed note labels accordingly; rule-based note labels
        // accordingly. Coach reads this to know whether the prior
        // read came from a model or a template.
        let aiNote = PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Steady delivery. The fundamentals held.",
            isAIBacked: true
        )
        let ctxAI = minimalContext(latestRepNote: aiNote)
        #expect(ctxAI.contains("AI-generated"))

        let ruleNote = PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Steady delivery. The fundamentals held.",
            isAIBacked: false
        )
        let ctxRule = minimalContext(latestRepNote: ruleNote)
        #expect(ctxRule.contains("rule-based"))
    }

    @Test func lastRepNoteSitsBeforePathSection() {
        // Context ordering contract: LAST REP NOTE → PATH so the
        // coach reads its prior rep read before the journey context.
        let note = PostRepCoachNote(
            sessionID: UUID(), voice: nil,
            noteText: "Steady delivery. The fundamentals held.",
            isAIBacked: false
        )
        let context = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            recentProofs: [],
            bigMoment: nil,
            forwardPlan: nil,
            latestRepNote: note
        )
        // No PATH status set so PATH won't render — but the LAST REP
        // NOTE block must exist before === END CONTEXT ===.
        let noteIdx = context.range(of: "LAST REP NOTE")?.lowerBound
        let endIdx = context.range(of: "=== END CONTEXT ===")?.lowerBound
        #expect(noteIdx != nil)
        #expect(endIdx != nil)
        if let noteIdx, let endIdx {
            #expect(noteIdx < endIdx)
        }
    }
}

// MARK: - M24 Track 3 — SuddenDeathRunHistoryStore
//
// Per-account, bounded persistence for completed Sudden Death runs.
// Same testable-init pattern as PostRepCoachNoteStore — a custom
// UserDefaults suite + account-ID provider closure means we never
// touch KeychainHelper or the live shared singleton, so suites can
// run in parallel without state bleed.
//
// Contract being locked here:
//   - Record + fetch round-trip preserves every field
//   - De-dupe on `id` (idempotent against double-mount)
//   - Capacity caps at the documented value, evicting oldest by
//     `completedAt`
//   - `recentRuns(difficulty:limit:)` filters AND honors the limit
//   - Per-account key isolation — two stores against the same suite
//     but different account IDs never see each other's runs
//   - Lifecycle (reload, endSession, deleteAllData) behaves the same
//     way the rest of the per-account stores do
//   - RoundOutcome encode/decode round-trips every case

@MainActor
struct SuddenDeathRunHistoryStoreTests {

    private func freshStore() -> SuddenDeathRunHistoryStore {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        return SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "tester" })
    }

    private func sampleRun(
        difficulty: SuddenDeathDifficulty = .medium,
        rounds: Int = 4,
        completedAt: Date = Date(),
        wasNewBest: Bool = false
    ) -> SuddenDeathRunRecord {
        SuddenDeathRunRecord(
            completedAt: completedAt,
            difficulty: difficulty,
            roundsSurvived: rounds,
            totalFillers: 1,
            totalWords: 80,
            score: 7,
            xpEarned: 120,
            finalOutcome: .survived,
            wasNewBestAtTime: wasNewBest
        )
    }

    @Test @MainActor func recordAndFetchRoundTrip() {
        let store = freshStore()
        let run = sampleRun(difficulty: .hard, rounds: 6, wasNewBest: true)
        store.record(run)
        let fetched = store.recentRuns(difficulty: .hard)
        #expect(fetched.count == 1)
        #expect(fetched.first?.id == run.id)
        #expect(fetched.first?.roundsSurvived == 6)
        #expect(fetched.first?.wasNewBestAtTime == true)
    }

    @Test @MainActor func recordDedupesOnID() {
        // Same record id recorded twice replaces rather than stacks —
        // guards against a fast double-mount of the result view firing
        // recordRun twice.
        let store = freshStore()
        let id = UUID()
        let first = SuddenDeathRunRecord(
            id: id, completedAt: Date(timeIntervalSince1970: 100),
            difficulty: .medium, roundsSurvived: 3, totalFillers: 2,
            totalWords: 40, score: 5, xpEarned: 60,
            finalOutcome: .fillerOverload, wasNewBestAtTime: false
        )
        let second = SuddenDeathRunRecord(
            id: id, completedAt: Date(timeIntervalSince1970: 200),
            difficulty: .medium, roundsSurvived: 3, totalFillers: 2,
            totalWords: 40, score: 5, xpEarned: 60,
            finalOutcome: .fillerOverload, wasNewBestAtTime: false
        )
        store.record(first)
        store.record(second)
        #expect(store.runs.count == 1)
        // Newer completedAt wins on the replace.
        #expect(store.runs.first?.completedAt == Date(timeIntervalSince1970: 200))
    }

    @Test @MainActor func capacityEvictsOldestByCompletedAt() {
        let store = freshStore()
        let cap = SuddenDeathRunHistoryStore.capacity
        for offset in 0..<(cap + 5) {
            let run = SuddenDeathRunRecord(
                completedAt: Date(timeIntervalSince1970: TimeInterval(offset)),
                difficulty: .medium, roundsSurvived: offset, totalFillers: 0,
                totalWords: 50, score: 6, xpEarned: 80,
                finalOutcome: .survived, wasNewBestAtTime: false
            )
            store.record(run)
        }
        #expect(store.runs.count == cap)
        // The 5 oldest rounds (0..4) should all be gone.
        for i in 0..<5 {
            #expect(!store.runs.contains { $0.roundsSurvived == i })
        }
        // The newest (cap+4) must be retained.
        #expect(store.runs.contains { $0.roundsSurvived == cap + 4 })
    }

    @Test @MainActor func recentRunsFiltersByDifficulty() {
        let store = freshStore()
        let now = Date()
        store.record(sampleRun(difficulty: .easy, rounds: 8, completedAt: now))
        store.record(sampleRun(difficulty: .medium, rounds: 4, completedAt: now.addingTimeInterval(-100)))
        store.record(sampleRun(difficulty: .hard, rounds: 2, completedAt: now.addingTimeInterval(-200)))
        store.record(sampleRun(difficulty: .easy, rounds: 6, completedAt: now.addingTimeInterval(-300)))
        let easy = store.recentRuns(difficulty: .easy)
        #expect(easy.count == 2)
        // Newest-first ordering preserved inside the difficulty filter.
        #expect(easy.first?.roundsSurvived == 8)
        #expect(easy.last?.roundsSurvived == 6)
    }

    @Test @MainActor func recentRunsHonorsLimit() {
        let store = freshStore()
        let now = Date()
        for i in 0..<10 {
            store.record(sampleRun(difficulty: .medium, rounds: i,
                                   completedAt: now.addingTimeInterval(TimeInterval(i))))
        }
        let top5 = store.recentRuns(difficulty: .medium, limit: 5)
        #expect(top5.count == 5)
        // Newest-first: the first row should be the run with rounds=9.
        #expect(top5.first?.roundsSurvived == 9)
        // limit = nil returns everything.
        let all = store.recentRuns(difficulty: .medium, limit: nil)
        #expect(all.count == 10)
    }

    @Test @MainActor func recentRunsLimitLargerThanAvailableReturnsAll() {
        let store = freshStore()
        store.record(sampleRun(difficulty: .easy, rounds: 3))
        store.record(sampleRun(difficulty: .easy, rounds: 5))
        let runs = store.recentRuns(difficulty: .easy, limit: 100)
        #expect(runs.count == 2)
    }

    @Test @MainActor func emptyHistoryReturnsEmpty() {
        let store = freshStore()
        #expect(store.recentRuns(difficulty: .hard).isEmpty)
        #expect(store.recentRuns(difficulty: .medium, limit: 5).isEmpty)
        #expect(store.allRuns.isEmpty)
    }

    @Test @MainActor func clearAllEmptiesStore() {
        let store = freshStore()
        store.record(sampleRun())
        store.record(sampleRun())
        #expect(store.runs.count == 2)
        store.clearAll()
        #expect(store.runs.isEmpty)
    }

    @Test @MainActor func deleteAllDataWipesByAccountID() {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let store = SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "alpha" })
        store.record(sampleRun())
        #expect(store.runs.count == 1)
        store.deleteAllData(for: "alpha")
        #expect(store.runs.isEmpty)
    }

    @Test @MainActor func perAccountKeyIsolation() {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let alpha = SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "alpha" })
        let beta  = SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "beta" })
        alpha.record(sampleRun(rounds: 7))
        #expect(alpha.runs.count == 1)
        #expect(beta.runs.isEmpty)
    }

    @Test @MainActor func reloadReadsPersistedRuns() {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let writer = SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "shared" })
        writer.record(sampleRun(difficulty: .hard, rounds: 9, wasNewBest: true))
        let reader = SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "shared" })
        #expect(reader.runs.count == 1)
        #expect(reader.runs.first?.roundsSurvived == 9)
        #expect(reader.runs.first?.wasNewBestAtTime == true)
    }

    @Test @MainActor func endSessionClearsInMemoryWithoutErasingDisk() {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        let store = SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "tester" })
        store.record(sampleRun())
        store.endSession()
        #expect(store.runs.isEmpty)
        let reloaded = SuddenDeathRunHistoryStore(defaults: suite, accountIDProvider: { "tester" })
        #expect(reloaded.runs.count == 1)
    }

    @Test func roundOutcomeRoundTripsForEveryCase() throws {
        // Encoder/decoder contract on RoundOutcome — the run record
        // can't ship without this because every persisted record
        // carries one.
        let cases: [RoundOutcome] = [
            .survived, .timeoutBeforeStart, .fillerOverload, .tooShort
        ]
        for outcome in cases {
            let record = SuddenDeathRunRecord(
                difficulty: .medium, roundsSurvived: 3, totalFillers: 0,
                totalWords: 40, score: 5, xpEarned: 60,
                finalOutcome: outcome, wasNewBestAtTime: false
            )
            let data = try JSONEncoder().encode(record)
            let decoded = try JSONDecoder().decode(SuddenDeathRunRecord.self, from: data)
            #expect(decoded.finalOutcome == outcome)
        }
    }

    @Test func runRecordRoundTripsEveryField() throws {
        // Field-by-field decode integrity — guards against a future
        // CodingKeys oversight silently dropping a stat from the
        // history list.
        let id = UUID()
        let date = Date(timeIntervalSince1970: 1_700_000_000)
        let record = SuddenDeathRunRecord(
            id: id, completedAt: date, difficulty: .hard,
            roundsSurvived: 7, totalFillers: 3, totalWords: 142,
            score: 8, xpEarned: 240, finalOutcome: .fillerOverload,
            wasNewBestAtTime: true,
            gamePoints: 1_425,
            activeMultipliers: ["x1.3 Deep"]
        )
        let data = try JSONEncoder().encode(record)
        let decoded = try JSONDecoder().decode(SuddenDeathRunRecord.self, from: data)
        #expect(decoded.id == id)
        #expect(decoded.completedAt == date)
        #expect(decoded.difficulty == .hard)
        #expect(decoded.roundsSurvived == 7)
        #expect(decoded.totalFillers == 3)
        #expect(decoded.totalWords == 142)
        #expect(decoded.score == 8)
        #expect(decoded.xpEarned == 240)
        #expect(decoded.finalOutcome == .fillerOverload)
        #expect(decoded.wasNewBestAtTime == true)
        #expect(decoded.gamePoints == 1_425)
        #expect(decoded.activeMultipliers == ["x1.3 Deep"])
    }

    @Test func legacyRunRecordWithoutPointsFieldsStillDecodes() throws {
        let record = SuddenDeathRunRecord(
            difficulty: .medium,
            roundsSurvived: 3,
            totalFillers: 1,
            totalWords: 52,
            score: 5,
            xpEarned: 70,
            finalOutcome: .fillerOverload,
            wasNewBestAtTime: false,
            gamePoints: 400,
            activeMultipliers: ["x1.2 Developed"]
        )
        let data = try JSONEncoder().encode(record)
        var legacyObject = try #require(
            JSONSerialization.jsonObject(with: data) as? [String: Any]
        )
        legacyObject.removeValue(forKey: "gamePoints")
        legacyObject.removeValue(forKey: "activeMultipliers")
        let legacyData = try JSONSerialization.data(withJSONObject: legacyObject)

        let decoded = try JSONDecoder().decode(SuddenDeathRunRecord.self, from: legacyData)
        #expect(decoded.roundsSurvived == 3)
        #expect(decoded.gamePoints == 0)
        #expect(decoded.activeMultipliers.isEmpty)
    }
}

