// MARK: - SuddenDeathHistorySummary (Track B — History tab integration)
//
// Pure breakdown helper. Test surface is small but locks the contract
// the History card relies on: per-difficulty grouping, best/avg/clean
// math, sort-by-most-recent-played.

struct SuddenDeathHistorySummaryTests {

    private func run(
        difficulty: SuddenDeathDifficulty,
        rounds: Int,
        fillers: Int = 0,
        completedAt: Date
    ) -> SuddenDeathRunRecord {
        SuddenDeathRunRecord(
            completedAt: completedAt,
            difficulty: difficulty,
            roundsSurvived: rounds,
            totalFillers: fillers,
            totalWords: 60,
            score: 7,
            xpEarned: 100,
            finalOutcome: .survived,
            wasNewBestAtTime: false
        )
    }

    @Test func emptyInputProducesEmptyBreakdowns() {
        let breakdowns = SuddenDeathHistorySummary.breakdowns(from: [])
        #expect(breakdowns.isEmpty)
        #expect(SuddenDeathHistorySummary.totalRunCount(from: []) == 0)
        #expect(SuddenDeathHistorySummary.mostRecentDate(from: []) == nil)
    }

    @Test func groupsByDifficulty() {
        let now = Date()
        let runs = [
            run(difficulty: .easy,   rounds: 5, completedAt: now),
            run(difficulty: .easy,   rounds: 3, completedAt: now.addingTimeInterval(-60)),
            run(difficulty: .medium, rounds: 6, completedAt: now.addingTimeInterval(-120)),
            run(difficulty: .hard,   rounds: 2, completedAt: now.addingTimeInterval(-180)),
            run(difficulty: .hard,   rounds: 8, completedAt: now.addingTimeInterval(-200))
        ]
        let breakdowns = SuddenDeathHistorySummary.breakdowns(from: runs)
        #expect(breakdowns.count == 3)
        let counts = Dictionary(uniqueKeysWithValues: breakdowns.map { ($0.difficulty, $0.runCount) })
        #expect(counts[.easy] == 2)
        #expect(counts[.medium] == 1)
        #expect(counts[.hard] == 2)
    }

    @Test func bestRoundsIsPerDifficultyMax() {
        let now = Date()
        let runs = [
            run(difficulty: .hard, rounds: 2, completedAt: now),
            run(difficulty: .hard, rounds: 8, completedAt: now.addingTimeInterval(-60)),
            run(difficulty: .hard, rounds: 5, completedAt: now.addingTimeInterval(-120))
        ]
        let hard = SuddenDeathHistorySummary.breakdowns(from: runs).first { $0.difficulty == .hard }
        #expect(hard?.bestRounds == 8)
    }

    @Test func averageRoundsRoundsToOneDecimal() {
        let now = Date()
        // 5 + 6 + 8 = 19 / 3 = 6.3333... → 6.3
        let runs = [
            run(difficulty: .medium, rounds: 5, completedAt: now),
            run(difficulty: .medium, rounds: 6, completedAt: now.addingTimeInterval(-60)),
            run(difficulty: .medium, rounds: 8, completedAt: now.addingTimeInterval(-120))
        ]
        let medium = SuddenDeathHistorySummary.breakdowns(from: runs).first { $0.difficulty == .medium }
        #expect(medium?.averageRounds == 6.3)
    }

    @Test func cleanRunCountTracksZeroFillers() {
        let now = Date()
        let runs = [
            run(difficulty: .easy, rounds: 4, fillers: 0, completedAt: now),
            run(difficulty: .easy, rounds: 5, fillers: 0, completedAt: now.addingTimeInterval(-60)),
            run(difficulty: .easy, rounds: 3, fillers: 2, completedAt: now.addingTimeInterval(-120)),
            run(difficulty: .easy, rounds: 6, fillers: 1, completedAt: now.addingTimeInterval(-180))
        ]
        let easy = SuddenDeathHistorySummary.breakdowns(from: runs).first { $0.difficulty == .easy }
        #expect(easy?.cleanRunCount == 2)
    }

    @Test func sortByMostRecentPlayedFirst() {
        // Hard last played 10 minutes ago, Easy 2 minutes ago → Easy first.
        let now = Date()
        let runs = [
            run(difficulty: .easy, rounds: 4, completedAt: now.addingTimeInterval(-120)),
            run(difficulty: .hard, rounds: 6, completedAt: now.addingTimeInterval(-600))
        ]
        let breakdowns = SuddenDeathHistorySummary.breakdowns(from: runs)
        #expect(breakdowns.first?.difficulty == .easy)
        #expect(breakdowns.last?.difficulty == .hard)
    }

    @Test func mostRecentDateAcrossAllDifficulties() {
        let now = Date()
        let runs = [
            run(difficulty: .easy, rounds: 4, completedAt: now.addingTimeInterval(-3600)),
            run(difficulty: .hard, rounds: 6, completedAt: now)
        ]
        #expect(SuddenDeathHistorySummary.mostRecentDate(from: runs) == now)
    }

    @Test func totalRunCountIsRawCount() {
        let now = Date()
        let runs = (0..<7).map {
            run(difficulty: .medium, rounds: $0 + 1, completedAt: now.addingTimeInterval(TimeInterval(-$0 * 60)))
        }
        #expect(SuddenDeathHistorySummary.totalRunCount(from: runs) == 7)
    }
}

// MARK: - PostRepCoachNote voice-change retroactive read
//
// Covers the pure `regenerationInput` helper (input construction
// from a finalized session + new voice) and verifies the
// deterministic output through the existing service path. Integration
// with `CoachingProfileStore.save(_:)` is exercised in the next
// suite using a fresh PostRepCoachNoteStore against an isolated
// UserDefaults suite — the store's `record(_:)` de-dupe contract is
// what makes the regen replace the stale-voice record cleanly.

struct PostRepCoachNoteRegenerationInputTests {

    private func makeSession(id: UUID = UUID(), intentLabel: String? = nil) -> PracticeSession {
        PracticeSession(
            id: id,
            transcript: "We focused on three priorities for the quarter and the team aligned quickly.",
            fillerWordCount: 1,
            duration: 32,
            date: Date(timeIntervalSince1970: 1_700_000_000),
            mode: .timed,
            score: 7,
            intentLabel: intentLabel
        )
    }

    @Test func sessionMetricsCarryThroughUnchanged() {
        let session = makeSession()
        let input = PracticeSessionFinalizer.regenerationInput(
            from: session,
            newVoice: .warm,
            baseline: .empty,
            bigMoment: nil,
            bigMomentDaysUntil: nil
        )
        #expect(input.sessionID == session.id)
        #expect(input.mode == session.mode)
        #expect(input.score == session.score)
        #expect(input.fillerCount == session.fillerWordCount)
        #expect(input.duration == session.duration)
        #expect(input.wordCount == session.wordCount)
    }

    @Test func newVoiceLandsOnInput() {
        let session = makeSession()
        let input = PracticeSessionFinalizer.regenerationInput(
            from: session,
            newVoice: .executive,
            baseline: .empty,
            bigMoment: nil,
            bigMomentDaysUntil: nil
        )
        #expect(input.voice == .executive)
    }

    @Test func nilNewVoiceCarriesThrough() {
        // Edge case — the user could theoretically clear their voice
        // (the existing model doesn't expose this in the UI today,
        // but the helper handles it defensively so a future settings
        // affordance doesn't break the regen contract).
        let session = makeSession()
        let input = PracticeSessionFinalizer.regenerationInput(
            from: session,
            newVoice: nil,
            baseline: .empty,
            bigMoment: nil,
            bigMomentDaysUntil: nil
        )
        #expect(input.voice == nil)
    }

    @Test func intentLabelCarriesThroughFromSession() {
        let session = makeSession(intentLabel: "Tighten my structure")
        let input = PracticeSessionFinalizer.regenerationInput(
            from: session,
            newVoice: .concise,
            baseline: .empty,
            bigMoment: nil,
            bigMomentDaysUntil: nil
        )
        #expect(input.intentLabel == "Tighten my structure")
    }

    @Test func insufficientBaselineMapsToNilOnInput() {
        // Cold-start baseline has insufficient confidence → input
        // exposes nil for filler rate + pace so the deterministic
        // chain skips the comparison branch.
        let session = makeSession()
        let input = PracticeSessionFinalizer.regenerationInput(
            from: session,
            newVoice: .warm,
            baseline: .empty,
            bigMoment: nil,
            bigMomentDaysUntil: nil
        )
        #expect(input.baselineFillerRate == nil)
        #expect(input.baselinePaceWPM == nil)
    }

    @Test func deterministicNoteFromRegeneratedInputIsVoiceShaped() {
        // Wire test: an input built by regenerationInput must produce a
        // note in the requested voice when fed through the existing
        // deterministic path. Tests the END-TO-END handoff between the
        // new helper and the service.
        let session = makeSession()
        let warmInput = PracticeSessionFinalizer.regenerationInput(
            from: session, newVoice: .warm, baseline: .empty,
            bigMoment: nil, bigMomentDaysUntil: nil
        )
        let executiveInput = PracticeSessionFinalizer.regenerationInput(
            from: session, newVoice: .executive, baseline: .empty,
            bigMoment: nil, bigMomentDaysUntil: nil
        )
        let warmNote = PostRepCoachNoteService.deterministicNote(input: warmInput)
        let executiveNote = PostRepCoachNoteService.deterministicNote(input: executiveInput)
        #expect(warmNote.voice == .warm)
        #expect(executiveNote.voice == .executive)
        // Two different voices → two different phrasings against the
        // same facts. Equality would mean the persona switch never
        // reached the sentence selectors.
        #expect(warmNote.noteText != executiveNote.noteText)
    }

    @Test func regeneratedNoteIsHonestlyRuleBased() {
        // The deterministic path always sets `isAIBacked: false`. The
        // AI upgrade path (separate, async) can flip this later. Lock
        // the honest-provenance contract on the deterministic write
        // that lands synchronously after a voice change.
        let session = makeSession()
        let input = PracticeSessionFinalizer.regenerationInput(
            from: session, newVoice: .authoritative, baseline: .empty,
            bigMoment: nil, bigMomentDaysUntil: nil
        )
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        #expect(note.isAIBacked == false)
    }

    @Test func sessionIDIsStableAcrossRegens() {
        // The store de-dupes by sessionID. Two regenerations against
        // the same session MUST land with the same sessionID so the
        // second write replaces (not stacks) the first.
        let sharedID = UUID()
        let session = makeSession(id: sharedID)
        let first = PracticeSessionFinalizer.regenerationInput(
            from: session, newVoice: .warm, baseline: .empty,
            bigMoment: nil, bigMomentDaysUntil: nil
        )
        let second = PracticeSessionFinalizer.regenerationInput(
            from: session, newVoice: .executive, baseline: .empty,
            bigMoment: nil, bigMomentDaysUntil: nil
        )
        #expect(first.sessionID == sharedID)
        #expect(second.sessionID == sharedID)
    }
}

// MARK: - PostRepCoachNoteStore regen replacement contract
//
// The voice-change regen leans on the store's existing sessionID
// dedupe. These tests pin the store-level behavior the regen
// depends on: write A in old voice → write B for same session in
// new voice → store holds B only, with the new voice.

@MainActor
struct PostRepCoachNoteStoreRegenerationTests {

    private func freshStore() -> PostRepCoachNoteStore {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        return PostRepCoachNoteStore(defaults: suite, accountIDProvider: { "tester" })
    }

    @Test func regenReplacesPriorRecordForSameSession() {
        let store = freshStore()
        let sessionID = UUID()
        let oldVoice = PostRepCoachNote(
            sessionID: sessionID, voice: .authoritative,
            noteText: "Verdict: that was a 7. Composure carried the rep.",
            isAIBacked: false
        )
        let newVoice = PostRepCoachNote(
            sessionID: sessionID, voice: .warm,
            noteText: "That rep scored 7 — and it sounded like it felt right too.",
            isAIBacked: false
        )
        store.record(oldVoice)
        store.record(newVoice)
        #expect(store.notes.count == 1)
        #expect(store.note(for: sessionID)?.voice == .warm)
        #expect(store.note(for: sessionID)?.noteText.contains("felt right") == true)
    }

    @Test func regenDoesNotAffectOtherSessions() {
        // Two distinct sessions, one regen — only the matching
        // session's note flips. The other session's note keeps its
        // original voice.
        let store = freshStore()
        let sessionA = UUID()
        let sessionB = UUID()
        store.record(PostRepCoachNote(
            sessionID: sessionA, voice: .authoritative,
            noteText: "Verdict: that was a 7. Composure carried the rep.",
            isAIBacked: false
        ))
        store.record(PostRepCoachNote(
            sessionID: sessionB, voice: .authoritative,
            noteText: "Verdict: that was an 8. Composure carried the rep.",
            isAIBacked: false
        ))
        // Regen only sessionA in warm
        store.record(PostRepCoachNote(
            sessionID: sessionA, voice: .warm,
            noteText: "That rep scored 7 — and it sounded like it felt right too.",
            isAIBacked: false
        ))
        #expect(store.notes.count == 2)
        #expect(store.note(for: sessionA)?.voice == .warm)
        #expect(store.note(for: sessionB)?.voice == .authoritative)
    }

    @Test func latestNoteReflectsRegeneratedVoiceAfterReplacement() {
        // The Ask Noum chat coach reads `latestNote()` — after a
        // voice change regen, the latest read MUST surface the new
        // voice, not the stale one.
        let store = freshStore()
        let sessionID = UUID()
        store.record(PostRepCoachNote(
            sessionID: sessionID, voice: .concise,
            noteText: "Steady. Hold the line.",
            isAIBacked: false,
            generatedAt: Date(timeIntervalSince1970: 100)
        ))
        store.record(PostRepCoachNote(
            sessionID: sessionID, voice: .storytelling,
            noteText: "A steady chapter — the through-line carried.",
            isAIBacked: false,
            generatedAt: Date(timeIntervalSince1970: 200)
        ))
        #expect(store.latestNote()?.voice == .storytelling)
    }
}

// MARK: - M25 Stream 4 — celebration timing

/// Locks the read-time constants used by `PreSummaryCelebration`.
/// All cards now show on a single screen with staggered reveal, so the
/// hold duration is for the whole screen (not per-card). The
/// `holdDuration(isSingleEvent:reduceMotion:)` API is preserved for
/// backward compat but returns the same value regardless of event count.
@MainActor
struct M25CelebrationTimingTests {

    @Test func fullMotionHoldsLongEnoughToReadAllCards() {
        let hold = PreSummaryCelebration.holdDuration(isSingleEvent: true, reduceMotion: false)
        #expect(hold == 5.0, "full-motion hold must give 5s for the user to read all cards")
    }

    @Test func multiEventFullMotionSameHold() {
        let hold = PreSummaryCelebration.holdDuration(isSingleEvent: false, reduceMotion: false)
        #expect(hold == 5.0, "multi-event uses the same 5s hold since all cards are on one screen")
    }

    @Test func reduceMotionHoldIsAccessible() {
        let hold = PreSummaryCelebration.holdDuration(isSingleEvent: true, reduceMotion: true)
        #expect(hold == 3.0, "reduce-motion hold is 3s")
    }

    @Test func reduceMotionMultiEventSameHold() {
        let hold = PreSummaryCelebration.holdDuration(isSingleEvent: false, reduceMotion: true)
        #expect(hold == 3.0, "reduce-motion multi-event uses the same 3s hold")
    }

    @Test func reduceMotionAlwaysShorterOrEqualThanFullMotion() {
        // Vestibular path must never out-hold the full-motion path.
        let singleFull = PreSummaryCelebration.holdDuration(isSingleEvent: true, reduceMotion: false)
        let singleReduced = PreSummaryCelebration.holdDuration(isSingleEvent: true, reduceMotion: true)
        let multiFull = PreSummaryCelebration.holdDuration(isSingleEvent: false, reduceMotion: false)
        let multiReduced = PreSummaryCelebration.holdDuration(isSingleEvent: false, reduceMotion: true)
        #expect(singleReduced <= singleFull)
        #expect(multiReduced <= multiFull)
    }
}

// MARK: - M25 Stream 4 — shareable card history + friends

@MainActor
struct M25ShareableCardTests {

    private func makeSession(score: Int?, id: UUID = UUID()) -> PracticeSession {
        var s = PracticeSession(
            transcript: "Internal speech that must never appear on the share card.",
            fillerWordCount: 0,
            duration: 30,
            date: Date(),
            mode: .timed,
            pressureLevel: .standard
        )
        s.id = id
        s.score = score
        return s
    }

    @Test func recentScoresReturnsFiveWhenFiveExist() {
        let store = PracticeSessionStore.shared
        // Snapshot + restore so we don't pollute other tests that may
        // assume an empty store.
        let snapshot = store.sessions
        defer { setSessions(snapshot, on: store) }

        let current = makeSession(score: 9)
        // Seed store newest-first (matches production insert order).
        let seeded: [PracticeSession] = [
            current,
            makeSession(score: 8),
            makeSession(score: 6),
            makeSession(score: 7),
            makeSession(score: 5)
        ]
        setSessions(seeded, on: store)

        let scores = ShareableSessionCard.recentScores(forSession: current)
        #expect(scores.count == 5)
        #expect(scores.last == 9, "current session must be the trailing entry")
        #expect(scores.first == 5, "oldest entry comes first")
    }

    @Test func recentScoresAppendsCurrentWhenNotInStore() {
        let store = PracticeSessionStore.shared
        let snapshot = store.sessions
        defer { setSessions(snapshot, on: store) }

        setSessions([
            makeSession(score: 6),
            makeSession(score: 7)
        ], on: store)
        let current = makeSession(score: 9)
        let scores = ShareableSessionCard.recentScores(forSession: current)
        #expect(scores.last == 9, "share path must include the in-flight rep even before persistence")
        #expect(scores.count <= 5)
    }

    @Test func friendsSectionEmptyHidesByReturningEmptyArray() {
        // When the friends list is empty, the helper returns [] so the
        // section never renders. The view checks `friendsPeak.isEmpty`.
        let friends = ShareableSessionCard.topFriendsPeak(friends: [])
        #expect(friends.isEmpty)
    }

    @Test func friendsSectionExcludesFriendsWithUnknownPeak() {
        // A friend with no synced peak rating is a "—" in the friends
        // section — we'd rather hide them than print noise.
        let source = [NoumFriend(
            id: UUID(),
            displayName: "Synced Friend",
            addedAt: Date(),
            addedVia: .manual,
            lastKnownPeakRating: 700
        ), NoumFriend(
            id: UUID(),
            displayName: "Awaiting Sync",
            addedAt: Date(),
            addedVia: .manual,
            lastKnownPeakRating: nil
        )]
        let friends = ShareableSessionCard.topFriendsPeak(friends: source)
        #expect(friends.count == 1)
        #expect(friends.first?.displayName == "Synced Friend")
    }

    @Test func friendsSectionRanksByPeakAndCapsAtThree() {
        let peaks = [560, 820, 690, 740, 610]
        let source = peaks.enumerated().map { i, peak in
            NoumFriend(
                id: UUID(),
                displayName: "Friend \(i)",
                addedAt: Date(),
                addedVia: .manual,
                lastKnownPeakRating: peak
            )
        }
        let friends = ShareableSessionCard.topFriendsPeak(friends: source)
        #expect(friends.count == 3)
        #expect(friends[0].peakRating == 820)
        #expect(friends[1].peakRating == 740)
        #expect(friends[2].peakRating == 690)
    }

    @Test func friendPeakModelCarriesNoTranscriptOrFillerFields() {
        // Privacy posture: the model that feeds the card must expose
        // name + initials + peak rating only. Any new field added here
        // ships to the share image.
        let mirror = Mirror(reflecting: ShareableSessionCard.FriendPeak(
            id: UUID(),
            displayName: "Sam",
            initials: "S",
            peakRating: 700
        ))
        let labels = mirror.children.compactMap { $0.label }
        #expect(Set(labels) == Set(["id", "displayName", "initials", "peakRating"]))
    }

    @Test func recentScoresHelperReadsOnlyScores() {
        // The helper must return Int, not anything carrying transcript
        // text. Type check is the static guarantee — assert the value
        // type explicitly so a future refactor that widens the shape
        // breaks loudly.
        let store = PracticeSessionStore.shared
        let snapshot = store.sessions
        defer { setSessions(snapshot, on: store) }
        let current = makeSession(score: 9)
        setSessions([current], on: store)
        let scores: [Int] = ShareableSessionCard.recentScores(forSession: current)
        #expect(scores == [9])
    }

    // MARK: - Test helpers

    /// Replace the store's sessions array via the remote-replace API,
    /// which is the only public bulk-setter the store exposes. The
    /// `sorted by date desc` inside `replaceFromRemote` means we seed
    /// the input with strictly increasing dates so the resulting
    /// newest-first order matches the desired order.
    private func setSessions(_ sessions: [PracticeSession], on store: PracticeSessionStore) {
        // sessions input here is in production order (newest-first).
        // Re-stamp dates strictly descending so replaceFromRemote keeps
        // that order through its internal sort.
        let now = Date()
        let stamped: [PracticeSession] = sessions.enumerated().map { index, session in
            PracticeSession(
                id: session.id,
                transcript: session.transcript,
                fillerWordCount: session.fillerWordCount,
                duration: session.duration,
                date: now.addingTimeInterval(-Double(index)),
                mode: session.mode,
                imConversationDetails: session.imConversationDetails,
                score: session.score,
                xpEarned: session.xpEarned,
                headline: session.headline,
                insights: session.insights,
                coachSummary: session.coachSummary,
                aiCoachFeedback: session.aiCoachFeedback,
                prompt: session.prompt,
                theme: session.theme,
                drillResult: session.drillResult,
                transcriptConfidence: session.transcriptConfidence,
                transcriptionProvider: session.transcriptionProvider,
                pressureLevel: session.pressureLevel,
                isRated: session.isRated,
                pauseMetrics: session.pauseMetrics,
                pitchMetrics: session.pitchMetrics,
                grammarFindings: session.grammarFindings,
                intentFocus: session.intentFocus,
                intentLabel: session.intentLabel
            )
        }
        store.replaceFromRemote(stamped)
    }

}

// MARK: - M25 Stream 2 — IM stack overhaul
//
// Two test surfaces:
//   1. `M25IMMessageSpeakerGenerationTests` — exercises the generation-token
//      guard on `IMMessageSpeaker` deterministically. Verifies that a stale
//      token is rejected after speak() / stop() advances the counter — the
//      exact predicate the production playback paths use before
//      `playAudioData`. No network, no audio.
//   2. `M25NPCSystemPromptTests` — asserts that each voice variant of
//      `AINPCChatService.buildSystemPrompt` produces a prompt containing
//      the voice-specific testing-for clause, and that the user's
//      coaching profile + big moment + userContext block reach the
//      prompt. Pure-function — no provider.

#if canImport(AVFAudio)
@MainActor
struct M25IMMessageSpeakerGenerationTests {

    /// Calling `advanceGenerationForTesting()` returns a value strictly
    /// greater than the previous one and is reflected in
    /// `currentGeneration`. This is the same `&+= 1` step `speak()` and
    /// `stop()` use, exercised without spawning a real network task.
    @Test func advanceMovesCurrentGenerationForward() {
        let speaker = IMMessageSpeaker.shared
        let before = speaker.currentGeneration
        let after = speaker.advanceGenerationForTesting()
        #expect(after > before)
        #expect(speaker.currentGeneration == after)
    }

    /// The generation captured at the start of a speak() Task is the
    /// predicate that gates `playAudioData`. After ANY subsequent
    /// advance (speak again, or stop), that captured token must no
    /// longer be current — otherwise the stale audio would play.
    @Test func capturedGenerationStaleAfterSubsequentAdvance() {
        let speaker = IMMessageSpeaker.shared
        let captured = speaker.advanceGenerationForTesting()
        #expect(speaker.isGenerationStillCurrent(captured))
        _ = speaker.advanceGenerationForTesting()
        #expect(!speaker.isGenerationStillCurrent(captured))
    }

    /// Multiple rapid advances (the rapid-rounds bug pattern) all
    /// invalidate earlier tokens. Round 1's captured token is stale
    /// after round 2's advance and stays stale after round 3's. The
    /// production race fix relies on this monotonic-by-construction
    /// behavior, not on the magnitude of the gap.
    @Test func staleTokenStaysStaleAfterRepeatedAdvances() {
        let speaker = IMMessageSpeaker.shared
        let roundOne = speaker.advanceGenerationForTesting()
        _ = speaker.advanceGenerationForTesting() // round 2
        _ = speaker.advanceGenerationForTesting() // round 3
        #expect(!speaker.isGenerationStillCurrent(roundOne))
    }

    /// A live `speak(...)` call advances the generation. Even though
    /// the playback Task itself may never run a real fetch in the test
    /// environment (no API keys), the synchronous bump happens on the
    /// main actor before the Task is scheduled — so the captured-before
    /// invariant the production fix depends on is observable here.
    @Test func liveSpeakAdvancesGeneration() {
        let speaker = IMMessageSpeaker.shared
        let before = speaker.currentGeneration
        speaker.speak("hello", setup: IMConversationSetup(scenario: .workUpdate, targetTone: .confident))
        #expect(speaker.currentGeneration > before)
        // Tear down the spawned task immediately so the test does not
        // leak an in-flight URLSession request.
        speaker.stop()
    }

    /// `stop()` also advances the generation — this is what closes the
    /// other half of the race window where a fetch had landed and was
    /// about to play but the user has since pressed stop or moved on.
    @Test func stopAdvancesGeneration() {
        let speaker = IMMessageSpeaker.shared
        let before = speaker.currentGeneration
        speaker.stop()
        #expect(speaker.currentGeneration > before)
    }
}

/// S4 — voice-conversation speaking-state seam on `IMMessageSpeaker`.
/// Verifies the `isSpeaking` flag tracks a deterministic state machine
/// (set on play-start, cleared on BOTH natural finish and barge-in) and
/// that the `onPlaybackFinished` handoff fires only on natural finish —
/// without ever playing real audio (no API keys / no audio in tests).
/// Mirrors the M25 generation-token suite above.
///
/// Each test calls `stop()` first to reset the shared singleton to a
/// known clean state (no live player, `isSpeaking == false`), the same
/// defensive teardown the M25 tests use.
@MainActor
struct S4IMMessageSpeakerSpeakingStateTests {

    /// After a clean teardown the speaker is not speaking. This is the
    /// resting state a "coach speaking" UI binds against.
    @Test func isSpeakingFalseAfterStop() {
        let speaker = IMMessageSpeaker.shared
        speaker.stop()
        #expect(speaker.isSpeaking == false)
    }

    /// `stop()` (barge-in / teardown) clears a set speaking flag AND
    /// advances the generation in one step — the two halves of a clean
    /// interruption. Without this, a "coach is speaking" UI would stick
    /// after the user barges in.
    @Test func stopClearsSpeakingAndAdvancesGeneration() {
        let speaker = IMMessageSpeaker.shared
        speaker.stop() // known clean baseline
        speaker.setSpeakingForTesting(true)
        #expect(speaker.isSpeaking == true)
        let before = speaker.currentGeneration
        speaker.stop()
        #expect(speaker.isSpeaking == false)
        #expect(speaker.currentGeneration > before)
    }

    /// A natural end-of-clip clears `isSpeaking` and fires the
    /// listen → speak → listen handoff exactly once. This is the
    /// `audioPlayerDidFinishPlaying` branch exercised via the test seam.
    @Test func naturalFinishClearsSpeakingAndFiresHandoff() {
        let speaker = IMMessageSpeaker.shared
        speaker.stop()
        var finishedCount = 0
        speaker.onPlaybackFinished = { finishedCount += 1 }
        speaker.setSpeakingForTesting(true)
        speaker.finishPlaybackForTesting()
        #expect(speaker.isSpeaking == false)
        #expect(finishedCount == 1)
        speaker.onPlaybackFinished = nil // don't leak into other tests
    }

    /// Barge-in (`stop()`) must NOT fire `onPlaybackFinished` — the
    /// caller initiated the interruption and already knows. Only a
    /// natural finish triggers the auto-handoff back to listening.
    @Test func bargeInDoesNotFireHandoff() {
        let speaker = IMMessageSpeaker.shared
        speaker.stop()
        var finishedCount = 0
        speaker.onPlaybackFinished = { finishedCount += 1 }
        speaker.setSpeakingForTesting(true)
        speaker.stop()
        #expect(speaker.isSpeaking == false)
        #expect(finishedCount == 0)
        speaker.onPlaybackFinished = nil
    }

    /// A live `speak(...)` advances the generation (already covered by
    /// M25). The state seam adds: a `stop()` immediately after leaves the
    /// speaker not speaking, so the spawned playback Task — even if it
    /// later resolves with stale audio — cannot leave a stuck flag,
    /// because `playAudioData` only sets `isSpeaking` after a generation
    /// check the stale clip fails.
    @Test func stopAfterSpeakLeavesNotSpeaking() {
        let speaker = IMMessageSpeaker.shared
        speaker.speak(
            "hello",
            setup: IMConversationSetup(scenario: .workUpdate, targetTone: .confident)
        )
        speaker.stop()
        #expect(speaker.isSpeaking == false)
    }
}
#endif

/// S5/C5 — spoken-coach-mode pure decision logic (`AskNoumSpokenMode`).
///
/// `spokenRoute(outcome:spokenRepliesEnabled:localeSupportsAI:)` is the single
/// source of truth for whether — and through WHICH engines — a freshly-landed
/// coach turn is read aloud. It is deliberately view-free so the full truth
/// table can be asserted without the SwiftUI view, an audio engine, or a
/// model. These tests pin every gate: toggle, locale, and outcome shape.
struct S5SpokenModeRouteTests {

    /// The happy path: toggle ON + locale supports AI + a real non-empty
    /// reply → the full engine chain (cloud first, on-device terminal).
    @Test func realReplyRoutesToFullChainWhenEnabledAndLocaleSupported() {
        #expect(AskNoumSpokenMode.spokenRoute(
            outcome: .reply("Do three reps of Pressure Drill."),
            spokenRepliesEnabled: true,
            localeSupportsAI: true
        ) == .fullChain)
    }

    /// Toggle OFF is an absolute veto even on an otherwise-speakable reply —
    /// text-only must stay fully silent. The user's mute choice is the one
    /// voice preference that is ALWAYS respected.
    @Test func neverSpeaksWhenToggleOff() {
        #expect(AskNoumSpokenMode.spokenRoute(
            outcome: .reply("A perfectly good reply."),
            spokenRepliesEnabled: false,
            localeSupportsAI: true
        ) == AskNoumSpokenMode.SpokenRoute.none)
    }

    /// Locale gate: a non-AI locale stays text-only even with the toggle ON,
    /// mirroring the chat-reply locale gate so non-English users get a clean
    /// silent experience rather than an English voice over a localized UI.
    @Test func neverSpeaksWhenLocaleUnsupported() {
        #expect(AskNoumSpokenMode.spokenRoute(
            outcome: .reply("A perfectly good reply."),
            spokenRepliesEnabled: true,
            localeSupportsAI: false
        ) == AskNoumSpokenMode.SpokenRoute.none)
    }

    /// A `.failure` outcome is NEVER spoken — the system-notice row is a UI
    /// affordance, not the coach's voice. Asserted across every failure cause
    /// so a new cause can't silently become speakable, and `spokenText` is
    /// nil so no caller can even extract something to say.
    @Test func neverSpeaksAnyFailureCause() {
        let causes: [ChatFailure] = [
            .noProvider, .unauthenticated, .rateLimited, .localeUnsupported,
            .network, .empty, .contentRejected
        ]
        for cause in causes {
            #expect(AskNoumSpokenMode.spokenRoute(
                outcome: .failure(cause),
                spokenRepliesEnabled: true,
                localeSupportsAI: true
            ) == AskNoumSpokenMode.SpokenRoute.none, "failure(\(cause)) must not be spoken")
            #expect(AskNoumSpokenMode.spokenText(for: .failure(cause)) == nil)
        }
    }

    /// A whitespace-only reply is rejected even though it is nominally a
    /// `.reply`. The predicate must not depend on the store routing empties to
    /// `.failure(.empty)` — it owns the empty check itself.
    @Test func neverSpeaksWhitespaceOnlyReply() {
        #expect(AskNoumSpokenMode.spokenRoute(
            outcome: .reply("   \n\t  "),
            spokenRepliesEnabled: true,
            localeSupportsAI: true
        ) == AskNoumSpokenMode.SpokenRoute.none)
    }

    /// All four off/locale combinations on an empty-text reply are `.none` —
    /// no combination of flags resurrects an empty reply.
    @Test func emptyReplyNeverSpeaksUnderAnyFlags() {
        for enabled in [true, false] {
            for locale in [true, false] {
                #expect(AskNoumSpokenMode.spokenRoute(
                    outcome: .reply(""),
                    spokenRepliesEnabled: enabled,
                    localeSupportsAI: locale
                ) == AskNoumSpokenMode.SpokenRoute.none)
            }
        }
    }

    @Test func scaffoldOnlyReplyNeverStartsSpeechRoute() {
        let outcome = ChatOutcome.reply("**Read:**\n- **Move:**")

        #expect(AskNoumSpokenMode.spokenRoute(
            outcome: outcome,
            spokenRepliesEnabled: true,
            localeSupportsAI: true
        ) == AskNoumSpokenMode.SpokenRoute.none)
        #expect(AskNoumSpokenMode.spokenText(for: outcome) == nil)
    }

    /// `spokenText` hands back trimmed live coach text and nil otherwise, so
    /// call sites can't drift from the route decision by re-extracting text.
    @Test func spokenTextMatchesSpeakableOutcomes() {
        #expect(AskNoumSpokenMode.spokenText(for: .reply("  Tighten the open.  ")) == "Tighten the open.")
        #expect(AskNoumSpokenMode.spokenText(for: .reply("   ")) == nil)
        #expect(AskNoumSpokenMode.spokenText(for: .failure(.network)) == nil)
    }

    @Test func spokenTextNeverReadsMarkdownOrScaffoldLabels() {
        let spoken = AskNoumSpokenMode.spokenText(for: .reply("""
        **Read:** You want it straight.
        - **Move:** Give one 30-second update and stop.
        """))

        #expect(spoken == "You want it straight. Give one 30-second update and stop.")
        let value = spoken ?? ""
        #expect(!value.contains("**"))
        #expect(!value.lowercased().contains("read:"))
        #expect(!value.lowercased().contains("move:"))
    }
}

#if canImport(SwiftUI)
struct LiveCoachImmediateSpeechTests {

    @Test func provisionalReadUsesSameSpokenSanitizerAsFinalReplies() {
        let spoken = LiveCoachCallView.liveCoachSpokenText(
            from: """
            **Read:** You're closer mechanically than authoritatively.
            - **Move:** Run one 45-second verdict-first answer.
            """,
            spokenRepliesEnabled: true,
            localeSupportsAI: true
        )

        #expect(spoken == "You're closer mechanically than authoritatively. Run one 45-second verdict-first answer.")
    }

    @Test func provisionalReadRespectsMuteAndLocaleGate() {
        #expect(LiveCoachCallView.liveCoachSpokenText(
            from: "Start with the verdict, then stop.",
            spokenRepliesEnabled: false,
            localeSupportsAI: true
        ) == nil)
        #expect(LiveCoachCallView.liveCoachSpokenText(
            from: "Start with the verdict, then stop.",
            spokenRepliesEnabled: true,
            localeSupportsAI: false
        ) == nil)
    }

    @Test func scaffoldOnlyProvisionalReadDoesNotStartSpeech() {
        #expect(LiveCoachCallView.liveCoachSpokenText(
            from: "**Read:**\n- **Move:**",
            spokenRepliesEnabled: true,
            localeSupportsAI: true
        ) == nil)
    }

    @Test func finalSpeechIsSuppressedOnlyAfterImmediateSpeechStarts() {
        #expect(LiveCoachCallView.shouldSpeakFinalCoachOutcome(
            provisionalSpeechStarted: false
        ))
        #expect(!LiveCoachCallView.shouldSpeakFinalCoachOutcome(
            provisionalSpeechStarted: true
        ))
    }
}
#endif

/// S5 — voice → spoken-tone mapping. Pure + total: every chosen voice maps to
/// a real `IMTargetTone`, and a nil chosen voice maps to the steady neutral
/// `.calm` coach register (never an invented tone).
struct S5SpokenModeCoachToneTests {

    @Test func eachChosenVoiceMapsToExpectedTone() {
        #expect(AskNoumSpokenMode.coachTone(for: .authoritative) == .confident)
        #expect(AskNoumSpokenMode.coachTone(for: .warm) == .warm)
        #expect(AskNoumSpokenMode.coachTone(for: .concise) == .concise)
        #expect(AskNoumSpokenMode.coachTone(for: .persuasive) == .assertive)
        #expect(AskNoumSpokenMode.coachTone(for: .executive) == .professional)
        #expect(AskNoumSpokenMode.coachTone(for: .storytelling) == .warm)
    }

    /// No chosen voice → neutral steady coach tone. The fallback must be a
    /// real tone, never a crash or an invented register.
    @Test func nilVoiceMapsToCalm() {
        #expect(AskNoumSpokenMode.coachTone(for: nil) == .calm)
    }

    /// Totality guard: every `SpeakingStyleGoal` case resolves to one of the
    /// real `IMTargetTone` cases (no default-to-junk). Iterates `allCases` so
    /// a newly-added voice forces a conscious mapping decision here.
    @Test func everyVoiceResolvesToARealTone() {
        let realTones = Set(IMTargetTone.allCases)
        for voice in SpeakingStyleGoal.allCases {
            #expect(realTones.contains(AskNoumSpokenMode.coachTone(for: voice)))
        }
    }
}

/// Ask Noum live-reply quality gate.
///
/// MARK: - Make It Stick (Winston memorability analyzer)
///
/// Pins `MemorabilityAnalyzer` — the deterministic opening/closing read drawn
/// from Patrick Winston's "How to Speak". It must call only the reliably
/// detectable bookends, never over-flag a clean rep, and never mistake a
/// mid-talk "thank you" for a weak close.
@Suite("MemorabilityAnalyzer")
struct MemorabilityAnalyzerTests {

    @Test func tooShortIsInsufficientBothEnds() {
        let read = MemorabilityAnalyzer.analyze(transcript: "Hello there everyone.")
        #expect(read.opening == .insufficient)
        #expect(read.closing == .insufficient)
        #expect(!read.hasActionableSignal)
    }

    @Test func orientedOpenWithPromiseCue() {
        let t = "Today I'll show you why our close rate doubled, and the one change that did it. We rebuilt onboarding around a single first action."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.opening == .oriented)
    }

    @Test func orientedOpenWithQuestionNoIncidentalCue() {
        // Question opener with NO orientation cue word — proves the "?" path
        // itself orients, not a coincidental cue match.
        let t = "Why should anyone in that room care what we built? We lose a deal a week to slow follow-up, and that is the gap."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.opening == .oriented)
    }

    @Test func cueMatchRespectsWordBoundaries() {
        // "first" must NOT fire inside "First Republic"; "the key" must NOT fire
        // inside "keyboard". Both reps open cold (no real orientation cue).
        let t1 = "First Republic shipped the keyboard remap to all seats this week, and the rollout finished without a single support ticket filed."
        #expect(MemorabilityAnalyzer.analyze(transcript: t1).opening == .cold)
    }

    @Test func coldOpenIsDetectedButNotActionableAlone() {
        // A direct detail-led open with a clean landing. The opening read is
        // `.cold` (no framing cue), but that ABSENCE must NOT drive coaching —
        // only a weak close is actionable. Guards against over-flagging strong
        // direct openings.
        let t = "The Q3 migration moved forty tables to the new schema, and we backfilled every record over one weekend with zero downtime."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.opening == .cold)
        #expect(read.closing == .landed)
        #expect(!read.hasActionableSignal)
    }

    @Test func trailedOffCloseOnYeah() {
        let t = "Today I want to walk through the new pricing and why it helps retention. It lowers the entry tier and adds an annual plan. So yeah."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        if case .trailedOff = read.closing {} else { Issue.record("expected trailedOff close, got \(read.closing)") }
        #expect(read.hasActionableSignal)
    }

    @Test func weakWholeTailThatsIt() {
        let t = "Here's the key point about the redesign: fewer steps, clearer copy, faster load. We shipped it Tuesday to all users. That's it."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        if case .trailedOff(let tail) = read.closing { #expect(tail == "that's it") }
        else { Issue.record("expected trailedOff, got \(read.closing)") }
    }

    @Test func thankYouEndingIsWeakClose() {
        let t = "Let me show you the three wins from this sprint and what they unlock next. Search is faster and onboarding is simpler now. Thank you."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        if case .trailedOff = read.closing {} else { Issue.record("expected trailedOff for thank-you close") }
    }

    @Test func midTalkThankYouDoesNotFalseFlagClose() {
        // "thank you" appears mid-talk, but the rep LANDS on a committed line.
        let t = "Thank you for the intro. Here's the point: we cut latency in half this quarter. The fix was caching the hot path, and we ship it Monday."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.closing == .landed)
    }

    @Test func cleanRepProducesNoActionableSignal() {
        let t = "Today I'll make the case for one metric over five. Teams that track a single north-star ship faster. Adopt it for next quarter and watch focus rise."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.opening == .oriented)
        #expect(read.closing == .landed)
        #expect(!read.hasActionableSignal)
    }

    // Coaching-invariant guard: honest uncertainty + committed contrastive
    // closes are SEMANTIC content, not trailed-off landings. Flagging them
    // would punish-shame valid speech (CLAUDE.md), so they must read as landed.
    @Test func honestUncertaintyCloseIsNotTrailedOff() {
        let t = "Let me show you where the rollout stands and the one risk I'm watching. The migration is done; the data check is still running, so honestly I'm not sure yet."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.closing == .landed)
        #expect(!read.hasActionableSignal)
    }

    @Test func committedAnywayCloseIsNotTrailedOff() {
        let t = "Here's the call we made on the deadline and why it held. The data was incomplete and the room was split, but we shipped it anyway."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.closing == .landed)
    }

    @Test func trailingSoAnywayStaysWeak() {
        // A genuine trail-off ("...so anyway") IS still caught.
        let t = "Today I'll cover the three changes in this release and what they unlock. Search is faster and the editor is cleaner now. So anyway."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        if case .trailedOff = read.closing {} else { Issue.record("expected trailedOff for 'so anyway'") }
    }

    // Integration contract: structureReadLines (the CoachContextBuilder helper)
    // stays silent on a clean rep and names the weak close otherwise.
    @Test func structureReadLinesSilentOnCleanRep() {
        let clean = MemorabilityAnalyzer.Read(opening: .oriented, closing: .landed)
        #expect(CoachContextBuilder.structureReadLines(for: clean) == nil)
    }

    @Test func structureReadLinesNamesTheWeakClose() {
        let weak = MemorabilityAnalyzer.Read(opening: .oriented, closing: .trailedOff(tail: "so yeah"))
        let lines = CoachContextBuilder.structureReadLines(for: weak)
        #expect(lines != nil)
        #expect(lines?.contains(where: { $0.contains("so yeah") }) == true)
    }

    @Test func multiWordSuffixTrailOffIsCaught() {
        let t = "Today I'll cover the migration plan and the rollback path in case we need it. We tested both this week, and that's pretty much it."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        if case .trailedOff = read.closing {} else { Issue.record("expected trailedOff for multi-word '...that's pretty much it'") }
    }

    @Test func singleWeakWordInCommittedCloseDoesNotFlag() {
        // Ends with the word "thanks" as committed content, not a weak close —
        // a single-word weak token only counts when it IS the whole tail.
        let t = "Today, here's what shipped and why the team pulled it off under the deadline. The launch held, and that is what earned their thanks."
        let read = MemorabilityAnalyzer.analyze(transcript: t)
        #expect(read.closing == .landed)
    }
}

/// The model can have the right context and still draft a reply that feels like
/// a generic AI assistant. These tests pin the pure gate the service uses before
/// a live reply reaches the store: obvious menus, bare clarification, robotic
/// phrases, defensive product language, and text-mode overlength get repaired
/// or replaced instead of shipped verbatim.
struct AICoachChatReplyQualityGateTests {

    @Test func acceptsConciseGroundedCoachReply() {
        let reply = "The pattern I'd watch is the rushed close. Yesterday's timed rep had 5 fillers; next rep, hold a beat before sentence two."
        #expect(AICoachChatService.replyQualityIssue(in: reply) == nil)
    }

    @Test func rejectsRoboticTemplatePhrase() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Based on your data, the key insight is that you should optimize your opening."
        )
        #expect(issue == .roboticPhrase("based on your data"))
    }

    @Test func rejectsReportStyleDeclinePhrase() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Recent reps show a decline in scores, so target fillers next."
        )
        #expect(issue == .roboticPhrase("recent reps show"))
    }

    @Test func rejectsUnderstoodOpening() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Understood. Your last rep suggests the close needs more authority."
        )
        #expect(issue == .roboticPhrase("understood"))
    }

    @Test func rejectsLetsRegister() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Let's focus on vocal variety in the next rep."
        )
        #expect(issue == .roboticPhrase("let's"))
    }

    @Test func rejectsLetUsRegister() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Let us test the silent pause in your next rep."
        )
        #expect(issue == .roboticPhrase("let us"))
    }

    @Test func rejectsAssistantExplainerRegister() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "I understand your frustration. Here are some tips to communicate more clearly: be clear and concise."
        )
        #expect(issue == .roboticPhrase("i understand your frustration"))
    }

    @Test func rejectsPatronizingSimplificationRegister() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Effective communication is important. In order to improve, try to be more confident."
        )
        #expect(issue == .roboticPhrase("in order to improve"))
    }

    @Test func rejectsInternalCognitiveJargon() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Your retrieval load rises under pressure, so pause before sentence two.",
            latestUserTurn: "Why do I keep saying um?"
        )
        #expect(issue == .roboticPhrase("retrieval load"))
    }

    @Test func rejectsInternalProfileLanguageInCoachReply() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "You do not have rated sessions or a chosen profile yet, so record one baseline answer.",
            latestUserTurn: "How do I get better before my interview?"
        )
        #expect(issue == .roboticPhrase("chosen profile"))
    }

    @Test func rejectsFormalNoBaselineOpening() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "Since we do not have any rated sessions yet, run one baseline practice rep now.",
            latestUserTurn: "How do I get better before my interview?"
        )
        #expect(issue == .roboticPhrase("since we do not have"))
    }

    @Test func rejectsFormalRatedSessionsColdStartOpening() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "We do not have any rated sessions yet, so run one baseline interview answer now.",
            latestUserTurn: "How do I get better before my interview?"
        )
        #expect(issue == .roboticPhrase("we do not have any rated sessions"))
    }

    @Test func rejectsUserFacingRatedSessionJargonOnColdStart() {
        let issue = AICoachChatService.replyQualityIssue(
            in: "I don't have rated sessions yet, so the useful first move is a baseline interview answer.",
            latestUserTurn: "How do I get better before my interview?"
        )
        #expect(issue == .roboticPhrase("i don't have rated sessions"))
    }

    @Test func rejectsColdStartIntakeQuestionAfterBaselineMove() {
        let context = """
        PROFESSIONAL TURN CONTRACT
        - Personalization floor: no rated sessions yet.
        GOAL
        - No voice set yet.
        BASELINE
        - Not enough data for a stable baseline yet.
        """
        let issue = AICoachChatService.replyQualityIssue(
            in: "No baseline yet, so run one timed rep on a likely interview question. What's the interview for?",
            latestUserTurn: "How do I get better before my interview?",
            systemContext: context
        )
        #expect(issue == .menuInsteadOfDecision)
    }

    @Test func rejectsColdStartProductModeBeforeBaseline() {
        let context = """
        PROFESSIONAL TURN CONTRACT
        - Personalization floor: no rated sessions yet.
        GOAL
        - No voice set yet.
        BASELINE
        - Not enough data for a stable baseline yet.
        """
        let issue = AICoachChatService.replyQualityIssue(
            in: "No baseline yet, so do one Ah-Counter round for 60 seconds on a topic you know well.",
            latestUserTurn: "What should I work on?",
            systemContext: context
        )
        #expect(issue == .roboticPhrase("cold-start product mode"))
    }

    @Test func rejectsColdStartNumericFillerTargetBeforeBaseline() {
        let context = """
        PROFESSIONAL TURN CONTRACT
        - Personalization floor: no rated sessions yet.
        GOAL
        - No voice set yet.
        BASELINE
        - Not enough data for a stable baseline yet.
        """
        let issue = AICoachChatService.replyQualityIssue(
            in: "No baseline yet, so record 60 seconds on something you know cold, aiming to stay under 4 fillers.",
            latestUserTurn: "What should I work on?",
            systemContext: context
        )
        #expect(issue == .roboticPhrase("cold-start metric target"))
    }

    @Test func rejectsColdStartWordedFillerTargetBeforeBaseline() {
        let context = """
        PROFESSIONAL TURN CONTRACT
        - Personalization floor: no rated sessions yet.
        GOAL
        - No voice set yet.
        BASELINE
        - Not enough data for a stable baseline yet.
        """
        let issue = AICoachChatService.replyQualityIssue(
            in: "No baseline yet, so record 60 seconds on something you know cold and stay below four fillers.",
            latestUserTurn: "Where should I start?",
            systemContext: context
        )
        #expect(issue == .roboticPhrase("cold-start metric target"))
    }

    @Test func rejectsColdStartFirstNumberFramingOnStartVariant() {
        let context = """
        PROFESSIONAL TURN CONTRACT
        - Personalization floor: no rated sessions yet.
        BASELINE
        - Not enough data for a stable baseline yet.
        """
        let issue = AICoachChatService.replyQualityIssue(
            in: "No baseline yet, so do one Ah-Counter round and get your first number.",
            latestUserTurn: "I'm new here. What first?",
            systemContext: context
