        #expect(!lower.contains("sudden death"))
        #expect(!lower.contains("im conversation"))
        #expect(!lower.contains("first number"))
        #expect(AICoachChatService.replyQualityIssue(
            in: repair,
            latestUserTurn: turn,
            systemContext: system
        ) == nil)
    }

    @Test func safeReferenceRepairAcceptsColdStartMetricTargetIssue() throws {
        let turn = "What should I work on?"
        let system = """
        PROFESSIONAL TURN CONTRACT
        - Personalization floor: no rated sessions yet.
        BASELINE
        - Not enough data for a stable baseline yet.
        """
        let repair = try #require(AICoachChatService.safeReferenceRepairReply(
            issue: .roboticPhrase("cold-start metric target"),
            latestUserTurn: turn,
            system: system,
            quoteGuard: nil,
            turnDepth: .groundedRead
        ))
        let lower = repair.lowercased()

        #expect(repair.contains("No baseline yet"))
        #expect(repair.contains("Record 60 seconds"))
        #expect(!lower.contains("under 4 fillers"))
        #expect(!lower.contains("first number"))
        #expect(!repair.contains("?"))
        #expect(AICoachChatService.replyQualityIssue(
            in: repair,
            latestUserTurn: turn,
            systemContext: system
        ) == nil)
    }

    @Test func safeReferenceRepairAcceptsColdStartIntakeQuestionIssue() throws {
        let turn = "How do I get better before my interview?"
        let system = """
        PROFESSIONAL TURN CONTRACT
        - Personalization floor: no rated sessions yet.
        BASELINE
        - Not enough data for a stable baseline yet.
        """
        let repair = try #require(AICoachChatService.safeReferenceRepairReply(
            issue: .menuInsteadOfDecision,
            latestUserTurn: turn,
            system: system,
            quoteGuard: nil,
            turnDepth: .groundedRead
        ))

        #expect(repair.contains("No baseline yet"))
        #expect(repair.contains("Record 60 seconds on one likely question"))
        #expect(!repair.contains("?"))
        #expect(AICoachChatService.replyQualityIssue(
            in: repair,
            latestUserTurn: turn,
            systemContext: system
        ) == nil)
    }

    @Test func safeReferenceRepairDoesNotRewriteColdStartIssueWithRecentEvidence() {
        let repair = AICoachChatService.safeReferenceRepairReply(
            issue: .roboticPhrase("cold-start metric target"),
            latestUserTurn: "What should I work on?",
            system: """
            RECENT (most-recent first)
            - Your last rep had 4 fillers and a late close.
            """,
            quoteGuard: nil,
            turnDepth: .groundedRead
        )

        #expect(repair == nil)
    }

    @Test func quoteGuardRejectsUnverifiedYouSaidQuote() {
        let guardContext = CoachChatQuoteGuardContext(
            transcripts: ["We launched the product on Tuesday and handled the deadline well."],
            latestUserTurn: "How did that answer land?"
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "You said \"revenue is up twenty percent\", but the move is simpler: next rep, lead with the point.",
            latestUserTurn: "How did that answer land?",
            quoteGuard: guardContext
        )

        #expect(issue == .unverifiedQuotedUserSpeech)
    }

    @Test func quoteGuardAllowsExactTranscriptQuote() {
        let guardContext = CoachChatQuoteGuardContext(
            transcripts: ["I want to let the silence work before I close."],
            latestUserTurn: "How did that answer land?"
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "You said \"let the silence work\", and that is the useful signal. Next rep, hold the pause before your close.",
            latestUserTurn: "How did that answer land?",
            quoteGuard: guardContext
        )

        #expect(issue == nil)
    }

    @Test func gateTwoIgnoresContractionApostrophesAsQuotes() {
        // Regression: the straight apostrophe (U+0027) is also the contraction
        // glyph. A grounded reply with a "you said" attribution AND two
        // contractions ("you're" … "I'd") used to have the text BETWEEN the two
        // apostrophes ("re rushing the close, so I") scraped out as a bogus
        // quoted fragment, which then failed Gate 2 and killed a legitimate
        // reply into .unverifiedQuotedUserSpeech. The source engages the reply
        // (shares "rushing"/"close") so Gate 1 passes, but does NOT contain that
        // spurious fragment verbatim — so pre-fix this returned the issue.
        let guardContext = CoachChatQuoteGuardContext(
            transcripts: ["I keep rushing the close on every rep."],
            latestUserTurn: "How did that answer land?"
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "You said you're rushing the close, so I'd hold a beat before sentence two.",
            latestUserTurn: "How did that answer land?",
            quoteGuard: guardContext
        )

        #expect(issue == nil)

        // The fragment scraper no longer treats contraction apostrophes as
        // quotation: no straight-single-quoted fragments come back at all.
        let fragments = AICoachChatService.quotedFragments(
            in: "You said you're rushing the close, so I'd hold a beat before sentence two."
        )
        #expect(fragments.isEmpty)

        // A genuine straight-single-quoted phrase is still extracted, so Gate 2
        // keeps catching fabricated 'quotes' — the boundary fix is surgical.
        let realQuote = AICoachChatService.quotedFragments(
            in: "You said 'let the silence work' before your close."
        )
        #expect(realQuote.contains("let the silence work"))
    }

    @Test func quoteGuardAllowsVerifiedProofQuote() {
        let guardContext = CoachChatQuoteGuardContext(
            verifiedProofQuotes: ["we focused on three priorities"],
            latestUserTurn: "What should I keep?"
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "Your words were \"we focused on three priorities\", so keep that clean frame. Next rep, close with the same structure.",
            latestUserTurn: "What should I keep?",
            quoteGuard: guardContext
        )

        #expect(issue == nil)
    }

    @Test func gateOneAcceptsReadOfEarlierChatTurn() {
        // Regression (owner bug 2026-06-10: "chat says the same thing over
        // and over"): "you mentioned X" referencing a user message from
        // EARLIER in the conversation — not the latest turn, not a rep
        // transcript — is a real read of real user words. Without the
        // conversation sources, Gate 1 rejected every such reply into the
        // same deterministic fallback on every turn.
        // Reuses the reply shape the rubric already accepts (see
        // dualGatePassesTranscriptClaimThatEngagesTranscript) but grounds it
        // ONLY in an earlier conversation turn: the decoy transcript and the
        // latest turn share no >=4-char content word with the reply, so the
        // earlier turn ("product… deadline") is the sole legitimate source.
        let reply = "You opened with the product launch and the deadline held; next rep, make the close the ask."
        let conversationContext = CoachChatQuoteGuardContext(
            transcripts: ["I practiced pacing this morning."],
            latestUserTurn: "How did I do?",
            recentUserTurns: [
                "Last week we shipped the product and barely hit the deadline.",
                "How did I do?"
            ]
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: reply,
            latestUserTurn: "How did I do?",
            quoteGuard: conversationContext
        )
        #expect(issue == nil)

        // Same reply WITHOUT the conversation sources still fails Gate 1 —
        // the anti-fabrication floor is unchanged.
        let bareContext = CoachChatQuoteGuardContext(
            transcripts: ["I practiced pacing this morning."],
            latestUserTurn: "How did I do?"
        )
        let bareIssue = AICoachChatService.replyQualityIssue(
            in: reply,
            latestUserTurn: "How did I do?",
            quoteGuard: bareContext
        )
        #expect(bareIssue == .unengagedUserSpeechClaim)
    }

    // MARK: Dual gate — Gate 1 (presence/engagement, the
    // PostRepCoachNoteService.engagesTranscript standard applied to chat).
    // Gate 2 (above) catches fabricated QUOTES; these pin the half the chat
    // was missing: a reply that claims a read of the user's words WITHOUT
    // quoting must still touch a known source.

    @Test func dualGateRejectsQuoteFreeFabricatedTranscriptClaim() {
        // The reply narrates an opening the user never gave — no quotation
        // marks, so Gate 2 cannot see it. Gate 1 must reject it: zero shared
        // content words and no verbatim slice against any source.
        let guardContext = CoachChatQuoteGuardContext(
            transcripts: ["We launched the product on Tuesday and handled the deadline well."],
            latestUserTurn: "How did I do?"
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "You opened with the budget shortfall and argued for headcount; next rep, lead with your strongest number.",
            latestUserTurn: "How did I do?",
            quoteGuard: guardContext
        )

        #expect(issue == .unengagedUserSpeechClaim)
    }

    @Test func dualGatePassesTranscriptClaimThatEngagesTranscript() {
        // Same claim shape, but genuinely grounded: shares content words
        // with the rep transcript, so the presence gate passes.
        let guardContext = CoachChatQuoteGuardContext(
            transcripts: ["We launched the product on Tuesday and handled the deadline well."],
            latestUserTurn: "How did I do?"
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "You opened with the product launch and the deadline held; next rep, make the close the ask.",
            latestUserTurn: "How did I do?",
            quoteGuard: guardContext
        )

        #expect(issue == nil)
    }

    @Test func dualGateAllowsLatestTurnGroundedSpeechClaim() {
        // "You said ..." in chat often reads the user's latest MESSAGE, not
        // a rep. Engagement against the latest turn keeps those replies live
        // instead of falsely downgrading them to the deterministic fallback.
        let guardContext = CoachChatQuoteGuardContext(
            transcripts: ["We launched the product on Tuesday and handled the deadline well."],
            latestUserTurn: "I keep rambling when I get nervous."
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "You said the rambling starts when nerves spike, so the useful test is a hard cap. Run one answer in two sentences, then stop.",
            latestUserTurn: "I keep rambling when I get nervous.",
            quoteGuard: guardContext
        )

        #expect(issue == nil)
    }

    @Test func dualGateIgnoresMetricRepMentionsWithoutSpeechClaim() {
        // Citing rep METRICS is not a claim about the user's words — the
        // system prompt explicitly endorses this shape, so the presence gate
        // must not fire on it even with zero transcript overlap.
        let guardContext = CoachChatQuoteGuardContext(
            transcripts: ["We launched the product on Tuesday and handled the deadline well."],
            latestUserTurn: "How did I do?"
        )
        let issue = AICoachChatService.replyQualityIssue(
            in: "Yesterday's rep had 5 fillers; the fix is a held pause after sentence two.",
            latestUserTurn: "How did I do?",
            quoteGuard: guardContext
        )

        #expect(issue == nil)
    }

    @Test func dualGateRejectsSpeechClaimWhenNoSourcesExist() {
        // No transcript, no proofs, no latest turn -> a claimed read is
        // unverifiable, mirroring Gate 2's rejection of unverifiable quotes.
        let guardContext = CoachChatQuoteGuardContext()
        let issue = AICoachChatService.replyQualityIssue(
            in: "You said you wanted a stronger close, so tonight hold the final line.",
            latestUserTurn: nil,
            quoteGuard: guardContext
        )

        #expect(issue == .unengagedUserSpeechClaim)
    }

    @Test func claimsUserSpeechReadScopesTheGateCorrectly() {
        // Positive: attribution families that claim the user's words.
        #expect(AICoachChatService.claimsUserSpeechRead(in: "You mentioned the board meeting."))
        #expect(AICoachChatService.claimsUserSpeechRead(in: "Your phrasing on the close softened."))
        #expect(AICoachChatService.claimsUserSpeechRead(in: "You opened with the mission."))
        // Negative: prescriptions and third-person reads are not claims
        // about what the user said.
        #expect(!AICoachChatService.claimsUserSpeechRead(in: "Next rep, hold a beat before sentence two."))
        #expect(!AICoachChatService.claimsUserSpeechRead(in: "The opening carried the point; the close softened."))
    }
}

/// Exact transcript-regression harness for the 2026-06-27 live coach eval.
///
/// This is not an expert-calibration claim; it keeps the known live failures
/// from drifting back in when provider prompts, fallback order, or repair copy
/// change. The reference replies are compact "what good looks like" examples
/// that must pass the same local senior-coach gate the product uses.
struct CoachLiveTranscriptRegressionTests {
    private struct Case {
        let id: String
        let userTurn: String
        let liveReply: String
        let expectedIssue: CoachChatReplyQualityIssue?
        let referenceReply: String
        let quoteGuard: CoachChatQuoteGuardContext?

        init(
            id: String,
            userTurn: String,
            liveReply: String,
            expectedIssue: CoachChatReplyQualityIssue?,
            referenceReply: String,
            quoteGuard: CoachChatQuoteGuardContext? = nil
        ) {
            self.id = id
            self.userTurn = userTurn
            self.liveReply = liveReply
            self.expectedIssue = expectedIssue
            self.referenceReply = referenceReply
            self.quoteGuard = quoteGuard
        }
    }

    private static let transcriptCases: [Case] = [
        Case(
            id: "interview-baseline",
            userTurn: "How do I get better before my interview?",
            liveReply: "No rated sessions yet, so the honest starting point is: I don't know which part of your delivery needs the most work.\nRun one timed rep - pick a likely interview question, answer it out loud for 60-90 seconds, then note where you hesitated or rushed. That gives us something real to coach from.\nWhat's the interview for?",
            expectedIssue: .roboticPhrase("no rated sessions yet"),
            referenceReply: "No baseline yet, so start there. Record 60 seconds on one likely interview question, then review whether your first sentence answers it before polishing anything."
        ),
        Case(
            id: "fillers-under-pressure",
            userTurn: "How do I stop saying um under pressure?",
            liveReply: "Your last rep had 6 fillers under a timed limit, so the pattern is there when the clock runs.\nTo break this, test the silent pause: the moment you feel an um coming, hold one second of silence instead, then say the next word.\nRun one rep now with that silent beat to see if it stops the filler.",
            expectedIssue: .roboticPhrase("to break this"),
            referenceReply: "Your last rep had 6 fillers, so use the silent beat as a test. Hold one second before the next word and see whether the filler count drops on the next rep."
        ),
        Case(
            id: "filler-count",
            userTurn: "What should I do with that filler count?",
            liveReply: "Your last rep had five fillers, so test a slow open on your next run to give yourself room to find the second sentence. Say your first line slower than feels natural, which can replace the early um with a silent beat.",
            expectedIssue: .roboticPhrase("give yourself room to find"),
            referenceReply: "Five fillers is enough signal to test the opening, not judge the whole answer. Say the first line slower than feels natural, then hold one beat before sentence two."
        ),
        Case(
            id: "robotic-feedback",
            userTurn: "This is robotic and too much writing.",
            liveReply: "You are right to call that out, and I am cutting the robotic report voice. Your last rep had one filler, so record a new rep where you say the main point in your very first sentence and then stop.",
            expectedIssue: .roboticPhrase("i am cutting the"),
            referenceReply: "Fair push. That read like a report. Your last rep had one filler, so run one cleaner rep: main point first, then stop."
        ),
        Case(
            id: "markdown-tts",
            userTurn: "The ** don't format and TTS reads them out. The responses feel robotic and cold, nowhere near an expert coach.",
            liveReply: "Fair push. I'll cut the markers and the report voice - your last rep gives me enough to work from, so next time out, lead with your recommendation in the first sentence and stop there.",
            expectedIssue: .roboticPhrase("i'll cut the markers"),
            referenceReply: "Fair push: TTS reading symbols breaks trust. Your last rep has enough signal, so lead with the recommendation, give one proof point, then stop."
        ),
        Case(
            id: "cold-overexplained",
            userTurn: "This still sounds cold and overexplained, like generic AI tips.",
            liveReply: "You are right to call that out, as that generic tip-giving was cold and did not help. Your last rep had one filler but the main point did not clearly lead, so open your next attempt by saying your core client recommendation in the very first sentence because that tests whether a strong start helps you feel in control.",
            expectedIssue: .roboticPhrase("generic tip-giving"),
            referenceReply: "Fair push: that was advice, not coaching. Your last rep had one filler, so say the client recommendation first, then soften it with one reassurance."
        ),
        Case(
            id: "what-next",
            userTurn: "What next?",
            liveReply: "Your last rep had no fillers, so the gap to close is the ending - run the same executive update and finish on one specific decision or next step you want from the room.",
            expectedIssue: nil,
            referenceReply: "Your last rep was clean on fillers, so the useful gap is the close. Run the same executive update and end with the one decision or next step you want from the room."
        ),
        Case(
            id: "why-landed-badly",
            userTurn: "Why did that answer land badly?",
            liveReply: "Your last rep put the recommendation right up front, but you asserted the claim without giving a reason or an implication to back it up. That risks sounding like an opinion rather than an authoritative verdict, so run a rep where you state the point, give one clear reason, and name the impact if we do not act.",
            expectedIssue: .overclaimsEvidence,
            referenceReply: "From the transcript, the recommendation arrived late, so the first fix is order. Say the decision first, add one reason, then name the implication.",
            quoteGuard: CoachChatQuoteGuardContext(
                transcripts: ["I waited too long to state the recommendation, then gave the context after it."],
                latestUserTurn: "Why did that answer land badly?"
            )
        ),
        Case(
            id: "leadership-update",
            userTurn: "I have a leadership update tomorrow, what should I practice?",
            liveReply: "Your last rep led with the point cleanly, so test the thirty-second update for tomorrow's meeting. State your main headline and what it means in the first sentence, because a senior room wants the implication immediately.",
            expectedIssue: .roboticPhrase("a senior room wants"),
            referenceReply: "Your last rep led cleanly, so tomorrow's practice should sharpen the ask. Run a 30-second update: headline, implication, one decision you need."
        )
    ]

    @Test func liveTranscriptRowsStayVersioned() {
        #expect(Self.transcriptCases.map(\.id) == [
            "interview-baseline",
            "fillers-under-pressure",
            "filler-count",
            "robotic-feedback",
            "markdown-tts",
            "cold-overexplained",
            "what-next",
            "why-landed-badly",
            "leadership-update"
        ])
    }

    @Test func knownLiveFailuresTripTheLocalCoachGate() {
        for row in Self.transcriptCases {
            let issue = AICoachChatService.replyQualityIssue(
                in: row.liveReply,
                latestUserTurn: row.userTurn,
                quoteGuard: row.quoteGuard
            )
            #expect(issue == row.expectedIssue,
                    "\(row.id) expected \(String(describing: row.expectedIssue)), got \(String(describing: issue))")
        }
    }

    @Test func referenceRepliesPassTheSeniorCoachGate() {
        for row in Self.transcriptCases {
            let issue = AICoachChatService.replyQualityIssue(
                in: row.referenceReply,
                latestUserTurn: row.userTurn,
                quoteGuard: row.quoteGuard
            )
            let rubric = AICoachChatService.professionalCoachRubric(
                reply: row.referenceReply,
                latestUserTurn: row.userTurn
            )
            #expect(issue == nil, "\(row.id) reference reply issue: \(String(describing: issue))")
            #expect(rubric.passesSeniorCoachFloor,
                    "\(row.id) reference reply should pass. Misses: \(rubric.misses)")
        }
    }
}

/// Cross-surface fabricated-quote guard.
///
/// The live chat already routes "you said …" attributions through
/// `ProofMomentService.transcriptContains`. These tests pin that the SAME guard
/// now governs the two other AI prose surfaces that quote the user — the
/// post-rep coach note and the sessionDebrief insight — so a fabricated quote
/// cannot reach the user on any surface dressed as proof. The guard is exercised
/// directly (the network paths in `generate()` / `insight()` need a provider);
/// both call sites build the guard from the rep transcript exactly as below.
struct CrossSurfaceQuoteFabricationGuardTests {

    /// A coach note that ATTRIBUTES a quote the transcript never contained is
    /// flagged — the note path falls back to the deterministic, non-quoting note.
    @Test func noteWithFabricatedAttributedQuoteIsRejected() {
        let transcript = "I opened with the company mission and then walked through the roadmap."
        let guardContext = CoachChatQuoteGuardContext(transcripts: [transcript])
        let note = "You said \"we crushed the quarterly target\" — strong, but next rep, land the point sooner."
        #expect(AICoachChatService.containsUnverifiedQuotedUserSpeech(in: note, quoteGuard: guardContext))
    }

    /// A note quoting words the user ACTUALLY said (flexible match) is allowed.
    @Test func noteWithVerifiedAttributedQuotePasses() {
        let transcript = "I opened with the company mission and then walked through the roadmap."
        let guardContext = CoachChatQuoteGuardContext(transcripts: [transcript])
        let note = "You said \"the company mission\" up front, which framed the rest. Next rep, close with the same clarity."
        #expect(!AICoachChatService.containsUnverifiedQuotedUserSpeech(in: note, quoteGuard: guardContext))
    }

    /// Prose that quotes WITHOUT a "you said …" attribution (e.g. naming a
    /// technique) is not user-speech and is not falsely rejected.
    @Test func proseQuotingWithoutAttributionIsNotFlagged() {
        let transcript = "I rushed the close and forgot to pause."
        let guardContext = CoachChatQuoteGuardContext(transcripts: [transcript])
        let note = "The move is the \"land the pause\" drill: hold one beat before your final line."
        #expect(!AICoachChatService.containsUnverifiedQuotedUserSpeech(in: note, quoteGuard: guardContext))
    }

    /// sessionDebrief headline+body assembly: an attributed quote absent from
    /// the rep transcript is flagged, so the insight path uses its template.
    @Test func insightProseWithFabricatedQuoteIsRejected() {
        let transcript = "I think the timeline slipped a little but we recovered by Friday."
        let guardContext = CoachChatQuoteGuardContext(transcripts: [transcript])
        let prose = "Strong recovery\nYou said \"we hit every milestone on time\", which anchored your close."
        #expect(AICoachChatService.containsUnverifiedQuotedUserSpeech(in: prose, quoteGuard: guardContext))
    }

    /// The production sessionDebrief helper applies the same guard to
    /// headline+body and falls back when the quote cannot be verified.
    @Test func insightHelperRejectsFabricatedAttributedQuote() {
        let insight = AIInsight(
            kind: .sessionDebrief,
            headline: "Strong recovery",
            body: "You said \"we hit every milestone on time\", which anchored your close.",
            evidence: ["Recovered by Friday"],
            action: "Close with the same structure.",
            isAIBacked: true,
            generatedAt: Date()
        )
        #expect(AIInsightsService.containsUnverifiedSessionDebriefQuote(
            insight: insight,
            transcript: "I think the timeline slipped a little but we recovered by Friday."
        ))
    }

    /// Empty/silent sessionDebriefs have no source text, so attributed quotes
    /// are rejected instead of passing because the transcript branch is absent.
    @Test func insightHelperRejectsAttributedQuoteWhenTranscriptIsEmpty() {
        let insight = AIInsight(
            kind: .sessionDebrief,
            headline: "That line landed",
            body: "You said \"that landed perfectly\", so keep the same close.",
            evidence: ["Transcript unavailable"],
            action: "Repeat the close once.",
            isAIBacked: true,
            generatedAt: Date()
        )
        #expect(AIInsightsService.containsUnverifiedSessionDebriefQuote(
            insight: insight,
            transcript: ""
        ))
    }

    /// On an empty transcript (IM / silent rep) there is nothing to verify
    /// against, so any attributed quote is unverifiable → flagged → fallback.
    @Test func attributedQuoteOnEmptyTranscriptIsRejected() {
        let guardContext = CoachChatQuoteGuardContext(transcripts: [""])
        let note = "You said \"that landed perfectly\" — keep that energy next time."
        #expect(AICoachChatService.containsUnverifiedQuotedUserSpeech(in: note, quoteGuard: guardContext))
    }
}

/// Version-controlled Ask Noum evaluation fixtures.
///
/// This is the first VALIDATE-1 substrate: a small, leak-guarded set of
/// representative coaching moments that must clear the same context builder
/// and reply rubric the live coach uses. It is not expert calibration and it
/// does not claim parity with a human coach; it catches obvious non-coach
/// behavior before the product ships it.
struct CoachChatEvaluationFixtureTests {

    @Test func fixtureIDsAreStableAndUnique() {
        let ids = CoachChatEvaluationCorpus.fixtures.map(\.id)
        #expect(Set(ids).count == ids.count)
        for id in ids {
            #expect(id.range(of: #"^[a-z0-9]+(-[a-z0-9]+)*$"#, options: .regularExpression) != nil,
                    "Fixture id should be stable slug copy: \(id)")
        }
    }

    @Test func fixturesCoverCoreCoachParityPillars() {
        let covered = Set(CoachChatEvaluationCorpus.fixtures.map(\.pillar))
        #expect(covered == Set(CoachChatEvaluationPillar.allCases),
                "Fixtures should cover every core coach-parity evaluation pillar.")
    }

    @Test func fixturesBuildContextThroughCoachContextBuilder() {
        for fixture in CoachChatEvaluationCorpus.fixtures {
            let context = CoachChatEvaluationCorpus.renderedContext(for: fixture)
            #expect(CoachChatEvaluationCorpus.contains(context, "PROFESSIONAL TURN CONTRACT"),
                    "\(fixture.id) should carry the turn-level professional contract.")
            #expect(CoachChatEvaluationCorpus.contains(context, "No broad menu"),
                    "\(fixture.id) should instruct the coach to avoid broad menus.")
            for needle in fixture.expectedContextNeedles {
                #expect(CoachChatEvaluationCorpus.contains(context, needle),
                        "\(fixture.id) missing expected context needle: \(needle)\n\(context)")
            }
        }
    }

    @Test func fixturesRenderProductionLikeCoachingExpertiseWhenRetrieved() {
        for fixture in CoachChatEvaluationCorpus.fixtures {
            let context = CoachChatEvaluationCorpus.renderedContext(for: fixture)
            let expertise = CoachChatEvaluationCorpus.deterministicCoachingExpertise(for: fixture)
            if expertise.isEmpty {
                #expect(!CoachChatEvaluationCorpus.contains(context, "COACHING EXPERTISE"),
                        "\(fixture.id) should omit an empty expertise block.")
            } else {
                #expect(CoachChatEvaluationCorpus.contains(context, "COACHING EXPERTISE"),
                        "\(fixture.id) should carry retrieved coaching expertise.")
                for card in expertise {
                    #expect(CoachChatEvaluationCorpus.contains(context, card.id)
                            || CoachChatEvaluationCorpus.contains(context, card.technique)
                            || CoachChatEvaluationCorpus.contains(context, card.title),
                            "\(fixture.id) missing retrieved card \(card.id)")
                }
            }
        }
    }

    @Test func referenceSeniorRepliesPassTheProfessionalRubric() {
        for fixture in CoachChatEvaluationCorpus.fixtures {
            let context = CoachChatEvaluationCorpus.renderedContext(for: fixture)
            let result = AICoachChatService.professionalCoachRubric(
                reply: fixture.referenceReply,
                latestUserTurn: fixture.latestUserTurn
            )
            #expect(result.passesSeniorCoachFloor,
                    "\(fixture.id) reference reply should pass. Misses: \(result.misses)")
            let qualityIssue = AICoachChatService.replyQualityIssue(
                in: fixture.referenceReply,
                latestUserTurn: fixture.latestUserTurn,
                quoteGuard: CoachChatEvaluationCorpus.quoteGuard(for: fixture),
                systemContext: context
            )
            #expect(qualityIssue == nil,
                    "\(fixture.id) reference reply tripped quality gate: \(String(describing: qualityIssue))")
        }
    }

    @Test func knownBadRepliesFailForTheIntendedReason() {
