// MARK: - WPM zone band ratio + label contracts
//
// The zone band on `TimedHistoryBreakdownCard` is a visual restatement
// of `inZoneRepCount / runCount`. The view itself isn't unit-tested
// (SwiftUI rendering), but the underlying ratio + range constants are.

struct TimedHistoryZoneBandContractTests {

    @Test func zoneRangeConstantsLockedToWPMEvaluatorTimedBand() {
        // The card subtitle quotes the same shared conversational band
        // used by pace training and coach feedback. A future engine-side
        // tweak should fail this contract on purpose.
        #expect(TimedHistorySummary.zoneMinWPM == 110)
        #expect(TimedHistorySummary.zoneMaxWPM == 150)
        #expect(TimedHistorySummary.zoneMinWPM < TimedHistorySummary.zoneMaxWPM)
    }

    @Test func inZoneCountStaysBoundedByRunCount() {
        // No run can be "in zone" more than once; the count cannot
        // exceed the total. Belt-and-braces — locks the invariant the
        // visual band depends on.
        let now = Date()
        let inZone = PracticeSession(
            transcript: String(repeating: "word ", count: 70), // ~140 WPM at 30s
            fillerWordCount: 0,
            duration: 30,
            date: now,
            mode: .timed,
            score: 8
        )
        let outOfZone = PracticeSession(
            transcript: String(repeating: "word ", count: 30),
            fillerWordCount: 0,
            duration: 30,
            date: now.addingTimeInterval(-3600),
            mode: .timed,
            score: 6
        )
        let stats = TimedHistorySummary.summarize(sessions: [inZone, outOfZone], now: now)
        #expect(stats?.inZoneRepCount ?? 0 <= stats?.runCount ?? 0)
    }
}

// MARK: - IMScenarioDetailView trust/tension trace + tone-match stats
//
// The detail view's two new analytical cards (trust/tension sparkline,
// tone-match strip) read from pure helpers on `IMHistorySummary`. The
// view itself is SwiftUI and not unit-tested; the helpers below carry
// the math + filter contracts the view depends on.

struct IMScenarioTracePointsTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        trust: Int,
        tension: Int,
        daysOffset: Double,
        hasFinalState: Bool = true
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: .confident),
                turns: [],
                actualTone: nil,
                finalState: hasFinalState
                    ? IMConversationState(trust: trust, engagement: 6, tension: tension, beat: "x")
                    : nil,
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func tracePointsEmptyOnEmptyInput() {
        let points = IMHistorySummary.tracePoints(from: [], scenario: .networking)
        #expect(points.isEmpty)
    }

    @Test func tracePointsOnlyIncludesRequestedScenario() {
        let sessions = [
            imSession(scenario: .networking, trust: 7, tension: 4, daysOffset: -3),
            imSession(scenario: .difficultConversation, trust: 4, tension: 8, daysOffset: -2),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -1)
        ]
        let points = IMHistorySummary.tracePoints(from: sessions, scenario: .networking)
        #expect(points.count == 2)
        #expect(points.allSatisfy { $0.trust >= 1 && $0.trust <= 10 })
    }

    @Test func tracePointsOrderedOldestToNewest() {
        let sessions = [
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -1), // newest
            imSession(scenario: .networking, trust: 6, tension: 6, daysOffset: -5), // oldest
            imSession(scenario: .networking, trust: 7, tension: 7, daysOffset: -3)  // middle
        ]
        let points = IMHistorySummary.tracePoints(from: sessions, scenario: .networking)
        #expect(points.count == 3)
        // Oldest first; newest last.
        #expect(points[0].trust == 6)
        #expect(points[1].trust == 7)
        #expect(points[2].trust == 5)
    }

    @Test func tracePointsDropsRepsWithoutFinalState() {
        let sessions = [
            imSession(scenario: .networking, trust: 7, tension: 4, daysOffset: -2),
            imSession(scenario: .networking, trust: 0, tension: 0, daysOffset: -1, hasFinalState: false)
        ]
        let points = IMHistorySummary.tracePoints(from: sessions, scenario: .networking)
        #expect(points.count == 1)
        #expect(points.first?.trust == 7)
    }

    @Test func tracePointsClampsToNormalizedRange() {
        // The engine's normalized accessors clamp 1...10. Even if a
        // bad fixture stored 0 / 99, the trace point reads through
        // the normalizer so the chart never plots out-of-band.
        let session = PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate,
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: .networking, targetTone: .confident),
                turns: [],
                actualTone: nil,
                finalState: IMConversationState(trust: 99, engagement: 6, tension: -5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
        let points = IMHistorySummary.tracePoints(from: [session], scenario: .networking)
        #expect(points.first?.trust == 10)
        #expect(points.first?.tension == 1)
    }

    @Test func tracePointsIgnoresNonIMSessions() {
        // Defensive: an upstream filter mistake passes a Timed rep —
        // the helper must drop it rather than coerce a state.
        let sessions = [
            imSession(scenario: .networking, trust: 7, tension: 4, daysOffset: -1),
            PracticeSession(
                transcript: "timed",
                fillerWordCount: 0,
                duration: 30,
                date: baseDate,
                mode: .timed,
                score: 9
            )
        ]
        let points = IMHistorySummary.tracePoints(from: sessions, scenario: .networking)
        #expect(points.count == 1)
    }
}

struct IMScenarioToneMatchStatsTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func toneMatchStatsEmptyOnEmptyInput() {
        let stats = IMHistorySummary.toneMatchStats(from: [], scenario: .networking)
        #expect(stats.evaluatedCount == 0)
        #expect(stats.matchCount == 0)
        #expect(stats.matchRate == nil)
        #expect(stats.lastFive.isEmpty)
    }

    @Test func toneMatchStatsIgnoresRepsWithoutActualTone() {
        // A rep that didn't produce an `actualTone` reading is not a
        // miss — it's missing data. Excluded from both numerator and
        // denominator so the rate stays honest.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: nil, daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2)
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .networking)
        #expect(stats.evaluatedCount == 1)
        #expect(stats.matchCount == 1)
        #expect(stats.matchRate == 1.0)
    }

    @Test func toneMatchStatsIgnoresWhitespaceOnlyActualTone() {
        // Whitespace-only `actualTone` is treated the same as nil —
        // the evaluator didn't actually produce a reading.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "   ", daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2)
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .networking)
        #expect(stats.evaluatedCount == 1)
    }

    @Test func toneMatchIsCaseInsensitive() {
        #expect(IMHistorySummary.matches(targetTone: .confident, actualTone: "CONFIDENT"))
        #expect(IMHistorySummary.matches(targetTone: .warm, actualTone: "very Warm and open"))
        #expect(IMHistorySummary.matches(targetTone: .professional, actualTone: "Professional, clipped"))
    }

    @Test func toneMatchSubstringContainment() {
        // The evaluator often qualifies the tone ("warmly confident").
        // A direct title hit still counts when it is not contradicted.
        #expect(IMHistorySummary.matches(targetTone: .confident, actualTone: "warmly confident"))
        #expect(!IMHistorySummary.matches(targetTone: .warm, actualTone: "professional and clipped"))
    }

    @Test func toneMatchRecognizesEvaluatorAliasesBeyondTitleSubstring() {
        #expect(IMHistorySummary.matches(targetTone: .calm, actualTone: "steady and composed"))
        #expect(IMHistorySummary.matches(targetTone: .warm, actualTone: "appreciative and collaborative"))
        #expect(IMHistorySummary.matches(targetTone: .professional, actualTone: "polished and structured"))
        #expect(IMHistorySummary.matches(targetTone: .assertive, actualTone: "firm and direct"))
        #expect(IMHistorySummary.matches(targetTone: .concise, actualTone: "brief and focused"))
    }

    @Test func toneMatchRejectsNegatedOrContradictoryReadouts() {
        #expect(!IMHistorySummary.matches(targetTone: .confident, actualTone: "not confident yet"))
        #expect(!IMHistorySummary.matches(targetTone: .calm, actualTone: "calm but rushed"))
        #expect(!IMHistorySummary.matches(targetTone: .assertive, actualTone: "assertive but aggressive"))
        #expect(!IMHistorySummary.matches(targetTone: .warm, actualTone: "warm but distant"))
        #expect(!IMHistorySummary.matches(targetTone: .professional, actualTone: "professional but scattered"))
    }

    @Test func toneMatchEmptyActualNeverMatches() {
        #expect(!IMHistorySummary.matches(targetTone: .confident, actualTone: ""))
        #expect(!IMHistorySummary.matches(targetTone: .confident, actualTone: "   "))
    }

    @Test func toneMatchStatsOnlyIncludesRequestedScenario() {
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -2)
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .networking)
        #expect(stats.evaluatedCount == 1)
        #expect(stats.matchCount == 1)
    }

    @Test func toneMatchStatsLastFiveOrderedNewestFirst() {
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -10),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -8),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .networking)
        #expect(stats.evaluatedCount == 6)
        #expect(stats.matchCount == 4)
        // 6 evaluated reps total → only the most recent 5 land in the
        // strip; the oldest "shaky" entry should be excluded.
        #expect(stats.lastFive.count == 5)
        #expect(stats.lastFive.first?.matched == true)  // newest
        #expect(stats.lastFive.allSatisfy { $0.id != sessions[0].id })  // oldest excluded
    }

    @Test func toneMatchStatsRateRounding() {
        // 2 of 3 matches → 0.67 (rounded to two decimals).
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -3)
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .networking)
        #expect(stats.matchRate == 0.67)
    }

    @Test func toneMatchStatsRateUsesAliasMatcher() {
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "steady and composed", daysOffset: -1),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm but rushed", daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -3)
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .difficultConversation)
        #expect(stats.evaluatedCount == 3)
        #expect(stats.matchCount == 1)
        #expect(stats.matchRate == 0.33)
    }

    @Test func toneMatchStatsIgnoresNonIMSessions() {
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1),
            PracticeSession(
                transcript: "timed",
                fillerWordCount: 0,
                duration: 30,
                date: baseDate,
                mode: .timed,
                score: 9
            )
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .networking)
        #expect(stats.evaluatedCount == 1)
        #expect(stats.matchCount == 1)
    }
}

struct IMToneMatcherContractTests {

    @Test func scoreRewardsMultiplePositiveSignals() {
        let transcript = "I recommend we move forward. I can own the decision and report the result by Friday."
        #expect(IMToneMatcher.score(for: .confident, transcript: transcript) >= 8)
        #expect(IMToneMatcher.score(for: .professional, transcript: transcript) >= 8)
    }

    @Test func scoreLetsCommitmentOffsetOneSoftHedge() {
        let transcript = "I think I can own the next step and I will send the proposal today."
        #expect(IMToneMatcher.score(for: .confident, transcript: transcript) >= 7)
    }

    @Test func scoreNormalizesCommonContractions() {
        #expect(IMToneMatcher.score(for: .confident, transcript: "I'm confident this is the right next step.") >= 8)
        #expect(IMToneMatcher.score(for: .assertive, transcript: "Let's set the decision today; I can't keep this open.") >= 8)
    }

    @Test func scorePenalizesContradictorySofteningOrEscalation() {
        #expect(IMToneMatcher.score(for: .assertive, transcript: "Sorry, maybe we could do that if that is okay.") <= 5)
        #expect(IMToneMatcher.score(for: .calm, transcript: "I just hate how urgent this is, and you always make it worse.") <= 5)
    }

    @Test func conciseScoreReadsLengthAndRambleSignals() {
        let concise = "Bottom line: approve the proposal, then I will send next steps."
        let rambling = String(repeating: "I mean basically kind of this needs a bit more context ", count: 8)

        #expect(IMToneMatcher.score(for: .concise, transcript: concise) >= 8)
        #expect(IMToneMatcher.score(for: .concise, transcript: rambling) <= 5)
    }
}

// MARK: - Cross-scenario tone-drill signal → recommendation engine
//
// The read side of the IM loop (per-scenario trust/tension + tone-match
// chips) is already surfaced on the History list and scenario detail.
// `IMHistorySummary.toneDrillSignal` is the *act* half: it picks the one
// scenario where the committed tone reliably misses, and
// `RecommendationBiasEngine.blueprint(... imToneSignal:)` turns it into a
// one-tap "drill this scenario's tone" recommendation that prefills the
// exact scenario + tone. These tests lock the honest evidence bar (rep
// count + sub-threshold rate), the worst-first selection, the dominant-
// tone choice, and the engine override.

struct IMToneDrillSignalTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    private func input() -> AIHomeRecommendationInput {
        AIHomeRecommendationInput(
            recentSessionSummary: "",
            averageFillers: 0,
            averageDuration: 0,
            averageWordsPerMinute: 0,
            fillerTrendDelta: 0,
            durationTrendDelta: 0,
            paceTrendDelta: 0,
            averageWordCount: 0,
            strongestMode: nil,
            currentIdentity: "",
            currentIdentityEvidence: "",
            sessionStreak: 0,
            daysSinceLastSession: 0,
            preferredModeBias: "",
            preferredToneBias: "",
            preferredScenarioBias: "",
            modeBenefitBias: ""
        )
    }

    private func caseMemory(
        status: CoachInterventionReviewStatus,
        followedRepCount: Int,
        minimumFollowedRepsForReview: Int = 2,
        target: String? = "One clean opening",
        criterion: CoachSuccessCriterion? = nil
    ) -> CoachMemory {
        CoachMemory(
            updatedAt: baseDate,
            evidenceCount: 5,
            evidenceConfidence: .tentative,
            currentLever: .fillerReduction,
            goalFit: .aligned,
            strengths: [],
            blockers: ["Filler words"],
            workingHypothesis: "Under pressure, fillers are still carrying the opening.",
            activeIntervention: CoachIntervention(
                title: "Clean up the opening",
                focus: "cleaner opening",
                target: target,
                mode: .ahCounter,
                prescribedAt: baseDate.addingTimeInterval(-3600),
                lastObservedAt: nil,
                followedRepCount: followedRepCount,
                minimumFollowedRepsForReview: minimumFollowedRepsForReview,
                reviewStatus: status,
                reviewBasis: "Still forming evidence.",
                successCriterion: criterion,
                criterionStatus: criterion == nil ? nil : .pending,
                reviewDueAt: baseDate.addingTimeInterval(86400)
            )
        )
    }

    @Test func signalNilOnEmptyHistory() {
        #expect(IMHistorySummary.toneDrillSignal(from: []) == nil)
    }

    @Test func signalNilBelowRepBar() {
        // Two evaluated misses is a bad day, not a pattern — below the
        // 3-rep bar the engine should not fabricate a drill.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky", daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed", daysOffset: -2)
        ]
        #expect(IMHistorySummary.toneDrillSignal(from: sessions) == nil)
    }

    @Test func signalNilWhenHitRateAtThreshold() {
        // 2 of 5 == exactly 0.40. The contract is *strictly below* the
        // threshold, so the boundary must not fire.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -5)
        ]
        let stats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .networking)
        #expect(stats.matchRate == 0.4)
        #expect(IMHistorySummary.toneDrillSignal(from: sessions) == nil)
    }

    @Test func signalFiresOnLowHitRateWithEnoughReps() {
        // 1 of 4 == 0.25, four evaluated reps — clears both bars.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",  daysOffset: -1),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -4)
        ]
        let signal = IMHistorySummary.toneDrillSignal(from: sessions)
        #expect(signal?.scenario == .difficultConversation)
        #expect(signal?.targetTone == .calm)
        #expect(signal?.evaluatedCount == 4)
        #expect(signal?.matchRate == 0.25)
    }

    @Test func signalPicksWorstScenario() {
        // Two qualifying scenarios; the lower hit rate (more leverage)
        // wins: networking 1/4 == 0.25 vs Work Update 0/4 == 0.0.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -4),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "scattered", daysOffset: -5),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "rushed",    daysOffset: -6),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",     daysOffset: -7),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "tense",     daysOffset: -8)
        ]
        let signal = IMHistorySummary.toneDrillSignal(from: sessions)
        #expect(signal?.scenario == .workUpdate)
        #expect(signal?.matchRate == 0.0)
    }

    @Test func signalTiebreakPrefersMoreEvidence() {
        // Equal hit rate (both 0.25); the scenario with more evaluated
        // reps is the more trustworthy read and wins the tiebreak:
        // Social Catch-Up 2/8 vs Networking 1/4.
        var sessions: [PracticeSession] = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -4)
        ]
        // Social Catch-Up: 2 matches, 6 misses == 2/8 == 0.25.
        sessions.append(imSession(scenario: .socialCatchUp, targetTone: .warm, actualTone: "warm", daysOffset: -10))
        sessions.append(imSession(scenario: .socialCatchUp, targetTone: .warm, actualTone: "warm", daysOffset: -11))
        for offset in 12...17 {
            sessions.append(imSession(scenario: .socialCatchUp, targetTone: .warm, actualTone: "flat", daysOffset: -Double(offset)))
        }
        let socialStats = IMHistorySummary.toneMatchStats(from: sessions, scenario: .socialCatchUp)
        #expect(socialStats.matchRate == 0.25)
        #expect(socialStats.evaluatedCount == 8)

        let signal = IMHistorySummary.toneDrillSignal(from: sessions)
        #expect(signal?.scenario == .socialCatchUp)
        #expect(signal?.evaluatedCount == 8)
    }

    @Test func signalTargetToneIsDominantCommittedTone() {
        // A scenario practiced with two different committed tones; the
        // drill should re-set the one the user reached for most (calm,
        // 3 reps) — not the minority (assertive, 1 rep).
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -1),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .assertive, actualTone: "soft", daysOffset: -4)
        ]
        let signal = IMHistorySummary.toneDrillSignal(from: sessions)
        #expect(signal?.targetTone == .calm)
        #expect(signal?.matchRate == 0.0)
        #expect(signal?.evaluatedCount == 4)
    }

    @Test func signalIgnoresRepsWithoutActualTone() {
        // Reps the evaluator never read (nil/blank actualTone) are
        // missing data, not misses — they must not pad the rep count
        // into clearing the bar on their own.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: nil, daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "  ", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed", daysOffset: -4)
        ]
        // Only 2 evaluated reps (the two non-blank) → below the rep bar.
        #expect(IMHistorySummary.toneDrillSignal(from: sessions) == nil)
    }

    @Test func blueprintFromToneSignalPrescribesScenarioDrill() {
        let signal = IMToneDrillSignal(
            scenario: .difficultConversation,
            targetTone: .calm,
            matchRate: 0.25,
            evaluatedCount: 4
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil,
            input: input(),
            plan: nil,
            imToneSignal: signal
        )
        #expect(blueprint.recommendedMode == .imConversation)
        #expect(blueprint.recommendedScenario == .difficultConversation)
        #expect(blueprint.recommendedTone == .calm)
        #expect(blueprint.focus == "Difficult Conversation tone")
        #expect(blueprint.target.contains("calm"))
        #expect(blueprint.target.contains("Difficult Conversation"))
        // Copy reports the observed hit rate honestly — no reframe.
        #expect(blueprint.whyNow.contains("25%"))
        #expect(blueprint.whyNow.contains("Difficult Conversation"))
        #expect(blueprint.whyNow.contains("4"))
    }

    @Test func blueprintWithoutSignalKeepsNormalBias() {
        // No signal → the engine falls back to its goal/baseline bias.
        // With a nil profile and a cold input it should NOT recommend an
        // IM scenario drill — regression guard on the override.
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil,
            input: input(),
            plan: nil
        )
        #expect(blueprint.recommendedMode == .timed)
        // Both nil on a non-IM recommendation. The picker + summary now
        // forward `recommendedScenario` / `recommendedTone` straight into
        // the IM destination, so this nil-when-off-IM contract is what
        // keeps a free-choice IM launch on the normal scenario grid
        // instead of a stale prefill.
        #expect(blueprint.recommendedScenario == nil)
        #expect(blueprint.recommendedTone == nil)
    }

    @Test func caseInterventionContinuesBeforeToneDrillSignal() {
        // A human coach should collect the minimum reps for the active
        // intervention before a different signal steals the next drill.
        let signal = IMToneDrillSignal(
            scenario: .difficultConversation,
            targetTone: .calm,
            matchRate: 0.25,
            evaluatedCount: 4
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil,
            input: input(),
            plan: nil,
            imToneSignal: signal,
            coachMemory: caseMemory(status: .formingEvidence, followedRepCount: 1)
        )

        #expect(blueprint.source == .caseIntervention)
        #expect(blueprint.recommendedMode == .ahCounter)
        #expect(blueprint.focus == "cleaner opening")
        #expect(blueprint.target == "One clean opening")
        #expect(blueprint.whyNow.contains("1 of 2"))
    }

    @Test func caseInterventionFallsBackToCriterionWhenTargetMissing() {
        let criterion = CoachSuccessCriterion(
            metric: .fillersPerRep,
            comparator: .atMost,
            threshold: 1,
            evaluationWindow: 2,
            summary: "1 or fewer fillers per rep across 2 reps"
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil,
            input: input(),
            plan: nil,
            coachMemory: caseMemory(
                status: .awaitingAttempt,
                followedRepCount: 0,
                target: nil,
                criterion: criterion
            )
        )

        #expect(blueprint.source == .caseIntervention)
        #expect(blueprint.target == "1 or fewer fillers per rep across 2 reps")
        #expect(blueprint.whyNow == "Start the first rep for this focus.")
    }

    @Test func caseInterventionStopsWhenCoachNeedsAdaptation() {
        let signal = IMToneDrillSignal(
            scenario: .networking,
            targetTone: .confident,
            matchRate: 0.2,
            evaluatedCount: 5
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil,
            input: input(),
            plan: nil,
            imToneSignal: signal,
            coachMemory: caseMemory(status: .adaptBeforeRepeating, followedRepCount: 2)
        )

        #expect(blueprint.source == .imToneDrill)
        #expect(blueprint.recommendedMode == .imConversation)
        #expect(blueprint.recommendedScenario == .networking)
    }

    @Test func goalBasedIMRecommendationCarriesScenarioAndTone() {
        // The other half of the destination contract: when the *goal*
        // bias (not a tone drill) lands on IM, the blueprint must carry a
        // concrete scenario + tone so the picker quick-start and Home both
        // prefill the same setup. A calmer-delivery / social / warm-voice
        // profile prioritises IM → social catch-up + warm.
        let profile = CoachingProfile(
            speakingContext: .social,
            primaryGoal: .calmerDelivery,
            confidenceLevel: .rebuilding,
            biggestChallenge: .rushing,
            desiredOutcome: .composed,
            speakingStyleGoal: .warm,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: "",
            chosenStyleGoal: .warm
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: profile,
            input: input(),
            plan: nil
        )
        #expect(blueprint.recommendedMode == .imConversation)
        #expect(blueprint.recommendedScenario == .socialCatchUp)
        #expect(blueprint.recommendedTone == .warm)
    }

    @Test func endToEndSignalFeedsImDrillBlueprint() {
        // Full path: low-hit-rate history → signal → IM drill blueprint
        // with the scenario + tone prefilled for a one-tap re-rep.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",  daysOffset: -1),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -4)
        ]
        let signal = IMHistorySummary.toneDrillSignal(from: sessions)
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil,
            input: input(),
            plan: nil,
            imToneSignal: signal
        )
        #expect(blueprint.recommendedMode == .imConversation)
        #expect(blueprint.recommendedScenario == .difficultConversation)
        #expect(blueprint.recommendedTone == .calm)
    }

    // MARK: - Adaptation: the blueprint copy responds to the trajectory

    @Test func blueprintReinforcesWhenDrillRecovering() {
        // A recovering trajectory should reinforce the drill the user is
        // already on and report the climb without claiming the drill caused it.
        let signal = IMToneDrillSignal(
            scenario: .difficultConversation,
            targetTone: .calm,
            matchRate: 0.25,
            evaluatedCount: 5,
            progress: IMToneDrillProgress(
                direction: .recovering,
                earlierRate: 0.0,
                recentRate: 0.5,
                windowSize: 2
            )
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil, input: input(), plan: nil, imToneSignal: signal
        )
        // Prefill is identical across trajectories — only the rationale adapts.
        #expect(blueprint.recommendedMode == .imConversation)
        #expect(blueprint.recommendedScenario == .difficultConversation)
        #expect(blueprint.recommendedTone == .calm)
        // Reinforcing rationale names the climb (recent vs earlier window).
        #expect(blueprint.whyNow.contains("50%"))
        #expect(blueprint.whyNow.contains("0%"))
        #expect(blueprint.whyMode.contains("test whether it holds"))
        // Not the neutral "landed only" line.
        #expect(!blueprint.whyNow.contains("landed only"))
    }

    @Test func blueprintVariesWhenDrillSlipping() {
        // A slipping trajectory should change the approach rather than
        // repeat the identical ask, and report the drop honestly.
        let signal = IMToneDrillSignal(
            scenario: .networking,
            targetTone: .confident,
            matchRate: 0.2,
            evaluatedCount: 5,
            progress: IMToneDrillProgress(
                direction: .slipping,
                earlierRate: 1.0,
                recentRate: 0.0,
                windowSize: 2
            )
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil, input: input(), plan: nil, imToneSignal: signal
        )
        #expect(blueprint.recommendedScenario == .networking)
        #expect(blueprint.recommendedTone == .confident)
        #expect(blueprint.whyNow.contains("0%"))
        #expect(blueprint.whyNow.contains("100%"))
        #expect(blueprint.whyMode.contains("change"))
        #expect(!blueprint.whyNow.contains("landed only"))
    }

    @Test func blueprintStaysNeutralWhenProgressStalledOrAbsent() {
        // No trajectory read (or a stalled one) → the neutral prescription
        // reporting the overall hit rate, unchanged from before Adaptation.
        let stalled = IMToneDrillSignal(
            scenario: .difficultConversation,
            targetTone: .calm,
            matchRate: 0.25,
            evaluatedCount: 4,
            progress: IMToneDrillProgress(
                direction: .stalled,
                earlierRate: 0.0,
                recentRate: 0.0,
                windowSize: 2
            )
        )
        let blueprint = RecommendationBiasEngine.blueprint(
            profile: nil, input: input(), plan: nil, imToneSignal: stalled
        )
        #expect(blueprint.whyNow.contains("landed only"))
        #expect(blueprint.whyNow.contains("25%"))
        #expect(!blueprint.whyMode.contains("working"))

        // The pre-Adaptation nil case still reads neutral too.
        let noProgress = IMToneDrillSignal(
            scenario: .difficultConversation,
            targetTone: .calm,
            matchRate: 0.25,
            evaluatedCount: 4
        )
        let neutral = RecommendationBiasEngine.blueprint(
            profile: nil, input: input(), plan: nil, imToneSignal: noProgress
        )
        #expect(neutral.whyNow.contains("landed only"))
    }

    @Test func signalCarriesProgressWhenEnoughReps() {
        // End-to-end: a low-but-recovering history → the signal the engine
        // receives carries a recovering Adaptation read for the same
        // scenario it prescribes.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let signal = IMHistorySummary.toneDrillSignal(from: sessions)
        #expect(signal?.scenario == .difficultConversation)
        #expect(signal?.matchRate == 0.25)
        #expect(signal?.progress?.direction == .recovering)
    }
}

// MARK: - IM tone-drill Adaptation read (is the drill working?)
//
// `IMHistorySummary.toneDrillProgress` compares the tone-match hit rate of
// a scenario's earliest vs latest evaluated-rep window. It is the
// Adaptation half of the tone-drill loop — the read the engine uses to
// reinforce a recovering drill or change a slipping one. These tests lock
// the honest-data contracts (nil below 4 reps, non-overlapping windows,
// oldest→newest ordering, missing-`actualTone` exclusion) and the
// recovering / stalled / slipping classification at the threshold.

struct IMToneDrillProgressTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func progressNilOnEmptyHistory() {
        #expect(IMHistorySummary.toneDrillProgress(from: [], scenario: .networking) == nil)
    }

    @Test func progressNilBelowFourEvaluatedReps() {
        // Three evaluated reps can't be split into two disjoint windows
        // honestly — the helper declines rather than fabricating a read.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -3)
        ]
        #expect(IMHistorySummary.toneDrillProgress(from: sessions, scenario: .networking) == nil)
    }

    @Test func progressIgnoresRepsWithoutActualTone() {
        // nil/blank actualTone is missing data, not a miss — it must not
        // pad the count to four and produce a read off three real reps.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: nil,         daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "   ",       daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -5)
        ]
        // Only 3 evaluated reps remain → below the bar.
        #expect(IMHistorySummary.toneDrillProgress(from: sessions, scenario: .networking) == nil)
    }

    @Test func progressReadsRecoveringWhenRecentBeatsEarlier() {
        // Oldest reps miss, newest reps land → the rate is climbing.
        // Ordered oldest→newest the outcomes are [miss, miss, match, match];
        // window = 2 → earlier 0/2 == 0.0, recent 2/2 == 1.0.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let progress = IMHistorySummary.toneDrillProgress(from: sessions, scenario: .difficultConversation)
        #expect(progress?.direction == .recovering)
        #expect(progress?.earlierRate == 0.0)
        #expect(progress?.recentRate == 1.0)
        #expect(progress?.windowSize == 2)
    }

    @Test func progressReadsSlippingWhenRecentWorseThanEarlier() {
        // Oldest reps land, newest reps miss → the rate is falling.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -1)
        ]
        let progress = IMHistorySummary.toneDrillProgress(from: sessions, scenario: .networking)
        #expect(progress?.direction == .slipping)
        #expect(progress?.earlierRate == 1.0)
        #expect(progress?.recentRate == 0.0)
    }

    @Test func progressReadsStalledWhenFlat() {
        // Same rate in both windows (one match per window) → no trajectory.
        // Ordered oldest→newest: [match, miss, match, miss]; window = 2 →
        // earlier 1/2 == 0.5, recent 1/2 == 0.5, delta 0 < threshold.
        let sessions = [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -4),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",        daysOffset: -3),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -2),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "scattered",    daysOffset: -1)
        ]
        let progress = IMHistorySummary.toneDrillProgress(from: sessions, scenario: .workUpdate)
        #expect(progress?.direction == .stalled)
        #expect(progress?.earlierRate == 0.5)
        #expect(progress?.recentRate == 0.5)
    }

    @Test func progressWindowsNeverOverlapAtSixReps() {
        // Six evaluated reps → window = min(3, 6/2) == 3; the earliest 3
        // and latest 3 partition the set with no rep counted twice.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        let progress = IMHistorySummary.toneDrillProgress(from: sessions, scenario: .networking)
        #expect(progress?.windowSize == 3)
        #expect(progress?.direction == .recovering)
        #expect(progress?.earlierRate == 0.0)   // 0 of first 3
        #expect(progress?.recentRate == 1.0)    // 3 of last 3
    }

    @Test func progressFiltersToScenarioAndMode() {
        // Cross-scenario and non-IM reps must not contaminate the read for
        // the requested scenario. Networking has 4 clean recovering reps;
        // the difficultConversation reps are noise for this query.
        var sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        sessions.append(imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm", daysOffset: -5))
        sessions.append(imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm", daysOffset: -6))
        let progress = IMHistorySummary.toneDrillProgress(from: sessions, scenario: .networking)
        #expect(progress?.direction == .recovering)
        #expect(progress?.recentRate == 1.0)
    }

    @Test func progressThresholdConstantIsRobustToWindowGranularity() {
        // The threshold must sit below the smallest possible non-zero swing
        // (one rep flipping in a 2-rep window == 0.5) and above zero, so a
        // flat history reads stalled and any real flip reads directional.
        #expect(IMHistorySummary.toneDrillProgressThreshold > 0)
        #expect(IMHistorySummary.toneDrillProgressThreshold < 0.5)
    }
}

// MARK: - Tone-drill trajectory threaded into the chat coach context
//
// Round 12 of the M24 deferred slate: the Adaptation read the
// recommendation engine already adapts to (rounds 9–11) is now carried
// into `CoachContextBuilder.userContext` so the persistent Ask Noum coach
// can speak to whether the prescribed tone drill is working — not only the
// next-practice card. These tests lock the terse, citeable line shape, the
// per-direction guidance, the nil-when-no-trajectory contract, and the
// end-to-end surfacing inside `userContext`.

struct ToneDrillTrajectoryContextTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func trajectoryLinesNilWhenSignalCarriesNoProgress() {
        // A pre-Adaptation signal (no progress) must not fabricate a
        // trajectory the coach can't see.
        let signal = IMToneDrillSignal(
            scenario: .difficultConversation,
            targetTone: .calm,
            matchRate: 0.25,
            evaluatedCount: 3
        )
        #expect(CoachContextBuilder.toneDrillTrajectoryLines(for: signal) == nil)
    }

    @Test func trajectoryLinesReinforceWhenRecovering() {
        let signal = IMToneDrillSignal(
            scenario: .difficultConversation,
            targetTone: .calm,
            matchRate: 0.25,
            evaluatedCount: 5,
            progress: IMToneDrillProgress(
                direction: .recovering, earlierRate: 0.0, recentRate: 0.5, windowSize: 2
            )
        )
        let lines = CoachContextBuilder.toneDrillTrajectoryLines(for: signal)
        let joined = (lines ?? []).joined(separator: "\n")
        #expect(joined.contains("Calm tone in Difficult Conversation"))
        #expect(joined.contains("0% to 50%"))
        #expect(joined.contains("recovering"))
        // Guidance must reinforce, not restate the original miss.
        #expect(joined.lowercased().contains("reinforce"))
    }

    @Test func trajectoryLinesVaryApproachWhenSlipping() {
        let signal = IMToneDrillSignal(
            scenario: .networking,
            targetTone: .confident,
            matchRate: 0.2,
            evaluatedCount: 5,
            progress: IMToneDrillProgress(
                direction: .slipping, earlierRate: 1.0, recentRate: 0.0, windowSize: 2
            )
        )
        let joined = (CoachContextBuilder.toneDrillTrajectoryLines(for: signal) ?? []).joined(separator: "\n")
        #expect(joined.contains("100% to 0%"))
        #expect(joined.contains("slipping"))
        #expect(joined.lowercased().contains("changing how they open"))
    }

    @Test func trajectoryLinesNameThePlateauWhenStalled() {
        let signal = IMToneDrillSignal(
            scenario: .workUpdate,
            targetTone: .professional,
            matchRate: 0.25,
            evaluatedCount: 4,
            progress: IMToneDrillProgress(
                direction: .stalled, earlierRate: 0.5, recentRate: 0.5, windowSize: 2
            )
        )
        let joined = (CoachContextBuilder.toneDrillTrajectoryLines(for: signal) ?? []).joined(separator: "\n")
        #expect(joined.contains("no movement yet"))
        #expect(joined.lowercased().contains("plateau"))
    }

    @Test func userContextSurfacesTrajectoryForPrescribedScenario() {
        // End-to-end: a low-but-recovering history → userContext carries a
        // TONE-DRILL TRAJECTORY section for the prescribed scenario so the
        // chat coach can speak to the response, not only the card.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctx.contains("TONE-DRILL TRAJECTORY"))
        #expect(ctx.contains("Calm tone in Difficult Conversation"))
        #expect(ctx.contains("recovering"))
    }

    @Test func userContextOmitsTrajectoryWhenNoDrillSignal() {
        // No IM history clears the drill bar → no hollow trajectory heading.
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!ctx.contains("TONE-DRILL TRAJECTORY"))
    }
}

// MARK: - Tone-drill "resolved" read (the win, after the drill is won)
//
// M24 deferred slate (round 13): `toneDrillSignal` + `toneDrillProgress`
// self-clear the moment a scenario climbs past the drill bar, so the coach
// stops acknowledging a tone gap at exactly the moment the user closes it.
// `toneDrillResolved` is the complement — it fires only on genuine
// turnaround evidence (earliest window below the bar, latest window holding
// at/above the 60% hold rate, overall at/above the bar so the active drill
// has cleared). These tests lock the turnaround detection, the four
// negative paths (empty, too-thin, never-struggled, still-active-drill,
// bouncy-recent), the freshest-win selection, and the constant boundary.

struct IMToneDrillResolvedTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func resolvedNilOnEmptyHistory() {
        #expect(IMHistorySummary.toneDrillResolved(from: []) == nil)
    }

    @Test func resolvedNilBelowFourEvaluatedReps() {
        // Three reps can't be split into two disjoint windows — no read.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        #expect(IMHistorySummary.toneDrillResolved(from: sessions) == nil)
    }

    @Test func resolvedDetectsTurnaround() {
        // Six reps, window = 3: earliest 3 all miss (0%), latest 3 all land
        // (100%), overall 3/6 == 50% — a clean, held win above the 40% bar.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let resolved = IMHistorySummary.toneDrillResolved(from: sessions)
        #expect(resolved?.scenario == .difficultConversation)
        #expect(resolved?.targetTone == .calm)
        #expect(resolved?.earlierRate == 0.0)
        #expect(resolved?.recentRate == 1.0)
        #expect(resolved?.evaluatedCount == 6)
    }

    @Test func resolvedNilWhenNeverStruggled() {
        // Steady competence is not a "win to announce" — the earliest
        // window is already above the drill bar, so there's no gap closed.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        #expect(IMHistorySummary.toneDrillResolved(from: sessions) == nil)
    }

    @Test func resolvedNilWhenStillActiveDrill() {
        // Eight reps, window = 3: earliest 3 miss, latest 3 land, but the
        // overall rate (3/8 == 37.5%) is still below the 40% drill bar — so
        // `toneDrillSignal` is still firing for this scenario and the coach
        // must not double-announce it as solved.
        let sessions = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -8),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -7),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        #expect(IMHistorySummary.toneDrillResolved(from: sessions) == nil)
    }

    @Test func resolvedNilWhenRecentWindowDoesNotHold() {
        // Eight reps, window = 3: a bouncy recovery where the latest window
        // only lands 1 of 3 (33% < 60% hold bar) even though the overall
        // rate clears the drill bar. A win must be *held*, not lucky.
        // Oldest→newest outcomes: miss, match, miss, match, match, miss,
        // match, miss → earliest 3 == 1/3 (33%), latest 3 == 1/3 (33%),
        // overall 4/8 == 50%.
        let sessions = [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",        daysOffset: -8),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -7),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "scattered",    daysOffset: -6),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -5),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -4),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",        daysOffset: -3),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -2),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "scattered",    daysOffset: -1)
        ]
        #expect(IMHistorySummary.toneDrillResolved(from: sessions) == nil)
    }

    @Test func resolvedPicksFreshestWinAcrossScenarios() {
        // Two scenarios both resolved; the one whose most-recent evaluated
        // rep is freshest wins — acknowledge what the user just earned, not
        // the older recovery. Networking's last rep is more recent.
        var sessions = [
            // Difficult Conversation resolved, but older (last rep -10d).
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -15),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -14),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -13),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",  daysOffset: -12),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",  daysOffset: -11),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",  daysOffset: -10)
        ]
        sessions += [
            // Networking resolved, fresher (last rep -1d).
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        #expect(IMHistorySummary.toneDrillResolved(from: sessions)?.scenario == .networking)
    }

    @Test func resolvedHoldRateSitsAboveTheDrillBar() {
        // "Solved" must be a meaningfully cleared bar, not a scrape over the
        // drill threshold — otherwise a recovering-but-not-held scenario
        // would read as won.
        #expect(IMHistorySummary.toneDrillResolvedHoldRate > IMHistorySummary.toneDrillMatchRateThreshold)
    }

    // MARK: - Per-scenario read + crossing detection
    //
    // The post-rep coach note headlines a solved drill exactly once — on the
    // rep that crosses the bar — using the per-scenario overload to compare
    // the resolved read with vs. without the just-finished rep. These lock
    // that primitive and the crossing behavior it enables.

    @Test func resolvedPerScenarioMatchesCrossScenarioForSingleWin() {
        // With one resolved scenario, the scoped overload returns the same
        // win the cross-scenario scan surfaces.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let scoped = IMHistorySummary.toneDrillResolved(from: sessions, scenario: .difficultConversation)
        let cross = IMHistorySummary.toneDrillResolved(from: sessions)
        #expect(scoped == cross)
        #expect(scoped?.scenario == .difficultConversation)
    }

    @Test func resolvedPerScenarioNilForUnrelatedScenario() {
        // The scoped overload reads only the scenario asked for — a resolved
        // Difficult Conversation never surfaces under a Networking query.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        #expect(IMHistorySummary.toneDrillResolved(from: sessions, scenario: .networking) == nil)
    }

    @Test func resolvedFiresOnCrossingRepNotBefore() {
        // The crossing rep is the one that flips a scenario from not-resolved
        // to resolved. Five reps (oldest→newest: miss, miss, match, match,
        // miss) don't clear the hold bar — the latest 2-rep window lands only
        // 50% (< 60%). The sixth rep (a match) makes it six reps, window 3:
        // earliest 33% (< 40% bar), latest 67% (≥ 60% hold), overall 50% — a
        // held win. So the read must be nil before the rep and non-nil after:
        // exactly the finalizer's with-vs-without crossing comparison.
        let beforeCrossing = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -1)
        ]
        let crossingRep = imSession(
            scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: 0
        )
        #expect(IMHistorySummary.toneDrillResolved(from: beforeCrossing, scenario: .networking) == nil)
        #expect(IMHistorySummary.toneDrillResolved(from: beforeCrossing + [crossingRep], scenario: .networking) != nil)
    }

    @Test func resolvedDoesNotRepeatAfterCrossing() {
        // Once crossed, a further match keeps the scenario resolved — but the
        // rep before this one was ALSO resolved, so the finalizer's crossing
        // check (resolved now AND not a rep ago) yields no new headline. Both
        // the six-rep state and the seven-rep state read resolved, so the
        // win never repeats on the rep after the crossing.
        let throughCrossing = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        let nextRep = imSession(
            scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: 0
        )
        #expect(IMHistorySummary.toneDrillResolved(from: throughCrossing, scenario: .networking) != nil)
        #expect(IMHistorySummary.toneDrillResolved(from: throughCrossing + [nextRep], scenario: .networking) != nil)
    }
}

// MARK: - Tone-drill crossing helper (the single source of truth)
//
// M24 deferred slate (round 21): the with-vs-without-this-rep crossing
// predicate used to live in two places — `PracticeSessionFinalizer.
// recordPostRepCoachNote` (the prose post-rep coach note) and
// `SummaryView.heroToneDrillResolvedRibbon` (the hero score card SOLVED
// ribbon). Both surfaces must light up on the *same* rep and never
// double-celebrate; the round-21 refactor lifts the predicate into
// `IMHistorySummary.toneDrillCrossing(in:scenario:currentRepId:)` so both
// call sites route through one tested primitive. These tests lock the
// helper's positive path, the "already-solved-before stays quiet"
// negative path, the relapse-then-reclear positive path, the stale-id
// defensive negative, and order-independence (store-prepended list vs.
// finalizer-appended list yield the same crossing read).

struct IMToneDrillCrossingTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func crossingFiresOnTheRepThatClosesTheGap() {
        // Mirrors `resolvedDetectsCrossingRep` (the round-13 raw-primitive
        // test) but routes through the round-21 helper. Five reps below
        // the bar + a sixth rep that lands the tone → the sixth rep is
        // the crossing rep. The helper must return the resolved read
        // when called with that rep's id.
        let priorReps = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -1)
        ]
        let crossingRep = imSession(
            scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: 0
        )
        let allSessions = priorReps + [crossingRep]
        let crossed = IMHistorySummary.toneDrillCrossing(
            in: allSessions,
            scenario: .networking,
            currentRepId: crossingRep.id
        )
        #expect(crossed?.scenario == .networking)
        #expect(crossed?.targetTone == .confident)
    }

    @Test func crossingStaysQuietWhenAlreadyResolvedBefore() {
        // The rep after a crossing rep also reads as resolved — but the
        // helper must return nil, because the win was already named one
        // rep ago. This is the "never repeat" contract: the SOLVED
        // headline (note) and the SOLVED ribbon (hero card) must not
        // light up on rep #7 just because rep #6 already closed the gap.
        let throughCrossing = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -1)
        ]
        let nextRep = imSession(
            scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: 0
        )
        let allSessions = throughCrossing + [nextRep]
        // Sanity: both the with-this-rep and without-this-rep reads
        // are non-nil — so the helper's "before == nil" gate is what
        // keeps the win from repeating.
        #expect(IMHistorySummary.toneDrillResolved(from: allSessions, scenario: .networking) != nil)
        #expect(IMHistorySummary.toneDrillResolved(from: throughCrossing, scenario: .networking) != nil)
        #expect(IMHistorySummary.toneDrillCrossing(
            in: allSessions,
            scenario: .networking,
            currentRepId: nextRep.id
        ) == nil)
    }

    @Test func crossingFiresAgainOnRelapseThenReclear() {
        // The honesty contract: a scenario that crossed, fell back below
        // the bar across a fresh window, then climbed again, reads as a
        // *new* crossing — the user did genuinely re-close the gap. The
        // round-13 primitive locks this for the raw read; the helper
        // must surface it the same way through the with-vs-without
        // comparison.
        //
        // Construction: 6 reps that crossed (oldest), then a post-crossing
        // stretch — two relapse misses (tense, rushed) and the first calm
        // of the climb back — then the reclear rep (calm). `toneDrillResolved`
        // reads the latest window as the 3 newest evaluated reps. Stripped
        // of the reclear rep that window is [tense, rushed, calm] = 1/3
        // (33% < 60%) → resolved-before is nil; with the reclear rep in it
        // slides to [rushed, calm, calm] = 2/3 (67% >= 60%) → resolved-now
        // is non-nil, so the helper surfaces the fresh crossing. A lone
        // calm rep can't reclear a window still holding two relapse misses;
        // the climb has to land twice — exactly what the 60% hold bar over
        // a 3-rep window enforces ("the climb stuck, isn't one lucky rep").
        let earlyCrossing = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -12),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -11),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -10),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -9),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -8),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -7)
        ]
        let relapseWindow = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -2),
            // The climb's first calm — one short of reclearing the 3-rep
            // hold window on its own (relapse misses still outweigh it).
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let reclearRep = imSession(
            scenario: .difficultConversation, targetTone: .calm, actualTone: "calm", daysOffset: 0
        )
        let priorOnly = earlyCrossing + relapseWindow
        let withReclear = priorOnly + [reclearRep]
        // Sanity: the relapse pushed the latest window back below the
        // hold bar, so resolved-before is nil; resolved-now (with the
        // reclear rep) is non-nil → exactly the crossing the helper
        // surfaces.
        #expect(IMHistorySummary.toneDrillResolved(from: priorOnly, scenario: .difficultConversation) == nil)
        #expect(IMHistorySummary.toneDrillResolved(from: withReclear, scenario: .difficultConversation) != nil)
        let crossed = IMHistorySummary.toneDrillCrossing(
            in: withReclear,
            scenario: .difficultConversation,
            currentRepId: reclearRep.id
        )
        #expect(crossed?.scenario == .difficultConversation)
        #expect(crossed?.targetTone == .calm)
    }

    @Test func crossingNilWhenScenarioNeverCrossed() {
        // A scenario still firmly below the drill bar — the helper must
        // not invent a victory just because the call site asked. Locks
        // the primary negative for the recommendation-engine still owns
        // this scenario; the SOLVED surfaces stay quiet.
        let belowBar = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",  daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",   daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",  daysOffset: -1)
        ]
        let latest = imSession(
            scenario: .networking, targetTone: .confident, actualTone: "rushed", daysOffset: 0
        )
        let allSessions = belowBar + [latest]
        #expect(IMHistorySummary.toneDrillCrossing(
            in: allSessions,
            scenario: .networking,
            currentRepId: latest.id
        ) == nil)
    }

    @Test func crossingNilOnStaleRepId() {
        // Defensive contract: if `currentRepId` doesn't match any session
        // in the list, the helper returns nil — it never invents a
        // victory from a stale id. Without this gate, a refactor that
        // accidentally passed e.g. the *prior* rep's id while sessions
        // already excluded it could silently surface a SOLVED moment on
        // the wrong rep.
        let throughCrossing = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -5),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -1),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: 0)
        ]
        // Sanity: the cross-history read IS resolved — so the helper's
        // stale-id gate is what keeps it from surfacing.
        #expect(IMHistorySummary.toneDrillResolved(from: throughCrossing, scenario: .networking) != nil)
        #expect(IMHistorySummary.toneDrillCrossing(
            in: throughCrossing,
            scenario: .networking,
            currentRepId: UUID()  // a freshly generated id that can't match any session
        ) == nil)
    }

    @Test func crossingIsOrderIndependentAcrossCallSites() {
        // The two call sites pass differently-ordered lists: the
        // finalizer hands the helper `allSessions` (insertion order),
        // the SummaryView hands it `sessionStore.sessions` (the store
        // prepends, so the just-finished rep is at index 0). The helper
        // must return the same crossing read for both orderings — the
        // with-vs-without comparison is by id, not by position.
        let priorReps = [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",        daysOffset: -5),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "scattered",    daysOffset: -4),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -3),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -2),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",        daysOffset: -1)
        ]
        let crossingRep = imSession(
            scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: 0
        )
        // Finalizer-style ordering: latest rep appended.
        let finalizerOrdering = priorReps + [crossingRep]
        // SummaryView-style ordering: latest rep prepended.
        let storeOrdering = [crossingRep] + priorReps
        let finalizerCrossing = IMHistorySummary.toneDrillCrossing(
            in: finalizerOrdering,
            scenario: .workUpdate,
            currentRepId: crossingRep.id
        )
        let storeCrossing = IMHistorySummary.toneDrillCrossing(
            in: storeOrdering,
            scenario: .workUpdate,
            currentRepId: crossingRep.id
        )
        #expect(finalizerCrossing?.scenario == .workUpdate)
        #expect(finalizerCrossing?.targetTone == .professional)
        #expect(storeCrossing?.scenario == .workUpdate)
        #expect(storeCrossing?.targetTone == .professional)
        // The exact same primitive output across both orderings.
        #expect(finalizerCrossing == storeCrossing)
    }
}

// MARK: - Tone-drill resolved read threaded into the chat coach context
//
// The win belongs on the conversational surface: the recommendation card
// rightly moves on to the next drill once a scenario clears the bar, but a
// user who opens Ask Noum should hear the coach acknowledge what they fixed.
// These tests lock the citeable line shape, the end-to-end surfacing inside
// `userContext`, the omission when nothing is resolved, and the coherence
// case where an active drill in one scenario and a solved win in another
// both surface at once.

struct ToneDrillResolvedContextTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func resolvedLinesCiteClimbAndScenario() {
        let resolved = IMToneDrillResolved(
            scenario: .difficultConversation,
            targetTone: .calm,
            earlierRate: 0.0,
            recentRate: 1.0,
            evaluatedCount: 6,
            lastEvaluatedDate: baseDate
        )
        let joined = CoachContextBuilder.toneDrillResolvedLines(for: resolved).joined(separator: "\n")
        #expect(joined.contains("Calm tone in Difficult Conversation"))
        #expect(joined.contains("0% to 100%"))
        #expect(joined.lowercased().contains("holding above the drill bar"))
        // Guidance must move the user forward, not re-prescribe the drill.
        #expect(joined.lowercased().contains("next target"))
    }

    @Test func userContextSurfacesSolvedSection() {
        // End-to-end: a once-failing, now-holding scenario → userContext
        // carries a TONE-DRILL SOLVED section so the chat coach names the win.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctx.contains("TONE-DRILL SOLVED"))
        #expect(ctx.contains("Calm tone in Difficult Conversation"))
        #expect(ctx.contains("0% to 100%"))
    }

    @Test func userContextOmitsSolvedWhenNothingResolved() {
        // No resolved scenario → no hollow "solved" heading.
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!ctx.contains("TONE-DRILL SOLVED"))
    }

    @Test func solvedAndTrajectoryCoexistForDifferentScenarios() {
        // An active drill in one scenario (Work Update, 0% over 4 reps) and a
        // solved win in another (Networking, 0% → 100% over 6 reps) must both
        // surface — the coach drills the open gap and names the closed one.
        var sessions = [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",     daysOffset: -4),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "scattered", daysOffset: -3),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",     daysOffset: -2),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "rushed",    daysOffset: -1)
        ]
        sessions += [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -10),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -9),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -8),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -7),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -5)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctx.contains("TONE-DRILL TRAJECTORY"))
        #expect(ctx.contains("Professional tone in Work Update"))
        #expect(ctx.contains("TONE-DRILL SOLVED"))
        #expect(ctx.contains("Confident tone in Networking"))
    }
}

// MARK: - Tone-drill SOLVED freshness window (round 41)
//
// `IMHistorySummary.toneDrillResolved(from:)` returns the resolved read
// forever once a scenario crosses the drill bar — correct for the
// recommendation engine, but the chat-coach context block surfaced it on
// every reply for months after the crossing. Round 41 adds a freshness
// gate to the TONE-DRILL SOLVED section in `CoachContextBuilder.userContext`,
// anchored against the user's most-recent practice rep, so the line drops
// past `toneDrillSolvedRecencyDays` (14 days) — mirroring the round-38
// `repeatedPushbackRecencyDays` window on the case-state matrix.
//
// These tests pin the pure predicate (every branch + boundary), the
// userContext integration (fires when fresh, drops when stale, drops when
// no sessions), and the cross-surface contract that a fresh SOLVED can
// still coexist with an active TRAJECTORY in another scenario after the
// freshness gate (the gate is per-scenario via the SOLVED-resolved primitive,
// not a global "no more SOLVED ever" once a single window passes).
struct ToneDrillSolvedFreshnessTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    private func resolvedFixture(daysSinceBase: Double) -> IMToneDrillResolved {
        IMToneDrillResolved(
            scenario: .difficultConversation,
            targetTone: .calm,
            earlierRate: 0.0,
            recentRate: 1.0,
            evaluatedCount: 6,
            lastEvaluatedDate: baseDate.addingTimeInterval(daysSinceBase * 86_400)
        )
    }

    // MARK: - Pure predicate — happy path

    @Test func predicateFiresWhenNowEqualsLastEvaluatedDate() {
        // Zero elapsed time → fresh by definition.
        let resolved = resolvedFixture(daysSinceBase: 0)
        #expect(CoachContextBuilder.toneDrillSolvedIsFresh(resolved, now: baseDate))
    }

    @Test func predicateFiresWithinTheRecencyWindow() {
        // 7 days elapsed → comfortably inside the 14-day window.
        let resolved = resolvedFixture(daysSinceBase: -7)
        #expect(CoachContextBuilder.toneDrillSolvedIsFresh(resolved, now: baseDate))
    }

    // MARK: - Pure predicate — boundary

    @Test func predicateFiresAtExactRecencyBoundary() {
        // Inclusive 14-day boundary mirrors rounds 38/39/40's identical
        // recency-pin shape. A win at exactly 14 days old still surfaces;
        // a win past 14 days drops. The exact boundary is the contract.
        let resolved = resolvedFixture(daysSinceBase: -Double(CoachContextBuilder.toneDrillSolvedRecencyDays))
        #expect(CoachContextBuilder.toneDrillSolvedIsFresh(resolved, now: baseDate))
    }

    @Test func predicateDropsJustBeyondRecencyBoundary() {
        // 14 days + 1 second past → drops. Mirrors the round-38/40
        // strict-greater-than-window-edge contract on the rejection ack.
        let resolved = resolvedFixture(daysSinceBase: -Double(CoachContextBuilder.toneDrillSolvedRecencyDays))
        let justBeyond = baseDate.addingTimeInterval(1)
        #expect(!CoachContextBuilder.toneDrillSolvedIsFresh(resolved, now: justBeyond))
    }

    // MARK: - Pure predicate — outside the window

    @Test func predicateDropsOutsideRecencyWindow() {
        // 30 days elapsed → well past the 14-day window.
        let resolved = resolvedFixture(daysSinceBase: -30)
        #expect(!CoachContextBuilder.toneDrillSolvedIsFresh(resolved, now: baseDate))
    }

    // MARK: - Pure predicate — defensive (negative elapsed)

    @Test func predicateDropsWhenNowPredatesLastEvaluatedDate() {
        // A `now` that pre-dates `lastEvaluatedDate` is a bad anchor; the
        // predicate refuses to fire rather than returning true on a
        // mathematically-fresh-but-impossible state. Defensive pin so a
        // future caller that passes a stale `now` doesn't silently
        // re-surface a dropped win.
        let resolved = resolvedFixture(daysSinceBase: 0)
        let earlier = baseDate.addingTimeInterval(-86_400)  // 1 day before lastEvaluatedDate
        #expect(!CoachContextBuilder.toneDrillSolvedIsFresh(resolved, now: earlier))
    }

    // MARK: - userContext integration — fires when fresh

    @Test func userContextSurfacesSolvedWhenLastEvaluatedRepIsFresh() {
        // Most-recent rep at daysOffset -1 (and the SOLVED scenario's
        // lastEvaluatedDate is also -1, since it IS the most-recent rep)
        // → 0 days elapsed → fresh → section fires.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctx.contains("TONE-DRILL SOLVED"))
        #expect(ctx.contains("Calm tone in Difficult Conversation"))
    }

    // MARK: - userContext integration — drops when stale

    @Test func userContextDropsSolvedWhenLastEvaluatedRepIsStale() {
        // The user crossed the bar over 30 days ago and has practiced a
        // DIFFERENT scenario since, but has NOT touched the held scenario
        // for over a month. The chat coach should move on — the SOLVED
        // line drops while the held scenario stays held in the engine.
        // Anchor: most-recent rep is the workUpdate at daysOffset -1, but
        // the SOLVED scenario's lastEvaluatedDate is daysOffset -30 (the
        // win is over a month old).
        var sessions: [PracticeSession] = [
            // Held SOLVED scenario — last evaluated 30+ days before the
            // anchor, with the same "0% to 100%" climb the SOLVED line
            // would otherwise narrate.
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -35),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -34),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -33),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -32),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -31),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -30)
        ]
        // Recent unrelated reps in a different scenario — the user IS
        // practicing, just not in the SOLVED scenario.
        sessions += [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -2),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -1)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!ctx.contains("TONE-DRILL SOLVED"))
    }

    // MARK: - userContext integration — cross-surface contract

    @Test func userContextLayersFreshSolvedOverActiveTrajectoryInOtherScenario() {
        // A drill in flight (Work Update, sub-40% over 4 reps) and a
        // recently-solved win (Networking, 0% → 100%, last evaluated 4
        // days before the most-recent rep — well inside the freshness
        // window) must STILL both surface. The freshness gate is
        // per-scenario via the resolved primitive — it never drops a
        // fresh SOLVED just because another scenario carries a
        // trajectory.
        var sessions = [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",     daysOffset: -4),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "scattered", daysOffset: -3),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "vague",     daysOffset: -2),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "rushed",    daysOffset: -1)
        ]
        sessions += [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -10),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -9),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -8),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -7),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -5)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctx.contains("TONE-DRILL TRAJECTORY"))
        #expect(ctx.contains("Professional tone in Work Update"))
        #expect(ctx.contains("TONE-DRILL SOLVED"))
        #expect(ctx.contains("Confident tone in Networking"))
    }

    @Test func userContextDropsSolvedAtExactRecencyBoundaryWhenAnchorMovesPast() {
        // Boundary contract end-to-end: the SOLVED scenario's last
        // evaluated rep is at daysOffset -14, the anchor (most-recent
        // rep) is at daysOffset 0, delta is exactly 14 days, so the
        // freshness predicate fires inclusive of the boundary AND the
        // section surfaces. Moving the anchor 1 second past the boundary
        // drops the section. Pinning both halves of the boundary
        // structurally so a future tune of the constant doesn't silently
        // drift the boundary by a day on one half.
        let solvedSessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -19),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -18),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -17),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -16),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -15),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -14)
        ]
        // Anchor exactly on the 14-day boundary — inclusive freshness.
        let onBoundary = solvedSessions + [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: 0)
        ]
        let ctxOnBoundary = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: onBoundary,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctxOnBoundary.contains("TONE-DRILL SOLVED"))

        // Anchor 1 day past the boundary — drops.
        let beyondBoundary = solvedSessions + [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: 1)
        ]
        let ctxBeyond = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: beyondBoundary,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!ctxBeyond.contains("TONE-DRILL SOLVED"))
    }

    // MARK: - Predicate-line constants

    @Test func recencyWindowConstantMatchesRound38PushbackWindow() {
        // Cross-surface symmetry pin from the round-41 design: the SOLVED
        // freshness window and the round-38 pushback dampening window
        // share the same number (14 days). A future round that tunes one
        // should be made to consider whether to tune the other too —
        // this test forces the consideration by failing when they
        // diverge.
        #expect(
            CoachContextBuilder.toneDrillSolvedRecencyDays
            == CoachContextBuilder.repeatedPushbackRecencyDays
        )
    }
}

// MARK: - Tone-drill TRAJECTORY freshness window for the chat-coach context
//
// Round 42 mirrors the round-41 SOLVED freshness gate onto the still-in-flight
// TRAJECTORY surface. `IMHistorySummary.toneDrillSignal(from:)` has no recency
// bound on the latest evaluated rep, so a scenario the user practiced 60+
// days ago, never returned to, and is still below the bar would surface a
// TRAJECTORY line on every chat reply forever — the same "beating a dead
// horse" register round 41 closed on the SOLVED side. Round 42 anchors the
// section against the user's most-recent rep across all history and the
// prescribed scenario's latest evaluated rep, with the SAME constant
// (`toneDrillSolvedRecencyDays`) and the SAME inclusive 14-day boundary as
// round 41. The recommendation engine still prescribes the drill (the gap
// is real); only the chat-coach context surface gates.
//
// These tests pin the pure predicate (every branch + boundary + defensive
// negative-elapsed + no-evaluated-rep guard), the latest-evaluated-rep
// primitive on `IMHistorySummary`, the userContext integration (fires when
// fresh, drops when stale, drops at the boundary +1s), the SOLVED + TRAJECTORY
// layering contract (a stale TRAJECTORY in scenario A drops while a fresh
// SOLVED in scenario B still surfaces, and vice versa), and the cross-surface
// constant identity (round 41 + 42 share the same number by construction).
struct ToneDrillTrajectoryFreshnessTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    private func signalFixture(
        scenario: IMConversationScenario = .difficultConversation,
        targetTone: IMTargetTone = .calm
    ) -> IMToneDrillSignal {
        IMToneDrillSignal(
            scenario: scenario,
            targetTone: targetTone,
            matchRate: 0.25,
            evaluatedCount: 4,
            progress: IMToneDrillProgress(
                direction: .stalled, earlierRate: 0.25, recentRate: 0.25, windowSize: 2
            )
        )
    }

    /// A fresh 4-rep below-bar slip in the prescribed scenario — the
    /// shape the engine ratifies via `toneDrillSignal`, useful as the
    /// "scenario the trajectory is naming" half of a freshness test.
    private func slippingScenarioSessions(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        offBrandTone: String,
        earliestDayOffset: Double
    ) -> [PracticeSession] {
        // Four reps, all the wrong tone → matchRate 0%, below the 40%
        // drill bar, ≥3 evaluated reps so the signal fires. Days span
        // the four offsets so `toneDrillProgress` produces a non-nil
        // (here: stalled at 0%) trajectory and the section surfaces.
        [
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 1),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 2),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 3)
        ]
    }

    // MARK: - Pure predicate — happy path

    @Test func predicateFiresWhenNowEqualsLatestEvaluatedRep() {
        // Zero elapsed time → fresh by definition. The latest evaluated
        // rep in the prescribed scenario IS the anchor.
        let sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -3
        )
        // sessions.lazy.map(\.date).max() == baseDate (offset 0)
        let signal = signalFixture()
        #expect(CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: baseDate))
    }

    @Test func predicateFiresWithinTheRecencyWindow() {
        // 7 days elapsed → comfortably inside the 14-day window. Anchor at
        // baseDate, prescribed scenario's latest rep at -7.
        let sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -10
        )
        let signal = signalFixture()
        #expect(CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: baseDate))
    }

    // MARK: - Pure predicate — boundary

    @Test func predicateFiresAtExactRecencyBoundary() {
        // The prescribed scenario's latest evaluated rep is exactly 14
        // days before the anchor → inclusive boundary fires. Mirrors the
        // round-38/39/40/41 identical recency-pin contract.
        let earliest = -Double(CoachContextBuilder.toneDrillSolvedRecencyDays) - 3
        let sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: earliest
        )
        let signal = signalFixture()
        #expect(CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: baseDate))
    }

    @Test func predicateDropsJustBeyondRecencyBoundary() {
        // Latest evaluated rep 14 days + 1 second before the anchor →
        // drops. The exact strict-greater-than boundary contract,
        // identical to round 41's `predicateDropsJustBeyondRecencyBoundary`.
        let earliest = -Double(CoachContextBuilder.toneDrillSolvedRecencyDays) - 3
        let sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: earliest
        )
        let signal = signalFixture()
        let justBeyond = baseDate.addingTimeInterval(1)
        #expect(!CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: justBeyond))
    }

    // MARK: - Pure predicate — outside the window

    @Test func predicateDropsOutsideRecencyWindow() {
        // 30 days elapsed → well past the 14-day window.
        let sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -33
        )
        let signal = signalFixture()
        #expect(!CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: baseDate))
    }

    // MARK: - Pure predicate — defensive (negative elapsed)

    @Test func predicateDropsWhenNowPredatesLatestEvaluatedRep() {
        // A `now` that pre-dates the latest evaluated rep is a bad
        // anchor; the predicate refuses to fire rather than returning
        // true on a mathematically-fresh-but-impossible state. Defensive
        // pin mirroring round 41's identically-named predicate test.
        let sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -3
        )
        // Latest rep is at offset 0 (baseDate). Anchor at offset -1.
        let signal = signalFixture()
        let earlier = baseDate.addingTimeInterval(-86_400)
        #expect(!CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: earlier))
    }

    // MARK: - Pure predicate — defensive (no evaluated reps in scenario)

    @Test func predicateDropsWhenScenarioHasNoEvaluatedReps() {
        // The prescribed scenario has no evaluated reps in the session
        // set (the only reps in the set are in a different scenario, OR
        // none of them carry an actualTone). The predicate refuses to
        // fire rather than treating the missing anchor as fresh.
        let sessions = slippingScenarioSessions(
            scenario: .workUpdate, targetTone: .professional, offBrandTone: "vague", earliestDayOffset: -3
        )
        let signal = signalFixture()  // Prescribed scenario: .difficultConversation
        #expect(!CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: baseDate))
    }

    // MARK: - latestEvaluatedRepDate primitive

    @Test func latestEvaluatedRepDateReturnsMostRecentEvaluatedRep() {
        // The primitive must return the max date across evaluated reps
        // in the scenario — actualTone-bearing, non-empty, `.imConversation`
        // mode, scenario match.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -1)
        ]
        let date = IMHistorySummary.latestEvaluatedRepDate(from: sessions, scenario: .difficultConversation)
        #expect(date == baseDate.addingTimeInterval(-86_400))
    }

    @Test func latestEvaluatedRepDateIgnoresOtherScenarios() {
        // Reps in OTHER scenarios must not count toward the prescribed
        // scenario's freshness anchor. A user actively practicing
        // .workUpdate but not .difficultConversation should read as
        // "the prescribed scenario is cold" — not as "the user is
        // active, therefore everything is fresh."
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -30),
            imSession(scenario: .workUpdate,             targetTone: .professional, actualTone: "professional", daysOffset: -1)
        ]
        let date = IMHistorySummary.latestEvaluatedRepDate(from: sessions, scenario: .difficultConversation)
        #expect(date == baseDate.addingTimeInterval(-30 * 86_400))
    }

    @Test func latestEvaluatedRepDateExcludesRepsWithoutActualTone() {
        // A rep with no actualTone (the user backed out, or the rep
        // never landed a tone read) is not an "evaluated rep" — it must
        // not extend the freshness window. Mirrors `toneMatchStats`'s
        // filter.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense", daysOffset: -10),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: nil,     daysOffset: -1),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "   ",   daysOffset: -2)
        ]
        let date = IMHistorySummary.latestEvaluatedRepDate(from: sessions, scenario: .difficultConversation)
        #expect(date == baseDate.addingTimeInterval(-10 * 86_400))
    }

    @Test func latestEvaluatedRepDateReturnsNilWhenNoEvaluatedReps() {
        // The defensive nil that the predicate's guard relies on.
        #expect(IMHistorySummary.latestEvaluatedRepDate(from: [], scenario: .difficultConversation) == nil)
    }

    // MARK: - userContext integration — fires when fresh

    @Test func userContextSurfacesTrajectoryWhenLatestRepIsFresh() {
        // Round-13 happy path, unchanged by round 42: latest evaluated
        // rep in the prescribed scenario IS the user's most-recent rep
        // (0 days elapsed) → fresh → section fires.
        let sessions = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -4),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -3),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -2),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctx.contains("TONE-DRILL TRAJECTORY"))
        #expect(ctx.contains("Calm tone in Difficult Conversation"))
    }

    // MARK: - userContext integration — drops when stale

    @Test func userContextDropsTrajectoryWhenPrescribedScenarioIsStale() {
        // The user has a still-failing drill in scenario A (Difficult
        // Conversation) — last touched 30+ days ago — but has been
        // practicing scenario B (Work Update) actively in the interim.
        // The recommendation engine still prescribes the Difficult
        // Conversation drill (the gap is real), but the chat coach
        // should not re-issue the trajectory commentary on a long-stale
        // read. The TRAJECTORY section drops.
        var sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -33
        )
        sessions += [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -2),
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: -1)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!ctx.contains("TONE-DRILL TRAJECTORY"))
    }

    // MARK: - userContext integration — boundary

    @Test func userContextDropsTrajectoryAtExactRecencyBoundaryWhenAnchorMovesPast() {
        // Boundary contract end-to-end. The prescribed scenario's
        // latest evaluated rep is at daysOffset -14, the anchor (most-
        // recent rep, in a different scenario) is at daysOffset 0 →
        // delta is exactly 14 days → inclusive freshness fires AND
        // the section surfaces. Moving the anchor 1 day past the
        // boundary drops it. Pinning both halves of the boundary so a
        // future tune of the constant doesn't silently drift the
        // boundary by a day on one half.
        let slipping = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -17
        )
        // Anchor exactly on the 14-day boundary.
        let onBoundary = slipping + [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: 0)
        ]
        let ctxOnBoundary = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: onBoundary,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctxOnBoundary.contains("TONE-DRILL TRAJECTORY"))

        // Anchor 1 day past the boundary — drops.
        let beyondBoundary = slipping + [
            imSession(scenario: .workUpdate, targetTone: .professional, actualTone: "professional", daysOffset: 1)
        ]
        let ctxBeyond = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: beyondBoundary,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!ctxBeyond.contains("TONE-DRILL TRAJECTORY"))
    }

    // MARK: - userContext integration — cross-surface contract with SOLVED

    @Test func userContextLayersFreshSolvedOverStaleTrajectory() {
        // A stale TRAJECTORY in scenario A (Difficult Conversation, last
        // touched -30) drops out of the chat coach's context block, but
        // a fresh SOLVED in scenario B (Networking, last evaluated -5,
        // well inside the 14-day window) is preserved. The two freshness
        // gates are PER-SCENARIO via their respective primitives — a
        // dropped TRAJECTORY in one scenario must not block a fresh
        // SOLVED in another.
        var sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -33
        )
        sessions += [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -10),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -9),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -8),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -7),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -6),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -5)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(!ctx.contains("TONE-DRILL TRAJECTORY"))
        #expect(ctx.contains("TONE-DRILL SOLVED"))
        #expect(ctx.contains("Confident tone in Networking"))
    }

    @Test func userContextLayersFreshTrajectoryOverStaleSolved() {
        // The mirror contract: an ACTIVE drill in flight (fresh
        // TRAJECTORY) must still surface even when an old SOLVED in a
        // different scenario has aged past the window. Pins that round
        // 41 (SOLVED freshness) and round 42 (TRAJECTORY freshness) gate
        // independently per scenario, not as a "drop everything once
        // anything ages out" rule.
        var sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: -3
        )
        // Stale solved scenario — latest evaluated rep -35 days from baseDate.
        sessions += [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -40),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "rushed",    daysOffset: -39),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "flat",      daysOffset: -38),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -37),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -36),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -35)
        ]
        let ctx = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: .initial,
            sessions: sessions,
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil
        )
        #expect(ctx.contains("TONE-DRILL TRAJECTORY"))
        #expect(ctx.contains("Calm tone in Difficult Conversation"))
        #expect(!ctx.contains("TONE-DRILL SOLVED"))
    }

    // MARK: - Cross-surface constant identity (round 41 + 42)

    @Test func trajectoryFreshnessWindowUsesSameConstantAsSolved() {
        // Round 42 reuses the round-41 `toneDrillSolvedRecencyDays`
        // constant by design — the chat coach's freshness contract is
        // one number, shared across SOLVED + TRAJECTORY. This test is a
        // structural identity check: the value the TRAJECTORY predicate
        // reads through its body matches the value the SOLVED predicate
        // reads. (If a future round splits the surfaces' windows, this
        // test will need to be replaced with a deliberate divergence
        // contract — for now it forces the design intent.)
        // The boundary days are derived from `toneDrillSolvedRecencyDays`
        // in the body of `toneDrillTrajectoryIsFresh`, so a behavioural
        // proof: a TRAJECTORY at boundary -1 second fires; at boundary
        // +1 second drops; the SAME shifts hold for SOLVED.
        let trajectoryWindowSeconds = TimeInterval(CoachContextBuilder.toneDrillSolvedRecencyDays * 24 * 60 * 60)

        let sessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm, offBrandTone: "tense", earliestDayOffset: 0
        )
        // Latest evaluated rep is at offset +3 days from baseDate.
        let latestRepDate = baseDate.addingTimeInterval(3 * 86_400)
        let signal = signalFixture()

        let justInsideWindow = latestRepDate.addingTimeInterval(trajectoryWindowSeconds - 1)
        let exactlyOnWindow = latestRepDate.addingTimeInterval(trajectoryWindowSeconds)
        let justBeyondWindow = latestRepDate.addingTimeInterval(trajectoryWindowSeconds + 1)
        #expect(CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: justInsideWindow))
        #expect(CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: exactlyOnWindow))
        #expect(!CoachContextBuilder.toneDrillTrajectoryIsFresh(signal: signal, in: sessions, now: justBeyondWindow))
    }
}

// MARK: - Tone-drill trajectory threaded into the post-rep coach note
//
// The same Adaptation read also reaches the post-rep `CoachReadCard` via
// `PostRepCoachNoteService`: when the just-finished rep was an IM
// conversation whose committed tone is recovering or slipping, the
// deterministic note speaks to that response ahead of the per-rep metrics.
// These tests lock the voice-shaped copy, the recovering/slipping gating
// (stalled falls through), and the priority placement.

struct PostRepCoachNoteToneTrajectoryTests {

    private func makeInput(
        voice: SpeakingStyleGoal? = nil,
        mode: PracticeMode = .imConversation,
        progress: IMToneDrillProgress?,
        scenarioTitle: String? = "Difficult Conversation",
        toneTitle: String? = "Calm"
    ) -> PostRepCoachNoteInput {
        PostRepCoachNoteInput(
            sessionID: UUID(),
            mode: mode,
            score: 7,
            fillerCount: 2,
            duration: 60,
            wordCount: 120,
            voice: voice,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            totalSessionCount: 8,
            imToneDrillProgress: progress,
            imToneDrillScenarioTitle: scenarioTitle,
            imToneDrillToneTitle: toneTitle
        )
    }

    @Test func recoveringTrajectoryHeadlinesTheNote() {
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(
                progress: IMToneDrillProgress(
                    direction: .recovering, earlierRate: 0.0, recentRate: 0.5, windowSize: 2
                )
            )
        )
        let lower = note.noteText.lowercased()
        #expect(lower.contains("difficult conversation"))
        #expect(lower.contains("calm"))
        #expect(note.noteText.contains("0%") && note.noteText.contains("50%"))
        #expect(!note.noteText.contains("!"))
    }

    @Test func slippingTrajectoryPointsAtADifferentOpening() {
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(
                voice: .authoritative,
                progress: IMToneDrillProgress(
                    direction: .slipping, earlierRate: 1.0, recentRate: 0.0, windowSize: 2
                )
            )
        )
        #expect(note.noteText.lowercased().contains("difficult conversation"))
        #expect(note.noteText.lowercased().contains("open"))
    }

    @Test func stalledTrajectoryFallsThroughToMetricNote() {
        // A flat trajectory is not worth bumping the per-rep metric note, so
        // the branch is skipped and the scenario name does not appear.
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(
                progress: IMToneDrillProgress(
                    direction: .stalled, earlierRate: 0.5, recentRate: 0.5, windowSize: 2
                )
            )
        )
        #expect(!note.noteText.contains("Difficult Conversation"))
    }

    @Test func noTrajectoryFallsThroughToMetricNote() {
        // Non-IM reps carry nil progress → the branch never fires.
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(mode: .timed, progress: nil, scenarioTitle: nil, toneTitle: nil)
        )
        #expect(!note.noteText.contains("Difficult Conversation"))
    }

    @Test func trajectorySentenceIsVoiceShapedAndCleanAcrossAllVoices() {
        let voices: [SpeakingStyleGoal?] = [
            .authoritative, .warm, .concise, .persuasive, .executive, .storytelling, nil
        ]
        let recovering = IMToneDrillProgress(
            direction: .recovering, earlierRate: 0.0, recentRate: 0.5, windowSize: 2
        )
        for voice in voices {
            let persona = CoachPersona.persona(for: voice)
            let sentence = PostRepCoachNoteService.imToneTrajectorySentence(
                progress: recovering, scenario: "Difficult Conversation", tone: "Calm", persona: persona
            )
            #expect(sentence.contains("0%") && sentence.contains("50%"))
            #expect(!sentence.contains("!"))
            #expect(!sentence.lowercased().hasPrefix("let's"))
        }
    }
}

// MARK: - Round 43: post-rep coach note's IM tone-drill anchoring on the just-finished rep
//
// M24 deferred slate round 43 — defensive symmetric pin to round 41 (SOLVED
// freshness on the chat-coach context surface) and round 42 (TRAJECTORY
// freshness on the chat-coach context surface). The post-rep note doesn't
// need a freshness gate because, by construction, the read IS the just-
// finished rep's scenario — the user just produced the rep that anchors the
// read. Round 43's job is to lock that structural anchoring contract in
// tests so a future refactor that drifts the helper toward a global
// "freshest trajectory anywhere" read fails loudly.
//
// The cross-rep cold-open path — where the user finishes an IM rep in
// scenario A and the deterministic note's TRAJECTORY branch references
// scenario B's old trajectory — must be structurally impossible. The pin
// lives in `MomentumComputer.imToneDrillNoteFields(forJustFinished:in:)`,
// which threads the just-finished rep's `details.setup.scenario` through
// `IMHistorySummary.toneDrillProgress(from:scenario:)` (and
// `IMHistorySummary.toneDrillCrossing(in:scenario:currentRepId:)` for the
// SOLVED branch). Both primitives filter strictly by scenario, so the trio
// is anchored on the just-finished rep by construction — round 43 makes
// that contract testable in isolation by lifting the block out of the
// finalizer's private `recordPostRepCoachNote`.
//
// The cross-surface tests through `deterministicNote(input:)` close the
// loop: even when scenario B has a textbook slipping below-bar trajectory
// in the session set, a note for a just-finished rep in scenario A NEVER
// mentions scenario B's title. The same SOLVED contract holds — a crossing
// in scenario B that pre-dates the just-finished rep doesn't headline the
// note for a sub-bar rep in scenario A.

struct PostRepCoachNoteJustFinishedRepAnchoringTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        id: UUID = UUID(),
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            id: id,
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86_400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    private func nonIMSession(daysOffset: Double = 0) -> PracticeSession {
        PracticeSession(
            transcript: "timed rep",
            fillerWordCount: 1,
            duration: 60,
            date: baseDate.addingTimeInterval(daysOffset * 86_400),
            mode: .timed,
            score: 7
        )
    }

    /// A 4-rep below-bar slip in the given scenario — all reps off-brand.
    /// Produces `toneDrillProgress` of `(stalled, 0.0, 0.0, 2)` (the same
    /// shape the round-41/42 fixtures use). Useful as the "scenario B"
    /// half of an anchoring test — the trajectory the helper must NOT
    /// pick up when the just-finished rep is in scenario A.
    private func slippingScenarioSessions(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        offBrandTone: String,
        earliestDayOffset: Double
    ) -> [PracticeSession] {
        [
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 1),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 2),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 3)
        ]
    }

    /// A 4-rep recovering trajectory in the given scenario — first two
    /// off-brand, last two on-brand. Earlier rate 0%, recent rate 100%,
    /// overall 50% (above the 40% drill bar). With the last rep included,
    /// `toneDrillResolved` fires; without it, the 3-rep history is below
    /// `toneDrillProgress`'s 4-rep floor and resolved returns nil — so the
    /// last rep IS the crossing rep.
    private func crossingScenarioSessions(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        offBrandTone: String,
        onBrandTone: String,
        crossingRepId: UUID,
        earliestDayOffset: Double
    ) -> [PracticeSession] {
        [
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 1),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: onBrandTone, daysOffset: earliestDayOffset + 2),
            imSession(id: crossingRepId, scenario: scenario, targetTone: targetTone, actualTone: onBrandTone, daysOffset: earliestDayOffset + 3)
        ]
    }

    // MARK: - Helper — non-IM rep returns empty

    @Test func helperReturnsEmptyForNonIMReps() {
        // The just-finished rep is a Timed rep — there's no scenario to
        // anchor on. Every field is nil.
        let justFinished = nonIMSession(daysOffset: 0)
        let allSessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        ) + [justFinished]

        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: allSessions
        )
        #expect(fields.progress == nil)
        #expect(fields.scenarioTitle == nil)
        #expect(fields.toneTitle == nil)
        #expect(fields.resolved == nil)
        #expect(fields.resolvedScenarioTitle == nil)
        #expect(fields.resolvedToneTitle == nil)
    }

    @Test func helperReturnsEmptyForIMRepWithoutConversationDetails() {
        // Defensive — legacy persisted IM sessions could carry `mode ==
        // .imConversation` but a nil `imConversationDetails`. The helper
        // must read all-nil rather than crash on the forced unwrap.
        let legacy = PracticeSession(
            transcript: "legacy",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate,
            mode: .imConversation,
            imConversationDetails: nil,
            score: 7
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: legacy, in: [legacy]
        )
        #expect(fields.progress == nil)
        #expect(fields.scenarioTitle == nil)
        #expect(fields.toneTitle == nil)
        #expect(fields.resolved == nil)
        #expect(fields.resolvedScenarioTitle == nil)
        #expect(fields.resolvedToneTitle == nil)
    }

    // MARK: - Helper — title anchoring

    @Test func helperAnchorsScenarioTitleOnJustFinishedRep() {
        // The scenario title comes from the just-finished rep's
        // `details.setup.scenario.title`, not from any "most common
        // scenario" read across history.
        let justFinished = imSession(
            scenario: .workUpdate, targetTone: .professional,
            actualTone: "professional", daysOffset: 0
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: [justFinished]
        )
        #expect(fields.scenarioTitle == IMConversationScenario.workUpdate.title)
    }

    @Test func helperAnchorsToneTitleOnJustFinishedRep() {
        // The tone title comes from the just-finished rep's
        // `details.setup.targetTone.title`, not from a "most committed
        // tone in scenario" read across history. Even when the
        // just-finished rep targets a DIFFERENT tone than prior reps in
        // the same scenario (the user re-targeted), the title surfaces
        // the JUST-FINISHED rep's tone.
        let priors = (1...4).map { i in
            imSession(
                scenario: .difficultConversation, targetTone: .calm,
                actualTone: "calm", daysOffset: -Double(i)
            )
        }
        let justFinished = imSession(
            scenario: .difficultConversation, targetTone: .assertive,
            actualTone: "assertive", daysOffset: 0
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: priors + [justFinished]
        )
        #expect(fields.toneTitle == IMTargetTone.assertive.title)
        #expect(fields.scenarioTitle == IMConversationScenario.difficultConversation.title)
    }

    // MARK: - Helper — thin per-scenario history

    @Test func helperReturnsThinHistoryNilProgressWithNonNilTitles() {
        // Just-finished rep is the only IM rep in its scenario. Per-
        // scenario history is below the 4-rep floor → `toneDrillProgress`
        // returns nil → progress field is nil. Titles remain set (they
        // come from `details.setup`, not from history).
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "shaky", daysOffset: 0
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: [justFinished]
        )
        #expect(fields.progress == nil)
        #expect(fields.scenarioTitle == IMConversationScenario.networking.title)
        #expect(fields.toneTitle == IMTargetTone.confident.title)
    }

    // MARK: - Helper — cross-rep anchoring (the core round-43 contract)

    @Test func helperProgressIgnoresOtherScenariosWhenJustFinishedRepIsThin() {
        // The just-finished rep is in scenario A (Networking, thin
        // history). Scenario B (Difficult Conversation) has a textbook 4-
        // rep below-bar slip. The "freshest trajectory anywhere" read
        // would surface scenario B's slip; the helper MUST NOT — it
        // threads scenario A through `toneDrillProgress`, which filters
        // strictly by scenario. Progress for the just-finished rep's
        // scenario is nil; the slipping trajectory in scenario B is
        // invisible to the helper.
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "shaky", daysOffset: 0
        )
        let scenarioBSlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -10
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: scenarioBSlip + [justFinished]
        )
        #expect(fields.progress == nil)
        #expect(fields.scenarioTitle == IMConversationScenario.networking.title)
        // The helper MUST NOT surface scenario B's title under either field.
        #expect(fields.scenarioTitle != IMConversationScenario.difficultConversation.title)
        #expect(fields.resolvedScenarioTitle == nil)
    }

    @Test func helperProgressReadsFromJustFinishedRepsScenarioOnlyWhenBothQualify() {
        // Both scenarios have 4-rep histories that would qualify for
        // `toneDrillProgress`. Scenario A (Difficult Conversation) is
        // RECOVERING (first 2 off, last 2 on); scenario B (Networking)
        // is SLIPPING (first 2 on, last 2 off). The just-finished rep is
        // in scenario A → returned progress direction must be
        // `.recovering`, NOT `.slipping`. Strict per-scenario anchoring.
        let recoveringA = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -7),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: 0)
        ]
        let slippingB = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -1)
        ]
        // Just-finished rep IS the last rep in scenario A.
        let justFinished = recoveringA.last!
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: recoveringA + slippingB
        )
        #expect(fields.progress?.direction == .recovering)
        #expect(fields.scenarioTitle == IMConversationScenario.difficultConversation.title)
        #expect(fields.toneTitle == IMTargetTone.calm.title)
    }

    @Test func helperProgressIsForJustFinishedScenarioEvenWhenOtherScenarioWouldFireMoreLoudly() {
        // The just-finished rep is in scenario A (Networking), where the
        // user has practiced ONCE — too thin for `toneDrillProgress`.
        // Scenario B (Difficult Conversation) has a textbook 4-rep
        // below-bar slip that the recommendation engine would prescribe
        // as the next drill. The helper must still surface only scenario
        // A's titles (with nil progress) — the post-rep note must NOT
        // pivot to commenting on scenario B's trajectory just because
        // it's the loudest open thread.
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "confident", daysOffset: 0
        )
        let scenarioBSlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -10
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: scenarioBSlip + [justFinished]
        )
        #expect(fields.progress == nil)
        #expect(fields.scenarioTitle == IMConversationScenario.networking.title)
        #expect(fields.toneTitle == IMTargetTone.confident.title)
    }

    // MARK: - Helper — SOLVED resolved trio anchoring

    @Test func helperReturnsNilResolvedWhenJustFinishedRepIsNotTheCrossingRep() {
        // The just-finished rep is in a sub-bar drill scenario (still
        // failing — first 2 windows of 4 reps are all off-brand). Even
        // though a crossing happened EARLIER in time in another scenario,
        // the resolved trio for the just-finished rep is nil — the
        // helper threads scenario A through `toneDrillCrossing`, which
        // only fires when the just-finished rep itself is the crossing.
        let crossingScenarioBPriorWin = crossingScenarioSessions(
            scenario: .workUpdate, targetTone: .professional,
            offBrandTone: "vague", onBrandTone: "professional",
            crossingRepId: UUID(), earliestDayOffset: -20
        )
        let justFinishedA = imSession(
            scenario: .difficultConversation, targetTone: .calm,
            actualTone: "tense", daysOffset: 0
        )
        let scenarioASlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinishedA,
            in: crossingScenarioBPriorWin + scenarioASlip + [justFinishedA]
        )
        #expect(fields.resolved == nil)
        #expect(fields.resolvedScenarioTitle == nil)
        #expect(fields.resolvedToneTitle == nil)
        // Trajectory still surfaces for scenario A (the just-finished
        // rep's scenario).
        #expect(fields.scenarioTitle == IMConversationScenario.difficultConversation.title)
    }

    @Test func helperPopulatesResolvedTrioOnCrossingRep() {
        // Construct a crossing rep: first 2 reps off-brand, last 2
        // on-brand. With all 4 reps, `toneDrillResolved` fires; without
        // the 4th, the 3-rep history is below the 4-rep floor of
        // `toneDrillProgress` so resolved returns nil → the 4th rep IS
        // the crossing.
        let crossingId = UUID()
        let crossingFour = crossingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", onBrandTone: "calm",
            crossingRepId: crossingId, earliestDayOffset: -3
        )
        let justFinished = crossingFour.last!
        #expect(justFinished.id == crossingId)
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: crossingFour
        )
        #expect(fields.resolved != nil)
        #expect(fields.resolvedScenarioTitle == IMConversationScenario.difficultConversation.title)
        #expect(fields.resolvedToneTitle == IMTargetTone.calm.title)
        #expect(fields.resolved?.scenario == .difficultConversation)
        #expect(fields.resolved?.targetTone == .calm)
    }

    @Test func helperResolvedTrioAnchorsOnJustFinishedRepScenarioTitle() {
        // Title equality contract: the resolved scenario title equals
        // the just-finished rep's scenario title (both routed through
        // `IMConversationScenario.title`).
        let crossingId = UUID()
        let crossingFour = crossingScenarioSessions(
            scenario: .networking, targetTone: .confident,
            offBrandTone: "shaky", onBrandTone: "confident",
            crossingRepId: crossingId, earliestDayOffset: -3
        )
        let justFinished = crossingFour.last!
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: crossingFour
        )
        #expect(fields.resolvedScenarioTitle == fields.scenarioTitle)
    }

    // MARK: - Cross-surface contract via deterministicNote

    @Test func deterministicNoteNeverNamesAnotherScenarioWhenJustFinishedRepIsThin() {
        // End-to-end pin on the cross-rep cold-open path. The just-
        // finished rep is in scenario A (Networking, thin history).
        // Scenario B (Difficult Conversation) has a fresh 4-rep below-
        // bar slip — the loudest open trajectory in the session set. The
        // deterministic note must NOT name scenario B; the only IM
        // surface the note can speak from is the just-finished rep's
        // scenario, which has nil trajectory → the metric chain takes
        // over instead.
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "confident", daysOffset: 0
        )
        let scenarioBSlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: scenarioBSlip + [justFinished]
        )
        let input = PostRepCoachNoteInput(
            sessionID: justFinished.id,
            mode: .imConversation,
            score: 7,
            fillerCount: 2,
            duration: 60,
            wordCount: 120,
            voice: nil,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            totalSessionCount: 8,
            imToneDrillProgress: fields.progress,
            imToneDrillScenarioTitle: fields.scenarioTitle,
            imToneDrillToneTitle: fields.toneTitle,
            imToneDrillResolved: fields.resolved,
            imToneDrillResolvedScenarioTitle: fields.resolvedScenarioTitle,
            imToneDrillResolvedToneTitle: fields.resolvedToneTitle
        )
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        #expect(!note.noteText.contains("Difficult Conversation"))
        #expect(!note.noteText.lowercased().contains("difficult conversation"))
    }

    @Test func deterministicNoteSpeaksToJustFinishedScenarioOnRecoveringTrajectory() {
        // Happy path through the helper + deterministic note. The just-
        // finished rep is in scenario A (Difficult Conversation, calm)
        // and scenario A's trajectory is recovering BUT not yet solved
        // (recent rate 50% — below the 60% hold bar). Scenario B
        // (Networking, confident) has a textbook slipping trajectory in
        // the same session set. The note headlines scenario A; the note
        // must NOT mention scenario B; only the just-finished rep's
        // scenario can be the subject of the trajectory read.
        let recoveringA = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -7),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: 0)
        ]
        let slippingB = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -1)
        ]
        let justFinished = recoveringA.last!
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: recoveringA + slippingB
        )
        let input = PostRepCoachNoteInput(
            sessionID: justFinished.id,
            mode: .imConversation,
            score: 7,
            fillerCount: 2,
            duration: 60,
            wordCount: 120,
            voice: nil,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            totalSessionCount: 8,
            imToneDrillProgress: fields.progress,
            imToneDrillScenarioTitle: fields.scenarioTitle,
            imToneDrillToneTitle: fields.toneTitle,
            imToneDrillResolved: fields.resolved,
            imToneDrillResolvedScenarioTitle: fields.resolvedScenarioTitle,
            imToneDrillResolvedToneTitle: fields.resolvedToneTitle
        )
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        let lower = note.noteText.lowercased()
        #expect(lower.contains("difficult conversation"))
        #expect(lower.contains("calm"))
        #expect(!lower.contains("networking"))
        #expect(!lower.contains("confident"))
    }

    @Test func deterministicNoteHeadlinesResolvedWinOnlyForJustFinishedRepsScenario() {
        // SOLVED-branch cross-surface pin. The just-finished rep is a
        // sub-bar IM rep in scenario A; scenario B had a crossing rep at
        // an EARLIER date in history. The deterministic note must not
        // headline scenario B's old crossing — the helper threads
        // scenario A through `toneDrillCrossing` so the resolved trio is
        // nil for the just-finished rep, and the note's SOLVED branch
        // stays quiet.
        let priorCrossingB = crossingScenarioSessions(
            scenario: .workUpdate, targetTone: .professional,
            offBrandTone: "vague", onBrandTone: "professional",
            crossingRepId: UUID(), earliestDayOffset: -20
        )
        let scenarioASlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        )
        let justFinished = scenarioASlip.last!
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: priorCrossingB + scenarioASlip
        )
        #expect(fields.resolved == nil)
        let input = PostRepCoachNoteInput(
            sessionID: justFinished.id,
            mode: .imConversation,
            score: 5,
            fillerCount: 2,
            duration: 60,
            wordCount: 120,
            voice: nil,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            totalSessionCount: 12,
            imToneDrillProgress: fields.progress,
            imToneDrillScenarioTitle: fields.scenarioTitle,
            imToneDrillToneTitle: fields.toneTitle,
            imToneDrillResolved: fields.resolved,
            imToneDrillResolvedScenarioTitle: fields.resolvedScenarioTitle,
            imToneDrillResolvedToneTitle: fields.resolvedToneTitle
        )
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        let lower = note.noteText.lowercased()
        #expect(!lower.contains("work update"))
        #expect(!lower.contains("professional"))
    }
}

// MARK: - AI-path symmetric pin on the post-rep coach note IM tone-drill clauses (round 44)
//
// `PostRepCoachNoteService.userPrompt(from:)` builds the AI provider's
// MOMENTUM block by reading the SAME `imToneDrill*` fields the
// deterministic path reads. The round-43 helper anchoring contract
// (`MomentumComputer.imToneDrillNoteFields(forJustFinished:in:)`) ensures
// those fields are always anchored on the just-finished rep's scenario —
// never on a "loudest open trajectory anywhere" global read — so the AI
// prompt's IM tone-drill clauses also can't name a non-just-finished
// scenario, by construction.
//
// Round 44 is the defensive AI-path symmetric pin to round 43's
// `PostRepCoachNoteJustFinishedRepAnchoringTests` deterministic-path
// suite. Same fixtures, same cross-rep cold-open contract, but routed
// through `userPrompt(from:)` instead of `deterministicNote(input:)`.
// The two surfaces stay locked in step: a future regression that lets
// the AI prompt name scenario B when the just-finished rep is in
// scenario A breaks here AND breaks round 43's deterministic-path tests.
//
// `userPrompt(from:)` is `nonisolated static`, so the tests run without
// AI provider stubs.
//
// Future move #22 from round 43's HANDOFF, closed.

struct PostRepCoachNoteUserPromptAnchoringTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        id: UUID = UUID(),
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        actualTone: String?,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            id: id,
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86_400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: targetTone),
                turns: [],
                actualTone: actualTone,
                finalState: IMConversationState(trust: 6, engagement: 6, tension: 5, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    private func nonIMSession(daysOffset: Double = 0) -> PracticeSession {
        PracticeSession(
            transcript: "timed rep",
            fillerWordCount: 1,
            duration: 60,
            date: baseDate.addingTimeInterval(daysOffset * 86_400),
            mode: .timed,
            score: 7
        )
    }

    /// A 4-rep below-bar slip in the given scenario — all reps off-brand.
    /// Mirrors round-43's slipping fixture so the cross-rep cold-open
    /// contracts use the same shape across surfaces.
    private func slippingScenarioSessions(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        offBrandTone: String,
        earliestDayOffset: Double
    ) -> [PracticeSession] {
        [
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 1),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 2),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 3)
        ]
    }

    /// A 4-rep crossing trajectory: first 2 off-brand, last 2 on-brand. The
    /// last rep is the crossing rep — `toneDrillCrossing` fires for it.
    private func crossingScenarioSessions(
        scenario: IMConversationScenario,
        targetTone: IMTargetTone,
        offBrandTone: String,
        onBrandTone: String,
        crossingRepId: UUID,
        earliestDayOffset: Double
    ) -> [PracticeSession] {
        [
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: offBrandTone, daysOffset: earliestDayOffset + 1),
            imSession(scenario: scenario, targetTone: targetTone, actualTone: onBrandTone, daysOffset: earliestDayOffset + 2),
            imSession(id: crossingRepId, scenario: scenario, targetTone: targetTone, actualTone: onBrandTone, daysOffset: earliestDayOffset + 3)
        ]
    }

    /// Build the `PostRepCoachNoteInput` that the finalizer would build,
    /// routing the just-finished rep through the round-43 helper so the
    /// `imToneDrill*` fields are anchored on the just-finished rep's
    /// scenario by construction (the AI path's cross-rep cold-open
    /// impossibility flows from this single wire).
    private func makeInput(
        justFinished: PracticeSession,
        allSessions: [PracticeSession],
        score: Int? = 7
    ) -> PostRepCoachNoteInput {
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: allSessions
        )
        return PostRepCoachNoteInput(
            sessionID: justFinished.id,
            mode: justFinished.mode,
            score: score,
            fillerCount: 2,
            duration: 60,
            wordCount: 120,
            voice: nil,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            totalSessionCount: max(allSessions.count, 8),
            imToneDrillProgress: fields.progress,
            imToneDrillScenarioTitle: fields.scenarioTitle,
            imToneDrillToneTitle: fields.toneTitle,
            imToneDrillResolved: fields.resolved,
            imToneDrillResolvedScenarioTitle: fields.resolvedScenarioTitle,
            imToneDrillResolvedToneTitle: fields.resolvedToneTitle
        )
    }

    // MARK: - userPrompt — non-IM reps drop the IM tone-drill clauses

    @Test func userPromptOmitsIMTrajectoryClauseForNonIMReps() {
        // The helper returns `.empty` for a Timed rep — so the AI prompt's
        // trajectory clause (which requires non-nil progress + titles) is
        // never appended. The "tone-match" / "tone in" phrasing is the
        // structural marker of the trajectory clause; neither may appear.
        let justFinished = nonIMSession(daysOffset: 0)
        let allSessions = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        ) + [justFinished]
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: allSessions)
        )
        #expect(!prompt.contains("tone-match"))
        #expect(!prompt.lowercased().contains(" tone in "))
        #expect(!prompt.contains("Difficult Conversation"))
    }

    @Test func userPromptOmitsIMResolvedClauseForNonIMReps() {
        // Same shape as the trajectory test but for SOLVED. The helper
        // returns `.empty` → `imToneDrillResolved` is nil → the SOLVED
        // clause's `"SOLVED this rep"` marker is never written.
        let crossingId = UUID()
        let crossingFour = crossingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", onBrandTone: "calm",
            crossingRepId: crossingId, earliestDayOffset: -10
        )
        let justFinished = nonIMSession(daysOffset: 0)
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: crossingFour + [justFinished])
        )
        #expect(!prompt.contains("SOLVED this rep"))
        #expect(!prompt.contains("Difficult Conversation"))
    }

    @Test func userPromptOmitsIMClausesForLegacyIMRepsWithoutDetails() {
        // Defensive — legacy persisted IM sessions could carry `mode ==
        // .imConversation` but a nil `imConversationDetails`. The helper
        // reads `.empty` rather than crashing; the AI prompt has no IM
        // tone-drill clause to render.
        let legacy = PracticeSession(
            transcript: "legacy",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate,
            mode: .imConversation,
            imConversationDetails: nil,
            score: 7
        )
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: legacy, allSessions: [legacy])
        )
        #expect(!prompt.contains("tone-match"))
        #expect(!prompt.contains("SOLVED this rep"))
    }

    // MARK: - userPrompt — happy-path clauses name the just-finished rep's titles

    @Test func userPromptIncludesTrajectoryClauseNamingJustFinishedRepsScenario() {
        // Recovering trajectory in scenario A (Difficult Conversation,
        // calm): first 2 reps off, last 2 on. The just-finished rep is the
        // 4th. The AI prompt's MOMENTUM block must include a trajectory
        // clause that names scenario A's title.
        let recoveringA = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -7),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: 0)
        ]
        let justFinished = recoveringA.last!
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: recoveringA)
        )
        #expect(prompt.contains("Difficult Conversation"))
        #expect(prompt.contains("tone-match"))
    }

    @Test func userPromptTrajectoryClauseNamesJustFinishedRepsTone() {
        // The tone in the MOMENTUM trajectory clause comes from the
        // just-finished rep's tone title — anchored, not derived from a
        // "most committed tone in history" read.
        let recoveringA = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -7),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: 0)
        ]
        let justFinished = recoveringA.last!
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: recoveringA)
        )
        #expect(prompt.contains("Calm tone in Difficult Conversation"))
    }

    // MARK: - userPrompt — defensive gating on direction + title nullability

    @Test func userPromptOmitsTrajectoryClauseOnStalledDirection() {
        // `userPrompt` gates the trajectory clause on `direction != .stalled`
        // — a flat trajectory isn't worth coaching language. A stalled
        // progress with valid titles must NOT produce a "tone-match" clause.
        // This is locked symmetric to the deterministic-path stalled
        // fall-through pinned in `PostRepCoachNoteToneTrajectoryTests`.
        let stalledInput = PostRepCoachNoteInput(
            sessionID: UUID(),
            mode: .imConversation,
            score: 7,
            fillerCount: 1,
            duration: 60,
            wordCount: 80,
            voice: nil,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            totalSessionCount: 8,
            imToneDrillProgress: IMToneDrillProgress(
                direction: .stalled, earlierRate: 0.25, recentRate: 0.30, windowSize: 2
            ),
            imToneDrillScenarioTitle: "Difficult Conversation",
            imToneDrillToneTitle: "Calm"
        )
        let prompt = PostRepCoachNoteService.userPrompt(from: stalledInput)
        #expect(!prompt.contains("tone-match"))
        #expect(!prompt.contains("Calm tone in Difficult Conversation"))
    }

    @Test func userPromptOmitsTrajectoryClauseWhenScenarioTitleIsNil() {
        // Belt-and-braces — `userPrompt` unwraps titles before emitting
        // the clause. A non-nil progress with nil titles (a state the
        // helper never produces, but the input is constructable) must
        // still skip the clause rather than emit a nil-string fragment.
        let titlelessInput = PostRepCoachNoteInput(
            sessionID: UUID(),
            mode: .imConversation,
            score: 7,
            fillerCount: 1,
            duration: 60,
            wordCount: 80,
            voice: nil,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            totalSessionCount: 8,
            imToneDrillProgress: IMToneDrillProgress(
                direction: .recovering, earlierRate: 0.0, recentRate: 0.5, windowSize: 2
            ),
            imToneDrillScenarioTitle: nil,
            imToneDrillToneTitle: nil
        )
        let prompt = PostRepCoachNoteService.userPrompt(from: titlelessInput)
        #expect(!prompt.contains("tone-match"))
    }

    // MARK: - userPrompt — cross-rep cold-open contracts (round-44 core)

    @Test func userPromptNeverNamesAnotherScenarioWhenJustFinishedRepIsThin() {
        // End-to-end pin on the cross-rep cold-open path through the AI
        // prompt — the symmetric companion to round-43's
        // `deterministicNoteNeverNamesAnotherScenarioWhenJustFinishedRepIsThin`.
        // Just-finished rep in scenario A (Networking, thin history).
        // Scenario B (Difficult Conversation) has a fresh 4-rep below-bar
        // slip — the loudest open trajectory in the session set. The AI
        // prompt MUST NOT name scenario B's title; the only IM surface the
        // prompt can speak from is the just-finished rep's scenario, which
        // has nil trajectory.
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "confident", daysOffset: 0
        )
        let scenarioBSlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        )
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: scenarioBSlip + [justFinished])
        )
        #expect(!prompt.contains("Difficult Conversation"))
        #expect(!prompt.lowercased().contains("difficult conversation"))
        // No spurious trajectory clause should fire — the helper returns
        // nil progress for scenario A's thin history.
        #expect(!prompt.contains("tone-match"))
    }

    @Test func userPromptSolvedClauseNamesJustFinishedScenarioOnly() {
        // The crossing rep IS the just-finished rep. The SOLVED clause
        // fires and names scenario A's title — never any other scenario in
        // the user's history.
        let crossingId = UUID()
        let crossingFour = crossingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", onBrandTone: "calm",
            crossingRepId: crossingId, earliestDayOffset: -3
        )
        let justFinished = crossingFour.last!
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: crossingFour)
        )
        #expect(prompt.contains("SOLVED this rep"))
        #expect(prompt.contains("Difficult Conversation"))
        #expect(prompt.contains("Calm tone in Difficult Conversation"))
    }

    @Test func userPromptOmitsSolvedClauseWhenResolvedIsNil() {
        // Non-crossing rep — the SOLVED branch must stay quiet. A sub-bar
        // rep in scenario A with no crossing → resolved is nil → the AI
        // prompt has no SOLVED-shaped clause to emit.
        let scenarioASlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        )
        let justFinished = scenarioASlip.last!
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: scenarioASlip)
        )
        #expect(!prompt.contains("SOLVED this rep"))
    }

    @Test func userPromptNeverNamesAnotherScenarioOnSolvedCrossSurfaceContract() {
        // End-to-end pin on the SOLVED cross-rep cold-open path through
        // the AI prompt — the symmetric companion to round-43's
        // `deterministicNoteHeadlinesResolvedWinOnlyForJustFinishedRepsScenario`.
        // The just-finished rep is sub-bar in scenario A; scenario B had a
        // crossing rep at an earlier date. The helper threads scenario A
        // through `toneDrillCrossing` → resolved is nil for the just-
        // finished rep → the AI prompt's SOLVED clause must not name
        // scenario B's old crossing.
        let priorCrossingB = crossingScenarioSessions(
            scenario: .workUpdate, targetTone: .professional,
            offBrandTone: "vague", onBrandTone: "professional",
            crossingRepId: UUID(), earliestDayOffset: -20
        )
        let scenarioASlip = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        )
        let justFinished = scenarioASlip.last!
        let prompt = PostRepCoachNoteService.userPrompt(
            from: makeInput(justFinished: justFinished, allSessions: priorCrossingB + scenarioASlip, score: 5)
        )
        #expect(!prompt.contains("SOLVED this rep"))
        #expect(!prompt.contains("Work Update"))
        #expect(!prompt.contains("Professional"))
        #expect(!prompt.lowercased().contains("work update"))
    }

    // MARK: - Cross-surface contract: userPrompt + deterministicNote name the same scenario

    @Test func userPromptAndDeterministicNoteNameSameJustFinishedRepsScenario() {
        // Both surfaces route through the same `imToneFields` from the
        // round-43 helper. A recovering trajectory in scenario A (with a
        // loud slipping trajectory in scenario B in the same session set)
        // must produce: prompt + deterministic note BOTH name scenario A,
        // NEITHER names scenario B. The two surfaces stay structurally
        // locked.
        let recoveringA = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -7),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: 0)
        ]
        let slippingB = [
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -4),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "confident", daysOffset: -3),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -2),
            imSession(scenario: .networking, targetTone: .confident, actualTone: "shaky",     daysOffset: -1)
        ]
        let justFinished = recoveringA.last!
        let input = makeInput(
            justFinished: justFinished,
            allSessions: recoveringA + slippingB
        )
        let prompt = PostRepCoachNoteService.userPrompt(from: input)
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        // Prompt — names scenario A, not B.
        #expect(prompt.contains("Difficult Conversation"))
        #expect(!prompt.contains("Networking"))
        // Note — names scenario A, not B.
        let lowerNote = note.noteText.lowercased()
        #expect(lowerNote.contains("difficult conversation"))
        #expect(!lowerNote.contains("networking"))
    }

    // MARK: - Cross-surface contract: SOLVED-branch symmetric companion (round 45)
    //
    // Round 45 closes future move #25 from round 44's HANDOFF — the
    // TRAJECTORY-branch cross-surface contract pinned by
    // `userPromptAndDeterministicNoteNameSameJustFinishedRepsScenario`
    // above is symmetrically pinned on the SOLVED branch. Same shape: a
    // crossing rep in scenario A as the just-finished rep, a parallel
    // scenario B carrying loud signals (current slip, prior crossing) in
    // the same session set, and both surfaces — AI prompt + deterministic
    // note — MUST headline scenario A's SOLVED win and NEITHER may name
    // scenario B. Three angles cover (1) the baseline thin-B case,
    // (2) the parallel-currently-slipping-B case where the recommendation
    // engine would prescribe B's drill, and (3) the parallel-prior-
    // crossing-C case where a past win in another scenario could tempt a
    // "you've done it before" pivot. All three are pinned in lockstep —
    // a future regression on either surface trips the cross-surface
    // contract independently of which path broke first.

    @Test func userPromptAndDeterministicNoteSolvedBranchAnchorOnJustFinishedScenario() {
        // Baseline SOLVED cross-surface contract — symmetric to round 44's
        // `userPromptAndDeterministicNoteNameSameJustFinishedRepsScenario`
        // on the TRAJECTORY surface. Just-finished rep IS the crossing rep
        // in scenario A; scenario B sits in the session set as a thin
        // parallel (one rep, no qualifying history). Both surfaces name
        // scenario A's title in the SOLVED clause; neither names B.
        let crossingId = UUID()
        let crossingA = crossingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", onBrandTone: "calm",
            crossingRepId: crossingId, earliestDayOffset: -3
        )
        let thinB = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "shaky", daysOffset: -1
        )
        let justFinished = crossingA.last!
        #expect(justFinished.id == crossingId)
        let input = makeInput(
            justFinished: justFinished,
            allSessions: crossingA + [thinB]
        )
        let prompt = PostRepCoachNoteService.userPrompt(from: input)
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        // Prompt — SOLVED clause names scenario A, not B.
        #expect(prompt.contains("SOLVED this rep"))
        #expect(prompt.contains("Difficult Conversation"))
        #expect(!prompt.contains("Networking"))
        // Note — the holding sentence names scenario A, not B. The deterministic
        // priority chain hits SOLVED first (branch 0 in
        // `metricSentence(for:persona:)`), while the user-facing copy stays
        // evidence-scaled rather than claiming the skill is solved.
        let lowerNote = note.noteText.lowercased()
        #expect(lowerNote.contains("difficult conversation"))
        #expect(lowerNote.contains("holding"))
        #expect(!lowerNote.contains("networking"))
    }

    @Test func userPromptAndDeterministicNoteSolvedBranchHoldsWhenParallelScenarioIsRecentlySlipping() {
        // Defensive — scenario B has a current 4-rep below-bar slip in
        // the same session set (the recommendation engine would prescribe
        // B's drill next). The helper threads scenario A only through
        // `toneDrillCrossing` and `toneDrillProgress`, so B's slip is
        // invisible to BOTH the AI prompt's MOMENTUM clauses and the
        // deterministic note's metric chain. Both surfaces remain on
        // scenario A's SOLVED win; B's loudest open thread never surfaces.
        let crossingId = UUID()
        let crossingA = crossingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", onBrandTone: "calm",
            crossingRepId: crossingId, earliestDayOffset: -3
        )
        let slippingB = slippingScenarioSessions(
            scenario: .networking, targetTone: .confident,
            offBrandTone: "shaky", earliestDayOffset: -4
        )
        let justFinished = crossingA.last!
        #expect(justFinished.id == crossingId)
        let input = makeInput(
            justFinished: justFinished,
            allSessions: crossingA + slippingB
        )
        let prompt = PostRepCoachNoteService.userPrompt(from: input)
        let note = PostRepCoachNoteService.deterministicNote(input: input)
        // Prompt — SOLVED clause names scenario A; B's slip never surfaces.
        #expect(prompt.contains("SOLVED this rep"))
        #expect(prompt.contains("Difficult Conversation"))
        #expect(!prompt.contains("Networking"))
        // Note — SOLVED branch wins the priority chain even when B's
        // trajectory would have been the loudest open thread.
        let lowerNote = note.noteText.lowercased()
        #expect(lowerNote.contains("difficult conversation"))
        #expect(lowerNote.contains("holding"))
