        // never derived from a "loudest scenario" read.
        #expect(fields.scenarioTitle == "Networking")
        #expect(fields.toneTitle == "Confident")
    }

    @Test func helperReturnsResolvedAndRecoveringWithBoundaryRatesForRoundFortyFiveCrossingFixture() {
        // Crossing-A own-scenario — the round-45 baseline crossing
        // fixture (built via the suite's `crossingScenarioSessions`
        // helper). Actual tones in scenario A (Difficult Conversation,
        // calm): `["tense", "tense", "calm", "calm"]` (the 4th rep is
        // the crossing rep, marked with `crossingId` via the helper's
        // `id:` parameter) → outcomes `[false, false, true, true]`;
        // earlier prefix `[false, false]` = 0% match; recent suffix
        // `[true, true]` = 100% match; delta = 1.0 → recovering. The
        // SOLVED gate passes both arms: earlierRate (0.0) < threshold
        // (0.4) AND recentRate (1.0) >= holdRate (0.6) AND overallRate
        // (0.5) >= matchRateThreshold (0.4) AND the just-finished rep
        // IS the crossing rep (resolved-with-this-rep is non-nil,
        // resolved-without-this-rep is nil because the 3-rep history
        // sits below the 4-rep floor of `toneDrillProgress`). The
        // helper threads scenario A through `toneDrillCrossing` →
        // resolved trio populated → both surfaces' SOLVED clauses can
        // fire. Round 43 already pinned `.resolved != nil` and the
        // resolved title equality on this fixture
        // (`helperPopulatesResolvedTrioOnCrossingRep` +
        // `helperResolvedTrioAnchorsOnJustFinishedRepScenarioTitle`);
        // round 50 extends the helper-boundary contract to the
        // direction classification AND the boundary rate values on
        // both the progress side AND the resolved side, mirroring the
        // round-49 pattern at the crossing corner of the matrix. A
        // future regression that broke ONLY the resolved object's
        // rate copying (e.g., wiring `recentRate: progress.earlierRate`
        // by mistake) would still produce a non-nil resolved with the
        // right titles, so the round-43 + round-45 tests would still
        // pass — but the resolved object's rate values would be wrong;
        // round 50 catches that at the helper boundary.
        let crossingId = UUID()
        let crossingA = crossingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", onBrandTone: "calm",
            crossingRepId: crossingId, earliestDayOffset: -3
        )
        let justFinished = crossingA.last!
        // Defensive belt — the suite helper's `crossingRepId` argument
        // wires the just-finished rep's id to `crossingId`; a future
        // refactor of the helper that flipped the wiring would silently
        // change which rep `toneDrillCrossing` evaluates against.
        #expect(justFinished.id == crossingId)
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: crossingA
        )
        // Direction — the recovering gate fires on the crossing fixture
        // too (the resolved branch and the trajectory branch are
        // structurally independent gates on `imToneDrillProgress` and
        // `imToneDrillResolved`; both can be non-nil for the same
        // just-finished rep, and the surface templates render the
        // SOLVED clause OUTRANKING the trajectory clause — locked by
        // `PostRepCoachNoteToneResolvedTests` — so the surface stays
        // single-voice while the helper carries both reads).
        #expect(fields.progress?.direction == .recovering)
        // Progress-side rate boundaries — exact 0.0 / 1.0 on the two
        // windows. The mirror of the recovering fixture's 0.0 / 0.5
        // rates, but at the ceiling on the recent window — the
        // crossing fixture is the recovering corner taken all the way
        // to the SOLVED gate.
        #expect(fields.progress?.earlierRate == 0.0)
        #expect(fields.progress?.recentRate == 1.0)
        #expect(fields.progress?.windowSize == 2)
        // SOLVED-side: resolved trio populated. The round-43
        // `helperPopulatesResolvedTrioOnCrossingRep` test already
        // asserts the non-nil resolved + title equality; round 50
        // extends to the resolved object's rate boundaries — proves
        // the helper copies `progress.earlierRate` / `progress.recentRate`
        // into the resolved object verbatim (the `IMHistorySummary.toneDrillResolved`
        // primitive's wiring), so a future regression that broke ONLY
        // the rate copying — without breaking the non-nil gate or the
        // titles — is caught at the helper boundary.
        #expect(fields.resolved != nil)
        #expect(fields.resolved?.earlierRate == 0.0)
        #expect(fields.resolved?.recentRate == 1.0)
        #expect(fields.resolved?.scenario == .difficultConversation)
        #expect(fields.resolved?.targetTone == .calm)
        #expect(fields.resolvedScenarioTitle == "Difficult Conversation")
        #expect(fields.resolvedToneTitle == "Calm")
        // Scenario + tone titles on the progress side — anchored on
        // the just-finished rep, the round-43 contract carried through
        // the SOLVED branch.
        #expect(fields.scenarioTitle == "Difficult Conversation")
        #expect(fields.toneTitle == "Calm")
        // Title equality across progress + resolved sides — both
        // anchored on the just-finished rep's scenario, the round-43
        // `helperResolvedTrioAnchorsOnJustFinishedRepScenarioTitle`
        // contract pinned again at the rate-boundary fixture.
        #expect(fields.resolvedScenarioTitle == fields.scenarioTitle)
        #expect(fields.resolvedToneTitle == fields.toneTitle)
    }

    // MARK: - Helper-level nil-progress / nil-resolved assertions on the round-46 thin-A fixtures (round 51)
    //
    // Round 51 closes the remaining leg of future move #29 from round
    // 50's HANDOFF — "Helper-output assertion on the thin-A round-46
    // leg." Round 49 covered the round-47 50%-alternating leg and the
    // round-48 boundary-fixture legs (helper-level direction assertions
    // on the three stalled fixtures). Round 50 covered the round-44/45
    // non-stalled corners (helper-level direction + boundary-rate
    // assertions on the recovering / slipping / crossing fixtures). The
    // remaining leg is the THIN corner — the round-46 thin-A
    // just-finished fixtures where scenario A has only 1 evaluated rep
    // (the just-finished rep itself) and the helper's
    // `IMHistorySummary.toneDrillProgress` 4-rep floor gates both
    // `progress` and `resolved` to nil. The round-46 surface tests
    // already assert the prompt + deterministic note never name the
    // parallel scenario when the just-finished rep is thin in A, which is
    // the user-facing contract; round 51 lifts the helper-output
    // structural contract — `progress == nil && resolved == nil` —
    // from the surface layer to the helper layer at all three round-46
    // parallel-loud fixture shapes (slipping-B, recovering-B,
    // prior-crossing-C), completing the two-layer regression net
    // (surface + helper) on the fifth structural corner of the
    // direction × locus matrix (recovering / slipping / crossing /
    // stalled / thin). Pure test addition; no production code change;
    // no engine state change; no schema bump; no migration; no new
    // view inputs. The structural contracts were already true at round
    // 14 (the `IMHistorySummary.toneDrillProgress` primitive's
    // `outcomes.count >= 4` floor at line 552 of `IMHistorySummary.swift`)
    // and at round 43 (the helper threads only the just-finished rep's
    // scenario through `toneDrillProgress`, never the parallel
    // scenario's history); round 51 locks the thin-A helper-boundary
    // output at each round-46 fixture shape so a future regression
    // that broke ONLY the 4-rep floor (e.g., shifted it to 3) or the
    // scenario-filter in the helper (e.g., pulled the parallel
    // scenario's outcomes into the window-split) is caught at the
    // helper output, before either downstream surface gets a chance to
    // silently swallow the change. The titles assertion is the
    // round-43 anchoring contract carried through the thin corner —
    // even when both progress and resolved are nil, the helper still
    // derives `scenarioTitle` + `toneTitle` from the just-finished
    // rep's `imConversationDetails.setup` (lines 385-386 of
    // `PostRepCoachNoteService.swift`), so a future regression that
    // accidentally nilled the titles alongside the progress trio would
    // trip the round-51 title assertions independently of the nil-on-
    // both assertions.
    //
    // The contract layered on top of rounds 49 + 50: round 51 makes
    // the helper-boundary assertion across all FIVE structural corners
    // of the matrix structurally complete in lockstep — recovering
    // (round 50, fields.progress != nil + .recovering direction + 0.0/
    // 0.5 rates), slipping (round 50, fields.progress != nil + .slipping
    // direction + 1.0/0.0 rates), crossing (round 50, fields.progress
    // != nil + .recovering direction + fields.resolved != nil), stalled
    // (round 49, fields.progress != nil + .stalled direction at 50%-
    // alternating + 0%-floor + 100%-ceiling), thin (round 51, fields.
    // progress == nil + fields.resolved == nil + titles still
    // anchored). The five corners together close the helper-boundary
    // belt at every shape the post-rep coach note's IM tone-drill
    // surface reads from.

    @Test func helperReturnsNilProgressAndNilResolvedForRoundFortySixThinJustFinishedWithParallelSlippingFixture() {
        // Thin-A just-finished + parallel-slipping-B — the round-46
        // baseline thin-just-finished cross-surface contract
        // (`userPromptAndDeterministicNoteThinJustFinishedNeverNameParallelSlippingScenario`).
        // Just-finished rep is the lone evaluated rep in scenario A
        // (Networking, confident, on-brand "confident"); scenario B
        // (Difficult Conversation, calm) carries a 4-rep below-bar
        // slip — the loudest open trajectory and the recommendation
        // engine's next prescription. The helper threads scenario A
        // only through `toneDrillProgress` (1 rep → nil at the 4-rep
        // floor) AND through `toneDrillCrossing` (1 rep → nil; needs
        // disjoint windows). Both trio fields nil. The titles still
        // anchor on the just-finished rep's scenario + tone — the
        // round-43 anchoring contract holds even when the trajectory
        // and SOLVED branches both gate off. A future regression that
        // pulled scenario B's outcomes into scenario A's window-split
        // (e.g., a scenario-filter inversion in the helper) would
        // silently flip `progress` to non-nil with B's slipping shape
        // while the surface trajectory clause kept rendering A's
        // anchoring titles — the round-46 surface tests would still
        // pass on the anchoring assertion, but the helper's progress
        // trio would be wrong; round 51 catches that at the helper
        // boundary.
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "confident", daysOffset: 0
        )
        let slippingB = slippingScenarioSessions(
            scenario: .difficultConversation, targetTone: .calm,
            offBrandTone: "tense", earliestDayOffset: -3
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: slippingB + [justFinished]
        )
        // Progress trio — nil because scenario A has only 1 evaluated
        // rep (below the 4-rep floor in `toneDrillProgress`). A
        // regression that pulled scenario B's 4 reps into the
        // window-split would silently flip this to non-nil.
        #expect(fields.progress == nil)
        // SOLVED trio — nil because scenario A has only 1 rep (no
        // earlier window to compare against in `toneDrillCrossing`).
        // A regression that pulled scenario C's prior crossing into
        // the resolved gate would silently flip this to non-nil.
        #expect(fields.resolved == nil)
        #expect(fields.resolvedScenarioTitle == nil)
        #expect(fields.resolvedToneTitle == nil)
        // Scenario + tone titles — STILL anchored on the just-finished
        // rep's scenario even when both branches gate off. The
        // round-43 anchoring contract: the helper derives titles from
        // `details.setup.scenario` + `details.setup.targetTone`
        // unconditionally when the just-finished rep is an IM rep with
        // details (lines 385-386 of `PostRepCoachNoteService.swift`);
        // the trajectory / SOLVED branches gate independently. A
        // regression that nilled the titles alongside the progress
        // trio would trip these assertions independently of the
        // nil-on-both assertions above.
        #expect(fields.scenarioTitle == "Networking")
        #expect(fields.toneTitle == "Confident")
    }

    @Test func helperReturnsNilProgressAndNilResolvedForRoundFortySixThinJustFinishedWithParallelRecoveringFixture() {
        // Thin-A just-finished + parallel-recovering-B — the round-46
        // recovering-elsewhere cross-surface contract
        // (`userPromptAndDeterministicNoteThinJustFinishedNeverNameParallelRecoveringScenario`).
        // Scenario B carries a 4-rep recovering trajectory (the
        // "you're recovering elsewhere" pivot would be the loudest
        // open positive thread the recommendation engine could
        // surface). The helper threads scenario A only through both
        // primitives, so B's recovery is invisible to the helper
        // output — the trajectory trio stays nil even though scenario
        // B has a recovering trajectory the round-50 helper-boundary
        // test would classify as `.recovering` with 0.0/0.5 rates.
        // Mirrors the round-50 recovering-A fixture's shape but
        // shifted to scenario B with the same off-on rep pattern.
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "confident", daysOffset: 0
        )
        let recoveringB = [
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -7),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "rushed", daysOffset: -6),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "tense",  daysOffset: -5),
            imSession(scenario: .difficultConversation, targetTone: .calm, actualTone: "calm",   daysOffset: -1)
        ]
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: recoveringB + [justFinished]
        )
        // Progress trio — nil. Scenario A still has only 1 rep; B's
        // recovering trajectory is invisible to A's helper read.
        #expect(fields.progress == nil)
        // SOLVED trio — nil. The same 1-rep floor blocks the
        // resolved branch.
        #expect(fields.resolved == nil)
        #expect(fields.resolvedScenarioTitle == nil)
        #expect(fields.resolvedToneTitle == nil)
        // Titles still anchor on A even though B has the loudest
        // recovering arc in the session set. The anchoring contract
        // holds at the thin corner.
        #expect(fields.scenarioTitle == "Networking")
        #expect(fields.toneTitle == "Confident")
    }

    @Test func helperReturnsNilProgressAndNilResolvedForRoundFortySixThinJustFinishedWithParallelPriorCrossingFixture() {
        // Thin-A just-finished + parallel-prior-crossing-C — the
        // round-46 prior-crossing-elsewhere cross-surface contract
        // (`userPromptAndDeterministicNoteThinJustFinishedNeverNameParallelPriorCrossing`).
        // Scenario C (Work Update, professional) had a prior crossing
        // rep at -20 days — the "you've done it before in another
        // scenario, here's a fresh thin rep elsewhere — pivot to C's
        // old win" cold-open is the loudest dramatic temptation the
        // helper has to gate off. The helper threads scenario A only
        // through `toneDrillCrossing`, so C's old win is invisible to
        // the helper output. A future regression that pulled the
        // global "any scenario's most recent crossing" into the
        // resolved gate would silently flip `resolved` to non-nil
        // with C's title, while the surface SOLVED clause kept
        // rendering A's anchoring titles — the round-46 surface tests
        // would still pass on the not-named assertion (the resolved
        // title would shift to C but the prompt template's SOLVED
        // clause reads from `imToneDrillResolvedScenarioTitle` which
        // would also be C), so the surface tests' not-Work-Update
        // assertion would catch it — but the helper boundary catches
        // it earlier with one assertion at the source.
        let justFinished = imSession(
            scenario: .networking, targetTone: .confident,
            actualTone: "confident", daysOffset: 0
        )
        let priorCrossingC = crossingScenarioSessions(
            scenario: .workUpdate, targetTone: .professional,
            offBrandTone: "vague", onBrandTone: "professional",
            crossingRepId: UUID(), earliestDayOffset: -20
        )
        let fields = MomentumComputer.imToneDrillNoteFields(
            forJustFinished: justFinished, in: priorCrossingC + [justFinished]
        )
        // Progress trio — nil. The 4-rep floor in scenario A still
        // gates this off even though scenario C has a complete
        // 4-rep crossing trajectory in history.
        #expect(fields.progress == nil)
        // SOLVED trio — nil. The most coaching-tempting failure mode
        // (the just-finished rep's scenario has no signal but
        // another scenario has a prior win) is structurally
        // impossible at the helper boundary; the resolved gate is
        // scenario-filtered to A only.
        #expect(fields.resolved == nil)
        #expect(fields.resolvedScenarioTitle == nil)
        #expect(fields.resolvedToneTitle == nil)
        // Titles still anchor on A — Work Update / Professional
        // (scenario C / its tone) never leaks into the helper
        // output even though C is the only scenario in history
        // with a complete crossing trajectory.
        #expect(fields.scenarioTitle == "Networking")
        #expect(fields.toneTitle == "Confident")
    }
}

// MARK: - Tone-drill SOLVED win threaded into the post-rep coach note
//
// The terminal state of the loop. When the just-finished IM rep is the one
// that pushes its scenario's committed tone across the bar, the post-rep
// note headlines the win once — outranking even a personal best — then the
// branch goes quiet (the crossing is gated upstream in the finalizer, locked
// by `IMToneDrillResolvedTests`). These lock the voice-shaped copy, the
// top-of-chain priority, the honest fall-through when nothing crossed, and
// that the copy stays brand-voice-clean and forward-pointing across voices.

struct PostRepCoachNoteToneResolvedTests {

    private func resolved(
        scenario: IMConversationScenario = .difficultConversation,
        tone: IMTargetTone = .calm,
        earlierRate: Double = 0.0,
        recentRate: Double = 1.0
    ) -> IMToneDrillResolved {
        IMToneDrillResolved(
            scenario: scenario,
            targetTone: tone,
            earlierRate: earlierRate,
            recentRate: recentRate,
            evaluatedCount: 6,
            lastEvaluatedDate: Date()
        )
    }

    private func makeInput(
        voice: SpeakingStyleGoal? = nil,
        resolved: IMToneDrillResolved?,
        scenarioTitle: String? = "Difficult Conversation",
        toneTitle: String? = "Calm",
        isPersonalBest: Bool = false,
        score: Int? = 8
    ) -> PostRepCoachNoteInput {
        PostRepCoachNoteInput(
            sessionID: UUID(),
            mode: .imConversation,
            score: score,
            fillerCount: 0,
            duration: 60,
            wordCount: 120,
            voice: voice,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: nil,
            bigMomentDaysUntil: nil,
            isPersonalBest: isPersonalBest,
            totalSessionCount: 8,
            imToneDrillResolved: resolved,
            imToneDrillResolvedScenarioTitle: resolved == nil ? nil : scenarioTitle,
            imToneDrillResolvedToneTitle: resolved == nil ? nil : toneTitle
        )
    }

    @Test func resolvedWinHeadlinesTheNoteWithoutClaimingMastery() {
        let note = PostRepCoachNoteService.deterministicNote(input: makeInput(resolved: resolved()))
        let lower = note.noteText.lowercased()
        #expect(lower.contains("difficult conversation"))
        #expect(lower.contains("calm"))
        #expect(note.noteText.contains("0%") && note.noteText.contains("100%"))
        #expect(lower.contains("holding"))
        #expect(!note.noteText.contains("!"))
    }

    @Test func resolvedWinOutranksPersonalBest() {
        // The crossing rep can also be a personal best. The solved win is the
        // rarer, more coaching-significant signal, so it must headline — the
        // note names the closed tone gap, not the score milestone.
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(voice: .authoritative, resolved: resolved(), isPersonalBest: true)
        )
        #expect(note.noteText.lowercased().contains("difficult conversation"))
        #expect(!note.noteText.lowercased().contains("personal best"))
    }

    @Test func noResolvedWinFallsThroughToMetricNote() {
        // No crossing this rep → the branch never fires and the scenario name
        // does not appear (a personal best headlines instead here).
        let note = PostRepCoachNoteService.deterministicNote(
            input: makeInput(resolved: nil, isPersonalBest: true)
        )
        #expect(!note.noteText.contains("Difficult Conversation"))
    }

    @Test func resolvedSentenceIsVoiceShapedAndCleanAcrossAllVoices() {
        let voices: [SpeakingStyleGoal?] = [
            .authoritative, .warm, .concise, .persuasive, .executive, .storytelling, nil
        ]
        let win = resolved(earlierRate: 0.0, recentRate: 0.8)
        for voice in voices {
            let persona = CoachPersona.persona(for: voice)
            let sentence = PostRepCoachNoteService.imToneResolvedSentence(
                resolved: win, scenario: "Difficult Conversation", tone: "Calm", persona: persona
            )
            #expect(sentence.contains("0%") && sentence.contains("80%"))
            #expect(!sentence.contains("!"))
            #expect(!sentence.lowercased().hasPrefix("let's"))
            // Stays inside the per-rep note's character budget so lead +
            // closing can wrap it without truncating the percentages.
            #expect(sentence.count <= 150)
            #expect(PostRepCoachNoteService.passesBrandVoiceContract(sentence))
        }
    }
}

// MARK: - IMScenarioDetailView relational trend (trust/tension chips)
//
// The scenario header's two trend chips ("Trust ↑" / "Tension ↓") read
// from `IMHistorySummary.relationalTrend`, which compares the earliest
// vs latest window of the per-scenario trace. The view maps the raw
// `Movement` to good/bad coloring; these tests lock the math + the
// honest-data contracts (nil below 4 reps, non-overlapping windows,
// flat below the 0.5 threshold).

struct IMScenarioRelationalTrendTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        trust: Int,
        tension: Int,
        daysOffset: Double,
        hasFinalState: Bool = true
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: .confident),
                turns: [],
                actualTone: nil,
                finalState: hasFinalState
                    ? IMConversationState(trust: trust, engagement: 6, tension: tension, beat: "x")
                    : nil,
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func relationalTrendNilOnEmptyInput() {
        #expect(IMHistorySummary.relationalTrend(from: [], scenario: .networking) == nil)
    }

    @Test func relationalTrendNilBelowFourReps() {
        // Three reps can't separate a "first stretch" from a "recent
        // stretch" — the helper returns nil rather than fabricate a read.
        let sessions = [
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -3),
            imSession(scenario: .networking, trust: 5, tension: 6, daysOffset: -2),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -1)
        ]
        #expect(IMHistorySummary.relationalTrend(from: sessions, scenario: .networking) == nil)
    }

    @Test func relationalTrendDetectsImprovement() {
        // Oldest three: low trust, high tension. Newest three: high
        // trust, low tension. → trust up, tension down (the good arc).
        let sessions = [
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -6),
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -5),
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -4),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -3),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -2),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -1)
        ]
        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .networking)
        #expect(trend?.trust == .up)
        #expect(trend?.tension == .down)
        #expect(trend?.trustDelta == 5.0)
        #expect(trend?.tensionDelta == -5.0)
        #expect(trend?.windowSize == 3)
        #expect(trend?.hasSignal == true)
    }

    @Test func relationalTrendDetectsRegression() {
        // Reverse arc: trust falling, tension rising.
        let sessions = [
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -6),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -5),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -4),
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -3),
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -2),
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -1)
        ]
        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .networking)
        #expect(trend?.trust == .down)
        #expect(trend?.tension == .up)
        #expect(trend?.hasSignal == true)
    }

    @Test func relationalTrendFlatWhenStable() {
        // Four reps, no movement → both flat, hasSignal false. The
        // helper still returns a (non-nil) struct: there's enough data,
        // there's just no trend to show, so the header chips self-hide.
        let sessions = [
            imSession(scenario: .networking, trust: 6, tension: 5, daysOffset: -4),
            imSession(scenario: .networking, trust: 6, tension: 5, daysOffset: -3),
            imSession(scenario: .networking, trust: 6, tension: 5, daysOffset: -2),
            imSession(scenario: .networking, trust: 6, tension: 5, daysOffset: -1)
        ]
        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .networking)
        #expect(trend != nil)
        #expect(trend?.trust == .flat)
        #expect(trend?.tension == .flat)
        #expect(trend?.hasSignal == false)
    }

    @Test func relationalTrendFlatBelowThreshold() {
        // Six reps, trust drifts up by only 0.3 (< 0.5 threshold) →
        // flat. Earliest 3 trust = 5,5,5 (mean 5.0); latest 3 = 5,5,6
        // (mean 5.33) → delta 0.3. Tension is constant → flat.
        let sessions = [
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -6),
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -5),
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -4),
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -3),
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -2),
            imSession(scenario: .networking, trust: 6, tension: 5, daysOffset: -1)
        ]
        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .networking)
        #expect(trend?.trustDelta == 0.3)
        #expect(trend?.trust == .flat)
        #expect(trend?.tension == .flat)
        #expect(trend?.hasSignal == false)
    }

    @Test func relationalTrendWindowSizeForFourReps() {
        // Four reps → window = min(3, 4/2) = 2. Earliest 2 vs latest 2,
        // non-overlapping. Trust 4,4 → 7,7 = delta +3 (up).
        let sessions = [
            imSession(scenario: .networking, trust: 4, tension: 6, daysOffset: -4),
            imSession(scenario: .networking, trust: 4, tension: 6, daysOffset: -3),
            imSession(scenario: .networking, trust: 7, tension: 6, daysOffset: -2),
            imSession(scenario: .networking, trust: 7, tension: 6, daysOffset: -1)
        ]
        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .networking)
        #expect(trend?.windowSize == 2)
        #expect(trend?.trustDelta == 3.0)
        #expect(trend?.trust == .up)
        #expect(trend?.tension == .flat)
    }

    @Test func relationalTrendThresholdIsInclusive() {
        // Delta of exactly 0.5 reads as a trend (>= boundary). Four reps,
        // window 2: trust 5,5 → 5,6 (mean 5.0 → 5.5) = delta 0.5 → up.
        let sessions = [
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -4),
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -3),
            imSession(scenario: .networking, trust: 5, tension: 5, daysOffset: -2),
            imSession(scenario: .networking, trust: 6, tension: 5, daysOffset: -1)
        ]
        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .networking)
        #expect(trend?.trustDelta == 0.5)
        #expect(trend?.trust == .up)
    }

    @Test func relationalTrendIgnoresOtherScenariosAndModes() {
        // Inherits the trace-point filter: only the requested scenario's
        // IM reps with a final state contribute. The cross-scenario and
        // Timed rows must not bleed into the window math.
        let sessions = [
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -4),
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -3),
            imSession(scenario: .difficultConversation, trust: 9, tension: 1, daysOffset: -3),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -2),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -1),
            PracticeSession(
                transcript: "timed",
                fillerWordCount: 0,
                duration: 30,
                date: baseDate,
                mode: .timed,
                score: 9
            )
        ]
        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .networking)
        #expect(trend?.windowSize == 2)
        #expect(trend?.trust == .up)
        #expect(trend?.tension == .down)
    }

    @Test func relationalTrendDropsRepsWithoutFinalState() {
        // A rep with no final state has no trust/tension to plot, so it
        // can't contribute to the window. Four total, one stateless →
        // three contributing → nil (below the 4-rep floor).
        let sessions = [
            imSession(scenario: .networking, trust: 3, tension: 8, daysOffset: -4),
            imSession(scenario: .networking, trust: 5, tension: 6, daysOffset: -3),
            imSession(scenario: .networking, trust: 0, tension: 0, daysOffset: -2, hasFinalState: false),
            imSession(scenario: .networking, trust: 8, tension: 3, daysOffset: -1)
        ]
        #expect(IMHistorySummary.relationalTrend(from: sessions, scenario: .networking) == nil)
    }
}

// MARK: - IMHistoryBreakdownCard row — trend-chip gating contract
//
// The IM History list row now carries the trust/tension trend chips
// (the same `relationalTrend` read the scenario detail header shows) on
// a full-width chip row beneath its stats. The row itself appears for
// any scenario with ≥1 IM rep, but the trend chips must appear only
// when there is honest signal. These tests lock that two-part contract
// so the list and the detail drill-down can never disagree about when a
// trend is shown:
//   • a scenario in `breakdowns` with ≥4 trending final-state reps both
//     renders a row AND yields a non-nil trend with `hasSignal == true`
//   • a scenario in `breakdowns` with too few reps still renders a row
//     but `relationalTrend` is nil → the chip self-hides, never a
//     fabricated flat reading on a row that has data for its stats

struct IMHistoryBreakdownTrendContractTests {

    private let baseDate: Date = {
        DateComponents(calendar: .current, year: 2026, month: 5, day: 1, hour: 12).date!
    }()

    private func imSession(
        scenario: IMConversationScenario,
        trust: Int,
        tension: Int,
        daysOffset: Double
    ) -> PracticeSession {
        PracticeSession(
            transcript: "im rep",
            fillerWordCount: 0,
            duration: 30,
            date: baseDate.addingTimeInterval(daysOffset * 86400),
            mode: .imConversation,
            imConversationDetails: IMConversationDetails(
                setup: IMConversationSetup(scenario: scenario, targetTone: .confident),
                turns: [],
                actualTone: nil,
                finalState: IMConversationState(trust: trust, engagement: 6, tension: tension, beat: "x"),
                outcome: nil
            ),
            score: 7
        )
    }

    @Test func trendingScenarioYieldsBothRowAndSignal() {
        // Six reps, improving arc. The scenario must surface as a
        // breakdown row (so the user sees it on the list) AND carry a
        // non-flat trend (so the chip renders on that row).
        let sessions = [
            imSession(scenario: .difficultConversation, trust: 3, tension: 8, daysOffset: -6),
            imSession(scenario: .difficultConversation, trust: 3, tension: 8, daysOffset: -5),
            imSession(scenario: .difficultConversation, trust: 3, tension: 8, daysOffset: -4),
            imSession(scenario: .difficultConversation, trust: 8, tension: 3, daysOffset: -3),
            imSession(scenario: .difficultConversation, trust: 8, tension: 3, daysOffset: -2),
            imSession(scenario: .difficultConversation, trust: 8, tension: 3, daysOffset: -1)
        ]
        let breakdowns = IMHistorySummary.breakdowns(from: sessions)
        #expect(breakdowns.contains { $0.scenario == .difficultConversation })

        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .difficultConversation)
        #expect(trend?.hasSignal == true)
        #expect(trend?.trust == .up)
        #expect(trend?.tension == .down)
    }

    @Test func tooFewRepsRenderRowButHideTrendChip() {
        // Two reps: enough for a breakdown row (it has stats), but below
        // the 4-rep floor the trend helper returns nil → the row renders
        // its stats with no trend chip rather than fabricating a flat one.
        let sessions = [
            imSession(scenario: .networking, trust: 4, tension: 6, daysOffset: -2),
            imSession(scenario: .networking, trust: 7, tension: 4, daysOffset: -1)
        ]
        let breakdowns = IMHistorySummary.breakdowns(from: sessions)
        #expect(breakdowns.contains { $0.scenario == .networking })
        #expect(breakdowns.first?.runCount == 2)

        #expect(IMHistorySummary.relationalTrend(from: sessions, scenario: .networking) == nil)
    }

    @Test func stableButSufficientHistoryRowShowsNoChip() {
        // Four reps, no movement: a breakdown row exists, the trend is
        // non-nil but `hasSignal` is false → the chip row self-hides on
        // this scenario. Locks that "enough data, no trend" reads as
        // no-chip, the same contract the detail header self-hide uses.
        let sessions = [
            imSession(scenario: .workUpdate, trust: 6, tension: 5, daysOffset: -4),
            imSession(scenario: .workUpdate, trust: 6, tension: 5, daysOffset: -3),
            imSession(scenario: .workUpdate, trust: 6, tension: 5, daysOffset: -2),
            imSession(scenario: .workUpdate, trust: 6, tension: 5, daysOffset: -1)
        ]
        let breakdowns = IMHistorySummary.breakdowns(from: sessions)
        #expect(breakdowns.contains { $0.scenario == .workUpdate })

        let trend = IMHistorySummary.relationalTrend(from: sessions, scenario: .workUpdate)
        #expect(trend != nil)
        #expect(trend?.hasSignal == false)
    }
}

// MARK: - SuddenDeathGamePointsTests

@Suite("Sudden Death Game Points")
struct SuddenDeathGamePointsTests {

    private func makeResult(
        roundsSurvived: Int,
        totalFillers: Int = 0,
        totalWords: Int = 50,
        wordCountsByRound: [Int]? = nil,
        finalOutcome: RoundOutcome = .fillerOverload,
        pitchMetrics: PitchMetrics? = nil,
        wordChoiceMetrics: WordChoiceMetrics? = nil,
        eloquenceFindings: [EloquenceFinding] = [],
        sessionWPM: Double = 0
    ) -> PressureSessionResult {
        let outcomes: [RoundOutcome] = {
            var arr = Array(repeating: RoundOutcome.survived, count: roundsSurvived)
            if finalOutcome.isFailed { arr.append(finalOutcome) }
            return arr
        }()
        let words = wordCountsByRound ?? Array(repeating: 15, count: roundsSurvived)
        let minimums = Array(repeating: 10, count: outcomes.count)
        var result = PressureSessionResult(
            roundsSurvived: roundsSurvived,
            finalOutcome: finalOutcome,
            roundOutcomes: outcomes,
            totalDuration: Double(roundsSurvived) * 20,
            totalFillers: totalFillers,
            totalWords: totalWords,
            bestRoundWords: words.max() ?? 0,
            personalBest: 0,
            difficulty: .medium,
            wordCountsByRound: words,
            minimumWordsByRound: minimums
        )
        result.pitchMetrics = pitchMetrics
        result.wordChoiceMetrics = wordChoiceMetrics
        result.eloquenceFindings = eloquenceFindings
        result.sessionWPM = sessionWPM
        return result
    }

    // MARK: Base points (tiered)

    @Test func zeroRoundsGivesZeroPoints() {
        let result = makeResult(roundsSurvived: 0)
        #expect(result.gamePoints == 0)
    }

    @Test func warmUpTierBaseIs100PerRound() {
        // Rounds 1–3 are 100 pts each.
        let result = makeResult(roundsSurvived: 3, totalFillers: 1, wordCountsByRound: [10, 10, 10])
        // Base = 300, no content bonuses (words < 20). Minimal multipliers.
        #expect(result.gamePoints >= 300)
    }

    @Test func mediumTierBaseIs150PerRound() {
        // Rounds 4–6 award 150 pts each. 4 rounds: 3×100 + 1×150 = 450 base.
        let result = makeResult(roundsSurvived: 4, totalFillers: 1, wordCountsByRound: [10, 10, 10, 10])
        #expect(result.gamePoints >= 450)
    }

    @Test func hardTierBaseIs200PerRound() {
        // Rounds 7+ award 200 pts each. 7 rounds: 3×100 + 3×150 + 1×200 = 950 base.
        let result = makeResult(roundsSurvived: 7, totalFillers: 1, wordCountsByRound: [10, 10, 10, 10, 10, 10, 10])
        #expect(result.gamePoints >= 950)
    }

    @Test func tieredBasePointsStaticMethod() {
        #expect(PressureRoundConfig.basePoints(for: 1) == 100)
        #expect(PressureRoundConfig.basePoints(for: 3) == 100)
        #expect(PressureRoundConfig.basePoints(for: 4) == 150)
        #expect(PressureRoundConfig.basePoints(for: 6) == 150)
        #expect(PressureRoundConfig.basePoints(for: 7) == 200)
        #expect(PressureRoundConfig.basePoints(for: 10) == 200)
    }

    // MARK: Clean multiplier

    @Test func cleanRunApplies1_5xMultiplier() {
        let clean = makeResult(roundsSurvived: 2, totalFillers: 0, wordCountsByRound: [15, 15])
        let dirty = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15])
        #expect(clean.gamePoints > dirty.gamePoints)
        let mults = clean.computedMultipliers.map(\.label)
        #expect(mults.contains("Clean"))
    }

    @Test func cleanMultiplierValueIs1_5() {
        let result = makeResult(roundsSurvived: 1, totalFillers: 0, wordCountsByRound: [15])
        let cleanMult = result.computedMultipliers.first { $0.label == "Clean" }
        #expect(cleanMult != nil)
        #expect(cleanMult?.value == 1.5)
    }

    // MARK: Depth multiplier

    @Test func deepRunAt5RoundsApplies1_3x() {
        let result = makeResult(roundsSurvived: 5, totalFillers: 1, wordCountsByRound: [15, 15, 15, 15, 15])
        let mults = result.computedMultipliers.map(\.label)
        #expect(mults.contains("Deep"))
        let deepMult = result.computedMultipliers.first { $0.label == "Deep" }
        #expect(deepMult?.value == 1.3)
    }

    @Test func marathonAt8RoundsReplacesDeep() {
        let result = makeResult(roundsSurvived: 8, totalFillers: 1, wordCountsByRound: Array(repeating: 15, count: 8))
        let labels = result.computedMultipliers.map(\.label)
        #expect(labels.contains("Marathon"))
        #expect(!labels.contains("Deep"))
    }

    @Test func marathonMultiplierValueIs1_6() {
        let result = makeResult(roundsSurvived: 8, totalFillers: 1, wordCountsByRound: Array(repeating: 15, count: 8))
        let marathonMult = result.computedMultipliers.first { $0.label == "Marathon" }
        #expect(marathonMult?.value == 1.6)
    }

    // MARK: Developed-response multiplier

    @Test func developedRequires3RoundsWith20PlusWords() {
        let developed = makeResult(roundsSurvived: 4, totalFillers: 1, wordCountsByRound: [25, 22, 21, 10])
        let labels = developed.computedMultipliers.map(\.label)
        #expect(labels.contains("Developed"))

        let notDeveloped = makeResult(roundsSurvived: 4, totalFillers: 1, wordCountsByRound: [25, 22, 10, 10])
        let labels2 = notDeveloped.computedMultipliers.map(\.label)
        #expect(!labels2.contains("Developed"))
    }

    // MARK: Content bonus

    @Test func contentBonusAdds50PerDevelopedRound() {
        let developed = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [25, 25])
        let brief = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [10, 10])
        #expect(developed.gamePoints > brief.gamePoints)
        #expect(developed.gamePoints - brief.gamePoints >= 100)
    }

    // MARK: Follow-up bonus

    @Test func followUpBonusAppliesForFollowUpRounds() {
        let result = makeResult(roundsSurvived: 3, totalFillers: 1, wordCountsByRound: [15, 15, 15])
        let config2 = PressureRoundConfig.config(for: 2, difficulty: .medium)
        let config3 = PressureRoundConfig.config(for: 3, difficulty: .medium)
        let expectedFollowUps = (config2.isFollowUp ? 1 : 0) + (config3.isFollowUp ? 1 : 0)
        #expect(expectedFollowUps > 0)
        #expect(result.gamePoints > 300)
    }

    // MARK: Multiplier stacking

    @Test func allMultipliersStackForCleanDeepDevelopedRun() {
        // Tiered base: 3×100 + 2×150 = 600. All 5 rounds ≥ 20 words → 5×50 = 250 content bonus.
        // Survival multipliers: Clean ×1.5, Deep ×1.3, Developed ×1.2.
        let result = makeResult(roundsSurvived: 5, totalFillers: 0, wordCountsByRound: [25, 22, 21, 25, 20])
        let labels = Set(result.computedMultipliers.map(\.label))
        #expect(labels.contains("Clean"))
        #expect(labels.contains("Deep"))
        #expect(labels.contains("Developed"))
        // 600 base + 250 content + follow-up bonuses, times stacked multipliers.
        #expect(result.gamePoints > Int(Double(600) * 1.5 * 1.3))
    }

    // MARK: Label formatting

    @Test func multiplierLabelsFormatCorrectly() {
        let result = makeResult(roundsSurvived: 5, totalFillers: 0, wordCountsByRound: [15, 15, 15, 15, 15])
        let labels = result.multiplierLabels
        #expect(labels.contains("×1.5 Clean"))
        #expect(labels.contains("×1.3 Deep"))
    }

    // MARK: Legacy record compat

    @Test func legacyRunRecordDefaultsToZeroGamePoints() {
        let record = SuddenDeathRunRecord(
            difficulty: .medium,
            roundsSurvived: 3,
            totalFillers: 0,
            totalWords: 50,
            score: 5,
            xpEarned: 100,
            finalOutcome: .fillerOverload,
            wasNewBestAtTime: false
        )
        #expect(record.gamePoints == 0)
        #expect(record.activeMultipliers.isEmpty)
    }

    // MARK: Points high score store

    @Test func bestPointsStartsAtZero() {
        let store = SuddenDeathHighScoreStore.shared
        let current = store.bestPoints()
        #expect(current >= 0)
    }

    // MARK: Quality multipliers — Vocal Variety

    @Test func vocalVarietyAppliesWhenPitchIsVaried() {
        // monotoneScore < 0.35 with reliable pitch → ×1.15
        let pitch = PitchMetrics(meanHz: 180, stdHz: 40, voicedRatio: 0.6, windowCount: 20)
        #expect(pitch.isReliable)
        #expect(pitch.monotoneScore < 0.35)
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], pitchMetrics: pitch)
        let labels = result.computedMultipliers.map(\.label)
        #expect(labels.contains("Vocal Variety"))
        let mult = result.computedMultipliers.first { $0.label == "Vocal Variety" }
        #expect(mult?.value == 1.15)
    }

    @Test func vocalVarietySkippedWhenMonotone() {
        // monotoneScore >= 0.35 → no Vocal Variety multiplier
        let pitch = PitchMetrics(meanHz: 180, stdHz: 10, voicedRatio: 0.6, windowCount: 20)
        #expect(pitch.isReliable)
        #expect(pitch.monotoneScore >= 0.35)
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], pitchMetrics: pitch)
        let labels = result.computedMultipliers.map(\.label)
        #expect(!labels.contains("Vocal Variety"))
    }

    @Test func vocalVarietySkippedWhenUnreliable() {
        // Not enough windows → isReliable == false
        let pitch = PitchMetrics(meanHz: 180, stdHz: 40, voicedRatio: 0.6, windowCount: 3)
        #expect(!pitch.isReliable)
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], pitchMetrics: pitch)
        let labels = result.computedMultipliers.map(\.label)
        #expect(!labels.contains("Vocal Variety"))
    }

    // MARK: Quality multipliers — Pace Control

    @Test func paceControlAppliesInIdealRange() {
        // WPM inside the shared conversational band with ≥ 30 words → ×1.10
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, totalWords: 40, wordCountsByRound: [20, 20], sessionWPM: 130)
        let labels = result.computedMultipliers.map(\.label)
        #expect(labels.contains("Pace Control"))
        let mult = result.computedMultipliers.first { $0.label == "Pace Control" }
        #expect(mult?.value == 1.10)
    }

    @Test func paceControlSkippedWhenTooFast() {
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, totalWords: 40, wordCountsByRound: [20, 20], sessionWPM: 170)
        let labels = result.computedMultipliers.map(\.label)
        #expect(!labels.contains("Pace Control"))
    }

    @Test func paceControlSkippedWhenTooFewWords() {
        // < 30 total words → not enough data
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, totalWords: 20, wordCountsByRound: [10, 10], sessionWPM: 130)
        let labels = result.computedMultipliers.map(\.label)
        #expect(!labels.contains("Pace Control"))
    }

    // MARK: Quality multipliers — Word Choice

    @Test func wordChoiceAppliesWithHighUniqueRatio() {
        let wc = WordChoiceMetrics(uniqueRatio: 0.70, repeatedContentWords: [], contentWordCount: 25)
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], wordChoiceMetrics: wc)
        let labels = result.computedMultipliers.map(\.label)
        #expect(labels.contains("Word Choice"))
        let mult = result.computedMultipliers.first { $0.label == "Word Choice" }
        #expect(mult?.value == 1.10)
    }

    @Test func wordChoiceSkippedBelowMinContentWords() {
        let wc = WordChoiceMetrics(uniqueRatio: 0.70, repeatedContentWords: [], contentWordCount: 10)
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], wordChoiceMetrics: wc)
        let labels = result.computedMultipliers.map(\.label)
        #expect(!labels.contains("Word Choice"))
    }

    @Test func wordChoiceSkippedBelowUniqueThreshold() {
        let wc = WordChoiceMetrics(uniqueRatio: 0.50, repeatedContentWords: [], contentWordCount: 25)
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], wordChoiceMetrics: wc)
        let labels = result.computedMultipliers.map(\.label)
        #expect(!labels.contains("Word Choice"))
    }

    // MARK: Quality multipliers — Rhetoric

    @Test func rhetoricAppliesWithAnyFinding() {
        let finding = EloquenceFinding(device: .tricolon, snippet: "life, liberty, and pursuit", coachLine: "Nice tricolon")
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], eloquenceFindings: [finding])
        let labels = result.computedMultipliers.map(\.label)
        #expect(labels.contains("Rhetoric"))
        let mult = result.computedMultipliers.first { $0.label == "Rhetoric" }
        #expect(mult?.value == 1.15)
    }

    @Test func rhetoricSkippedWhenNoFindings() {
        let result = makeResult(roundsSurvived: 2, totalFillers: 1, wordCountsByRound: [15, 15], eloquenceFindings: [])
        let labels = result.computedMultipliers.map(\.label)
        #expect(!labels.contains("Rhetoric"))
    }

    // MARK: Backward compat — nil quality signals

    @Test func nilQualitySignalsProduceSameMultipliersAsBefore() {
        // No quality signals populated → only survival multipliers fire.
        let result = makeResult(roundsSurvived: 5, totalFillers: 0, wordCountsByRound: [25, 22, 21, 25, 20])
        let labels = Set(result.computedMultipliers.map(\.label))
        #expect(labels == Set(["Clean", "Deep", "Developed"]))
        #expect(!labels.contains("Vocal Variety"))
        #expect(!labels.contains("Pace Control"))
        #expect(!labels.contains("Word Choice"))
        #expect(!labels.contains("Rhetoric"))
    }

    // MARK: Quality multipliers stack with survival multipliers

    @Test func qualityMultipliersStackWithSurvivalMultipliers() {
        let pitch = PitchMetrics(meanHz: 180, stdHz: 40, voicedRatio: 0.6, windowCount: 20)
        let wc = WordChoiceMetrics(uniqueRatio: 0.70, repeatedContentWords: [], contentWordCount: 25)
        let finding = EloquenceFinding(device: .anaphora, snippet: "we will, we will", coachLine: "Anaphora")
        let result = makeResult(
            roundsSurvived: 5,
            totalFillers: 0,
            totalWords: 50,
            wordCountsByRound: [25, 22, 21, 25, 20],
            pitchMetrics: pitch,
            wordChoiceMetrics: wc,
            eloquenceFindings: [finding],
            sessionWPM: 135
        )
        let labels = Set(result.computedMultipliers.map(\.label))
        // Survival multipliers
        #expect(labels.contains("Clean"))
        #expect(labels.contains("Deep"))
        #expect(labels.contains("Developed"))
        // Quality multipliers
        #expect(labels.contains("Vocal Variety"))
        #expect(labels.contains("Pace Control"))
        #expect(labels.contains("Word Choice"))
        #expect(labels.contains("Rhetoric"))
        // Points must be significantly higher than survival-only.
        let survivalOnly = makeResult(roundsSurvived: 5, totalFillers: 0, wordCountsByRound: [25, 22, 21, 25, 20])
        #expect(result.gamePoints > survivalOnly.gamePoints)
    }
}

// MARK: - PaceTrainingEngine Tests

@Suite("Pace Training Engine")
struct PaceTrainingEngineTests {

    // MARK: Sub-mode

    @Test func subModeLabels() {
        #expect(PaceSubMode.freestyle.label == "Freestyle")
        #expect(PaceSubMode.readAlong.label == "Read Along")
    }

    @Test func subModeAllCases() {
        #expect(PaceSubMode.allCases.count == 2)
    }

    // MARK: Engine defaults

    @Test @MainActor func engineDefaultsToFreestyle() {
        let engine = PaceTrainingEngine()
        #expect(engine.subMode == .freestyle)
    }

    @Test func conversationalPaceBandIsSharedTarget() {
        #expect(ConversationalPaceBand.targetWPM == 130)
        #expect(ConversationalPaceBand.toleranceWPM == 20)
        #expect(ConversationalPaceBand.minDisplayWPM == 110)
        #expect(ConversationalPaceBand.maxDisplayWPM == 150)
        #expect(ConversationalPaceBand.displayRange == "110–150")
        #expect(ConversationalPaceBand.contains(130))
        #expect(!ConversationalPaceBand.contains(151))
    }

    @Test @MainActor func engineDefaultTargetWPM() {
        let engine = PaceTrainingEngine()
        #expect(engine.targetWPM == 130)
        #expect(engine.zoneMin == 110)
        #expect(engine.zoneMax == 150)
    }

    @Test @MainActor func engineStartsInSetupPhase() {
        let engine = PaceTrainingEngine()
        #expect(engine.phase == .setup)
    }

    @Test @MainActor func engineCustomTargetWPM() {
        let engine = PaceTrainingEngine(targetWPM: 150)
        #expect(engine.targetWPM == 150)
        #expect(engine.zoneMin == 130)
        #expect(engine.zoneMax == 170)
    }

    // MARK: Band position

    @Test @MainActor func bandPositionClampsAtBounds() {
        let engine = PaceTrainingEngine()
        // At 0 WPM → band position clamped to 0
        #expect(engine.bandPosition == 0)
    }

    // MARK: Zone label

    @Test @MainActor func zoneLabelReflectsWPM() {
        let engine = PaceTrainingEngine()
        // At 0 WPM → "Too Slow"
        #expect(engine.zoneLabel == "Too Slow")
    }

    // MARK: Reset

    @Test @MainActor func resetClearsState() {
        let engine = PaceTrainingEngine()
        engine.ingestTranscript("hello world")
        engine.reset()
        #expect(engine.totalWords == 0)
        #expect(engine.currentWPM == 0)
        #expect(engine.elapsed == 0)
        #expect(engine.phase == .setup)
