// MARK: - Sudden Death Idempotent Finalization

@Suite("SuddenDeathIdempotentFinalizationTests")
struct SuddenDeathIdempotentFinalizationTests {

    /// CoachMemoryStore.refresh should be idempotent: calling it twice
    /// with the same session data produces the same memory. The one-time
    /// guard lives in SuddenDeathPracticeView (didCommitCompletedRun),
    /// but we verify the store-level contract here: repeated refresh
    /// calls don't compound effects.
    @MainActor
    @Test func repeatedRefreshProducesSameMemory() {
        let suite = "sd-idempotent-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "sd-\(UUID().uuidString)"

        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        var baseline = CommunicationBaseline.empty
        baseline.qualifyingSessionCount = 5
        let session = PracticeSession(
            transcript: "Survived three rounds.",
            fillerWordCount: 0,
            duration: 90,
            date: Date(),
            mode: .suddenDeath,
            score: 8
        )

        let refreshArgs: () -> Void = {
            store.refresh(
                profile: profile(),
                baseline: baseline,
                sessions: [session],
                trends: [],
                forwardPlan: nil,
                lastSessionID: session.id,
                now: Date(timeIntervalSince1970: 2_000)
            )
        }

        // First refresh
        refreshArgs()
        let first = store.currentMemory

        // Second refresh (simulating Go Again → Coach Read path)
        refreshArgs()
        let second = store.currentMemory

        #expect(first == second)
        #expect(first?.evidenceCount == second?.evidenceCount)
        #expect(first?.currentLever == second?.currentLever)
    }

    /// noteReflection is additive but not compounding — calling it twice
    /// with the same clause just overwrites, not appends.
    @MainActor
    @Test func noteReflectionOverwritesDoesNotCompound() {
        let suite = "sd-reflection-overwrite-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "sd-\(UUID().uuidString)"

        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        var baseline = CommunicationBaseline.empty
        baseline.qualifyingSessionCount = 5

        store.refresh(
            profile: profile(),
            baseline: baseline,
            sessions: [PracticeSession(
                transcript: "Test.", fillerWordCount: 0,
                duration: 45, date: Date(), mode: .suddenDeath, score: 8
            )],
            trends: [],
            forwardPlan: nil,
            lastSessionID: nil,
            now: Date()
        )

        store.noteReflection("nerves got me")
        store.noteReflection("nerves got me")
        #expect(store.currentMemory?.lastReflectionSummary == "nerves got me")

        // Overwrite with different value
        store.noteReflection("felt strong")
        #expect(store.currentMemory?.lastReflectionSummary == "felt strong")
    }

    /// Adaptation log does not grow when refreshed with the same lever.
    @MainActor
    @Test func adaptationLogDoesNotGrowOnSameLeverRefresh() {
        let suite = "sd-adaptation-stable-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "sd-\(UUID().uuidString)"

        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        var baseline = CommunicationBaseline.empty
        baseline.qualifyingSessionCount = 6
        baseline.persistentBlockers = ["Filler words"]
        let trend = SkillTrend(
            skillArea: .fillerReduction,
            direction: .declining,
            confidence: .high,
            windowSize: 8,
            currentLevel: .weak
        )

        // First refresh — sets lever to fillerReduction
        store.refresh(
            profile: profile(),
            baseline: baseline,
            sessions: [PracticeSession(
                transcript: "Test.", fillerWordCount: 3,
                duration: 60, date: Date(), mode: .suddenDeath, score: 5
            )],
            trends: [trend],
            forwardPlan: nil,
            lastSessionID: nil,
            now: Date(timeIntervalSince1970: 1_000)
        )
        let logAfterFirst = store.currentMemory?.adaptationLog?.count ?? 0

        // Second refresh — same lever, same trends
        store.refresh(
            profile: profile(),
            baseline: baseline,
            sessions: [PracticeSession(
                transcript: "Test.", fillerWordCount: 3,
                duration: 60, date: Date(), mode: .suddenDeath, score: 5
            )],
            trends: [trend],
            forwardPlan: nil,
            lastSessionID: nil,
            now: Date(timeIntervalSince1970: 2_000)
        )
        let logAfterSecond = store.currentMemory?.adaptationLog?.count ?? 0

        #expect(logAfterFirst == logAfterSecond)
    }

    private func profile() -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: .concise,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: "",
            chosenStyleGoal: .concise
        )
    }
}

// MARK: - Summary "Practice Again" router

/// Locks the contract of `SummaryPracticeAgainRouter` — the pure helper
/// behind Summary's "Practice Again" CTA.
///
/// IM-mode reps re-arm the just-finished scenario + tone instead of
/// dropping the user back on the picker (the old behavior hard-coded
/// `scenario: nil, tone: nil` even though `IMConversationDetails.setup`
/// carries the exact pair). The other modes have no per-rep setup, so the
/// router must ignore any IM setup passed alongside them — these tests
/// pin that the cross-pollination can't happen.
@MainActor
struct SummaryPracticeAgainRouterTests {

    @Test func imRepReArmsScenarioAndTone() {
        let setup = IMConversationSetup(
            scenario: .difficultConversation,
            targetTone: .calm
        )
        let destination = SummaryPracticeAgainRouter.destination(
            for: .imConversation,
            imSetup: setup
        )
        #expect(destination == .imPractice(
            scenario: .difficultConversation,
            tone: .calm
        ))
    }

    @Test func imRepWithoutSetupFallsBackToPicker() {
        let destination = SummaryPracticeAgainRouter.destination(
            for: .imConversation,
            imSetup: nil
        )
        #expect(destination == .imPractice(scenario: nil, tone: nil))
    }

    @Test func timedIgnoresImSetup() {
        let setup = IMConversationSetup(
            scenario: .workUpdate,
            targetTone: .confident
        )
        #expect(SummaryPracticeAgainRouter.destination(
            for: .timed,
            imSetup: setup
        ) == .timedPractice)
        #expect(SummaryPracticeAgainRouter.destination(
            for: .timed,
            imSetup: nil
        ) == .timedPractice)
    }

    @Test func suddenDeathIgnoresImSetup() {
        let setup = IMConversationSetup(
            scenario: .networking,
            targetTone: .warm
        )
        #expect(SummaryPracticeAgainRouter.destination(
            for: .suddenDeath,
            imSetup: setup
        ) == .suddenDeathPractice)
        #expect(SummaryPracticeAgainRouter.destination(
            for: .suddenDeath,
            imSetup: nil
        ) == .suddenDeathPractice)
    }

    @Test func ahCounterIgnoresImSetup() {
        let setup = IMConversationSetup(
            scenario: .socialCatchUp,
            targetTone: .confident
        )
        #expect(SummaryPracticeAgainRouter.destination(
            for: .ahCounter,
            imSetup: setup
        ) == .ahCounterPractice)
        #expect(SummaryPracticeAgainRouter.destination(
            for: .ahCounter,
            imSetup: nil
        ) == .ahCounterPractice)
    }
}

// MARK: - Summary "Looking ahead" router

/// Locks the contract of `SummaryLookingAheadRouter` — the pure helper
/// behind the post-rep "Looking ahead" recommendation launch.
///
/// The blueprint already carries the recommended scenario + tone for IM
/// reps (the tone-drill signal threads them when the user is missing the
/// same scenario/tone repeatedly), so a one-tap launch from the
/// recommendation card lands the user directly inside that scenario
/// instead of dropping back on the picker. The non-IM modes ignore the
/// scenario/tone fields entirely. When IM is the recommendation but the
/// device has IM Mode unconfigured (`imAvailable == false`), the router
/// falls back to `.timedPractice` so the recommendation never sends the
/// user to a surface that can't run — mirroring `HomeCoachCard`'s
/// existing fallback. These tests pin every branch.
@MainActor
struct SummaryLookingAheadRouterTests {

    /// Helper that fills the non-routing fields of a blueprint with neutral
    /// placeholders. The router only reads `recommendedMode`,
    /// `recommendedScenario`, and `recommendedTone`; the copy / theme /
    /// difficulty fields are irrelevant to destination selection but are
    /// required by the struct's memberwise init.
    private func blueprint(
        mode: PracticeMode,
        scenario: IMConversationScenario? = nil,
        tone: IMTargetTone? = nil
    ) -> RecommendationBiasBlueprint {
        RecommendationBiasBlueprint(
            recommendedMode: mode,
            recommendedTone: tone,
            recommendedScenario: scenario,
            focus: "",
            target: "",
            modeBenefit: "",
            whyMode: "",
            whyNow: "",
            suggestedTimedDifficulty: nil,
            suggestedTheme: .all
        )
    }

    @Test func imRecommendationLaunchesScenarioAndTone() {
        let plan = blueprint(
            mode: .imConversation,
            scenario: .difficultConversation,
            tone: .calm
        )
        let destination = SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: true,
            modeAvailability: .allAvailable
        )
        #expect(destination == .imPractice(
            scenario: .difficultConversation,
            tone: .calm
        ))
    }

    @Test func imRecommendationWithoutPairFallsBackToPicker() {
        // Goal-biased IM recommendation with no specific tone-drill
        // signal — scenario/tone are nil. The router still routes to the
        // IM picker (the safe default) rather than substituting Timed.
        let plan = blueprint(mode: .imConversation)
        let destination = SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: true,
            modeAvailability: .allAvailable
        )
        #expect(destination == .imPractice(scenario: nil, tone: nil))
    }

    @Test func imRecommendationFallsBackToTimedWhenImUnavailable() {
        // IM is the recommendation but the device has IM Mode
        // unconfigured (no AI provider, no backend) — sending the user
        // into IM would just bounce them at IMPracticeView's guard, so
        // route to Timed instead. Mirrors `HomeCoachCard.destination()`.
        let plan = blueprint(
            mode: .imConversation,
            scenario: .networking,
            tone: .warm
        )
        let destination = SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: false,
            modeAvailability: .allAvailable
        )
        #expect(destination == .timedPractice)
    }

    @Test func timedIgnoresImFields() {
        let plan = blueprint(
            mode: .timed,
            scenario: .workUpdate,
            tone: .confident
        )
        #expect(SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: true
        ) == .timedPractice)
        #expect(SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: false
        ) == .timedPractice)
    }

    @Test func suddenDeathIgnoresImFields() {
        let plan = blueprint(
            mode: .suddenDeath,
            scenario: .networking,
            tone: .warm
        )
        #expect(SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: true,
            modeAvailability: .allAvailable
        ) == .suddenDeathPractice)
        #expect(SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: false,
            modeAvailability: .allAvailable
        ) == .suddenDeathPractice)
    }

    @Test func ahCounterIgnoresImFields() {
        let plan = blueprint(
            mode: .ahCounter,
            scenario: .socialCatchUp,
            tone: .confident
        )
        #expect(SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: true
        ) == .ahCounterPractice)
        #expect(SummaryLookingAheadRouter.destination(
            for: plan,
            imAvailable: false
        ) == .ahCounterPractice)
    }

    @Test func omittedCapabilitySnapshotFailsClosedForGatedModes() {
        #expect(SummaryLookingAheadRouter.destination(
            for: blueprint(mode: .suddenDeath),
            imAvailable: true
        ) == .timedPractice)
        #expect(SummaryLookingAheadRouter.destination(
            for: blueprint(mode: .imConversation),
            imAvailable: true
        ) == .timedPractice)
    }

    @Test func fourModeCapabilityMatrixRoutesAndAcceptsOnlyAvailableModes() {
        let modes: [PracticeMode] = [.timed, .suddenDeath, .ahCounter, .imConversation]
        for suddenDeathAvailable in [false, true] {
            for imConversationAvailable in [false, true] {
                let availability = NextActionModeAvailability(
                    suddenDeathAvailable: suddenDeathAvailable,
                    imConversationAvailable: imConversationAvailable
                )
                for imLive in [false, true] {
                    for mode in modes {
                        let launch = PracticeModeLaunchProjection.resolve(
                            displayedMode: mode,
                            scenario: .difficultConversation,
                            tone: .calm,
                            imAvailable: imLive,
                            modeAvailability: availability
                        )
                        let shouldLaunchDisplayedMode: Bool
                        switch mode {
                        case .timed, .ahCounter:
                            shouldLaunchDisplayedMode = true
                        case .suddenDeath:
                            shouldLaunchDisplayedMode = suddenDeathAvailable
                        case .imConversation:
                            shouldLaunchDisplayedMode = imConversationAvailable && imLive
                        }

                        #expect(launch.acceptsDisplayedPrescription == shouldLaunchDisplayedMode)
                        #expect(launch.launchedMode == (shouldLaunchDisplayedMode ? mode : .timed))
                        if !shouldLaunchDisplayedMode {
                            #expect(launch.destination == .timedPractice)
                        } else {
                            switch mode {
                            case .timed:
                                #expect(launch.destination == .timedPractice)
                            case .suddenDeath:
                                #expect(launch.destination == .suddenDeathPractice)
                            case .ahCounter:
                                #expect(launch.destination == .ahCounterPractice)
                            case .imConversation:
                                #expect(launch.destination == .imPractice(
                                    scenario: .difficultConversation,
                                    tone: .calm
                                ))
                            }
                        }
                    }
                }
            }
        }
    }

    // MARK: - Lower-level overload

    // The `destination(for:scenario:tone:imAvailable:)` overload is the
    // form the Summary prescription uses after projecting a finalized
    // recommendation. Behavior must be identical to the
    // blueprint form (the blueprint form delegates straight through to
    // this one), so these tests pin the same set of branches *and*
    // confirm parity for the cases that matter.

    @Test func lowerLevelImLaunchesScenarioAndTone() {
        let destination = SummaryLookingAheadRouter.destination(
            for: .imConversation,
            scenario: .difficultConversation,
            tone: .calm,
            imAvailable: true,
            modeAvailability: .allAvailable
        )
        #expect(destination == .imPractice(
            scenario: .difficultConversation,
            tone: .calm
        ))
    }

    @Test func lowerLevelImWithoutPairFallsBackToPicker() {
        // Mirrors the goal-biased IM recommendation: scenario/tone are
        // nil, but the user *did* ask for IM Mode, so route to the
        // picker (the safe default) rather than substituting Timed.
        let destination = SummaryLookingAheadRouter.destination(
            for: .imConversation,
            scenario: nil,
            tone: nil,
            imAvailable: true,
            modeAvailability: .allAvailable
        )
        #expect(destination == .imPractice(scenario: nil, tone: nil))
    }

    @Test func lowerLevelImFallsBackToTimedWhenImUnavailable() {
        // IM was the recommendation but the device has IM Mode
        // unconfigured — same fallback as the blueprint form, so the
        // Home and Summary produce the same safe destination for the same
        // recommendation shape.
        let destination = SummaryLookingAheadRouter.destination(
            for: .imConversation,
            scenario: .networking,
            tone: .warm,
            imAvailable: false,
            modeAvailability: .allAvailable
        )
        #expect(destination == .timedPractice)
    }

    @Test func lowerLevelTimedIgnoresImFields() {
        #expect(SummaryLookingAheadRouter.destination(
            for: .timed,
            scenario: .workUpdate,
            tone: .confident,
            imAvailable: true
        ) == .timedPractice)
        #expect(SummaryLookingAheadRouter.destination(
            for: .timed,
            scenario: .workUpdate,
            tone: .confident,
            imAvailable: false
        ) == .timedPractice)
    }

    @Test func lowerLevelSuddenDeathIgnoresImFields() {
        #expect(SummaryLookingAheadRouter.destination(
            for: .suddenDeath,
            scenario: .networking,
            tone: .warm,
            imAvailable: true,
            modeAvailability: .allAvailable
        ) == .suddenDeathPractice)
        #expect(SummaryLookingAheadRouter.destination(
            for: .suddenDeath,
            scenario: .networking,
            tone: .warm,
            imAvailable: false,
            modeAvailability: .allAvailable
        ) == .suddenDeathPractice)
    }

    @Test func lowerLevelAhCounterIgnoresImFields() {
        #expect(SummaryLookingAheadRouter.destination(
            for: .ahCounter,
            scenario: .socialCatchUp,
            tone: .confident,
            imAvailable: true
        ) == .ahCounterPractice)
        #expect(SummaryLookingAheadRouter.destination(
            for: .ahCounter,
            scenario: .socialCatchUp,
            tone: .confident,
            imAvailable: false
        ) == .ahCounterPractice)
    }

    @Test func blueprintAndLowerLevelOverloadsAgree() {
        // Parity check: for every combination of mode × availability ×
        // scenario/tone presence, the two overloads must return the
        // same destination. If they ever diverge, Home's blueprint route and
        // Summary's projected route would launch different reps for the same
        // recommendation.
        let modes: [PracticeMode] = [.timed, .suddenDeath, .ahCounter, .imConversation]
        let pairs: [(IMConversationScenario?, IMTargetTone?)] = [
            (nil, nil),
            (.difficultConversation, .calm),
            (.networking, .warm),
            (.workUpdate, .confident)
        ]
        for mode in modes {
            for (scenario, tone) in pairs {
                for imAvailable in [true, false] {
                    let plan = blueprint(mode: mode, scenario: scenario, tone: tone)
                    let viaBlueprint = SummaryLookingAheadRouter.destination(
                        for: plan,
                        imAvailable: imAvailable,
                        modeAvailability: .allAvailable
                    )
                    let viaLowerLevel = SummaryLookingAheadRouter.destination(
                        for: mode,
                        scenario: scenario,
                        tone: tone,
                        imAvailable: imAvailable,
                        modeAvailability: .allAvailable
                    )
                    #expect(viaBlueprint == viaLowerLevel)
                }
            }
        }
    }
}

// MARK: - LookingAheadCard launch CTA (round 19)
//
// The post-rep "Looking ahead" card uses the same router as Home's rendered
// coach prescription (`SummaryLookingAheadRouter`). The card grows an additive
// `onStart` closure: when wired by the owning view, a subordinate
// text-link CTA renders so the user can launch the recommended next mode
// in one tap from the bottom of the Session Details disclosure.
//
// The destination contract itself is already locked by
// `SummaryLookingAheadRouterTests` above — these tests pin the *opt-in*
// surface: the default-nil closure (so the existing voice-alignment
// tests + every other LookingAheadCard call site stay byte-for-byte
// unchanged), the predicate the body uses to gate CTA rendering, and
// the per-mode label copy ("Start Timed" / "Start Pressure Drill" / etc.)
// so a future PracticeMode rename can never silently break the CTA
// label without a failing test.

@MainActor
struct LookingAheadCardStartCTAContractTests {

    private func hint(mode: PracticeMode) -> LookingAheadCard.Hint {
        LookingAheadCard.Hint(
            mode: mode,
            whyMode: "Test mode benefit.",
            whyNow: "Test why now."
        )
    }

    @Test func defaultInitOmitsStartCallbackForBackCompat() {
        // The legacy call site — `LookingAheadCard(hint:)` — must keep
        // working without the round-19 opt-in. The existing voice-
        // alignment tests construct the card with hint-only; if the
        // closure parameter weren't defaulted, those tests would fail
        // to compile. This test pins the default behavior explicitly
        // (the predicate that the body's `if let onStart` branch reads
        // is false → the subordinate CTA stays hidden), so a future
        // refactor that drops the default surfaces here.
        let card = LookingAheadCard(hint: hint(mode: .timed))
        #expect(!card.shouldShowStartCTA, "Default card must not render the CTA.")
    }

    @Test func wiringCallbackEnablesCTARender() {
        // When the owning view passes a closure, the body's gate flips
        // to true so the subordinate CTA shows. The predicate is what
        // the `if let onStart` branch in the body reads — this locks
        // the contract independently of SwiftUI rendering.
        let card = LookingAheadCard(hint: hint(mode: .timed), onStart: {})
        #expect(card.shouldShowStartCTA)
    }

    @Test func startCTALabelMatchesModeDisplayLabel() {
        // The CTA copy mirrors the mode's canonical display label so a
        // future rename of `PracticeMode.displayLabel` propagates to
        // the CTA without a manual sync.
        for mode in [PracticeMode.timed, .suddenDeath, .ahCounter, .imConversation] {
            let card = LookingAheadCard(hint: hint(mode: mode))
            #expect(card.startCTALabel == "Start \(mode.displayLabel)")
        }
    }

    @Test func startCTALabelHasNoUrgencyOrFanfare() {
        // Brand-voice contract — the post-rep card is a quiet "and when
        // you come back, this is where you should go" follow-on, not a
        // celebration. No exclamations, no urgency framing, no "let's"
        // pep-talk verbs. Locked across every mode so a future copy
        // tweak can't sneak fanfare onto one mode without a failing
        // test.
        for mode in [PracticeMode.timed, .suddenDeath, .ahCounter, .imConversation] {
            let label = LookingAheadCard(hint: hint(mode: mode)).startCTALabel
            #expect(!label.contains("!"), "CTA must not exclaim — got \(label)")
            #expect(!label.lowercased().contains("let's"), "CTA must not pep-talk — got \(label)")
            #expect(!label.lowercased().contains("now"), "CTA must not urgency-frame — got \(label)")
            #expect(!label.lowercased().contains("hurry"), "CTA must not urgency-frame — got \(label)")
        }
    }

    @Test func callbackInvokesOnTap() {
        // The closure shape (`() -> Void`) is what the owning view
        // passes — when tapped, the card fires it without arguments.
        // This pins the closure signature so a refactor that adds an
        // argument (e.g. routing the destination through the closure
        // instead of computing it inside the view body) is caught.
        var fired = false
        let card = LookingAheadCard(hint: hint(mode: .timed), onStart: { fired = true })
        card.onStart?()
        #expect(fired, "Wired closure must fire on tap.")
    }

    @Test func ctaShowsAcrossEveryMode() {
        // Sanity check that the gate predicate is mode-agnostic — the
        // closure-based gate must light up for every mode so the
        // post-rep launch surface stays available regardless of which
        // mode the engine recommends.
        for mode in [PracticeMode.timed, .suddenDeath, .ahCounter, .imConversation] {
            let card = LookingAheadCard(hint: hint(mode: mode), onStart: {})
            #expect(card.shouldShowStartCTA, "CTA gate must fire for \(mode).")
        }
    }
}

// MARK: - HeroScoreCard SOLVED ribbon (round 20)
//
// Round 20 surfaces the IM tone-drill SOLVED win on the post-rep hero
// score card itself, not only inside the coach note. The crossing
// detection — "is THIS the rep that pushed the scenario over the bar?" —
// stays in `SummaryView` next to the same store + scenario derivation the
// post-rep coach-note finalizer uses, so the SOLVED ribbon on the hero
// and the SOLVED-headlined sentence in the note light up on the *same*
// rep and never double-celebrate. The card stays pure presentation: it
// takes a string pair (scenario title + tone title) and renders a quiet
// mode-tinted capsule between the score ring and the headline.
//
// These tests pin the *opt-in* surface — the default-nil ribbon (so
// every existing HeroScoreCard call site stays byte-for-byte unchanged),
// the predicate the body uses to gate ribbon rendering, the per-scenario
// / per-tone label copy shape, and the brand-voice contract (no
// exclamations, no fanfare). The crossing-detection logic itself is
// already locked by `IMToneDrillResolvedTests` (per-scenario primitive +
// crossing comparison) above — these tests do not re-verify that
// computation, only the surface-rendering contract.

@MainActor
struct HeroScoreCardToneDrillRibbonContractTests {

    @Test func defaultInitOmitsRibbonForBackCompat() {
        // The legacy call site — `HeroScoreCard(scoreValue: ..., ...)` —
        // must keep working without the round-20 opt-in. If the
        // ribbon parameter weren't defaulted, every prior call site
        // (currently just the one in `SummaryView`, but defaults guard
        // future call sites too) would fail to compile. This test pins
        // the default behavior explicitly (the predicate the body's
        // `if let label` branch reads is false → the ribbon stays
        // hidden), so a future refactor that drops the default surfaces
        // here.
        let card = HeroScoreCard(
            scoreValue: 8,
            practiceTitle: "Timed",
            scoreAccent: .blue,
            scoreEmoji: "hand.thumbsup.fill",
            headline: "Strong delivery",
            sessionPrompt: nil,
            effectiveFillerCount: 1,
            fillerTint: .green,
            fillerDelta: nil,
            effectiveDuration: 30,
            durationAssessment: .onTarget,
            celebrationVisible: false
        )
        #expect(!card.shouldShowToneDrillResolvedRibbon, "Default card must not render the SOLVED ribbon.")
        #expect(card.toneDrillResolvedRibbonLabel == nil, "Default label must be nil.")
    }

    @Test func wiringRibbonEnablesRender() {
        // When the owning view passes a non-nil ribbon, the body's gate
        // flips to true so the SOLVED capsule shows. The predicate is
        // what the `if let label` branch in the body reads — this locks
        // the contract independently of SwiftUI rendering.
        let card = HeroScoreCard(
            scoreValue: 9,
            practiceTitle: "IM Mode",
            scoreAccent: .blue,
            scoreEmoji: "flame.fill",
            headline: "Strong delivery",
            sessionPrompt: nil,
            effectiveFillerCount: 0,
            fillerTint: .green,
            fillerDelta: nil,
            effectiveDuration: 60,
            durationAssessment: .onTarget,
            celebrationVisible: false,
            toneDrillResolvedRibbon: HeroScoreCard.ToneDrillResolvedRibbon(
                scenarioTitle: "Difficult Conversation",
                toneTitle: "Calm"
            )
        )
        #expect(card.shouldShowToneDrillResolvedRibbon)
    }

    @Test func ribbonLabelShapeNamesToneAndScenario() {
        // The capsule copy mirrors the post-rep coach-note's
        // `Your <tone> tone in <scenario> is solved` phrasing but
        // compressed to a chip label. Both the scenario title AND the
        // committed tone title appear in the label — without either,
        // the user can't tell which drill closed. Locked across every
        // (scenario, tone) pair the IM engine produces so a future tone
        // addition can't ship a ribbon that drops the new tone name.
        let scenarios = ["Social Catch-Up", "Work Update", "Difficult Conversation", "Networking"]
        let tones = ["Confident", "Warm", "Concise", "Assertive", "Calm", "Professional"]
        for scenario in scenarios {
            for tone in tones {
                let card = HeroScoreCard(
                    scoreValue: 8,
                    practiceTitle: "IM Mode",
                    scoreAccent: .blue,
                    scoreEmoji: "hand.thumbsup.fill",
                    headline: "Strong delivery",
                    sessionPrompt: nil,
                    effectiveFillerCount: 0,
                    fillerTint: .green,
                    fillerDelta: nil,
                    effectiveDuration: 45,
                    durationAssessment: .onTarget,
                    celebrationVisible: false,
                    toneDrillResolvedRibbon: HeroScoreCard.ToneDrillResolvedRibbon(
                        scenarioTitle: scenario,
                        toneTitle: tone
                    )
                )
                let label = card.toneDrillResolvedRibbonLabel ?? ""
                #expect(label.contains(scenario), "Label must name the scenario — got \(label)")
                #expect(label.contains(tone), "Label must name the committed tone — got \(label)")
                #expect(label.hasPrefix("Holding"), "Label must lead with the evidence-scaled outcome — got \(label)")
            }
        }
    }

    @Test func ribbonLabelHasNoUrgencyOrFanfare() {
        // Brand-voice contract — the SOLVED ribbon is a quiet "you closed
        // this gap" tag, not a celebration overlay. The visual register
        // (a 0.10-alpha IM-tinted capsule) is already restrained; the
        // copy must match. No exclamations, no "let's", no urgency
        // framing, no shouty "WIN!" / "AMAZING!" pep-talk. Locked
        // across multiple (scenario, tone) pairs so a future copy
        // tweak can't sneak fanfare onto one combination without a
        // failing test. Mirrors `LookingAheadCardStartCTAContractTests.
        // startCTALabelHasNoUrgencyOrFanfare` shape so the two
        // restraint contracts stay aligned.
        let cases: [(String, String)] = [
            ("Difficult Conversation", "Calm"),
            ("Networking", "Confident"),
            ("Work Update", "Professional"),
            ("Social Catch-Up", "Warm")
        ]
        for (scenario, tone) in cases {
            let card = HeroScoreCard(
                scoreValue: 8,
                practiceTitle: "IM Mode",
                scoreAccent: .blue,
                scoreEmoji: "hand.thumbsup.fill",
                headline: "Strong delivery",
                sessionPrompt: nil,
                effectiveFillerCount: 0,
                fillerTint: .green,
                fillerDelta: nil,
                effectiveDuration: 45,
                durationAssessment: .onTarget,
                celebrationVisible: false,
                toneDrillResolvedRibbon: HeroScoreCard.ToneDrillResolvedRibbon(
                    scenarioTitle: scenario,
                    toneTitle: tone
                )
            )
            let label = card.toneDrillResolvedRibbonLabel ?? ""
            #expect(!label.contains("!"), "Ribbon must not exclaim — got \(label)")
            #expect(!label.lowercased().contains("let's"), "Ribbon must not pep-talk — got \(label)")
            #expect(!label.lowercased().contains("now"), "Ribbon must not urgency-frame — got \(label)")
            #expect(!label.lowercased().contains("hurry"), "Ribbon must not urgency-frame — got \(label)")
            #expect(!label.lowercased().contains("amazing"), "Ribbon must not fanfare — got \(label)")
            #expect(!label.lowercased().contains("nailed"), "Ribbon must not fanfare — got \(label)")
            #expect(!label.lowercased().contains("crushed"), "Ribbon must not fanfare — got \(label)")
        }
    }

    @Test func ribbonStaysHiddenWhenNotWired() {
        // Sanity: explicitly passing nil keeps the ribbon hidden and
        // the label nil. Locked separately from the default-omits
        // case so a refactor that changes default from nil to a
        // sentinel (or vice-versa) still has to keep the explicit-nil
        // contract honest.
        let card = HeroScoreCard(
            scoreValue: 8,
            practiceTitle: "Timed",
            scoreAccent: .blue,
            scoreEmoji: "hand.thumbsup.fill",
            headline: "Strong delivery",
            sessionPrompt: nil,
            effectiveFillerCount: 1,
            fillerTint: .green,
            fillerDelta: nil,
            effectiveDuration: 30,
            durationAssessment: .onTarget,
            celebrationVisible: false,
            toneDrillResolvedRibbon: nil
        )
        #expect(!card.shouldShowToneDrillResolvedRibbon)
        #expect(card.toneDrillResolvedRibbonLabel == nil)
    }

    @Test func ribbonValueTypeEquatability() {
        // The `ToneDrillResolvedRibbon` bundle is Equatable so the
        // SwiftUI body's `if let label` branch participates in
        // diff-aware re-renders correctly: a stable scenario+tone
        // pair across re-renders must compare equal so the capsule
        // doesn't flicker. Pins the value-type contract.
        let a = HeroScoreCard.ToneDrillResolvedRibbon(
            scenarioTitle: "Difficult Conversation",
            toneTitle: "Calm"
        )
        let b = HeroScoreCard.ToneDrillResolvedRibbon(
            scenarioTitle: "Difficult Conversation",
            toneTitle: "Calm"
        )
        let c = HeroScoreCard.ToneDrillResolvedRibbon(
            scenarioTitle: "Networking",
            toneTitle: "Calm"
        )
        let d = HeroScoreCard.ToneDrillResolvedRibbon(
            scenarioTitle: "Difficult Conversation",
            toneTitle: "Confident"
        )
        #expect(a == b, "Same scenario+tone must compare equal.")
        #expect(a != c, "Different scenario must compare unequal.")
        #expect(a != d, "Different tone must compare unequal.")
    }
}

// MARK: - M24 deferred slate round 22 — AIRateLimiter publication
//
// `AIRateLimiter` is the per-account, per-day budget for outbound AI
// calls on the per-rep coach voice surface. Rounds prior to 22 read
// it synchronously inside SwiftUI bodies (Settings AI-usage card,
// `CoachReadCard` daily-budget hint) — which meant a rep consumed in
// another tab while the card was visible left the rendered count
// stale until the user navigated away and back. Round 22 makes the
// limiter an `ObservableObject` that publishes a `changeToken` bump
// on writes that change what `remainingToday(kind:)` would return.
//
// The publication contract is narrow on purpose:
//   • Bump on a successful `consumeIfAllowed` — the read-side count
//     went down.
//   • Bump on `deleteAllData(for:)` ONLY when the wiped account is
//     the active one — other-account wipes don't affect what
//     `remainingToday(kind:)` would return for the current account.
//   • Stay quiet on debounce-blocked or cap-reached `consumeIfAllowed`
//     — the count didn't move, so observers re-rendering would burn
//     CPU for no visible change.
//   • Stay quiet on `endSession` — that's a sign-out lifecycle hook
//     that clears the in-memory debounce window only; views don't
//     observe debounce.
//
// These tests lock that contract pre-Combine-import: they sample
// `changeToken` directly (it's `@Published private(set) var`,
// readable from the same module) before and after each operation.
// Sampling the underlying token is preferable to subscribing to
// `objectWillChange` because the bump is synchronous in the same
// MainActor turn — a Combine subscription would need extra delivery
// scheduling to observe reliably in a unit test.

@MainActor
struct AIRateLimiterPublicationTests {

    /// Hermetic limiter: fresh in-memory `UserDefaults` suite, frozen
    /// clock so the debounce window can be reasoned about explicitly,
    /// fixed account id so the active-account `deleteAllData` gate is
    /// deterministic, and a premium override so the cap doesn't drift
    /// with the test runner's StoreKit state.
    private func freshLimiter(
        accountID: String = "publication-tester",
        premium: Bool = false,
        clock: Date = Date(timeIntervalSince1970: 1_700_000_000)
    ) -> AIRateLimiter {
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        return AIRateLimiter(
            defaults: suite,
            accountIDProvider: { accountID },
            now: { clock },
            premiumProvider: { premium }
        )
    }

    @Test func changeTokenStartsAtZeroForFreshInstance() {
        // A brand-new limiter has not seen any state change yet. The
        // token reads zero so observers can establish a baseline at
        // `.onAppear` without spurious renders. (`@Published`
        // semantics: an initial assignment in `init` does not fire
        // `objectWillChange` for `private(set)` properties that were
        // assigned their default value at declaration.)
        let limiter = freshLimiter()
        #expect(limiter.changeToken == 0)
    }

    @Test func consumeBumpsChangeTokenOnSuccess() {
        // The primary positive path: a successful `consumeIfAllowed`
        // writes a new value into `UserDefaults` AND bumps the token.
        // SwiftUI surfaces observing the limiter re-render and read
        // the post-consume `remainingToday` value.
        let limiter = freshLimiter()
        let before = limiter.changeToken
        let allowed = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        #expect(allowed == true, "Fresh limiter under cap must allow consume.")
        #expect(limiter.changeToken == before &+ 1,
            "Successful consume must bump the publication token exactly once.")
    }

    @Test func consumeBumpsTokenExactlyOncePerSuccess() {
        // The first successful consume on a fresh limiter lifts the
        // token from 0 to exactly 1 — no double-bump from a refactor
        // that splits the write path into a "check + record" pair, no
        // skipped bump from a future early-return ordering bug. The
        // `consumeDoesNotBumpOnCapReached` test below extends this
        // exact-once contract across `freeDailyCap` successful
        // consumes; this is the single-consume anchor.
        let limiter = freshLimiter()
        _ = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        #expect(limiter.changeToken == 1)
    }

    @Test func consumeDoesNotBumpOnDebounceBlock() {
        // Debounce-blocked consume returns false without writing to
        // `UserDefaults` and without bumping the token. The frozen
        // clock holds the second call inside the 1.5s debounce floor
        // of the first call's timestamp.
        let limiter = freshLimiter()
        let allowedFirst = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        #expect(allowedFirst == true)
        let tokenAfterFirst = limiter.changeToken

        let allowedSecond = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        #expect(allowedSecond == false,
            "Second consume inside debounce window must be blocked.")
        #expect(limiter.changeToken == tokenAfterFirst,
            "Debounce-blocked consume must not bump the publication token.")
    }

    @Test func consumeDoesNotBumpOnCapReached() {
        // Cap-reached consume returns false without bumping the
        // token. We stand up a limiter whose clock advances past the
        // debounce window between calls so only the cap gate is
        // exercised, then push exactly `freeDailyCap` successful
        // consumes through and assert the +1 call returns false with
        // no further token bump.
        let baseDate = Date(timeIntervalSince1970: 1_700_000_000)
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        var tick = 0
        let limiter = AIRateLimiter(
            defaults: suite,
            accountIDProvider: { "cap-tester" },
            now: { baseDate.addingTimeInterval(Double(tick) * 60.0) },
            premiumProvider: { false }
        )

        for _ in 0..<AIRateLimiter.freeDailyCap {
            let allowed = limiter.consumeIfAllowed(kind: .postRepCoachNote)
            #expect(allowed == true)
            tick += 1
        }
        let tokenAtCap = limiter.changeToken
        #expect(tokenAtCap == UInt64(AIRateLimiter.freeDailyCap),
            "Each successful consume up to the cap should bump exactly once.")

        let overCap = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        #expect(overCap == false,
            "Consume at cap+1 must return false (soft-degrade contract).")
        #expect(limiter.changeToken == tokenAtCap,
            "Cap-reached consume must not bump the publication token.")
    }

    @Test func endSessionDoesNotBumpChangeToken() {
        // `endSession` clears the in-memory `lastCallTimestamp`
        // dictionary — debounce only, no read-side effect. Observers
        // that re-rendered here would burn CPU for nothing. The
        // contract: `endSession` is silent on the publication axis.
        let limiter = freshLimiter()
        _ = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        let tokenBeforeEnd = limiter.changeToken
        limiter.endSession()
        #expect(limiter.changeToken == tokenBeforeEnd,
            "endSession must not bump the publication token.")
    }

    @Test func deleteAllDataBumpsTokenForActiveAccount() {
        // The active-account wipe resets every (kind × day) counter to
        // 0 — observing surfaces should re-read and see the wider
        // budget. The bump fires from inside `deleteAllData(for:)`
        // when the wiped id matches the current `accountIDProvider`
        // return value.
        let limiter = freshLimiter(accountID: "active")
        _ = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        let tokenBeforeWipe = limiter.changeToken
        limiter.deleteAllData(for: "active")
        #expect(limiter.changeToken == tokenBeforeWipe &+ 1,
            "Active-account deleteAllData must bump the publication token.")
        // Also lock the read-side effect: after the wipe, remaining
        // is back to the full cap.
        #expect(limiter.remainingToday(kind: .postRepCoachNote)
            == AIRateLimiter.freeDailyCap)
    }

    @Test func deleteAllDataDoesNotBumpForDifferentAccount() {
        // Wiping a *different* account's counters cannot affect what
        // `remainingToday(kind:)` would return for the current
        // account — they're in different storage keys. A bump here
        // would re-render every observer for no visible reason.
        // Locks the gated-bump contract.
        let limiter = freshLimiter(accountID: "active")
        _ = limiter.consumeIfAllowed(kind: .postRepCoachNote)
        let tokenBeforeOtherWipe = limiter.changeToken
        limiter.deleteAllData(for: "some-other-account")
        #expect(limiter.changeToken == tokenBeforeOtherWipe,
            "Other-account deleteAllData must not bump the publication token.")
    }

    @Test func tokenAndRemainingTodayStayInLockstep() {
        // Integration check: every token bump corresponds to a
        // read-side change that an observing view would render. After
        // each successful consume, `remainingToday` is one lower than
        // before. This is the contract a SwiftUI body relies on —
        // "if the token moved, the number I read is different from
        // last time."
        let baseDate = Date(timeIntervalSince1970: 1_700_000_000)
        let suite = UserDefaults(suiteName: UUID().uuidString)!
        var tick = 0
        let limiter = AIRateLimiter(
            defaults: suite,
            accountIDProvider: { "lockstep" },
            now: { baseDate.addingTimeInterval(Double(tick) * 60.0) },
            premiumProvider: { false }
        )

        var lastToken = limiter.changeToken
        var lastRemaining = limiter.remainingToday(kind: .postRepCoachNote)
        for _ in 0..<5 {
            tick += 1
            let allowed = limiter.consumeIfAllowed(kind: .postRepCoachNote)
            #expect(allowed == true)
            let nowToken = limiter.changeToken
            let nowRemaining = limiter.remainingToday(kind: .postRepCoachNote)
            #expect(nowToken == lastToken &+ 1, "Token must advance by 1.")
            #expect(nowRemaining == lastRemaining - 1,
                "remainingToday must decrease by 1 when the token advances.")
            lastToken = nowToken
            lastRemaining = nowRemaining
        }
    }
}

// MARK: - M24 deferred slate round 23 — CoachReadCard daily-budget hint
//
// Round 22 made `AIRateLimiter` an `ObservableObject` so the daily-
// budget hint on the post-rep CoachReadCard refreshes when a rep
// elsewhere consumes the AI-polish budget. Round 23 closes the one
// remaining read-side stale hole the round-22 doc-comment explicitly
// rationalized away: premium tier changes. The Pro-upgrade entry from
// `SummaryView` is a `.sheet` (verified in
// `SummaryView.swift:.sheet(isPresented: $showPaywall)`), which means
// the CoachReadCard stays mounted when the paywall dismisses after a
// successful purchase. Without round 23's `@StateObject premium`
// observer the hint would keep reading the pre-upgrade cap (12)
// against the same used count, leaving "1 AI coach note remaining
// today" on screen even though the new cap (40) puts the user back
// at 30 remaining.
//
// The contract these tests lock lives at the pure-function layer —
// `CoachReadCard.shouldShowDailyBudgetHint(noteIsAIBacked:cap:remaining:)`
// — so the threshold math can be reasoned about without standing up
// a real `AIRateLimiter` + `PremiumManager`. The tier-upgrade /
// tier-downgrade tests are the round-23 anchors: at the same `used`
// count, the hint flips solely on the cap change. That's the body
// recomputation the new `@StateObject premium` triggers.

@MainActor
struct CoachReadCardDailyBudgetHintTests {

    private let freeCap = AIRateLimiter.freeDailyCap        // 12
    private let premiumCap = AIRateLimiter.premiumDailyCap  // 40
    private let threshold = CoachReadCard.dailyBudgetHintThresholdRatio  // 0.75

    @Test func hintIsHiddenWhenNoteIsRuleBased() {
        // Rule-based notes carry the explicit `RULE-BASED` tag in the
        // card header. The hint would be a second voice saying the
        // same thing — and would also misleadingly imply the AI
        // polish layer is "running out" when in fact it isn't
        // participating at all.
        #expect(
            CoachReadCard.shouldShowDailyBudgetHint(
                noteIsAIBacked: false,
                cap: freeCap,
                remaining: 0
            ) == false
        )
    }

    @Test func hintIsHiddenWhenBudgetIsHealthy() {
        // Below the 75%-used bar the hint stays silent. At cap=12
        // with 9 remaining, used=3 → ratio=0.25, well below the
        // 0.75 threshold.
        #expect(
            CoachReadCard.shouldShowDailyBudgetHint(
                noteIsAIBacked: true,
                cap: freeCap,
                remaining: 9
            ) == false
        )
    }

    @Test func hintAppearsExactlyAtThreshold() {
        // The threshold is `>= 0.75`, not `> 0.75`. At cap=12 with
        // 3 remaining, used=9 → ratio=0.75 exactly — the hint
        // appears. Pins the inclusive-comparison contract so a
        // future refactor flipping `>=` to `>` would surface as a
        // test failure rather than as a quiet UX regression.
        #expect(
            CoachReadCard.shouldShowDailyBudgetHint(
                noteIsAIBacked: true,
                cap: freeCap,
                remaining: 3
            ) == true
        )
    }

    @Test func hintIsShownWhenAtZeroRemaining() {
        // Cap-reached. The card has already soft-degraded to a
        // rule-based note for the next rep (the note in front of
        // the user might still be AI-backed — it was the one that
        // just tipped the limiter at the cap). The hint reads
        // "Rule-based today — coach notes resume tomorrow."
        #expect(
            CoachReadCard.shouldShowDailyBudgetHint(
                noteIsAIBacked: true,
                cap: freeCap,
                remaining: 0
            ) == true
        )
    }

    @Test func hintIsHiddenWhenCapIsZero() {
        // Defensive — a misconfigured tier or a future limiter
        // variant that returns cap=0 would otherwise divide by zero
        // when computing the ratio. The pure function returns false
        // so the body computation stays silent rather than crashing
        // or rendering an empty caption.
        #expect(
            CoachReadCard.shouldShowDailyBudgetHint(
                noteIsAIBacked: true,
                cap: 0,
                remaining: 0
            ) == false
        )
    }

    @Test func tierUpgradeCrossesBackBelowThreshold() {
        // The round-23 anchor. Same `used` count (10), cap goes
        // 12 → 40 on a Pro upgrade. Pre-upgrade ratio ~0.83 → hint
        // shown. Post-upgrade ratio 0.25 → hint hidden. The card
        // observing `PremiumManager` makes this transition happen
        // the same body turn as the purchase landing, not on a
        // navigation re-mount.
        let used = 10
        let preUpgrade = CoachReadCard.shouldShowDailyBudgetHint(
            noteIsAIBacked: true,
            cap: freeCap,
            remaining: freeCap - used
        )
        let postUpgrade = CoachReadCard.shouldShowDailyBudgetHint(
            noteIsAIBacked: true,
            cap: premiumCap,
            remaining: premiumCap - used
        )
        #expect(preUpgrade == true, "Pre-upgrade ratio 10/12 should trigger the hint.")
        #expect(postUpgrade == false, "Post-upgrade ratio 10/40 should hide the hint.")
    }

    @Test func tierDowngradeCrossesAboveThreshold() {
        // The mirror of the upgrade contract. A subscription lapse
        // (premium → free) with the same `used` count flips the
        // hint back on. Real-world relevance is lower than the
        // upgrade case (lapse rarely happens mid-summary), but the
        // contract is symmetric — locking both directions keeps a
        // future refactor that hard-codes premium cap from
        // accidentally one-way-only.
        let used = 10
        let preDowngrade = CoachReadCard.shouldShowDailyBudgetHint(
            noteIsAIBacked: true,
            cap: premiumCap,
            remaining: premiumCap - used
        )
        let postDowngrade = CoachReadCard.shouldShowDailyBudgetHint(
            noteIsAIBacked: true,
            cap: freeCap,
            remaining: freeCap - used
        )
        #expect(preDowngrade == false, "Pre-downgrade ratio 10/40 should hide the hint.")
        #expect(postDowngrade == true, "Post-downgrade ratio 10/12 should trigger the hint.")
    }

    @Test func remainingOverCapClampsCleanly() {
        // Defensive — if a caller ever passes a remaining count
        // larger than the cap (e.g. mid-flight tier upgrade where
        // the rate-limiter and the cap reader briefly disagree),
        // the pure function clamps rather than reporting a
        // negative `used` count that would invert the ratio and
        // falsely trigger the hint.
        #expect(
            CoachReadCard.shouldShowDailyBudgetHint(
                noteIsAIBacked: true,
                cap: freeCap,
                remaining: freeCap + 5
            ) == false
        )
    }

    @Test func thresholdMatchesDocumentedRatio() {
        // The 0.75 ratio is referenced in:
        //   • the round-22 HANDOFF (".. crossing the 75%-used
        //     threshold mid-view actually starts showing the hint")
        //   • the CoachReadCard doc-comment
        // Pin the constant so a future tweak to a different number
        // surfaces as a test that the documentation must be updated
        // in lockstep with the code.
        #expect(threshold == 0.75)
    }

    @Test func hintCopyAtZeroNamesTomorrowsResume() {
        // The simplified-copy line is shown at the cap-reached state.
        // Brand-voice compliant: no exclamation,
        // no urgency, no "running out" framing. Pins the exact
        // string so a copy edit must be deliberate.
        #expect(
            CoachReadCard.dailyBudgetHintCopy(remaining: 0)
                == "Simpler coach notes today. Personalized wording resumes tomorrow."
        )
    }

    @Test func hintCopyAtOneIsSingular() {
        // English singular/plural rule on the count noun.
        #expect(
            CoachReadCard.dailyBudgetHintCopy(remaining: 1)
                == "1 AI coach note remaining today."
        )
    }

    @Test func hintCopyAtMoreIsPlural() {
        // Plural branch.
        #expect(
            CoachReadCard.dailyBudgetHintCopy(remaining: 3)
                == "3 AI coach notes remaining today."
        )
    }

    @Test func hintCopyNegativeClampsToZeroBranch() {
        // Defensive — a transient state where the cap reader and
        // the counter disagree could yield a negative `remaining`
        // for a single body recomputation. The copy should treat
        // that as cap-reached (the safe over-report) rather than
        // emit "-1 AI coach notes remaining today."
        #expect(
            CoachReadCard.dailyBudgetHintCopy(remaining: -2)
                == "Simpler coach notes today. Personalized wording resumes tomorrow."
        )
    }
}

// MARK: - M24 deferred slate round 24 — intervention-review prompt
//
// Rounds 22 + 23 closed two read-side honesty holes on
// `CoachReadCard`. Round 24 picks up the highest-impact next-step
// from the 2026-05-29 case-intervention HANDOFF: post-rep
// intervention review.
//
// The case-file infrastructure already records `reviewDueAt`,
// `followedRepCount`, and `minimumFollowedRepsForReview` on the
// active `CoachIntervention`. Until round 24, those fields fed only
// the AI context block in `CoachContextBuilder.interventionCycleLines`
// — the user themselves never saw a prompt to revisit the
// intervention at the moment the cadence elapsed. Vision pillar #5
// (Personalized coaching) and coach-parity stage #4 (Adaptation)
// both call this out: "compare response across multiple attempts
// and either reinforce, vary, or replace the intervention with an
// explained rationale."
//
// Round 24:
//   • `CoachIntervention.isReviewDue(at:)` — pure predicate; both
//     gates (followed-rep threshold AND reviewDueAt elapsed) must
//     hold so an early prompt never lands on thin evidence and a
//     late prompt never holds past the agreed cadence.
//   • `InterventionReviewPromptCard` — restrained Summary card,
//     pure-function copy helpers so the strings can be locked.
//   • `CoachContextBuilder.interventionReviewOpener(...)` — seed
//     opener for the "Review with coach" CTA, voice-mapped on the
//     same SpeakingStyleGoal axis as `sessionOpener`.
//
// These tests lock the predicate's three boundary conditions,
// the headline / body copy branches, and the per-voice opener
// shapes. All three layers are pure functions of small value
// types so no `CoachMemoryStore` or `AskNoumStore` is required.

@MainActor
struct InterventionReviewPromptTests {

    // MARK: - Helpers

    /// Build a baseline intervention the tests can mutate field-by-
    /// field. Default values are tuned so `isReviewDue(at:)` returns
    /// false out of the box (no `reviewDueAt`, followed reps below
    /// threshold) — every test explicitly sets the field it's
    /// asserting against.
    private func makeIntervention(
        focus: String? = "filler reduction",
        title: String = "Filler reduction drill",
        followedRepCount: Int = 0,
        minimumFollowedRepsForReview: Int = 3,
        reviewDueAt: Date? = nil
    ) -> CoachIntervention {
        CoachIntervention(
            title: title,
            focus: focus,
            target: "Cut fillers per minute below 4.",
            mode: .timed,
            prescribedAt: Date(timeIntervalSince1970: 1_700_000_000),
            lastObservedAt: Date(timeIntervalSince1970: 1_700_000_000),
            followedRepCount: followedRepCount,
            minimumFollowedRepsForReview: minimumFollowedRepsForReview,
            reviewStatus: .formingEvidence,
            reviewBasis: "Evidence is forming across followed reps.",
            successCriterion: nil,
            criterionStatus: nil,
            reviewDueAt: reviewDueAt
        )
    }

    private let now = Date(timeIntervalSince1970: 1_700_000_000)

    private func repeatedReflectionPattern(_ feeling: ReflectionFeeling) -> CoachReflectionPattern {
        CoachReflectionPattern.build(from: [
            SessionReflection(sessionID: UUID(), feeling: feeling, recordedAt: Date(timeIntervalSince1970: 1_000)),
            SessionReflection(sessionID: UUID(), feeling: .strong, recordedAt: Date(timeIntervalSince1970: 900)),
            SessionReflection(sessionID: UUID(), feeling: feeling, recordedAt: Date(timeIntervalSince1970: 800)),
            SessionReflection(sessionID: UUID(), feeling: feeling, recordedAt: Date(timeIntervalSince1970: 700)),
        ])!
    }

    // MARK: - Predicate guards

    @Test func reviewIsNotDueWhenReviewDueAtIsNil() {
        // The case file may carry an active intervention without a
        // cadence stamp (early in the cycle, before the case engine
        // chooses a review date). The predicate must return false so
        // the prompt never surfaces without a coach-stamped cadence.
        let intervention = makeIntervention(
            followedRepCount: 5,
            minimumFollowedRepsForReview: 3,
            reviewDueAt: nil
        )
        #expect(intervention.isReviewDue(at: now) == false)
    }

    @Test func reviewIsNotDueWhenFollowedRepsBelowMinimum() {
        // Cadence elapsed, but evidence floor not yet met. A real
        // coach doesn't ask "is this working?" two reps in — they
        // wait for enough observed reps to have a basis. The
        // predicate honours that.
        let intervention = makeIntervention(
            followedRepCount: 1,
            minimumFollowedRepsForReview: 3,
            reviewDueAt: now.addingTimeInterval(-86_400)  // one day ago
        )
        #expect(intervention.isReviewDue(at: now) == false)
    }

    @Test func reviewIsNotDueWhenDueDateInFuture() {
        // Evidence floor met, cadence not yet elapsed. The prompt
        // must wait — surfacing it before the agreed review date
        // would frame "we're checking in" as a coach-initiated
        // override of the cadence.
        let intervention = makeIntervention(
            followedRepCount: 5,
            minimumFollowedRepsForReview: 3,
            reviewDueAt: now.addingTimeInterval(86_400)  // one day from now
        )
        #expect(intervention.isReviewDue(at: now) == false)
    }

    // MARK: - Predicate happy path + boundaries

    @Test func reviewIsDueWhenDueDateInPast() {
        // Both gates met — happy path. The summary surfaces the
        // prompt this rep.
        let intervention = makeIntervention(
            followedRepCount: 5,
            minimumFollowedRepsForReview: 3,
            reviewDueAt: now.addingTimeInterval(-86_400)
        )
        #expect(intervention.isReviewDue(at: now) == true)
    }

    @Test func reviewIsDueWhenDueDateExactlyNow() {
        // Boundary: the predicate uses `>=`, not `>`. The instant
        // the cadence elapses, the prompt is eligible. Pins the
        // inclusive-comparison contract so a future refactor
        // flipping `>=` to `>` would surface as a test failure
        // rather than as a quietly-late prompt the day after.
        let intervention = makeIntervention(
            followedRepCount: 5,
            minimumFollowedRepsForReview: 3,
            reviewDueAt: now
        )
        #expect(intervention.isReviewDue(at: now) == true)
    }

    @Test func reviewIsDueWhenFollowedRepsExactlyAtMinimum() {
        // Boundary: the predicate uses `>=`, not `>`. The instant
        // the user lands their Nth followed rep — N being the
        // configured minimum — the evidence threshold is met. A
        // refactor that flips `>=` to `>` would silently delay the
        // prompt by one rep.
        let intervention = makeIntervention(
            followedRepCount: 3,
            minimumFollowedRepsForReview: 3,
            reviewDueAt: now.addingTimeInterval(-3600)
        )
        #expect(intervention.isReviewDue(at: now) == true)
    }

    @Test func reviewIsNotDueWhenFollowedRepsOneShortAndCadenceElapsed() {
        // Symmetric mirror of the boundary test: one rep short,
        // cadence elapsed → still not due. The evidence floor wins
        // over an elapsed cadence; the prompt waits.
        let intervention = makeIntervention(
            followedRepCount: 2,
            minimumFollowedRepsForReview: 3,
            reviewDueAt: now.addingTimeInterval(-3600)
        )
        #expect(intervention.isReviewDue(at: now) == false)
    }

    // MARK: - Headline copy

    @Test func headlineCopyNamesFocus() {
        // The headline names the active focus so the user reads the
        // subject of the review in one beat. Lower-cased per the
        // brand voice (the focus is mid-sentence after a verb, not
        // a proper noun).
        let intervention = makeIntervention(focus: "Filler reduction", title: "Filler drill")
        #expect(
            InterventionReviewPromptCard.headlineCopy(for: intervention)
                == "Time to check in on filler reduction."
        )
    }

    @Test func headlineCopyFallsBackToTitleWhenFocusIsNil() {
        // Defensive — early in the case cycle, an intervention may
        // not yet have a focus phrase. The headline falls back to
        // the title so the user never sees "Time to check in on ."
        let intervention = makeIntervention(focus: nil, title: "Authority practice")
        #expect(
            InterventionReviewPromptCard.headlineCopy(for: intervention)
                == "Time to check in on authority practice."
        )
    }

    @Test func headlineCopyFallsBackToTitleWhenFocusIsEmpty() {
        // Same fallback for the empty-string edge — case-engine
        // refactors that write `""` instead of `nil` shouldn't
        // produce an empty noun phrase.
        let intervention = makeIntervention(focus: "", title: "Pace control")
        #expect(
            InterventionReviewPromptCard.headlineCopy(for: intervention)
                == "Time to check in on pace control."
        )
    }

    // MARK: - Body copy

    @Test func bodyCopyUsesSingularRepNoun() {
        let intervention = makeIntervention(followedRepCount: 1)
        #expect(
            InterventionReviewPromptCard.bodyCopy(for: intervention)
                == "Your coach scheduled this review after 1 completed rep. One question: keep going, adapt, or replace it?"
        )
    }

    @Test func bodyCopyUsesPluralRepNoun() {
        let intervention = makeIntervention(followedRepCount: 4)
        #expect(
            InterventionReviewPromptCard.bodyCopy(for: intervention)
                == "Your coach scheduled this review after 4 completed reps. One question: keep going, adapt, or replace it?"
        )
    }

    @Test func bodyCopyUsesPluralForZeroReps() {
        // Defensive — the predicate guarantees followedRepCount >=
        // minimumFollowedRepsForReview before the card renders, but
        // the pure copy helper still has to handle 0 cleanly. "0
        // followed reps" is the right plural for English count
        // nouns.
        let intervention = makeIntervention(followedRepCount: 0)
        #expect(
            InterventionReviewPromptCard.bodyCopy(for: intervention)
                == "Your coach scheduled this review after 0 completed reps. One question: keep going, adapt, or replace it?"
        )
    }

    // MARK: - Opener lead

    @Test func openerLeadNamesModeFocusAndDepth() {
        // The lead is the half of the opener that doesn't depend on
        // voice. It must carry mode + focus + followed-rep depth so
        // the AI reply has the evidence scaffolding in scope.
        let intervention = makeIntervention(
            focus: "Filler reduction",
            followedRepCount: 4
        )
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: nil
        )
        #expect(opener.hasPrefix("Time to review the active case: Timed Practice for filler reduction, 4 followed reps in."))
    }

    @Test func openerLeadUsesSingularRepNoun() {
        // Singular boundary at 1 followed rep.
        let intervention = makeIntervention(
            focus: "Pace",
            followedRepCount: 1
        )
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: nil
        )
        #expect(opener.contains("1 followed rep in."))
        #expect(!opener.contains("1 followed reps in."))
    }

    @Test func openerLeadFallsBackToTitleWhenFocusIsNil() {
        // Defensive — same fallback the card headline carries. The
        // opener must never read "for ," to the model.
        let intervention = makeIntervention(
            focus: nil,
            title: "Authority practice",
            followedRepCount: 3
        )
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: nil
        )
        #expect(opener.contains("for authority practice,"))
    }

    @Test func openerAddsSubjectivePatternReviewBeforeVoiceAsk() {
        // A human coach reviews more than the metric. When the case file
        // has a repeated self-report pattern, the opener asks the coach
        // to check whether that felt blocker is changing without
        // stealing the final voice-shaped ask.
        let intervention = makeIntervention(
            focus: "Filler reduction",
            followedRepCount: 4
        )
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: .concise,
            reflectionPattern: repeatedReflectionPattern(.nervous)
        )

        #expect(opener.contains("Also review the subjective pattern as self-report, not diagnosis: check whether the repeated nerves are easing, unchanged, or worse."))
        #expect(opener.hasSuffix("Keep, adapt, or replace?"))
    }

    @Test func openerSubjectivePatternAvoidsCausalOrDiagnosticClaims() {
        // The pattern is user-owned self-report. The opener may ask
        // about it, but must not say the intervention caused it or
        // treat it as a diagnosis.
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: makeIntervention(followedRepCount: 4),
            voice: nil,
            reflectionPattern: repeatedReflectionPattern(.heldBack)
        )
        let lower = opener.lowercased()

        #expect(opener.contains("self-report, not diagnosis"))
        #expect(opener.contains("still holding back"))
        #expect(!lower.contains("caused"))
        #expect(!lower.contains("diagnosed"))
    }

    // MARK: - Opener voice mapping

    @Test func openerAskByVoiceAuthoritative() {
        let intervention = makeIntervention(followedRepCount: 3)
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: .authoritative
        )
        #expect(opener.hasSuffix("Is this still the right intervention, or do we adapt?"))
    }

    @Test func openerAskByVoiceWarm() {
        let intervention = makeIntervention(followedRepCount: 3)
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: .warm
        )
        #expect(opener.hasSuffix("Is this still feeling like the right work?"))
    }

    @Test func openerAskByVoiceConcise() {
        let intervention = makeIntervention(followedRepCount: 3)
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: .concise
        )
        #expect(opener.hasSuffix("Keep, adapt, or replace?"))
    }

    @Test func openerAskByVoicePersuasive() {
        let intervention = makeIntervention(followedRepCount: 3)
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: .persuasive
        )
        #expect(opener.hasSuffix("Make the case — keep going or change tack?"))
    }

    @Test func openerAskByVoiceExecutive() {
        let intervention = makeIntervention(followedRepCount: 3)
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: .executive
        )
        #expect(opener.hasSuffix("Verdict: continue, adapt, or replace?"))
    }

    @Test func openerAskByVoiceStorytelling() {
        let intervention = makeIntervention(followedRepCount: 3)
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: .storytelling
        )
        #expect(opener.hasSuffix("Where does this arc go next?"))
    }

    @Test func openerAskWhenVoiceIsNil() {
        // Voice nil → neutral ask. The fallback covers users who
        // haven't completed the coaching profile yet — the opener
        // still produces a coherent review question.
        let intervention = makeIntervention(followedRepCount: 3)
        let opener = CoachContextBuilder.interventionReviewOpener(
            intervention: intervention,
            voice: nil
        )
        #expect(opener.hasSuffix("Should we keep going, adapt, or change tack?"))
    }

    // MARK: - Starter-chip headline (AskNoumView empty state)
    //
    // The chip on `AskNoumView`'s empty state is a short-form sibling
    // of `InterventionReviewPromptCard`. The display label has to
    // share the card's focus-or-title fallback so the user reads the
    // same noun phrase across both surfaces. These tests lock the
    // pure helper's three copy branches — the chip dispatches the
    // full `interventionReviewOpener` on tap (already covered by the
    // opener tests above), so only the display label needs new
    // coverage here.

    @Test func caseReviewStarterHeadlineNamesFocus() {
        // Happy path — focus is present, lower-cased mid-sentence
        // after the em-dash.
        let intervention = makeIntervention(focus: "Filler reduction", title: "Filler drill")
        #expect(
            CoachContextBuilder.interventionReviewStarterHeadline(for: intervention)
                == "Review the active case — filler reduction"
        )
    }

    @Test func caseReviewStarterHeadlineFallsBackToTitleWhenFocusIsNil() {
        // Defensive — same fallback the card headline carries. Early
        // in the case cycle an intervention may not yet have a focus
        // phrase; the chip must never read "Review the active case — ."
        let intervention = makeIntervention(focus: nil, title: "Authority practice")
        #expect(
            CoachContextBuilder.interventionReviewStarterHeadline(for: intervention)
                == "Review the active case — authority practice"
        )
    }

    @Test func caseReviewStarterHeadlineFallsBackToTitleWhenFocusIsEmpty() {
        // Same fallback for the empty-string edge — case-engine
        // refactors that write `""` instead of `nil` shouldn't
        // produce an empty noun phrase.
        let intervention = makeIntervention(focus: "", title: "Pace control")
        #expect(
            CoachContextBuilder.interventionReviewStarterHeadline(for: intervention)
                == "Review the active case — pace control"
        )
    }
}

// MARK: - M24 deferred slate round 26 — Hypothesis acknowledgement chips
//
// Closes the round-25 future-move #1 — "Record user confirmation /
// rejection of the working hypothesis." After the coach replies to an
// `interventionReviewOpener` dispatch, the AskNoum view surfaces a
// three-chip row (confirmed / uncertain / rejected). A tap persists
// the verdict to `CoachMemory.hypothesisAcknowledgement` and dispatches
// a voice-shaped follow-up turn into the chat.
//
// Pure-helper layers under test:
//   • `CoachContextBuilder.shouldShowHypothesisAcknowledgement(messages:)` —
//     predicate that decides when the row renders. Matches the lead of
//     `interventionReviewOpenerLead`.
//   • `CoachContextBuilder.hypothesisAcknowledgementChips(for:)` — the
//     voice-shaped chip catalog; three branches per voice, all carrying
//     the same `CoachHypothesisConfidence` enum.
//   • `CoachHypothesisAcknowledgement.appliesTo(currentHypothesis:)` —
//     snapshot guard so a rebuild that rewrites the hypothesis re-prompts
//     the user.
//   • `CoachMemoryStore.noteHypothesisAcknowledgement(_:)` — persistence
//     mutation. Snapshots the current hypothesis so drift is detectable.
//
// Vision alignment: closes the "case formulation needs a reason for
// changing course" gap called out in `docs/VISION.md`. The user's
// verdict on the hypothesis is now durable case-file data, not an
// inference from chat tone.

@MainActor
@Suite("HypothesisAcknowledgementTests")
struct HypothesisAcknowledgementTests {

    // MARK: - Predicate

    @Test func shouldShowReturnsTrueWhenCoachRepliedToReviewOpener() {
        // Happy path: a case-review opener landed (user turn), the
        // coach replied (most-recent message), no later user turn.
        // The chip row eligible.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "\(CoachContextBuilder.interventionReviewOpenerLead) Timed for filler reduction, 4 followed reps in. Keep, adapt, or replace?"),
            CoachMessage(role: .coach, text: "Three reps in, your filler rate is down by 30%; I'd keep going for one more rep before I'd call it.", isPending: false),
        ]
        #expect(CoachContextBuilder.shouldShowHypothesisAcknowledgement(messages: messages) == true)
    }

    @Test func shouldShowReturnsFalseWhenLastMessageIsUserTurn() {
        // After the user replies to the case-review thread, the chip
        // row must collapse — the conversation has moved on and a
        // late ack on a stale coach reply would land out of order.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "\(CoachContextBuilder.interventionReviewOpenerLead) Timed for filler reduction, 4 followed reps in."),
            CoachMessage(role: .coach, text: "Three reps in, your filler rate is down."),
            CoachMessage(role: .user, text: "Tell me more about the trend."),
        ]
        #expect(CoachContextBuilder.shouldShowHypothesisAcknowledgement(messages: messages) == false)
    }

    @Test func shouldShowReturnsFalseWhenCoachReplyIsPending() {
        // While the model is composing, the chip row must not render
        // — there's no reply to react to. Pinning the pending guard
        // stops a flash-of-chips on the typing dots.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "\(CoachContextBuilder.interventionReviewOpenerLead) Timed for filler reduction."),
            CoachMessage(role: .coach, text: "", isPending: true),
        ]
        #expect(CoachContextBuilder.shouldShowHypothesisAcknowledgement(messages: messages) == false)
    }

    @Test func shouldShowReturnsFalseWhenUserTurnIsOrganicQuestion() {
        // A coach reply to a regular question (not the case-review
        // opener) must not surface the chip row — the row is the
        // case-review surface, not a generic "do you agree with me?"
        // pestering pattern.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "What was my filler rate this week?"),
            CoachMessage(role: .coach, text: "Your filler rate landed at 3.4 per minute this week.", isPending: false),
        ]
        #expect(CoachContextBuilder.shouldShowHypothesisAcknowledgement(messages: messages) == false)
    }

    @Test func shouldShowReturnsFalseOnEmptyMessages() {
        #expect(CoachContextBuilder.shouldShowHypothesisAcknowledgement(messages: []) == false)
    }

    // MARK: - Chip catalog

    @Test func chipCatalogIsThreeChipsPerVoice() {
        // The verdict palette must always offer the full three branches —
        // confirmed / uncertain / rejected — so the user has the same
        // expressive surface regardless of voice tone. A voice that
        // collapsed the catalog to two would deny the user the
        // "uncertain" middle option.
        for voice in [SpeakingStyleGoal.authoritative, .warm, .concise, .persuasive, .executive, .storytelling] {
            let chips = CoachContextBuilder.hypothesisAcknowledgementChips(for: voice)
            #expect(chips.count == 3, "voice \(voice) chip catalog missing branches")
            #expect(Set(chips.map(\.confidence)) == Set([.confirmed, .uncertain, .rejected]))
        }
        let nilChips = CoachContextBuilder.hypothesisAcknowledgementChips(for: nil)
        #expect(nilChips.count == 3)
        #expect(Set(nilChips.map(\.confidence)) == Set([.confirmed, .uncertain, .rejected]))
    }

    @Test func chipDispatchTextIsNeverEmpty() {
        // Defensive: the dispatched user turn lands in the chat thread.
        // An empty dispatch would create a blank user bubble and an
        // orphan coach turn.
        for voice in [SpeakingStyleGoal.authoritative, .warm, .concise, .persuasive, .executive, .storytelling, nil] as [SpeakingStyleGoal?] {
            let chips = CoachContextBuilder.hypothesisAcknowledgementChips(for: voice)
            for chip in chips {
                #expect(!chip.dispatchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                        "voice \(String(describing: voice)) confidence \(chip.confidence) has empty dispatch")
                #expect(!chip.label.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                        "voice \(String(describing: voice)) confidence \(chip.confidence) has empty label")
            }
        }
    }

    @Test func chipLabelsAvoidBannedPhrasings() {
        // Brand-voice rule scan — no exclamation marks, no "Let's",
        // no urgency framing. The chips are a verdict surface, not a
        // CTA chorus.
        let banned = ["!", "Let's", "let's", "hurry", "now or never"]
        for voice in [SpeakingStyleGoal.authoritative, .warm, .concise, .persuasive, .executive, .storytelling, nil] as [SpeakingStyleGoal?] {
            let chips = CoachContextBuilder.hypothesisAcknowledgementChips(for: voice)
            for chip in chips {
                for phrase in banned {
                    #expect(!chip.label.contains(phrase),
                            "voice \(String(describing: voice)) chip label contains banned phrase \(phrase)")
                    #expect(!chip.dispatchText.contains(phrase),
                            "voice \(String(describing: voice)) chip dispatch contains banned phrase \(phrase)")
                }
            }
        }
    }

    @Test func authoritativeVoiceUsesVerdictRegister() {
        // Voice-shape sanity: the authoritative coach's chips read as
        // verdicts ("Yes — that's the read"), not as agreement ("That
        // fits how I see it" is the warm coach's register). Catches a
        // copy-paste of the warm chips into the authoritative slot.
        let chips = CoachContextBuilder.hypothesisAcknowledgementChips(for: .authoritative)
        let confirmed = chips.first { $0.confidence == .confirmed }
        #expect(confirmed?.label == "Yes — that's the read")
    }

    @Test func conciseVoiceUsesOneWordLabels() {
        // The concise coach's chips compress to single tokens so the
        // verdict reads as fast as the voice expects.
        let chips = CoachContextBuilder.hypothesisAcknowledgementChips(for: .concise)
        let labels = chips.map(\.label)
        #expect(labels.contains("Matches"))
        #expect(labels.contains("Unsure"))
        #expect(labels.contains("Adapt"))
    }

    // MARK: - Snapshot guard

    @Test func appliesToReturnsTrueOnExactHypothesisMatch() {
        let ack = CoachHypothesisAcknowledgement(
            confidence: .confirmed,
            hypothesisSnapshot: "Filler reduction may be the highest-leverage focus because pace is steady; verify over more reps.",
            acknowledgedAt: Date()
        )
        #expect(ack.appliesTo(currentHypothesis: "Filler reduction may be the highest-leverage focus because pace is steady; verify over more reps.") == true)
    }

    @Test func appliesToReturnsTrueIgnoringSurroundingWhitespace() {
        // A trim-difference between a Codable round-trip and a freshly
        // built hypothesis must not invalidate an otherwise-matching ack.
        let ack = CoachHypothesisAcknowledgement(
            confidence: .confirmed,
            hypothesisSnapshot: "Filler reduction is the next lever.",
            acknowledgedAt: Date()
        )
        #expect(ack.appliesTo(currentHypothesis: "   Filler reduction is the next lever.   ") == true)
    }

    @Test func appliesToReturnsFalseOnHypothesisDrift() {
        // A memory rebuild that rewrote the hypothesis from a tentative
        // to a moderate phrasing must invalidate the ack — the user
        // hasn't yet confirmed the new read.
        let ack = CoachHypothesisAcknowledgement(
            confidence: .confirmed,
            hypothesisSnapshot: "Filler reduction may be the highest-leverage focus; verify over more reps.",
            acknowledgedAt: Date()
        )
        #expect(ack.appliesTo(currentHypothesis: "Filler reduction appears to be the highest-leverage focus; keep checking against future reps.") == false)
    }

    @Test func appliesToReturnsFalseOnNilOrEmptyCurrentHypothesis() {
        let ack = CoachHypothesisAcknowledgement(
            confidence: .confirmed,
            hypothesisSnapshot: "Filler reduction is the next lever.",
            acknowledgedAt: Date()
        )
        #expect(ack.appliesTo(currentHypothesis: nil) == false)
        #expect(ack.appliesTo(currentHypothesis: "") == false)
        #expect(ack.appliesTo(currentHypothesis: "   ") == false)
    }

    // MARK: - Store mutation + persistence

    @Test func noteHypothesisAcknowledgementPersistsAndReloads() {
        let suite = "coach-memory-hypAck-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "account-\(UUID().uuidString)"

        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        store.replaceForTesting(makeMemory(workingHypothesis: "Filler reduction is the next lever."))

        store.noteHypothesisAcknowledgement(.confirmed, at: Date(timeIntervalSince1970: 1_700_000_000))
        #expect(store.currentMemory?.hypothesisAcknowledgement?.confidence == .confirmed)
        #expect(store.currentMemory?.hypothesisAcknowledgement?.hypothesisSnapshot == "Filler reduction is the next lever.")

        let reloaded = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        #expect(reloaded.currentMemory?.hypothesisAcknowledgement?.confidence == .confirmed)
        #expect(reloaded.currentMemory?.hypothesisAcknowledgement?.hypothesisSnapshot == "Filler reduction is the next lever.")
    }

    @Test func noteHypothesisAcknowledgementIsNoOpWithoutWorkingHypothesis() {
        // Defensive: the chip row never renders without a working
        // hypothesis, but the store still guards. A no-op write here
        // prevents a memory with empty `workingHypothesis` from
        // accidentally persisting a snapshot of "".
        let suite = "coach-memory-hypAck-nopath-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "account-\(UUID().uuidString)"

        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        store.replaceForTesting(makeMemory(workingHypothesis: nil))
        store.noteHypothesisAcknowledgement(.confirmed)
        #expect(store.currentMemory?.hypothesisAcknowledgement == nil)
    }

    @Test func noteHypothesisAcknowledgementOverwritesPriorVerdict() {
        // The user reverses their mind on the same hypothesis. The
        // store carries the LATEST verdict, not a history list — that
        // pattern would balloon the case file.
        let suite = "coach-memory-hypAck-overwrite-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "account-\(UUID().uuidString)"

        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        store.replaceForTesting(makeMemory(workingHypothesis: "Filler reduction is the next lever."))

        store.noteHypothesisAcknowledgement(.confirmed, at: Date(timeIntervalSince1970: 1_000))
        store.noteHypothesisAcknowledgement(.rejected, at: Date(timeIntervalSince1970: 2_000))
        #expect(store.currentMemory?.hypothesisAcknowledgement?.confidence == .rejected)
        #expect(store.currentMemory?.hypothesisAcknowledgement?.acknowledgedAt == Date(timeIntervalSince1970: 2_000))
    }

    // MARK: - User-context surfacing

    @Test func userContextSurfacesAcknowledgementWhenApplied() {
        // The coach's next reply needs to know the user's verdict.
        // The context builder emits a CASE FORMULATION line carrying
        // the confidence label + the next-move instruction.
        var memory = makeMemory(workingHypothesis: "Filler reduction is the next lever.")
        memory.hypothesisAcknowledgement = CoachHypothesisAcknowledgement(
            confidence: .rejected,
            hypothesisSnapshot: "Filler reduction is the next lever.",
            acknowledgedAt: Date()
        )
        memory.currentLever = .fillerReduction

        let context = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: SpeakingRating.initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            recentProofs: [],
            bigMoment: nil,
            recentMomentOutcomes: [],
            forwardPlan: nil,
            latestRepNote: nil,
            coachMemory: memory,
            pendingRecommendation: nil,
            recommendationOutcomes: [],
            trends: []
        )
        #expect(context.contains("Hypothesis acknowledgement: user said the working hypothesis does not match"))
        #expect(context.contains("Treat the working hypothesis as falsified"))
    }

    @Test func userContextDropsStaleAcknowledgement() {
        // The hypothesis was rewritten after the ack landed. The
        // context block must NOT surface the stale verdict — it would
        // lead the coach to reinforce a read the user has not yet
        // confirmed.
        var memory = makeMemory(workingHypothesis: "Pace control is the next lever.")
        memory.hypothesisAcknowledgement = CoachHypothesisAcknowledgement(
            confidence: .confirmed,
            hypothesisSnapshot: "Filler reduction is the next lever.",  // OLD hypothesis
            acknowledgedAt: Date()
        )
        memory.currentLever = .paceControl

        let context = CoachContextBuilder.userContext(
            profile: nil,
            baseline: .empty,
            rating: SpeakingRating.initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            recentProofs: [],
            bigMoment: nil,
            recentMomentOutcomes: [],
            forwardPlan: nil,
            latestRepNote: nil,
            coachMemory: memory,
            pendingRecommendation: nil,
            recommendationOutcomes: [],
            trends: []
        )
        #expect(!context.contains("Hypothesis acknowledgement"))
    }

    // MARK: - Backward-compat decode

    @Test func coachMemoryDecodesWithoutAcknowledgementField() throws {
        // Memories persisted before round 26 must decode without a
        // `hypothesisAcknowledgement` key. The decoder uses
        // `decodeIfPresent`; this pins that contract so a future
        // refactor that flips it to `decode` would surface here.
        let legacyJSON = """
        {
            "updatedAt": 1700000000,
            "evidenceCount": 5,
            "evidenceConfidence": 2,
            "goalFit": "noLever",
            "strengths": [],
            "blockers": []
        }
        """.data(using: .utf8)!

        let decoded = try JSONDecoder().decode(CoachMemory.self, from: legacyJSON)
        #expect(decoded.hypothesisAcknowledgement == nil)
        #expect(decoded.evidenceCount == 5)
    }

    // MARK: - Case-review card acknowledgement surface (F4a)
    //
    // The Profile `CaseReviewCard` now offers the same confirm/question/reject
    // verdict AskNoum does, wired to the SAME store path. These pin the card's
    // pure eligibility + echo helpers so the surface can't drift from the
    // durable `appliesTo` snapshot contract.

    @Test func caseReviewOffersAckWhenHypothesisUnacknowledged() {
        let memory = makeMemory(workingHypothesis: "Filler reduction is the next lever.")
        #expect(CaseReviewCard.hasUnacknowledgedHypothesis(in: memory) == true)
        #expect(CaseReviewCard.acknowledgedEcho(for: memory) == nil)
    }

    @Test func caseReviewHidesAckOnceConfirmedForCurrentHypothesis() {
        var memory = makeMemory(workingHypothesis: "Filler reduction is the next lever.")
        memory.hypothesisAcknowledgement = CoachHypothesisAcknowledgement(
            confidence: .confirmed,
            hypothesisSnapshot: "Filler reduction is the next lever.",
            acknowledgedAt: Date()
        )
        #expect(CaseReviewCard.hasUnacknowledgedHypothesis(in: memory) == false)
        #expect(CaseReviewCard.acknowledgedEcho(for: memory) == "You confirmed this read.")
    }

    @Test func caseReviewReoffersAckOnHypothesisDrift() {
        // A memory rebuild rewrote the hypothesis; the prior ack snapshot no
        // longer applies, so the card must re-offer the verdict (and show no
        // stale echo).
        var memory = makeMemory(workingHypothesis: "Filler reduction is the next lever.")
        memory.hypothesisAcknowledgement = CoachHypothesisAcknowledgement(
            confidence: .confirmed,
            hypothesisSnapshot: "An older, differently-worded read.",
            acknowledgedAt: Date()
        )
        #expect(CaseReviewCard.hasUnacknowledgedHypothesis(in: memory) == true)
        #expect(CaseReviewCard.acknowledgedEcho(for: memory) == nil)
    }

    @Test func caseReviewNoAckWithoutWorkingHypothesis() {
        let memory = makeMemory(workingHypothesis: nil)
        #expect(CaseReviewCard.hasUnacknowledgedHypothesis(in: memory) == false)
        #expect(CaseReviewCard.acknowledgedEcho(for: memory) == nil)
    }

    @Test func caseReviewAckEchoCopyPerVerdictIsCalm() {
        let expected: [(CoachHypothesisConfidence, String)] = [
            (.confirmed, "You confirmed this read."),
            (.uncertain, "You're not sure about this read yet."),
            (.rejected,  "You asked the coach to adapt this read."),
        ]
        for (confidence, copy) in expected {
            var memory = makeMemory(workingHypothesis: "Filler reduction is the next lever.")
            memory.hypothesisAcknowledgement = CoachHypothesisAcknowledgement(
                confidence: confidence,
                hypothesisSnapshot: "Filler reduction is the next lever.",
                acknowledgedAt: Date()
            )
            #expect(CaseReviewCard.acknowledgedEcho(for: memory) == copy)
            // Brand voice: calm, never punitive — no exclamation even on reject.
            #expect(!copy.contains("!"))
        }
    }

    // MARK: - Helpers

    private func makeMemory(workingHypothesis: String?) -> CoachMemory {
        CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_700_000_000),
            evidenceCount: 5,
            evidenceConfidence: .moderate,
            goalFit: .noLever,
            strengths: [],
            blockers: [],
            workingHypothesis: workingHypothesis
        )
    }
}

// MARK: - Delivery Profile Tests (F3)
//
// The user-facing "how you come across" surface composes existing engines into
// four answers. These lock the pure decision logic (improvement selection,
// next-target priority, pattern copy, nil-omission) and the no-person-label
// contract without standing up heavy session fixtures — the underlying
// per-rep reads are already covered by the Composure/ConfidenceMarker suites.

@Suite("DeliveryProfile")
struct DeliveryProfileTests {

    private func trend(_ dim: String, prior: Double, recent: Double, _ dir: DerivedReadDirection) -> DerivedReadTrend {
        DerivedReadTrend(dimension: dim, recentMean: recent, priorMean: prior, recentCount: 5, priorCount: 5, direction: dir)
    }

    @Test func strongestImprovementPicksLargestDelta() {
        let trends = [
            trend("Composure", prior: 0.60, recent: 0.66, .improving),          // +0.06
            trend("Confidence markers", prior: 0.50, recent: 0.72, .improving), // +0.22 (wins)
            trend("Structural", prior: 0.70, recent: 0.60, .declining),
        ]
        let line = DeliveryProfile.strongestImprovement(in: trends)
        #expect(line?.contains("Confidence markers") == true)
        #expect(line?.contains("improved") == true)
    }

    @Test func strongestImprovementNilWithoutImprovingTrend() {
        let trends = [
            trend("Composure", prior: 0.60, recent: 0.60, .stable),
            trend("Structural", prior: 0.70, recent: 0.60, .declining),
        ]
        #expect(DeliveryProfile.strongestImprovement(in: trends) == nil)
    }

    @Test func nextTargetPrefersDecliningDimension() {
        let trends = [
            trend("Composure", prior: 0.60, recent: 0.66, .improving),
            trend("Confidence markers", prior: 0.72, recent: 0.55, .declining),
        ]
        let line = DeliveryProfile.nextTarget(in: trends, pattern: .clear)
        #expect(line?.contains("Confidence markers") == true)
        #expect(line?.contains("slipped") == true)
    }

    @Test func nextTargetFallsBackToTimidMarkers() {
        let trends = [trend("Composure", prior: 0.60, recent: 0.62, .stable)]
        let line = DeliveryProfile.nextTarget(in: trends, pattern: .timid)
        #expect(line?.contains("Confidence markers") == true)
    }

    @Test func nextTargetNamesLowestWeakStableOnlyBelowHalf() {
        let weak = [trend("Vocal energy steadiness", prior: 0.40, recent: 0.42, .stable)]
        #expect(DeliveryProfile.nextTarget(in: weak, pattern: .clear)?.contains("Vocal energy steadiness") == true)

        let solid = [trend("Vocal energy steadiness", prior: 0.70, recent: 0.71, .stable)]
        #expect(DeliveryProfile.nextTarget(in: solid, pattern: .clear) == nil)
    }

    @Test func patternLineIsHypothesisFramedNeverPersonLabel() {
        let clear = DeliveryProfile(pattern: .clear, evidenceDepth: 4, improvedLine: nil, pressureLine: nil, nextTargetLine: nil)
        let timid = DeliveryProfile(pattern: .timid, evidenceDepth: 4, improvedLine: nil, pressureLine: nil, nextTargetLine: nil)
        let forming = DeliveryProfile(pattern: .forming, evidenceDepth: 0, improvedLine: nil, pressureLine: nil, nextTargetLine: nil)

        #expect(clear.patternLine?.contains("reading as clear") == true)
        #expect(timid.patternLine?.contains("reading as tentative") == true)
        #expect(forming.patternLine == nil)
        for line in [clear.patternLine, timid.patternLine].compactMap({ $0 }) {
            #expect(!line.lowercased().contains("you are"))
            #expect(line.contains("these reps") || line.contains("recent reps"))
        }
    }

    @Test func buildReturnsNilWhenNoSignal() {
        // No sessions + no durable read -> forming, no lines -> nil (no empty shell).
        let profile = DeliveryProfile.build(
            sessions: [],
            snapshots: [],
            hedgingPerMinute: 3.0,
            paceBaseline: 130,
            deliveryRead: nil
        )
        #expect(profile == nil)
    }

    @Test func buildSurfacesDurablePatternEvenWithThinTrends() {
        // A characterised read carried forward must surface even when the trend
        // windows are too thin to produce improvement/target lines.
        let read = CoachDeliveryRead(dominantPattern: .clear, evidenceDepth: 4, tentativeLine: "x")
        let profile = DeliveryProfile.build(
            sessions: [],
            snapshots: [],
            hedgingPerMinute: 3.0,
            paceBaseline: 130,
            deliveryRead: read
        )
        #expect(profile?.pattern == .clear)
        #expect(profile?.patternLine != nil)
        #expect(profile?.improvedLine == nil)
    }
}

// MARK: - Weekly Coach Check-In Tests (F1)
//
// The bidirectional weekly check-in. These lock persistence + cap/ordering,
// the no-nag cadence gate, the all-empty no-op, and the user-reported /
// non-causal shape of the coach-context lines.

@Suite("WeeklyCheckInCopy")
struct WeeklyCheckInCopyTests {

    @Test func copyFramesCheckInAsSelfReportNotDiagnosis() {
        let combined = [
            WeeklyCheckInCopy.sheetBody,
            WeeklyCheckInCopy.noteTitle,
            WeeklyCheckInCopy.noteBody,
            WeeklyCheckInCopy.confidenceHelper,
            WeeklyCheckInCopy.drillHelper
        ].joined(separator: " ")

        #expect(combined.contains("Your words"))
        #expect(combined.contains("not a score"))
        #expect(combined.contains("your own read"))
        #expect(!combined.lowercased().contains("we know"))
        #expect(!combined.lowercased().contains("proof that"))
        #expect(!combined.lowercased().contains("diagnosis"))
    }

    @Test func promptIDsMatchPersistedCheckInFields() {
        #expect(WeeklyCheckInCopy.hardest.id == "hardest")
        #expect(WeeklyCheckInCopy.outsideApp.id == "outsideApp")
        #expect(WeeklyCheckInCopy.avoidedSaying.id == "avoidedSaying")
    }

    @Test func freeTextPromptsStayShortAndCoachLike() {
        let prompts = [
            WeeklyCheckInCopy.hardest,
            WeeklyCheckInCopy.outsideApp,
            WeeklyCheckInCopy.avoidedSaying
        ]

        for prompt in prompts {
            #expect(prompt.title.count <= 32)
            #expect(prompt.helper.count <= 72)
            #expect(prompt.placeholder.count <= 28)
            #expect(!prompt.title.contains("?") || prompt.title.hasSuffix("?"))
            #expect(!prompt.helper.lowercased().contains("score"))
        }
    }

    @Test func choiceQuestionsAvoidPerformanceReviewLanguage() {
        let combined = [
            WeeklyCheckInCopy.confidenceQuestion,
            WeeklyCheckInCopy.confidenceHelper,
            WeeklyCheckInCopy.drillQuestion,
            WeeklyCheckInCopy.drillHelper
        ].joined(separator: " ").lowercased()

        #expect(!combined.contains("performance review"))
        #expect(!combined.contains("grade"))
        #expect(!combined.contains("rate yourself"))
    }
}

@MainActor
@Suite("CoachCheckIn")
struct CoachCheckInStoreTests {

    @Test func recordPersistsAndReloadsNewestFirst() {
        let suite = "coachCheckIn-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "acct-\(UUID().uuidString)"
        let store = CoachCheckInStore(defaults: defaults, accountIDProvider: { accountID })

        store.record(hardest: "Saying no", at: Date(timeIntervalSince1970: 1_000))
        store.record(outsideApp: "Team standup", at: Date(timeIntervalSince1970: 2_000))
        #expect(store.checkIns.count == 2)
        #expect(store.checkIns.first?.outsideApp == "Team standup") // newest first

        let reloaded = CoachCheckInStore(defaults: defaults, accountIDProvider: { accountID })
        reloaded.reloadForCurrentAccount() // mirrors the auth reload path (init does not auto-load)
        #expect(reloaded.checkIns.count == 2)
        #expect(reloaded.checkIns.first?.outsideApp == "Team standup")
    }

    @Test func allEmptyRecordIsNoOp() {
        let suite = "coachCheckIn-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = CoachCheckInStore(defaults: defaults, accountIDProvider: { "a" })
        let result = store.record(hardest: "   ", outsideApp: nil, drillVerdict: nil, confidenceShift: nil, avoidedSaying: "   ")
        #expect(result == nil)
        #expect(store.checkIns.isEmpty)
    }

    @Test func capBoundsAtEightNewestFirst() {
        let suite = "coachCheckIn-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = CoachCheckInStore(defaults: defaults, accountIDProvider: { "a" })
        for i in 0..<12 {
            store.record(hardest: "week \(i)", at: Date(timeIntervalSince1970: Double(i) * 1_000))
        }
        #expect(store.checkIns.count == CoachCheckInStore.cap)
        #expect(store.checkIns.first?.hardest == "week 11")
    }

    @Test func cadenceGateIsNoNag() {
        let now = Date(timeIntervalSince1970: 1_000_000)
        #expect(CoachCheckInStore.isCheckInDue(latest: nil, now: now) == true)
        let recent = CoachCheckIn(recordedAt: now.addingTimeInterval(-3 * 86_400), hardest: "x")
        #expect(CoachCheckInStore.isCheckInDue(latest: recent, now: now) == false)
        let old = CoachCheckIn(recordedAt: now.addingTimeInterval(-7 * 86_400), hardest: "x")
        #expect(CoachCheckInStore.isCheckInDue(latest: old, now: now) == true)
    }

    @Test func contextLinesAreUserReportedAndNonCausal() {
        let checkIn = CoachCheckIn(
            hardest: "Pushback in reviews",
            outsideApp: "1:1 with my manager",
            drillVerdict: .stalled,
            confidenceShift: .lessSteady,
            avoidedSaying: "I softened the direct ask"
        )
        let lines = checkIn.coachContextLines
        #expect(lines.count == 5)
        #expect(lines.contains { $0.contains("Hardest this week") && $0.contains("Pushback in reviews") })
        #expect(lines.contains { $0.contains("outside the app") && $0.contains("1:1 with my manager") })
        #expect(lines.contains { $0.contains("the current drill felt stalled") })
        #expect(lines.contains { $0.contains("Confidence this week") && $0.contains("less steady") })
        #expect(lines.contains { $0.contains("What they avoided saying") && $0.contains("softened the direct ask") })
        #expect(!lines.joined(separator: " ").lowercased().contains("diagnosed"))
    }

    @Test func fieldsAreTrimmedAndBounded() {
        let long = String(repeating: "a", count: 500)
        let checkIn = CoachCheckIn(hardest: "  spaced   out  ", outsideApp: long, avoidedSaying: "  direct   ask  ")
        #expect(checkIn.hardest == "spaced out")
        #expect(checkIn.outsideApp?.count == CoachCheckIn.fieldCharacterLimit)
        #expect(checkIn.avoidedSaying == "direct ask")
    }

    @Test func recordPersistsConfidenceAndAvoidance() {
        let suite = "coachCheckIn-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "acct-\(UUID().uuidString)"
        let store = CoachCheckInStore(defaults: defaults, accountIDProvider: { accountID })

        let saved = store.record(
            confidenceShift: .moreSteady,
            avoidedSaying: "I avoided disagreeing in the meeting",
            at: Date(timeIntervalSince1970: 2_000)
        )

        #expect(saved?.confidenceShift == .moreSteady)
        #expect(saved?.avoidedSaying == "I avoided disagreeing in the meeting")

        let reloaded = CoachCheckInStore(defaults: defaults, accountIDProvider: { accountID })
        reloaded.reloadForCurrentAccount()
        #expect(reloaded.latest?.confidenceShift == .moreSteady)
        #expect(reloaded.latest?.avoidedSaying == "I avoided disagreeing in the meeting")
    }

    @Test func legacyCheckInDecodesWithoutConfidenceAndAvoidance() throws {
        let legacy = """
        {
            "id": "\(UUID().uuidString)",
            "recordedAt": 1700000000,
            "hardest": "Saying no",
            "outsideApp": "Team standup",
            "drillVerdict": "helped"
        }
        """.data(using: .utf8)!

        let decoded = try JSONDecoder().decode(CoachCheckIn.self, from: legacy)
        #expect(decoded.hardest == "Saying no")
        #expect(decoded.outsideApp == "Team standup")
        #expect(decoded.drillVerdict == .helped)
        #expect(decoded.confidenceShift == nil)
        #expect(decoded.avoidedSaying == nil)
    }
}

// MARK: - Big Moment Transfer Enrichment Tests (F4b)
//
// The "did your prep transfer?" signal must flow into BOTH the AI context
// (report.coachContextLine) and the case file (CoachTransferReview), stay
// user-reported (no causal claim), and decode on reports persisted before F4b.

@MainActor
@Suite("BigMomentTransferEnrichment")
struct BigMomentTransferEnrichmentTests {

    private func report(drillTransfer: ReportedDrillTransfer?, note: String? = nil) -> BigMomentOutcomeReport {
        BigMomentOutcomeReport(
            moment: BigMoment(title: "Q3 review", category: .review),
            outcome: .mixed,
            audienceResponse: .unclear,
            note: note,
            drillTransfer: drillTransfer
        )
    }

    @Test func coachContextLineIncludesDrillTransferAndStaysNonCausal() {
        let line = report(drillTransfer: .partly).coachContextLine
        #expect(line.contains("They felt their rehearsal partly carried"))
        #expect(!line.lowercased().contains("caused"))
        // Absent transfer -> no rehearsal clause (no fabricated signal).
        #expect(!report(drillTransfer: nil).coachContextLine.contains("their rehearsal"))
    }

    @Test func recordOutcomeCarriesDrillTransfer() {
        let suite = "bigMoment-transfer-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = BigMomentStore(defaults: defaults, accountIDProvider: { "a" })
        let moment = BigMoment(title: "Pitch", category: .presentation)
        let saved = store.recordOutcome(
            for: moment,
            outcome: .wentWell,
            audienceResponse: .engaged,
            note: nil,
            drillTransfer: .transferred
        )
        #expect(saved?.drillTransfer == .transferred)
    }

    @Test func transferReviewCarriesDrillTransferIntoCaseLine() {
        let review = CoachTransferReview(report: report(drillTransfer: .didNotTransfer))
        #expect(review.drillTransfer == .didNotTransfer)
        #expect(review.reportedOutcomeLine.contains("They felt their rehearsal didn't carry"))
    }

    @Test func outcomeReportDecodesWithoutDrillTransferField() throws {
        // Reports persisted before F4b must decode with drillTransfer == nil.
        let legacy = """
        {
            "id": "\(UUID().uuidString)",
            "momentID": "\(UUID().uuidString)",
            "momentTitle": "Old moment",
            "category": "interview",
            "outcome": "wentWell",
            "audienceResponse": "engaged",
            "recordedAt": 1700000000
        }
        """.data(using: .utf8)!
        let decoded = try JSONDecoder().decode(BigMomentOutcomeReport.self, from: legacy)
        #expect(decoded.drillTransfer == nil)
        #expect(decoded.outcome == .wentWell)
    }
}

// MARK: - Prep Session Readiness Tests (F2)
//
// The rehearsal readiness read extends the existing PrepSession flow (closing
// its documented "end-of-prep ready-signal" defer). These lock the level
// transitions, the prep-window bound (pre-moment reps excluded), remaining-
// shape naming, and the no-confidence-claim contract on the context line.

@Suite("PrepSessionReadiness")
struct PrepSessionReadinessTests {

    private func session(_ mode: PracticeMode, daysAfter offset: Int, from base: Date) -> PracticeSession {
        PracticeSession(
            transcript: "x",
            fillerWordCount: 0,
            duration: 60,
            date: base.addingTimeInterval(Double(offset) * 86_400),
            mode: mode
        )
    }

    private func plan() -> PrepSessionPlan {
        PrepSessionPlanner.plan(
            bigMoment: BigMoment(title: "Board pitch", category: .presentation),
            daysRemaining: 5,
            modeAvailability: .allAvailable
        )
    }

    @Test func notStartedWhenNoRepsSinceMoment() {
        let created = Date(timeIntervalSince1970: 1_000_000)
        let older = session(.timed, daysAfter: -2, from: created) // before -> excluded
        let r = PrepSessionPlanner.readiness(plan: plan(), sessions: [older], momentCreatedAt: created)
        #expect(r.level == .notStarted)
        #expect(r.coveredCount == 0)
        #expect(r.line.contains("No rehearsal reps"))
    }

    @Test func underwayWhenSomeShapesCovered() {
        let created = Date(timeIntervalSince1970: 1_000_000)
        let sessions = [
            session(.timed, daysAfter: 1, from: created),
            session(.suddenDeath, daysAfter: 2, from: created),
        ]
        let r = PrepSessionPlanner.readiness(plan: plan(), sessions: sessions, momentCreatedAt: created)
        #expect(r.level == .underway)
        #expect(r.coveredCount == 2)
        #expect(r.contextLine.contains("2 of 3"))
        #expect(r.line.contains("audience simulation")) // the remaining (IM) shape is named
    }

    @Test func rehearsedWhenAllShapesCovered() {
        let created = Date(timeIntervalSince1970: 1_000_000)
        let sessions = [
            session(.timed, daysAfter: 1, from: created),
            session(.suddenDeath, daysAfter: 2, from: created),
            session(.imConversation, daysAfter: 3, from: created),
        ]
        let r = PrepSessionPlanner.readiness(plan: plan(), sessions: sessions, momentCreatedAt: created)
        #expect(r.level == .rehearsed)
        #expect(r.coveredCount == 3)
        #expect(r.totalRepsInWindow == 3)
        #expect(r.contextLine.contains("all 3"))
    }

    @Test func windowExcludesPreMomentReps() {
        let created = Date(timeIntervalSince1970: 1_000_000)
        let sessions = [
            session(.timed, daysAfter: -5, from: created),      // before -> excluded
            session(.suddenDeath, daysAfter: 1, from: created), // after -> counts
        ]
        let r = PrepSessionPlanner.readiness(plan: plan(), sessions: sessions, momentCreatedAt: created)
        #expect(r.totalRepsInWindow == 1)
        #expect(r.coveredModes == [.suddenDeath])
    }

    @Test func contextLineReportsActivityNotConfidence() {
        let created = Date(timeIntervalSince1970: 1_000_000)
        let r = PrepSessionPlanner.readiness(
            plan: plan(),
            sessions: [session(.timed, daysAfter: 1, from: created)],
            momentCreatedAt: created
        )
        let lower = r.contextLine.lowercased()
        #expect(!lower.contains("will do well"))
        #expect(!lower.contains("ready to succeed"))
        #expect(!lower.contains("guaranteed"))
    }
}

// MARK: - Coach-Parity Readiness Tests (F5)
//
// The honesty instrument for stage 7. These lock the core contracts: validation
// is NEVER self-certified (capped at forming), cold start earns nothing, the
// transfer ladder, formulation needs user confirmation, and the coach-context
// claim-scaling always forbids parity claims.

@Suite("CoachParityReadiness")
struct CoachParityReadinessTests {

    private func memory(
        confidence: BaselineConfidence = .insufficient,
        lever: SkillArea? = nil,
        hypothesis: String? = nil,
        ack: CoachHypothesisAcknowledgement? = nil
    ) -> CoachMemory {
        CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_700_000_000),
            evidenceCount: 5,
            evidenceConfidence: confidence,
            currentLever: lever,
            goalFit: .noLever,
            strengths: [],
            blockers: [],
            workingHypothesis: hypothesis,
            hypothesisAcknowledgement: ack
        )
    }

    @Test func coldStartHasNothingEarned() {
        let r = CoachParityReadiness.build(memory: nil, sessionCount: 0, recommendationOutcomeCount: 0, transferReportCount: 0, checkInCount: 0)
        #expect(r.earnedCount == 0)
        #expect(r.status(for: .diagnosis) == .thin)
        #expect(r.status(for: .validation) == .thin)
    }

    @Test func validationIsNeverEarnedEvenWithManyTransfers() {
        // THE core honesty contract: the app cannot self-certify parity.
        let r = CoachParityReadiness.build(
            memory: memory(confidence: .stable, lever: .fillerReduction),
            sessionCount: 50,
            recommendationOutcomeCount: 50,
            transferReportCount: 99,
            checkInCount: 50
        )
        #expect(r.status(for: .validation) != .earned)
        #expect(r.status(for: .validation) == .forming)
    }

    @Test func transferLadderThinFormingEarned() {
        func transfer(_ count: Int) -> CoachParityReadiness.StageStatus {
            CoachParityReadiness.build(memory: nil, sessionCount: 0, recommendationOutcomeCount: 0, transferReportCount: count, checkInCount: 0).status(for: .transfer)
        }
        #expect(transfer(0) == .thin)
        #expect(transfer(1) == .forming)
        #expect(transfer(2) == .earned)
    }

    @Test func diagnosisEarnedWithModerateConfidenceAndLever() {
        let r = CoachParityReadiness.build(
            memory: memory(confidence: .moderate, lever: .fillerReduction),
            sessionCount: 5, recommendationOutcomeCount: 0, transferReportCount: 0, checkInCount: 0
        )
        #expect(r.status(for: .diagnosis) == .earned)
    }

    @Test func formulationEarnedOnlyWhenHypothesisConfirmed() {
        let hypothesis = "Filler reduction is the lever."
        let unconfirmed = CoachParityReadiness.build(
            memory: memory(hypothesis: hypothesis),
            sessionCount: 5, recommendationOutcomeCount: 0, transferReportCount: 0, checkInCount: 0
        )
        #expect(unconfirmed.status(for: .formulation) == .forming)

        let ack = CoachHypothesisAcknowledgement(confidence: .confirmed, hypothesisSnapshot: hypothesis, acknowledgedAt: Date())
        let confirmed = CoachParityReadiness.build(
            memory: memory(hypothesis: hypothesis, ack: ack),
            sessionCount: 5, recommendationOutcomeCount: 0, transferReportCount: 0, checkInCount: 0
        )
        #expect(confirmed.status(for: .formulation) == .earned)
    }

    @Test func contextLinesAlwaysForbidParityClaim() {
        let r = CoachParityReadiness.build(
            memory: memory(confidence: .stable, lever: .fillerReduction),
            sessionCount: 50, recommendationOutcomeCount: 50, transferReportCount: 99, checkInCount: 50
        )
        let joined = r.coachContextLines.joined(separator: " ").lowercased()
        #expect(joined.contains("never claim coach-parity"))
    }
}

// MARK: - Ask Noum voice-input notice (A2)
//
// The mic must never silently "do nothing": when voice can't proceed, the input
// bar shows an honest reason. Lock the pure reason → message mapping.

@Suite("AskNoumVoiceInputNotice")
struct AskNoumVoiceInputNoticeTests {
    @Test func noticeMapsEveryReasonAndNilWhenAvailable() {
        guard #available(iOS 17.0, *) else { return }
        #expect(AskNoumVoiceInput.notice(for: nil) == nil)
        #expect(AskNoumVoiceInput.notice(for: .permissionDenied)?.contains("Speech access") == true)
        #expect(AskNoumVoiceInput.notice(for: .microphoneDenied)?.contains("Mic access") == true)
        #expect(AskNoumVoiceInput.notice(for: .localeUnsupported)?.contains("language") == true)
        #expect(AskNoumVoiceInput.notice(for: .temporarilyUnavailable)?.contains("try again") == true)
    }

    @Test func onlyTransientFailuresKeepVoiceRetryable() {
        guard #available(iOS 17.0, *) else { return }
        #expect(AskNoumVoiceInput.reasonAllowsRetry(nil))
        #expect(AskNoumVoiceInput.reasonAllowsRetry(.temporarilyUnavailable))
        #expect(!AskNoumVoiceInput.reasonAllowsRetry(.permissionDenied))
        #expect(!AskNoumVoiceInput.reasonAllowsRetry(.microphoneDenied))
        #expect(!AskNoumVoiceInput.reasonAllowsRetry(.localeUnsupported))
    }
}

// MARK: - Ask Noum mode-launch suggestion (A3)
//
// Detects whether a coach reply points at a concrete practice mode so ONE
// tappable launch card can appear. Conservative: explicit names + a few
// high-confidence skill phrases map; ambiguous advice yields no card.

@Suite("AskNoumModeSuggestion")
struct AskNoumModeSuggestionTests {
    @Test func detectsExplicitModes() {
        #expect(AskNoumModeSuggestion.detect(in: "Do an Ah-Counter round next, target under 4 fillers.") == .ahCounterPractice)
        #expect(AskNoumModeSuggestion.detect(in: "Try a Sudden Death round to test composure.") == .suddenDeathPractice)
        #expect(AskNoumModeSuggestion.detect(in: "Try a Pressure Drill round to test composure.") == .suddenDeathPractice)
        #expect(AskNoumModeSuggestion.detect(in: "Run a difficult conversation rep next.") == .imPractice(scenario: nil, tone: nil))
        #expect(AskNoumModeSuggestion.detect(in: "Warm up with a Timed rep first.") == .timedPractice)
    }

    @Test func mapsHighConfidenceSkillPhrasesToTimed() {
        #expect(AskNoumModeSuggestion.detect(in: "Let's focus on vocal variety.") == .timedPractice)
        #expect(AskNoumModeSuggestion.detect(in: "For your next rep, vary your pitch more.") == .timedPractice)
    }

    @Test func returnsNilOnAmbiguousAdvice() {
        #expect(AskNoumModeSuggestion.detect(in: "Try to be more confident and own the room.") == nil)
        #expect(AskNoumModeSuggestion.detect(in: "That was a strong answer — nice work.") == nil)
    }

    @Test func fillerMentionsDoNotLaunchAhCounterUnlessCoachPrescribesTheDrill() {
        #expect(AskNoumModeSuggestion.detect(
            in: "Your filler words came back in the last rep; hold a pause before sentence two."
        ) == nil)
        #expect(AskNoumModeSuggestion.detect(
            in: "The filler pattern is worth watching, but start with a calmer opener first."
        ) == nil)
        #expect(AskNoumModeSuggestion.detect(
            in: "Run a filler drill next: one clean opener, then stop."
        ) == .ahCounterPractice)
    }

    @Test func labelsAreActionShaped() {
        #expect(AskNoumModeSuggestion.label(for: .timedPractice) == "Start Timed Practice")
        #expect(AskNoumModeSuggestion.label(for: .ahCounterPractice) == "Start Filler Control")
        #expect(AskNoumModeSuggestion.label(for: .suddenDeathPractice) == "Start Pressure Drill")
        #expect(AskNoumModeSuggestion.label(for: .imPractice(scenario: nil, tone: nil)) == "Start Conversation Practice")
    }

    @Test func launchableSuggestionsMapToQuickStartModes() {
        #expect(AskNoumModeSuggestion.quickStartMode(for: .timedPractice) == .timed)
        #expect(AskNoumModeSuggestion.quickStartMode(for: .suddenDeathPractice) == .suddenDeath)
        #expect(AskNoumModeSuggestion.quickStartMode(for: .ahCounterPractice) == .ahCounter)
        #expect(AskNoumModeSuggestion.quickStartMode(for: .imPractice(scenario: nil, tone: nil)) == .imConversation)
        #expect(AskNoumModeSuggestion.quickStartMode(for: .settings) == nil)
    }

    @Test func unratedPressureSuggestionFailsClosedAsOneTimedLaunch() throws {
        let launch = try #require(AskNoumModeSuggestion.launchProjection(
            in: "Try a Pressure Drill round to test composure.",
            modeAvailability: .failClosed,
            imAvailable: true
        ))

        #expect(launch.mode == .timed)
        #expect(launch.label == "Start Timed Practice")
        #expect(launch.quickStartMode == .timed)
        #expect(launch.destination == .timedPractice)
    }

    @Test func unavailableConversationSuggestionFailsClosedAsOneTimedLaunch() throws {
        let launch = try #require(AskNoumModeSuggestion.launchProjection(
            in: "Run a difficult conversation rep next.",
            modeAvailability: NextActionModeAvailability(
                suddenDeathAvailable: true,
                imConversationAvailable: false
            ),
            imAvailable: false
        ))

        #expect(launch.mode == .timed)
        #expect(launch.label == "Start Timed Practice")
        #expect(launch.quickStartMode == .timed)
        #expect(launch.destination == .timedPractice)
    }

    @Test func availableGatedSuggestionsKeepLabelsArmingAndRoutesAligned() throws {
        let pressure = try #require(AskNoumModeSuggestion.launchProjection(
            in: "Try a Pressure Drill round to test composure.",
            modeAvailability: .allAvailable,
            imAvailable: true
        ))
        #expect(pressure.mode == .suddenDeath)
        #expect(pressure.label == "Start Pressure Drill")
        #expect(pressure.quickStartMode == .suddenDeath)
        #expect(pressure.destination == .suddenDeathPractice)

        let conversation = try #require(AskNoumModeSuggestion.launchProjection(
            in: "Run a difficult conversation rep next.",
            modeAvailability: .allAvailable,
            imAvailable: true
        ))
        #expect(conversation.mode == .imConversation)
        #expect(conversation.label == "Start Conversation Practice")
        #expect(conversation.quickStartMode == .imConversation)
        #expect(conversation.destination == .imPractice(scenario: nil, tone: nil))
    }

    @Test func tapTimeImLossCannotArmOrRouteTheRenderedConversationMode() throws {
        let rendered = try #require(AskNoumModeSuggestion.launchProjection(
            in: "Run a difficult conversation rep next.",
            modeAvailability: .allAvailable,
            imAvailable: true
        ))
        #expect(rendered.quickStartMode == .imConversation)

        // Keep the decision-time snapshot deliberately stale to prove the
        // live IM guard, not only the snapshot, closes the render-to-tap race.
        let tapped = rendered.resolvingForTap(
            modeAvailability: .allAvailable,
            imAvailable: false
        )
        #expect(tapped.mode == .timed)
        #expect(tapped.label == "Start Timed Practice")
        #expect(tapped.quickStartMode == .timed)
        #expect(tapped.destination == .timedPractice)
    }

    @Test func capabilityGainDoesNotUpgradeAnAlreadyRenderedTimedFallback() throws {
        let rendered = try #require(AskNoumModeSuggestion.launchProjection(
            in: "Run a difficult conversation rep next.",
            modeAvailability: .failClosed,
            imAvailable: false
        ))

        let tapped = rendered.resolvingForTap(
            modeAvailability: .allAvailable,
            imAvailable: true
        )
        #expect(tapped.mode == .timed)
        #expect(tapped.label == "Start Timed Practice")
        #expect(tapped.quickStartMode == .timed)
        #expect(tapped.destination == .timedPractice)
    }
}

