// MARK: - M26 Vocal Energy Metrics Tests
//
// Per VISION roadmap #2 (Delivery intelligence). VocalEnergyMetrics
// captures aggregate RMS amplitude + steadiness per session so the
// coach has a HOW-THEY-SOUNDED signal alongside the WHAT-THEY-SAID
// metrics. Tests pin the accumulator math, the thin-data gate, and
// the Codable round-trip on PracticeSession (backwards compatibility
// with sessions persisted before the field existed).

@Suite("VocalEnergyMetrics")
struct VocalEnergyMetricsTests {

    @Test func computeOnSilenceProducesZeros() {
        let silent = Array(repeating: 0.0, count: 100)
        let m = VocalEnergyAccumulator.compute(samples: silent)
        #expect(m.meanLevel == 0)
        #expect(m.peakLevel == 0)
        #expect(m.stdDeviation == 0)
        #expect(m.coefficientOfVariation == 0)
        // Steadiness on silence is 0 (no signal to be steady about);
        // guards against the CV divide-by-zero path producing
        // misleading "perfect steadiness" on a silent rep.
        #expect(m.steadiness == 1.0 || m.steadiness == 0.0,
                "Silence steadiness is the divide-by-zero edge; pinned for documentation")
    }

    @Test func computeOnConstantLevelIsMaximallySteady() {
        let flat = Array(repeating: 0.45, count: 200)
        let m = VocalEnergyAccumulator.compute(samples: flat)
        // Summing 200 identical doubles accumulates floating-point error, so
        // compare within a tolerance rather than exact equality.
        #expect(abs(m.meanLevel - 0.45) < 0.0001)
        #expect(abs(m.peakLevel - 0.45) < 0.0001)
        #expect(m.stdDeviation < 0.0001)
        #expect(m.coefficientOfVariation < 0.0001)
        #expect(m.steadiness > 0.999)
    }

    @Test func computeOnAlternatingSignalIsVariable() {
        // Alternating between 0.20 and 0.60 produces CV ≈ 0.5 →
        // steadiness ≈ 0.5. Catches "label drift" if anyone retunes
        // the CV→steadiness mapping.
        let alt = (0..<200).map { i in i.isMultiple(of: 2) ? 0.20 : 0.60 }
        let m = VocalEnergyAccumulator.compute(samples: alt)
        #expect(m.meanLevel > 0.39 && m.meanLevel < 0.41)
        #expect(m.coefficientOfVariation > 0.4 && m.coefficientOfVariation < 0.6)
        #expect(m.steadiness > 0.4 && m.steadiness < 0.6)
    }

    @Test func accumulatorReturnsNilBelowSampleFloor() {
        let acc = VocalEnergyAccumulator()
        // Default floor is 30 samples (≈0.75s at 40Hz envelope rate).
        for _ in 0..<10 { acc.append(level: 0.4) }
        #expect(acc.finalize() == nil, "Below floor should return nil — no fabricated read on thin data")
    }

    @Test func accumulatorReturnsMetricsAtSampleFloor() {
        let acc = VocalEnergyAccumulator()
        for _ in 0..<VocalEnergyAccumulator.minimumSampleFloor { acc.append(level: 0.4) }
        let m = acc.finalize()
        #expect(m != nil)
        #expect(m?.sampleCount == VocalEnergyAccumulator.minimumSampleFloor)
    }

    @Test func accumulatorResetClearsSamples() {
        let acc = VocalEnergyAccumulator()
        for _ in 0..<60 { acc.append(level: 0.5) }
        acc.reset()
        #expect(acc.currentSampleCount() == 0)
        #expect(acc.finalize() == nil, "Reset followed by finalize should produce nothing")
    }

    @Test func qualitativeReadoutLabelsByEnergyAndSteadiness() {
        // Verify the four energy buckets × two steadiness buckets
        // produce the expected coach-voice labels. This is what
        // shows up in CoachContextBuilder.userContext as the
        // "Vocal: <label>" tail on RECENT session lines.
        let lowSteady = VocalEnergyMetrics(meanLevel: 0.10, peakLevel: 0.20, stdDeviation: 0.01, coefficientOfVariation: 0.10, steadiness: 0.90, sampleCount: 100)
        #expect(lowSteady.qualitativeReadout == "low energy, steady")
        let engagedVariable = VocalEnergyMetrics(meanLevel: 0.50, peakLevel: 0.90, stdDeviation: 0.25, coefficientOfVariation: 0.50, steadiness: 0.50, sampleCount: 100)
        #expect(engagedVariable.qualitativeReadout == "engaged energy, mostly steady")
        let highVeryVariable = VocalEnergyMetrics(meanLevel: 0.70, peakLevel: 1.0, stdDeviation: 0.50, coefficientOfVariation: 0.80, steadiness: 0.20, sampleCount: 100)
        #expect(highVeryVariable.qualitativeReadout == "high energy, very variable")
    }

    @Test func codableRoundTripPreservesAllFields() throws {
        let original = VocalEnergyMetrics(
            meanLevel: 0.45,
            peakLevel: 0.87,
            stdDeviation: 0.12,
            coefficientOfVariation: 0.27,
            steadiness: 0.73,
            sampleCount: 480
        )
        let data = try JSONEncoder().encode(original)
        let decoded = try JSONDecoder().decode(VocalEnergyMetrics.self, from: data)
        #expect(decoded == original)
    }

    @Test func practiceSessionDecodingHandlesMissingVocalEnergyField() throws {
        // Simulate an older persisted PracticeSession (pre-M26) that
        // doesn't have a `vocalEnergyMetrics` key. Must decode cleanly
        // with the field set to nil — VISION dev rule on Codable
        // backwards compatibility.
        let json = """
        {
          "id": "11111111-1111-1111-1111-111111111111",
          "transcript": "test",
          "fillerWordCount": 2,
          "duration": 60,
          "date": -10000,
          "mode": "timed",
          "insights": [],
          "pressureLevel": 1,
          "isRated": false
        }
        """.data(using: .utf8)!
        let decoded = try JSONDecoder().decode(PracticeSession.self, from: json)
        #expect(decoded.vocalEnergyMetrics == nil)
        #expect(decoded.fillerWordCount == 2)
    }
}

// MARK: - M27 Composure Read Tests
//
// ComposureReadEngine composes vocal energy steadiness + pitch
// variation + pause filled-ratio + hedging rate into a single
// 0-1 composure score. Pure function over what the rep already
// produced. Tests pin:
//   - Score math at the channel-mixing level
//   - Honest-about-thin-data gate (returns nil below 2 channels)
//   - Pitch CV bucket mapping
//   - Qualitative label coverage
//   - Channel-list readout when N channels contribute

@Suite("ComposureReadEngine")
struct ComposureReadEngineTests {

    private func makeSession(
        vocalEnergy: VocalEnergyMetrics? = nil,
        pitch: PitchMetrics? = nil,
        pause: PauseMetrics? = nil
    ) -> PracticeSession {
        PracticeSession(
            transcript: "test rep",
            fillerWordCount: 0,
            duration: 60,
            date: Date(),
            mode: .timed,
            pauseMetrics: pause,
            pitchMetrics: pitch,
            vocalEnergyMetrics: vocalEnergy
        )
    }

    @Test func returnsNilWhenNoChannelsContribute() {
        let session = makeSession()
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: nil)
        #expect(read == nil, "Zero channels → nil; engine must not fabricate")
    }

    @Test func returnsNilWhenOnlyOneChannelContributes() {
        // Only vocal energy present — below the 2-channel floor.
        let energy = VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.6, stdDeviation: 0.05, coefficientOfVariation: 0.12, steadiness: 0.88, sampleCount: 100)
        let session = makeSession(vocalEnergy: energy)
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: nil)
        #expect(read == nil, "1 channel < 2-channel floor → nil")
    }

    @Test func twoChannelsProduceRead() {
        let energy = VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.6, stdDeviation: 0.05, coefficientOfVariation: 0.12, steadiness: 0.88, sampleCount: 100)
        let session = makeSession(vocalEnergy: energy)
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: 2.0)
        #expect(read != nil)
        #expect(read?.contributingChannels == 2)
        #expect(read?.inputs.vocalEnergyContributed == true)
        #expect(read?.inputs.hedgingContributed == true)
    }

    @Test func allFourChannelsContributeWhenAvailable() {
        let energy = VocalEnergyMetrics(meanLevel: 0.45, peakLevel: 0.7, stdDeviation: 0.06, coefficientOfVariation: 0.13, steadiness: 0.87, sampleCount: 100)
        let pitch = PitchMetrics(meanHz: 150, stdHz: 30, voicedRatio: 0.7, windowCount: 50)
        let pause = PauseMetrics(count: 5, meanSeconds: 1.2, longestSeconds: 2.5, filledRatio: 0.20)
        let session = makeSession(vocalEnergy: energy, pitch: pitch, pause: pause)
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: 1.0)
        #expect(read?.contributingChannels == 4)
        // All four contribute; score is the mean of 4 channel scores.
        #expect(read?.score ?? 0 > 0.7, "All-channels-good session reads as high composure")
    }

    @Test func monotonePitchPenalizesScore() {
        let energy = VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.5, stdDeviation: 0.02, coefficientOfVariation: 0.05, steadiness: 0.95, sampleCount: 100)
        // Very monotone — CV ≈ 0.05 → pitch channel scores 0.4
        let monotonePitch = PitchMetrics(meanHz: 150, stdHz: 7.5, voicedRatio: 0.8, windowCount: 50)
        let session = makeSession(vocalEnergy: energy, pitch: monotonePitch)
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: nil)
        // Channels: vocal energy 0.95 + pitch 0.4 → mean ≈ 0.675
        #expect(read?.score ?? 0 < 0.75)
        #expect(read?.score ?? 0 > 0.6)
    }

    @Test func highFilledPauseRatioPenalizesScore() {
        // 80% of pauses filled → pause channel scores 0.20.
        let energy = VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.5, stdDeviation: 0.02, coefficientOfVariation: 0.05, steadiness: 0.95, sampleCount: 100)
        let pause = PauseMetrics(count: 5, meanSeconds: 0.8, longestSeconds: 1.5, filledRatio: 0.80)
        let session = makeSession(vocalEnergy: energy, pause: pause)
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: nil)
        // 0.95 + 0.20 → mean ≈ 0.575
        #expect(read?.score ?? 0 < 0.65)
        #expect(read?.score ?? 0 > 0.50)
    }

    @Test func highHedgingPenalizesScore() {
        let energy = VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.5, stdDeviation: 0.02, coefficientOfVariation: 0.05, steadiness: 0.95, sampleCount: 100)
        let session = makeSession(vocalEnergy: energy)
        // 7 hedges/min → hedge score 0.10
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: 7.0)
        #expect(read?.contributingChannels == 2)
        // 0.95 + 0.10 → mean ≈ 0.525
        #expect(read?.score ?? 0 < 0.60)
    }

    @Test func qualitativeLabelCoversAllBuckets() {
        #expect(ComposureReadEngine.qualitativeLabel(score: 0.95).contains("held"))
        #expect(ComposureReadEngine.qualitativeLabel(score: 0.70).contains("mostly held"))
        #expect(ComposureReadEngine.qualitativeLabel(score: 0.50).contains("mixed"))
        #expect(ComposureReadEngine.qualitativeLabel(score: 0.30).contains("thin"))
        #expect(ComposureReadEngine.qualitativeLabel(score: 0.10).contains("unsettled"))
    }

    @Test func channelListReadoutHandlesMultipleChannels() {
        let oneChannel = ComposureRead.Inputs(vocalEnergyContributed: true, pitchContributed: false, pauseQualityContributed: false, hedgingContributed: false)
        #expect(ComposureReadEngine.readChannelList(inputs: oneChannel) == "vocal energy")

        let twoChannels = ComposureRead.Inputs(vocalEnergyContributed: true, pitchContributed: true, pauseQualityContributed: false, hedgingContributed: false)
        #expect(ComposureReadEngine.readChannelList(inputs: twoChannels) == "vocal energy + pitch")

        let allFour = ComposureRead.Inputs(vocalEnergyContributed: true, pitchContributed: true, pauseQualityContributed: true, hedgingContributed: true)
        let list = ComposureReadEngine.readChannelList(inputs: allFour)
        #expect(list.contains("vocal energy") && list.contains("pitch") && list.contains("pause quality") && list.contains("hedging rate"))
    }

    @Test func readoutPrefixIsTentativeWhenFewerChannelsContribute() {
        let energy = VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.5, stdDeviation: 0.02, coefficientOfVariation: 0.05, steadiness: 0.95, sampleCount: 100)
        let session = makeSession(vocalEnergy: energy)
        let read = ComposureReadEngine.derive(session: session, hedgingPerMinute: 2.0)
        // 2 channels → "Early composure read" (tentative prefix)
        #expect(read?.readout.contains("Early composure read") == true)
    }

    @Test func codableRoundTripPreservesAllFields() throws {
        let inputs = ComposureRead.Inputs(vocalEnergyContributed: true, pitchContributed: false, pauseQualityContributed: true, hedgingContributed: true)
        let original = ComposureRead(score: 0.72, contributingChannels: 3, inputs: inputs, readout: "Composure: mostly held — a couple of channels wobbled (from vocal energy, pause quality + hedging rate)")
        let data = try JSONEncoder().encode(original)
        let decoded = try JSONDecoder().decode(ComposureRead.self, from: data)
        #expect(decoded == original)
    }
}

// MARK: - M28 Confidence Marker Engine Tests
//
// ConfidenceMarkerEngine composes hedging density + filler density +
// pace consistency + composure carryover into a 0-1 confidence-marker
// score. Tests pin:
//   - 2-channel minimum (returns nil below)
//   - Per-channel score mapping
//   - Pace-consistency channel skips on too-short / too-few-words reps
//   - Qualitative label coverage
//   - Channel-list readout
//   - Codable round-trip
//
// Per VISION: reads MARKERS, not the person. Copy never asserts
// "the user is unconfident" — only "this rep read as tentative".

@Suite("ConfidenceMarkerEngine")
struct ConfidenceMarkerEngineTests {

    private func makeSession(
        transcript: String = "hello this is a test rep with several words to compute pace from honestly",
        fillerCount: Int = 0,
        duration: TimeInterval = 60
    ) -> PracticeSession {
        PracticeSession(
            transcript: transcript,
            fillerWordCount: fillerCount,
            duration: duration,
            date: Date(),
            mode: .timed
        )
    }

    @Test func returnsNilWhenOnlyOneChannelContributes() {
        let session = PracticeSession(
            transcript: "x",
            fillerWordCount: 0,
            duration: 0,
            date: Date(),
            mode: .timed
        )
        // duration 0 → filler density channel skips. transcript empty
        // + duration 0 → pace channel skips. No hedging, no composure.
        // No channels available → nil.
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: nil,
            paceWPM: nil,
            composure: nil
        )
        #expect(read == nil)
    }

    @Test func twoChannelsProduceRead() {
        // Hedging + filler density (duration > 0 → filler density
        // contributes).
        let session = makeSession(fillerCount: 2, duration: 60)
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: 2.0,
            paceWPM: nil,
            composure: nil
        )
        #expect(read != nil)
        #expect(read?.contributingChannels == 2)
        #expect(read?.inputs.hedgingContributed == true)
        #expect(read?.inputs.fillerDensityContributed == true)
        #expect(read?.inputs.paceConsistencyContributed == false)
        #expect(read?.inputs.composureContributed == false)
    }

    @Test func cleanRepReadsAsHighConfidence() {
        // 0 hedging, 0 fillers, on-baseline pace, high composure
        let energy = VocalEnergyMetrics(meanLevel: 0.45, peakLevel: 0.55, stdDeviation: 0.03, coefficientOfVariation: 0.07, steadiness: 0.93, sampleCount: 100)
        let session = PracticeSession(
            transcript: "this is a clean delivery with about thirteen words spoken at a steady pace",
            fillerWordCount: 0,
            duration: 60,
            date: Date(),
            mode: .timed,
            vocalEnergyMetrics: energy
        )
        // Estimated WPM ~14/min → far from any realistic baseline.
        // Skip pace channel by passing nil baseline. Composure 0.93.
        let composure = ComposureRead(
            score: 0.93,
            contributingChannels: 2,
            inputs: ComposureRead.Inputs(vocalEnergyContributed: true, pitchContributed: false, pauseQualityContributed: false, hedgingContributed: true),
            readout: "test"
        )
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: 0,
            paceWPM: nil,
            composure: composure
        )
        // Channels: hedging 1.0 + filler 1.0 + composure 0.93 → mean ≈ 0.977
        #expect(read?.score ?? 0 > 0.90)
        #expect(read?.contributingChannels == 3)
    }

    @Test func heavyHedgingPenalizesScore() {
        let session = makeSession(fillerCount: 0, duration: 60)
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: 7.0,
            paceWPM: nil,
            composure: nil
        )
        // hedging 0.10 + filler 1.0 → mean 0.55
        #expect(read?.score ?? 0 < 0.60)
        #expect(read?.score ?? 0 > 0.50)
    }

    @Test func heavyFillerDensityPenalizesScore() {
        let session = makeSession(fillerCount: 8, duration: 60)
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: 0,
            paceWPM: nil,
            composure: nil
        )
        // hedging 1.0 + filler 0.15 → mean 0.575
        #expect(read?.score ?? 0 < 0.60)
        #expect(read?.score ?? 0 > 0.55)
    }

    @Test func paceChannelSkipsOnShortReps() {
        // Duration below the 15s floor — pace channel must NOT contribute
        let session = makeSession(transcript: "a few words", fillerCount: 1, duration: 5)
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: 1.0,
            paceWPM: 150,
            composure: nil
        )
        #expect(read?.inputs.paceConsistencyContributed == false)
    }

    @Test func paceChannelContributesOnLongerReps() {
        // Long enough + words enough that pace channel can contribute
        let manyWords = Array(repeating: "word", count: 50).joined(separator: " ")
        let session = makeSession(transcript: manyWords, fillerCount: 0, duration: 30)
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: 1.0,
            paceWPM: 100,  // baseline ~100 wpm; session = 50 words / 0.5 min = 100 wpm → perfect match
            composure: nil
        )
        #expect(read?.inputs.paceConsistencyContributed == true)
    }

    @Test func paceDriftPenalizesPaceChannelScore() {
        let manyWords = Array(repeating: "x", count: 30).joined(separator: " ")
        let session = makeSession(transcript: manyWords, fillerCount: 0, duration: 60)
        // 30 words / 60s = 30 wpm; baseline = 150 wpm → 80% delta → score 0.20
        let read = ConfidenceMarkerEngine.derive(
            session: session,
            hedgingPerMinute: 0,
            paceWPM: 150,
            composure: nil
        )
        // hedging 1.0 + filler 1.0 + pace 0.20 → mean ≈ 0.733
        #expect(read?.contributingChannels == 3)
        #expect(read?.score ?? 0 > 0.65)
        #expect(read?.score ?? 0 < 0.80)
    }

    @Test func qualitativeLabelCoversAllBuckets() {
        #expect(ConfidenceMarkerEngine.qualitativeLabel(score: 0.95).contains("clean"))
        #expect(ConfidenceMarkerEngine.qualitativeLabel(score: 0.70).contains("mostly clean"))
        #expect(ConfidenceMarkerEngine.qualitativeLabel(score: 0.50).contains("mixed"))
        #expect(ConfidenceMarkerEngine.qualitativeLabel(score: 0.30).contains("heavy"))
        #expect(ConfidenceMarkerEngine.qualitativeLabel(score: 0.10).contains("very heavy"))
    }

    @Test func channelListReadout() {
        let two = ConfidenceMarkerRead.Inputs(hedgingContributed: true, fillerDensityContributed: true, paceConsistencyContributed: false, composureContributed: false)
        #expect(ConfidenceMarkerEngine.channelList(inputs: two) == "hedging density + filler density")
        let all = ConfidenceMarkerRead.Inputs(hedgingContributed: true, fillerDensityContributed: true, paceConsistencyContributed: true, composureContributed: true)
        let listAll = ConfidenceMarkerEngine.channelList(inputs: all)
        #expect(listAll.contains("hedging") && listAll.contains("filler") && listAll.contains("pace") && listAll.contains("composure"))
    }

    @Test func readoutDoesNotMakePersonalAssertions() {
        // Anti-overclaim: the readout must say "this rep" or "markers",
        // never "you sound" or "the user is". Per VISION:
        // "Inferred psychological or interpersonal patterns must be
        // framed as coach hypotheses, never facts or diagnoses."
        let allInputs = ConfidenceMarkerRead.Inputs(hedgingContributed: true, fillerDensityContributed: true, paceConsistencyContributed: true, composureContributed: true)
        let readout = ConfidenceMarkerEngine.readoutCopy(score: 0.2, inputs: allInputs)
        #expect(!readout.lowercased().contains("you sound"), "Readout must read markers, not the person")
        #expect(!readout.lowercased().contains("you are"), "Readout must read markers, not the person")
        #expect(!readout.lowercased().contains("you're"), "Readout must read markers, not the person")
        #expect(readout.lowercased().contains("markers"), "Readout names the markers explicitly")
    }

    @Test func codableRoundTripPreservesAllFields() throws {
        let inputs = ConfidenceMarkerRead.Inputs(hedgingContributed: true, fillerDensityContributed: false, paceConsistencyContributed: true, composureContributed: true)
        let original = ConfidenceMarkerRead(score: 0.65, contributingChannels: 3, inputs: inputs, readout: "Confidence markers: mostly clean")
        let data = try JSONEncoder().encode(original)
        let decoded = try JSONDecoder().decode(ConfidenceMarkerRead.self, from: data)
        #expect(decoded == original)
    }
}

// MARK: - M29 Structural Read Engine Tests
//
// StructuralReadEngine composes per-rep categoryRatings (Opening /
// Structure / Depth / Close, each Good/OK/Could improve) into a 0-1
// structural-quality score. Tests pin:
//   - 2-dimension minimum (returns nil below)
//   - FeedbackRating → numeric score mapping
//   - All-Good composite + all-Could-improve composite
//   - strongestAndWeakest attribution
//   - Qualitative label coverage
//   - Tentative prefix on ≤2 dimensions

@Suite("StructuralReadEngine")
struct StructuralReadEngineTests {

    @Test func returnsNilWhenZeroDimensionsContribute() {
        let read = StructuralReadEngine.derive(categoryRatings: [:])
        #expect(read == nil)
    }

    @Test func returnsNilWhenOnlyOneDimensionContributes() {
        let read = StructuralReadEngine.derive(categoryRatings: ["Opening": "Good"])
        #expect(read == nil, "1 dimension < 2 minimum")
    }

    @Test func ignoresUnknownRatingStrings() {
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening": "Mediocre",       // not a FeedbackRating raw value
            "Structure": "BadValue",     // not a FeedbackRating raw value
        ])
        #expect(read == nil, "Unknown rating strings should not count as contributing")
    }

    @Test func twoDimensionsProduceReadWithTentativePrefix() {
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening": "Good",
            "Close":   "OK",
        ])
        #expect(read != nil)
        #expect(read?.contributingDimensions == 2)
        #expect(read?.readout.contains("Early structural read") == true,
                "≤2 dimensions reads as tentative per VISION dev rule")
    }

    @Test func threeDimensionsProduceConfidentPrefix() {
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening": "Good",
            "Structure": "Good",
            "Close":   "Good",
        ])
        #expect(read?.readout.contains("Early") == false,
                "≥3 dimensions should drop the 'Early' prefix")
        #expect(read?.readout.contains("Structural read") == true)
    }

    @Test func allGoodProducesMaxScore() {
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening":   "Good",
            "Structure": "Good",
            "Depth":     "Good",
            "Close":     "Good",
        ])
        #expect(read?.score == 1.0)
        #expect(read?.contributingDimensions == 4)
    }

    @Test func allCouldImproveProducesMinScore() {
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening":   "Could improve",
            "Structure": "Could improve",
            "Depth":     "Could improve",
            "Close":     "Could improve",
        ])
        #expect(read?.score == 0.0)
    }

    @Test func mixedRatingsAverageCorrectly() {
        // Good (1.0) + OK (0.5) + Could improve (0.0) → mean 0.5
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening":   "Good",
            "Structure": "OK",
            "Close":     "Could improve",
        ])
        #expect(read?.score == 0.5)
    }

    @Test func scoreFunctionMapsRatingsCorrectly() {
        #expect(StructuralReadEngine.score(forRating: "Good") == 1.0)
        #expect(StructuralReadEngine.score(forRating: "OK") == 0.5)
        #expect(StructuralReadEngine.score(forRating: "Could improve") == 0.0)
        #expect(StructuralReadEngine.score(forRating: nil) == nil)
        #expect(StructuralReadEngine.score(forRating: "Unknown") == nil)
    }

    @Test func strongestAndWeakestIdentifiesExtremes() {
        let inputs = StructuralRead.Inputs(
            openingRating: "Good",
            structureRating: "Could improve",
            depthRating: "OK",
            closeRating: "Good"
        )
        let pair = StructuralReadEngine.strongestAndWeakest(inputs: inputs)
        #expect(pair?.strongest == "opening", "First-encountered tied-Good wins")
        #expect(pair?.weakest == "structure")
    }

    @Test func strongestAndWeakestReturnsNilWhenNoDimensions() {
        let inputs = StructuralRead.Inputs(
            openingRating: nil,
            structureRating: nil,
            depthRating: nil,
            closeRating: nil
        )
        #expect(StructuralReadEngine.strongestAndWeakest(inputs: inputs) == nil)
    }

    @Test func qualitativeLabelCoversAllBuckets() {
        #expect(StructuralReadEngine.qualitativeLabel(score: 0.95).contains("bones held"))
        #expect(StructuralReadEngine.qualitativeLabel(score: 0.75).contains("mostly held"))
        #expect(StructuralReadEngine.qualitativeLabel(score: 0.55).contains("mixed"))
        #expect(StructuralReadEngine.qualitativeLabel(score: 0.35).contains("thin"))
        #expect(StructuralReadEngine.qualitativeLabel(score: 0.10).contains("weak shape"))
    }

    @Test func readoutNamesStrongestAndWeakestWhenTheyDiffer() {
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening":   "Good",
            "Structure": "Could improve",
            "Close":     "OK",
        ])
        let readout = read?.readout ?? ""
        #expect(readout.contains("opening") && readout.contains("structure"),
                "Readout should name the strongest + weakest dimensions explicitly")
    }

    @Test func readoutFallsBackWhenAllDimensionsTie() {
        // All Good → strongest == weakest. Readout should say "carried"
        // not "X held, Y faltered".
        let read = StructuralReadEngine.derive(categoryRatings: [
            "Opening":   "Good",
            "Structure": "Good",
            "Close":     "Good",
        ])
        let readout = read?.readout ?? ""
        #expect(readout.contains("carried"), "Tied dimensions take the carried-the-rep fallback")
        #expect(!readout.contains("faltered"))
    }

    @Test func codableRoundTripPreservesAllFields() throws {
        let inputs = StructuralRead.Inputs(
            openingRating: "Good",
            structureRating: nil,
            depthRating: "OK",
            closeRating: "Could improve"
        )
        let original = StructuralRead(score: 0.5, contributingDimensions: 3, inputs: inputs, readout: "test readout")
        let data = try JSONEncoder().encode(original)
        let decoded = try JSONDecoder().decode(StructuralRead.self, from: data)
        #expect(decoded == original)
    }
}

// MARK: - M30 Derived Reads Trend Engine Tests
//
// DerivedReadsTrendEngine walks the session history + recomputes the
// four derived reads (vocal energy / composure / confidence / structural)
// per rep and classifies direction (improving / declining / stable /
// insufficient) per dimension. Pure function — no new persistence.
// Tests pin:
//   - Empty / thin sessions → empty result
//   - Recent-only (no prior comparison) → stable
//   - Improving + declining classification at the movement threshold
//   - Each dimension's score function feeds the classifier correctly
//   - Sort order: newest-first (recent window = first N)
//   - Per-trend readout copy includes the actual numbers

@Suite("DerivedReadsTrendEngine")
struct DerivedReadsTrendEngineTests {

    private func session(daysAgo: Int, energySteadiness: Double?, fillerCount: Int = 0, duration: TimeInterval = 60) -> PracticeSession {
        let energy: VocalEnergyMetrics? = energySteadiness.map {
            VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.6, stdDeviation: 0.05, coefficientOfVariation: 0.12, steadiness: $0, sampleCount: 100)
        }
        return PracticeSession(
            transcript: "rep transcript with enough words for pace estimation here",
            fillerWordCount: fillerCount,
            duration: duration,
            date: Date().addingTimeInterval(TimeInterval(-daysAgo * 86400)),
            mode: .timed,
            vocalEnergyMetrics: energy
        )
    }

    @Test func emptySessionsProducesEmptyResult() {
        let trends = DerivedReadsTrendEngine.compute(
            sessions: [],
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in 150 }
        )
        #expect(trends.isEmpty)
    }

    @Test func thinSessionsProducesEmptyResult() {
        // Only 2 sessions — below the minRecentReps floor of 3.
        let sessions = [
            session(daysAgo: 1, energySteadiness: 0.7),
            session(daysAgo: 2, energySteadiness: 0.7)
        ]
        let trends = DerivedReadsTrendEngine.compute(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        #expect(trends.isEmpty)
    }

    @Test func recentOnlyWithoutPriorReadsAsStable() {
        // 5 recent reps, 0 prior. Should read as stable (no comparison
        // basis).
        let sessions = (1...5).map { session(daysAgo: $0, energySteadiness: 0.75) }
        let trends = DerivedReadsTrendEngine.compute(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        let energyTrend = trends.first { $0.dimension == "Vocal energy steadiness" }
        #expect(energyTrend?.direction == .stable)
        #expect(energyTrend?.recentCount == 5)
        #expect(energyTrend?.priorCount == 0)
    }

    @Test func improvingTrendClassifiesCorrectly() {
        // 5 recent (mean ~0.85) + 5 prior (mean ~0.55) → improving
        var sessions: [PracticeSession] = []
        for i in 1...5 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.85))     // recent
        }
        for i in 6...10 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.55))     // prior
        }
        let trends = DerivedReadsTrendEngine.compute(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        let energy = trends.first { $0.dimension == "Vocal energy steadiness" }
        #expect(energy?.direction == .improving)
        #expect(energy?.recentMean ?? 0 > 0.80)
        #expect(energy?.priorMean ?? 0 < 0.60)
    }

    @Test func decliningTrendClassifiesCorrectly() {
        // 5 recent (mean ~0.40) + 5 prior (mean ~0.80) → declining
        var sessions: [PracticeSession] = []
        for i in 1...5 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.40))
        }
        for i in 6...10 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.80))
        }
        let trends = DerivedReadsTrendEngine.compute(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        let energy = trends.first { $0.dimension == "Vocal energy steadiness" }
        #expect(energy?.direction == .declining)
    }

    @Test func deltaWithinNoiseBandReadsAsStable() {
        // Recent 0.70 + prior 0.74 → delta -0.04 → within ±0.05 → stable
        var sessions: [PracticeSession] = []
        for i in 1...5 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.70))
        }
        for i in 6...10 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.74))
        }
        let trends = DerivedReadsTrendEngine.compute(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        let energy = trends.first { $0.dimension == "Vocal energy steadiness" }
        #expect(energy?.direction == .stable)
    }

    @Test func sessionsAreSortedNewestFirst() {
        // Pass sessions in jumbled order; verify the engine sorted
        // them — recent window must pick the newest 5, not the
        // first 5 of the input array.
        var sessions: [PracticeSession] = []
        // Add prior (low steadiness) FIRST in the array but with
        // older dates
        for i in 6...10 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.40))
        }
        // Add recent (high steadiness) AFTER, with newer dates
        for i in 1...5 {
            sessions.append(session(daysAgo: i, energySteadiness: 0.85))
        }
        let trends = DerivedReadsTrendEngine.compute(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        let energy = trends.first { $0.dimension == "Vocal energy steadiness" }
        // If sort worked: recent = high steadiness → improving
        #expect(energy?.direction == .improving)
    }

    @Test func dimensionOmittedWhenNoSignalAcrossWindow() {
        // No vocal energy metrics on ANY session → vocal energy
        // dimension should be omitted (not produce a 0-score trend).
        let sessions = (1...10).map { session(daysAgo: $0, energySteadiness: nil) }
        let trends = DerivedReadsTrendEngine.compute(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        let energy = trends.first { $0.dimension == "Vocal energy steadiness" }
        #expect(energy == nil, "Dimension with no signal must be omitted, not zeroed")
    }

    @Test func readoutLinesIncludeActualNumbers() {
        let trend = DerivedReadTrend(
            dimension: "Composure",
            recentMean: 0.78,
            priorMean: 0.62,
            recentCount: 5,
            priorCount: 5,
            direction: .improving
        )
        #expect(trend.readout.contains("0.62"))
        #expect(trend.readout.contains("0.78"))
        #expect(trend.readout.contains("improving"))
    }

    @Test func computeTrendReturnsNilWhenNoRecentScores() {
        // No recent sessions had a score → return nil so the engine
        // omits the dimension entirely.
        let trend = DerivedReadsTrendEngine.computeTrend(
            dimension: "test",
            recent: [session(daysAgo: 1, energySteadiness: nil)],
            prior: [],
            score: { _ in nil }
        )
        #expect(trend == nil)
    }

    @Test func codableRoundTripPreservesTrend() throws {
        let original = DerivedReadTrend(
            dimension: "Composure",
            recentMean: 0.78,
            priorMean: 0.62,
            recentCount: 5,
            priorCount: 5,
            direction: .improving
        )
        let data = try JSONEncoder().encode(original)
        let decoded = try JSONDecoder().decode(DerivedReadTrend.self, from: data)
        #expect(decoded == original)
    }
}

// MARK: - FusedDeliveryReadTests (#3)
//
// `DerivedReadsTrendEngine.fusedDeliveryRead` fuses the existing per-rep
// reads (composure + confidence markers, with structural as a non-
// contradiction guard) over the recent window into one DURABLE, hedged
// delivery read. THE MOST INTERPRETIVELY DANGEROUS READ in the system —
// these tests pin the conservative contract:
//   - `.forming` + suppressed line below the 4-of-5 consistency floor
//   - a pattern (`.clear` / `.timid`) only at/above the floor
//   - never a label on thin / missing channels (returns nil — no signal)
//   - split votes never characterise (the coach abstains)
//   - copy is a HYPOTHESIS about the REP SET, baseline-relative, with no
//     absolute-loudness / absolute-pitch term
//   - the `.evasive` / `.polished` / `.detached` labels are absent by
//     design (the enum simply has no such cases to emit)
//   - back-compat: a `CoachMemory` persisted without `coachDeliveryRead`
//     decodes to nil (round-trip)
//   - carry-forward: a thin-window `build` preserves the previous read
//     (mirrors `lastTransferReview`)
//
// Fixtures mirror `DerivedReadsTrendEngineTests.session(daysAgo:...)` and
// are hand-traced against the REAL constants in `ComposureReadEngine` +
// `ConfidenceMarkerEngine`:
//   clear rep  (steadiness 0.85, 0 fillers, hedging 0): composure 0.925,
//              confidence 0.975 — both ≥ 0.65 → clear vote.
//   timid rep  (steadiness 0.45, 10 fillers, hedging 6): confidence 0.239
//              — ≤ 0.40 → timid vote.

@Suite("FusedDeliveryRead")
struct FusedDeliveryReadTests {

    private func session(daysAgo: Int, energySteadiness: Double?, fillerCount: Int = 0, duration: TimeInterval = 60) -> PracticeSession {
        let energy: VocalEnergyMetrics? = energySteadiness.map {
            VocalEnergyMetrics(meanLevel: 0.4, peakLevel: 0.6, stdDeviation: 0.05, coefficientOfVariation: 0.12, steadiness: $0, sampleCount: 100)
        }
        return PracticeSession(
            transcript: "rep transcript with enough words for pace estimation here",
            fillerWordCount: fillerCount,
            duration: duration,
            date: Date().addingTimeInterval(TimeInterval(-daysAgo * 86400)),
            mode: .timed,
            vocalEnergyMetrics: energy
        )
    }

    // MARK: Engine — characterisation floor

    @Test func characterizesClearAtFloor() {
        // 5 clear reps (steadiness 0.85, 0 fillers, hedging 0) → 5 clear
        // votes ≥ the 4-of-5 floor → `.clear`.
        let sessions = (1...5).map { session(daysAgo: $0, energySteadiness: 0.85) }
        let read = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        #expect(read?.dominantPattern == .clear)
        #expect(read?.evidenceDepth == 5)
        #expect(read?.tentativeLine != nil)
        #expect(read?.isCharacterized == true)
    }

    @Test func characterizesTimidAtFloor() {
        // 5 timid reps (steadiness 0.45, 10 fillers, hedging 6) →
        // confidence 0.239 ≤ 0.40 → 5 timid votes → `.timid`.
        let sessions = (1...5).map { session(daysAgo: $0, energySteadiness: 0.45, fillerCount: 10) }
        let read = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 6 },
            paceBaselinePerSession: { _ in nil }
        )
        #expect(read?.dominantPattern == .timid)
        #expect(read?.evidenceDepth == 5)
        #expect(read?.tentativeLine != nil)
    }

    @Test func formingBelowFloorWithSuppressedLine() {
        // Only 3 clear reps — below the 4-rep consistency floor. The reps
        // DO form reads, but not enough agree → `.forming`, line SUPPRESSED.
        let sessions = (1...3).map { session(daysAgo: $0, energySteadiness: 0.85) }
        let read = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        #expect(read?.dominantPattern == .forming)
        #expect(read?.evidenceDepth == 0)
        #expect(read?.tentativeLine == nil, "Below the floor the line must be suppressed")
        #expect(read?.isCharacterized == false)
    }

    @Test func splitVotesNeverCharacterize() {
        // 3 clear + 2 timid in the recent window: neither vote reaches the
        // 4-rep floor → `.forming`. The coach abstains on a split read.
        // The hedging closure keys off steadiness so clear reps get 0 and
        // timid reps get 6, matching their filler load.
        var sessions: [PracticeSession] = []
        for i in 1...3 { sessions.append(session(daysAgo: i, energySteadiness: 0.85, fillerCount: 0)) }
        for i in 4...5 { sessions.append(session(daysAgo: i, energySteadiness: 0.45, fillerCount: 10)) }
        let read = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { s in (s.vocalEnergyMetrics?.steadiness ?? 0) > 0.6 ? 0 : 6 },
            paceBaselinePerSession: { _ in nil }
        )
        #expect(read?.dominantPattern == .forming)
        #expect(read?.tentativeLine == nil)
    }

    // MARK: Engine — never labels on thin / missing channels

    @Test func returnsNilWhenNoChannelsFormAnyRead() {
        // No vocal-energy metrics AND no hedging signal → composure can't
        // form (0 channels) and confidence falls to 1 channel → neither
        // read forms on ANY rep → no signal at all → nil (let the caller
        // carry a previous read forward rather than invent `.forming`).
        let sessions = (1...5).map { session(daysAgo: $0, energySteadiness: nil) }
        let read = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in nil },
            paceBaselinePerSession: { _ in nil }
        )
        #expect(read == nil, "No formed reads on any rep → nil, never a fabricated label")
    }

    @Test func emptyWindowReturnsNil() {
        let read = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: [],
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )
        #expect(read == nil)
    }

    // MARK: Engine — copy hygiene (hypothesis, baseline-relative, no absolute term)

    @Test func clearCopyIsHedgedHypothesisNotTrait() {
        let sessions = (1...5).map { session(daysAgo: $0, energySteadiness: 0.85) }
        let line = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 0 },
            paceBaselinePerSession: { _ in nil }
        )?.tentativeLine
        let lowered = (line ?? "").lowercased()
        // Reads the REP SET, not the person.
        #expect(lowered.contains("reps"))
        #expect(lowered.contains("not a fixed trait"))
        #expect(!lowered.contains("you are"))
        // No absolute-loudness / absolute-pitch vocabulary.
        #expect(!lowered.contains("loud"))
        #expect(!lowered.contains("quiet"))
        #expect(!lowered.contains("decibel"))
        #expect(!lowered.contains("hz"))
    }

    @Test func timidCopyIsBaselineRelativeHypothesis() {
        let sessions = (1...5).map { session(daysAgo: $0, energySteadiness: 0.45, fillerCount: 10) }
        let line = DerivedReadsTrendEngine.fusedDeliveryRead(
            sessions: sessions,
            snapshots: [],
            hedgingPerMinutePerSession: { _ in 6 },
            paceBaselinePerSession: { _ in nil }
        )?.tentativeLine
        let lowered = (line ?? "").lowercased()
        #expect(lowered.contains("hypothesis"))
        #expect(lowered.contains("baseline"))          // explicitly relative to the user's own baseline
        #expect(lowered.contains("not a label on the person"))
        #expect(!lowered.contains("you are timid"))
        #expect(!lowered.contains("loud"))
        #expect(!lowered.contains("hz"))
    }

    // MARK: CoachMemory — back-compat round-trip

    @Test func memoryPersistedWithoutFieldDecodesToNil() throws {
        // A memory with no delivery read must round-trip with the field nil,
        // and a blob missing the key entirely must decode to nil too.
        let memory = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_000),
            evidenceCount: 6,
            evidenceConfidence: .moderate,
            goalFit: .noLever,
            strengths: [],
            blockers: []
        )
        #expect(memory.coachDeliveryRead == nil)

        let data = try JSONEncoder().encode(memory)
        let decoded = try JSONDecoder().decode(CoachMemory.self, from: data)
        #expect(decoded.coachDeliveryRead == nil)
        #expect(decoded.visualDeliveryRead == nil)

        // Strip the key from the JSON object to simulate a pre-D2 blob.
        var object = try #require(
            try JSONSerialization.jsonObject(with: data) as? [String: Any]
        )
        object.removeValue(forKey: "coachDeliveryRead")
        object.removeValue(forKey: "visualDeliveryRead")
        let strippedData = try JSONSerialization.data(withJSONObject: object)
        let strippedDecoded = try JSONDecoder().decode(CoachMemory.self, from: strippedData)
        #expect(strippedDecoded.coachDeliveryRead == nil)
        #expect(strippedDecoded.visualDeliveryRead == nil)
    }

    @Test func memoryRoundTripPreservesCharacterizedRead() throws {
        var memory = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_000),
            evidenceCount: 6,
            evidenceConfidence: .moderate,
            goalFit: .noLever,
            strengths: [],
            blockers: []
        )
        memory.coachDeliveryRead = CoachDeliveryRead(
            dominantPattern: .clear,
            evidenceDepth: 5,
            tentativeLine: "these reps read as clear — a read of these reps, not a fixed trait."
        )
        let data = try JSONEncoder().encode(memory)
        let decoded = try JSONDecoder().decode(CoachMemory.self, from: data)
        #expect(decoded.coachDeliveryRead == memory.coachDeliveryRead)
        #expect(decoded.coachDeliveryRead?.dominantPattern == .clear)
        #expect(decoded.coachDeliveryRead?.evidenceDepth == 5)
    }

    // MARK: build — compute + carry-forward across thin windows

    private func baselineForFusedReads(hedging: Double) -> CommunicationBaseline {
        var baseline = CommunicationBaseline.empty
        baseline.qualifyingSessionCount = 6   // moderate → evidenceCount > 0
        baseline.hedgingRate.value = hedging
        // pace.value stays 0 → the confidence read's pace channel is skipped
        // deterministically (it requires paceBaseline > 0).
        return baseline
    }

    @Test func buildComputesCharacterizedReadFromSessions() {
        // 5 clear reps + a baseline whose hedging rate is 0 → build fuses a
        // `.clear` read onto the fresh memory.
        let sessions = (1...5).map { session(daysAgo: $0, energySteadiness: 0.85) }
        let memory = CoachMemoryEngine.build(
            profile: nil,
            baseline: baselineForFusedReads(hedging: 0),
            sessions: sessions,
            trends: [],
            forwardPlan: nil,
            previous: nil,
            lastSessionID: nil
        )
        #expect(memory?.coachDeliveryRead?.dominantPattern == .clear)
        #expect(memory?.coachDeliveryRead?.evidenceDepth == 5)
        #expect(memory?.caseFile?.deliveryRead == memory?.coachDeliveryRead)
        #expect(memory?.caseFile?.deliveryRead?.tentativeLine?.contains("not a fixed trait") == true)
    }

    @Test func caseFileBuildCarriesDeliveryReadAsDurableCaseSignal() throws {
        let read = CoachDeliveryRead(
            dominantPattern: .timid,
            evidenceDepth: 5,
            tentativeLine: "Across the last 5 reps the delivery has read as tentative — hedging and tentative markers landing relative to this user's own baseline. A hypothesis about these reps, not a label on the person."
        )
        let memory = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_000),
            evidenceCount: 5,
            evidenceConfidence: .moderate,
            goalFit: .noLever,
            strengths: [],
            blockers: [],
            coachDeliveryRead: read
        )

        let caseFile = try #require(CoachCaseFile.build(
            from: memory,
            now: Date(timeIntervalSince1970: 1_100)
        ))

        #expect(caseFile.deliveryRead == read)
        #expect(caseFile.hypothesis == nil)
        #expect(caseFile.activeIntervention == nil)
        #expect(caseFile.nextMove == .gatherEvidence)
        #expect(caseFile.deliveryRead?.tentativeLine?.contains("not a label on the person") == true)
    }

    @Test func caseFileBuildCarriesVisualDeliveryReadAsOptInCaseSignal() throws {
        let read = VisualDeliveryRead(
            recordedAt: Date(timeIntervalSince1970: 1_000),
            sessionID: UUID(),
            posture: .good,
            eyeContact: .ok,
            gestureUse: .ok,
            presenceDelivery: .good,
            summary: "Your visual delivery looks composed. Keep the eye line steadier on the next rep.",
            primaryImprovement: "Eye contact: Eye line returns to the lens often enough."
        )
        let memory = CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_000),
            evidenceCount: 1,
            evidenceConfidence: .tentative,
            goalFit: .noLever,
            strengths: [],
            blockers: [],
            visualDeliveryRead: read
        )

        let caseFile = try #require(CoachCaseFile.build(
            from: memory,
            now: Date(timeIntervalSince1970: 1_100)
        ))

        #expect(caseFile.visualDeliveryRead == read)
        #expect(caseFile.hypothesis == nil)
        #expect(caseFile.activeIntervention == nil)
        #expect(caseFile.nextMove == CoachCaseNextMove.gatherEvidence)
        #expect(caseFile.visualDeliveryRead?.coachContextLine.contains("opt-in visual evidence") == true)
    }

    @Test func buildCarriesPreviousReadForwardOnThinWindow() throws {
        // Build 1: 5 clear reps → `.clear` characterised.
        let richSessions = (1...5).map { session(daysAgo: $0, energySteadiness: 0.85) }
        let first = try #require(
            CoachMemoryEngine.build(
                profile: nil,
                baseline: baselineForFusedReads(hedging: 0),
                sessions: richSessions,
                trends: [],
                forwardPlan: nil,
                previous: nil,
                lastSessionID: nil
            )
        )
        #expect(first.coachDeliveryRead?.dominantPattern == .clear)

        // Build 2: only 2 reps — below the consistency floor → the fresh read
        // is `.forming`; the carry-forward must preserve the previous `.clear`
        // rather than erase it (mirrors `lastTransferReview`).
        let thinSessions = (1...2).map { session(daysAgo: $0, energySteadiness: 0.85) }
        let second = try #require(
            CoachMemoryEngine.build(
                profile: nil,
                baseline: baselineForFusedReads(hedging: 0),
                sessions: thinSessions,
                trends: [],
                forwardPlan: nil,
                previous: first,
                lastSessionID: nil
            )
        )
        #expect(second.coachDeliveryRead?.dominantPattern == .clear, "Thin window must preserve the previous durable read")
        #expect(second.coachDeliveryRead?.evidenceDepth == 5)
    }

    @Test func buildLeavesReadNilWhenThinAndNoPrevious() {
        // A cold thin window (2 reps, no previous) must NOT persist
        // `.forming` — it stays nil until a real pattern earns the floor.
        let thinSessions = (1...2).map { session(daysAgo: $0, energySteadiness: 0.85) }
        let memory = CoachMemoryEngine.build(
            profile: nil,
            baseline: baselineForFusedReads(hedging: 0),
            sessions: thinSessions,
            trends: [],
            forwardPlan: nil,
            previous: nil,
            lastSessionID: nil
        )
        #expect(memory?.coachDeliveryRead == nil)
    }
}

// MARK: - RevisedReadCardTests
//
// Round-28 pure-copy tests for the post-rep "REVISED READ" surface.
// The card renders only when (1) the latest `CoachCourseChange`
// documents user pushback AND (2) the entry is fresh against the
// carrying memory's `updatedAt`. Both predicates live on
// `CoachCourseChange` and are pinned by `CoachMemoryEngineTests` —
// this suite pins the user-facing copy itself so a future edit to
// `bodyCopy` doesn't quietly drift away from the engine's
// `workingHypothesis` clause shape.

@MainActor
@Suite("RevisedReadCardTests")
struct RevisedReadCardTests {

    @Test func headlineCopyNamesUserAction() {
        // The user reads their own action ("you flagged") so the card
        // lands as an acknowledgement, not a generic plan-change ping.
        #expect(RevisedReadCard.headlineCopy == "You flagged the prior read as off.")
    }

    @Test func bodyCopyQuotesRevisedHypothesisInline() {
        // Names the revised working hypothesis so the user reads
        // exactly what the coach has updated to. Mirrors the
        // `workingHypothesis(lever:evidenceConfidence:)` clause shape.
        let hypothesis = "Pace appears to be the highest-leverage focus because stable at developing; keep checking against future reps."
        let body = RevisedReadCard.bodyCopy(workingHypothesis: hypothesis)
        #expect(body.hasPrefix("Here's the revised read: "))
        #expect(body.contains("Pace appears to be the main focus"))
    }

    @Test func bodyCopyStripsTrailingPeriodToAvoidDoubleStop() {
        // The engine's hypothesis clause already ends with `.`; the
        // card's "Here's the revised read: …" wrapper adds another.
        // The body must drop the inner period so the line never reads
        // as two sentences ending in one.
        let hypothesis = "Pace appears to be the highest-leverage focus; keep checking against future reps."
        let body = RevisedReadCard.bodyCopy(workingHypothesis: hypothesis)
        // Should not contain `..` (which would mean both periods landed).
        #expect(!body.contains(".."))
        // Should still end with exactly one period.
        #expect(body.hasSuffix("."))
    }

    @Test func bodyCopyFallsBackWhenNoHypothesis() {
        // Defensive: a memory rebuild with no current lever produces
        // `workingHypothesis == nil`. The card must still read as a
        // calm acknowledgement rather than rendering an empty line.
        let body = RevisedReadCard.bodyCopy(workingHypothesis: nil)
        #expect(body == "The coach noted it and is forming the next read.")
    }

    @Test func bodyCopyFallsBackWhenHypothesisIsBlank() {
        // Whitespace-only hypothesis takes the same fallback as nil so
        // the card never renders "Here's the revised read: ." Either
        // boundary should be unreachable through the store, but the
        // Codable round-trip could deliver a bad value; defend here.
        let body = RevisedReadCard.bodyCopy(workingHypothesis: "   \n  ")
        #expect(body == "The coach noted it and is forming the next read.")
    }

    // MARK: - Round 34 — second-cycle pushback copy split
    //
    // Round 33 wrote a `secondCyclePushbackMarker` parenthetical into the
    // adaptation log's `reason` whenever the user pushed back on the
    // rebuilt read after already pushing back on the original (two
    // consecutive cycles). The chat-coach context split in round 33
    // surfaced the second-cycle pattern to the model via
    // `freshRevisedReadContextLines` + the generic-arm note. Round 34
    // mirrors that split on the post-rep card itself so the user, the
    // coach, and the model read the same cycle distinction on the same
    // rep. The router functions (`headlineCopy(for:)`, `bodyCopy(for:
    // workingHypothesis:)`) gate purely on `documentsSecondCyclePushback`
    // — no other inputs, no UI dependency.

    /// Builds a fixture `CoachCourseChange` whose `reason` carries both the
    /// first-cycle and second-cycle pushback markers, matching what
    /// `CoachMemoryEngine.build(...)`'s ack arms emit on a round-33
    /// second-cycle rebuild. Mirrors the round-33 engine test fixture
    /// (`courseChangeDocumentsSecondCyclePushbackWhenMarkerEmbedded`) so
    /// the post-rep card tests and the engine tests gate on the same
    /// canonical reason shape.
    private func secondCyclePushbackChange() -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw (after a prior pushback rebuild); revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
    }

    /// First-cycle fixture — same reason shape minus the round-33
    /// parenthetical. Used to lock the no-regression contract on the
    /// router functions: a first-cycle entry must still surface the
    /// round-28 headline + body copy verbatim.
    private func firstCyclePushbackChange() -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
    }

    @Test func headlineCopyOnSecondCycleEntryNamesRebuiltPushback() {
        // The user reads their pushback named in the second cycle
        // ("the rebuilt read as off too") so the card lands as the
        // coach acknowledging the repeated adapt — not as a silent
        // re-rebuild. The "too" preserves the round-33 chat-coach
        // copy's "shifted again" register on the summary surface.
        #expect(
            RevisedReadCard.secondCycleHeadlineCopy
                == "You flagged the rebuilt read as off too."
        )
    }

    @Test func headlineCopyRouterReturnsSecondCycleCopyWhenMarkerEmbedded() {
        // Router contract: a change carrying the round-33 second-cycle
        // marker routes to the second-cycle headline. Locks the post-rep
        // card to the same predicate the chat-coach context block reads.
        let headline = RevisedReadCard.headlineCopy(for: secondCyclePushbackChange())
        #expect(headline == RevisedReadCard.secondCycleHeadlineCopy)
        // The first-cycle copy must NOT surface alongside it — the card
        // shows one canonical headline per cycle, not both.
        #expect(headline != RevisedReadCard.headlineCopy)
    }

    @Test func headlineCopyRouterReturnsFirstCycleCopyWithoutMarker() {
        // No-regression contract: a first-cycle entry routes to the
        // round-28 headline verbatim. Pre-round-34 behaviour preserved.
        let headline = RevisedReadCard.headlineCopy(for: firstCyclePushbackChange())
        #expect(headline == RevisedReadCard.headlineCopy)
        #expect(headline == "You flagged the prior read as off.")
    }

    @Test func bodyCopyOnSecondCycleEntryQuotesNextReadAndNamesFocusedQuestion() {
        // Second-cycle body names the rebuilt read as the operating
        // hypothesis AND tells the user the coach will treat the
        // repeated adapt as case history — one focused question instead
        // of re-prescribing identical work. Mirrors the round-33
        // second-cycle coach-move line inside
        // `CoachContextBuilder.freshRevisedReadContextLines(...)`.
        let hypothesis = "Pace appears to be the highest-leverage focus because stable at developing; keep checking against future reps."
        let body = RevisedReadCard.bodyCopy(
            for: secondCyclePushbackChange(),
            workingHypothesis: hypothesis
        )
        #expect(body.hasPrefix("Here's the next read: "))
        #expect(body.contains("Pace appears to be the main focus"))
        #expect(body.contains("Expect one focused question, not the same exercise again."))
    }

    @Test func bodyCopyOnSecondCycleEntryStripsTrailingPeriodToAvoidDoubleStop() {
        // The engine's hypothesis clause already ends with `.`; the
        // second-cycle body wraps it in "Here's the next read: …."
        // which would otherwise produce `..`. Lock the strip step on
        // the new branch too — same contract as the round-28 first-cycle
        // strip, lifted into `strippedHypothesis(_:)` in round 34.
        let hypothesis = "Pace appears to be the highest-leverage focus; keep checking against future reps."
        let body = RevisedReadCard.bodyCopy(
            for: secondCyclePushbackChange(),
            workingHypothesis: hypothesis
        )
        #expect(!body.contains(".."))
    }

    @Test func bodyCopyOnSecondCycleEntryFallsBackWhenNoHypothesis() {
        // Defensive: a second-cycle rebuild with no current lever
        // produces `workingHypothesis == nil`. The card must still
        // read as a calm acknowledgement of the repeated adapt
        // rather than rendering an empty line.
        let body = RevisedReadCard.bodyCopy(
            for: secondCyclePushbackChange(),
            workingHypothesis: nil
        )
        #expect(body == "The coach noted the repeated adapt and is forming a new read.")
    }

    @Test func bodyCopyOnSecondCycleEntryFallsBackWhenHypothesisIsBlank() {
        // Whitespace-only hypothesis takes the same fallback as nil so
        // the card never renders "Here's the next read: ." on the
        // second-cycle branch. Matches the round-28 first-cycle defence.
        let body = RevisedReadCard.bodyCopy(
            for: secondCyclePushbackChange(),
            workingHypothesis: "   \n  "
        )
        #expect(body == "The coach noted the repeated adapt and is forming a new read.")
    }

    @Test func bodyCopyRouterReturnsFirstCycleCopyWithoutMarker() {
        // No-regression contract on the body router: a first-cycle
        // entry routes to the round-28 body verbatim. The "Here's the
        // revised read: …" wrapper and trailing-period strip behave
        // exactly as before round 34.
        let hypothesis = "Pace is the highest-leverage focus."
        let body = RevisedReadCard.bodyCopy(
            for: firstCyclePushbackChange(),
            workingHypothesis: hypothesis
        )
        #expect(body == RevisedReadCard.bodyCopy(workingHypothesis: hypothesis))
        #expect(body == "Here's the revised read: Pace is the main focus.")
    }

    @Test func bodyCopyRouterReturnsFirstCycleFallbackOnNilHypothesisWithoutMarker() {
        // Defensive: nil hypothesis on a first-cycle entry routes to the
        // round-28 fallback verbatim. The second-cycle fallback must NOT
        // fire when the marker is absent.
        let body = RevisedReadCard.bodyCopy(
            for: firstCyclePushbackChange(),
            workingHypothesis: nil
        )
        #expect(body == "The coach noted it and is forming the next read.")
    }

    @Test func headlineAndBodyDoNotUseExclamationOrApology() {
        // Brand-voice lock on the second-cycle copy. Round 33's HANDOFF
        // pinned the same rules on the chat-coach context lines (no
        // exclamation, no "Let's", no "we", no apology). Round 34
        // mirrors them on the post-rep card so the cross-surface read
        // is consistent.
        let headline = RevisedReadCard.secondCycleHeadlineCopy
        let body = RevisedReadCard.secondCycleBodyCopy(workingHypothesis: "Pace is the focus.")
        let fallback = RevisedReadCard.secondCycleBodyCopy(workingHypothesis: nil)
        for line in [headline, body, fallback] {
            #expect(!line.contains("!"))
            #expect(!line.lowercased().contains("let's"))
            #expect(!line.lowercased().contains(" we "))
            #expect(!line.lowercased().contains("sorry"))
        }
    }
}

// MARK: - Round 36 — CaseReviewCard second-cycle history badge
//
// Round 33 wrote a `secondCyclePushbackMarker` parenthetical into
// `CoachCourseChange.reason` whenever a user pushback rebuild itself
// followed a prior pushback rebuild (two consecutive cycles). Round 34
// mirrored that signal on the post-rep `RevisedReadCard` headline + body;
// round 35 mirrored it on the chat-seed lead. Round 36 closes the third
// surface: the Profile-tab `CaseReviewCard` now renders a small "2nd cycle"
// capsule beside the "Last shift" eyebrow when the latest adaptation entry
// documents the second-cycle pattern. Cross-surface coherence on a single
// predicate (`CoachCourseChange.documentsSecondCyclePushback`) — no new
// state, no schema bump, no migration.
//
// These tests pin the pure constant + pure predicate the SwiftUI view
// reads. The view layer is intentionally simple (a Text inside a Capsule
// gated on `showsSecondCycleBadge(for:)`); the predicate is the testable
// surface.

@MainActor
@Suite("CaseReviewSecondCycleBadgeTests")
struct CaseReviewSecondCycleBadgeTests {

    /// Mirrors the round-34 `RevisedReadCardTests` and round-33 engine
    /// fixtures so the badge tests, the post-rep card tests, and the
    /// engine tests gate on the same canonical reason shape.
    private func secondCyclePushbackChange() -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw (after a prior pushback rebuild); revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
    }

    /// First-cycle fixture — same reason shape minus the round-33
    /// parenthetical. Locks the no-regression contract: a first-cycle
    /// entry must NOT surface the badge.
    private func firstCyclePushbackChange() -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: "user-tapped rejection of: \"…\""
        )
    }

    // MARK: - Pure constant

    @Test func secondCycleBadgeLabelIsCalmShortHistoryTag() {
        // The badge is a calm history qualifier — short so it scans
        // alongside the existing eyebrow label without crowding the
        // five-section case spine. Mirrors `RevisedReadCard`'s
        // `secondCycleHeadlineCopy` register (no exclamation, no
        // urgency framing).
        #expect(CaseReviewCard.secondCycleBadgeLabel == "2nd cycle")
    }

    // MARK: - Pure predicate

    @Test func showsBadgeTrueWhenChangeCarriesSecondCycleMarker() {
        // Predicate contract: a change carrying the round-33
        // second-cycle marker gates the badge on. Locks the
        // `CaseReviewCard` history surface to the same predicate the
        // post-rep card (round 34) and the chat seed (round 35) read.
        #expect(
            CaseReviewCard.showsSecondCycleBadge(for: secondCyclePushbackChange()) == true
        )
    }

    @Test func showsBadgeFalseOnFirstCyclePushbackEntry() {
        // No-regression contract: a first-cycle pushback entry must
        // NOT surface the badge. The "Last shift" row still renders;
        // it just reads as the round-29 first-cycle entry would, with
        // no qualifier.
        #expect(
            CaseReviewCard.showsSecondCycleBadge(for: firstCyclePushbackChange()) == false
        )
    }

    @Test func showsBadgeFalseOnEngineLeverShiftEntry() {
        // Defensive: an engine-only lever shift (no user pushback, no
        // marker) routes through `documentsSecondCyclePushback == false`
        // and therefore surfaces no badge. The reason text reads as
        // case history; the badge surface is exclusively the cycle
        // qualifier.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: .fillerReduction,
            toLever: .paceControl,
            reason: "Pace evidence overtook filler evidence; shifting focus.",
            evidenceBasis: "engine-detected pace decay"
        )
        #expect(CaseReviewCard.showsSecondCycleBadge(for: change) == false)
    }

    @Test func showsBadgeFalseOnVoiceChangeEntry() {
        // Defensive: a user-confirmed voice-goal change writes its own
        // marker (`voiceChangeMarker`) but NOT the second-cycle
        // pushback marker. The badge must stay off — a voice change is
        // not a repeated-adapt signal.
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: Date(timeIntervalSince1970: 1_000),
            fromLever: nil,
            toLever: nil,
            reason: CoachCourseChange.voiceChangeReason(from: .warm, to: .concise),
            evidenceBasis: "user-confirmed voice change"
        )
        #expect(CaseReviewCard.showsSecondCycleBadge(for: change) == false)
    }

    // MARK: - Brand voice

    @Test func secondCycleBadgeLabelIsBrandVoiceCompliant() {
        // The badge is short enough that brand-voice violations would
        // surface immediately; lock it explicitly so a future copy edit
        // can't drift into "Cycle 2!" or "let's adapt" style violations.
        let label = CaseReviewCard.secondCycleBadgeLabel
        #expect(!label.contains("!"))
        #expect(!label.lowercased().contains("let's"))
        #expect(!label.lowercased().contains(" we "))
        #expect(!label.lowercased().contains("sorry"))
    }

    // MARK: - Cross-surface contract

    @Test func badgePredicateMatchesPostRepCardSecondCycleGate() {
        // The post-rep `RevisedReadCard` (round 34) gates its second-
        // cycle headline + body on the SAME predicate. A change that
        // surfaces the badge here must surface the second-cycle copy on
        // the post-rep card; a change that surfaces the first-cycle
        // copy on the card must NOT surface the badge here.
        let secondCycle = secondCyclePushbackChange()
        let firstCycle = firstCyclePushbackChange()

        #expect(
            CaseReviewCard.showsSecondCycleBadge(for: secondCycle)
                == (RevisedReadCard.headlineCopy(for: secondCycle)
                    == RevisedReadCard.secondCycleHeadlineCopy)
        )
        #expect(
            CaseReviewCard.showsSecondCycleBadge(for: firstCycle)
                == (RevisedReadCard.headlineCopy(for: firstCycle)
                    == RevisedReadCard.secondCycleHeadlineCopy)
        )
    }

    @Test func badgePredicateMatchesChatSeedSecondCycleGate() {
        // The chat-seed `revisedReadOpener(for:workingHypothesis:voice:)`
        // router (round 35) gates the second-cycle lead on the SAME
        // predicate. Cross-surface contract: the three surfaces — case
        // history badge, post-rep card, and chat seed — agree on every
        // change about whether the cycle distinction surfaces.
        let secondCycle = secondCyclePushbackChange()
        let firstCycle = firstCyclePushbackChange()

        let secondCycleSeed = CoachContextBuilder.revisedReadOpener(
            for: secondCycle,
            workingHypothesis: "Pace is the focus.",
            voice: nil
        )
        let firstCycleSeed = CoachContextBuilder.revisedReadOpener(
            for: firstCycle,
            workingHypothesis: "Pace is the focus.",
            voice: nil
        )

        #expect(
            CaseReviewCard.showsSecondCycleBadge(for: secondCycle)
                == secondCycleSeed.hasPrefix(CoachContextBuilder.revisedReadOpenerSecondCycleLead)
        )
        #expect(
            CaseReviewCard.showsSecondCycleBadge(for: firstCycle)
                == firstCycleSeed.hasPrefix(CoachContextBuilder.revisedReadOpenerSecondCycleLead)
        )
    }
}

// MARK: - Round 29 — Revised-read opener tests (CoachContextBuilder)
//
// Round 29 closes Future Move #11 from the round-28 HANDOFF: a tap on
// the post-rep `TalkToNoumCTACard` no longer dispatches the generic
// `sessionOpener` on the rep where `RevisedReadCard` is showing.
// Instead it dispatches `CoachContextBuilder.revisedReadOpener(...)`,
// which names the user's pushback ("I flagged the prior read as off"),
// quotes the coach's revised working hypothesis, and ends with a
// voice-shaped invitation.
//
// These tests pin the pure-function contract `SummaryView.talkToNoumOpener`
// reads. The gate decision (revised-read opener vs `sessionOpener`)
// lives in `SummaryView`; this suite covers only the opener composition
// itself — lead, body (with hypothesis present, with trailing-period
// strip, with nil/blank fallbacks), and the seven voice-mapped ask
// branches.
//
// The lead is pinned as a static constant on `CoachContextBuilder`
// (`revisedReadOpenerLead`) so a future predicate (e.g. a chat-thread
// classifier that fires a revised-read follow-up chip row, mirror of
// the round-26 `shouldShowHypothesisAcknowledgement` predicate) can
// match the prefix without composing the full opener.

@Suite("RevisedReadOpenerTests")
struct RevisedReadOpenerTests {

    // MARK: - Lead

    @Test func openerLeadNamesUserPushbackInFirstPerson() {
        // The lead is the user-voice clause that names the pushback.
        // First-person ("I flagged") matches every other dispatched
        // opener — `sessionOpener` ("Just finished..."),
        // `interventionReviewOpener` ("Time to review..."), and the
        // hypothesis ack chips ("Yes — that's the read"). The user is
        // the one typing the message; the perspective stays continuous.
        #expect(
            CoachContextBuilder.revisedReadOpenerLead
                == "Picking up the case file — I flagged the prior read as off."
        )
    }

    @Test func openerStartsWithTheLeadConstant() {
        // Composition contract: the full opener must begin with the
        // pinned lead so a future predicate can match the prefix
        // without depending on the voice-shaped suffix.
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace appears to be the highest-leverage focus.",
            voice: nil
        )
        #expect(opener.hasPrefix(CoachContextBuilder.revisedReadOpenerLead))
    }

    // MARK: - Body

    @Test func openerBodyQuotesRevisedHypothesisInline() {
        // The body names the revised working hypothesis so the coach
        // reply has the case-anchored read in scope from the first
        // turn. Same hypothesis text the post-rep `RevisedReadCard`
        // quotes — the chat thread and the card read as continuous
        // voice.
        let hypothesis = "Pace appears to be the highest-leverage focus because stable at developing; keep checking against future reps."
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: hypothesis,
            voice: nil
        )
        #expect(opener.contains("The revised read you're holding is: "))
        #expect(opener.contains("Pace appears to be the highest-leverage focus"))
    }

    @Test func openerBodyStripsTrailingPeriodToAvoidDoubleStop() {
        // Mirrors `RevisedReadCard.bodyCopy(workingHypothesis:)` — the
        // engine's hypothesis clause already ends with `.`, and the
        // opener wraps it in "The revised read you're holding is: …"
        // which appends another. The strip step keeps the seed as
        // three discrete sentences (lead, body, ask) with no `..`.
        let hypothesis = "Pace appears to be the highest-leverage focus; keep checking against future reps."
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: hypothesis,
            voice: nil
        )
        #expect(!opener.contains(".."))
    }

    @Test func openerBodyFallsBackWhenNoHypothesis() {
        // Defensive: a memory rebuild with no current lever produces
        // `workingHypothesis == nil`. The seed must never read "The
        // revised read you're holding is: ." to the model.
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: nil,
            voice: nil
        )
        #expect(opener.contains("The revised read is still forming."))
        #expect(!opener.contains("The revised read you're holding is:"))
    }

    @Test func openerBodyFallsBackWhenHypothesisIsBlank() {
        // Whitespace-only hypothesis takes the same fallback as nil so
        // the seed never renders "The revised read you're holding is: ."
        // Either boundary should be unreachable through the store, but
        // the Codable round-trip could deliver a bad value; defend here.
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "   \n  ",
            voice: nil
        )
        #expect(opener.contains("The revised read is still forming."))
        #expect(!opener.contains("The revised read you're holding is:"))
    }

    // MARK: - Voice mapping

    @Test func openerAskByVoiceAuthoritative() {
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: .authoritative
        )
        #expect(opener.hasSuffix("Where does the read land now?"))
    }

    @Test func openerAskByVoiceWarm() {
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: .warm
        )
        #expect(opener.hasSuffix("What does this open up?"))
    }

    @Test func openerAskByVoiceConcise() {
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: .concise
        )
        #expect(opener.hasSuffix("Where does this go?"))
    }

    @Test func openerAskByVoicePersuasive() {
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: .persuasive
        )
        #expect(opener.hasSuffix("Make the case for the new read."))
    }

    @Test func openerAskByVoiceExecutive() {
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: .executive
        )
        #expect(opener.hasSuffix("Brief me on what shifted."))
    }

    @Test func openerAskByVoiceStorytelling() {
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: .storytelling
        )
        #expect(opener.hasSuffix("What chapter does this start?"))
    }

    @Test func openerAskWhenVoiceIsNil() {
        // Voice nil → neutral ask. Covers users who haven't completed
        // the coaching profile yet — the opener still produces a
        // coherent case-anchored seed.
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: nil
        )
        #expect(opener.hasSuffix("Where does this go from here?"))
    }

    // MARK: - Composition

    @Test func openerComposesLeadBodyAndAskWithSingleSpaces() {
        // Lock the surface contract: the opener is exactly three
        // sentences joined by single spaces (lead + body + ask). No
        // double spaces, no newlines, no missing separators.
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: "Pace is the highest-leverage focus.",
            voice: .concise
        )
        #expect(!opener.contains("  "))
        #expect(!opener.contains("\n"))
        #expect(
            opener
                == "Picking up the case file — I flagged the prior read as off. The revised read you're holding is: Pace is the highest-leverage focus. Where does this go?"
        )
    }

    @Test func openerFallbackComposesLeadAndFallbackBodyWithAsk() {
        // Same composition contract for the nil-hypothesis fallback —
        // the seed is still three discrete sentences (lead + fallback
        // body + ask) with single-space joins, ready for the chat
        // surface without further trimming.
        let opener = CoachContextBuilder.revisedReadOpener(
            workingHypothesis: nil,
            voice: .warm
        )
        #expect(
            opener
                == "Picking up the case file — I flagged the prior read as off. The revised read is still forming. What does this open up?"
        )
    }

    // MARK: - Round 35 — Second-cycle opener (CoachContextBuilder)
    //
    // Round 35 closes Future Move #13 from the round-34 HANDOFF: the chat
