        // log pre-dating the ack, there is no anchored read to continue
        // from. This is the gate that distinguishes "engine refined the
        // user-ratified rebuild" from "engine drifted the lever from a
        // baseline reading the user happened to confirm".
        let now = Date()
        let firstEngineAt = now.addingTimeInterval(-7200)
        let ackAt = firstEngineAt.addingTimeInterval(300)
        let secondEngineAt = ackAt.addingTimeInterval(3600)
        let mem = Self.memory(
            updatedAt: secondEngineAt,
            adaptationLog: [
                Self.engineOnlyChange(at: firstEngineAt),
                Self.engineOnlyChange(at: secondEngineAt),
            ],
            hypothesisAcknowledgement: Self.ack(.confirmed, at: ackAt)
        )
        #expect(CoachContextBuilder.caseAnchoredContinuationApplies(in: mem, now: now) == false)
    }

