        // to resolve the tension between the two surfaces (frame the
        // refinement as complementing the ratified read, not replacing
        // it). A future copy edit that drops any clause fails this test.
        let (mem, now) = Self.canonicalContinuationState()
        let line = CoachContextBuilder.caseAnchoredContinuationContextLine(
            memory: mem,
            now: now
        ) ?? ""
        #expect(line.contains("engine-only refinement"))
        #expect(line.contains("previously-confirmed rebuild"))
        #expect(line.contains("ratified rebuild"))
        #expect(line.contains("quiet conviction"))
