        #expect(!line.lowercased().contains("wrong"))
    }

    // MARK: - Mutual exclusion with round 37

    @Test func round37AndRound39AreMutuallyExclusiveOnLatestEntryNature() {
        // Round 37 requires `last.documentsUserPushback == true`.
        // Round 39 requires it `== false`. On any single memory state,
        // at most one fires. Pin both branches.
        let now = Date()

        // Branch A: latest is user pushback → round 37 may fire, round
        // 39 must NOT.
        let pushbackOnTopMem = Self.memory(
            updatedAt: now,
            adaptationLog: [Self.pushbackChange(at: now.addingTimeInterval(-60))],
            hypothesisAcknowledgement: Self.ack(.confirmed, at: now)
        )
        #expect(CoachContextBuilder.caseAnchoredAmplificationApplies(in: pushbackOnTopMem, now: now) == true)
        #expect(CoachContextBuilder.caseAnchoredContinuationApplies(in: pushbackOnTopMem, now: now) == false)

        // Branch B: latest is engine-only on top of a prior pushback →
        // round 39 fires, round 37 must NOT.
        let (continuationMem, continuationNow) = Self.canonicalContinuationState()
        #expect(CoachContextBuilder.caseAnchoredAmplificationApplies(in: continuationMem, now: continuationNow) == false)
        #expect(CoachContextBuilder.caseAnchoredContinuationApplies(in: continuationMem, now: continuationNow) == true)
    }

    // MARK: - Mutual exclusion with round 38

    @Test func round38AndRound39AreMutuallyExclusiveOnAckConfidence() {
        // Round 38 requires `.rejected`. Round 39 requires `.confirmed`.
        // The two cannot coexist on the same memory state — pin both
        // branches.
        let now = Date()

        // Branch A: rejected ack → round 38 fires when latest is user
        // pushback. Round 39 must NOT fire.
        let pushbackAt = now.addingTimeInterval(-60)
        let rejectedAt = now
        let rejectedMem = Self.memory(
            updatedAt: rejectedAt,
            adaptationLog: [Self.pushbackChange(at: pushbackAt)],
            hypothesisAcknowledgement: Self.ack(.rejected, at: rejectedAt)
        )
        #expect(CoachContextBuilder.interventionUnderRepeatedPushbackApplies(in: rejectedMem, now: now) == true)
        #expect(CoachContextBuilder.caseAnchoredContinuationApplies(in: rejectedMem, now: now) == false)

        // Branch B: confirmed ack + engine refinement on top → round 39
        // fires. Round 38 must NOT fire (it requires `.rejected`).
        let (continuationMem, continuationNow) = Self.canonicalContinuationState()
        #expect(CoachContextBuilder.interventionUnderRepeatedPushbackApplies(in: continuationMem, now: continuationNow) == false)
        #expect(CoachContextBuilder.caseAnchoredContinuationApplies(in: continuationMem, now: continuationNow) == true)
    }

