        // Round 32 must NOT fire (latest entry is engine-only).
        #expect(ctx.contains("Case file rebuild verdict:") == false)
    }
}

// MARK: - SecondCyclePushbackContextTests
//
// Round 33 — pins the chat-coach user-context block's response to a
// second-cycle pushback. Round 32 surfaced the "second pushback" label
// while the round-30 chip-row ack was still carried in memory. Once the
// engine drops that ack on the next memory rebuild, round 32 goes dark
// AND the freshly-appended `CoachCourseChange` reads identically to a
// first-cycle pushback unless the engine has tagged it.
//
// Round 33's engine work (covered in `CoachMemoryEngineTests`) embeds
// the `secondCyclePushbackMarker` parenthetical inside the new entry's
// `reason`. This suite covers the SECOND half: the context builder
// reading that marker (via `CoachCourseChange.documentsSecondCyclePushback`)
// and emitting distinct copy in BOTH the round-31 fresh window and the
// generic "Last course change" else-arm.
//
// Three-tier precedence is preserved exactly as round 32 set it; round 33
// only changes WHAT copy round 31 and the generic else-arm emit when the
// latest change is a second-cycle pushback. No reordering, no new branch.

@MainActor
@Suite("SecondCyclePushbackContextTests")
struct SecondCyclePushbackContextTests {

    // MARK: - Fixtures

    nonisolated private static let rebuiltHypothesis =
        "Filler reduction may be the highest-leverage focus across recent reps."

    private static func firstCyclePushback(
        at changedAt: Date,
        evidenceBasis: String = "user-tapped rejection of: \"prior read\""
    ) -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: changedAt,
            fromLever: .paceControl,
            toLever: .paceControl,
            reason: "User reported the prior hypothesis did not match what they saw; revising the read.",
            evidenceBasis: evidenceBasis
        )
    }

    private static func secondCyclePushback(
        at changedAt: Date,
        evidenceBasis: String = "user-tapped rejection of: \"rebuilt read\""
    ) -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: changedAt,
            fromLever: .paceControl,
            toLever: .fillerReduction,
            reason: "Shifted focus from Pace to Filler Words after the user reported the prior hypothesis did not match what they saw (after a prior pushback rebuild).",
            evidenceBasis: evidenceBasis
        )
    }

    private static func memory(
        updatedAt: Date,
        adaptationLog: [CoachCourseChange],
        workingHypothesis: String? = rebuiltHypothesis,
        hypothesisAcknowledgement: CoachHypothesisAcknowledgement? = nil
    ) -> CoachMemory {
        CoachMemory(
            updatedAt: updatedAt,
            evidenceCount: 6,
            evidenceConfidence: .moderate,
            voice: .authoritative,
            currentLever: .fillerReduction,
            currentLeverConfidence: .medium,
            currentLeverBasis: "rebuilt after a second user pushback",
            previousLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: workingHypothesis,
            hypothesisAcknowledgement: hypothesisAcknowledgement,
            adaptationLog: adaptationLog
        )
    }

    private func sampleProfile() -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: .authoritative,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: ""
        )
    }

    // MARK: - Fresh window: round-31 copy swaps for second-cycle phrasing

    @Test func freshRevisedReadLinesSurfaceSecondCycleCopyWhenMarkerEmbedded() {
        // Round-31 path on a SECOND-CYCLE rebuild: the case-state line
        // names "shifted again" instead of "just shifted", and the
        // coach-move line names the second cycle explicitly with anti-
        // re-prescribe and anti-strengthening rails. First-cycle copy
        // must NOT also surface — single canonical block per cycle.
        let now = Date()
        let mem = Self.memory(
            updatedAt: now,
            adaptationLog: [
                Self.firstCyclePushback(at: now.addingTimeInterval(-600)),
                Self.secondCyclePushback(at: now),
            ]
        )
        let lines = CoachContextBuilder.freshRevisedReadContextLines(memory: mem)
        #expect(lines.count == 2)
        let caseState = lines.first ?? ""
        let coachMove = lines.last ?? ""
        #expect(caseState.contains("Case file shifted again"))
        #expect(caseState.contains("two consecutive rebuild cycles"))
        #expect(coachMove.contains("second rebuild cycle"))
        #expect(coachMove.contains("do not re-prescribe the same intervention unchanged"))
        #expect(coachMove.contains("avoid strengthening either prior read"))
        // First-cycle copy must not double up.
        #expect(caseState.contains("Case file just shifted:") == false)
    }

    @Test func freshRevisedReadLinesStayFirstCycleCopyWhenMarkerAbsent() {
        // Round-31 path on a FIRST-CYCLE rebuild: original copy unchanged
        // when the marker is not present. Locks the no-regression contract.
        let now = Date()
        let mem = Self.memory(
            updatedAt: now,
            adaptationLog: [Self.firstCyclePushback(at: now)]
        )
        let lines = CoachContextBuilder.freshRevisedReadContextLines(memory: mem)
        #expect(lines.count == 2)
        let caseState = lines.first ?? ""
        let coachMove = lines.last ?? ""
        #expect(caseState.contains("Case file just shifted:"))
        #expect(coachMove.contains("Coach move on the rebuild:"))
        // Second-cycle copy must not surface on a first-cycle entry.
        #expect(caseState.contains("Case file shifted again") == false)
        #expect(coachMove.contains("second rebuild cycle") == false)
    }

    // MARK: - userContext: three-tier precedence honoured, copy swapped

    @Test func userContextSurfacesSecondCycleCopyOnFreshSecondCycleRebuild() {
        // Integration: a freshly-stamped second-cycle pushback (no ack
        // carried, so round 32 dark) routes to round 31 — which now
        // emits the second-cycle phrasing.
        let now = Date()
        let mem = Self.memory(
            updatedAt: now,
            adaptationLog: [
                Self.firstCyclePushback(at: now.addingTimeInterval(-600)),
                Self.secondCyclePushback(at: now),
            ]
        )
        let ctx = CoachContextBuilder.userContext(
            profile: sampleProfile(),
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            coachMemory: mem
        )
        #expect(ctx.contains("Case file shifted again"))
        #expect(ctx.contains("two consecutive rebuild cycles"))
        #expect(ctx.contains("second rebuild cycle"))
        // Round 32 dark, generic line dark — single canonical block.
        #expect(ctx.contains("Case file rebuild verdict:") == false)
        #expect(ctx.contains("Last course change:") == false)
        // First-cycle copy must not double up either.
        #expect(ctx.contains("Case file just shifted:") == false)
    }

    @Test func userContextSurfacesGenericLineWithRepeatedAdaptNoteAfterFreshnessExpires() {
        // The headline durability contract: round 31 has aged out (the
        // rebuild's `changedAt` is more than 1s before memory.updatedAt),
        // round 32 has no ack to fire on. The generic "Last course
        // change:" line carries the recorded reason — AND the new
        // round-33 "Repeated-adapt note:" follow-up line surfaces because
        // the latest change `documentsSecondCyclePushback`. The model
        // still sees the second-cycle signal in context, even after the
        // freshness window and the chip-row ack have both ended.
        let memUpdated = Date()
        let changedAt = memUpdated.addingTimeInterval(-600)
        let mem = Self.memory(
            updatedAt: memUpdated,
            adaptationLog: [
                Self.firstCyclePushback(at: memUpdated.addingTimeInterval(-1_200)),
                Self.secondCyclePushback(at: changedAt),
            ]
        )
        let ctx = CoachContextBuilder.userContext(
            profile: sampleProfile(),
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            coachMemory: mem
        )
        #expect(ctx.contains("Last course change:"))
        #expect(ctx.contains("(after a prior pushback rebuild)"))
        #expect(ctx.contains("Repeated-adapt note:"))
        #expect(ctx.contains("second-cycle pushback"))
        #expect(ctx.contains("Avoid re-prescribing identical work"))
        // Round 31 / 32 still dark on a non-fresh, no-ack second-cycle.
        #expect(ctx.contains("Case file shifted again") == false)
        #expect(ctx.contains("Case file rebuild verdict:") == false)
    }

    @Test func userContextGenericLineHasNoRepeatedAdaptNoteOnFirstCyclePushback() {
        // Defensive: an aged-out FIRST-CYCLE pushback must continue to
        // surface the bare generic line (no repeated-adapt note). The
        // round-33 follow-up only fires when the marker is present.
        let memUpdated = Date()
        let changedAt = memUpdated.addingTimeInterval(-600)
        let mem = Self.memory(
            updatedAt: memUpdated,
            adaptationLog: [Self.firstCyclePushback(at: changedAt)]
        )
        let ctx = CoachContextBuilder.userContext(
            profile: sampleProfile(),
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            coachMemory: mem
        )
        #expect(ctx.contains("Last course change:"))
        #expect(ctx.contains("Repeated-adapt note:") == false)
    }

    @Test func userContextRebuildVerdictBlockStillFiresOnSecondCyclePushbackWithFreshAck() {
        // Three-tier precedence preserved end-to-end on a second-cycle
        // entry that still carries an ack: round 32 wins. The round-33
        // copy swaps apply only to round 31 and the generic else-arm; the
        // round-32 path is unchanged.
        let changedAt = Date()
        let ackAt = changedAt.addingTimeInterval(60)
        let memUpdated = ackAt
        let mem = Self.memory(
            updatedAt: memUpdated,
            adaptationLog: [
                Self.firstCyclePushback(at: changedAt.addingTimeInterval(-600)),
                Self.secondCyclePushback(at: changedAt),
            ],
            hypothesisAcknowledgement: CoachHypothesisAcknowledgement(
                confidence: .rejected,
                hypothesisSnapshot: Self.rebuiltHypothesis,
                acknowledgedAt: ackAt
            )
        )
        let ctx = CoachContextBuilder.userContext(
            profile: sampleProfile(),
            baseline: .empty,
            rating: .initial,
            sessions: [],
            currentStreak: 0,
            pathStatus: nil,
            pathGatingPhrase: nil,
            coachMemory: mem
        )
        // Round 32 fires — case-state line names "second pushback" via the
        // existing rebuildVerdictLabel pipeline.
        #expect(ctx.contains("Case file rebuild verdict: the user lodged a second pushback"))
        // Round 31 + generic + repeated-adapt note all dark on this turn.
        #expect(ctx.contains("Case file shifted again") == false)
        #expect(ctx.contains("Last course change:") == false)
        #expect(ctx.contains("Repeated-adapt note:") == false)
    }
}

// MARK: - IM conversation evaluation contract (slice-2)

/// Pure-seam coverage for the IM grader's contract completion: the deterministic
/// fallback (`IMConversationEvaluationService.deterministicEvaluation`) and the
/// transcript-grounding gate (`evaluationEngagesTranscript`). IM is the
/// highest-fidelity role-play surface and its grade drives the saved score, the
/// relationship state, and the next move — so a finished conversation must never
/// dead-end with a thrown error offline / non-English / with no provider.
///
/// What is NOT tested here (and why): the live `evaluateConversation` network
/// path and the `LocaleSettingsManager.shared.current` mutation are deliberately
/// out of scope — mutating the locale singleton persists to UserDefaults and
/// would make the suite order-dependent. The locale gate is the one-line
/// `guard activeLocaleSupportsAI() else { return fallback }`; on an unsupported
/// locale it returns EXACTLY this `deterministicEvaluation` output, which these
/// tests pin directly (mirrors `CoachReadParityTests`' discipline for the same
/// gate in `AICoachService`).
struct IMConversationEvaluationContractTests {

    // MARK: Fixtures

    private static func userTurn(_ text: String) -> IMConversationTurn {
        IMConversationTurn(speaker: .user, text: text)
    }

    private static func npcTurn(_ text: String) -> IMConversationTurn {
        IMConversationTurn(speaker: .npc, text: text)
    }

    /// A realistic, substantive networking conversation. Turn 1 is
    /// unambiguously the longest user turn (68 chars vs the others' 59 and 62),
    /// so the deterministic headline quotes it — no dependence on `max(by:)`
    /// tie-breaking. Turn 1 is exactly 14 words, the `longestSubstantiveTurn`
    /// word cap, so the whole turn appears verbatim in the headline.
    private static func groundedConversation() -> [IMConversationTurn] {
        [
            npcTurn("Good to meet you. What kind of work are you focused on?"),
            userTurn("I lead the platform team at a fintech startup based here in the city"),
            npcTurn("Oh nice, what are you building?"),
            userTurn("We just shipped a payments rewrite that cut latency by half"),
            npcTurn("That sounds impactful."),
            userTurn("It was, and the team really pulled together to ship it on time")
        ]
    }

    private static func transcript(of turns: [IMConversationTurn]) -> String {
        turns
            .filter { $0.speaker == .user }
            .map(\.text)
            .joined(separator: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static let setup = IMConversationSetup(scenario: .networking, targetTone: .confident)

    private static func evaluate(
        turns: [IMConversationTurn],
        finalState: IMConversationState? = IMConversationState(trust: 7, engagement: 7, tension: 3, beat: "Open and engaged."),
        duration: TimeInterval = 120
    ) -> IMConversationEvaluation {
        IMConversationEvaluationService.deterministicEvaluation(
            setup: setup,
            turns: turns,
            finalState: finalState,
            transcript: transcript(of: turns),
            fillerCount: 1,
            duration: duration,
            recentSessions: [],
            relationship: nil
        )
    }

    // MARK: Deterministic fallback — grounded headline quotes a real turn

    @Test func fallbackHeadlineQuotesAnActualTurn() {
        let turns = Self.groundedConversation()
        let eval = Self.evaluate(turns: turns)
        // The headline must quote the longest substantive user turn verbatim —
        // not a generic stat-restate. This is the grounding anchor.
        #expect(
            eval.headline.contains("I lead the platform team at a fintech startup based here in the city"),
            "Headline should quote the actual user turn. Got: \(eval.headline)"
        )
    }

    @Test func fallbackPassesItsOwnGroundingGate() {
        // The deterministic read is the fallback returned on a grounding-gate
        // failure of the AI read, so it must itself clear the gate — otherwise
        // a substitution could loop. (It does, trivially, because it quotes the
        // transcript.)
        let turns = Self.groundedConversation()
        let eval = Self.evaluate(turns: turns)
        #expect(
            IMConversationEvaluationService.evaluationEngagesTranscript(eval, transcript: Self.transcript(of: turns)),
            "The deterministic fallback must engage the transcript it was built from."
        )
    }

    @Test func fallbackScoresAreAllInValidBand() {
        let eval = Self.evaluate(turns: Self.groundedConversation())
        for value in [eval.toneMatch, eval.clarityScore, eval.composureScore, eval.vocabularyScore, eval.conversationScore] {
            #expect((1...10).contains(value), "Every IM dimension must clamp to 1...10. Got \(value)")
        }
        #expect((1...10).contains(eval.overallScore), "overallScore must clamp to 1...10")
        // Insights: the schema/prompt contract is exactly 3 concise strings.
        #expect(eval.insights.count == 3, "Fallback must emit exactly 3 insights. Got \(eval.insights.count)")
        #expect(eval.insights.allSatisfy { !$0.isEmpty }, "No insight may be empty")
        #expect(!eval.feedback.isEmpty, "Feedback must not be empty")
        #expect(!eval.suggestedDrill.isEmpty, "Drill must not be empty")
        // The outcome is resolved by the shared resolver so the call site's
        // `outcome?.closingMessage` path is preserved.
        #expect(eval.outcome != nil, "Fallback must carry an outcome for the call-site closing-message path")
    }

    @Test func fallbackUsesSharedToneMatcherSoGradeAgreesWithPerTurnRead() {
        // Single-source-of-truth: the fallback's toneMatch must equal what the
        // live per-turn tone read (IMToneMatcher) computes for the same tone +
        // transcript, so the saved grade can never disagree with the tone read.
        let turns = Self.groundedConversation()
        let transcript = Self.transcript(of: turns)
        let eval = Self.evaluate(turns: turns)
        #expect(
            eval.toneMatch == IMToneMatcher.score(for: .confident, transcript: transcript),
            "Fallback toneMatch must equal the shared IMToneMatcher score for the same tone/transcript."
        )
    }

    // MARK: Honesty — short session softens to an early read

    @Test func shortSessionSoftensHeadlineToEarlyRead() {
        // <= 2 user turns OR < 30s → the headline must not assert a confident
        // verdict; it states an "early read" instead (matches the LLM prompt's
        // own short-session rule).
        let turns: [IMConversationTurn] = [
            Self.npcTurn("Good to meet you. What kind of work are you focused on?"),
            Self.userTurn("I run growth at a small design studio downtown")
        ]
        let eval = Self.evaluate(turns: turns, duration: 18)
        #expect(
            eval.headline.lowercased().contains("early read"),
            "A short session must soften to an early read. Got: \(eval.headline)"
        )
    }

    @Test func emptyTurnsNeverFabricateAQuoteAndStayValid() {
        // No usable turn → the headline states a grounded scenario read, never a
        // fabricated quote, and the grade is still well-formed.
        let eval = Self.evaluate(turns: [], finalState: IMConversationState.starting, duration: 5)
        #expect(!eval.headline.contains("''"), "Must not render an empty quote")
        #expect(eval.headline.lowercased().contains("early read"), "Empty short session is an early read")
        #expect(eval.insights.count == 3)
        #expect((1...10).contains(eval.overallScore))
    }

    // MARK: Grounding gate — accept / reject / empty

    @Test func groundingGateAcceptsAReadThatSharesAContentWord() {
        let turns = Self.groundedConversation()
        let transcript = Self.transcript(of: turns)
        // "platform" is a >= 4-char non-stop content word present in the turns.
        let grounded = Self.syntheticEvaluation(
            headline: "You held the room — your platform line set the frame.",
            insights: ["Reciprocity stayed high.", "Specificity carried it.", "Trust landed."]
        )
        #expect(
            IMConversationEvaluationService.evaluationEngagesTranscript(grounded, transcript: transcript),
            "A read sharing a content word with a turn must pass the gate."
        )
    }

    @Test func groundingGateAcceptsAReadQuotingAMultiWordDetailFromATurn() {
        let turns = Self.groundedConversation()
        let transcript = Self.transcript(of: turns)
        // A read that quotes a real multi-word detail from a turn ("payments
        // rewrite", a >= 12-char verbatim run also carrying content words)
        // engages the conversation and must pass — only the insights carry the
        // contact; the headline alone shares nothing.
        let grounded = Self.syntheticEvaluation(
            headline: "Solid, measured exchange overall.",
            insights: ["The 'payments rewrite' detail gave them something concrete.", "Good pacing.", "Stay specific."]
        )
        #expect(
            IMConversationEvaluationService.evaluationEngagesTranscript(grounded, transcript: transcript),
            "A read quoting a real multi-word detail from a turn must pass the gate."
        )
    }

    @Test func groundingGateAcceptsAVerbatimSliceWithNoSharedContentWord() {
        // Isolate the >= 12-char verbatim-slice branch from the content-word
        // branch. Transcript tokens (>= 4 chars) are "abcdefghij" + "klmnopqrst".
        // The read embeds the verbatim 12-char slice "efghij klmno" (which spans
        // the word boundary and reproduces NO whole content word as a standalone
        // token — the candidate's tokens are "value"/"efghij"/"klmnozone", none
        // equal to a transcript token), so only the slice path can pass it.
        let transcript = "the abcdefghij klmnopqrst"
        let read = Self.syntheticEvaluation(
            headline: "The value efghij klmnozone landed.",
            insights: ["Composed read.", "Steady pacing.", "Stayed on point."]
        )
        #expect(
            IMConversationEvaluationService.evaluationEngagesTranscript(read, transcript: transcript),
            "A read containing a >= 12-char verbatim slice of a turn must pass via the slice path."
        )
    }

    @Test func groundingGateRejectsAnUngroundedRead() {
        // Transcript with ONLY sub-4-char tokens → the content-word set is
        // empty, and no 12-char slice of it can appear in a generic English
        // read → the gate must reject, and `evaluateConversation` would
        // substitute the deterministic fallback.
        let transcript = "Xy zq wb mm tf vn"
        let ungrounded = Self.syntheticEvaluation(
            headline: "You did a solid job overall and showed good composure.",
            insights: [
                "Your engagement was strong throughout the exchange.",
                "Consider adding more specifics to your replies.",
                "Trust generally improved over the conversation."
            ]
        )
        #expect(
            IMConversationEvaluationService.evaluationEngagesTranscript(ungrounded, transcript: transcript) == false,
            "A generic read that engages no real turn must be rejected."
        )
    }

    @Test func groundingGateEmptyTranscriptPasses() {
        // IM with no captured user words → nothing to quote → never block.
        let any = Self.syntheticEvaluation(headline: "Anything.", insights: ["a", "b", "c"])
        #expect(IMConversationEvaluationService.evaluationEngagesTranscript(any, transcript: ""))
        #expect(IMConversationEvaluationService.evaluationEngagesTranscript(any, transcript: "   "))
    }

    // MARK: Schema decode-safety (byte-identical contract preserved)

    @Test func schemaDecodesUnchanged() throws {
        // The wire contract the AI/backend graders emit must still decode into
        // the byte-identical schema the surfaces depend on.
        let json = """
        {
          "actualTone": "Warm",
          "toneMatch": 8,
          "clarityScore": 7,
          "composureScore": 6,
          "vocabularyScore": 7,
          "conversationScore": 8,
          "headline": "You held the room.",
          "feedback": "Specific and responsive.",
          "insights": ["a", "b", "c"],
          "suggestedDrill": "Reciprocity drill.",
          "outcome": {
            "title": "Strong connection",
            "summary": "You built trust.",
            "closingMessage": "Great talking, let's keep in touch."
          }
        }
        """
        let data = try #require(json.data(using: .utf8))
        let decoded = try JSONDecoder().decode(IMConversationEvaluation.self, from: data)
        #expect(decoded.actualTone == "Warm")
        #expect(decoded.toneMatch == 8)
        #expect(decoded.conversationScore == 8)
        #expect(decoded.insights == ["a", "b", "c"])
        #expect(decoded.outcome?.title == "Strong connection")
        #expect((1...10).contains(decoded.overallScore))
    }

    @Test func schemaDecodesWithMissingOutcome() throws {
        // `outcome` is optional — a grade with no outcome must still decode.
        let json = """
        {
          "actualTone": "Clear but measured",
          "toneMatch": 6, "clarityScore": 6, "composureScore": 6,
          "vocabularyScore": 6, "conversationScore": 6,
          "headline": "An even exchange.",
          "feedback": "Steady throughout.",
          "insights": ["x", "y", "z"],
          "suggestedDrill": "Tone drill."
        }
        """
        let data = try #require(json.data(using: .utf8))
        let decoded = try JSONDecoder().decode(IMConversationEvaluation.self, from: data)
        #expect(decoded.outcome == nil)
        #expect(decoded.headline == "An even exchange.")
    }

    // MARK: Helper — synthetic grade for gate tests

    private static func syntheticEvaluation(headline: String, insights: [String]) -> IMConversationEvaluation {
        IMConversationEvaluation(
            actualTone: "Clear but measured",
            toneMatch: 7,
            clarityScore: 7,
            composureScore: 7,
            vocabularyScore: 7,
            conversationScore: 7,
            headline: headline,
            feedback: "Synthetic feedback for the gate test.",
            insights: insights,
            suggestedDrill: "Synthetic drill.",
            outcome: nil
        )
    }
}

// MARK: - AICoachChatService truncation guard (S1)

/// Deterministic coverage for the chat-reply truncation fix. The felt
/// output length/quality is on-device-QA-only (no toolchain/keys on the
/// build host), but the finish-reason gate that decides whether a
/// completion is committed or routed to the honest "try rephrasing"
/// notice is a pure seam and must be locked down.
///
/// Roots being guarded (see `AICoachChatService` header): a length-
/// truncated completion (Gemini `finishReason == MAX_TOKENS`, OpenAI /
/// DeepSeek `finish_reason == length`) is a guillotined sentence and
/// must NOT be returned as a finished reply. Non-truncated empty /
/// unparseable responses may use the grounded deterministic fallback, but
/// truncation stays an honest `.failure(.empty)` notice.
@Suite("AICoachTruncationGuardTests")
struct AICoachTruncationGuardTests {

    // MARK: Stub builders — shaped exactly like the provider JSON the
    // real extractor parses, so the gate is exercised on realistic
    // objects (not hand-rolled finish-reason-only dicts).

    private func geminiObject(finishReason: String?, text: String = "A complete coach reply.") -> [String: Any] {
        var candidate: [String: Any] = [
            "content": ["parts": [["text": text]]]
        ]
        if let finishReason { candidate["finishReason"] = finishReason }
        return ["candidates": [candidate]]
    }

    private func openAIObject(finishReason: String?, content: String = "A complete coach reply.") -> [String: Any] {
        var choice: [String: Any] = [
            "message": ["role": "assistant", "content": content]
        ]
        if let finishReason { choice["finish_reason"] = finishReason }
        return ["choices": [choice]]
    }

    private func data(_ object: [String: Any]) -> Data {
        try! JSONSerialization.data(withJSONObject: object)
    }

    // MARK: Truncated completions are caught

    @Test func geminiMaxTokensIsTruncated() {
        let object = geminiObject(finishReason: "MAX_TOKENS", text: "We are in a")
        #expect(AICoachChatService.isLengthTruncated(responseObject: object, provider: .gemini))
    }

    @Test func openAILengthIsTruncated() {
        let object = openAIObject(finishReason: "length", content: "We are currently")
        #expect(AICoachChatService.isLengthTruncated(responseObject: object, provider: .openAI))
    }

    @Test func deepSeekLengthIsTruncated() {
        // DeepSeek rides the OpenAI-shaped path.
        let object = openAIObject(finishReason: "length")
        #expect(AICoachChatService.isLengthTruncated(responseObject: object, provider: .deepSeek))
    }

    @Test func finishReasonMatchIsCaseInsensitive() {
        // Guard against a provider casing drift (e.g. "Length",
        // "max_tokens"). `.uppercased()` normalizes before matching.
        #expect(AICoachChatService.isLengthTruncated(
            responseObject: openAIObject(finishReason: "Length"), provider: .openAI))
        #expect(AICoachChatService.isLengthTruncated(
            responseObject: geminiObject(finishReason: "max_tokens"), provider: .gemini))
    }

    // MARK: Complete completions pass through

    @Test func geminiStopIsNotTruncated() {
        let object = geminiObject(finishReason: "STOP")
        #expect(!AICoachChatService.isLengthTruncated(responseObject: object, provider: .gemini))
    }

    @Test func openAIStopIsNotTruncated() {
        let object = openAIObject(finishReason: "stop")
        #expect(!AICoachChatService.isLengthTruncated(responseObject: object, provider: .openAI))
    }

    @Test func missingFinishReasonIsNotTruncated() {
        // Some clean stops omit the field entirely — a missing reason
        // must read as complete, never as a (false) truncation that would
        // suppress a perfectly good reply.
        #expect(!AICoachChatService.isLengthTruncated(
            responseObject: geminiObject(finishReason: nil), provider: .gemini))
        #expect(!AICoachChatService.isLengthTruncated(
            responseObject: openAIObject(finishReason: nil), provider: .openAI))
    }

    @Test func extractionReturnsTrimmedTextForCompleteResponses() {
        #expect(AICoachChatService.extractReplyText(
            from: data(openAIObject(finishReason: "stop", content: "  Hold the beat.  ")),
            provider: .openAI
        ) == .text("Hold the beat."))
        #expect(AICoachChatService.extractReplyText(
            from: data(geminiObject(finishReason: "STOP", text: "  Lead with the point.  ")),
            provider: .gemini
        ) == .text("Lead with the point."))
    }

    @Test func extractionSeparatesEmptyFromLengthTruncated() {
        #expect(AICoachChatService.extractReplyText(
            from: data(openAIObject(finishReason: "stop", content: "   ")),
            provider: .openAI
        ) == .empty)
        #expect(AICoachChatService.extractReplyText(
            from: data(geminiObject(finishReason: "MAX_TOKENS", text: "We are in a")),
            provider: .gemini
        ) == .lengthTruncated)
        #expect(AICoachChatService.extractReplyText(
            from: data(["unexpected": "shape"]),
            provider: .openAI
        ) == .empty)
    }

    @Test func noneProviderIsNeverTruncated() {
        #expect(!AICoachChatService.isLengthTruncated(responseObject: [:], provider: .none))
    }

    // MARK: parseFinishReason extracts the right provider field

    @Test func parseFinishReasonReadsProviderSpecificField() {
        // Gemini's field is `finishReason` under `candidates`; OpenAI's is
        // `finish_reason` under `choices`. Reading one shape with the
        // other provider must miss (returns nil) — proving the gate is
        // provider-scoped and won't cross-read.
        let gemini = geminiObject(finishReason: "MAX_TOKENS")
        let openAI = openAIObject(finishReason: "length")
        #expect(AICoachChatService.parseFinishReason(responseObject: gemini, provider: .gemini) == "MAX_TOKENS")
        #expect(AICoachChatService.parseFinishReason(responseObject: openAI, provider: .openAI) == "length")
        // Cross-read: Gemini object has no `choices`, OpenAI object has no
        // `candidates` → nil → treated as not-truncated.
        #expect(AICoachChatService.parseFinishReason(responseObject: gemini, provider: .openAI) == nil)
        #expect(AICoachChatService.parseFinishReason(responseObject: openAI, provider: .gemini) == nil)
        #expect(!AICoachChatService.isLengthTruncated(responseObject: gemini, provider: .openAI))
    }

    @Test func emptyObjectYieldsNilFinishReason() {
        #expect(AICoachChatService.parseFinishReason(responseObject: [:], provider: .gemini) == nil)
        #expect(AICoachChatService.parseFinishReason(responseObject: [:], provider: .openAI) == nil)
    }
}

// MARK: - S2 Goal data + intelligence layer
//
// Deterministic seams behind the chat-driven "set or change your voice"
// affordance (the UI card + commit path are S3). All pure / store-level —
// no live model output, no pixel layout. Covers:
//   • `CoachContextBuilder.detectGoalIntent` — initialSet vs change, the 6
//     voice aliases, and nil on non-goal text.
//   • `CoachingProfile.secondaryStyleGoal` — decode-safety (legacy JSON
//     without the key) + round-trip.
//   • `CoachingProfile.blendedAlignedSkillAreas` — union of both voices.
//   • `CoachMemoryStore.noteVoiceChange` — appends a `CoachCourseChange` with
//     the correct from/to lever + the voice-change marker + suffix(8) bound.
//   • `CoachContextBuilder.recentVoiceChangeCount` — counts only in-window
//     voice-change entries.
//   • `CoachContextBuilder.goalIntentContextLines` — propose / change-trade-off
//     / anti-thrash framing.

@Suite("GoalIntentDetectionTests")
struct GoalIntentDetectionTests {

    // kind: initialSet when cold start, change when a voice already exists.

    @Test func initialSetWhenNoCurrentVoice() {
        let intent = CoachContextBuilder.detectGoalIntent(
            "Can I set my communication style and goals here with you now?",
            currentVoice: nil
        )
        #expect(intent?.kind == .initialSet)
    }

    @Test func changeWhenCurrentVoiceExists() {
        let intent = CoachContextBuilder.detectGoalIntent(
            "I want to switch my voice to persuasive instead.",
            currentVoice: .authoritative
        )
        #expect(intent?.kind == .change)
        #expect(intent?.requestedVoice == .persuasive)
    }

    // Resolve each of the 6 voices from a natural-language alias (not the
    // rawValue / title) so the detector matches how a user actually types.

    @Test func resolvesAllSixVoicesFromAliases() {
        let cases: [(String, SpeakingStyleGoal)] = [
            ("I want to sound more commanding", .authoritative),
            ("can you make my voice more welcoming", .warm),
            ("set my voice to sharp and crisp", .concise),
            ("change my voice to be more convincing", .persuasive),
            ("change my style to boardroom ready", .executive),
            ("I'd rather work on vivid storytelling", .storytelling),
        ]
        for (text, expected) in cases {
            let intent = CoachContextBuilder.detectGoalIntent(text, currentVoice: .warm)
            #expect(intent?.requestedVoice == expected, "Expected \(expected) for: \(text)")
        }
    }

    @Test func resolvesFromExactRawValueAndTitle() {
        // resolve(_:) coverage through the detector — rawValue + display title.
        let raw = CoachContextBuilder.detectGoalIntent("set my voice to warm", currentVoice: nil)
        #expect(raw?.requestedVoice == .warm)
        let title = CoachContextBuilder.detectGoalIntent(
            "change my voice to Executive presence",
            currentVoice: .warm
        )
        #expect(title?.requestedVoice == .executive)
    }

    // Non-goal text returns nil so the card never surfaces spuriously.

    @Test func returnsNilOnNonGoalText() {
        #expect(CoachContextBuilder.detectGoalIntent("How did my last rep go?", currentVoice: .warm) == nil)
        #expect(CoachContextBuilder.detectGoalIntent("What does authoritative even mean?", currentVoice: nil) == nil)
        #expect(CoachContextBuilder.detectGoalIntent("Tell me more.", currentVoice: .concise) == nil)
        #expect(CoachContextBuilder.detectGoalIntent("", currentVoice: nil) == nil)
    }

    @Test func setPhraseWithNoNamedVoiceStillFiresWithNilVoice() {
        // "help me pick" turns the dead-end into a guided pick — the card
        // offers the palette. Intent fires, requestedVoice is nil.
        let intent = CoachContextBuilder.detectGoalIntent(
            "Can you help me pick a voice?",
            currentVoice: nil
        )
        #expect(intent != nil)
        #expect(intent?.requestedVoice == nil)
        #expect(intent?.kind == .initialSet)
    }

    @Test func bareVoiceMentionWithoutIntentDoesNotFire() {
        // A voice word with no set/change phrase AND no goal/voice/style anchor
        // must NOT trip the card — only a real request should.
        #expect(CoachContextBuilder.detectGoalIntent("That was a really persuasive close.", currentVoice: .warm) == nil)
    }

    // S1 — non-canonical descriptor closest-match. A user can name a QUALITY
    // ("engaging") that is not one of the six register words; with an explicit
    // set/change phrase present, it maps to the nearest canonical voice. "engaging"
    // is verbatim in Storytelling's coachingDescription ("vivid, engaging, and
    // memorable"), so it resolves to .storytelling — never a fabricated voice.

    @Test func nonCanonicalDescriptorWithIntentResolvesToClosestVoice() {
        let intent = CoachContextBuilder.detectGoalIntent(
            "I want to sound more engaging",
            currentVoice: .warm
        )
        #expect(intent != nil)
        #expect(intent?.kind == .change)
        // Closest-match resolves the descriptor onto a canonical voice; the
        // only acceptable outcomes are the mapped voice or a nil (guided pick) —
        // NEVER an invented voice. "engaging" maps to .storytelling.
        #expect(intent?.requestedVoice == .storytelling || intent?.requestedVoice == nil)
        #expect(intent?.requestedVoice == .storytelling)
    }

    @Test func descriptorClosestMatchCoversRepresentativeQualities() {
        // Each descriptor must land on one of the six canonical voices (or nil),
        // gated by an explicit set/change phrase. Never an invented voice.
        let cases: [(String, SpeakingStyleGoal)] = [
            ("I want to sound more engaging", .storytelling),
            ("I want to sound more composed", .executive),
            ("I want to sound more efficient", .concise),
            ("I want to sound more assured", .authoritative),
            ("I want to sound more encouraging", .warm),
        ]
        for (text, expected) in cases {
            let intent = CoachContextBuilder.detectGoalIntent(text, currentVoice: .warm)
            #expect(intent?.requestedVoice == expected, "Expected \(expected) for: \(text)")
        }
    }

    @Test func bareDescriptorWithoutIntentDoesNotFire() {
        // A descriptor with NO set/change phrase and NO goal/voice/style anchor
        // must NOT trip the card — the closest-match second pass is gated behind
        // an explicit intent cue, so a casual quality mention resolves nothing.
        #expect(CoachContextBuilder.detectGoalIntent("That felt really engaging.", currentVoice: .warm) == nil)
        #expect(CoachContextBuilder.detectGoalIntent("She seemed very composed up there.", currentVoice: .concise) == nil)
    }

    @Test func unmappableDescriptorWithIntentFallsToGuidedPick() {
        // A set/change phrase whose quality maps to NONE of the six voices must
        // return requestedVoice == nil (guided pick), never a fabricated voice.
        let intent = CoachContextBuilder.detectGoalIntent(
            "I want to sound more mysterious",
            currentVoice: .warm
        )
        #expect(intent != nil)
        #expect(intent?.requestedVoice == nil)
    }
}

@Suite("SecondaryStyleGoalDecodeSafetyTests")
struct SecondaryStyleGoalDecodeSafetyTests {

    private func legacyProfileJSON() -> Data {
        // A profile persisted before `secondaryStyleGoal` existed — the key is
        // simply absent. Must decode with secondaryStyleGoal == nil.
        let json = """
        {
            "speakingContext": "work",
            "primaryGoal": "reduceFillers",
            "confidenceLevel": "rebuilding",
            "biggestChallenge": "fillerWords",
            "desiredOutcome": "concise",
            "speakingStyleGoal": "authoritative",
            "styleReference": "",
            "coachingBrief": "Brief stakeholders clearly.",
            "motivationWhyNow": "",
            "successVision": ""
        }
        """
        return Data(json.utf8)
    }

    @Test func legacyProfileWithoutKeyDecodesToNil() throws {
        let profile = try JSONDecoder().decode(CoachingProfile.self, from: legacyProfileJSON())
        #expect(profile.secondaryStyleGoal == nil)
        // Existing fields still decode unchanged (decode-safety regression guard).
        #expect(profile.speakingStyleGoal == .authoritative)
        #expect(profile.coachingBrief == "Brief stakeholders clearly.")
    }

    @Test func roundTripPreservesSetSecondary() throws {
        var profile = CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: .warm,
            styleReference: "",
            coachingBrief: "Brief stakeholders clearly.",
            motivationWhyNow: "",
            successVision: ""
        )
        profile.secondaryStyleGoal = .persuasive

        let data = try JSONEncoder().encode(profile)
        let decoded = try JSONDecoder().decode(CoachingProfile.self, from: data)
        #expect(decoded.secondaryStyleGoal == .persuasive)
        #expect(decoded.speakingStyleGoal == .warm)
        #expect(decoded == profile)
    }

    @Test func defaultMemberwiseInitLeavesSecondaryNil() {
        let profile = CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: .concise,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: ""
        )
        #expect(profile.secondaryStyleGoal == nil)
    }
}

@Suite("BlendedAlignedSkillAreasTests")
struct BlendedAlignedSkillAreasTests {

    private func profile(primary: SpeakingStyleGoal, secondary: SpeakingStyleGoal?) -> CoachingProfile {
        var p = CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .concise,
            speakingStyleGoal: primary,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: "",
            chosenStyleGoal: primary
        )
        p.secondaryStyleGoal = secondary
        return p
    }

    @Test func singleVoiceEqualsEnumLevelSet() {
        let p = profile(primary: .warm, secondary: nil)
        #expect(p.blendedAlignedSkillAreas == SpeakingStyleGoal.warm.alignedSkillAreas)
    }

    @Test func blendIsUnionOfBothVoices() {
        // concise = {conciseSpeaking, structure, fillerReduction}
        // warm    = {paceControl, vocalEmphasis, answerDevelopment}
        // disjoint → union has 6.
        let p = profile(primary: .concise, secondary: .warm)
        let expected = SpeakingStyleGoal.concise.alignedSkillAreas
            .union(SpeakingStyleGoal.warm.alignedSkillAreas)
        #expect(p.blendedAlignedSkillAreas == expected)
        #expect(p.blendedAlignedSkillAreas.count == 6)
        #expect(p.blendedAlignedSkillAreas.contains(.conciseSpeaking))
        #expect(p.blendedAlignedSkillAreas.contains(.paceControl))
    }

    @Test func blendWithSameSecondaryCollapsesToPrimary() {
        // A degenerate "blend" where secondary == primary must not double-count
        // or change the set — it reads as a single voice.
        let p = profile(primary: .persuasive, secondary: .persuasive)
        #expect(p.blendedAlignedSkillAreas == SpeakingStyleGoal.persuasive.alignedSkillAreas)
    }
}

@MainActor
@Suite("NoteVoiceChangeTests")
struct NoteVoiceChangeTests {

    private func makeMemory() -> CoachMemory {
        CoachMemory(
            updatedAt: Date(timeIntervalSince1970: 1_000),
            evidenceCount: 6,
            evidenceConfidence: .moderate,
            goalFit: .aligned,
            strengths: [],
            blockers: []
        )
    }

    private func reason(from: SpeakingStyleGoal, to: SpeakingStyleGoal) -> String {
        // Use the canonical composer so the test stays in lockstep with the
        // marker the anti-thrash counter reads.
        CoachCourseChange.voiceChangeReason(from: from, to: to)
    }

    @Test func canonicalReasonAlwaysCarriesMarker() {
        for from in SpeakingStyleGoal.allCases {
            for to in SpeakingStyleGoal.allCases {
                let switchReason = CoachCourseChange.voiceChangeReason(from: from, to: to)
                let blendReason = CoachCourseChange.voiceChangeReason(from: from, to: to, kind: .blend)
                #expect(switchReason.range(of: CoachCourseChange.voiceChangeMarker, options: .caseInsensitive) != nil)
                #expect(blendReason.range(of: CoachCourseChange.voiceChangeMarker, options: .caseInsensitive) != nil)
            }
        }
    }

    @Test func appendsCourseChangeWithCorrectLeversAndMarker() {
        let suite = "note-voice-change-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "account-\(UUID().uuidString)"

        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        store.replaceForTesting(makeMemory())

        store.noteVoiceChange(
            from: .warm,
            to: .persuasive,
            reason: reason(from: .warm, to: .persuasive),
            evidenceBasis: "user-confirmed in chat",
            at: Date(timeIntervalSince1970: 2_000)
        )

        let entry = store.currentMemory?.adaptationLog?.last
        #expect(entry != nil)
        // Levers map via primaryAlignedSkillArea: warm -> paceControl,
        // persuasive -> structure.
        #expect(entry?.fromLever == .paceControl)
        #expect(entry?.toLever == .structure)
        #expect(entry?.documentsVoiceChange == true)
        #expect(entry?.changedAt == Date(timeIntervalSince1970: 2_000))
        // Persists + reloads.
        let reloaded = CoachMemoryStore(defaults: defaults, accountIDProvider: { accountID })
        #expect(reloaded.currentMemory?.adaptationLog?.last?.toLever == .structure)
        #expect(reloaded.currentMemory?.adaptationLog?.last?.documentsVoiceChange == true)
    }

    @Test func isNoOpWithoutCurrentMemory() {
        // Cold start: no memory to record against; the profile write is the
        // durable record there. Must not crash or create a memory.
        let suite = "note-voice-change-nomem-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { "tester" })
        store.replaceForTesting(nil)

        store.noteVoiceChange(
            from: .warm,
            to: .concise,
            reason: reason(from: .warm, to: .concise),
            evidenceBasis: "user-confirmed in chat"
        )
        #expect(store.currentMemory == nil)
    }

    @Test func boundsAdaptationLogToEight() {
        let suite = "note-voice-change-bound-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { "tester" })
        store.replaceForTesting(makeMemory())

        // Ten appends → only the last 8 survive (matches the engine's ceiling).
        for i in 0..<10 {
            store.noteVoiceChange(
                from: .warm,
                to: .concise,
                reason: reason(from: .warm, to: .concise),
                evidenceBasis: "change #\(i)",
                at: Date(timeIntervalSince1970: TimeInterval(1_000 + i))
            )
        }
        #expect(store.currentMemory?.adaptationLog?.count == 8)
        // The earliest two were dropped; the newest is retained.
        #expect(store.currentMemory?.adaptationLog?.first?.evidenceBasis == "change #2")
        #expect(store.currentMemory?.adaptationLog?.last?.evidenceBasis == "change #9")
    }

    @Test func preservesPriorEngineCourseChanges() {
        // The voice change APPENDS; it must not wipe an engine-recorded
        // course change already in the log.
        let suite = "note-voice-change-preserve-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = CoachMemoryStore(defaults: defaults, accountIDProvider: { "tester" })
        var memory = makeMemory()
        memory.adaptationLog = [
            CoachCourseChange(
                id: UUID(),
                changedAt: Date(timeIntervalSince1970: 500),
                fromLever: .fillerReduction,
                toLever: .structure,
                reason: "Shifted focus from Filler Words to Structure.",
                evidenceBasis: "updated read across recent reps"
            )
        ]
        store.replaceForTesting(memory)

        store.noteVoiceChange(
            from: .warm,
            to: .concise,
            reason: reason(from: .warm, to: .concise),
            evidenceBasis: "user-confirmed in chat",
            at: Date(timeIntervalSince1970: 2_000)
        )
        #expect(store.currentMemory?.adaptationLog?.count == 2)
        #expect(store.currentMemory?.adaptationLog?.first?.documentsVoiceChange == false)
        #expect(store.currentMemory?.adaptationLog?.last?.documentsVoiceChange == true)
    }
}

@Suite("RecentVoiceChangeCountTests")
struct RecentVoiceChangeCountTests {

    private func voiceChange(at date: Date) -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: date,
            fromLever: .paceControl,
            toLever: .structure,
            reason: CoachCourseChange.voiceChangeReason(from: .warm, to: .persuasive),
            evidenceBasis: "user-confirmed in chat"
        )
    }

    private func engineChange(at date: Date) -> CoachCourseChange {
        CoachCourseChange(
            id: UUID(),
            changedAt: date,
            fromLever: .fillerReduction,
            toLever: .structure,
            reason: "Shifted focus from Filler Words to Structure.",
            evidenceBasis: "updated read"
        )
    }

    @Test func nilLogCountsZero() {
        #expect(CoachContextBuilder.recentVoiceChangeCount(adaptationLog: nil) == 0)
    }

    @Test func countsOnlyInWindowVoiceChanges() {
        let now = Date(timeIntervalSince1970: 1_000_000)
        let day: TimeInterval = 24 * 60 * 60
        let log = [
            voiceChange(at: now.addingTimeInterval(-1 * day)),   // in window
            voiceChange(at: now.addingTimeInterval(-3 * day)),   // in window
            voiceChange(at: now.addingTimeInterval(-30 * day)),  // out of window
            engineChange(at: now.addingTimeInterval(-1 * day)),  // not a voice change
        ]
        let count = CoachContextBuilder.recentVoiceChangeCount(
            adaptationLog: log,
            within: 7 * day,
            now: now
        )
        #expect(count == 2)
    }

    @Test func engineOnlyLogCountsZero() {
        let now = Date(timeIntervalSince1970: 1_000_000)
        let log = [engineChange(at: now), engineChange(at: now.addingTimeInterval(-100))]
        #expect(CoachContextBuilder.recentVoiceChangeCount(adaptationLog: log, now: now) == 0)
    }
}

@Suite("GoalIntentContextLinesTests")
struct GoalIntentContextLinesTests {

    @Test func initialSetEmitsProposeNotCommitted() {
        let lines = CoachContextBuilder.goalIntentContextLines(
            intent: .init(requestedVoice: .warm, kind: .initialSet),
            currentVoice: nil,
            adaptationLog: nil
        )
        #expect(lines.contains { $0.contains("SET their voice to Warm and welcoming") })
        #expect(lines.contains { $0.contains("do NOT assume it is set") })
    }

    @Test func initialSetWithNoVoiceAsksToGuide() {
        let lines = CoachContextBuilder.goalIntentContextLines(
            intent: .init(requestedVoice: nil, kind: .initialSet),
            currentVoice: nil,
            adaptationLog: nil
        )
        #expect(lines.contains { $0.contains("not named a specific voice") })
    }

    @Test func changeNamesTradeOffAndRaisesAsQuestion() {
        let lines = CoachContextBuilder.goalIntentContextLines(
            intent: .init(requestedVoice: .persuasive, kind: .change),
            currentVoice: .authoritative,
            adaptationLog: nil
        )
        #expect(lines.contains { $0.contains("CHANGE their voice from Authoritative to Persuasive") })
        #expect(lines.contains { $0.contains("Name the trade-off") })
        #expect(lines.contains { $0.contains("their call") })
    }

    // S1 — the change branch must carry an explicit clarifying-question
    // instruction (why change now / what has shifted) AND forbid the model from
    // claiming the change is set, mirroring system-prompt rule 16.
    @Test func changeBranchAsksWhyAndForbidsClaimingSet() {
        let lines = CoachContextBuilder.goalIntentContextLines(
            intent: .init(requestedVoice: .persuasive, kind: .change),
            currentVoice: .authoritative,
            adaptationLog: nil
        )
        #expect(lines.contains { $0.contains("ASK a clarifying question") })
        #expect(lines.contains { $0.contains("what has shifted") })
        #expect(lines.contains { $0.contains("do NOT state it is set") })
    }

    @Test func antiThrashNoteFiresAtThreshold() {
        let now = Date(timeIntervalSince1970: 1_000_000)
        let day: TimeInterval = 24 * 60 * 60
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: now.addingTimeInterval(-1 * day),
            fromLever: .paceControl,
            toLever: .structure,
            reason: CoachCourseChange.voiceChangeReason(from: .warm, to: .persuasive),
            evidenceBasis: "user-confirmed in chat"
        )
        // Two in-window voice changes → at threshold → anti-thrash note.
        let lines = CoachContextBuilder.goalIntentContextLines(
            intent: .init(requestedVoice: .concise, kind: .change),
            currentVoice: .persuasive,
            adaptationLog: [change, change],
            now: now
        )
        #expect(lines.contains { $0.contains("changed voice 2 times in the last week") })
        #expect(lines.contains { $0.contains("Do not punish-shame") })
    }

    @Test func antiThrashNoteAbsentBelowThreshold() {
        let now = Date(timeIntervalSince1970: 1_000_000)
        let change = CoachCourseChange(
            id: UUID(),
            changedAt: now.addingTimeInterval(-1 * 24 * 60 * 60),
            fromLever: .paceControl,
            toLever: .structure,
            reason: CoachCourseChange.voiceChangeReason(from: .warm, to: .persuasive),
            evidenceBasis: "user-confirmed in chat"
        )
        let lines = CoachContextBuilder.goalIntentContextLines(
            intent: .init(requestedVoice: .concise, kind: .change),
            currentVoice: .persuasive,
            adaptationLog: [change],
            now: now
        )
        #expect(!lines.contains { $0.contains("times in the last week") })
    }
}

// MARK: - Goal proposal card (S3 — in-chat set / change confirmation)
//
// S3 wires the human-in-the-loop affordance into AskNoumView. The deterministic
// seams under test here are the two pure functions the view + tap handlers read:
//   • `CoachContextBuilder.shouldShowGoalProposal(messages:intentPresent:)` —
//     the visibility predicate. Same chat-shape gate as the ack rows (last
//     message is a non-pending coach reply) AND a detected intent is pending.
//   • `CoachContextBuilder.goalProposalChips(intent:currentVoice:)` — the chip
//     catalog. Four shapes: cold-start-with-target, cold-start-palette,
//     change-with-target (switch / blend / keep), change-palette.
//
// The commit handlers (`recordGoalSet` / `recordGoalChange`) touch @MainActor
// stores + the model and are verified by hand-trace + on-device QA (no toolchain
// / keys on this host). The LLM-never-writes invariant is enforced statically
// (the only `CoachingProfileStore.save` call sites in the chat path are the two
// tap handlers, never the service or `runReply`).

@Suite("GoalProposalPredicateTests")
struct GoalProposalPredicateTests {

    @Test func showsWhenCoachRepliedAndIntentPending() {
        // Happy path: the user asked to set/change a voice (intent present),
        // the coach replied (most-recent, non-pending). Card eligible.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "Can I set my communication style here with you?"),
            CoachMessage(role: .coach, text: "We can — want me to set it to warm?", isPending: false),
        ]
        #expect(CoachContextBuilder.shouldShowGoalProposal(messages: messages, intentPresent: true) == true)
    }

    @Test func hiddenWhenNoIntentPending() {
        // Same chat shape, but no detected intent — a plain coach reply to a
        // plain question must never surface the goal card.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "How did my last rep go?"),
            CoachMessage(role: .coach, text: "Your filler rate dropped to 3.1 per minute.", isPending: false),
        ]
        #expect(CoachContextBuilder.shouldShowGoalProposal(messages: messages, intentPresent: false) == false)
    }

    @Test func hiddenWhileCoachReplyPending() {
        // While the model composes, no card — there's no reply to anchor the
        // confirmation under.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "Change my voice to persuasive."),
            CoachMessage(role: .coach, text: "", isPending: true),
        ]
        #expect(CoachContextBuilder.shouldShowGoalProposal(messages: messages, intentPresent: true) == false)
    }

    @Test func hiddenWhenLastMessageIsUserTurn() {
        // After the user types again, the conversation moved on — collapse the
        // card so a stale confirmation can't land out of order.
        let messages: [CoachMessage] = [
            CoachMessage(role: .user, text: "Change my voice to persuasive."),
            CoachMessage(role: .coach, text: "Want me to switch you?", isPending: false),
            CoachMessage(role: .user, text: "Actually tell me more first."),
        ]
        #expect(CoachContextBuilder.shouldShowGoalProposal(messages: messages, intentPresent: true) == false)
    }

    @Test func hiddenOnEmptyMessages() {
        #expect(CoachContextBuilder.shouldShowGoalProposal(messages: [], intentPresent: true) == false)
    }
}

// MARK: - ChatContinuationSurfaceTests
//
// Iteration 6 one-per-turn arbiter: every substantive coach turn ends in
// exactly ONE continuation surface. The chat body switches on
// `CoachContextBuilder.continuationSurface(...)`, so a pending decision (goal
// commit / hypothesis verdict / revised-read verdict) and the "Next move"
// panel can never stack under a single coach reply. Priority pinned here:
// goal proposal (the only profile-commit path — the model never writes)
// > hypothesis ack > revised-read verdict > next move > nothing.

@Suite("ChatContinuationSurfaceTests")
struct ChatContinuationSurfaceTests {

    @Test func goalProposalOutranksEveryOtherSurface() {
        // A goal-change turn whose reply also earned follow-up chips must
        // show ONLY the commit card — the chips would compete with the
        // proposal the coach just gave.
        let surface = CoachContextBuilder.continuationSurface(
            goalProposalEligible: true,
            hypothesisAckEligible: true,
            revisedReadFollowUpEligible: true,
            nextMoveAvailable: true
        )
        #expect(surface == .goalProposal)
    }

    @Test func hypothesisAckOutranksNextMove() {
        // A case-review reply that also names a launchable mode: the user
        // owes the thread a verdict before the coach assigns homework.
        let surface = CoachContextBuilder.continuationSurface(
            goalProposalEligible: false,
            hypothesisAckEligible: true,
            revisedReadFollowUpEligible: false,
            nextMoveAvailable: true
        )
        #expect(surface == .hypothesisAcknowledgement)
    }

    @Test func revisedReadVerdictOutranksNextMove() {
        let surface = CoachContextBuilder.continuationSurface(
            goalProposalEligible: false,
            hypothesisAckEligible: false,
            revisedReadFollowUpEligible: true,
            nextMoveAvailable: true
        )
        #expect(surface == .revisedReadFollowUp)
    }

    @Test func nextMoveRendersWhenNoDecisionIsPending() {
        let surface = CoachContextBuilder.continuationSurface(
            goalProposalEligible: false,
            hypothesisAckEligible: false,
            revisedReadFollowUpEligible: false,
            nextMoveAvailable: true
        )
        #expect(surface == .nextMove)
    }

    @Test func nilWhenNoSurfaceEarned() {
        // A greeting turn whose reply earned no continuation renders nothing
        // — no surface is fabricated just to fill the space.
        let surface = CoachContextBuilder.continuationSurface(
            goalProposalEligible: false,
            hypothesisAckEligible: false,
            revisedReadFollowUpEligible: false,
            nextMoveAvailable: false
        )
        #expect(surface == nil)
    }
}

// MARK: - LiveCallLandingLineTests
//
// Iteration 6 live-call landing: when no case-file focus has been earned,
// the landing may show ONE data-grounded line built from the latest timed
// rep's delivery facts — and must show NOTHING on a true cold start (no
// measured pace → nil; rep-0 fabricates no read). Facts only, forward-only
// invites, brand voice (no exclamations).

@Suite("LiveCallLandingLineTests")
struct LiveCallLandingLineTests {

    @Test func coldStartWithoutMeasuredPaceShowsNoLine() {
        // Zero WPM = no rep / empty transcript. The landing must stay
        // "Tap Talk to begin" — never a fabricated read.
        #expect(CoachContextBuilder.liveCallLandingLine(wordsPerMinute: 0, fillerCount: 0) == nil)
        #expect(CoachContextBuilder.liveCallLandingLine(wordsPerMinute: 0, fillerCount: 5) == nil)
    }

    @Test func fillerHeavyRepInvitesTightening() {
        // >= 4 fillers (the same threshold the deterministic chat fallback
        // uses) earns the "tighten" invite, citing both facts.
        let line = CoachContextBuilder.liveCallLandingLine(wordsPerMinute: 142, fillerCount: 5)
        #expect(line == "Last rep: 142 WPM, 5 fillers — want to tighten that?")
    }

    @Test func cleanRepStatesFactsWithForwardInvite() {
        // A clean rep states the facts and invites forward — no verdict,
        // no celebration fabricated from one rep.
        let line = CoachContextBuilder.liveCallLandingLine(wordsPerMinute: 128, fillerCount: 0)
        #expect(line == "Last rep: 128 WPM, no fillers — want to pick it up from there?")
    }

    @Test func singularFillerReadsNaturally() {
        let line = CoachContextBuilder.liveCallLandingLine(wordsPerMinute: 115, fillerCount: 1)
        #expect(line?.contains("1 filler —") == true)
        #expect(line?.contains("fillers") == false)
    }

    @Test func landingLineHonorsBrandVoice() {
        // No exclamation marks, ever (brand non-negotiable), and the line
        // never judges — it cites and invites.
        for fillers in [0, 1, 3, 4, 9] {
            let line = CoachContextBuilder.liveCallLandingLine(wordsPerMinute: 150, fillerCount: fillers)
            #expect(line?.contains("!") == false)
            #expect(line?.hasPrefix("Last rep:") == true)
        }
    }

    @Test func liveLandingSelectsNewestTimedRepByDateNotArrayPosition() {
        let olderTimed = liveLandingSession(
            transcript: "older timed rep",
            date: Date(timeIntervalSince1970: 1_000),
            mode: .timed
        )
        let newestTimed = liveLandingSession(
            transcript: "newest timed rep",
            date: Date(timeIntervalSince1970: 3_000),
            mode: .timed
        )
        let newestButWrongMode = liveLandingSession(
            transcript: "newer non timed rep",
            date: Date(timeIntervalSince1970: 4_000),
            mode: .suddenDeath
        )

        let selected = LiveCoachCallView.latestTimedRepForLiveLanding(
            from: [newestTimed, newestButWrongMode, olderTimed]
        )

        #expect(selected?.id == newestTimed.id)
    }

    @Test func liveLandingSelectorReturnsNilWhenNoTimedRepExists() {
        let selected = LiveCoachCallView.latestTimedRepForLiveLanding(
            from: [
                liveLandingSession(
                    transcript: "pressure rep",
                    date: Date(timeIntervalSince1970: 2_000),
                    mode: .suddenDeath
                ),
                liveLandingSession(
                    transcript: "im rep",
                    date: Date(timeIntervalSince1970: 3_000),
                    mode: .imConversation
                )
            ]
        )

        #expect(selected == nil)
    }

    private func liveLandingSession(
        transcript: String,
        date: Date,
        mode: PracticeMode
    ) -> PracticeSession {
        PracticeSession(
            transcript: transcript,
            fillerWordCount: 1,
            duration: 60,
            date: date,
            mode: mode,
            score: 7
        )
    }
}

@Suite("GoalProposalChipCatalogTests")
struct GoalProposalChipCatalogTests {

    // MARK: - Cold start (.initialSet)

    @Test func coldStartWithTargetOffersSetAndDecline() {
        let chips = CoachContextBuilder.goalProposalChips(
            intent: .init(requestedVoice: .warm, kind: .initialSet),
            currentVoice: nil
        )
        #expect(chips.count == 2)
        // First chip commits the set; carries the resolved voice.
        #expect(chips.first?.action == .set(.warm))
        #expect(chips.first?.label == "Set Warm and welcoming")
        // Last chip declines.
        #expect(chips.last?.action == .decline)
        // No `noteVoiceChange`/blend semantics on cold start — only set/decline.
        #expect(chips.allSatisfy { chip in
            if case .switchTo = chip.action { return false }
            if case .blend = chip.action { return false }
            return true
        })
    }

    @Test func coldStartWithoutTargetOffersFullPalettePlusDecline() {
        let chips = CoachContextBuilder.goalProposalChips(
            intent: .init(requestedVoice: nil, kind: .initialSet),
            currentVoice: nil
        )
        // Six voices + one decline.
        #expect(chips.count == SpeakingStyleGoal.allCases.count + 1)
        #expect(chips.last?.action == .decline)
        // Every voice is represented exactly once as a `.set`.
        let setVoices: [SpeakingStyleGoal] = chips.compactMap { chip in
            if case .set(let v) = chip.action { return v }
            return nil
        }
        #expect(Set(setVoices) == Set(SpeakingStyleGoal.allCases))
        #expect(setVoices.count == SpeakingStyleGoal.allCases.count)
    }

    // MARK: - Change (.change)

    @Test func changeWithTargetOffersSwitchBlendKeep() {
        let chips = CoachContextBuilder.goalProposalChips(
            intent: .init(requestedVoice: .persuasive, kind: .change),
            currentVoice: .warm
        )
        #expect(chips.count == 3)
        #expect(chips[0].action == .switchTo(.persuasive))
        #expect(chips[1].action == .blend(.persuasive))
        #expect(chips[2].action == .decline) // "Keep <old>"
        // The blend chip names BOTH voices so the user reads what they keep.
        #expect(chips[1].label == "Blend Warm and welcoming + Persuasive")
        // The keep chip names the OLD voice so the decline is explicit.
        #expect(chips[2].label == "Keep Warm and welcoming")
    }

    @Test func changeOmitsBlendWhenTargetEqualsCurrent() {
        // A "change" whose resolved target is the SAME as the current voice
        // (degenerate, but possible if the detector resolves the active voice):
        // no blend chip (blending a voice with itself is meaningless), just
        // switch (a harmless no-op the commit handler guards) + keep.
        let chips = CoachContextBuilder.goalProposalChips(
            intent: .init(requestedVoice: .warm, kind: .change),
            currentVoice: .warm
        )
        #expect(!chips.contains { chip in
            if case .blend = chip.action { return true }
            return false
        })
        #expect(chips.contains { $0.action == .decline })
    }

    @Test func changeWithoutTargetOffersPaletteExcludingCurrentPlusKeep() {
        let chips = CoachContextBuilder.goalProposalChips(
            intent: .init(requestedVoice: nil, kind: .change),
            currentVoice: .warm
        )
        // Five switch targets (all voices except the current one) + keep.
        #expect(chips.count == SpeakingStyleGoal.allCases.count - 1 + 1)
        #expect(chips.last?.action == .decline)
        let switchVoices: [SpeakingStyleGoal] = chips.compactMap { chip in
            if case .switchTo(let v) = chip.action { return v }
            return nil
        }
        // Current voice must NOT appear as a switch target.
        #expect(!switchVoices.contains(.warm))
        #expect(Set(switchVoices) == Set(SpeakingStyleGoal.allCases).subtracting([.warm]))
    }

    @Test func everyChipCarriesNonEmptyDispatchAndStableID() {
        // The dispatched continuation text is what keeps the chat continuous
        // after a tap — it must never be empty, and IDs must be unique so the
        // SwiftUI ForEach + accessibility identifiers stay stable.
        let catalogs: [[CoachContextBuilder.GoalProposalChip]] = [
            CoachContextBuilder.goalProposalChips(intent: .init(requestedVoice: .warm, kind: .initialSet), currentVoice: nil),
            CoachContextBuilder.goalProposalChips(intent: .init(requestedVoice: nil, kind: .initialSet), currentVoice: nil),
            CoachContextBuilder.goalProposalChips(intent: .init(requestedVoice: .persuasive, kind: .change), currentVoice: .warm),
            CoachContextBuilder.goalProposalChips(intent: .init(requestedVoice: nil, kind: .change), currentVoice: .concise),
        ]
        for chips in catalogs {
            #expect(chips.allSatisfy { !$0.dispatchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty })
            #expect(chips.allSatisfy { !$0.label.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty })
            #expect(Set(chips.map { $0.id }).count == chips.count)
        }
    }
}

@Suite("LessonProgressPresentationTests")
struct LessonProgressPresentationTests {
    @Test func presentationClampsAndUsesPracticePassLanguage() {
        let low = LessonProgressPresentation(completedPasses: -2)
        let high = LessonProgressPresentation(completedPasses: 99)

        #expect(low.completedPasses == 0)
        #expect(high.completedPasses == LessonProgressPresentation.masteryPassCap)
        #expect(high.fractionText == "5/5")
        #expect(high.accessibilityLabel == "5 of 5 spaced practice rounds complete")
    }

    @Test func lessonSummaryAvoidsLegacyRewardLanguage() {
        let summary = LessonProgressPresentation(completedPasses: 2)
            .lessonSummaryLine(title: "Rule of Three")

        #expect(summary == "2 of 5 spaced rounds on Rule of Three.")
        #expect(!summary.localizedCaseInsensitiveContains("crown"))
        #expect(!summary.localizedCaseInsensitiveContains("XP"))
    }

    @Test func legacyProgressFieldStillDecodes() throws {
        let data = #"{"lessonID":"rule_of_three","crownLevel":3,"totalAttempts":4}"#
            .data(using: .utf8)!

        let progress = try JSONDecoder().decode(LessonProgress.self, from: data)

        #expect(progress.lessonID == "rule_of_three")
        #expect(progress.practicePassCount == 3)
        #expect(progress.totalAttempts == 4)
    }

    @Test func progressEncodesNewPracticePassFieldOnly() throws {
        let progress = LessonProgress(
            lessonID: "rule_of_three",
            practicePassCount: 3,
            lastCompletedAt: nil,
            totalAttempts: 4
        )

        let data = try JSONEncoder().encode(progress)
        let object = try #require(JSONSerialization.jsonObject(with: data) as? [String: Any])

        #expect(object["practicePassCount"] as? Int == 3)
        #expect(object["crownLevel"] == nil)
    }
}

@Suite("ReviewSurfaceCopyTests")
struct ReviewSurfaceCopyTests {
    @Test func recentRepReviewCopyDoesNotPromisePromptReplay() {
        #expect(RecentRepReviewCopy.header == "Review recent reps")
        #expect(RecentRepReviewCopy.action == "Practice this mode")
        #expect(!RecentRepReviewCopy.action.localizedCaseInsensitiveContains("prompt again"))
    }

    @Test func targetedPracticeHeaderAvoidsPunitiveLanguage() {
        let header = TargetedPracticeCopy.header
        #expect(header == "Targeted practice")
        #expect(!header.localizedCaseInsensitiveContains("mistake"))
        #expect(!header.localizedCaseInsensitiveContains("fix"))
    }

    @Test func recentRepReviewSignalRequiresRealFriction() {
        let now = Date(timeIntervalSince1970: 2_000_000)
        let ordinary = reviewSignalSession(date: now, score: 8, fillers: 1, mode: .timed)

        #expect(MistakeReplayCard.hasReviewRows(in: [ordinary], now: now) == false)
    }

    @Test func recentRepReviewSignalFindsLowScoreHighFillerAndEarlyPressure() {
        let now = Date(timeIntervalSince1970: 2_000_000)
        let lowScore = reviewSignalSession(date: now, score: 5, fillers: 1, mode: .timed)
        let highFiller = reviewSignalSession(date: now, score: 8, fillers: 6, mode: .ahCounter)
        let earlyPressure = reviewSignalSession(
            date: now,
            score: 7,
            fillers: 1,
            mode: .suddenDeath,
            insights: ["Survived 2 rounds"]
        )

        #expect(MistakeReplayCard.hasReviewRows(in: [lowScore], now: now) == true)
        #expect(MistakeReplayCard.hasReviewRows(in: [highFiller], now: now) == true)
        #expect(MistakeReplayCard.hasReviewRows(in: [earlyPressure], now: now) == true)
    }

    private func reviewSignalSession(
        date: Date,
        score: Int?,
        fillers: Int,
        mode: PracticeMode,
        insights: [String] = []
    ) -> PracticeSession {
        PracticeSession(
            transcript: "test transcript with enough ordinary words for a saved rep",
            fillerWordCount: fillers,
            duration: 60,
            date: date,
            mode: mode,
            score: score,
            insights: insights
        )
    }
}

// MARK: - Reward ownership (Iteration 1)
//
// The post-rep full celebration must fire ONLY on a real crossing detected by
// SessionFinalizer — never on a score or XP threshold (the prior
// `score>=7 || xp>=100` bug), and never on the first rep (milestone detection
// starts at count 10 / streak 3 and emits no PB on rep 1, so rep 1 yields
// milestone == nil -> hasMilestoneCrossing == false).
struct RewardOwnershipTests {
    @Test func celebrationNeverFiresFromScoreOrXPAlone() {
        guard #available(iOS 17.0, *) else { return }
        #expect(SummaryView.shouldShowCelebration(hasMilestoneCrossing: false, score: 10, xpEarned: 999) == false)
        #expect(SummaryView.shouldShowCelebration(hasMilestoneCrossing: false, score: 7, xpEarned: 100) == false)
        #expect(SummaryView.shouldShowCelebration(hasMilestoneCrossing: false, score: 0, xpEarned: 0) == false)
    }

    @Test func celebrationFiresOnlyOnRealCrossing() {
        guard #available(iOS 17.0, *) else { return }
        #expect(SummaryView.shouldShowCelebration(hasMilestoneCrossing: true, score: 0, xpEarned: 0) == true)
        #expect(SummaryView.shouldShowCelebration(hasMilestoneCrossing: true, score: 3, xpEarned: 5) == true)
    }

    @Test @MainActor func firstRepIsNotTreatedAsAMilestoneCrossing() {
        guard #available(iOS 17.0, *) else { return }

        let sessionStore = PracticeSessionStore.shared
        let profile = ProfileManager.shared
        let sessionSnapshot = sessionStore.sessions
        let xpSnapshot = profile.xp
        defer {
            sessionStore.replaceFromRemote(sessionSnapshot)
            profile.replaceFromRemote(xpSnapshot)
        }

        var firstRep = makePracticeSession(date: Date(), fillerCount: 1, duration: 45)
        firstRep.score = 7
        sessionStore.replaceFromRemote([firstRep])
        profile.replaceFromRemote(0)

        let result = SessionFinalizer.finalize(
            xpEarned: 35,
            scoreValue: 7,
            effectiveFillerCount: firstRep.fillerWordCount,
            effectiveDuration: firstRep.duration,
            transcriptWordCount: firstRep.wordCount,
            scoreBreakdown: [],
            currentMode: firstRep.mode,
            sessionPrompt: nil,
            latestSessionID: firstRep.id,
            recentSessions: [firstRep],
            imConversationDetails: nil,
            practiceTitle: "Timed Practice",
            derivedInsightsFirst: nil,
            pressureLevel: .standard,
            transcript: firstRep.transcript
        )

        #expect(result.milestone == nil)
        #expect(SummaryView.shouldShowCelebration(
            hasMilestoneCrossing: result.milestone != nil,
            score: 7,
            xpEarned: 35
        ) == false)
    }
}

// MARK: - Practice picker goal grounding (Iteration 5)
//
// Locks the honesty contract on the Coach-Pick hero's quiet goal line:
// it renders ONLY when there is a profile, the goal-refresh cadence is
// not due (never claim distance against a goal the user hasn't
// reconfirmed), and the baseline has measured evidence for the goal's
// dimension (`measuredDistanceFromGoal` != nil — no fabricated 0.5
// midpoint reads). The vocabulary is forward-only.
struct PracticeModeGoalGroundingTests {

    private static func stat(_ value: Double) -> BaselineStat {
        BaselineStat(value: value, sampleCount: 10, confidence: .moderate, trend: .stable, percentile25: 0, percentile75: 0)
    }

    private static func measuredBaseline(fillerRate: Double) -> CommunicationBaseline {
        var b = CommunicationBaseline.empty
        b.fillerRate = stat(fillerRate)
        return b
    }

    private static func fillerProfile() -> CoachingProfile {
        CoachingProfile(
            speakingContext: .interviews,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .persuasive,
            speakingStyleGoal: .executive,
            styleReference: "",
            coachingBrief: "Sound sharper in interviews",
            motivationWhyNow: "",
            successVision: ""
        )
    }

    @Test func suppressesWithoutProfile() {
        let line = PracticeModeGoalGrounding.line(
            profile: nil,
            baseline: Self.measuredBaseline(fillerRate: 0),
            goalRefreshDue: false
        )
        #expect(line == nil)
    }

    @Test func suppressesWhenGoalRefreshIsDue() {
        // A due 2-week check-in means the stated goal may be stale —
        // never ground the prescription in a goal awaiting reconfirmation.
        let line = PracticeModeGoalGrounding.line(
            profile: Self.fillerProfile(),
            baseline: Self.measuredBaseline(fillerRate: 0),
            goalRefreshDue: true
        )
        #expect(line == nil)
    }

    @Test func suppressesOnInsufficientBaselineEvidence() {
        // CommunicationBaseline.empty has .insufficient confidence on all
        // stats — measuredDistanceFromGoal returns nil, so no line. The
        // unmeasured 0.5 fallback must never leak into the picker.
        let line = PracticeModeGoalGrounding.line(
            profile: Self.fillerProfile(),
            baseline: CommunicationBaseline.empty,
            goalRefreshDue: false
        )
        #expect(line == nil)
    }

    @Test func rendersGoalTitleAndForwardLabelWhenMeasured() {
        let line = PracticeModeGoalGrounding.line(
            profile: Self.fillerProfile(),
            baseline: Self.measuredBaseline(fillerRate: 0),
            goalRefreshDue: false
        )
        #expect(line == "Goal: Reduce filler words \u{00B7} On track")
    }

    @Test func farFromGoalStaysForwardOnly() {
        // distance 1.0 renders the neutral "Early days" — never deficit,
        // countdown, or shame framing.
        let line = PracticeModeGoalGrounding.line(
            profile: Self.fillerProfile(),
            baseline: Self.measuredBaseline(fillerRate: 8),
            goalRefreshDue: false
        )
        #expect(line == "Goal: Reduce filler words \u{00B7} Early days")
    }
}

// MARK: - RetentionLoopEngine displayed-streak override (Iteration 5)
//
// Locks the streak consolidation: live call sites hand the freeze-aware
// displayed streak from StreakFreezeManager into the retention snapshot,
// so the "X/2 days" challenge label and streak achievements can never
// disagree with the streak number Home/Profile show.
struct RetentionLoopDisplayedStreakTests {

    @Test func snapshotUsesProvidedDisplayedStreak() {
        let snapshot = RetentionLoopEngine.snapshot(
            sessions: [],
            profile: nil,
            displayedStreak: 1
        )
        #expect(snapshot.activeChallenge.title == "Build a rhythm")
        #expect(snapshot.activeChallenge.progressLabel == "1/2 days")
        // Quiet-streak owner decision: the rhythm challenge is an invite,
        // never possession/loss framing.
        let copy = "\(snapshot.activeChallenge.title) \(snapshot.activeChallenge.summary)".lowercased()
        for banned in ["hold the", "keep the", "lose", "don't break"] {
            #expect(!copy.contains(banned))
        }
    }

    @Test func snapshotFallsBackToRawCalcWithoutOverride() {
        let snapshot = RetentionLoopEngine.snapshot(
            sessions: [],
            profile: nil
        )
        #expect(snapshot.activeChallenge.progressLabel == "0/2 days")
    }
}

// MARK: - C3-felt-memory — evidence age/depth behind the working hypothesis
//
// The coach's hypothesis should FEEL durable: "Watching this across 9 reps
// over 3 weeks", not a line regenerated per rep. These tests lock the three
// layers: (1) the pure span/depth phrasing on `CoachCaseFile` (one shared
// implementation for Profile + post-rep note + chat case file), (2) the
// `hypothesisWatchStartedAt` anchor's carry-forward contract on
// `CoachMemoryEngine`, and (3) the tentative-below-the-floor invariant —
// below `.moderate` (the same floor where `workingHypothesis` switches from
// "may be" to "appears to be") every surface hedges, never asserts.

struct HypothesisEvidenceDepthTests {

    private var utc: Calendar {
        var cal = Calendar(identifier: .gregorian)
        cal.timeZone = TimeZone(identifier: "UTC")!
        return cal
    }

    private let now = Date(timeIntervalSince1970: 1_700_000_000)

    private func daysAgo(_ days: Double) -> Date {
        now.addingTimeInterval(-days * 86_400)
    }

    // MARK: - watchSpanPhrase

    @Test func spanPhraseIsNilWithoutProvableSpan() {
        #expect(CoachCaseFile.watchSpanPhrase(from: nil, to: now, calendar: utc) == nil)
        #expect(CoachCaseFile.watchSpanPhrase(from: daysAgo(0.5), to: now, calendar: utc) == nil)
        // A future anchor must never produce a span (never invent age).
        #expect(CoachCaseFile.watchSpanPhrase(from: daysAgo(-2), to: now, calendar: utc) == nil)
    }

    @Test func spanPhraseScalesHonestlyWithAge() {
        #expect(CoachCaseFile.watchSpanPhrase(from: daysAgo(1), to: now, calendar: utc) == "since yesterday")
        #expect(CoachCaseFile.watchSpanPhrase(from: daysAgo(4), to: now, calendar: utc) == "over the past 4 days")
        #expect(CoachCaseFile.watchSpanPhrase(from: daysAgo(10), to: now, calendar: utc) == "over the past week")
        #expect(CoachCaseFile.watchSpanPhrase(from: daysAgo(21), to: now, calendar: utc) == "over 3 weeks")
        #expect(CoachCaseFile.watchSpanPhrase(from: daysAgo(70), to: now, calendar: utc) == "over 2 months")
    }

    // MARK: - evidenceDepthClause / evidenceDepthLine

    @Test func depthClauseComposesRepsAndSpan() {
        #expect(CoachCaseFile.evidenceDepthClause(
            evidenceCount: 0, watchingSince: daysAgo(21), now: now, calendar: utc
        ) == nil)
        #expect(CoachCaseFile.evidenceDepthClause(
            evidenceCount: 1, watchingSince: nil, now: now, calendar: utc
        ) == "1 rep")
        #expect(CoachCaseFile.evidenceDepthClause(
            evidenceCount: 9, watchingSince: daysAgo(21), now: now, calendar: utc
        ) == "9 reps over 3 weeks")
    }

    @Test func depthLineIsAssuredAtModerateFloor() {
        let line = CoachCaseFile.evidenceDepthLine(
            evidenceCount: 9,
            confidence: .moderate,
            watchingSince: daysAgo(21),
            now: now,
            calendar: utc
        )
        #expect(line == "Seen across 9 recent reps.")
    }

    @Test func depthLineHedgesBelowEvidenceFloor() {
        let noSpan = CoachCaseFile.evidenceDepthLine(
            evidenceCount: 4, confidence: .tentative,
            watchingSince: nil, now: now, calendar: utc
        )
        #expect(noSpan == "Early read — 4 reps so far; still forming.")

        let withSpan = CoachCaseFile.evidenceDepthLine(
            evidenceCount: 4, confidence: .insufficient,
            watchingSince: daysAgo(3), now: now, calendar: utc
        )
        #expect(withSpan == "Early read — 4 reps over the past 3 days; still forming.")

        // Below the floor the assured framing must never leak through.
        for line in [noSpan, withSpan] {
            #expect(line?.contains("Seen across") == false)
        }
        #expect(CoachCaseFile.evidenceDepthLine(
            evidenceCount: 0, confidence: .moderate,
            watchingSince: nil, now: now, calendar: utc
        ) == nil)
    }

    // MARK: - hypothesisWatchStart carry-forward contract

    private func previousMemory(
        lever: SkillArea?,
        hypothesis: String?,
        anchor: Date?,
        updatedAt: Date
    ) -> CoachMemory {
        CoachMemory(
            updatedAt: updatedAt,
            evidenceCount: 6,
            evidenceConfidence: .moderate,
            currentLever: lever,
            goalFit: .noLever,
            strengths: [],
            blockers: [],
            workingHypothesis: hypothesis,
            hypothesisWatchStartedAt: anchor
        )
    }

    @Test func watchStartIsNilWithoutHypothesis() {
        #expect(CoachMemoryEngine.hypothesisWatchStart(
            hasHypothesis: false,
            currentLever: .paceControl,
            previous: previousMemory(lever: .paceControl, hypothesis: "x", anchor: daysAgo(10), updatedAt: daysAgo(2)),
            now: now
        ) == nil)
    }

    @Test func firstHypothesisStartsTheWatchNow() {
        #expect(CoachMemoryEngine.hypothesisWatchStart(
            hasHypothesis: true,
            currentLever: .paceControl,
            previous: nil,
            now: now
        ) == now)
    }

    @Test func sameLeverCarriesTheAnchorForward() {
        let anchor = daysAgo(21)
        #expect(CoachMemoryEngine.hypothesisWatchStart(
            hasHypothesis: true,
            currentLever: .paceControl,
            previous: previousMemory(lever: .paceControl, hypothesis: "x", anchor: anchor, updatedAt: daysAgo(2)),
            now: now
        ) == anchor)
    }

    @Test func legacyPreviousWithoutAnchorClaimsOnlyUpdatedAt() {
        // A memory persisted before the anchor existed: the watch provably
        // existed at least since the previous rebuild — claim exactly that.
        let updated = daysAgo(5)
        #expect(CoachMemoryEngine.hypothesisWatchStart(
            hasHypothesis: true,
            currentLever: .paceControl,
            previous: previousMemory(lever: .paceControl, hypothesis: "x", anchor: nil, updatedAt: updated),
            now: now
        ) == updated)
    }

    @Test func leverShiftResetsTheWatch() {
        #expect(CoachMemoryEngine.hypothesisWatchStart(
            hasHypothesis: true,
            currentLever: .openingStrength,
            previous: previousMemory(lever: .paceControl, hypothesis: "x", anchor: daysAgo(21), updatedAt: daysAgo(2)),
            now: now
        ) == now)
    }

    // MARK: - CoachMemory Codable backward compat

    @Test func memoryRoundTripPreservesWatchAnchor() throws {
        let anchor = daysAgo(21)
        let memory = previousMemory(lever: .paceControl, hypothesis: "x", anchor: anchor, updatedAt: now)
        let data = try JSONEncoder().encode(memory)
        let decoded = try JSONDecoder().decode(CoachMemory.self, from: data)
        #expect(decoded.hypothesisWatchStartedAt == anchor)
    }

    @Test func legacyBlobWithoutAnchorDecodesNil() throws {
        let memory = previousMemory(lever: .paceControl, hypothesis: "x", anchor: daysAgo(21), updatedAt: now)
        let data = try JSONEncoder().encode(memory)
        var object = try #require(
            try JSONSerialization.jsonObject(with: data) as? [String: Any]
        )
        object.removeValue(forKey: "hypothesisWatchStartedAt")
        let strippedData = try JSONSerialization.data(withJSONObject: object)
        let decoded = try JSONDecoder().decode(CoachMemory.self, from: strippedData)
        #expect(decoded.hypothesisWatchStartedAt == nil)
    }

    // MARK: - Case-file evidence summary carries the watch age

    @Test func caseFileEvidenceSummaryCarriesWatchAge() throws {
        // 21.5-day anchor: ≥ 21 complete days in any timezone/DST offset,
        // since `evidenceSummary` uses Calendar.current internally.
        var memory = previousMemory(
            lever: .paceControl,
            hypothesis: "Pace appears to be the highest-leverage focus because endings rush; keep checking against future reps.",
            anchor: daysAgo(21.5),
            updatedAt: now
        )
        memory.currentLeverBasis = "endings rush under pressure"
        let caseFile = try #require(CoachCaseFile.build(from: memory, now: now))
        #expect(caseFile.evidenceSummary.contains("watched over 3 weeks"))
        #expect(caseFile.evidenceSummary.contains("basis: endings rush under pressure"))
    }

    @Test func caseFileEvidenceSummaryOmitsAgeWithoutHypothesis() throws {
        var memory = previousMemory(lever: .paceControl, hypothesis: nil, anchor: nil, updatedAt: now)
        memory.currentLeverBasis = "endings rush under pressure"
        let caseFile = try #require(CoachCaseFile.build(from: memory, now: now))
        #expect(!caseFile.evidenceSummary.contains("watched"))
    }

    // MARK: - ProfileCoachReadContent evidence line

    @Test func profileReadCarriesAssuredEvidenceLine() {
        let memory = CoachMemory(
            updatedAt: now,
            evidenceCount: 8,
            evidenceConfidence: .moderate,
            currentLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: "Pace appears to be the highest-leverage focus because endings rush; keep checking against future reps.",
            hypothesisWatchStartedAt: daysAgo(21.5)
        )
        let content = ProfileCoachReadContent.make(
            sessionCount: 8,
            plan: nil,
            memory: memory,
            proof: nil,
            now: now
        )
        #expect(content.label == "FORMING READ")
        #expect(content.evidenceLine == "Seen across 8 recent reps.")
    }

    @Test func profileReadHedgesEvidenceLineBelowFloor() {
        let memory = CoachMemory(
            updatedAt: now,
            evidenceCount: 4,
            evidenceConfidence: .tentative,
            currentLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: "Pace may be the highest-leverage focus because endings rush; verify over more reps.",
            hypothesisWatchStartedAt: nil
        )
        let content = ProfileCoachReadContent.make(
            sessionCount: 4,
            plan: nil,
            memory: memory,
            proof: nil,
            now: now
        )
        // Pins the label dedup fix too: `.tentative.label` is already
        // "Early read", so the badge must read "EARLY READ", not
        // "EARLY READ READ".
        #expect(content.label == "EARLY READ")
        #expect(content.evidenceLine == "Early read — 4 reps so far; still forming.")
        #expect(content.evidenceLine?.contains("Seen across") == false)
    }

    @Test func profileReadHasNoEvidenceLineWithoutHypothesis() {
        let cold = ProfileCoachReadContent.make(
            sessionCount: 0, plan: nil, memory: nil, proof: nil, now: now
        )
        #expect(cold.evidenceLine == nil)

        let planOnly = ProfileCoachReadContent.make(
            sessionCount: 5,
            plan: CoachingPlan(
                strongestMode: .timed,
                currentFocus: "Focus on deliberate openings.",
                suggestedDrill: "Timed Practice on Medium.",
                encouragement: "Your recent sessions are steady.",
                hiddenBaseline: HiddenBaseline(
                    averageFillers: 2,
                    averageDuration: 45,
                    averageWordsPerMinute: 132,
                    currentIdentity: "Controlled"
                )
            ),
            memory: nil,
            proof: nil,
            now: now
        )
        #expect(planOnly.evidenceLine == nil)
    }
}

// MARK: - C3-felt-memory — standing watch in the post-rep coach note

struct PostRepStandingWatchTests {

    private var utc: Calendar {
        var cal = Calendar(identifier: .gregorian)
        cal.timeZone = TimeZone(identifier: "UTC")!
        return cal
    }

    private let now = Date(timeIntervalSince1970: 1_700_000_000)

    private func daysAgo(_ days: Double) -> Date {
        now.addingTimeInterval(-days * 86_400)
    }

    private func memory(
        hypothesis: String? = "Pace appears to be the highest-leverage focus because endings rush; keep checking against future reps.",
        confidence: BaselineConfidence = .moderate,
        evidenceCount: Int = 9,
        anchor: Date? = nil
    ) -> CoachMemory {
        CoachMemory(
            updatedAt: now,
            evidenceCount: evidenceCount,
            evidenceConfidence: confidence,
            currentLever: .paceControl,
            goalFit: .aligned,
            strengths: [],
            blockers: [],
            workingHypothesis: hypothesis,
            hypothesisWatchStartedAt: anchor
        )
    }

    private func input(
        watch: PostRepStandingWatch,
        bigMoment: BigMoment? = nil,
        bigMomentDaysUntil: Int? = nil,
        weeklyRepCount: Int = 0
    ) -> PostRepCoachNoteInput {
        PostRepCoachNoteInput(
            sessionID: UUID(),
            mode: .timed,
            score: nil,
            fillerCount: 0,
            duration: 30,
            wordCount: 10,
            voice: nil,
            intentLabel: nil,
            baselineFillerRate: nil,
            baselinePaceWPM: nil,
            bigMoment: bigMoment,
            bigMomentDaysUntil: bigMomentDaysUntil,
            weeklyRepCount: weeklyRepCount,
            standingHypothesis: watch.hypothesis,
            standingFocusLabel: watch.focusLabel,
            standingWatchClause: watch.clause,
            standingWatchIsAssured: watch.isAssured
        )
    }

    // MARK: - PostRepStandingWatch.make

    @Test func makeIsEmptyWithoutMemoryOrHypothesis() {
        let noMemory = PostRepStandingWatch.make(memory: nil, now: now, calendar: utc)
        #expect(noMemory.hypothesis == nil)
        #expect(noMemory.clause == nil)
        #expect(!noMemory.isAssured)

        let noHypothesis = PostRepStandingWatch.make(
            memory: memory(hypothesis: nil), now: now, calendar: utc
        )
        #expect(noHypothesis.hypothesis == nil)
        #expect(!noHypothesis.isAssured)
    }

    @Test func makeProjectsAssuredWatchFromMemory() {
        let watch = PostRepStandingWatch.make(
            memory: memory(anchor: daysAgo(21)), now: now, calendar: utc
        )
        #expect(watch.hypothesis?.isEmpty == false)
        #expect(watch.focusLabel == "Pace")
        #expect(watch.clause == "9 reps over 3 weeks")
        #expect(watch.isAssured)
    }

    @Test func makeStaysTentativeBelowEvidenceFloor() {
        let watch = PostRepStandingWatch.make(
            memory: memory(confidence: .tentative, evidenceCount: 4),
            now: now,
            calendar: utc
        )
        #expect(watch.hypothesis?.isEmpty == false)
        #expect(!watch.isAssured)
    }

    // MARK: - Deterministic note suffix

    @Test func deterministicNoteCarriesAssuredStandingWatch() {
        let watch = PostRepStandingWatch.make(
            memory: memory(anchor: daysAgo(21)), now: now, calendar: utc
        )
        let note = PostRepCoachNoteService.deterministicNote(input: input(watch: watch))
        #expect(note.noteText.contains("Still watching pace — 9 reps over 3 weeks."))
        #expect(!note.noteText.contains("!"))
    }

    @Test func deterministicNoteStaysSilentBelowEvidenceFloor() {
        // Weak evidence → softer feedback: the suffix never fires below
        // the `.moderate` floor, so a 3-rep "watch" can't read as durable.
        let watch = PostRepStandingWatch.make(
            memory: memory(confidence: .tentative, evidenceCount: 4, anchor: daysAgo(2)),
            now: now,
            calendar: utc
        )
        let note = PostRepCoachNoteService.deterministicNote(input: input(watch: watch))
        #expect(!note.noteText.lowercased().contains("watching"))
    }

    @Test func weeklyRhythmMilestoneOutranksStandingWatch() {
        let watch = PostRepStandingWatch.make(
            memory: memory(anchor: daysAgo(21)), now: now, calendar: utc
        )
        let note = PostRepCoachNoteService.deterministicNote(
            input: input(watch: watch, weeklyRepCount: 3)
        )
        #expect(note.noteText.contains("3 reps this week"))
        #expect(!note.noteText.contains("9 reps over 3 weeks"))
    }

    @Test func standingWatchSuffixIsVoiceShapedAndBrandClean() {
        for voice in SpeakingStyleGoal.allCases {
            let suffix = PostRepCoachNoteService.standingWatchSuffix(
                focusLabel: "Pace",
                watchClause: "9 reps over 3 weeks",
                isAssured: true,
                persona: CoachPersona.persona(for: voice)
            )
            #expect(suffix?.contains("9 reps over 3 weeks") == true)
            #expect(suffix?.contains("!") == false)
            #expect(suffix?.lowercased().contains("let's") == false)
        }
        #expect(PostRepCoachNoteService.standingWatchSuffix(
            focusLabel: "Pace",
            watchClause: "9 reps over 3 weeks",
            isAssured: false,
            persona: CoachPersona.persona(for: nil)
        ) == nil)
    }

    // MARK: - AI prompt block

    @Test func userPromptCarriesStandingCoachRead() {
        let watch = PostRepStandingWatch.make(
            memory: memory(anchor: daysAgo(21)), now: now, calendar: utc
        )
        let prompt = PostRepCoachNoteService.userPrompt(from: input(watch: watch))
        #expect(prompt.contains("STANDING COACH READ"))
        #expect(prompt.contains("Working hypothesis: Pace appears to be"))
        #expect(prompt.contains("Seen across 9 reps over 3 weeks."))
        #expect(!prompt.contains("Frame any reference to this read as tentative"))
    }

    @Test func userPromptInstructsTentativeFramingBelowFloor() {
        let watch = PostRepStandingWatch.make(
            memory: memory(confidence: .tentative, evidenceCount: 4),
            now: now,
            calendar: utc
        )
        let prompt = PostRepCoachNoteService.userPrompt(from: input(watch: watch))
        #expect(prompt.contains("STANDING COACH READ"))
        #expect(prompt.contains("tentative"))
        #expect(prompt.contains("never as established"))
        #expect(!prompt.contains("Seen across"))
    }

    @Test func userPromptOmitsBlockWithoutHypothesis() {
        let prompt = PostRepCoachNoteService.userPrompt(
            from: input(watch: .empty)
        )
        #expect(!prompt.contains("STANDING COACH READ"))
    }
}

// MARK: - C4-transfer-and-read — Move 8: post-rep delivery read line
//
// ONE bounded, qualitative delivery line in the post-rep verdict, fused
// from the existing per-rep ComposureRead + ConfidenceMarkerRead (each
// already enforcing its own 2-channel evidence floor). These tests pin
// the four contracts: self-suppression when either read is missing,
// bucket selection at the shared floors (deliveryClearFloor /
// deliveryTimidCeiling), the Pressure Drill variant, and the
// never-numeric / markers-not-person copy rules.

@Suite("PostRepDeliveryReadLineTests")
struct PostRepDeliveryReadLineTests {

    private func composure(_ score: Double) -> ComposureRead {
        ComposureRead(
            score: score,
            contributingChannels: 3,
            inputs: .init(
                vocalEnergyContributed: true,
                pitchContributed: false,
                pauseQualityContributed: true,
                hedgingContributed: true
            ),
            readout: "test composure readout"
        )
    }

    private func confidence(_ score: Double) -> ConfidenceMarkerRead {
        ConfidenceMarkerRead(
            score: score,
            contributingChannels: 3,
            inputs: .init(
                hedgingContributed: true,
                fillerDensityContributed: true,
                paceConsistencyContributed: false,
                composureContributed: true
            ),
            readout: "test confidence readout"
        )
    }

    /// Every emitted line across the bucket matrix — used by the copy-rule
    /// sweeps so a new bucket can't dodge the contracts.
    private var allEmittedLines: [String] {
        let scores: [Double] = [0.85, 0.65, 0.5, 0.4, 0.2]
        var lines: [String] = []
        for c in scores {
            for k in scores {
                for mode in [PracticeMode.timed, .suddenDeath] {
                    if let line = PostRepDeliveryReadLine.make(
                        composure: composure(c),
                        confidence: confidence(k),
                        mode: mode
                    ) {
                        lines.append(line)
                    }
                }
            }
        }
        return lines
    }

    @Test func suppressedWhenEitherReadIsMissing() {
        // Either engine returning nil (below its 2-channel floor) must
        // suppress the line entirely — silence over a one-channel guess.
        #expect(PostRepDeliveryReadLine.make(
            composure: nil, confidence: confidence(0.9), mode: .timed
        ) == nil)
        #expect(PostRepDeliveryReadLine.make(
            composure: composure(0.9), confidence: nil, mode: .timed
        ) == nil)
        #expect(PostRepDeliveryReadLine.make(
            composure: nil, confidence: nil, mode: .timed
        ) == nil)
    }

    @Test func steadyBucketRequiresBothReadsAtTheSharedClearFloor() {
        let line = PostRepDeliveryReadLine.make(
            composure: composure(DerivedReadsTrendEngine.deliveryClearFloor),
            confidence: confidence(DerivedReadsTrendEngine.deliveryClearFloor),
            mode: .timed
        )
        #expect(line == "Steady delivery this rep — composure held and the phrasing stayed direct.")
    }

    @Test func pressureDrillVariantNamesTheTimePressure() {
        let line = PostRepDeliveryReadLine.make(
            composure: composure(0.8),
            confidence: confidence(0.8),
            mode: .suddenDeath
        )
        #expect(line == "Steady delivery this rep — composure held under the time pressure.")
    }

    @Test func steadyEnergyWithTentativeMarkersBucket() {
        let line = PostRepDeliveryReadLine.make(
            composure: composure(0.8),
            confidence: confidence(0.5),
            mode: .timed
        )
        #expect(line == "Steady energy this rep, with a few tentative markers in the phrasing.")
    }

    @Test func directPhrasingDespiteWaveringEnergyBucket() {
        let line = PostRepDeliveryReadLine.make(
            composure: composure(0.4),
            confidence: confidence(0.8),
            mode: .timed
        )
        #expect(line == "The phrasing stayed direct this rep, even where the energy wavered.")
    }

    @Test func tentativeBucketCarriesTheOneRepHedge() {
        let line = PostRepDeliveryReadLine.make(
            composure: composure(0.3),
            confidence: confidence(DerivedReadsTrendEngine.deliveryTimidCeiling),
            mode: .timed
        )
        #expect(line == "This rep read as tentative in places — one rep's read, not a pattern.")
    }

    @Test func mixedBucketIsTheHonestMiddle() {
        let line = PostRepDeliveryReadLine.make(
            composure: composure(0.5),
            confidence: confidence(0.5),
            mode: .timed
        )
        #expect(line == "A mixed delivery read this rep — steady stretches alongside tentative beats.")
    }

    @Test func emittedLinesAreNeverNumeric() {
        // The verdict line is qualitative by contract — no score, no
        // composite, no channel count ever leaks into user copy.
        for line in allEmittedLines {
            #expect(line.rangeOfCharacter(from: .decimalDigits) == nil, "numeric leak in: \(line)")
        }
    }

    @Test func emittedLinesReadMarkersNeverThePerson() {
        // Anti-diagnosis rule: the line characterises THIS REP's markers,
        // never the speaker. No trait language, no "you are/sound/lack".
        let banned = ["you are", "you sound", "you lack", "you're", "timid person", "unconfident"]
        for line in allEmittedLines {
            let lowered = line.lowercased()
            for phrase in banned {
                #expect(!lowered.contains(phrase), "trait language in: \(line)")
            }
            #expect(!line.contains("!"))
        }
    }
}

