    @Test func checkInCopyUsesCategoryDisplayNameOnly() {
        // Privacy contract holds by construction (the helper takes only the
        // category), and the rendered title must embed the lowercase
        // sentence form — same rule as the T-7 / T-1 countdown copy.
        for category in BigMomentCategory.allCases {
            let copy = NotificationCopy.bigMomentCheckIn(category: category)
            #expect(copy.title == "How did your \(category.displayName) go?")
        }
    }
}

// MARK: - C4-transfer-and-read — Move 5: transient acknowledgment lifecycle

@MainActor
@Suite("BigMomentOutcomeAckTransientTests")
struct BigMomentOutcomeAckTransientTests {

    @Test func recordOutcomeSetsTheAckAndConsumeClearsIt() {
        let suite = "big-moment-ack-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = BigMomentStore(defaults: defaults, accountIDProvider: { "ack-account" })
        let moment = BigMoment(title: "Team review", category: .review)

        #expect(store.pendingOutcomeAck == nil)
        let report = store.recordOutcome(
            for: moment,
            outcome: .wentWell,
            audienceResponse: .engaged,
            drillTransfer: .transferred
        )
        #expect(store.pendingOutcomeAck == report)

        store.consumeOutcomeAck()
        #expect(store.pendingOutcomeAck == nil)
        // Consuming the transient ack never touches the persisted report.
        #expect(store.recentOutcomeReports().first?.momentID == moment.id)
    }

    @Test func ackIsInMemoryOnlyAndClearedByReload() {
        let suite = "big-moment-ack-reload-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let accountID = "ack-reload-account"
        let store = BigMomentStore(defaults: defaults, accountIDProvider: { accountID })
        store.recordOutcome(
            for: BigMoment(title: "Keynote", category: .publicSpeaking),
            outcome: .mixed,
            audienceResponse: .unclear
        )
        #expect(store.pendingOutcomeAck != nil)

        // Account reload (sign-in path) clears the transient beat.
        store.reloadForCurrentAccount()
        #expect(store.pendingOutcomeAck == nil)

        // A fresh store instance (relaunch) never resurrects it either.
        let relaunched = BigMomentStore(defaults: defaults, accountIDProvider: { accountID })
        relaunched.reloadForCurrentAccount()
        #expect(relaunched.pendingOutcomeAck == nil)
        #expect(relaunched.recentOutcomeReports().count == 1)
    }

    @Test func endSessionClearsTheAck() {
        let suite = "big-moment-ack-end-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = BigMomentStore(defaults: defaults, accountIDProvider: { "ack-end" })
        store.recordOutcome(
            for: BigMoment(title: "Interview", category: .interview),
            outcome: .fellShort,
            audienceResponse: .resistant
        )
        #expect(store.pendingOutcomeAck != nil)
        store.endSession()
        #expect(store.pendingOutcomeAck == nil)
    }
}

// MARK: - C5 — live-call STT provider chain (pure selection/fallback logic)

/// C5 — `LiveCallSTTChain` is the pure decision core behind the live coach
/// call's speech input: the configured cloud `TranscriptionProvider` leads
/// (the exact chain practice reps stream through), native Apple recognition
/// is the ALWAYS-terminal fallback, and a cloud provider that already failed
/// this surface session is skipped instead of re-tried on every hands-free
/// turn. These tests pin the selection and fallback decisions without a
/// recognizer, a network, or an audio engine.
struct C5LiveCallSTTChainTests {

    /// The canonical stored-value → provider mapping, shared with
    /// `SpeechRecognizerViewModel`: unset → Deepgram (the default),
    /// "deepgram"/"google" → themselves, and malformed legacy values fall
    /// back to the authenticated default rather than AWS. Pinned so
    /// the live call and practice reps can never resolve different providers
    /// from the same persisted setting.
    @Test func storedValueResolutionMatchesPracticeRepSemantics() {
        #expect(TranscriptionProviderID.resolved(fromStoredValue: nil) == .deepgram)
        #expect(TranscriptionProviderID.resolved(fromStoredValue: "deepgram") == .deepgram)
        #expect(TranscriptionProviderID.resolved(fromStoredValue: "google") == .google)
        #expect(TranscriptionProviderID.resolved(fromStoredValue: "aws") == .aws)
        #expect(TranscriptionProviderID.resolved(fromStoredValue: "garbage") == .deepgram)
        #expect(TranscriptionProviderID.resolved(fromStoredValue: "") == .deepgram)
    }

    /// Healthy chain: cloud leads, native is terminal — the order that makes
    /// a cloud quota outage degrade to Apple transcription, never a dead mic.
    @Test func cloudLeadsAndNativeIsTerminal() {
        let order = LiveCallSTTChain.engineOrder(
            configuredProviderRawValue: nil,
            cloudMarkedUnhealthy: false,
            nativeAvailable: true
        )
        #expect(order == [.cloud(.deepgram), .native])
    }

    /// The configured provider (not a hardcoded one) leads the chain.
    @Test func configuredProviderLeadsTheChain() {
        let order = LiveCallSTTChain.engineOrder(
            configuredProviderRawValue: "google",
            cloudMarkedUnhealthy: false,
            nativeAvailable: true
        )
        #expect(order == [.cloud(.google), .native])
    }

    /// A cloud provider that already failed this surface session is skipped
    /// — the next hands-free turn goes straight to native instead of paying
    /// a doomed network round-trip between every utterance.
    @Test func unhealthyCloudIsSkipped() {
        let order = LiveCallSTTChain.engineOrder(
            configuredProviderRawValue: "deepgram",
            cloudMarkedUnhealthy: true,
            nativeAvailable: true
        )
        #expect(order == [.native])
    }

    /// No native recognizer (the diagnosed simulator case that used to
    /// disable the Talk button outright) still yields a serviceable chain:
    /// cloud alone.
    @Test func missingNativeStillOffersCloud() {
        let order = LiveCallSTTChain.engineOrder(
            configuredProviderRawValue: nil,
            cloudMarkedUnhealthy: false,
            nativeAvailable: false
        )
        #expect(order == [.cloud(.deepgram)])
    }

    /// Both links gone → an EMPTY chain, which the attempt path turns into
    /// an honest `.temporarilyUnavailable` notice — never a silent dead mic
    /// and never a fabricated engine.
    @Test func exhaustedChainIsEmpty() {
        let order = LiveCallSTTChain.engineOrder(
            configuredProviderRawValue: nil,
            cloudMarkedUnhealthy: true,
            nativeAvailable: false
        )
        #expect(order.isEmpty)
    }

    /// Honest "who is listening" labels. The native engine deliberately says
    /// "Apple transcription", NOT "on-device" — `SFSpeechRecognizer` may
    /// route to Apple's servers when the on-device model isn't ready, so the
    /// label is the strongest claim that is always true.
    @Test func engineLabelsAreHonest() {
        #expect(LiveCallSTTChain.engineDescription(for: .cloud(.deepgram)) == "Cloud transcription")
        #expect(LiveCallSTTChain.engineDescription(for: .cloud(.google)) == "Cloud transcription")
        #expect(LiveCallSTTChain.engineDescription(for: .cloud(.aws)) == "Cloud transcription")
        #expect(LiveCallSTTChain.engineDescription(for: .native) == "Apple transcription")
        #expect(!LiveCallSTTChain.engineDescription(for: .native).lowercased().contains("on-device"))
    }
}

/// C5 — dead-mic watchdog decision (`LiveCallMicWatchdog`). The live call's
/// hands-free loop previously could sit in "Listening…" forever while the
/// recognition backend heard nothing. The watchdog flags an armed-but-
/// wordless mic after a patient window so the call ends the loop with an
/// honest line instead of pretending to listen.
struct C5LiveCallMicWatchdogTests {

    /// The core trip: loop active, recording, zero words, past the window.
    @Test func flagsArmedWordlessMicPastWindow() {
        #expect(LiveCallMicWatchdog.shouldFlag(
            loopActive: true,
            isRecording: true,
            hasPartialTranscript: false,
            secondsSinceArmed: LiveCallMicWatchdog.deadMicWindow + 0.5
        ))
    }

    /// Words arrived → never flagged, no matter how long the turn runs. A
    /// long thoughtful utterance is the OPPOSITE of a dead mic.
    @Test func neverFlagsOnceWordsArrived() {
        #expect(!LiveCallMicWatchdog.shouldFlag(
            loopActive: true,
            isRecording: true,
            hasPartialTranscript: true,
            secondsSinceArmed: 120
        ))
    }

    /// Inside the patience window → not flagged. A user gathering their
    /// thoughts for a few seconds before speaking is normal on a coaching
    /// call and must never be interrupted with "I can't hear you".
    @Test func patientWithinWindow() {
        #expect(!LiveCallMicWatchdog.shouldFlag(
            loopActive: true,
            isRecording: true,
            hasPartialTranscript: false,
            secondsSinceArmed: LiveCallMicWatchdog.deadMicWindow - 0.5
        ))
        // And the window itself is a real pause-friendly span, not a hair
        // trigger — pinned so a future tweak can't quietly make the call
        // interrupt people mid-breath.
        #expect(LiveCallMicWatchdog.deadMicWindow >= 5.0)
    }

    /// Not recording / loop not active → never flagged (the mic isn't
    /// claiming to listen, so there is nothing to be honest about).
    @Test func neverFlagsWhenNotListening() {
        #expect(!LiveCallMicWatchdog.shouldFlag(
            loopActive: false,
            isRecording: true,
            hasPartialTranscript: false,
            secondsSinceArmed: 60
        ))
        #expect(!LiveCallMicWatchdog.shouldFlag(
            loopActive: true,
            isRecording: false,
            hasPartialTranscript: false,
            secondsSinceArmed: 60
        ))
    }

    /// The notice names the fix and the typed escape hatch, and never blames
    /// the user — same never-shame register as every other coach surface.
    @Test func noticeIsHonestAndBlameFree() {
        let notice = LiveCallMicWatchdog.notice
        #expect(notice.contains("Type"))
        #expect(notice.lowercased().contains("mic"))
        for banned in ["you failed", "wrong", "your fault", "try harder"] {
            #expect(!notice.lowercased().contains(banned))
        }
    }
}

/// C5 — honest voice-output state (`IMMessageSpeaker.voiceUnavailableNoticeText`).
/// When a requested spoken reply produced no audio through any engine, the
/// chat surfaces show this single line instead of a silent bubble that reads
/// as a muted coach.
struct C5VoiceUnavailableNoticeTests {

    /// The note is factual + quiet: names the state, promises nothing,
    /// blames nobody, and never claims the text itself failed.
    @MainActor
    @Test func noticeCopyIsFactualAndBlameFree() {
        let notice = IMMessageSpeaker.voiceUnavailableNoticeText
        #expect(!notice.isEmpty)
        #expect(notice.lowercased().contains("voice"))
        #expect(notice.lowercased().contains("text"))
        #expect(!notice.contains("!"))
        for banned in ["error", "failed", "broken", "sorry"] {
            #expect(!notice.lowercased().contains(banned), "'\(banned)' reads as system blame, not coach calm")
        }
    }

    /// `stop()` clears the note — every new turn begins with `stop()`, so a
    /// stale "voice unavailable" can never describe a turn that spoke fine.
    @MainActor
    @Test func stopClearsTheNotice() {
        let speaker = IMMessageSpeaker.shared
        speaker.stop()
        #expect(speaker.voiceUnavailableNotice == nil)
    }
}

// MARK: - C6: Big Moment intake restyle (prefill + per-type chip colours)

// The intake sheet preselects the moment TYPE from what the coach already
// knows — the active moment's own category on re-entry, else the stated
// speaking context from onboarding — and NEVER invents a title or a date
// (the resolver returns a category only, by construction). Chip colours
// must stay pairwise distinct so every type reads as its own concept
// (docs/UX_VISUAL_DIRECTION.md — semantic colour, consistently).

@Suite("BigMomentIntakePrefillTests")
struct BigMomentIntakePrefillTests {

    private func profile(context: SpeakingContext) -> CoachingProfile {
        CoachingProfile(
            speakingContext: context,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            desiredOutcome: .persuasive,
            speakingStyleGoal: .concise,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: ""
        )
    }

    @Test func activeMomentCategoryWinsOverProfileHint() {
        // Re-entry from Settings revisits the user's explicit prior choice —
        // it beats any soft onboarding hint, even when they disagree.
        let moment = BigMoment(title: "Team review", category: .review)
        let resolved = BigMomentIntakePrefill.category(
            activeMoment: moment,
            profile: profile(context: .interviews)
        )
        #expect(resolved == .review)
    }

    @Test func statedContextMapsToMatchingType() {
        #expect(BigMomentIntakePrefill.category(activeMoment: nil, profile: profile(context: .interviews)) == .interview)
        #expect(BigMomentIntakePrefill.category(activeMoment: nil, profile: profile(context: .presentations)) == .presentation)
        #expect(BigMomentIntakePrefill.category(activeMoment: nil, profile: profile(context: .work)) == .conversation)
        #expect(BigMomentIntakePrefill.category(activeMoment: nil, profile: profile(context: .social)) == .conversation)
    }

    @Test func noSignalFallsBackToHistoricalDefault() {
        // Nothing known → the pre-restyle default (.presentation), so the
        // sheet behaves identically for a cold profile-less open.
        #expect(BigMomentIntakePrefill.category(activeMoment: nil, profile: nil) == .presentation)
    }

    @Test func everyActiveMomentCategoryRoundTrips() {
        // Whatever type the user saved is exactly what re-entry preselects.
        for category in BigMomentCategory.allCases {
            let moment = BigMoment(title: "x", category: category)
            #expect(BigMomentIntakePrefill.category(activeMoment: moment, profile: nil) == category)
        }
    }

    @Test func chipTintsArePairwiseDistinct() {
        // "Distinct colour per type" — six categories, six colours. A Set
        // collapse would mean two types share a chip colour.
        let tints = Set(BigMomentCategory.allCases.map(\.chipTint))
        #expect(tints.count == BigMomentCategory.allCases.count)
    }
}

// MARK: - Streak first-sight policy (A1 motion register)
//
// The Home streak line's one-shot flame pop is gated by a persisted
// last-seen day count on `StreakFreezeManager`. These tests pin the pure
// policy (`StreakFirstSight.evaluate`) — the honesty rules that keep the
// pop earned: seed silently on first launch (league-promotion-guard
// precedent), animate exactly once per genuine increment, stay silent on
// freeze-spends shown as the same number, and persist drops silently
// (never punish-shame).
struct StreakFirstSightPolicyTests {

    @Test func firstLaunchSeedsSilently() {
        // A fresh install (no stored last-seen) must never pop a day-N
        // streak it never watched grow — the exact lie the league
        // promotion guard exists to prevent.
        let outcome = StreakFirstSight.evaluate(lastSeen: nil, current: 5)
        #expect(!outcome.animate)
        #expect(outcome.persist == 5)
    }

    @Test func genuineIncrementAnimatesAndPersists() {
        let outcome = StreakFirstSight.evaluate(lastSeen: 3, current: 4)
        #expect(outcome.animate)
        #expect(outcome.persist == 4)
    }

    @Test func sameDayCountStaysSilent() {
        // Includes a freeze-spend rendered as the same number — the saved
        // day keeps the count flat, so nothing pops.
        let outcome = StreakFirstSight.evaluate(lastSeen: 4, current: 4)
        #expect(!outcome.animate)
        #expect(outcome.persist == 4)
    }

    @Test func dropPersistsSilently() {
        // Never punish-shame: a reset updates the snapshot with zero
        // ceremony so the NEXT genuine increment compares honestly.
        let outcome = StreakFirstSight.evaluate(lastSeen: 6, current: 2)
        #expect(!outcome.animate)
        #expect(outcome.persist == 2)
    }

    @Test func resetToZeroPersistsSilently() {
        let outcome = StreakFirstSight.evaluate(lastSeen: 3, current: 0)
        #expect(!outcome.animate)
        #expect(outcome.persist == 0)
    }

    @Test func multiDayJumpAnimatesOnce() {
        // A multi-day jump (e.g. a freeze-saved chain catching up) still
        // earns a single pop — evaluate is called once per sighting, and
        // the persisted value catches all the way up so it can't re-fire.
        let outcome = StreakFirstSight.evaluate(lastSeen: 2, current: 5)
        #expect(outcome.animate)
        #expect(outcome.persist == 5)
    }
}

// MARK: - Coaching onboarding custom challenge

struct CoachingOnboardingCustomChallengeTests {

    @Test func customChallengeTextPersistsAndDrivesDisplay() throws {
        let profile = profile(
            biggestChallenge: .rushing,
            customChallengeText: "I sound defensive when challenged"
        )

        #expect(profile.challengeDisplayTitle == "I sound defensive when challenged")
        #expect(profile.challengeContextLine.contains("I sound defensive when challenged"))
        #expect(profile.challengeContextLine.contains("nearest starting bucket"))

        let data = try JSONEncoder().encode(profile)
        let decoded = try JSONDecoder().decode(CoachingProfile.self, from: data)

        #expect(decoded.customChallengeText == "I sound defensive when challenged")
        #expect(decoded.challengeDisplayTitle == "I sound defensive when challenged")
        #expect(decoded.biggestChallenge == .rushing)
    }

    @Test func blankCustomChallengeFallsBackToCanonicalChallenge() {
        let profile = profile(
            biggestChallenge: .freezing,
            customChallengeText: "   "
        )

        #expect(profile.customChallengeText == nil)
        #expect(profile.challengeDisplayTitle == SpeakingChallenge.freezing.title)
        #expect(profile.challengeContextLine == SpeakingChallenge.freezing.title)
    }

    @Test func customChallengeRoutingKeepsExistingBucketsStable() {
        #expect(SpeakingChallenge.routingFallback(forCustomText: "I use fillers and say um too much") == .fillerWords)
        #expect(SpeakingChallenge.routingFallback(forCustomText: "I panic and blank on the spot") == .freezing)
        #expect(SpeakingChallenge.routingFallback(forCustomText: "I sound defensive when challenged") == .rushing)
        #expect(SpeakingChallenge.routingFallback(forCustomText: "I over-explain and lose the point") == .rambling)
        #expect(SpeakingChallenge.routingFallback(forCustomText: "My problem is hard to describe") == .rambling)
    }

    private func profile(
        biggestChallenge: SpeakingChallenge,
        customChallengeText: String?
    ) -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: biggestChallenge.recommendedPriority,
            confidenceLevel: .rebuilding,
            biggestChallenge: biggestChallenge,
            customChallengeText: customChallengeText,
            desiredOutcome: .composed,
            speakingStyleGoal: .executive,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: "",
            chosenStyleGoal: .executive
        )
    }
}

// MARK: - Scenario roleplay pressure ladder

struct RoleplayEngineTests {

    // MARK: Catalog integrity

    @Test func catalogCoversPressureAndInterpersonalScenarios() {
        let ids = Set(RoleplayCatalog.all.map { $0.scenarioId })
        #expect(ids == [
            "interview",
            "leadershipUpdate",
            "stakeholderPushback",
            "difficultQA",
            "feedbackConversation",
            "boundaryConversation",
            "repairTrust",
            "discoveryConversation"
        ])
    }

    @Test func everyObjectionIdIsGloballyUnique() {
        let allIDs = RoleplayCatalog.all.flatMap { $0.objectionSet.map { $0.id } }
        #expect(allIDs.count == Set(allIDs).count)
    }

    @Test func everyScenarioHasObjectionsAtEveryPressureLevel() {
        for scenario in RoleplayCatalog.all {
            for level in RoleplayPressureLevel.allCases {
                #expect(!scenario.objections(at: level).isEmpty, "\(scenario.scenarioId) missing objections at \(level)")
            }
        }
    }

    @Test func objectionsVaryByPressureLevelWithinAScenario() {
        for scenario in RoleplayCatalog.all {
            let easyTexts = Set(scenario.objections(at: .easy).map { $0.text })
            let realisticTexts = Set(scenario.objections(at: .realistic).map { $0.text })
            let hostileTexts = Set(scenario.objections(at: .hostile).map { $0.text })
            #expect(easyTexts.isDisjoint(with: realisticTexts))
            #expect(realisticTexts.isDisjoint(with: hostileTexts))
            #expect(easyTexts.isDisjoint(with: hostileTexts))
        }
    }

    @Test func rubricWeightsSumToApproximatelyOne() {
        for scenario in RoleplayCatalog.all {
            let total = scenario.rubric.reduce(0) { $0 + $1.weight }
            #expect(abs(total - 1.0) < 0.001, "\(scenario.scenarioId) rubric weights sum to \(total)")
        }
    }

    @Test func brandVoiceHasNoExclamationsOrFanfare() {
        let banned = ["!", "amazing", "crushed", "nailed", "let's go", "hurry"]
        for scenario in RoleplayCatalog.all {
            for objection in scenario.objectionSet {
                for phrase in banned {
                    #expect(!objection.text.lowercased().contains(phrase), "\(objection.id) contains banned phrase '\(phrase)'")
                }
            }
            for criterion in scenario.rubric {
                for phrase in banned {
                    #expect(!criterion.lowSignalHint.lowercased().contains(phrase))
                    #expect(!criterion.strongSignalHint.lowercased().contains(phrase))
                }
            }
        }
    }

    // MARK: Objection selection (no-repeat contract)

    @Test func nextObjectionAvoidsUsedIdsWhenFreshOnesRemain() {
        let scenario = RoleplayCatalog.interview
        let used = Set(scenario.objections(at: .easy).prefix(2).map { $0.id })
        let picked = RoleplayEngine.nextObjection(for: scenario, pressureLevel: .easy, excluding: used)
        #expect(picked != nil)
        #expect(!used.contains(picked!.id))
    }

    @Test func nextObjectionFallsBackToReuseOncePoolExhausted() {
        let scenario = RoleplayCatalog.interview
        let allEasyIDs = Set(scenario.objections(at: .easy).map { $0.id })
        let picked = RoleplayEngine.nextObjection(for: scenario, pressureLevel: .easy, excluding: allEasyIDs)
        #expect(picked != nil)
        #expect(allEasyIDs.contains(picked!.id))
    }

    @Test func nextObjectionNeverCrossesScenarios() {
        // The exclusion set is drawn from ANOTHER scenario's objections —
        // since IDs are scenario-prefixed and never collide, this proves
        // the same drill can't be "used up" by an unrelated roleplay.
        let interviewUsed = Set(RoleplayCatalog.interview.objectionSet.map { $0.id })
        let picked = RoleplayEngine.nextObjection(for: RoleplayCatalog.leadershipUpdate, pressureLevel: .easy, excluding: interviewUsed)
        #expect(picked != nil)
    }

    // MARK: Response scoring

    @Test func directEvidencedResponseScoresHigherThanRamblingFillerResponse() {
        let rubric = RoleplayCatalog.interview.rubric
        let strong = "We shipped it two weeks late because the vendor missed a component deadline, specifically the sensor batch."
        let weak = "Um, I guess, like, maybe it was kind of, sort of, actually late, I think, not sure why."
        #expect(RoleplayEngine.score(response: strong, rubric: rubric) > RoleplayEngine.score(response: weak, rubric: rubric))
    }

    @Test func emptyResponseScoresAtTheFloor() {
        let rubric = RoleplayCatalog.interview.rubric
        #expect(RoleplayEngine.score(response: "", rubric: rubric) == 0)
    }

    @Test func scoreStaysWithinUnitRange() {
        let rubric = RoleplayCatalog.interview.rubric
        let responses = [
            "",
            "yes",
            "We hit the number because the data specifically showed a 20% lift last quarter, for example in the west region.",
            String(repeating: "um like actually basically ", count: 20)
        ]
        for response in responses {
            let score = RoleplayEngine.score(response: response, rubric: rubric)
            #expect(score >= 0 && score <= 1)
        }
    }

    // MARK: Feedback

    @Test func feedbackReturnsOneStrengthAndOneGap() {
        let rubric = RoleplayCatalog.interview.rubric
        let (strength, gap) = RoleplayEngine.feedback(response: "We hit the number because the data showed a 20% lift.", rubric: rubric)
        #expect(!strength.isEmpty)
        #expect(!gap.isEmpty)
    }

    @Test func emptyResponseFeedbackIsGentleNotShaming() {
        let rubric = RoleplayCatalog.interview.rubric
        let (strength, gap) = RoleplayEngine.feedback(response: "   ", rubric: rubric)
        #expect(!strength.isEmpty)
        #expect(!gap.isEmpty)
        let shameWords = ["fail", "wrong", "bad", "terrible"]
        for word in shameWords {
            #expect(!gap.lowercased().contains(word))
            #expect(!strength.lowercased().contains(word))
        }
    }

    // MARK: Retry mode / pressure ladder movement

    @Test func strongResponseAtNonTopLevelRecommendsLevelUp() {
        let mode = RoleplayEngine.retryMode(afterQuality: 0.9, currentLevel: .easy)
        #expect(mode == .levelUp)
        #expect(RoleplayEngine.nextLevel(after: mode, currentLevel: .easy) == .realistic)
    }

    @Test func strongResponseAtHostileStaysAtHostile() {
        let mode = RoleplayEngine.retryMode(afterQuality: 0.9, currentLevel: .hostile)
        #expect(mode == .sameLevelNewObjection)
        #expect(RoleplayEngine.nextLevel(after: mode, currentLevel: .hostile) == .hostile)
    }

    @Test func weakResponseAtEasyRepeatsRatherThanDroppingFurther() {
        let mode = RoleplayEngine.retryMode(afterQuality: 0.1, currentLevel: .easy)
        #expect(mode == .sameObjectionSlower)
        #expect(RoleplayEngine.nextLevel(after: mode, currentLevel: .easy) == .easy)
    }

    @Test func weakResponseAboveEasyStepsDown() {
        let mode = RoleplayEngine.retryMode(afterQuality: 0.1, currentLevel: .realistic)
        #expect(mode == .levelDown)
        #expect(RoleplayEngine.nextLevel(after: mode, currentLevel: .realistic) == .easy)
    }

    @Test func midQualityResponseStaysAtLevelWithFreshObjection() {
        let mode = RoleplayEngine.retryMode(afterQuality: 0.6, currentLevel: .realistic)
        #expect(mode == .sameLevelNewObjection)
        #expect(RoleplayEngine.nextLevel(after: mode, currentLevel: .realistic) == .realistic)
    }

    // MARK: Turn composition — the data contract

    @Test func evaluateTurnProducesTheRequiredDataContractFields() {
        let scenario = RoleplayCatalog.stakeholderPushback
        let objection = scenario.objections(at: .realistic)[0]
        let result = RoleplayEngine.evaluateTurn(scenario: scenario, objection: objection, response: "Because the last rollout held at 98% uptime for six months.")
        #expect(result.scenarioId == scenario.scenarioId)
        #expect(result.pressureLevel == .realistic)
        #expect(result.objectionType == objection.type)
        #expect(result.objectionId == objection.id)
        #expect(result.responseQuality >= 0 && result.responseQuality <= 1)
    }

    // MARK: Pressure ladder ordering

    @Test func pressureLevelOrderingIsEasyBeforeRealisticBeforeHostile() {
        #expect(RoleplayPressureLevel.easy < RoleplayPressureLevel.realistic)
        #expect(RoleplayPressureLevel.realistic < RoleplayPressureLevel.hostile)
        #expect(RoleplayPressureLevel.hostile.next == nil)
        #expect(RoleplayPressureLevel.easy.previous == nil)
    }
}

// MARK: - Transparent memory & trajectory (TrajectorySummaryBuilder)

@Suite("TrajectorySummaryBuilderTests")
struct TrajectorySummaryBuilderTests {

    // MARK: Honest empty state

    @Test func honestEmptyStateWithNoProfileAndNoSessions() {
        let snapshot = TrajectorySummaryBuilder.build(
            profile: nil,
            baseline: .empty,
            sessions: [],
            coachMemory: nil,
            now: Date(timeIntervalSince1970: 1_000_000)
        )

        #expect(snapshot.activeGoals.isEmpty)
        #expect(snapshot.recentReps.isEmpty)
        #expect(snapshot.trendSignals.isEmpty)
        #expect(snapshot.evidenceFreshnessDays == nil)
        #expect(snapshot.confidence == .insufficient)
        #expect(snapshot.isStale == false)
        #expect(snapshot.userVisibility == TrajectorySummaryBuilder.notEnoughYetLine)
        // The honest state must never claim a goal or reps it doesn't have.
        #expect(!snapshot.userVisibility.contains("Using:"))
    }

    @Test func emptyStateWithProfileButNoRepsNamesTheGoalOnly() {
        let snapshot = TrajectorySummaryBuilder.build(
            profile: testProfile(),
            baseline: .empty,
            sessions: [],
            coachMemory: nil,
            now: Date(timeIntervalSince1970: 1_000_000)
        )

        #expect(!snapshot.activeGoals.isEmpty)
        #expect(snapshot.recentReps.isEmpty)
        #expect(snapshot.trendSignals.isEmpty)
        // No rep history at all — freshness must stay nil, never fabricated.
        #expect(snapshot.evidenceFreshnessDays == nil)
        #expect(snapshot.userVisibility.hasPrefix("Based on"))
        #expect(snapshot.userVisibility.contains("goal"))
        #expect(!snapshot.userVisibility.contains("reps"))
    }

    // MARK: Freshness bounding

    @Test func freshnessBoundingFlagsStaleEvidence() {
        let now = Date(timeIntervalSince1970: 2_000_000)
        let staleDays = TrajectorySummaryBuilder.stalenessThresholdDays + 5
        let staleDate = Calendar(identifier: .gregorian).date(byAdding: .day, value: -staleDays, to: now)!

        let snapshot = TrajectorySummaryBuilder.build(
            profile: testProfile(),
            baseline: .empty,
            sessions: [testSession(date: staleDate, fillerWordCount: 4, score: 5)],
            coachMemory: nil,
            now: now
        )

        #expect(snapshot.evidenceFreshnessDays == staleDays)
        #expect(snapshot.isStale == true)
        #expect(snapshot.userVisibility.contains("out of date"))
        #expect(snapshot.userVisibility.contains("\(staleDays) days ago"))
    }

    @Test func freshnessBoundingLeavesRecentEvidenceUnflagged() {
        let now = Date(timeIntervalSince1970: 2_000_000)
        let recentDays = TrajectorySummaryBuilder.stalenessThresholdDays - 3
        let recentDate = Calendar(identifier: .gregorian).date(byAdding: .day, value: -recentDays, to: now)!

        let snapshot = TrajectorySummaryBuilder.build(
            profile: testProfile(),
            baseline: .empty,
            sessions: [testSession(date: recentDate, fillerWordCount: 2, score: 7)],
            coachMemory: nil,
            now: now
        )

        #expect(snapshot.evidenceFreshnessDays == recentDays)
        #expect(snapshot.isStale == false)
        #expect(!snapshot.userVisibility.contains("out of date"))
    }

    @Test func stalenessBoundaryIsExclusive() {
        let now = Date(timeIntervalSince1970: 2_000_000)
        let boundaryDate = Calendar(identifier: .gregorian).date(
            byAdding: .day,
            value: -TrajectorySummaryBuilder.stalenessThresholdDays,
            to: now
        )!

        let snapshot = TrajectorySummaryBuilder.build(
            profile: testProfile(),
            baseline: .empty,
            sessions: [testSession(date: boundaryDate, fillerWordCount: 2, score: 7)],
            coachMemory: nil,
            now: now
        )

        // Exactly at the threshold is still fresh — only strictly-older reps
        // flip the flag, mirroring the codebase's other freshness gates.
        #expect(snapshot.isStale == false)
    }

    // MARK: No overclaim (weekly trend evidence floor)

    @Test func thinEvidenceProducesNoTrendSignalsEvenAcrossTwoWeeks() {
        var calendar = Calendar(identifier: .iso8601)
        calendar.timeZone = TimeZone(identifier: "UTC")!
        let now = calendar.date(from: DateComponents(weekday: 4, weekOfYear: 10, yearForWeekOfYear: 2026))!
        let lastWeek = calendar.date(byAdding: .weekOfYear, value: -1, to: now)!

        // Only 2 total reps — below `minimumSessionsForTrend` — even though
        // they land in two different calendar weeks. The builder must refuse
        // to compute a delta from that little evidence.
        let snapshot = TrajectorySummaryBuilder.build(
            profile: testProfile(),
            baseline: .empty,
            sessions: [
                testSession(date: now, fillerWordCount: 1, score: 8),
                testSession(date: lastWeek, fillerWordCount: 5, score: 4)
            ],
            coachMemory: nil,
            now: now
        )

        #expect(snapshot.trendSignals.isEmpty)
    }

    @Test func sufficientEvidenceAcrossTwoWeeksProducesAnHonestBoundedSignal() {
        var calendar = Calendar(identifier: .iso8601)
        calendar.timeZone = TimeZone(identifier: "UTC")!
        let now = calendar.date(from: DateComponents(weekday: 4, weekOfYear: 10, yearForWeekOfYear: 2026))!
        let yesterday = calendar.date(byAdding: .day, value: -1, to: now)!
        let lastWeekAnchor = calendar.date(byAdding: .weekOfYear, value: -1, to: now)!
        let lastWeekEarlier = calendar.date(byAdding: .day, value: -1, to: lastWeekAnchor)!

        let snapshot = TrajectorySummaryBuilder.build(
            profile: testProfile(),
            baseline: .empty,
            sessions: [
                testSession(date: now, fillerWordCount: 1, score: 8),
                testSession(date: yesterday, fillerWordCount: 2, score: 7),
                testSession(date: lastWeekAnchor, fillerWordCount: 6, score: 4),
                testSession(date: lastWeekEarlier, fillerWordCount: 8, score: 3)
            ],
            coachMemory: nil,
            now: now
        )

        let fillerSignal = snapshot.trendSignals.first { $0.metricLabel == "Filler words" }
        #expect(fillerSignal != nil)
        #expect(fillerSignal?.direction == .improving)
        #expect(fillerSignal?.exampleEvidenceLine != nil)

        let scoreSignal = snapshot.trendSignals.first { $0.metricLabel == "Score" }
        #expect(scoreSignal != nil)
        #expect(scoreSignal?.direction == .improving)

        // Every signal must cite a concrete example rep — never an
        // unsubstantiated claim.
        #expect(snapshot.trendSignals.allSatisfy { $0.exampleEvidenceLine != nil })
    }

    @Test func recentRepsAreBoundedToThreeEvenWithLongerHistory() {
        let now = Date(timeIntervalSince1970: 3_000_000)
        let calendar = Calendar(identifier: .gregorian)
        let sessions = (0..<10).map { offset in
            testSession(
                date: calendar.date(byAdding: .day, value: -offset, to: now)!,
                fillerWordCount: offset,
                score: 5
            )
        }

        let snapshot = TrajectorySummaryBuilder.build(
            profile: testProfile(),
            baseline: .empty,
            sessions: sessions,
            coachMemory: nil,
            now: now
        )

        #expect(snapshot.recentReps.count == 3)
    }

    // MARK: - Fixtures

    private func testProfile() -> CoachingProfile {
        CoachingProfile(
            speakingContext: .work,
            primaryGoal: .reduceFillers,
            confidenceLevel: .rebuilding,
            biggestChallenge: .fillerWords,
            customChallengeText: nil,
            desiredOutcome: .composed,
            speakingStyleGoal: .executive,
            styleReference: "",
            coachingBrief: "",
            motivationWhyNow: "",
            successVision: "",
            chosenStyleGoal: .executive
        )
    }

    private func testSession(date: Date, fillerWordCount: Int, score: Int) -> PracticeSession {
        PracticeSession(
            transcript: "test transcript",
            fillerWordCount: fillerWordCount,
            duration: 45,
            date: date,
            mode: .timed,
            score: score,
            isRated: true
        )
    }
}

// MARK: - Prompt caching (Anthropic/Gemini system-field split)
//
// Proves the DYNAMIC per-turn data (userContext / latest user words) never
// lands inside the block Anthropic marks `cache_control: ephemeral` — that
// block must be byte-identical across requests within the cache TTL, so any
// per-turn leakage silently kills the cache hit. Also proves the stable
// block stays byte-stable across two calls that differ only in the dynamic
// context, which is the literal precondition for a cache hit.

@Suite("AnthropicSystemBlocksCacheSplitTests")
struct AnthropicSystemBlocksCacheSplitTests {
    private let stableSystemPrompt = "You are Noum's senior communications coach. Voice: direct, warm, no fluff."
    private let dynamicUserContext = "GOAL: land the promotion pitch. RECENT REP: 2026-07-08, 4 fillers, score 71. LATEST USER TURN: \"did that pitch actually land or was I just hoping?\""

    @Test func stableBlockCarriesTheSystemPromptVerbatim() {
        let blocks = AICoachChatService.anthropicSystemBlocks(
            systemPrompt: stableSystemPrompt,
            userContext: dynamicUserContext
        )
        #expect(blocks.count == 2)
        #expect(blocks[0]["text"] as? String == stableSystemPrompt)
        #expect(blocks[0]["type"] as? String == "text")
    }

    @Test func stableBlockCarriesTheCacheControlBreakpoint() {
        let blocks = AICoachChatService.anthropicSystemBlocks(
            systemPrompt: stableSystemPrompt,
            userContext: dynamicUserContext
        )
        let cacheControl = blocks[0]["cache_control"] as? [String: String]
        #expect(cacheControl?["type"] == "ephemeral")
    }

    @Test func stableBlockDoesNotContainTheDynamicUserContext() {
        let blocks = AICoachChatService.anthropicSystemBlocks(
            systemPrompt: stableSystemPrompt,
            userContext: dynamicUserContext
        )
        let stableText = blocks[0]["text"] as? String ?? ""
        #expect(!stableText.contains("did that pitch actually land"))
        #expect(!stableText.contains("4 fillers"))
        #expect(!stableText.contains(dynamicUserContext))
    }

    @Test func dynamicBlockCarriesTheUserContextAndHasNoCacheControl() {
        let blocks = AICoachChatService.anthropicSystemBlocks(
            systemPrompt: stableSystemPrompt,
            userContext: dynamicUserContext
        )
        #expect(blocks[1]["text"] as? String == dynamicUserContext)
        #expect(blocks[1]["type"] as? String == "text")
        #expect(blocks[1]["cache_control"] == nil)
    }

    @Test func stableBlockIsByteStableAcrossTwoRequestsWithDifferentDynamicContext() {
        let firstTurn = AICoachChatService.anthropicSystemBlocks(
            systemPrompt: stableSystemPrompt,
            userContext: "GOAL: land the promotion pitch. LATEST USER TURN: \"how did I do?\""
        )
        let secondTurn = AICoachChatService.anthropicSystemBlocks(
            systemPrompt: stableSystemPrompt,
            userContext: "GOAL: land the promotion pitch. LATEST USER TURN: \"what should I fix next?\""
        )
        // The precondition for a cache hit: identical stable block...
        #expect((firstTurn[0]["text"] as? String) == (secondTurn[0]["text"] as? String))
        #expect((firstTurn[0]["cache_control"] as? [String: String]) == (secondTurn[0]["cache_control"] as? [String: String]))
        // ...while the dynamic block is free to differ.
        #expect((firstTurn[1]["text"] as? String) != (secondTurn[1]["text"] as? String))
    }

    @Test func totalTextContentIsUnchangedFromASingleComposedString() {
        let composed = stableSystemPrompt + "\n\n" + dynamicUserContext
        let blocks = AICoachChatService.anthropicSystemBlocks(
            systemPrompt: stableSystemPrompt,
            userContext: dynamicUserContext
        )
        let reassembled = (blocks[0]["text"] as? String ?? "") + "\n\n" + (blocks[1]["text"] as? String ?? "")
        #expect(reassembled == composed)
    }
}

@Suite("GeminiSystemPartsPrefixOrderingTests")
struct GeminiSystemPartsPrefixOrderingTests {
    private let stableSystemPrompt = "You are Noum's senior communications coach."
    private let dynamicUserContext = "RECENT REP: score 71. LATEST USER TURN: \"was that any good?\""

    @Test func stablePartComesFirstAndDynamicPartComesLast() {
        let parts = AICoachChatService.geminiSystemParts(
            systemPrompt: stableSystemPrompt,
            userContext: dynamicUserContext
        )
        #expect(parts.count == 2)
        #expect(parts[0]["text"] as? String == stableSystemPrompt)
        #expect(parts[1]["text"] as? String == dynamicUserContext)
    }

    @Test func stablePartDoesNotContainDynamicUserContext() {
        let parts = AICoachChatService.geminiSystemParts(
            systemPrompt: stableSystemPrompt,
            userContext: dynamicUserContext
        )
        let stableText = parts[0]["text"] as? String ?? ""
        #expect(!stableText.contains("was that any good"))
    }

    @Test func stablePartIsByteStableAcrossDifferentDynamicContext() {
        let a = AICoachChatService.geminiSystemParts(systemPrompt: stableSystemPrompt, userContext: "turn one")
        let b = AICoachChatService.geminiSystemParts(systemPrompt: stableSystemPrompt, userContext: "turn two")
        #expect((a[0]["text"] as? String) == (b[0]["text"] as? String))
        #expect((a[1]["text"] as? String) != (b[1]["text"] as? String))
    }
}

// MARK: - Prompt-cache usage extraction (Anthropic + Gemini)

@Suite("CoachChatCacheUsageExtractionTests")
struct CoachChatCacheUsageExtractionTests {
    private func data(_ object: [String: Any]) -> Data {
        try! JSONSerialization.data(withJSONObject: object)
    }

    @Test func anthropicUsageParsesAllFourFields() {
        let object: [String: Any] = [
            "content": [["type": "text", "text": "Fair push."]],
            "stop_reason": "end_turn",
            "usage": [
                "input_tokens": 1300,
                "output_tokens": 42,
                "cache_creation_input_tokens": 0,
                "cache_read_input_tokens": 1180
            ]
        ]
        let usage = AICoachChatService.extractAnthropicUsage(from: data(object))
        #expect(usage?.inputTokens == 1300)
        #expect(usage?.outputTokens == 42)
        #expect(usage?.cacheCreationInputTokens == 0)
        #expect(usage?.cacheReadInputTokens == 1180)
        #expect(usage?.cacheHit == true)
    }

    @Test func anthropicUsageMissingUsageObjectReturnsNil() {
        let object: [String: Any] = ["content": [["type": "text", "text": "hi"]]]
        #expect(AICoachChatService.extractAnthropicUsage(from: data(object)) == nil)
    }

    @Test func anthropicUsageOnFreshCacheCreationReportsNoReadYet() {
        let object: [String: Any] = [
            "usage": [
                "input_tokens": 1300,
                "output_tokens": 42,
                "cache_creation_input_tokens": 1180,
                "cache_read_input_tokens": 0
            ]
        ]
        let usage = AICoachChatService.extractAnthropicUsage(from: data(object))
        #expect(usage?.cacheCreationInputTokens == 1180)
        #expect(usage?.cacheReadInputTokens == 0)
        #expect(usage?.cacheHit == false)
    }

    @Test func geminiUsageParsesCachedContentTokenCountWhenPresent() {
        let object: [String: Any] = [
            "candidates": [["content": ["parts": [["text": "hi"]]]]],
            "usageMetadata": [
                "promptTokenCount": 900,
                "candidatesTokenCount": 30,
                "cachedContentTokenCount": 700
            ]
        ]
        let usage = AICoachChatService.extractGeminiUsage(from: data(object))
        #expect(usage?.inputTokens == 900)
        #expect(usage?.outputTokens == 30)
        #expect(usage?.cachedContentTokenCount == 700)
        #expect(usage?.cacheHit == true)
    }

    @Test func geminiUsageGuardsAbsentCachedContentTokenCount() {
        // Absent (not zero) on a cache miss — must not fabricate a 0.
        let object: [String: Any] = [
            "usageMetadata": [
                "promptTokenCount": 900,
                "candidatesTokenCount": 30
            ]
        ]
        let usage = AICoachChatService.extractGeminiUsage(from: data(object))
        #expect(usage?.cachedContentTokenCount == nil)
        #expect(usage?.cacheHit == false)
    }

    @Test func geminiUsageMissingUsageMetadataReturnsNil() {
        let object: [String: Any] = ["candidates": [["content": ["parts": [["text": "hi"]]]]]]
        #expect(AICoachChatService.extractGeminiUsage(from: data(object)) == nil)
    }

    @Test func chatExtractUsageDispatchesAnthropicVersusGemini() {
        let anthropicObject: [String: Any] = [
            "usage": ["input_tokens": 500, "output_tokens": 10, "cache_read_input_tokens": 400]
        ]
        let geminiObject: [String: Any] = [
            "usageMetadata": ["promptTokenCount": 500, "candidatesTokenCount": 10, "cachedContentTokenCount": 400]
        ]
        #expect(AICoachChatService.chatExtractUsage(from: data(anthropicObject), provider: .anthropic)?.cacheReadInputTokens == 400)
        #expect(AICoachChatService.chatExtractUsage(from: data(geminiObject), provider: .gemini)?.cachedContentTokenCount == 400)
    }
}
